    public function stripHtmlBoilerplate($html)
    {
        if (empty($html)) {
            return '';
        }
        $html = preg_replace('/<!DOCTYPE[^>]*>/i', '', $html);
        $html = preg_replace('/<html[^>]*>/i', '', $html);
        $html = preg_replace('/<\/html>/i', '', $html);
        $html = preg_replace('/<head[^>]*>.*?<\/head>/is', '', $html);
        $html = preg_replace('/<body[^>]*>/i', '', $html);
        $html = preg_replace('/<\/body>/i', '', $html);
        $html = preg_replace('/<form[^>]*>/i', '', $html);
        $html = preg_replace('/<\/form>/i', '', $html);
        $html = preg_replace('/document\.addEventListener\(\s*[\'"]DOMContentLoaded[\'"]\s*,\s*function\s*\(\s*\)\s*\{/i', 'setTimeout(function() {', $html);
        $html = preg_replace('/\$\(document\)\.ready\(\s*function\s*\(\s*\)\s*\{/i', 'setTimeout(function() {', $html);
        return $html;
    }

    public static function renderSubform($viewName, $calibration, $additionalData = [])
    {
        $type = str_replace(['formhtml.', '_view', '_edit'], '', $viewName);
        
        // Clone the model so we don't affect the main instance
        $subCalibration = clone $calibration;
        
        $identities = json_decode($calibration->subform_identities, true) ?? [];
        $subId = $identities[$type] ?? [];
        
        // Gunakan nilai dari subId. Jika tidak ada, biarkan null/kosong. (Tidak mengambil dari main form)
        $subCalibration->namaAlat = $subId['nama_alat'] ?? ($subId['namaAlat'] ?? null);
        $subCalibration->brandAlat = $subId['merek'] ?? null;
        $subCalibration->NoSeri = $subId['no_seri'] ?? null;
        $subCalibration->kodeAlat = $subId['kode_alat'] ?? null;
        $subCalibration->typeAlat = $subId['type_alat'] ?? null;
        $subCalibration->kapasitas = $subId['kapasitas'] ?? null;
        $subCalibration->resolusi = $subId['resolusi'] ?? null;
        $subCalibration->rangeMin = $subId['rentang_ukur_min'] ?? ($subId['rangeMin'] ?? null);
        $subCalibration->rangeMax = $subId['rentang_ukur_max'] ?? ($subId['rangeMax'] ?? null);
        $subCalibration->pemilikAlat = $subId['nama_pemilik'] ?? ($subId['pemilik_alat'] ?? null);
        $subCalibration->tanggalMasuk = $subId['tanggal_alat_masuk'] ?? ($subId['tanggal_masuk'] ?? null);
        $subCalibration->tanggalKalibrasi = $subId['tanggal_kalibrasi'] ?? null;
        $subCalibration->tempatKalibrasi = $subId['tempat_kalibrasi'] ?? null;
        $subCalibration->kondisiAlat = $subId['fungsi_komponen'] ?? ($subId['kondisi_alat'] ?? null);
        $subCalibration->keterangan = $subId['keterangan_fungsi_komponen'] ?? ($subId['keterangan'] ?? null);
        $subCalibration->RT_condition1 = $subId['suhu_awal'] ?? null;
        $subCalibration->RT_condition2 = $subId['suhu_tengah'] ?? null;
        $subCalibration->RT_condition3 = $subId['suhu_akhir'] ?? null;
        $subCalibration->RH_condition1 = $subId['rh_awal'] ?? null;
        $subCalibration->RH_condition2 = $subId['rh_tengah'] ?? null;
        $subCalibration->RH_condition3 = $subId['rh_akhir'] ?? null;
        $subCalibration->calibratedBy = $subId['calibrated_by'] ?? null;
        $subCalibration->verifiedBy = $subId['verified_by'] ?? null;
        $subCalibration->jenisPembacaan = $subId['jenis_pembacaan'] ?? null;
        $subCalibration->lokasiPT = $subId['lokasi_pt'] ?? null;
        $subCalibration->kode_th = $subId['kode_th'] ?? null;

        $data = array_merge(['calibration' => $subCalibration, 'is_subform' => true], $additionalData);
        try {
            $html = view($viewName, $data)->render();
            $controller = new self();
            return $controller->stripHtmlBoilerplate($html);
        } catch (\Exception $e) {
            \Log::error("Error rendering subform view {$viewName}: " . $e->getMessage());
            return "<!-- Error rendering subform {$viewName}: {$e->getMessage()} -->";
        }
    }
    
   public static function getSavedSubforms($calibrationId, $mainFormType)
    {
        $subforms = [];
        $calibration = Calibration::find($calibrationId);

        // If calibration record exists, check its additional_forms column first
        if ($calibration) {
            $rawAdditional = $calibration->additional_forms;
            if (is_string($rawAdditional)) {
                $rawAdditional = json_decode($rawAdditional, true);
            }

            // If additional_forms is explicitly null or an empty array, no subforms were attached to this calibration
            if ($rawAdditional === null || (is_array($rawAdditional) && empty($rawAdditional))) {
                return [];
            }

            // If additional_forms has subforms listed, only check those listed subforms
            if (is_array($rawAdditional) && !empty($rawAdditional)) {
                foreach ($rawAdditional as $type) {
                    if ($type === $mainFormType || !isset(self::$formRegistry[$type])) {
                        continue;
                    }
                    $config = self::$formRegistry[$type];
                    $modelClass = $config['head_model'] ?? null;
                    $associatedModels = $config['associated_models'] ?? [];
                    $detailClass = isset($associatedModels[1]) ? $associatedModels[1] : null;

                    if ($modelClass && class_exists($modelClass)) {
                        $subformCode = self::getSubformCode($type);
                        $subCalibrationId = $calibrationId . '-' . $subformCode;

                        $hasHead = $modelClass::where('calibration_id', $calibrationId)
                                              ->orWhere('calibration_id', $subCalibrationId)
                                              ->exists();
                        if ($hasHead) {
                            $hasDetail = true;
                            if ($detailClass && class_exists($detailClass)) {
                                try {
                                    $detailTable = (new $detailClass)->getTable();
                                    if (\Illuminate\Support\Facades\Schema::hasColumn($detailTable, 'calibration_id')) {
                                        $hasDetail = $detailClass::where('calibration_id', $calibrationId)
                                                                 ->orWhere('calibration_id', $subCalibrationId)
                                                                 ->exists();
                                    }
                                } catch (\Exception $e) {}
                            }
                            if ($hasDetail) {
                                $subforms[] = $type;
                            }
                        }
                    }
                }
                return array_unique($subforms);
            }
        }

        // Fallback for legacy records
        foreach (self::$formRegistry as $type => $config) {
            if ($type === $mainFormType) {
                continue;
            }
            $modelClass = $config['head_model'] ?? null;
            $associatedModels = $config['associated_models'] ?? [];
            $detailClass = isset($associatedModels[1]) ? $associatedModels[1] : null;

            if ($modelClass && class_exists($modelClass)) {
                try {
                    $subformCode = self::getSubformCode($type);
                    $subCalibrationId = $calibrationId . '-' . $subformCode;

                    $hasHead = $modelClass::where('calibration_id', $calibrationId)
                                          ->orWhere('calibration_id', $subCalibrationId)
                                          ->exists();
                    if ($hasHead) {
                        $hasDetail = true;
                        if ($detailClass && class_exists($detailClass)) {
                            try {
                                $detailTable = (new $detailClass)->getTable();
                                if (\Illuminate\Support\Facades\Schema::hasColumn($detailTable, 'calibration_id')) {
                                    $hasDetail = $detailClass::where('calibration_id', $calibrationId)
                                                             ->orWhere('calibration_id', $subCalibrationId)
                                                             ->exists();
                                }
                            } catch (\Exception $e) {}
                        }

                        if ($hasDetail) {
                            $subforms[] = $type;
                        } else {
                            self::deleteSubformData($calibrationId, $type);
                            \Log::info("🧹 Cleaned up ghost subform: {$type} for calibration ID: {$calibrationId}");
                        }
                    }
                } catch (\Exception $e) {
                    \Log::error("Error checking subform existence for {$type}: " . $e->getMessage());
                }
            }
        }
        return $subforms;
    }

    public static function deleteSubformData($calibrationId, $formType)
    {
        $registry = self::$formRegistry[$formType] ?? null;
        if ($registry && isset($registry['associated_models'])) {
            $subformCode = self::getSubformCode($formType);
            $subCalibrationId = $calibrationId . '-' . $subformCode;

            foreach ($registry['associated_models'] as $modelClass) {
                if (class_exists($modelClass)) {
                    try {
                        $modelClass::where('calibration_id', $calibrationId)
                                   ->orWhere('calibration_id', $subCalibrationId)
                                   ->orWhere('calibration_id', 'LIKE', $calibrationId . '-%')
                                   ->delete();
                        \Log::info("🗑️ Deleted subform record(s) from " . class_basename($modelClass) . " for calibration ID: {$calibrationId} and {$subCalibrationId}");
                    } catch (\Exception $e) {
                        \Log::error("❌ Error deleting subform record from " . class_basename($modelClass) . ": " . $e->getMessage());
                    }
                }
            }
        }

        // Hapus file fisik gambar / attachment terkait form type ini
        self::deleteFormGambarFiles($calibrationId, $formType);
    }
    
    /**
     * Hapus file fisik gambar dan attachment yang disimpan di public folder
     */
    public static function deleteFormGambarFiles($calibrationId, $formType)
    {
        try {
            if ($formType === 'enclosure') {
                $pattern = public_path('img_Enclosure/enclosure_' . $calibrationId . '_*.png');
                $files = glob($pattern);
                if (!empty($files)) {
                    foreach ($files as $file) {
                        if (file_exists($file)) {
                            @unlink($file);
                            \Log::info('🗑️ File gambar enclosure fisik dihapus: ' . $file);
                        }
                    }
                }
            } elseif ($formType === 'chamber') {
                $pattern = public_path('img_Chamber/chamber_' . $calibrationId . '_*.png');
                $files = glob($pattern);
                if (!empty($files)) {
                    foreach ($files as $file) {
                        if (file_exists($file)) {
                            @unlink($file);
                            \Log::info('🗑️ File gambar chamber fisik dihapus: ' . $file);
                        }
                    }
                }
            } elseif ($formType === 'surface_plate') {
                $pattern = public_path('img_SurfacePlate/surface_plate_' . $calibrationId . '_*.png');
                $files = glob($pattern);
                if (!empty($files)) {
                    foreach ($files as $file) {
                        if (file_exists($file)) {
                            @unlink($file);
                            \Log::info('🗑️ File gambar surface_plate fisik dihapus: ' . $file);
                        }
                    }
                }
            } elseif ($formType === 'gauge_block') {
                $folder = public_path('uploads/gauge-block/' . $calibrationId);
                if (is_dir($folder)) {
                    $files = glob($folder . '/*');
                    if (!empty($files)) {
                        foreach ($files as $file) {
                            if (file_exists($file)) {
                                @unlink($file);
                                \Log::info('🗑️ File attachment gauge-block fisik dihapus: ' . $file);
                            }
                        }
                    }
                    @rmdir($folder);
                    \Log::info('🗑️ Folder gauge-block dihapus: ' . $folder);
                }
            }
        } catch (\Exception $e) {
            \Log::error('❌ Gagal menghapus file fisik gambar/attachment: ' . $e->getMessage());
        }
    }




