    public static function getSubformCode($formType)
    {
        $mapping = [
            'dial_indicator' => 'DI',
            'dial_test_indicator' => 'DTI',
            'caliper' => 'CL',
            'depth_caliper' => 'DC',
            'inside_micrometer' => 'IM',
            'outside_micrometer' => 'OM',
            'depth_micrometer' => 'DM',
            'thermometer' => 'TH',
            'thermoindicator' => 'TI',
            'thermohygrometer' => 'THG',
            'timbangan' => 'TB',
            'timbangan_moisture' => 'TM',
            'timbangan_bias' => 'TBB',
            'anak_timbangan' => 'AT',
            'pressure_gauge' => 'PG',
            'differential_pressure_gauge' => 'DPG',
            'pressure_transmitter' => 'PT',
            'enclosure' => 'ENC',
            'chamber' => 'CH',
            'volumetrik' => 'VOL',
            'viscometer' => 'VIS',
            'visco_cup' => 'VC',
            'push_pull' => 'PP',
            'torque_wrench' => 'TW',
            'torque_meter' => 'TM',
            'thickness_gauge' => 'TG',
            'penggaris' => 'PG',
            'gauge_block' => 'GB',
            'holetest' => 'HT',
            'conductivity_meter' => 'CM',
            'coating_thickness' => 'CT',
            'durometer' => 'DR',
            'mikropipet_dispenset' => 'MD',
            'taper_gauge' => 'TPG',
            'bore_gauge' => 'BG',
            'feeler_gauge' => 'FG',
            'ph_meter' => 'PH',
            'tachometer' => 'TAC',
            'pin_gauge' => 'PNG',
            'plain_limit_gauge' => 'PLG',
            'temp_humid_transmitter' => 'THT',
            'temperature_transmitter' => 'TT',
            'ir_thermometer' => 'IRT',
            'plastic_shim' => 'PS',
            'profil_projector' => 'PPJ',
            'surface_roughness_tester' => 'SRT',
            'ultrasonic_thickness_gauge' => 'UTG',
            'thread_gauge' => 'TRG',
            'stopwatch' => 'SW',
            'centrifuge' => 'CEN',
            'utm' => 'UTM',
            'surface_plate' => 'SP',
            'abration_tester' => 'ABT',
            'height_gauge' => 'HG',
            'insulation' => 'INS'
        ];
        
        if (isset($mapping[$formType])) {
            return $mapping[$formType];
        }
        
        // Fallback: ambil inisial dari tiap kata
        $words = explode('_', $formType);
        $code = '';
        foreach ($words as $word) {
            if (!empty($word)) {
                $code .= strtoupper(substr($word, 0, 1));
            }
        }
        return $code ?: strtoupper(substr($formType, 0, 2));
    }

public function store(Request $request)
{
    try {
        // 🔥 SANITIZE LEGACY FORM TYPE
        if ($request->input('form_type') === 'thermometer_infrared') {
            $request->merge(['form_type' => 'ir_thermometer']);
        }
        
        // 🔥 CEK APAKAH INI SUBFORM SAVE (dengan prefix sub_)
        $hasSubformData = false;
        $subFormData = [];
        $mainFormData = [];
        
        foreach ($request->all() as $key => $value) {
            if (str_starts_with($key, 'sub_')) {
                $hasSubformData = true;
                $originalKey = substr($key, 4); // Hapus prefix 'sub_'
                $subFormData[$originalKey] = $value;
            } else {
                $mainFormData[$key] = $value;
            }
        }
        
        // 🔥 JIKA INI MAIN FORM + SUBFORM (dengan prefix sub_)
         if ($hasSubformData) {
            \Log::info('🔄 Processing MAIN FORM + SUBFORM (with sub_ prefix)');
            \Log::info('📋 Main Form Data Keys:', array_keys($mainFormData));
            \Log::info('📋 Sub Form Data Keys:', array_keys($subFormData));
            
            // Ambil additional_forms untuk mengetahui jenis subform
            $additionalForms = $request->input('additional_forms', []);
            if (!is_array($additionalForms)) {
                $additionalForms = !empty($additionalForms) ? [$additionalForms] : [];
            }
            if (empty($additionalForms)) {
                if (!empty($subFormData['additional_forms'])) {
                    $additionalForms = is_array($subFormData['additional_forms']) ? $subFormData['additional_forms'] : [$subFormData['additional_forms']];
                } elseif (!empty($subFormData['form_type'])) {
                    $additionalForms = is_array($subFormData['form_type']) ? $subFormData['form_type'] : [$subFormData['form_type']];
                }
            }
            \Log::info('📋 Additional Forms:', $additionalForms);
            
            // Merge data main form ke request
            // ---------------------------------------------------------
            // 🔥 CAPTURE SUBFORM IDENTITIES IF ANY
            // ---------------------------------------------------------
            $subformIdentities = [];
            foreach ($additionalForms as $subType) {
                // Extract fields that start with 'sub_'
                $subIdData = [];
                // We only need the main identity fields
                $identityFields = [
                    'nama_alat', 'nama_alat_final', 'merek', 'kode_alat', 'type_alat', 'no_seri', 
                    'kapasitas', 'resolusi', 'rentang_ukur_max', 'rentang_ukur_min', 'rangeMax', 'rangeMin',
                    'nama_pemilik', 'no_po', 'tanggal_alat_masuk', 'tanggal_kalibrasi', 
                    'jenis_pembacaan', 'tempat_kalibrasi', 'lokasi_pt', 'kode_th', 
                    'fungsi_komponen', 'keterangan_fungsi_komponen', 
                    'suhu_awal', 'suhu_tengah', 'suhu_akhir', 
                    'rh_awal', 'rh_tengah', 'rh_akhir', 
                    'calibrated_by', 'verified_by'
                ];
                
                foreach ($identityFields as $field) {
                    if (array_key_exists($field, $subFormData) && $subFormData[$field] !== null && $subFormData[$field] !== '') {
                        $subIdData[$field] = $subFormData[$field];
                    }
                }
                if (!empty($subIdData)) {
                    $subformIdentities[$subType] = $subIdData;
                }
                \Log::info("📝 Extracted subform identities for {$subType}:", $subIdData);
            }
            if (!empty($subformIdentities)) {
                $mainFormData['subform_identities'] = json_encode($subformIdentities);
                \Log::info("💾 Final subform_identities JSON to save:", ['json' => $mainFormData['subform_identities']]);
            }

            $request->merge($mainFormData);
            
            // ================================================================
            // 🔥 PROSES GENERATE ID
            // ================================================================
            $lastCalibration = Calibration::where('id', 'LIKE', 'PAS-%')
                ->orderBy('id', 'desc')
                ->first();
            
            if ($lastCalibration) {
                preg_match('/PAS-(\d+)-K/', $lastCalibration->id, $matches);
                if (isset($matches[1])) {
                    $lastNumber = intval($matches[1]);
                    $newNumber = $lastNumber + 1;
                } else {
                    $lastNumber = intval(substr($lastCalibration->id, 4));
                    $newNumber = $lastNumber + 1;
                }
                \Log::info('Data terakhir ditemukan:', ['last_id' => $lastCalibration->id, 'new_number' => $newNumber]);
            } else {
                $newNumber = 1;
                \Log::info('Tidak ada data sebelumnya, memulai dari nomor 1');
            }
            
            $nomorUrutFormatted = str_pad($newNumber, 6, '0', STR_PAD_LEFT);
            $tahunSekarang = date('y');
            
             // ==================================================================
        // 2. TENTUKAN ID_ALAT
        // ==================================================================
        $noSeriVal = trim((string)($request->no_seri ?? $request->input('no_seri') ?? $request->input('NoSeri') ?? ''));
        $merekVal  = trim((string)($request->merek ?? $request->input('merek') ?? $request->input('brandAlat') ?? ''));
        $typeVal   = trim((string)($request->type_alat ?? $request->input('type_alat') ?? $request->input('typeAlat') ?? ''));

        // Normalize all unicode dash variants to standard ASCII '-'
        $noSeriClean = preg_replace('/[\x{2010}-\x{2015}\x{2212}\x{FE58}\x{FE63}\x{FF0D}]/u', '-', $noSeriVal);
        $merekClean  = preg_replace('/[\x{2010}-\x{2015}\x{2212}\x{FE58}\x{FE63}\x{FF0D}]/u', '-', $merekVal);
        $typeClean   = preg_replace('/[\x{2010}-\x{2015}\x{2212}\x{FE58}\x{FE63}\x{FF0D}]/u', '-', $typeVal);

        $isInvalidNoSeri = empty($noSeriClean) || 
            preg_match('/^[\s\-\._]*$/u', $noSeriClean) || 
            in_array(strtolower($noSeriClean), ['n/a', 'na', 'tidak ada', 'none', 'null', '0', '123456', '-']);

        $isInvalidMerek = empty($merekClean) || 
            preg_match('/^[\s\-\._]*$/u', $merekClean) || 
            in_array(strtolower($merekClean), ['n/a', 'na', 'tidak ada', 'none', 'null', '0', '-']);

        $isInvalidType = empty($typeClean) || 
            preg_match('/^[\s\-\._]*$/u', $typeClean) || 
            in_array(strtolower($typeClean), ['n/a', 'na', 'tidak ada', 'none', 'null', '0', '-']);

        $existingAlat = null;
        if (!$isInvalidNoSeri && !($isInvalidMerek && $isInvalidType)) {
            $existingAlat = Calibration::withTrashed()->where('NoSeri', $request->no_seri)
                ->where('brandAlat', $request->merek)
                ->where('typeAlat', $request->type_alat)
                ->orderBy('created_at', 'desc')
                ->first();
        }
            
            
            if ($existingAlat && !empty($existingAlat->id_alat)) {
                $idAlat = $existingAlat->id_alat;
                if (preg_match('/PAS-(\d+)-K(\d+)/', $idAlat, $matches)) {
                    $nomorUrutAlat = $matches[1];
                    $tahunAlat = $matches[2];
                } else {
                    $nomorUrutAlat = $nomorUrutFormatted;
                    $tahunAlat = $tahunSekarang;
                    $idAlat = 'PAS-' . $nomorUrutAlat . '-K' . $tahunAlat;
                }
                \Log::info('Alat sudah pernah dikalibrasi:', ['id_alat_lama' => $idAlat]);
            } else {
                $nomorUrutAlat = $nomorUrutFormatted;
                $tahunAlat = $tahunSekarang;
                $idAlat = 'PAS-' . $nomorUrutAlat . '-K' . $tahunAlat;
                \Log::info('Alat baru, membuat id_alat:', ['id_alat_baru' => $idAlat]);
            }
            
            // ================================================================
            // 🔥 TENTUKAN URUTAN KALIBRASI
            // ================================================================
            $allCalibrations = Calibration::where('id_alat', $idAlat)->get();
            if ($allCalibrations->isEmpty() && $existingAlat) {
                $allCalibrations = Calibration::where('NoSeri', $request->no_seri)
                    ->where('brandAlat', $request->merek)
                    ->where('typeAlat', $request->type_alat)
                    ->orderBy('tanggalKalibrasi', 'asc')
                    ->get();
            }
            
            $urutanKalibrasi = $allCalibrations->count() + 1;
            
            do {
                $customId = $idAlat . '-' . $urutanKalibrasi;
                $exists = Calibration::where('id', $customId)->exists();
                if ($exists) {
                    \Log::warning('⚠️ ID sudah ada, increment urutan', ['id' => $customId]);
                    $urutanKalibrasi++;
                }
            } while ($exists);
            
            \Log::info('Membuat record kalibrasi baru:', [
                'id_alat' => $idAlat,
                'id' => $customId,
                'urutan_kalibrasi_ke' => $urutanKalibrasi
            ]);
            
            // ================================================================
            // 🔥 PERSIAPAN DATA CALIBRATION
            // ================================================================
            $namaAlatFinal = $request->nama_alat === 'MANUAL_INPUT'
                ? $request->nama_alat_manual
                : $request->nama_alat;
            
            $formType = $request->form_type ?? 'default';
            
            // $namaAlatLower = strtolower($namaAlatFinal);
            // $enclosureAlat = ['freezer', 'oven', 'furnace', 'incubator', 'waterbath', 'autoclave'];
            
            // if (in_array($namaAlatLower, $enclosureAlat) && $formType !== 'enclosure') {
            //     \Log::warning('⚠️ FORM TYPE SALAH!', ['dikirim' => $formType, 'seharusnya' => 'enclosure']);
            //     $formType = 'enclosure';
            //     $request->merge(['form_type' => 'enclosure']);
            // }
            
            \Log::info('✅ FORM TYPE FINAL:', ['form_type' => $formType, 'nama_alat' => $namaAlatFinal]);
            
            $certificateId = $this->generateCertificateIdFromNamaAlat($namaAlatFinal, $customId);
            $userNik = auth()->user()->nik;
            $userName = auth()->user()->nama;
            $lkCode = $this->getLkCodeByFormType($formType);
            $initialStatus = Calibration::STATUS_DRAFT;
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
            
            // ================================================================
            // 🔥 BUAT DATA CALIBRATION
            // ================================================================
            $calibrationData = [
                'id' => $customId,
                'id_alat' => $idAlat,
                 'certificate_id' => $certificateId,
                'NIK' => $userNik,
                'LK' => $lkCode,
                'jenisPembacaan' => $request->jenis_pembacaan,
                'lokasiPT' => $request->lokasi_pt,
                'no_label' => null,
                'form_type' => $formType,
                'namaAlat' => $namaAlatFinal,
                'brandAlat' => $request->merek,
                'kodeAlat' => $request->kode_alat,
                'typeAlat' => $request->type_alat,
                'NoSeri' => $request->no_seri,
                'kapasitas' => $request->kapasitas,
                'resolusi' => $request->resolusi,
                'rangeMin' => $request->rentang_ukur_min,
                'rangeMax' => $request->rentang_ukur_max,
                'type' => $request->type,
                'pemilikAlat' => $request->nama_pemilik,
                   'no_po' => $request->no_po,
                'tanggalMasuk' => $request->tanggal_alat_masuk,
                'tanggalKalibrasi' => $request->tanggal_kalibrasi,
                'tempatKalibrasi' => $request->tempat_kalibrasi,
                'kondisiAlat' => $request->fungsi_komponen,
                'keterangan' => $request->keterangan_fungsi_komponen,
                'status' => $initialStatus,
                'RT_condition1' => $request->suhu_awal,
                'RT_condition2' => $request->suhu_tengah,
                'RT_condition3' => $request->suhu_akhir,
                'RH_condition1' => $request->rh_awal,
                'RH_condition2' => $request->rh_tengah,
                'RH_condition3' => $request->rh_akhir,
                'calibratedBy' => $request->calibrated_by,
                'verifiedBy' => $request->verified_by,
                'jumlah_form' => $jumlahForm,
                'kode_th' => $request->kode_th,
                'subform_identities' => $request->subform_identities,
            ];
            
            $calibrationData = $this->autoCompleteRequiredColumns($calibrationData);
            
            \Log::info('Menyimpan data ke database...');
            $calibration = Calibration::create($calibrationData);
            
            \Log::info('Data berhasil disimpan:', [
                'id' => $calibration->id,
                'id_alat' => $calibration->id_alat,
                'status' => $calibration->status
            ]);
            
            $calibration->markAsDraft($userName);
            
            // ================================================================
            // 🔥 SIMPAN DATA SPESIFIK ALAT (MAIN FORM)
            // ================================================================
            $this->storeAlatSpecificData($request, $calibration, $certificateId, $formType, true, $jumlahForm);
            \Log::info('Data spesifik alat (main form) berhasil disimpan');
            
            // ================================================================
            // 🔥 SIMPAN SUBFORMS (dari data dengan prefix sub_)
            // ================================================================
            $savedSubforms = [];
            
            foreach ($additionalForms as $subFormType) {
                if (empty($subFormType) || $subFormType === $formType) {
                    continue;
                }
                
                \Log::info("💾 Processing subform: {$subFormType} for calibration ID: {$calibration->id}");
                
                $registry = self::$formRegistry[$subFormType] ?? null;
                if ($registry && isset($registry['store_method'])) {
                    $storeMethod = $registry['store_method'];
                    if (method_exists($this, $storeMethod)) {
                        try {
                            // 🔥 BUAT REQUEST BARU DENGAN DATA SUBFORM (tanpa prefix sub_)
                            $subRequest = new \Illuminate\Http\Request($subFormData);
                            $subRequest->setMethod('POST');
                            
                            // 🔥 TAMBAHKAN FORM_TYPE UNTUK SUBFORM
                            $subRequest->merge(['form_type' => $subFormType]);
                            
                            // 🔥 TENTUKAN NAMA ALAT SUBFORM
                            $subNamaAlat = $subRequest->nama_alat ?? $subRequest->namaAlat ?? $calibration->namaAlat;
                            
                            // 🔥 BUAT RECORD CALIBRATION KHUSUS UNTUK SUBFORM
                            // 🔥 TAMBAHKAN CALIBRATION_ID KE SUBREQUEST (gunakan ID main form sesuai permintaan user)
                            $subRequest->merge(['calibration_id' => $calibration->id]);
                            
                            // 🔥 TAMBAHKAN JUMLAH FORM (default 1 untuk subform)
                            $subRequest->merge(['jumlah_form' => 1]);
                            
                            $subCertificateId = $this->generateCertificateIdFromNamaAlat(
                                $subNamaAlat, 
                                $calibration
                            );
                            
                            // 🔥 SIMPAN DATA TEKNIS (HEAD & DETAIL) SUBFORM
                            // User request: "kalau head mah itu tetep aja id nya sama kaya si main form"
                            // So we pass the MAIN $calibration for the relations (head/detail)
                            // but we pass $subCertificateId so it gets the right certificate number.
                            $this->$storeMethod($subRequest, $calibration, $subCertificateId);
                            $savedSubforms[] = $subFormType;
                            \Log::info("✅ Successfully stored subform: {$subFormType} with main ID {$calibration->id}");
                        } catch (\Exception $e) {
                            \Log::error("❌ Error storing subform {$subFormType}: " . $e->getMessage());
                        }
                    } else {
                        \Log::warning("⚠️ Store method {$storeMethod} not found in controller.");
                    }
                } else {
                    \Log::warning("⚠️ Subform type {$subFormType} not registered in formRegistry.");
                }
            }
            
           
            // 🔥 UPDATE additional_forms & subform_identities
            if (!empty($savedSubforms)) {
                $existingForms = $calibration->additional_forms ?? [];
                if (is_string($existingForms)) {
                    $existingForms = json_decode($existingForms, true) ?? [];
                }
                if (!is_array($existingForms)) {
                    $existingForms = [];
                }
                $allForms = array_values(array_unique(array_merge($existingForms, $savedSubforms)));
                \DB::table('calibrations')
                    ->where('id', $calibration->id)
                    ->update(['additional_forms' => json_encode($allForms)]);
                \Log::info("✅ additional_forms updated: " . json_encode($allForms));
            }
            if (!empty($subformIdentities)) {
                \DB::table('calibrations')
                    ->where('id', $calibration->id)
                    ->update(['subform_identities' => json_encode($subformIdentities)]);
                \Log::info("✅ subform_identities updated for ID {$calibration->id}");
            }
            
            // ================================================================
            // 🔥 LOG RINGKASAN AKHIR
            // ================================================================
            \Log::info('=== RINGKASAN KALIBRASI (MAIN + SUBFORM) ===');
            \Log::info('ID Alat (tetap): ' . $calibration->id_alat);
            \Log::info('ID Kalibrasi (unik): ' . $calibration->id);
            \Log::info('No Seri Alat: ' . $calibration->NoSeri);
            \Log::info('Main Form Type: ' . $formType);
            \Log::info('Subforms Saved: ' . implode(', ', $savedSubforms));
            \Log::info('Ini adalah kalibrasi ke-' . $urutanKalibrasi . ' untuk alat ini');
            
            LogHelper::log('create', "Membuat data kalibrasi baru: {$calibration->namaAlat} ({$calibration->NoSeri}) - ID: {$calibration->id}", $calibration);
            
            // ================================================================
            // 🔥 RETURN RESPONSE
            // ================================================================
            return response()->json([
                'success' => true,
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'calibration_data' => [
                    'id' => $calibration->id,
                    'nama_alat' => $calibration->namaAlat,
                    'no_seri' => $calibration->NoSeri,
                    'tanggal_kalibrasi' => $calibration->tanggalKalibrasi,
                ],
                'subforms_saved' => $savedSubforms,
                'message' => 'Data kalibrasi berhasil disimpan',
                'print_label_url' => route('calibrations.print-label', ['id' => $calibration->id])
            ]);
        }
        
        // ================================================================
        // 🔥 PENANGANAN KHUSUS UNTUK PENYIMPANAN HANYA SUBFORM SECARA TERPISAH
        // ================================================================
        if ($request->has('calibration_id') && $request->input('is_subform_only_save') === 'true') {
            $calibration = Calibration::findOrFail($request->calibration_id);
            $subFormType = $request->form_type;
            
            $registry = self::$formRegistry[$subFormType] ?? null;
            if ($registry) {
                // Delete existing subform records first to prevent duplicates
                self::deleteSubformData($calibration->id, $subFormType);
                
                $storeMethod = $registry['store_method'] ?? null;
                if ($storeMethod && method_exists($this, $storeMethod)) {
                    \Log::info("🆕 [Subform AJAX Only Save] Storing subform: {$subFormType} for calibration ID: {$calibration->id}");
                    
                    // 🔥 TENTUKAN NAMA ALAT SUBFORM
                    $subNamaAlat = $request->nama_alat ?? $request->namaAlat ?? $calibration->namaAlat;
                    
                    // 🔥 BUAT RECORD CALIBRATION KHUSUS UNTUK SUBFORM
                    $subformCode = self::getSubformCode($subFormType);
                    $subCalibrationId = $calibration->id . '-' . $subformCode;
                    
                    // Clone data calibration utama, timpa dengan spesifik subform
                    $subCalibrationData = $calibration->toArray();
                    $subCalibrationData['id'] = $subCalibrationId;
                    $subCalibrationData['form_type'] = $subFormType;
                    $subCalibrationData['namaAlat'] = $subNamaAlat;
                    $subCalibrationData['additional_forms'] = null; // Subform tidak punya additional_forms
                    
                    // Hindari duplikasi
                    $subCalibration = Calibration::firstOrCreate(
                        ['id' => $subCalibrationId],
                        $subCalibrationData
                    );
                    
                    // 🔥 UPDATE REQUEST DENGAN CALIBRATION_ID SUBFORM
                    $request->merge(['calibration_id' => $subCalibration->id]);
                    $request->merge(['jumlah_form' => 1]);
                    
                    $subCertificateId = $this->generateCertificateIdFromNamaAlat($subNamaAlat, $subCalibration);
                    try {
                        \App\Models\Calibration::$preventUpdating = true;
                        
                        // 🔥 SIMPAN DATA TEKNIS (HEAD & DETAIL) SUBFORM
                        $this->$storeMethod($request, $subCalibration, $subCertificateId);

                        // Update additional_forms column to track saved subforms
                        $existingForms = $calibration->additional_forms ?? [];
                        if (!is_array($existingForms)) {
                            $existingForms = [];
                        }
                        if (!in_array($subFormType, $existingForms)) {
                            $existingForms[] = $subFormType;
                        }
                        \DB::table('calibrations')
                            ->where('id', $calibration->id)
                            ->update(['additional_forms' => json_encode($existingForms)]);

                        \Log::info("✅ [Subform AJAX Only Save] Subform {$subFormType} stored and additional_forms updated for calibration ID: {$calibration->id}");

                        return response()->json([
                            'success' => true,
                            'message' => "Subform {$subFormType} stored successfully",
                            'calibration_id' => $calibration->id
                        ]);
                    } catch (\Exception $e) {
                        \Log::error("❌ Error storing subform {$subFormType}: " . $e->getMessage());
                        return response()->json(['success' => false, 'error' => $e->getMessage()], 500);
                    } finally {
                        \App\Models\Calibration::$preventUpdating = false;
                    }
                }
            }
            return response()->json(['success' => false, 'error' => 'Subform registry or store method not found'], 400);
        }
        
        // ================================================================
        // 🔥 STORE NORMAL (TANPA SUBFORM) - UNTUK SINGLE FORM
        // ================================================================
        // CEK APAKAH INI AJAX REQUEST ATAU MULTIPLE FORM SUBMIT ATAU TAB MODE
        $isAjax = $request->ajax() || $request->wantsJson() || $request->has('submit_all') || $request->has('is_tabbed_mode');
        $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        $jumlahForm = (int) ($request->jumlah_form ?? 1);
        
        \Log::info('🔍=== STORE REQUEST DETAIL (NORMAL) ===', [
            'is_ajax' => $isAjax,
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm,
            'has_submit_all' => $request->has('submit_all'),
            'has_is_tabbed_mode' => $request->has('is_tabbed_mode'),
            'all_input_keys' => array_keys($request->all()),
        ]);
        
        // ==================================================================
        // EKSTRAK DATA UNTUK MULTIPLE SUBMIT
        // ==================================================================
        $formDataForValidation = [];
        
        if ($isMultipleSubmit) {
            // Ekstrak data form 1 untuk validasi
            foreach ($request->all() as $key => $value) {
                if (strpos($key, 'form_1_') === 0) {
                    $originalKey = substr($key, 7);
                    $formDataForValidation[$originalKey] = $value;
                } elseif ($key === 'form_type' || $key === 'jumlah_form' || $key === 'submit_all' || $key === '_token') {
                    continue;
                } elseif (!strpos($key, 'form_') === 0 && !in_array($key, ['_token', 'submit_all', 'jumlah_form', 'form_type'])) {
                    $formDataForValidation[$key] = $value;
                }
            }
            
            \Log::info('📋 Extracted form 1 data for validation:', array_keys($formDataForValidation));
            
            // Merge data untuk diproses
            $request->merge($formDataForValidation);
        } else {
            // Validasi normal untuk single form (DIHAPUS SESUAI PERMINTAAN)
            // Note: form 1 variables are processed further down
            \Log::info('📋 Validating single form submission');
        }
        
        \Log::info('🔍=== RAW REQUEST DATA ===', [
            'form_type' => $request->input('form_type'),
            'all_input' => $request->except(['_token']),
        ]);
        
        // Log proses generate ID
        \Log::info('=== MEMULAI PROSES GENERATE ID CUSTOM ===');
        \Log::info('User: ' . auth()->user()->nama . ' (' . auth()->user()->nik . ')');
        
        // ==================================================================
        // 1. TENTUKAN NOMOR URUT GLOBAL
        // ==================================================================
        $lastCalibration = Calibration::withTrashed()->where('id', 'LIKE', 'PAS-%')
            ->orderBy('id', 'desc')
            ->first();
        
        if ($lastCalibration) {
            preg_match('/PAS-(\d+)-K/', $lastCalibration->id, $matches);
            if (isset($matches[1])) {
                $lastNumber = intval($matches[1]);
                $newNumber = $lastNumber + 1;
            } else {
                $lastNumber = intval(substr($lastCalibration->id, 4));
                $newNumber = $lastNumber + 1;
            }
            \Log::info('Data terakhir ditemukan:', ['last_id' => $lastCalibration->id, 'new_number' => $newNumber]);
        } else {
            $newNumber = 1;
            \Log::info('Tidak ada data sebelumnya, memulai dari nomor 1');
        }
        
        $nomorUrutFormatted = str_pad($newNumber, 6, '0', STR_PAD_LEFT);
        $tahunSekarang = date('y');
        
       // ==================================================================
        // 2. TENTUKAN ID_ALAT
        // ==================================================================
        $noSeriVal   = trim((string)($request->no_seri ?? $request->input('no_seri') ?? $request->input('NoSeri') ?? ''));
        $merekVal    = trim((string)($request->merek ?? $request->input('merek') ?? $request->input('brandAlat') ?? ''));
        $typeVal     = trim((string)($request->type_alat ?? $request->input('type_alat') ?? $request->input('typeAlat') ?? ''));
        $kodeAlatVal = trim((string)($request->kode_alat ?? $request->input('kode_alat') ?? $request->input('kodeAlat') ?? ''));
        $pemilikVal  = trim((string)($request->nama_pemilik ?? $request->input('nama_pemilik') ?? $request->input('pemilikAlat') ?? ''));

        $isNoSeriInvalid   = $this->isInvalidIdentifier($noSeriVal);
        $isKodeAlatInvalid = $this->isInvalidIdentifier($kodeAlatVal);
        $isMerekInvalid    = $this->isInvalidIdentifier($merekVal);
        $isTypeInvalid     = $this->isInvalidIdentifier($typeVal);
        $isPemilikInvalid  = $this->isInvalidIdentifier($pemilikVal);

        $existingAlat = null;
        // Hanya cari alat lama jika minimal salah satu identifier utama (NoSeri atau KodeAlat) VALID / BUKAN PLACEHOLDER
        if (!$isNoSeriInvalid || !$isKodeAlatInvalid) {
            $query = Calibration::withTrashed()->whereNotNull('id_alat');

            if (!$isNoSeriInvalid) {
                $query->where('NoSeri', $noSeriVal);
            }
            if (!$isKodeAlatInvalid) {
                $query->where('kodeAlat', $kodeAlatVal);
            }
            if (!$isMerekInvalid) {
                $query->where('brandAlat', $merekVal);
            }
            if (!$isTypeInvalid) {
                $query->where('typeAlat', $typeVal);
            }
            if (!$isPemilikInvalid) {
                $query->where('pemilikAlat', $pemilikVal);
            }

            $existingAlat = $query->orderBy('created_at', 'desc')->first();
        }
        
        if ($existingAlat && !empty($existingAlat->id_alat)) {
            $idAlat = $existingAlat->id_alat;
            if (preg_match('/PAS-(\d+)-K(\d+)/', $idAlat, $matches)) {
                $nomorUrutAlat = $matches[1];
                $tahunAlat = $matches[2];
            } else {
                $nomorUrutAlat = $nomorUrutFormatted;
                $tahunAlat = $tahunSekarang;
                $idAlat = 'PAS-' . $nomorUrutAlat . '-K' . $tahunAlat;
            }
            \Log::info('Alat sudah pernah dikalibrasi:', ['id_alat_lama' => $idAlat]);
        } else {
            $nomorUrutAlat = $nomorUrutFormatted;
            $tahunAlat = $tahunSekarang;
            $idAlat = 'PAS-' . $nomorUrutAlat . '-K' . $tahunAlat;
            \Log::info('Alat baru, membuat id_alat:', ['id_alat_baru' => $idAlat]);
        }
        
        
        // ==================================================================
        // 3. TENTUKAN URUTAN KALIBRASI
        // ==================================================================
        $allCalibrations = Calibration::withTrashed()->where('id_alat', $idAlat)->get();
              if ($allCalibrations->isEmpty() && $existingAlat && (!$isNoSeriInvalid || !$isKodeAlatInvalid)) {
                    $queryAll = Calibration::withTrashed()->whereNotNull('id_alat');
                    if (!$isNoSeriInvalid) {
                        $queryAll->where('NoSeri', $noSeriVal);
                    }
                    if (!$isKodeAlatInvalid) {
                        $queryAll->where('kodeAlat', $kodeAlatVal);
                    }
                    $allCalibrations = $queryAll->orderBy('tanggalKalibrasi', 'asc')->get();
        }
        
        $urutanKalibrasi = $allCalibrations->count() + 1;
        
        do {
            $customId = $idAlat . '-' . $urutanKalibrasi;
            $exists = Calibration::withTrashed()->where('id', $customId)->exists();
            if ($exists) {
                \Log::warning('⚠️ ID sudah ada, increment urutan', ['id' => $customId]);
                $urutanKalibrasi++;
            }
        } while ($exists);
        
        \Log::info('Membuat record kalibrasi baru:', [
            'id_alat' => $idAlat,
            'id' => $customId,
            'urutan_kalibrasi_ke' => $urutanKalibrasi
        ]);
        
        // ==================================================================
        // 4. PERSIAPAN DATA CALIBRATION
        // ==================================================================
        $namaAlatFinal = $request->nama_alat === 'MANUAL_INPUT'
            ? $request->nama_alat_manual
            : $request->nama_alat;
        
        $formType = $request->form_type ?? 'default';
        
        // $namaAlatLower = strtolower($namaAlatFinal);
        // $enclosureAlat = ['freezer', 'oven', 'furnace', 'incubator', 'waterbath', 'autoclave'];
        
        // if (in_array($namaAlatLower, $enclosureAlat) && $formType !== 'enclosure') {
        //     \Log::warning('⚠️ FORM TYPE SALAH!', ['dikirim' => $formType, 'seharusnya' => 'enclosure']);
        //     $formType = 'enclosure';
        //     $request->merge(['form_type' => 'enclosure']);
        // }
        
        if ($formType === 'timbangan' && ($request->input('timbanganType') === 'moisture' || $request->input('timbangan_type') === 'moisture')) {
            \Log::info('⚠️ OVERRIDING FORM TYPE: timbangan -> timbangan_moisture');
            $formType = 'timbangan_moisture';
            $request->merge(['form_type' => 'timbangan_moisture']);
        }
        
        \Log::info('✅ FORM TYPE FINAL:', ['form_type' => $formType, 'nama_alat' => $namaAlatFinal]);
        
        $certificateId = $this->generateCertificateIdFromNamaAlat($namaAlatFinal, $customId);
        $userNik = auth()->user()->nik;
        $userName = auth()->user()->nama;
        $lkCode = $this->getLkCodeByFormType($formType);
        $initialStatus = Calibration::STATUS_DRAFT;
        
        // ==================================================================
        // 5. BUAT DATA CALIBRATION
        // ==================================================================
        $calibrationData = [
            'id' => $customId,
            'id_alat' => $idAlat,
             'certificate_id' => $certificateId,
            'NIK' => $userNik,
            'LK' => $lkCode,
            'jenisPembacaan' => $request->jenis_pembacaan,
            'lokasiPT' => $request->lokasi_pt,
            'no_label' => null,
            'form_type' => $formType,
            'namaAlat' => $namaAlatFinal,
            'brandAlat' => $request->merek,
            'kodeAlat' => $request->kode_alat,
            'typeAlat' => $request->type_alat,
            'NoSeri' => $request->no_seri,
            'kapasitas' => $request->kapasitas,
            'resolusi' => $request->resolusi,
            'rangeMin' => $request->rentang_ukur_min,
            'rangeMax' => $request->rentang_ukur_max,
            'type' => $request->type,
            'pemilikAlat' => $request->nama_pemilik,
             'no_po' => $request->no_po ?? $request->input('no_po'),
            'tanggalMasuk' => $request->tanggal_alat_masuk,
            'tanggalKalibrasi' => $request->tanggal_kalibrasi,
            'tempatKalibrasi' => $request->tempat_kalibrasi,
            'kondisiAlat' => $request->fungsi_komponen,
            'keterangan' => $request->keterangan_fungsi_komponen,
            'status' => $initialStatus,
            'RT_condition1' => $request->suhu_awal,
            'RT_condition2' => $request->suhu_tengah,
            'RT_condition3' => $request->suhu_akhir,
            'RH_condition1' => $request->rh_awal,
            'RH_condition2' => $request->rh_tengah,
            'RH_condition3' => $request->rh_akhir,
            'calibratedBy' => $request->calibrated_by,
            'verifiedBy' => $request->verified_by,
            'jumlah_form' => $jumlahForm,
            'kode_th' => $request->kode_th,
        ];
        
        $calibrationData = $this->autoCompleteRequiredColumns($calibrationData);
        
        \Log::info('Menyimpan data ke database...');
        $calibration = Calibration::create($calibrationData);
        
        \Log::info('Data berhasil disimpan:', [
            'id' => $calibration->id,
            'id_alat' => $calibration->id_alat,
            'status' => $calibration->status
        ]);
        
        $calibration->markAsDraft($userName);
        
        // ==================================================================
        // 6. SIMPAN DATA SPESIFIK ALAT
        // ==================================================================
        $this->storeAlatSpecificData($request, $calibration, $certificateId, $formType, $isMultipleSubmit, $jumlahForm);
        \Log::info('Data spesifik alat berhasil disimpan');

        // ==================================================================
        // SIMPAN DATA FORM TAMBAHAN (SUBFORMS) - TANPA PREFIX
        // ==================================================================
        $additionalFormsNormal = $request->input('additional_forms', []);
        if (!is_array($additionalFormsNormal) && !empty($additionalFormsNormal)) {
            $additionalFormsNormal = [$additionalFormsNormal];
        }
        if (!empty($additionalFormsNormal) && is_array($additionalFormsNormal)) {
            $savedSubformsNormal = [];
            \App\Models\Calibration::$preventUpdating = true;
            try {
                foreach ($additionalFormsNormal as $subFormType) {
                    if (empty($subFormType) || $subFormType === $formType) {
                        continue;
                    }
                    
                    \Log::info("💾 Storing additional subform: {$subFormType} for calibration ID: {$calibration->id}");
                    
                    $registry = self::$formRegistry[$subFormType] ?? null;
                    if ($registry && isset($registry['store_method'])) {
                        $storeMethod = $registry['store_method'];
                        if (method_exists($this, $storeMethod)) {
                            $subCertificateId = $this->generateCertificateIdFromNamaAlat(ucwords(str_replace('_', ' ', $subFormType)), $calibration);
                            
                            try {
                                $this->$storeMethod($request, $calibration, $subCertificateId);
                                $savedSubformsNormal[] = $subFormType;
                                \Log::info("✅ Successfully stored subform: {$subFormType}");
                            } catch (\Exception $e) {
                                \Log::error("❌ Error storing subform {$subFormType}: " . $e->getMessage());
                            }
                        } else {
                            \Log::warning("⚠️ Store method {$storeMethod} not found in controller.");
                        }
                    } else {
                        \Log::warning("⚠️ Subform type {$subFormType} not registered in formRegistry.");
                    }
                }
            } finally {
                \App\Models\Calibration::$preventUpdating = false;
            }

            if (!empty($savedSubformsNormal)) {
                $existingForms = $calibration->additional_forms ?? [];
                if (is_string($existingForms)) {
                    $existingForms = json_decode($existingForms, true) ?? [];
                }
                if (!is_array($existingForms)) {
                    $existingForms = [];
                }
                $allForms = array_values(array_unique(array_merge($existingForms, $savedSubformsNormal)));
                \DB::table('calibrations')
                    ->where('id', $calibration->id)
                    ->update(['additional_forms' => json_encode($allForms)]);
                \Log::info("✅ [Normal Store] additional_forms updated: " . json_encode($allForms));
            }
        }
        
        // ==================================================================
        // 7. LOG RINGKASAN AKHIR
        // ==================================================================
        \Log::info('=== RINGKASAN KALIBRASI ===');
        \Log::info('ID Alat (tetap): ' . $calibration->id_alat);
        \Log::info('ID Kalibrasi (unik): ' . $calibration->id);
        \Log::info('No Seri Alat: ' . $calibration->NoSeri);
        \Log::info('Ini adalah kalibrasi ke-' . $urutanKalibrasi . ' untuk alat ini');
        
        LogHelper::log('create', "Membuat data kalibrasi baru: {$calibration->namaAlat} ({$calibration->NoSeri}) - ID: {$calibration->id}", $calibration);
        
        // ==================================================================
        // 8. RETURN RESPONSE
        // ==================================================================
        \Log::info('🔍=== SEBELUM RETURN RESPONSE ===', [
            'isAjax_final' => $isAjax,
            'will_return_json' => $isAjax ? 'YES' : 'NO',
            'will_redirect' => $isAjax ? 'NO' : 'YES'
        ]);
        
        if ($isAjax) {
            $responseData = [
                'success' => true,
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'calibration_data' => [
                    'id' => $calibration->id,
                    'nama_alat' => $calibration->namaAlat,
                    'no_seri' => $calibration->NoSeri,
                    'tanggal_kalibrasi' => $calibration->tanggalKalibrasi,
                ],
                'message' => 'Data kalibrasi berhasil disimpan',
                'print_label_url' => route('calibrations.print-label', ['id' => $calibration->id])
            ];
            
            \Log::info('✅ JSON RESPONSE YANG DIKIRIM:', [
                'response_keys' => array_keys($responseData),
                'has_print_label_url' => isset($responseData['print_label_url']),
                'print_label_url' => $responseData['print_label_url'] ?? 'not set'
            ]);
            
            return response()->json($responseData)->header('Content-Type', 'application/json');
        }
        
        \Log::info('🔴 REDIRECT KE PRINT LABEL (NON-AJAX):', [
            'url' => route('calibrations.print-label', ['id' => $calibration->id, 'show_modal' => true]),
            'calibration_id' => $calibration->id
        ]);
        
        return redirect()->route('calibrations.print-label', [
            'id' => $calibration->id,
            'show_modal' => true
        ])->with('success', 'Data kalibrasi berhasil disimpan!');
        
    } catch (\Exception $e) {
        \Log::error('=== ERROR SAAT MENYIMPAN DATA ===');
        \Log::error('Error message: ' . $e->getMessage());
        \Log::error('Error trace: ' . $e->getTraceAsString());
        
        $errorMessage = $this->getUserFriendlyErrorMessage($e);
        
        if ($request->ajax() || $request->wantsJson() || $request->has('submit_all') || $request->has('is_tabbed_mode')) {
            return response()->json([
                'success' => false,
                'error' => $errorMessage
            ], 500)->header('Content-Type', 'application/json');
        }
        
        return redirect()->back()
            ->with('swal_error', true)
            ->with('swal_title', 'Gagal Menyimpan Data')
            ->with('swal_text', $errorMessage)
            ->withInput();
    }
}
/**
 * Mendapatkan pesan error yang user-friendly
 */
private function getUserFriendlyErrorMessage($e)
{
    $message = $e->getMessage();
    
    if (str_contains($message, 'Out of range value')) {
        return 'Nilai yang dimasukkan tidak valid. Pastikan format angka sudah benar.';
    }
    
    if (str_contains($message, 'Duplicate entry')) {
        return 'Data dengan ID yang sama sudah ada. Silakan coba lagi.';
    }
    
    if (str_contains($message, 'foreign key constraint')) {
        return 'Gagal menyimpan data referensi. Silakan coba lagi.';
    }
    
    if (str_contains($message, 'Column not found')) {
        return 'Terjadi kesalahan struktur data. Silakan hubungi administrator.';
    }
    
    if (str_contains($message, 'Connection refused')) {
        return 'Koneksi database terputus. Silakan hubungi administrator.';
    }
    
    return 'Terjadi kesalahan saat menyimpan data. Silakan coba lagi.';
}

