 /**
   * Halaman cetak label kalibrasi — dipanggil otomatis setelah store()
     */
      public function printLabel($id)
{
    $calibration = Calibration::findOrFail($id);

    // Hitung next kalibrasi (+1 tahun)
    $tglKalibrasi     = Carbon::parse($calibration->tanggalKalibrasi);
    $nextKalibrasi    = $tglKalibrasi->copy()->addYear();

    // Ambil Certificate ID dari head model masing-masing alat
    $headRecord = null;
    $formType = $calibration->form_type;
    $registry = self::$formRegistry[$formType] ?? null;

    if ($registry && isset($registry['head_model']) && class_exists($registry['head_model'])) {
        $headClass = $registry['head_model'];
        try {
            $headRecord = $headClass::where('calibration_id', $calibration->id)->first();
        } catch (\Exception $e) {
            \Log::warning("⚠️ Gagal mengambil head model {$headClass}: " . $e->getMessage());
        }
    }

    $certificateId = '';
    if ($headRecord) {
        $certificateId = $headRecord->certificate_id ?? $headRecord->no_sertifikat ?? $headRecord->no_certificate ?? '';
    }
    if (empty($certificateId)) {
        $certificateId = $calibration->certificate_id ?? $calibration->id;
    }

    $qrCodeUrl = 'https://pascalibration.com/' . $certificateId;

    // ══════════════════════════════════════
    // Susun data untuk view
    // ══════════════════════════════════════
    $data = [
        'id_alat'             => $calibration->id_alat,
        'id'                  => $calibration->id,
        'certificate_id'      => $certificateId,
        'qr_code_url'         => $qrCodeUrl,
        'LK'                  => $calibration->LK,
        'NoSeri'              => $calibration->NoSeri ?? '',
        'kodeAlat'            => $calibration->kodeAlat ?? '',   // 🔥 tambah
        'type'                => $calibration->typeAlat ?? '',       // 🔥 tambah
        'namaAlat'            => $calibration->namaAlat,
        'tanggalKalibrasi'    => $tglKalibrasi->format('d-m-Y'),
        'nextTanggalKalibrasi'=> $nextKalibrasi->format('d-m-Y'),
        'today'               => now()->format('d-m-Y'),
        'no_label'            => $calibration->no_label,
    ];

    // 🔹 Tentukan showModal
    // Prioritas: query parameter > cek no_label kosong
    $showModal = request()->query('show_modal', empty($calibration->no_label) ? 'true' : 'false') === 'true';

    $successMessage = session('success');

    // ══════════════════════════════════════
    // Ambil Logo
    // ══════════════════════════════════════
    $logoBase64 = '';
    $logoUrl = 'https://www.pascalibration.com/wp-content/uploads/2023/09/logo_pas_basic.png';
    
    $ctx = stream_context_create([
        'http' => [
            'timeout' => 10,
            'header'  => "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64)\r\n"
        ],
        'ssl' => [
            'verify_peer' => false,
            'verify_peer_name' => false,
        ]
    ]);
    
    try {
        $imgData = @file_get_contents($logoUrl, false, $ctx);
        if ($imgData !== false) {
            $logoBase64 = 'data:image/png;base64,' . base64_encode($imgData);
        }
    } catch (\Exception $e) { }

    // Fallback ke local public path jika gagal
    if (empty($logoBase64)) {
        $logoPath = public_path('logo/logo_pas_basic.png');
        if (file_exists($logoPath)) {
            $type = pathinfo($logoPath, PATHINFO_EXTENSION);
            $imgData = file_get_contents($logoPath);
            $logoBase64 = 'data:image/' . $type . ';base64,' . base64_encode($imgData);
        }
    }

    return view('calibrations.print-label', compact('data', 'successMessage', 'logoBase64', 'showModal'));
}
// app/Http/Controllers/CalibrationController.php

public function updateLabel(Request $request, $id)
{
    try {
        $request->validate([
            'no_label' => 'required|string|max:50'
        ]);
        
        $calibration = Calibration::findOrFail($id);
        $calibration->no_label = $request->no_label;
        $calibration->save();
        
        if ($request->ajax() || $request->wantsJson()) {
            return response()->json([
                'success' => true,
                'message' => 'No. Label berhasil disimpan',
                'data' => $calibration
            ]);
        }
        
        return redirect()->back()->with('success', 'No. Label berhasil disimpan');
        
    } catch (\Exception $e) {
        if ($request->ajax() || $request->wantsJson()) {
            return response()->json([
                'success' => false,
                'message' => $e->getMessage()
            ], 500);
        }
        
        return redirect()->back()->with('error', 'Gagal menyimpan No. Label: ' . $e->getMessage());
    }
}
 
  /**
 * Fetch calibration data by id (bisa id_alat atau id biasa)
 */
public function fetchDataById($id)
{
    try {
        \Log::info('🔍 ===== FETCH DATA BY ID =====', [
            'id' => $id,
            'timestamp' => now()->toDateTimeString(),
            'ip' => request()->ip()
        ]);
        
        // ==================================================================
        // TAHAP 1: Cari berdasarkan ID KALIBRASI (primary key)
        // ==================================================================
        \Log::info('📌 [TAHAP 1] Mencari data berdasarkan id kalibrasi...', ['id' => $id]);
        $calibration = Calibration::find($id);
        
        if ($calibration) {
            \Log::info('✅ Data ditemukan berdasarkan id kalibrasi', [
                'id' => $calibration->id,
                'id_alat' => $calibration->id_alat,
                'namaAlat' => $calibration->namaAlat,
                'NoSeri' => $calibration->NoSeri,
                'form_type_database' => $calibration->form_type
            ]);
        }
        
        // ==================================================================
        // 🔥 TAHAP 2 (BARU): Potong suffix dari QR Code
        // QR Code: PAS-000629-K26-1-AnakTimbangan
        // ID asli: PAS-000629-K26-1
        // ==================================================================
        if (!$calibration) {
            \Log::info('📌 [TAHAP 2] Mencoba potong suffix dari ID...', ['original_id' => $id]);
            
            // Pattern: PAS-XXXXXX-KYY-Z (dimana Z adalah urutan kalibrasi)
            // Suffix setelah Z adalah form type, jadi kita potong
            if (preg_match('/^(PAS-\d+-K\d+-\d+)(?:-(.+))?$/i', $id, $matches)) {
                $baseId = $matches[1]; // PAS-000629-K26-1
                $suffix = $matches[2] ?? ''; // AnakTimbangan
                
                \Log::info('🔍 ID dipotong:', [
                    'original' => $id,
                    'base_id' => $baseId,
                    'suffix' => $suffix
                ]);
                
                // Coba cari berdasarkan base ID
                $calibration = Calibration::find($baseId);
                
                if ($calibration) {
                    \Log::info('✅ Data ditemukan berdasarkan base ID (setelah dipotong)', [
                        'id' => $calibration->id,
                        'id_alat' => $calibration->id_alat,
                        'namaAlat' => $calibration->namaAlat,
                        'suffix_dari_qr' => $suffix
                    ]);
                }
            }
        }
        
        // ==================================================================
        // TAHAP 3: Cari berdasarkan ID_ALAT
        // ==================================================================
        if (!$calibration) {
            \Log::info('📌 [TAHAP 3] Mencoba berdasarkan id_alat...', ['id_alat' => $id]);
            $calibration = Calibration::where('id_alat', $id)
                ->orderBy('tanggalKalibrasi', 'desc')
                ->orderBy('created_at', 'desc')
                ->first();
            
            if ($calibration) {
                \Log::info('✅ Data ditemukan berdasarkan id_alat', [
                    'id' => $calibration->id,
                    'id_alat' => $calibration->id_alat,
                    'namaAlat' => $calibration->namaAlat
                ]);
            }
        }
        
        // ==================================================================
        // TAHAP 4: 🔥 FIX - Cari berdasarkan certificate_id di HEAD TABLES
        // ==================================================================
        if (!$calibration) {
            \Log::info('📌 [TAHAP 4] Mencari berdasarkan certificate_id di head tables...', ['certificate_id' => $id]);
            
            foreach (self::$formRegistry as $type => $config) {
                if (!isset($config['head_model']) || !class_exists($config['head_model'])) {
                    continue;
                }
                
                $headClass = $config['head_model'];
                
                try {
                    $headModel = new $headClass();
                    $tableName = $headModel->getTable();
                    
                    if (!\Illuminate\Support\Facades\Schema::hasColumn($tableName, 'certificate_id')) {
                        continue;
                    }
                    
                    // Cari exact match dulu
                    $head = $headClass::where('certificate_id', $id)->first();
                    
                    // Kalau tidak ada, coba LIKE
                    if (!$head) {
                        $head = $headClass::where('certificate_id', 'LIKE', '%' . $id . '%')->first();
                    }
                    
                    if ($head && $head->calibration_id) {
                        $found = Calibration::find($head->calibration_id);
                        if ($found) {
                            $calibration = $found;
                            \Log::info("✅ Data ditemukan via head model", [
                                'head_class' => $headClass,
                                'certificate_id' => $head->certificate_id,
                                'calibration_id' => $calibration->id
                            ]);
                            break;
                        }
                    }
                } catch (\Exception $e) {
                    \Log::debug("⚠️ Error cek head model {$headClass}: " . $e->getMessage());
                    continue;
                }
            }
        }
        
        // ==================================================================
        // TAHAP 5: 🔥 BARU - Cari berdasarkan certificate_id DENGAN SUFFIX TERPOTONG
        // Jika QR Code berisi "PAS-000629-K26-1-AnakTimbangan" tapi
        // certificate_id di head adalah "PAS-000629-K26-AnakTimbangan" (tanpa urutan)
        // ==================================================================
        if (!$calibration) {
            \Log::info('📌 [TAHAP 5] Mencari berdasarkan certificate_id pattern...', ['id' => $id]);
            
            // Ekstrak nomor urut dari ID (PAS-000629)
            if (preg_match('/^PAS-(\d+)/i', $id, $matches)) {
                $nomorUrut = $matches[1]; // 000629
                
                \Log::info('🔍 Mencari berdasarkan nomor urut:', ['nomor_urut' => $nomorUrut]);
                
                // Cari calibration yang id-nya mengandung nomor urut ini
                $calibration = Calibration::where('id', 'LIKE', 'PAS-' . $nomorUrut . '-%')
                    ->orWhere('id_alat', 'LIKE', 'PAS-' . $nomorUrut . '-%')
                    ->orderBy('created_at', 'desc')
                    ->first();
                
                if ($calibration) {
                    \Log::info('✅ Data ditemukan berdasarkan nomor urut', [
                        'id' => $calibration->id,
                        'nomor_urut' => $nomorUrut
                    ]);
                }
            }
        }
        
        // ==================================================================
        // TAHAP 6: Cari berdasarkan NoSeri atau kodeAlat
        // ==================================================================
        if (!$calibration) {
            \Log::info('📌 [TAHAP 6] Mencoba berdasarkan NoSeri atau kodeAlat...', ['id' => $id]);
            $calibration = Calibration::where('NoSeri', $id)
                ->orWhere('kodeAlat', $id)
                ->orderBy('tanggalKalibrasi', 'desc')
                ->orderBy('created_at', 'desc')
                ->first();
            
            if ($calibration) {
                \Log::info('✅ Data ditemukan berdasarkan NoSeri/kodeAlat', [
                    'id' => $calibration->id,
                    'NoSeri' => $calibration->NoSeri,
                    'kodeAlat' => $calibration->kodeAlat
                ]);
            }
        }
        
        // ==================================================================
        // JIKA MASIH TIDAK DITEMUKAN
        // ==================================================================
        if (!$calibration) {
            \Log::warning('❌ Data tidak ditemukan setelah semua tahap', ['id' => $id]);
            
            return response()->json([
                'success' => false,
                'message' => 'Data alat tidak ditemukan. Pastikan QR Code valid atau data sudah terdaftar di database.'
            ], 404);
        }
        
        // ==================================================================
        // DEBUG INFO: Cek apakah ini subform
        // ==================================================================
        $isSubform = strpos($calibration->id, '-') !== false && substr_count($calibration->id, '-') > 3;
        \Log::info('🔍 INFO SUBFORM:', [
            'calibration_id' => $calibration->id,
            'is_subform' => $isSubform,
            'form_type' => $calibration->form_type
        ]);

        // ==================================================================
        // TENTUKAN FORM TYPE
        // ==================================================================
        $formType = $calibration->form_type;
        $formTypeFromDatabase = !empty($formType);
        
        // FALLBACK: Jika form_type di database masih kosong atau 'general'
        if (empty($formType) || $formType === 'general') {
            $lk = $calibration->LK ?? '';
            
            $lkMapping = [
                'PAS-FLK-01'  => 'inside_micrometer',
                'PAS-FLK-02'  => 'outside_micrometer',
                'PAS-FLK-06'  => 'depth_micrometer',
                'PAS-FLK-30'  => 'thermometer',
                'PAS-FLK-04'  => 'dial_indicator',
                'PAS-FLK-07'  => 'dial_test_indicator',
                'PAS-FLK-03'  => 'caliper',
                'PAS-FLK-13'  => 'torque_wrench',
                'PAS-FLK-13B' => 'torque_meter',
                'PAS-FLK-15'  => 'timbangan',
                'PAS-FLK-62'  => 'feeler_gauge',
                'PAS-FLK-29'  => 'enclosure',
                'PAS-FLK-29B' => 'chamber',
                'PAS-FLK-17'  => 'pressure_gauge',
                'PAS-FLK-17B' => 'differential_pressure_gauge',
                'PAS-FLK-16'  => 'anak_timbangan',
                'PAS-FLK-58'  => 'bore_gauge',
                'PAS-FLK-44'  => 'insulation',
            ];
            
            if (isset($lkMapping[$lk])) {
                $formType = $lkMapping[$lk];
                \Log::info('🔄 Form type ditentukan dari LK:', ['LK' => $lk, 'form_type' => $formType]);
            } else {
                $namaAlatLower = strtolower($calibration->namaAlat ?? '');
                if (str_contains($namaAlatLower, 'inside')) {
                    $formType = 'inside_micrometer';
                } elseif (str_contains($namaAlatLower, 'outside')) {
                    $formType = 'outside_micrometer';
                } elseif (str_contains($namaAlatLower, 'depth')) {
                    $formType = 'depth_micrometer';
                } elseif (str_contains($namaAlatLower, 'anak timbang')) {
                    $formType = 'anak_timbangan';
                } elseif (str_contains($namaAlatLower, 'bore')) {
                    $formType = 'bore_gauge';
                } else {
                    $formType = 'general';
                }
                \Log::info('🔄 Form type ditentukan dari nama alat:', [
                    'namaAlat' => $namaAlatLower,
                    'form_type' => $formType
                ]);
            }
            
            $calibration->update(['form_type' => $formType]);
        }

        // ==================================================================
        // AMBIL RIWAYAT KALIBRASI
        // ==================================================================
        $riwayat = Calibration::where('id_alat', $calibration->id_alat)
            ->orderBy('tanggalKalibrasi', 'desc')
            ->limit(5)
            ->get(['id', 'id_alat', 'LK', 'tanggalKalibrasi']);

        // ==================================================================
        // AMBIL DATA REPETITION
        // ==================================================================
        $repetition = null;
        
        if ($formType === 'enclosure') {
            $addEnclosures = \App\Models\AddEnclosure::where('calibration_id', $calibration->id)->get();
            if ($addEnclosures->isNotEmpty()) {
                $repetition = $addEnclosures->pluck('repetition_number')->unique()->count();
            }
        }
        
        if ($formType === 'chamber') {
            $addChambers = \App\Models\AddChamber::where('calibration_id', $calibration->id)->get();
            if ($addChambers->isNotEmpty()) {
                $repetition = $addChambers->pluck('repetition_number')->unique()->count();
            }
        }

        // ==================================================================
        // FORMAT TANGGAL
        // ==================================================================
        $formatDate = function($date) {
            if (!$date) return null;
            if (is_string($date) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) return $date;
            if ($date instanceof \Carbon\Carbon) return $date->format('Y-m-d');
            try {
                return date('Y-m-d', strtotime($date));
            } catch (\Exception $e) {
                return null;
            }
        };

        $tanggalMasuk = $formatDate($calibration->tanggalMasuk);
        $tanggalKalibrasi = $formatDate($calibration->tanggalKalibrasi);

        $riwayatFormatted = $riwayat->map(function($item) use ($formatDate) {
            return [
                'id' => $item->id,
                'id_alat' => $item->id_alat,
                'LK' => $item->LK,
                'tanggalKalibrasi' => $formatDate($item->tanggalKalibrasi)
            ];
        });

        // ==================================================================
        // BUILD RESPONSE DATA
        // ==================================================================
        $responseData = [
            'id' => $calibration->id,
            'id_alat' => $calibration->id_alat ?? $calibration->id,
            'namaAlat' => $calibration->namaAlat,
            'brandAlat' => $calibration->brandAlat,
            'typeAlat' => $calibration->typeAlat,
            'NoSeri' => $calibration->NoSeri,
            'kodeAlat' => $calibration->kodeAlat,
            'kapasitas' => $calibration->kapasitas,
            'resolusi' => $calibration->resolusi,
            'rangeMin' => $calibration->rangeMin,
            'rangeMax' => $calibration->rangeMax,
            'posisiAlat' => $calibration->posisiAlat,
            'pemilikAlat' => $calibration->pemilikAlat,
            'lokasiPT' => $calibration->lokasiPT,
            'LK' => $calibration->LK,
            'tanggalMasuk' => $tanggalMasuk,
            'tanggalKalibrasi' => $tanggalKalibrasi,
            'tempatKalibrasi' => $calibration->tempatKalibrasi,
            'jenisPembacaan' => $calibration->jenisPembacaan,
            'kondisiAlat' => $calibration->kondisiAlat,
            'keterangan' => $calibration->keterangan,
            'RT_condition1' => $calibration->RT_condition1,
            'RT_condition2' => $calibration->RT_condition2,
            'RT_condition3' => $calibration->RT_condition3,
            'RH_condition1' => $calibration->RH_condition1,
            'RH_condition2' => $calibration->RH_condition2,
            'RH_condition3' => $calibration->RH_condition3,
            'form_type' => $formType,
            'riwayatKalibrasi' => $riwayatFormatted,
            'capacity' => $calibration->capacity,
            'skala' => $calibration->skala,
            'type' => $calibration->type,
            'repetition' => $repetition,
            'jumlah_form' => $calibration->jumlah_form ?? 1,
            'certificate_id' => $calibration->certificate_id ?? null,
        ];

        \Log::info('📤 RESPONSE YANG DIKIRIM:', [
            'form_type' => $responseData['form_type'],
            'jumlah_form' => $responseData['jumlah_form'],
            'capacity' => $responseData['capacity'],
            'namaAlat' => $responseData['namaAlat']
        ]);

        return response()->json([
            'success' => true,
            'data' => $responseData
        ]);
        
    } catch (\Exception $e) {
        \Log::error('❌ FETCH DATA ERROR:', [
            'id' => $id,
            'error_message' => $e->getMessage(),
            'error_file' => $e->getFile(),
            'error_line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        
        return response()->json([
            'success' => false,
            'message' => 'Terjadi kesalahan: ' . $e->getMessage()
        ], 500);
    }
}
    
     /**
     * Helper check whether identifier value (no_seri, kode_alat, merek, type_alat, etc.)
     * is empty, whitespace-only, or a generic placeholder.
     */
    private function isInvalidIdentifier($value): bool
    {
        if ($value === null) {
            return true;
        }

        $str = (string)$value;

        // 1. Remove unicode whitespace, NBSP (\u{00A0}), zero-width spaces (\u{200B}, \u{FEFF}), etc.
        $clean = preg_replace('/[\s\x{00A0}\x{FEFF}\x{200B}\x{200C}\x{200D}]+/u', '', $str);

        // 2. Normalize unicode hyphens/dashes to ASCII '-'
        $clean = preg_replace('/[\x{2010}-\x{2015}\x{2212}\x{FE58}\x{FE63}\x{FF0D}]/u', '-', $clean);

        if ($clean === '') {
            return true;
        }

        // 3. Check if string consists solely of non-alphanumeric punctuation/symbols (e.g. -, _, ., /, \, ?, *, #)
        if (preg_match('/^[\-\._\/\\\\\?\*\#]+$/u', $clean)) {
            return true;
        }

        // 4. Lowercase and alphanumeric-only strings for placeholder matching
        $lower = strtolower($clean);
        $alphaOnly = preg_replace('/[^a-z0-9]/u', '', $lower);

        if ($alphaOnly === '') {
            return true;
        }

        // 5. Common placeholder patterns
        $invalidList = [
            'n/a', 'na', 'n.a', 'n.a.', 'none', 'null', '0', '00', '000',
            'tidakada', 'tidak_ada', 'tanpaseri', 'tanpamerk', 'tanpatype', 'tanpakode',
            '123456', '12345', '1234', '123', 'tba', 'pos', 'pad', 'unknown',
            'noseri', 'nomorseri', 'no_seri', 'kodealat', 'merek', 'type'
        ];

        if (in_array($lower, $invalidList, true) || in_array($alphaOnly, $invalidList, true)) {
            return true;
        }

        return false;
    }


