    private function storeAlatSpecificData($request, $calibration, $certificateId, $formType, $isMultipleSubmit = false, $jumlahForm = 1)
{
    if ($formType === 'thermometer_infrared') {
        $formType = 'ir_thermometer';
    }
    
    if ($formType === 'timbangan' && ($request->input('timbanganType') === 'moisture' || $request->input('timbangan_type') === 'moisture')) {
        $formType = 'timbangan_moisture';
    }
    
    \Log::info('🔧 Detected form type:', ['type' => $formType]);
    
    switch($formType) {
        case 'inside_micrometer':
            \Log::info('📏 Storing Inside Micrometer data...');
