            \Log::info('📐 Storing anak_timbangan data...');
             $this->storeAnakTimbangan($request, $calibration, $certificateId, $isMultipleSubmit, $jumlahForm);
            break;    

        case 'pressure_transmitter':
            \Log::info('📐 Storing pressure_transmitter data...');
            $this->storePressureTransmitter($request, $calibration, $certificateId);
            break;       
            
        case 'surface_plate':
            \Log::info('📐 Storing surface_plate data...');
            $this->storeSurfacePlate($request, $calibration, $certificateId);
            break;
                
        case 'abration_tester':
            \Log::info('📐 Storing storeAbrationTester data...');
            $this->storeAbrationTester($request, $calibration, $certificateId);
            break;    
        
        case 'height_gauge':
            \Log::info('📐 Storing storeHeightGauge data...');
            $this->storeHeightGauge($request, $calibration, $certificateId);
            break;    
              
        case 'insulation':
            \Log::info('📐 Storing storeInsulation data...');
            $this->storeInsulation($request, $calibration, $certificateId);
            break;    
                  
                
        default:
            \Log::error('❌ Unknown form type:', ['type' => $formType]);
            throw new \Exception('Jenis alat tidak dikenali: ' . $formType);
    }
}


