   private function storeInsideMicrometer($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeInsideMicrometer =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI (LOOPING SEMUA KEMUNGKINAN TAB)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key (termasuk tab)
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                // Format dengan double formIndex dan tab
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                
                // Format tanpa tab suffix
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            // Hapus duplikasi
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format (termasuk tab) PER FORM
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                // Format dengan form index di dalam key
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                
                // Format tanpa tab suffix
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        /**
         * Mencari nilai satuan unit dengan berbagai format (termasuk tab)
         */
        $findSatuanUnit = function($formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_satuan_unit_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_satuan_unit_tab{$tab}";
                $possibleKeys[] = "satuan_unit_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "satuan_unit_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_satuan_unit_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_satuan_unit";
                $possibleKeys[] = "satuan_unit_{$formIndex}";
                $possibleKeys[] = "satuan_unit";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found satuan_unit for form {$formIndex} using key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai rentang ukur min per form (disimpan di head)
         */
        $findRentangUkurMin = function($formIndex) use ($findValue) {
            $value = $findValue('rentang_ukur_min', $formIndex);
            if (empty($value)) {
                $value = $findValue('range_min', $formIndex);
            }
            return !empty($value) ? $value : '0';
        };
        
        /**
         * Mencari nilai rentang ukur max per form (disimpan di head)
         */
        $findRentangUkurMax = function($formIndex) use ($findValue) {
            $value = $findValue('rentang_ukur_max', $formIndex);
            if (empty($value)) {
                $value = $findValue('range_max', $formIndex);
            }
            return !empty($value) ? $value : '';
        };
        
        /**
         * Mencari nilai kapasitas per form (disimpan di head)
         */
        $findKapasitas = function($formIndex) use ($findValue) {
            $value = $findValue('kapasitas', $formIndex);
            if (empty($value)) {
                $value = $findValue('capacity', $formIndex);
            }
            return !empty($value) ? $value : '';
        };
        
        /**
         * Mencari nilai resolusi per form (disimpan di head)
         */
        $findResolusi = function($formIndex) use ($findValue) {
            $value = $findValue('resolusi', $formIndex);
            if (empty($value)) {
                $value = $findValue('resolution', $formIndex);
            }
            return !empty($value) ? $value : '';
        };
        
        // ==================================================================
        // 3. STORE HEADS UNTUK SETIAP FORM
        //    (Alat Standar, Rentang Ukur Min/Max, Kapasitas, Resolusi SEMUA per form)
        // ==================================================================
        $headsUpdated = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Ambil semua data per form
            $satuanUnit = $findSatuanUnit($formIndex);
            $rentangUkurMin = $findRentangUkurMin($formIndex);
            $rentangUkurMax = $findRentangUkurMax($formIndex);
            $kapasitas = $findKapasitas($formIndex);
            $resolusi = $findResolusi($formIndex);
            
            // Ambil alat standar PER FORM (tidak dari form 1)
            $alatStandar = $findArrayValue('alat_standar', $formIndex);
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            \Log::info("📝 Creating/Updating head for form {$formIndex}", [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
            ]);
            
            HeadInsideMicrometer::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'satuan_unit' => $satuanUnit,
                    'rentang_ukur_min' => $rentangUkurMin,
                    'rentang_ukur_max' => $rentangUkurMax,
                    'kapasitas' => $kapasitas,
                    'resolusi' => $resolusi,
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-01 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)',
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
            $headsUpdated++;
        }
        
        \Log::info("✅ Updated {$headsUpdated} head records");
        
        // ==================================================================
        // 4. HAPUS DATA LAMA UNTUK FORM YANG TIDAK ADA
        // ==================================================================
        HeadInsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
            
        DetailInsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 5. STORE DETAILS UNTUK SETIAP FORM
        // ==================================================================
        $totalDetailsSaved = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Deteksi maksimum row dari yang ada di request
            $maxRow = 0;
            
            for ($row = 1; $row <= 20; $row++) {
                $titikUkur = $findValue('nominal', $formIndex, [$row]);
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('setting', $formIndex, [$row]);
                }
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                
                if ($titikUkur !== null && $titikUkur !== '') {
                    $maxRow = $maxRow > 0 ? max($maxRow, $row) : $row;
                }
            }
            
            // Jika tidak ada nominal sama sekali, skip
            if ($maxRow === 0) {
                \Log::info("No nominal data found for form {$formIndex}, skipping details");
                continue;
            }
            
            // Set minimal row ke 14
            $maxRow = max($maxRow, 14);
            \Log::info("Processing up to row {$maxRow} for form {$formIndex}");
            
            for ($row = 1; $row <= $maxRow; $row++) {
                // Cari nilai nominal (titik ukur)
                $titikUkur = $findValue('nominal', $formIndex, [$row]);
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('setting', $formIndex, [$row]);
                }
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                
                // Ambil 5 nilai penunjukan
                $penunjukan = [];
                for ($col = 1; $col <= 5; $col++) {
                    $value = $findValue('penunjukan', $formIndex, [$row, $col]);
                    if (empty($value)) {
                        $value = $findValue('nilai', $formIndex, [$row, $col]);
                    }
                    if (empty($value)) {
                        $value = $findValue('pembacaan', $formIndex, [$row, $col]);
                    }
                    $penunjukan[] = $value;
                }
                
                $hasTitikUkur = !empty(trim($titikUkur ?? ''));
                $hasAnyPenunjukan = !empty($penunjukan[0]) || !empty($penunjukan[1]) || 
                                    !empty($penunjukan[2]) || !empty($penunjukan[3]) || 
                                    !empty($penunjukan[4]);
                
                if ($hasTitikUkur || $hasAnyPenunjukan) {
                    if (empty($titikUkur)) {
                        $titikUkur = '0';
                    }
                    
                    $detailData = [
                        'ulangan01' => !empty($penunjukan[0]) ? str_replace(',', '.', $penunjukan[0]) : null,
                        'ulangan02' => !empty($penunjukan[1]) ? str_replace(',', '.', $penunjukan[1]) : null,
                        'ulangan03' => !empty($penunjukan[2]) ? str_replace(',', '.', $penunjukan[2]) : null,
                        'ulangan04' => !empty($penunjukan[3]) ? str_replace(',', '.', $penunjukan[3]) : null,
                        'ulangan05' => !empty($penunjukan[4]) ? str_replace(',', '.', $penunjukan[4]) : null,
                    ];
                    
                    DetailInsideMicrometer::updateOrCreate(
                        [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'titikUkur' => $titikUkur
                        ],
                        $detailData
                    );
                    $totalDetailsSaved++;
                    \Log::debug("Detail saved for form {$formIndex}, row {$row}", [
                        'titikUkur' => $titikUkur,
                        'penunjukan' => $penunjukan
                    ]);
                }
            }
        }
        
        \Log::info("✅ Saved {$totalDetailsSaved} detail measurements for Inside Micrometer");
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        \Log::info('✅ storeInsideMicrometer completed successfully', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_updated' => $headsUpdated,
            'total_details_saved' => $totalDetailsSaved
        ]);
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeInsideMicrometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function storeOutsideMicrometer($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeOutsideMicrometer =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI (LOOPING SEMUA KEMUNGKINAN TAB)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key (termasuk tab)
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                // Format dengan double formIndex dan tab
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                
                // Format tanpa tab suffix
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            // Hapus duplikasi
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format (termasuk tab)
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        /**
         * Mencari nilai satuan unit dengan berbagai format (termasuk tab)
         */
        $findSatuanUnit = function($formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_satuan_unit_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_satuan_unit_tab{$tab}";
                $possibleKeys[] = "satuan_unit_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "satuan_unit_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_satuan_unit_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_satuan_unit";
                $possibleKeys[] = "satuan_unit_{$formIndex}";
                $possibleKeys[] = "satuan_unit";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found satuan_unit for form {$formIndex} using key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * 🔥 BARU: Mencari nilai rentang ukur min per form
         */
        $findRentangUkurMin = function($formIndex) use ($findValue) {
            $value = $findValue('rentang_ukur_min', $formIndex);
            if (empty($value)) {
                $value = $findValue('range_min', $formIndex);
            }
            if (empty($value)) {
                $value = $findValue('rentang_ukur_min', $formIndex, []);
            }
            return !empty($value) ? $value : '0';
        };
        
        /**
         * 🔥 BARU: Mencari nilai rentang ukur max per form
         */
        $findRentangUkurMax = function($formIndex) use ($findValue) {
            $value = $findValue('rentang_ukur_max', $formIndex);
            if (empty($value)) {
                $value = $findValue('range_max', $formIndex);
            }
            if (empty($value)) {
                $value = $findValue('rentang_ukur_max', $formIndex, []);
            }
            return !empty($value) ? $value : '';
        };
        
        /**
         * 🔥 BARU: Mencari nilai kapasitas per form
         */
        $findKapasitas = function($formIndex) use ($findValue) {
            $value = $findValue('kapasitas', $formIndex);
            if (empty($value)) {
                $value = $findValue('capacity', $formIndex);
            }
            if (empty($value)) {
                $value = $findValue('kapasitas', $formIndex, []);
            }
            return !empty($value) ? $value : '';
        };
        
        /**
         * 🔥 BARU: Mencari nilai resolusi per form
         */
        $findResolusi = function($formIndex) use ($findValue) {
            $value = $findValue('resolusi', $formIndex);
            if (empty($value)) {
                $value = $findValue('resolution', $formIndex);
            }
            if (empty($value)) {
                $value = $findValue('resolusi', $formIndex, []);
            }
            return !empty($value) ? $value : '';
        };
        
        // ==================================================================
        // 3. AMBIL ALAT STANDAR PER FORM (TIDAK DARI FORM 1)
        // ==================================================================
        
        // ==================================================================
        // 4. LOOP UNTUK SETIAP FORM
        // ==================================================================
        $headsUpdated = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex}");
            \Log::info("=========================================");
            
            // 🔥 AMBIL DATA DARI REQUEST (PER FORM)
            $satuanUnit = $findSatuanUnit($formIndex);
            $rentangUkurMin = $findRentangUkurMin($formIndex);
            $rentangUkurMax = $findRentangUkurMax($formIndex);
            $kapasitas = $findKapasitas($formIndex);
            $resolusi = $findResolusi($formIndex);
            
            // 🔥 AMBIL ALAT STANDAR PER FORM (MASING-MASING FORM PUNYA SENDIRI)
            $alatStandar = $findArrayValue('alat_standar', $formIndex);
            
            // Jika masih kosong dan ini form 1, coba dari alat_standar biasa (backward compatibility)
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
                if (!is_array($alatStandar)) {
                    $alatStandar = [$alatStandar];
                }
            }
            
            // Pastikan dalam bentuk array
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            // Filter nilai kosong
            $alatStandar = array_filter($alatStandar);
            
            // Simpan ke database
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            \Log::info("📝 Head data untuk form {$formIndex}:", [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
            ]);
            
            // ==========================================================
            // SIMPAN HEAD OUTSIDE MICROMETER (DENGAN FIELD BARU)
            // ==========================================================
            HeadOutsideMicrometer::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'satuan_unit' => $satuanUnit,
                    'rentang_ukur_min' => $rentangUkurMin,
                    'rentang_ukur_max' => $rentangUkurMax,
                    'kapasitas' => $kapasitas,
                    'resolusi' => $resolusi,
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-02 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)',
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
            $headsUpdated++;
            
            // ==========================================================
            // SIMPAN DATA UJI KERATAAN (ADD OUTSIDE MICROMETER)
            // ==========================================================
            $ujiKerataanData = [
                'ukuranAnvil1' => $findValue('ukuranAnvil1', $formIndex, []),
                'jumlahAnvil1' => $findValue('jumlahAnvil1', $formIndex, []),
                'ukuranAnvil2' => $findValue('ukuranAnvil2', $formIndex, []),
                'jumlahAnvil2' => $findValue('jumlahAnvil2', $formIndex, []),
                'ukuranSpindle1' => $findValue('ukuranSpindle1', $formIndex, []),
                'jumlahSpindle1' => $findValue('jumlahSpindle1', $formIndex, []),
                'ukuranSpindle2' => $findValue('ukuranSpindle2', $formIndex, []),
                'jumlahSpindle2' => $findValue('jumlahSpindle2', $formIndex, []),
            ];
            
            \Log::info("📝 UJI KERATAAN DATA FOR FORM {$formIndex}:", $ujiKerataanData);
            
            AddOutsideMicrometer::updateOrCreate(
                [
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex
                ],
                $ujiKerataanData
            );
            
            // ==========================================================
            // SIMPAN DETAIL MEASUREMENTS (UJI SKALA NOMINAL)
            // ==========================================================
            $detailCount = 0;
            for ($row = 1; $row <= 14; $row++) {
                // Cari nilai nominal (titik ukur)
                $titikUkur = $findValue('nominal', $formIndex, [$row]);
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('setting', $formIndex, [$row]);
                }
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                
                // Ambil 5 nilai penunjukan
                $penunjukan = [];
                for ($col = 1; $col <= 5; $col++) {
                    $value = $findValue('penunjukan', $formIndex, [$row, $col]);
                    if (empty($value)) {
                        $value = $findValue('nilai', $formIndex, [$row, $col]);
                    }
                    if (empty($value)) {
                        $value = $findValue('pembacaan', $formIndex, [$row, $col]);
                    }
                    $penunjukan[] = $value;
                }
                
                $hasTitikUkur = !empty(trim($titikUkur ?? ''));
                $hasAnyPenunjukan = !empty($penunjukan[0]) || !empty($penunjukan[1]) || 
                                    !empty($penunjukan[2]) || !empty($penunjukan[3]) || 
                                    !empty($penunjukan[4]);
                
                if ($hasTitikUkur || $hasAnyPenunjukan) {
                    $detailData = [
                        'ulangan01' => !empty($penunjukan[0]) ? str_replace(',', '.', $penunjukan[0]) : null,
                        'ulangan02' => !empty($penunjukan[1]) ? str_replace(',', '.', $penunjukan[1]) : null,
                        'ulangan03' => !empty($penunjukan[2]) ? str_replace(',', '.', $penunjukan[2]) : null,
                        'ulangan04' => !empty($penunjukan[3]) ? str_replace(',', '.', $penunjukan[3]) : null,
                        'ulangan05' => !empty($penunjukan[4]) ? str_replace(',', '.', $penunjukan[4]) : null,
                    ];
                    
                    DetailOutsideMicrometer::updateOrCreate(
                        [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'titikUkur' => $titikUkur
                        ],
                        $detailData
                    );
                    $detailCount++;
                    \Log::debug("Detail saved for form {$formIndex}, row {$row}", [
                        'titikUkur' => $titikUkur,
                        'penunjukan' => $penunjukan
                    ]);
                }
            }
            \Log::info("📊 DETAIL SAVED FOR FORM {$formIndex}: {$detailCount} records");
        }
        
        // ==================================================================
        // 5. HAPUS DATA LAMA UNTUK FORM YANG TIDAK ADA
        // ==================================================================
        HeadOutsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        AddOutsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        DetailOutsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // (JANGAN UPDATE RANGE, KAPASITAS, RESOLUSI DI CALIBRATION)
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // FINAL VERIFICATION
        $allHeads = HeadOutsideMicrometer::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailOutsideMicrometer::where('calibration_id', $calibration->id)->get();
        $allAdd = AddOutsideMicrometer::where('calibration_id', $calibration->id)->get();
        
        \Log::info("🎯 FINAL SUMMARY:", [
            'total_head_records' => $allHeads->count(),
            'head_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_detail_records' => $allDetails->count(),
            'detail_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'total_add_records' => $allAdd->count(),
            'add_by_form' => $allAdd->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'heads_updated' => $headsUpdated
        ]);
        
        \Log::info('✅ storeOutsideMicrometer completed successfully');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeOutsideMicrometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

