                if ($value !== null && $value !== '') {
                    \Log::debug("Found satuan_unit for form {$formIndex} using key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * 🔥 BARU: Mencari nilai rentang ukur min per form
         */
        $findRentangUkurMin = function($formIndex) use ($findValue) {
            $value = $findValue('rentang_ukur_min', $formIndex);
            if (empty($value)) {
                $value = $findValue('range_min', $formIndex);
            }
            return !empty($value) ? $value : '0';
        };
        
        /**
         * 🔥 BARU: Mencari nilai rentang ukur max per form
         */
        $findRentangUkurMax = function($formIndex) use ($findValue) {
