            // Simpan ke database
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            \Log::info("📝 Creating/Updating head for form {$formIndex}", [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
            ]);
            
            HeadDepthMicrometer::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'satuan_unit' => $satuanUnit,
                    'rentang_ukur_min' => $rentangUkurMin,
                    'rentang_ukur_max' => $rentangUkurMax,
                    'kapasitas' => $kapasitas,
                    'resolusi' => $resolusi,
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-06 (JIS B 7544 : 1994)',
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
        }
        
        // ==================================================================
        // 4. HAPUS DATA LAMA UNTUK FORM YANG TIDAK ADA
        // ==================================================================
        HeadDepthMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        DetailDepthMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 5. STORE DETAILS UNTUK SETIAP FORM
        // ==================================================================
        $totalDetailsSaved = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Deteksi maksimum row dari yang ada di request
            $maxRow = 0;
            
            for ($row = 1; $row <= 20; $row++) {
                $titikUkur = $findValue('nominal', $formIndex, [$row]);
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('setting', $formIndex, [$row]);
                }
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                
                if ($titikUkur !== null && $titikUkur !== '') {
                    $maxRow = $maxRow > 0 ? max($maxRow, $row) : $row;
                }
            }
            
            // Jika tidak ada nominal sama sekali, skip
            if ($maxRow === 0) {
                \Log::info("No nominal data found for form {$formIndex}, skipping details");
                continue;
            }
            
            // Set minimal row ke 14
            $maxRow = max($maxRow, 14);
            \Log::info("Processing up to row {$maxRow} for form {$formIndex}");
            
            for ($row = 1; $row <= $maxRow; $row++) {
                // Cari nilai nominal (titik ukur)
                $titikUkur = $findValue('nominal', $formIndex, [$row]);
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('setting', $formIndex, [$row]);
                }
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                
                // Ambil 5 nilai penunjukan
                $penunjukan = [];
                for ($col = 1; $col <= 5; $col++) {
                    $value = $findValue('penunjukan', $formIndex, [$row, $col]);
                    if (empty($value)) {
                        $value = $findValue('nilai', $formIndex, [$row, $col]);
                    }
                    if (empty($value)) {
                        $value = $findValue('pembacaan', $formIndex, [$row, $col]);
                    }
                    $penunjukan[] = $value;
                }
                
                $hasTitikUkur = !empty(trim($titikUkur ?? ''));
                $hasAnyPenunjukan = !empty($penunjukan[0]) || !empty($penunjukan[1]) || 
                                    !empty($penunjukan[2]) || !empty($penunjukan[3]) || 
                                    !empty($penunjukan[4]);
                
                if ($hasTitikUkur || $hasAnyPenunjukan) {
                    if (empty($titikUkur)) {
                        $titikUkur = '0';
                    }
                    
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'ulangan01' => !empty($penunjukan[0]) ? str_replace(',', '.', $penunjukan[0]) : null,
                        'ulangan02' => !empty($penunjukan[1]) ? str_replace(',', '.', $penunjukan[1]) : null,
                        'ulangan03' => !empty($penunjukan[2]) ? str_replace(',', '.', $penunjukan[2]) : null,
                        'ulangan04' => !empty($penunjukan[3]) ? str_replace(',', '.', $penunjukan[3]) : null,
                        'ulangan05' => !empty($penunjukan[4]) ? str_replace(',', '.', $penunjukan[4]) : null,
                    ];
                    
                    DetailDepthMicrometer::updateOrCreate(
                        [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'titikUkur' => $titikUkur
                        ],
                        $detailData
                    );
                    $totalDetailsSaved++;
                    \Log::debug("Detail saved for form {$formIndex}, row {$row}", [
                        'titikUkur' => $titikUkur,
                        'penunjukan' => $penunjukan
                    ]);
                }
            }
        }
        
        \Log::info("✅ Saved {$totalDetailsSaved} detail measurements for Depth Micrometer");
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // (JANGAN UPDATE RANGE, KAPASITAS, RESOLUSI DI CALIBRATION)
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // FINAL VERIFICATION
        $allHeads = HeadDepthMicrometer::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailDepthMicrometer::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🎯 FINAL SUMMARY:', [
            'total_head_records' => $allHeads->count(),
            'head_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_detail_records' => $allDetails->count(),
            'detail_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
        ]);
        
        \Log::info('✅ storeDepthMicrometer completed successfully', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'total_details_saved' => $totalDetailsSaved
        ]);
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeDepthMicrometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

  private function updateDepthMicrometer($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateDepthMicrometer =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong atau MANUAL_INPUT):', [
                'certificate_id_lama' => $calibration->certificate_id,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        }
        
        // Update certificate_id di tabel calibration
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
            
            \Log::info('📝 UPDATE CERTIFICATE ID DI CALIBRATION:', [
                'certificate_id_baru' => $certificateIdBaru,
                'current_certificate_id' => $calibration->certificate_id
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Depth Micrometer - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM (DENGAN FIELD BARU PER FORM)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadDepthMicrometer::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // 🔥 AMBIL DATA DARI REQUEST (PER FORM)
            // Satuan Unit
            $satuanUnit = $request->input("satuan_unit_{$formIndex}", 
                          $request->input("satuan_unit", 'mm'));
            
            // 🔥 RENTANG UKUR MIN & MAX (PER FORM)
            $rentangUkurMin = $request->input("rentang_ukur_min_{$formIndex}", 
                             $request->input("rentang_ukur_min", '0'));
            $rentangUkurMax = $request->input("rentang_ukur_max_{$formIndex}", 
                             $request->input("rentang_ukur_max", ''));
            
            // 🔥 KAPASITAS & RESOLUSI (PER FORM)
            $kapasitas = $request->input("kapasitas_{$formIndex}", 
                        $request->input("kapasitas", ''));
            $resolusi = $request->input("resolusi_{$formIndex}", 
                      $request->input("resolusi", ''));
            
            // 🔥 AMBIL ALAT STANDAR UNTUK FORM INI (MASING-MASING FORM PUNYA SENDIRI)
            $alatStandar = [];
            
            // Coba ambil dari alat_standar_{formIndex}[]
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            
            // Jika masih kosong dan ini form 1, coba dari alat_standar biasa (backward compatibility)
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
            }
            
            // Pastikan dalam bentuk array
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            // Filter nilai kosong
            $alatStandar = array_filter($alatStandar);
            
            // Simpan ke database
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            $headData = [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-06 (JIS B 7544 : 1994)',
            ];
            
            \Log::info("📝 Head data untuk form {$formIndex}:", [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
            ]);
            
            // 🔥 UPDATE CERTIFICATE ID UNTUK SEMUA HEAD (FORM 1-4)
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            } elseif ($head && $head->certificate_id) {
                // Pertahankan certificate_id yang sudah ada
                $headData['certificate_id'] = $head->certificate_id;
            } else {
                $headData['certificate_id'] = $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'satuan_unit' => $head->satuan_unit,
                    'rentang_ukur_min' => $head->rentang_ukur_min,
                    'rentang_ukur_max' => $head->rentang_ukur_max,
                    'kapasitas' => $head->kapasitas,
                    'resolusi' => $head->resolusi,
                    'standard' => $head->standard,
                    'certificate_id' => $head->certificate_id ?? 'not_set'
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $head = HeadDepthMicrometer::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadDepthMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS (UJI SKALA NOMINAL) PER FORM
        // ==================================================================
        DetailDepthMicrometer::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Coba ambil data dengan berbagai format (dengan prefix form index)
            $titikUkurArray = $request->input("titikUkur_{$formIndex}", []);
            $ulangan01Array = $request->input("ulangan01_{$formIndex}", []);
            $ulangan02Array = $request->input("ulangan02_{$formIndex}", []);
            $ulangan03Array = $request->input("ulangan03_{$formIndex}", []);
            $ulangan04Array = $request->input("ulangan04_{$formIndex}", []);
            $ulangan05Array = $request->input("ulangan05_{$formIndex}", []);
            
            // Jika tidak ada data dengan format per form, coba ambil dari format array biasa
            if (empty($titikUkurArray)) {
                $titikUkurArray = $request->input("titikUkur", []);
                $ulangan01Array = $request->input("ulangan01", []);
                $ulangan02Array = $request->input("ulangan02", []);
                $ulangan03Array = $request->input("ulangan03", []);
                $ulangan04Array = $request->input("ulangan04", []);
                $ulangan05Array = $request->input("ulangan05", []);
                \Log::info("Using fallback array format for form {$formIndex}");
            }
            
            for ($i = 0; $i < 14; $i++) {
                $titikUkur = $titikUkurArray[$i] ?? '';
                $ulangan01 = $ulangan01Array[$i] ?? '';
                $ulangan02 = $ulangan02Array[$i] ?? '';
                $ulangan03 = $ulangan03Array[$i] ?? '';
                $ulangan04 = $ulangan04Array[$i] ?? '';
                $ulangan05 = $ulangan05Array[$i] ?? '';
                
                $hasData = !empty(trim($titikUkur)) || 
                          !empty(trim($ulangan01)) || 
                          !empty(trim($ulangan02)) || 
                          !empty(trim($ulangan03)) || 
                          !empty(trim($ulangan04)) || 
                          !empty(trim($ulangan05));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'ulangan01' => !empty($ulangan01) ? str_replace(',', '.', $ulangan01) : null,
                        'ulangan02' => !empty($ulangan02) ? str_replace(',', '.', $ulangan02) : null,
                        'ulangan03' => !empty($ulangan03) ? str_replace(',', '.', $ulangan03) : null,
                        'ulangan04' => !empty($ulangan04) ? str_replace(',', '.', $ulangan04) : null,
                        'ulangan05' => !empty($ulangan05) ? str_replace(',', '.', $ulangan05) : null,
                    ];
                    
                    DetailDepthMicrometer::create($detailData);
                    $totalDetailCount++;
                }
            }
        }
        
        \Log::info("✅ DETAIL DATA PROCESSED:", [
            'total_records' => $totalDetailCount,
            'forms_processed' => $jumlahForm
        ]);
        
        // ==================================================================
        // 3. UPDATE FIELD LAINNYA DI CALIBRATION
        // ⚠️ JANGAN UPDATE RANGE MIN/MAX, KAPASITAS, RESOLUSI!
        // ==================================================================
        $updateData = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->brandAlat ?? $calibration->brandAlat,
            'kodeAlat' => $request->kodeAlat ?? $calibration->kodeAlat,
            'typeAlat' => $request->typeAlat ?? $calibration->typeAlat,
            'NoSeri' => $request->NoSeri ?? $calibration->NoSeri,
            'pemilikAlat' => $request->pemilikAlat ?? $calibration->pemilikAlat,
              'no_po' => $request->no_po ?? $calibration->no_po,
            'tanggalMasuk' => $request->tanggalMasuk ?? $calibration->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi ?? $calibration->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $calibration->tempatKalibrasi,
            'jenisPembacaan' => $request->jenisPembacaan ?? $calibration->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT ?? $calibration->lokasiPT,
            'kode_th' => $request->kode_th ?? $calibration->kode_th,
            'kondisiAlat' => $request->kondisiAlat ?? $calibration->kondisiAlat,
            'keterangan' => $request->keterangan ?? $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1 ?? $calibration->RT_condition1,
            'RT_condition2' => $request->RT_condition2 ?? $calibration->RT_condition2,
            'RT_condition3' => $request->RT_condition3 ?? $calibration->RT_condition3,
            'RH_condition1' => $request->RH_condition1 ?? $calibration->RH_condition1,
            'RH_condition2' => $request->RH_condition2 ?? $calibration->RH_condition2,
            'RH_condition3' => $request->RH_condition3 ?? $calibration->RH_condition3,
            'calibratedBy' => $request->calibratedBy ?? $calibration->calibratedBy,
            'verifiedBy' => $request->verifiedBy ?? $calibration->verifiedBy,
            'jumlah_form' => $jumlahForm,
        ];
        
        // ⚠️ HAPUS FIELD YANG SUDAH DIPINDAHKAN KE HEAD
        unset($updateData['rangeMin']);
        unset($updateData['rangeMax']);
        unset($updateData['kapasitas']);
        unset($updateData['resolusi']);
        
        $calibration->update($updateData);
        $calibration->refresh();
        
        // ==================================================================
        // 4. FINAL SUMMARY
        // ==================================================================
        $finalHeadCount = HeadDepthMicrometer::where('calibration_id', $calibration->id)->count();
        $finalDetailCount = DetailDepthMicrometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('🎯 FINAL SUMMARY AFTER UPDATE:', [
            'total_heads' => $finalHeadCount,
            'heads_by_form' => HeadDepthMicrometer::where('calibration_id', $calibration->id)
                ->get()->groupBy('form_index')->map->count(),
            'total_details' => $finalDetailCount,
            'details_by_form' => DetailDepthMicrometer::where('calibration_id', $calibration->id)
                ->get()->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        \Log::info('🎉 updateDepthMicrometer COMPLETED SUCCESSFULLY', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateIdBaru ?? $calibration->certificate_id,
            'detail_records' => $finalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateDepthMicrometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}
    

     private function storeThermometer($request, $calibration, $certificateId, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeThermometer =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        // ==================================================================
        // FUNGSI BANTU UNTUK MENCARI NILAI DENGAN LOOPING SEMUA TAB (1-10)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10 (Prioritaskan key dengan prefix form_INDEX)
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
            }
            
            // Hanya fallback ke key tanpa prefix jika formIndex == 1
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                    $possibleKeys[] = "{$baseKey}{$suffix}";
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar, metode_kalibrasi) PER FORM
         */
        $findArrayValuePerForm = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = "{$baseKey}[{$formIndex}]";
                $possibleKeys[] = "{$baseKey}.{$formIndex}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}_tab{$tab}";
                    $possibleKeys[] = $baseKey;
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return implode(' ', array_filter($value));
                    }
                    if (is_string($value)) {
                        return trim($value);
                    }
                    return $value;
                }
            }
            
            return '';
        };
        
        /**
         * Mencari nilai numerik (range min, range max, kapasitas, resolusi)
         */
        $findNumericValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}_tab{$tab}";
                    $possibleKeys[] = $baseKey;
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found numeric value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai satuan suhu dengan looping tab 1-10 (TANPA DEFAULT)
         */
        $findSatuanSuhu = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}_tab{$tab}";
                    $possibleKeys[] = $baseKey;
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found {$baseKey} for form {$formIndex} using key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        // ==================================================================
        // SIMPAN HEAD untuk SETIAP FORM (masing-masing form punya data sendiri)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            
            // ==============================================================
            // AMBIL ALAT STANDAR PER FORM
            // ==============================================================
            $standardValue = $findArrayValuePerForm('alat_standar', $formIndex);
            
            // ==============================================================
            // AMBIL METODE KALIBRASI PER FORM
            // ==============================================================
            $metodeKalibrasiValue = $findArrayValuePerForm('metode_kalibrasi', $formIndex);
            
            // ==============================================================
            // AMBIL RENTANG UKUR MIN, MAX, KAPASITAS, RESOLUSI PER FORM
            // ==============================================================
            $rangeMin = $findNumericValue('rentang_ukur_min', $formIndex);
            if ($rangeMin === null || $rangeMin === '') {
                $rangeMin = $findNumericValue('range_min', $formIndex);
            }
            
            $rangeMax = $findNumericValue('rentang_ukur_max', $formIndex);
            if ($rangeMax === null || $rangeMax === '') {
                $rangeMax = $findNumericValue('range_max', $formIndex);
            }
            
            $kapasitas = $findNumericValue('kapasitas', $formIndex);
            if ($kapasitas === null || $kapasitas === '') {
                $kapasitas = $findNumericValue('kapasitas_ukur', $formIndex);
            }
            
            $resolusi = $findNumericValue('resolusi', $formIndex);
            if ($resolusi === null || $resolusi === '') {
                $resolusi = $findNumericValue('resolusi_ukur', $formIndex);
            }
            
            // ==============================================================
            // AMBIL KETERANGAN FUNGSI KOMPONEN PER FORM
            // ==============================================================
            $keteranganFungsiKomponen = $findValue('keterangan_fungsi_komponen', $formIndex);
            if ($keteranganFungsiKomponen === null || $keteranganFungsiKomponen === '') {
                $keteranganFungsiKomponen = $request->input("form_{$formIndex}_keterangan_fungsi_komponen_{$formIndex}_tab1") 
                    ?? $request->input("keterangan_fungsi_komponen_{$formIndex}_tab1")
                    ?? $request->input("keterangan_fungsi_komponen_{$formIndex}")
                    ?? $request->input("keterangan_fungsi_komponen.{$formIndex}");
            }
            
            // ==============================================================
            // AMBIL SATUAN SUHU PER FORM
            // ==============================================================
            $satuanSuhuKiri = $findSatuanSuhu('satuan_suhu_kiri', $formIndex);
            if (empty($satuanSuhuKiri)) {
                $satuanSuhuKiri = $findSatuanSuhu('satuan_suhu', $formIndex);
            }
            
            $satuanSuhuKanan = $findSatuanSuhu('satuan_suhu_kanan', $formIndex);
            if (empty($satuanSuhuKanan)) {
                $satuanSuhuKanan = $findSatuanSuhu('satuan_suhu', $formIndex);
            }
            
            // ==============================================================
            // LOG UNTUK DEBUG
            // ==============================================================
            \Log::info("📝 Saving head for form {$formIndex}", [
                'standard' => $standardValue,
                'calibrationMethod' => $metodeKalibrasiValue,
                'range_min' => $rangeMin,
                'range_max' => $rangeMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                'satuan_suhu_kiri' => $satuanSuhuKiri,
                'satuan_suhu_kanan' => $satuanSuhuKanan,
                'certificate_id' => $certificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
            ]);
            
            // ==============================================================
            // SIMPAN HEAD KE DATABASE
            // ==============================================================
            HeadThermometer::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard' => $standardValue,
                    'calibrationMethod' => $metodeKalibrasiValue,
                    'rentang_ukur_min' => $rangeMin,
                    'rentang_ukur_max' => $rangeMax,
                    'kapasitas' => $kapasitas,
                    'resolusi' => $resolusi,
                    'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                    'satuan_suhu_kiri' => $satuanSuhuKiri,
                    'satuan_suhu_kanan' => $satuanSuhuKanan,
                    'certificate_id' => $certificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
        }
        
        // ==================================================================
        // SIMPAN DETAIL UNTUK SETIAP FORM
        // ==================================================================
        // Hapus detail lama untuk calibration me (mencegah duplikasi)
        DetailThermometer::where('calibration_id', $calibration->id)->delete();
        $totalDetailsSaved = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            for ($row = 1; $row <= 36; $row += 3) {
                // Cari nilai setting suhu (titik ukur)
                $titikUkur = $findValue('setting_suhu', $formIndex, [$row]);
                if ($titikUkur === null || $titikUkur === '') {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                if ($titikUkur === null || $titikUkur === '') {
                    $titikUkur = $findValue('suhu', $formIndex, [$row]);
                }
                
                // Ambil 3 nilai STD dan 3 nilai UUT
                $stdValues = [];
                $uutValues = [];
                $hasAnyValue = ($titikUkur !== null && $titikUkur !== '');
                
                for ($offset = 0; $offset < 3; $offset++) {
                    $currentRow = $row + $offset;
                    
                    // Cari nilai STD
                    $stdValue = $findValue('std', $formIndex, [$currentRow]);
                    if ($stdValue === null || $stdValue === '') {
                        $stdValue = $findValue('standard', $formIndex, [$currentRow]);
                    }
                    
                    // Cari nilai UUT
                    $uutValue = $findValue('uut', $formIndex, [$currentRow]);
                    if ($uutValue === null || $uutValue === '') {
                        $uutValue = $findValue('unit', $formIndex, [$currentRow]);
                    }
                    
                    if ($stdValue !== null && $stdValue !== '') {
                        $hasAnyValue = true;
                    }
                    if ($uutValue !== null && $uutValue !== '') {
                        $hasAnyValue = true;
                    }
                    
                    $stdValues[] = ($stdValue !== null && $stdValue !== '') ? $stdValue : null;
                    $uutValues[] = ($uutValue !== null && $uutValue !== '') ? $uutValue : null;
                }
                
                // Jika tidak ada data sama sekali (baik titikUkur, STD, maupun UUT), skip
                if (!$hasAnyValue) {
                    continue;
                }
                
                $detailData = [
                    'STD01' => $stdValues[0],
                    'STD02' => $stdValues[1],
                    'STD03' => $stdValues[2],
                    'UUT01' => $uutValues[0],
                    'UUT02' => $uutValues[1],
                    'UUT03' => $uutValues[2],
                ];
                
                \Log::debug("Saving detail for form {$formIndex}, row {$row}", array_merge(['titikUkur' => $titikUkur], $detailData));
                
                DetailThermometer::create(array_merge([
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'titikUkur' => (string) ($titikUkur ?? ''),
                ], $detailData));
                $totalDetailsSaved++;
            }
        }
        
        \Log::info("✅ Saved {$totalDetailsSaved} detail measurements for Thermometer");
        
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        \Log::info('✅ storeThermometer completed successfully');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeThermometer FAILED:', [
            'message' => $e->getMessage(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
  /**
 * Update Thermometer data (Multiple Form Support)
 */
private function updateThermometer($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateThermometer =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head form 1 untuk cek certificate_id
        $form1Head = HeadThermometer::where('calibration_id', $calibration->id)
            ->where('form_index', 1)
            ->first();
        
        $currentCertificateId = $form1Head->certificate_id ?? null;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Thermometer - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'certificate_id_akan_dipakai' => $certificateIdBaru ?? $currentCertificateId
        ]);

        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                    $possibleKeys[] = "{$baseKey}{$suffix}";
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar, metode_kalibrasi) PER FORM
         */
        $findArrayValuePerForm = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = "{$baseKey}[{$formIndex}]";
                $possibleKeys[] = "{$baseKey}.{$formIndex}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}_tab{$tab}";
                    $possibleKeys[] = $baseKey;
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return implode(' ', array_filter($value));
                    }
                    if (is_string($value)) {
                        return trim($value);
                    }
                    return $value;
                }
            }
            
            return '';
        };
        
        /**
         * Mencari nilai numerik (range min, range max, kapasitas, resolusi)
         */
        $findNumericValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}_tab{$tab}";
                    $possibleKeys[] = $baseKey;
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found numeric value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai satuan suhu dengan looping tab 1-10 (TANPA DEFAULT)
         */
        $findSatuanSuhu = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "form_{$formIndex}_form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
            }
            
            if ($formIndex == 1) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "{$baseKey}_tab{$tab}";
                    $possibleKeys[] = $baseKey;
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found satuan suhu for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadThermometer::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // ==============================================================
            // AMBIL RENTANG UKUR MIN, MAX, KAPASITAS, RESOLUSI PER FORM
            // ==============================================================
            $rangeMin = $findNumericValue('rentang_ukur_min', $formIndex);
            if ($rangeMin === null || $rangeMin === '') {
                $rangeMin = $findNumericValue('range_min', $formIndex);
            }
            
            $rangeMax = $findNumericValue('rentang_ukur_max', $formIndex);
            if ($rangeMax === null || $rangeMax === '') {
                $rangeMax = $findNumericValue('range_max', $formIndex);
            }
            
            $kapasitas = $findNumericValue('kapasitas', $formIndex);
            if ($kapasitas === null || $kapasitas === '') {
                $kapasitas = $findNumericValue('kapasitas_ukur', $formIndex);
            }
            
            $resolusi = $findNumericValue('resolusi', $formIndex);
            if ($resolusi === null || $resolusi === '') {
                $resolusi = $findNumericValue('resolusi_ukur', $formIndex);
            }
            
            // AMBIL KETERANGAN FUNGSI KOMPONEN PER FORM
            $keteranganFungsiKomponen = $findValue('keterangan_fungsi_komponen', $formIndex);
            if ($keteranganFungsiKomponen === null || $keteranganFungsiKomponen === '') {
                $keteranganFungsiKomponen = $request->input("form_{$formIndex}_keterangan_fungsi_komponen_{$formIndex}_tab1") 
                    ?? $request->input("keterangan_fungsi_komponen_{$formIndex}_tab1")
                    ?? $request->input("keterangan_fungsi_komponen_{$formIndex}")
                    ?? $request->input("keterangan_fungsi_komponen.{$formIndex}");
            }
            
            $satuanSuhuKiri = $findSatuanSuhu('satuan_suhu_kiri', $formIndex) ?? '°C';
            $satuanSuhuKanan = $findSatuanSuhu('satuan_suhu_kanan', $formIndex) ?? '°C';
            
            $headData = [
                'rentang_ukur_min' => $rangeMin,
                'rentang_ukur_max' => $rangeMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'satuan_suhu_kiri' => $satuanSuhuKiri,
                'satuan_suhu_kanan' => $satuanSuhuKanan,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen, 
            ];
            
            // Alat standar dan metode kalibrasi untuk form 1   
            if ($formIndex == 1) {
                $alatStandar = $findArrayValuePerForm('alat_standar', 1) ?: $request->input('alat_standar', []);
                if (is_array($alatStandar)) {
                    $headData['standard'] = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
                } else {
                    $headData['standard'] = $alatStandar ?? '';
                }
                
                $metodeKalibrasi = $findArrayValuePerForm('metode_kalibrasi', 1) ?: $request->input('metode_kalibrasi', []);
                if (is_array($metodeKalibrasi)) {
                    $headData['calibrationMethod'] = !empty($metodeKalibrasi) ? implode(', ', $metodeKalibrasi) : '';
                } else {
                    $headData['calibrationMethod'] = $metodeKalibrasi ?? '';
                }
            }
            
            // UPDATE CERTIFICATE ID DI HEAD (bukan di calibration)
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'range_min' => $rangeMin,
                    'range_max' => $rangeMax,
                    'kapasitas' => $kapasitas,
                    'resolusi' => $resolusi,
                    'certificate_id' => $head->certificate_id,
                    'satuan_suhu_kiri' => $satuanSuhuKiri,
                    'satuan_suhu_kanan' => $satuanSuhuKanan,
                    'keterangan_fungsi_komponen' => $keteranganFungsiKomponen, 
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                if (empty($headData['certificate_id'])) {
                    $headData['certificate_id'] = $certificateIdBaru ?? $currentCertificateId ?? 'NEW-' . time();
                }
                $head = HeadThermometer::create($headData);
                \Log::info("➕ New head created for form {$formIndex}", [
                    'head_id' => $head->id,
                    'range_min' => $rangeMin,
                    'range_max' => $rangeMax,
                    'kapasitas' => $kapasitas,
                    'resolusi' => $resolusi,
                    'keterangan_fungsi_komponen' => $keteranganFungsiKomponen, 
                    'certificate_id' => $head->certificate_id
                ]);
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadThermometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS
        // ==================================================================
        // Hapus detail lama untuk calibration ini (mencegah duplikasi)
        DetailThermometer::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Process details using 3-row grouping
            for ($row = 1; $row <= 36; $row += 3) {
                $titikUkur = $findValue('setting_suhu', $formIndex, [$row]);
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('titik_ukur', $formIndex, [$row]);
                }
                if (empty($titikUkur)) {
                    $titikUkur = $findValue('suhu', $formIndex, [$row]);
                }
                
                if (empty($titikUkur) && $titikUkur !== '0') {
                    // Check if std or uut exist for row, row+1, row+2
                    $hasAny = false;
                    for ($off = 0; $off < 3; $off++) {
                        $s = $findValue('std', $formIndex, [$row + $off]);
                        $u = $findValue('uut', $formIndex, [$row + $off]);
                        if (!empty($s) || !empty($u)) { $hasAny = true; break; }
                    }
                    if (!$hasAny) continue;
                }
                
                $stdValues = [];
                $uutValues = [];
                for ($offset = 0; $offset < 3; $offset++) {
                    $currentRow = $row + $offset;
                    $stdVal = $findValue('std', $formIndex, [$currentRow]) ?? $request->input("std_{$formIndex}_{$currentRow}");
                    $uutVal = $findValue('uut', $formIndex, [$currentRow]) ?? $request->input("uut_{$formIndex}_{$currentRow}");
                    
                    $stdValues[] = ($stdVal !== null && $stdVal !== '') ? $stdVal : null;
                    $uutValues[] = ($uutVal !== null && $uutVal !== '') ? $uutVal : null;
                }
                
                DetailThermometer::create([
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'titikUkur' => (string) ($titikUkur ?? ''),
                    'STD01' => $stdValues[0],
                    'STD02' => $stdValues[1],
                    'STD03' => $stdValues[2],
                    'UUT01' => $uutValues[0],
                    'UUT02' => $uutValues[1],
                    'UUT03' => $uutValues[2],
                ]);
                $totalDetailCount++;
            }
        }
        
        // ==================================================================
        // 3. UPDATE CALIBRATION BASIC DATA (TANPA CERTIFICATE ID)
        // ==================================================================
        $calibrationUpdate = [];
        
        if ($request->filled('namaAlat')) {
            $calibrationUpdate['namaAlat'] = $request->namaAlat;
        }
        
        if ($request->filled('brandAlat')) {
            $calibrationUpdate['brandAlat'] = $request->brandAlat;
        }
        
        if ($request->filled('kodeAlat')) {
            $calibrationUpdate['kodeAlat'] = $request->kodeAlat;
        }
        
        if ($request->filled('typeAlat')) {
            $calibrationUpdate['typeAlat'] = $request->typeAlat;
        }
        
        if ($request->filled('NoSeri')) {
            $calibrationUpdate['NoSeri'] = $request->NoSeri;
        }
        
        if ($request->filled('pemilikAlat')) {
            $calibrationUpdate['pemilikAlat'] = $request->pemilikAlat;
        }
        
         if ($request->filled('no_po')) {
            $calibrationUpdate['no_po'] = $request->no_po;
        }
        
        if ($request->filled('tanggalMasuk')) {
            $calibrationUpdate['tanggalMasuk'] = $request->tanggalMasuk;
        }
        
        if ($request->filled('tanggalKalibrasi')) {
            $calibrationUpdate['tanggalKalibrasi'] = $request->tanggalKalibrasi;
        }
        
        if ($request->filled('jenisPembacaan')) {
            $calibrationUpdate['jenisPembacaan'] = $request->jenisPembacaan;
        }
        
        if ($request->filled('tempatKalibrasi')) {
            $calibrationUpdate['tempatKalibrasi'] = $request->tempatKalibrasi;
        }
        
        if ($request->filled('lokasiPT')) {
            $calibrationUpdate['lokasiPT'] = $request->lokasiPT;
        }
        
        if ($request->filled('kondisiAlat')) {
            $calibrationUpdate['kondisiAlat'] = $request->kondisiAlat;
        }
        
        if ($request->filled('keterangan')) {
            $calibrationUpdate['keterangan'] = $request->keterangan;
        }
        
        if ($request->filled('RT_condition1')) {
            $calibrationUpdate['RT_condition1'] = $request->RT_condition1;
            $calibrationUpdate['RT_condition2'] = $request->RT_condition2;
            $calibrationUpdate['RT_condition3'] = $request->RT_condition3;
        }
        
        if ($request->filled('RH_condition1')) {
            $calibrationUpdate['RH_condition1'] = $request->RH_condition1;
            $calibrationUpdate['RH_condition2'] = $request->RH_condition2;
            $calibrationUpdate['RH_condition3'] = $request->RH_condition3;
        }
        
         $calibratedByInput = $findValue('calibratedBy', 1) 
            ?? $findValue('calibrated_by', 1) 
            ?? $request->input('calibratedBy_1') 
            ?? $request->input('calibratedBy') 
            ?? $request->input('calibrated_by');
            
        if (!empty($calibratedByInput)) {
            $calibrationUpdate['calibratedBy'] = $calibratedByInput;
        }
        
        $verifiedByInput = $findValue('verifiedBy', 1) 
            ?? $findValue('verified_by', 1) 
            ?? $request->input('verifiedBy_1') 
            ?? $request->input('verifiedBy') 
            ?? $request->input('verified_by');
            
        if (!empty($verifiedByInput)) {
            $calibrationUpdate['verifiedBy'] = $verifiedByInput;
        }
        
        // NOTE: rangeMin, rangeMax, kapasitas, resolusi TIDAK disimpan di calibration
        // karena sudah disimpan di HeadThermometer per form
        
        // KOSONGKAN certificate_id di calibration (biar null, tidak dipakai)
        // Certificate ID hanya disimpan di HEAD saja
        $calibrationUpdate['certificate_id'] = null;
        $calibrationUpdate['jumlah_form'] = $jumlahForm;
        
        if (!empty($calibrationUpdate)) {
            $calibration->update($calibrationUpdate);
            $calibration->refresh();
            \Log::info('✅ CALIBRATION DATA UPDATED (tanpa certificate_id, tanpa range/resolusi)', $calibrationUpdate);
        }
        
        // ==================================================================
        // 4. FINAL VERIFICATION
        // ==================================================================
        $finalDetails = DetailThermometer::where('calibration_id', $calibration->id)
            ->orderBy('id')
            ->get();
        
        $finalHeads = HeadThermometer::where('calibration_id', $calibration->id)
            ->orderBy('form_index')
            ->get();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_count' => $finalHeads->count(),
            'details_count' => $finalDetails->count(),
            'certificate_id_calibration' => $calibration->certificate_id, // Harusnya null
            'certificate_id_heads' => $finalHeads->pluck('certificate_id')->toArray(),
            'range_data_heads' => $finalHeads->map(function($head) {
                return [
                    'form_index' => $head->form_index,
                    'rentang_ukur_min' => $head->rentang_ukur_min,
                    'rentang_ukur_max' => $head->rentang_ukur_max,
                    'kapasitas' => $head->kapasitas,
                    'resolusi' => $head->resolusi,
                ];
            })->toArray()
        ]);
        
        \Log::info('🎉 updateThermometer COMPLETED', [
            'calibration_id' => $calibration->id,
            'details_saved' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_head_form1' => $finalHeads->where('form_index', 1)->first()->certificate_id ?? 'TIDAK ADA'
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateThermometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
    
    
    // Helper function untuk clean value
    private function cleanValue($value)
    {
        if (is_null($value) || $value === '' || $value === 'null') {
            return null;
        }
        return $value;
    }

      private function storeDialIndicator($request, $calibration, $certificateId)
{
    try {
        \Log::info('START storeDialIndicator');
        
        // ==================================================================
        // DEBUG DETAILED
        // ==================================================================
        \Log::info('📋 ALL REQUEST DATA for dial indicator:', [
            'alat_standar' => $request->alat_standar,
            'alat_standar_tambahan' => $request->alat_standar_tambahan,
            'alat_standar_count' => is_array($request->alat_standar) ? count($request->alat_standar) : 0,
            'skala' => $request->skala,
            'repeability' => $request->repeability,
            'penunjukanAlat_count' => is_array($request->penunjukanAlat) ? count($request->penunjukanAlat) : 0
        ]);

        // ==================================================================
        // 1. AMBIL & SIMPAN SKALAf
        // ==================================================================
        $skala = $request->skala;
        if (!$skala || !in_array($skala, ['0.001', '0.01'])) {
            $skala = '0.01';
        }
        $calibration->update(['skala' => $skala]);
        $is001 = $skala === '0.001';
        \Log::info('Skala tersimpan', ['skala' => $skala, 'is001' => $is001]);

        // ==================================================================
        // 2. PROSES ALAT STANDAR - DENGAN FILTER YANG BENAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarTambahan = $request->alat_standar_tambahan ?? '';

        \Log::info('🔧 Processing alat standar:', [
            'alatStandar_raw' => $alatStandar,
            'alatStandarTambahan' => $alatStandarTambahan
        ]);

        $standardParts = [];
        
        if (is_array($alatStandar)) {
            foreach ($alatStandar as $index => $alat) {
                \Log::info("   - Item {$index}: '{$alat}' (length: " . strlen($alat) . ")");
                
                // FILTER 1: Skip jika kosong atau hanya whitespace
                if (trim($alat) === '') {
                    \Log::info("     -> SKIP: Empty string");
                    continue;
                }
                
                // FILTER 2: Untuk 'alat_standar_lainnya', gunakan value dari input tambahan
                if ($alat === 'alat_standar_lainnya') {
                    if (!empty(trim($alatStandarTambahan))) {
                        \Log::info("     -> ADD: 'alat_standar_lainnya' -> '{$alatStandarTambahan}'");
                        $standardParts[] = trim($alatStandarTambahan);
                    } else {
                        \Log::info("     -> SKIP: 'alat_standar_lainnya' but alat_standar_tambahan is empty");
                    }
                } 
                // FILTER 3: Untuk value lainnya, langsung tambahkan
                else {
                    \Log::info("     -> ADD: '{$alat}'");
                    $standardParts[] = trim($alat);
                }
            }
        }
        
        // FILTER 4: Jika ada input tambahan yang belum masuk
        if (!empty(trim($alatStandarTambahan))) {
            $alreadyExists = false;
            foreach ($standardParts as $part) {
                if ($part === trim($alatStandarTambahan)) {
                    $alreadyExists = true;
                    break;
                }
            }
            if (!$alreadyExists) {
                \Log::info("   - Adding alat_standar_tambahan yang belum terdaftar: '{$alatStandarTambahan}'");
                $standardParts[] = trim($alatStandarTambahan);
            }
        }

        // Pastikan tidak ada duplikat
        $standardParts = array_unique($standardParts);
        $standardValue = !empty($standardParts) ? implode(', ', $standardParts) : 'Tidak ada alat standar';
        
        \Log::info('📝 Standard value final:', ['standardValue' => $standardValue]);

        HeadDialIndicator::create([
            'calibration_id'    => $calibration->id,
            'certificate_id'    => $certificateId,
            'standard'          => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-03 (JIS B 7503:2017 (JMA/JSA); SNSU PK.P-03:2020).',
            'satuan_alat_kiri'          => $request->satuan_alat_kiri ?? null,
            'satuan_alat_kanan'          => $request->satuan_alat_kanan ?? null,
        ]);

        \Log::info('✅ HeadDialIndicator created');

        // ==================================================================
        // 3. SIMPAN REPEATABILITY
        // ==================================================================
        AddDialIndicator::create([
            'calibration_id' => $calibration->id,
            'repeatability'    => $request->repeatability ?? null,
            'ulangan01'      => $request->ulangan01 ?? null,
            'ulangan02'      => $request->ulangan02 ?? null,
            'ulangan03'      => $request->ulangan03 ?? null,
            'ulangan04'      => $request->ulangan04 ?? null,
            'ulangan05'      => $request->ulangan05 ?? null,
            'ulangan06'      => $request->ulangan06 ?? null,
            'ulangan07'      => $request->ulangan07 ?? null,
            'ulangan08'      => $request->ulangan08 ?? null,
            'ulangan09'      => $request->ulangan09 ?? null,
            'ulangan10'      => $request->ulangan10 ?? null,
        ]);

        \Log::info('✅ AddDialIndicator created');

        // ==================================================================
        // 4. SIMPAN DETAIL KALIBRASI
        // ==================================================================
        $penunjukanAlat = $request->penunjukanAlat ?? [];
        $pembacaanNaik  = $request->pembacaanNaik ?? [];
        $pembacaanTurun = $request->pembacaanTurun ?? [];

        \Log::info('📊 Jumlah baris diterima', [
            'penunjukanAlat' => count($penunjukanAlat),
            'pembacaanNaik'  => count($pembacaanNaik),
            'pembacaanTurun' => count($pembacaanTurun),
        ]);

        $detailCount = 0;
        $savedDetails = [];

        foreach ($penunjukanAlat as $i => $titikRaw) {
            $titik = trim($titikRaw ?? '');
            $naik = $pembacaanNaik[$i] ?? '';
            $turun = $pembacaanTurun[$i] ?? '';
            
            // Skip jika semua kolom kosong
            if ($titik === '' && $naik === '' && $turun === '') {
                continue;
            }
        
            $detail = DetailDialIndicator::create([
                'calibration_id' => $calibration->id,
                'titikUkur'      => $titik !== '' ? $titik : null,
                'ulanganNaik'    => $naik !== '' ? $naik : null,
                'ulanganTurun'   => $turun !== '' ? $turun : null,
            ]);
            
            $detailCount++;
            $savedDetails[] = [
                'titik' => $titik,
                'naik' => $naik,
                'turun' => $turun
            ];
        }

        \Log::info('✅ DetailDialIndicator berhasil disimpan', [
            'total_records' => $detailCount,
            'skala'         => $skala,
            'first_5_records' => array_slice($savedDetails, 0, 5)
        ]);

        \Log::info('🎯 storeDialIndicator SELESAI');

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeDialIndicator', [
            'message' => $e->getMessage(),
            'file'    => $e->getFile(),
            'line'    => $e->getLine(),
            'trace'   => $e->getTraceAsString()
        ]);
        throw $e;
    }
}


    /**
 * Update Thermometer data (Multiple Form Support)
 */
private function updateDialIndicator($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateDialIndicator =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head dial indicator untuk cek certificate_id
        $headDialIndicator = $calibration->headDialIndicator;
        
        // Jika head tidak ada, buat baru
        if (!$headDialIndicator) {
            $headDialIndicator = HeadDialIndicator::create([
                'calibration_id' => $calibration->id,
            ]);
            \Log::info('➕ New HeadDialIndicator created for certificate update');
        }
        
        $currentCertificateId = $headDialIndicator->certificate_id ?? null;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah (gunakan nama asli dari database sebelum diupdate)
        // Kita perlu ambil nama alat asli dari database karena $calibration->namaAlat sudah berubah
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ASLI DARI DATABASE:', [
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'request_nama_alat' => $namaAlatDariRequest
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE ALAT STANDAR (HEAD DIAL INDICATOR)
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = '';
        
        \Log::info('🔧 Update data:', [
            'alat_standar' => $alatStandar,
            'alat_standar_tambahan' => $request->alat_standar_tambahan
        ]);
        
        // Process alat standar
        $processedAlat = [];
        foreach ($alatStandar as $alat) {
            if ($alat === 'dial_gauge_tester_0_25mm') {
                $processedAlat[] = 'Dial Gauge Tester 0~25 mm';
            } 
            elseif ($alat === 'dial_calibration_tester_0_1mm') {
                $processedAlat[] = 'Dial Calibration Tester 0~1 mm';
            }
            elseif ($alat === 'electronic_gauge_tester_0_50mm') {
                $processedAlat[] = 'Electronic Gauge Tester 0~50 mm';
            }
            elseif ($alat === 'alat_standar_lainnya' && $request->filled('alat_standar_tambahan')) {
                $processedAlat[] = $request->alat_standar_tambahan;
            }
        }
        
        $alatStandarString = !empty($processedAlat) ? implode(', ', $processedAlat) : '';
        
        // Prepare update data
        $updateData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-03 (JIS B 7503:2017 (JMA/JSA); SNSU PK.P-03:2020)',
        ];
        
        // Tambahkan satuan kiri dan kanan jika ada
        if ($request->has('satuan_alat_kiri')) {
            $updateData['satuan_alat_kiri'] = $request->satuan_alat_kiri;
        }
        
        if ($request->has('satuan_alat_kanan')) {
            $updateData['satuan_alat_kanan'] = $request->satuan_alat_kanan;
        }
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $updateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        // Update head
        $headDialIndicator->update($updateData);
        
        // Refresh untuk mendapatkan data terbaru
        $headDialIndicator->refresh();
        
        \Log::info('✅ HeadDialIndicator updated:', [
            'certificate_id' => $headDialIndicator->certificate_id,
            'standard' => $alatStandarString
        ]);
        
        // ==================================================================
        // 2. UPDATE ADD DIAL INDICATOR (untuk repeatability dan ulangan 01-10)
        // ==================================================================
        // Cek apakah AddDialIndicator sudah ada
        if ($add = $calibration->addDialIndicator) {
            // Update existing
            $addUpdateData = [];
            
            // Update repeatability jika ada
            if ($request->filled('repeatability')) {
                $repeatValue = $this->formatRepeatability($request->repeatability);
                if (!is_null($repeatValue)) {
                    $addUpdateData['repeatability'] = $repeatValue;
                    \Log::info('✅ Repeatability formatted:', [
                        'original' => $request->repeatability,
                        'formatted' => $repeatValue
                    ]);
                }
            }
            
            // Update ulangan 01-10 jika ada
            for ($i = 1; $i <= 10; $i++) {
                $fieldName = ($i < 10) ? 'ulangan0' . $i : 'ulangan' . $i;
                if ($request->filled($fieldName)) {
                    $addUpdateData[$fieldName] = $this->formatNumericValue($request->$fieldName);
                    \Log::debug("📝 {$fieldName} to update:", ['value' => $addUpdateData[$fieldName]]);
                }
            }
            
            // Update jika ada data
            if (!empty($addUpdateData)) {
                $add->update($addUpdateData);
                \Log::info('✅ AddDialIndicator updated. Fields:', array_keys($addUpdateData));
            } else {
                \Log::info('ℹ️ No data to update in AddDialIndicator');
            }
            
        } else {
            // Create new AddDialIndicator jika belum ada
            $addData = [
                'calibration_id' => $calibration->id,
            ];
            
            // Tambahkan repeatability jika ada
            if ($request->filled('repeatability')) {
                $addData['repeatability'] = $this->formatNumericValue($request->repeatability);
                \Log::info('📝 Repeatability to create:', ['value' => $addData['repeatability']]);
            }
            
            // Tambahkan ulangan 01-10 jika ada
            for ($i = 1; $i <= 10; $i++) {
                $fieldName = ($i < 10) ? 'ulangan0' . $i : 'ulangan' . $i;
                if ($request->filled($fieldName)) {
                    $addData[$fieldName] = $this->formatNumericValue($request->$fieldName);
                    \Log::debug("📝 {$fieldName} to create:", ['value' => $addData[$fieldName]]);
                }
            }
            
            // Hanya create jika ada data (tidak hanya calibration_id)
            if (count($addData) > 1) {
                $add = AddDialIndicator::create($addData);
                \Log::info('➕ NEW AddDialIndicator created:', [
                    'add_id' => $add->id,
                    'fields_saved' => array_keys($addData)
                ]);
            } else {
                \Log::info('ℹ️ No AddDialIndicator data to create');
            }
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS (titikUkur, ulanganNaik, ulanganTurun)
        // ==================================================================
        // Hapus data detail lama
        $deletedCount = DetailDialIndicator::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Old DetailDialIndicator deleted:', ['deleted_count' => $deletedCount]);
        
        // **LOG DATA REQUEST**
        \Log::info('📊 Request data count:', [
            'titikUkur_kiri' => count($request->titikUkur_kiri ?? []),
            'ulanganNaik_kiri' => count($request->ulanganNaik_kiri ?? []),
            'ulanganTurun_kiri' => count($request->ulanganTurun_kiri ?? []),
            'titikUkur_kanan' => count($request->titikUkur_kanan ?? []),
            'ulanganNaik_kanan' => count($request->ulanganNaik_kanan ?? []),
            'ulanganTurun_kanan' => count($request->ulanganTurun_kanan ?? []),
        ]);
        
        $detailCount = 0;
        $savedData = [];
        
        // 1. Simpan data KIRI dulu
        if (is_array($request->titikUkur_kiri) && count($request->titikUkur_kiri) > 0) {
            foreach ($request->titikUkur_kiri as $index => $titikUkur) {
                // Skip jika null atau empty string (kecuali '0')
                if (($titikUkur === null || $titikUkur === '') && $titikUkur !== '0') {
                    \Log::debug("⏭️ Skipping KIRI index {$index}: titikUkur is empty");
                    continue;
                }
                
                $ulanganNaik = $request->ulanganNaik_kiri[$index] ?? null;
                $ulanganTurun = $request->ulanganTurun_kiri[$index] ?? null;
                
                // Format nilai
                $formattedTitikUkur = $this->formatNumericValue($titikUkur);
                $formattedNaik = $this->formatNumericValue($ulanganNaik);
                $formattedTurun = $this->formatNumericValue($ulanganTurun);
                
                // Simpan data kiri
                try {
                    DetailDialIndicator::create([
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ]);
                    
                    $detailCount++;
                    $savedData[] = [
                        'type' => 'kiri',
                        'index' => $index,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ];
                    
                    \Log::debug("✅ Saved KIRI index {$index}", [
                        'titikUkur' => $formattedTitikUkur,
                        'naik' => $formattedNaik,
                        'turun' => $formattedTurun
                    ]);
                    
                } catch (\Exception $e) {
                    \Log::error("❌ Error saving KIRI index {$index}: " . $e->getMessage());
                }
            }
        }
        
        // 2. Simpan data KANAN setelah kiri
        if (is_array($request->titikUkur_kanan) && count($request->titikUkur_kanan) > 0) {
            foreach ($request->titikUkur_kanan as $index => $titikUkur) {
                // Skip jika null atau empty string (kecuali '0')
                if (($titikUkur === null || $titikUkur === '') && $titikUkur !== '0') {
                    \Log::debug("⏭️ Skipping KANAN index {$index}: titikUkur is empty");
                    continue;
                }
                
                $ulanganNaik = $request->ulanganNaik_kanan[$index] ?? null;
                $ulanganTurun = $request->ulanganTurun_kanan[$index] ?? null;
                
                // Format nilai
                $formattedTitikUkur = $this->formatNumericValue($titikUkur);
                $formattedNaik = $this->formatNumericValue($ulanganNaik);
                $formattedTurun = $this->formatNumericValue($ulanganTurun);
                
                // Simpan data kanan
                try {
                    DetailDialIndicator::create([
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ]);
                    
                    $detailCount++;
                    $savedData[] = [
                        'type' => 'kanan',
                        'index' => $index,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ];
                    
                    \Log::debug("✅ Saved KANAN index {$index}", [
                        'titikUkur' => $formattedTitikUkur,
                        'naik' => $formattedNaik,
                        'turun' => $formattedTurun
                    ]);
                    
                } catch (\Exception $e) {
                    \Log::error("❌ Error saving KANAN index {$index}: " . $e->getMessage());
                }
            }
        }
        
        \Log::info('✅ DetailDialIndicator updated:', [
            'total_records' => $detailCount,
            'saved_data_summary' => $savedData
        ]);
        
        // ==================================================================
        // 4. FINAL VERIFICATION
        // ==================================================================
        $finalHead = HeadDialIndicator::where('calibration_id', $calibration->id)->first();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'details_count' => $detailCount,
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru
        ]);
        
        \Log::info('🎉 updateDialIndicator COMPLETED', [
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA'
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateDialIndicator FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}
       private function formatRepeatability($value)
    {
        \Log::debug("🔢 formatRepeatability INPUT:", ['value' => $value, 'type' => gettype($value)]);
        
        if (is_null($value) || $value === '' || $value === 'null') {
            return null;
        }
        
     
        return (string) $value; // Simpan sebagai string
        
 
    }

     private function storeDialTestIndicator($request, $calibration, $certificateId)
    {
        try {
            \Log::info('START storeDialTestIndicator');
    
            // ==================================================================
            // 1. AMBIL & SIMPAN SKALA (WAJIB!)
            // ==================================================================
            $skala = $request->skala; // '0.001' atau '0.01' dari hidden input
            if (!$skala || !in_array($skala, ['0.001', '0.01'])) {
                $skala = '0.01'; // fallback kalau kosong
            }
    
            $calibration->update(['skala' => $skala]);
            $is001 = $skala === '0.001';
    
            \Log::info('Skala tersimpan', ['skala' => $skala, 'is001' => $is001]);
    
            // ==================================================================
            // 2. PROSES ALAT STANDAR (tetap sama)
            // ==================================================================
            $alatStandar         = $request->alat_standar ?? [];
            $alatStandarTambahan  = $request->alat_standar_tambahan ?? '';
    
            $standardParts = [];
            foreach ($alatStandar as $alat) {
                if ($alat !== 'alat_standar_lainnya') {
                    $standardParts[] = $alat;
                }
            }
            if (!empty($alatStandarTambahan)) {
                $standardParts[] = $alatStandarTambahan;
            }
            $standardValue = implode(', ', $standardParts);
    
            HeadDialTestIndicator::create([
                'calibration_id'    => $calibration->id,
                'certificate_id'    => $certificateId,
                'standard'          => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-07 (JIS B 7533 : 2015)',
                'satuan_alat_kiri'          => $request->satuan_alat_kiri ?? null,
                'satuan_alat_kanan'          => $request->satuan_alat_kanan ?? null,
            ]);
    
            // ==================================================================
            // 3. SIMPAN REPEATABILITY (tetap sama)
            // ==================================================================
            AddDialTestIndicator::create([
                'calibration_id' => $calibration->id,
                'repeatability'    => $request->repeatability ?? null,
                'ulangan01'      => $request->ulangan01 ?? null,
                'ulangan02'      => $request->ulangan02 ?? null,
                'ulangan03'      => $request->ulangan03 ?? null,
                'ulangan04'      => $request->ulangan04 ?? null,
                'ulangan05'      => $request->ulangan05 ?? null,
                'ulangan06'      => $request->ulangan06 ?? null,
                'ulangan07'      => $request->ulangan07 ?? null,
                'ulangan08'      => $request->ulangan08 ?? null,
                'ulangan09'      => $request->ulangan09 ?? null,
                'ulangan10'      => $request->ulangan10 ?? null,
            ]);
    
            // ==================================================================
            // 4. SIMPAN DETAIL KALIBRASI + FILTER BERDASARKAN SKALA
            // ==================================================================
            $penunjukanAlat = $request->penunjukanAlat ?? [];
            $pembacaanNaik  = $request->pembacaanNaik ?? [];
            $pembacaanTurun = $request->pembacaanTurun ?? [];
            
            \Log::info('📊 Jumlah baris diterima', [
                'penunjukanAlat' => count($penunjukanAlat),
                'pembacaanNaik'  => count($pembacaanNaik),
                'pembacaanTurun' => count($pembacaanTurun),
                'semua_penunjukan' => $penunjukanAlat, // LOG SEMUA DATA
                'semua_pembacaan_naik' => $pembacaanNaik,
                'semua_pembacaan_turun' => $pembacaanTurun,
            ]);
    
            $detailCount = 0;
    
                
            foreach ($penunjukanAlat as $i => $titikRaw) {
                $titik = trim($titikRaw ?? '');
                
                // AMBIL DATA PEMBACAAN
                $naik = $pembacaanNaik[$i] ?? '';
                $turun = $pembacaanTurun[$i] ?? '';
                
                // SKIP HANYA JIKA SEMUA KOLOM KOSONG
                if ($titik === '' && $naik === '' && $turun === '') {
                    continue;
                }
            
                // SIMPAN SEMUA DATA TANPA FILTER SKALA
                // (Dial Test Indicator mungkin butuh range yang lebih besar)
                DetailDialTestIndicator::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur'      => $titik !== '' ? $titik : null,
                    'ulanganNaik'    => $naik !== '' ? $naik : null,
                    'ulanganTurun'   => $turun !== '' ? $turun : null,
                ]);
            
                $detailCount++;
            }
            
    
            \Log::info('DetailDialTestIndicator berhasil disimpan', [
                'total_records' => $detailCount,
                'skala'         => $skala
            ]);
    
            \Log::info('storeDialTestIndicator SELESAI');
    
        } catch (\Exception $e) {
            \Log::error('ERROR storeDialTestIndicator', [
                'message' => $e->getMessage(),
                'file'    => $e->getFile(),
                'line'    => $e->getLine(),
            ]);
            throw $e;
        }
    }
    
    private function updateDialTestIndicator($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateDialTestIndicator =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head dial test indicator untuk cek certificate_id
        $headDialTestIndicator = $calibration->headDialTestIndicator;
        
        // Jika head tidak ada, buat baru
        if (!$headDialTestIndicator) {
            $headDialTestIndicator = HeadDialTestIndicator::create([
                'calibration_id' => $calibration->id,
            ]);
            \Log::info('➕ New HeadDialTestIndicator created for certificate update');
        }
        
        $currentCertificateId = $headDialTestIndicator->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE ALAT STANDAR (HEAD DIAL TEST INDICATOR)
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = '';
        
        \Log::info('🔧 Alat standar RAW data:', [
            'alat_standar' => $alatStandar,
            'alat_standar_type' => gettype($alatStandar),
            'alat_standar_count' => is_array($alatStandar) ? count($alatStandar) : 'N/A',
            'alat_standar_tambahan' => $request->alat_standar_tambahan ?? ''
        ]);
        
        // Process alat standar
        $processedAlat = [];
        
        if (is_array($alatStandar) && count($alatStandar) > 0) {
            foreach ($alatStandar as $alat) {
                $alat = trim($alat);
                
                if ($alat === 'alat_standar_lainnya') {
                    if ($request->filled('alat_standar_tambahan')) {
                        $processedAlat[] = trim($request->alat_standar_tambahan);
                    }
                } else {
                    $processedAlat[] = $alat;
                }
            }
        }
        
        // Juga tambahkan alat_standar_tambahan jika diisi manual tanpa checkbox
        if ($request->filled('alat_standar_tambahan')) {
            $tambahan = trim($request->alat_standar_tambahan);
            if (!empty($tambahan) && !in_array($tambahan, $processedAlat)) {
                $processedAlat[] = $tambahan;
            }
        }
        
        // Hapus duplikat dan empty values
        $processedAlat = array_filter(array_unique($processedAlat));
        
        $alatStandarString = !empty($processedAlat) ? implode(', ', $processedAlat) : '';
        
        \Log::info('🔧 Alat standar processed:', [
            'processedAlat' => $processedAlat,
            'alatStandarString' => $alatStandarString
        ]);
        
        // Prepare update data
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-07 (JIS B 7533 : 2015)',
        ];
        
        // Tambahkan satuan kiri dan kanan jika ada
        if ($request->has('satuan_alat_kiri') && $request->satuan_alat_kiri !== null) {
            $headData['satuan_alat_kiri'] = $request->satuan_alat_kiri;
        }
        
        if ($request->has('satuan_alat_kanan') && $request->satuan_alat_kanan !== null) {
            $headData['satuan_alat_kanan'] = $request->satuan_alat_kanan;
        }
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        \Log::info('📝 Head data to save:', $headData);
        
        // Update head
        $headDialTestIndicator->update($headData);
        
        // Refresh untuk mendapatkan data terbaru
        $headDialTestIndicator->refresh();
        
        \Log::info('✅ HeadDialTestIndicator updated:', [
            'head_id' => $headDialTestIndicator->id,
            'certificate_id' => $headDialTestIndicator->certificate_id,
            'standard' => $headDialTestIndicator->standard,
            'satuan_alat_kiri' => $headDialTestIndicator->satuan_alat_kiri,
            'satuan_alat_kanan' => $headDialTestIndicator->satuan_alat_kanan,
        ]);
        
        // ==================================================================
        // 2. UPDATE ADD DIAL TEST INDICATOR (untuk repeatability dan ulangan 01-10)
        // ==================================================================
        if ($add = $calibration->addDialTestIndicator) {
            $updateData = [];
            
            if ($request->filled('repeatability')) {
                $repeatValue = $this->formatRepeatability($request->repeatability);
                if (!is_null($repeatValue)) {
                    $updateData['repeatability'] = $repeatValue;
                    \Log::info('✅ Repeatability formatted:', [
                        'original' => $request->repeatability,
                        'formatted' => $repeatValue
                    ]);
                }
            }
            
            for ($i = 1; $i <= 10; $i++) {
                $fieldName = ($i < 10) ? 'ulangan0' . $i : 'ulangan' . $i;
                if ($request->filled($fieldName)) {
                    $updateData[$fieldName] = $this->formatNumericValue($request->$fieldName);
                    \Log::debug("📝 {$fieldName} to update:", ['value' => $updateData[$fieldName]]);
                }
            }
            
            if (!empty($updateData)) {
                $add->update($updateData);
                \Log::info('✅ AddDialTestIndicator updated. Fields:', array_keys($updateData));
            } else {
                \Log::info('ℹ️ No data to update in AddDialTestIndicator');
            }
            
        } else {
            $addData = ['calibration_id' => $calibration->id];
            
            if ($request->filled('repeatability')) {
                $addData['repeatability'] = $this->formatNumericValue($request->repeatability);
                \Log::info('📝 Repeatability to create:', ['value' => $addData['repeatability']]);
            }
            
            for ($i = 1; $i <= 10; $i++) {
                $fieldName = ($i < 10) ? 'ulangan0' . $i : 'ulangan' . $i;
                if ($request->filled($fieldName)) {
                    $addData[$fieldName] = $this->formatNumericValue($request->$fieldName);
                    \Log::debug("📝 {$fieldName} to create:", ['value' => $addData[$fieldName]]);
                }
            }
            
            if (count($addData) > 1) {
                $add = AddDialTestIndicator::create($addData);
                \Log::info('➕ NEW AddDialTestIndicator created:', [
                    'add_id' => $add->id,
                    'fields_saved' => array_keys($addData)
                ]);
            } else {
                \Log::info('ℹ️ No AddDialTestIndicator data to create');
            }
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS (titikUkur, ulanganNaik, ulanganTurun)
        // ==================================================================
        $deletedCount = DetailDialTestIndicator::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Old DetailDialTestIndicator deleted:', ['deleted_count' => $deletedCount]);
        
        \Log::info('📊 Request data count:', [
            'titikUkur_kiri' => count($request->titikUkur_kiri ?? []),
            'ulanganNaik_kiri' => count($request->ulanganNaik_kiri ?? []),
            'ulanganTurun_kiri' => count($request->ulanganTurun_kiri ?? []),
            'titikUkur_kanan' => count($request->titikUkur_kanan ?? []),
            'ulanganNaik_kanan' => count($request->ulanganNaik_kanan ?? []),
            'ulanganTurun_kanan' => count($request->ulanganTurun_kanan ?? []),
        ]);
        
        $detailCount = 0;
        $savedData = [];
        
        // Simpan data KIRI
        if (is_array($request->titikUkur_kiri) && count($request->titikUkur_kiri) > 0) {
            foreach ($request->titikUkur_kiri as $index => $titikUkur) {
                if (($titikUkur === null || $titikUkur === '') && $titikUkur !== '0') {
                    \Log::debug("⏭️ Skipping KIRI index {$index}: titikUkur is empty");
                    continue;
                }
                
                $ulanganNaik = $request->ulanganNaik_kiri[$index] ?? null;
                $ulanganTurun = $request->ulanganTurun_kiri[$index] ?? null;
                
                $formattedTitikUkur = $this->formatNumericValue($titikUkur);
                $formattedNaik = $this->formatNumericValue($ulanganNaik);
                $formattedTurun = $this->formatNumericValue($ulanganTurun);
                
                try {
                    DetailDialTestIndicator::create([
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ]);
                    
                    $detailCount++;
                    $savedData[] = [
                        'type' => 'kiri',
                        'index' => $index,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ];
                    
                    \Log::debug("✅ Saved KIRI index {$index}");
                    
                } catch (\Exception $e) {
                    \Log::error("❌ Error saving KIRI index {$index}: " . $e->getMessage());
                }
            }
        }
        
        // Simpan data KANAN
        if (is_array($request->titikUkur_kanan) && count($request->titikUkur_kanan) > 0) {
            foreach ($request->titikUkur_kanan as $index => $titikUkur) {
                if (($titikUkur === null || $titikUkur === '') && $titikUkur !== '0') {
                    \Log::debug("⏭️ Skipping KANAN index {$index}: titikUkur is empty");
                    continue;
                }
                
                $ulanganNaik = $request->ulanganNaik_kanan[$index] ?? null;
                $ulanganTurun = $request->ulanganTurun_kanan[$index] ?? null;
                
                $formattedTitikUkur = $this->formatNumericValue($titikUkur);
                $formattedNaik = $this->formatNumericValue($ulanganNaik);
                $formattedTurun = $this->formatNumericValue($ulanganTurun);
                
                try {
                    DetailDialTestIndicator::create([
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ]);
                    
                    $detailCount++;
                    $savedData[] = [
                        'type' => 'kanan',
                        'index' => $index,
                        'titikUkur' => $formattedTitikUkur,
                        'ulanganNaik' => $formattedNaik,
                        'ulanganTurun' => $formattedTurun,
                    ];
                    
                    \Log::debug("✅ Saved KANAN index {$index}");
                    
                } catch (\Exception $e) {
                    \Log::error("❌ Error saving KANAN index {$index}: " . $e->getMessage());
                }
            }
        }
        
        \Log::info('✅ DetailDialTestIndicator updated:', [
            'total_records' => $detailCount
        ]);
        
        // ==================================================================
        // 4. FINAL VERIFICATION
        // ==================================================================
        $finalHead = HeadDialTestIndicator::where('calibration_id', $calibration->id)->first();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'details_count' => $detailCount,
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru
        ]);
        
        \Log::info('🎉 updateDialTestIndicator COMPLETED', [
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA'
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateDialTestIndicator FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}

            private function storeDepthCaliper($request, $calibration, $certificateId)
        {
            try {
                \Log::info('🚀 START storeDepthCaliper');
        
                // ==================================================================
                // 1. PROSES & SIMPAN ALAT STANDAR KE HEAD
                // ==================================================================
                $alatStandar = $request->alat_standar ?? [];
                $alatStandarTambahan = $request->alat_standar_tambahan ?? '';
        
                \Log::info('🔧 Data alat standar:', [
                    'alat_standar' => $alatStandar,
                    'alat_standar_tambahan' => $alatStandarTambahan
                ]);
        
                $standardParts = [];
                foreach ($alatStandar as $alat) {
                    if ($alat !== 'alat_standar_lainnya') {
                        $standardParts[] = $alat;
                    }
                }
                
                if (!empty($alatStandarTambahan)) {
                    $standardParts[] = $alatStandarTambahan;
                }
                
                $standardValue = !empty($standardParts) ? implode(', ', $standardParts) : '';
        
                // SIMPAN KE HEAD DEPTH CALIPER
                $headData = HeadDepthCaliper::create([
                    'calibration_id' => $calibration->id,
                    'certificate_id' => $certificateId,
                    'standard' => $standardValue,
                    'calibrationMethod' => ' PAS-IK1102-11 (JIS B 7518:2023 (JMA/JSA); SNSU PK.P-02:2020)',
                    'satuan_unit' => $request->satuan_unit ?? null,
                   
                ]);
        
                \Log::info('✅ HeadDepthCaliper berhasil disimpan', [
                    'id' => $headData->id,
                    'standard' => $standardValue,
                    'calibration_id' => $calibration->id
                ]);
        
                // ==================================================================
                // 2. SIMPAN DETAIL DEPTH CALIPER
                // ==================================================================
                $titikUkur = $request->titikUkur ?? [];
                $ulangan01 = $request->ulangan01 ?? [];
                $ulangan02 = $request->ulangan02 ?? [];
                $ulangan03 = $request->ulangan03 ?? [];
                $ulangan04 = $request->ulangan04 ?? [];
                $ulangan05 = $request->ulangan05 ?? [];
                $kodeStandardKiri = $request->kodeStandardKiri ?? [];
                $kodeStandardKanan = $request->kodeStandardKanan ?? [];
        
                \Log::info('📊 Data detail diterima', [
                    'titikUkur_count' => count($titikUkur),
                    'ulangan01_count' => count($ulangan01),
                    'ulangan02_count' => count($ulangan02),
                    'ulangan03_count' => count($ulangan03),
                    'ulangan04_count' => count($ulangan04),
                    'ulangan05_count' => count($ulangan05),
                    'kodeStandardKiri_count' => count($kodeStandardKiri),
                    'kodeStandardKanan_count' => count($kodeStandardKanan),
                ]);
        
                $detailCount = 0;
                $errors = [];
        
                // Proses 12 baris data (sesuai dengan form yang memiliki 12 baris)
                $totalRows = min(12, count($titikUkur), count($ulangan01), count($ulangan02), 
                               count($ulangan03), count($ulangan04), count($ulangan05),
                               count($kodeStandardKiri), count($kodeStandardKanan));
        
                for ($i = 0; $i < $totalRows; $i++) {
                    $titikValue = trim($titikUkur[$i] ?? '');
                    $ulangan01Value = $ulangan01[$i] ?? null;
                    $ulangan02Value = $ulangan02[$i] ?? null;
                    $ulangan03Value = $ulangan03[$i] ?? null;
                    $ulangan04Value = $ulangan04[$i] ?? null;
                    $ulangan05Value = $ulangan05[$i] ?? null;
                    $kodeKiriValue = $kodeStandardKiri[$i] ?? null;
                    $kodeKananValue = $kodeStandardKanan[$i] ?? null;
        
                    // SKIP jika semua kolom kosong
                    if (empty($titikValue) && 
                        empty($ulangan01Value) && 
                        empty($ulangan02Value) && 
                        empty($ulangan03Value) && 
                        empty($ulangan04Value) && 
                        empty($ulangan05Value) && 
                        empty($kodeKiriValue) && 
                        empty($kodeKananValue)) {
                        \Log::debug('Baris ' . ($i + 1) . ' kosong, dilewati');
                        continue;
                    }
        
                    // VALIDASI: Jika ada titikUkur, minimal harus ada 1 ulangan
                    if (!empty($titikValue)) {
                        $hasUlangan = !empty($ulangan01Value) || !empty($ulangan02Value) || 
                                     !empty($ulangan03Value) || !empty($ulangan04Value) || 
                                     !empty($ulangan05Value);
                        
                        if (!$hasUlangan) {
                            $errors[] = "Baris " . ($i + 1) . ": Titik Ukur '{$titikValue}' harus memiliki minimal 1 data ulangan";
                            \Log::warning('Validasi gagal: ' . end($errors));
                            continue;
                        }
                    }
        
                    // Validasi: Jika ada ulangan, harus ada titikUkur
                    $hasAnyUlangan = !empty($ulangan01Value) || !empty($ulangan02Value) || 
                                   !empty($ulangan03Value) || !empty($ulangan04Value) || 
                                   !empty($ulangan05Value);
                    
                    if ($hasAnyUlangan && empty($titikValue)) {
                        $errors[] = "Baris " . ($i + 1) . ": Data ulangan harus memiliki Titik Ukur";
                        \Log::warning('Validasi gagal: ' . end($errors));
                        continue;
                    }
        
                    // Validasi: Jika ada kode standard, harus ada titikUkur
                    if ((!empty($kodeKiriValue) || !empty($kodeKananValue)) && empty($titikValue)) {
                        $errors[] = "Baris " . ($i + 1) . ": Kode Standard harus memiliki Titik Ukur";
                        \Log::warning('Validasi gagal: ' . end($errors));
                        continue;
                    }
        
                    // Format nilai ulangan ke float jika ada
                    $formatUlangan = function($value) {
                        if (empty($value)) return null;
                        $value = str_replace(',', '.', $value);
                        return is_numeric($value) ? (float) $value : null;
                    };
        
                    // SIMPAN DATA DETAIL
                    try {
                        DetailDepthCaliper::create([
                            'calibration_id' => $calibration->id,
                            'titikUkur' => !empty($titikValue) ? $titikValue : null,
                            'ulangan01' => $formatUlangan($ulangan01Value),
                            'ulangan02' => $formatUlangan($ulangan02Value),
                            'ulangan03' => $formatUlangan($ulangan03Value),
                            'ulangan04' => $formatUlangan($ulangan04Value),
                            'ulangan05' => $formatUlangan($ulangan05Value),
                            'kodeStandardKiri' => !empty($kodeKiriValue) ? $kodeKiriValue : null,
                            'kodeStandardKanan' => !empty($kodeKananValue) ? $kodeKananValue : null,
                        ]);
        
                        $detailCount++;
        
                        \Log::debug('📝 Detail baris ' . ($i + 1) . ' disimpan', [
                            'titikUkur' => $titikValue,
                            'ulangan01' => $ulangan01Value,
                            'ulangan02' => $ulangan02Value,
                        ]);
        
                    } catch (\Exception $e) {
                        $errors[] = "Baris " . ($i + 1) . ": Gagal menyimpan - " . $e->getMessage();
                        \Log::error('❌ Gagal simpan detail baris ' . ($i + 1), [
                            'error' => $e->getMessage(),
                            'data' => compact('titikValue', 'ulangan01Value', 'ulangan02Value')
                        ]);
                    }
                }
        
                // LOG HASIL AKHIR
                \Log::info('✅ DetailDepthCaliper berhasil disimpan', [
                    'total_records' => $detailCount,
                    'total_rows' => $totalRows,
                    'calibration_id' => $calibration->id,
                    'errors_count' => count($errors),
                    'errors' => $errors
                ]);
        
                if (!empty($errors)) {
                    \Log::warning('⚠️ Ada error dalam penyimpanan detail', ['errors' => $errors]);
                    // Tidak throw error agar proses bisa lanjut, hanya log warning
                }
        
                // ==================================================================
                // 3. SIMPAN TTD DAN INFORMASI TAMBAHAN
                // ==================================================================
                // Data TTD sudah disimpan di calibration table melalui store method utama
                // Simpan informasi tambahan jika ada
                if ($request->has('additional_info') && !empty($request->additional_info)) {
                    $calibration->update([
                        'keterangan' => $request->additional_info
                    ]);
                    \Log::info('📝 Additional info saved to calibration');
                }
        
                \Log::info('🎉 storeDepthCaliper SELESAI');
        
            } catch (\Exception $e) {
                \Log::error('💥 ERROR storeDepthCaliper', [
                    'message' => $e->getMessage(),
                    'file' => $e->getFile(),
                    'line' => $e->getLine(),
                    'trace' => $e->getTraceAsString()
                ]);
                throw $e;
            }
        }
        
        /**
         * Update Depth Caliper data
         */
          private function updateDepthCaliper($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateDepthCaliper =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head depth caliper untuk cek certificate_id
        $headDepthCaliper = $calibration->headDepthCaliper;
        $currentCertificateId = $headDepthCaliper->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE ALAT STANDAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = '';
        
        \Log::info('🔧 Update data:', [
            'alat_standar' => $alatStandar,
            'alat_standar_tambahan' => $request->alat_standar_tambahan ?? ''
        ]);
        
        // Process alat standar
        $processedAlat = [];
        foreach ($alatStandar as $alat) {
            if ($alat === 'dial_gauge_tester_0_25mm') {
                $processedAlat[] = 'Dial Gauge Tester 0~25 mm';
            } 
            elseif ($alat === 'dial_calibration_tester_0_1mm') {
                $processedAlat[] = 'Dial Calibration Tester 0~1 mm';
            }
            elseif ($alat === 'electronic_gauge_tester_0_50mm') {
                $processedAlat[] = 'Electronic Gauge Tester 0~50 mm';
            }
            elseif ($alat === 'alat_standar_lainnya' && $request->filled('alat_standar_tambahan')) {
                $processedAlat[] = $request->alat_standar_tambahan;
            } else {
                $processedAlat[] = $alat;
            }
        }
        
        $alatStandarString = !empty($processedAlat) ? implode(', ', $processedAlat) : '';
        
        // Prepare update data untuk HEAD
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-05 (JIS B 7507 : 1993)',
            'satuan_unit' => $request->satuan_unit,
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        // Update atau create HEAD
        if ($headDepthCaliper) {
            $headDepthCaliper->update($headData);
            \Log::info('✅ HeadDepthCaliper updated:', [
                'standard' => $alatStandarString,
                'certificate_id' => $headDepthCaliper->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
            $headDepthCaliper = HeadDepthCaliper::create($headData);
            \Log::info('➕ NEW HeadDepthCaliper created:', [
                'head_id' => $headDepthCaliper->id,
                'certificate_id' => $headDepthCaliper->certificate_id
            ]);
        }
        
        // ==================================================================
        // 2. DEBUG: CEK STRUKTUR DATA DETAIL
        // ==================================================================
        \Log::info('🔍 DEBUG DETAIL DATA STRUCTURE:', [
            'has_detail' => $request->has('detail'),
            'detail_is_array' => is_array($request->detail),
            'detail_count' => is_array($request->detail) ? count($request->detail) : 0,
            'detail_sample' => is_array($request->detail) ? array_slice($request->detail, 0, 2) : [],
            'all_detail_keys' => is_array($request->detail) ? array_keys($request->detail) : [],
        ]);
        
        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS - MULTIDIMENSIONAL ARRAY
        // ==================================================================
        // Hapus data detail lama
        $deletedCount = DetailDepthCaliper::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Old DetailDepthCaliper deleted:', ['deleted_count' => $deletedCount]);
        
        // Simpan data detail baru
        $detailCount = 0;
        
        if (is_array($request->detail) && count($request->detail) > 0) {
            foreach ($request->detail as $index => $rowData) {
                // Debug setiap row
                \Log::debug("🔍 Processing detail row {$index}:", $rowData);
                
                // Skip jika semua field kosong
                $isEmpty = true;
                foreach ($rowData as $value) {
                    if (!empty(trim($value ?? ''))) {
                        $isEmpty = false;
                        break;
                    }
                }
                
                if ($isEmpty) {
                    \Log::debug("⏭️ Skipping empty row {$index}");
                    continue;
                }
                
                try {
                    // Prepare data untuk detail
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $this->formatNumericValue($rowData['titikUkur'] ?? null),
                        'kodeStandardKiri' => $rowData['kodeStandardKiri'] ?? null,
                        'kodeStandardKanan' => $rowData['kodeStandardKanan'] ?? null,
                    ];
                    
                    // Tambahkan ulangan01 sampai ulangan05
                    for ($u = 1; $u <= 5; $u++) {
                        $fieldName = 'ulangan0' . $u;
                        $detailData[$fieldName] = $this->formatNumericValue($rowData[$fieldName] ?? null);
                    }
                    
                    // Jika ada kolom tambahan (col1-col8 untuk baris kosong)
                    for ($c = 1; $c <= 8; $c++) {
                        $colName = 'col' . $c;
                        if (isset($rowData[$colName])) {
                            // Untuk kolom umum, simpan sesuai mapping
                            if ($c == 1) {
                                $detailData['titikUkur'] = $this->formatNumericValue($rowData[$colName]);
                            } elseif ($c == 2) {
                                $detailData['kodeStandardKiri'] = $rowData[$colName];
                            } elseif ($c == 3) {
                                $detailData['kodeStandardKanan'] = $rowData[$colName];
                            } elseif ($c >= 4 && $c <= 8) {
                                $ulanganNum = $c - 3; // col4 -> ulangan01, col5 -> ulangan02, dst
                                $ulanganField = 'ulangan0' . $ulanganNum;
                                $detailData[$ulanganField] = $this->formatNumericValue($rowData[$colName]);
                            }
                        }
                    }
                    
                    \Log::debug("💾 Saving detail row {$index}:", $detailData);
                    
                    DetailDepthCaliper::create($detailData);
                    $detailCount++;
                    
                } catch (\Exception $rowError) {
                    \Log::error("❌ DetailDepthCaliper row {$index} error:", [
                        'error' => $rowError->getMessage(),
                        'data' => $rowData
                    ]);
                }
            }
        } else {
            \Log::warning('⚠️ No detail data found or detail is not an array');
        }
        
        \Log::info('✅ DetailDepthCaliper updated:', ['total_records' => $detailCount]);
        
        // ==================================================================
        // 4. UPDATE ADDITIONAL DATA (jika ada)
        // ==================================================================
        if ($add = $calibration->addDepthCaliper) {
            $updateData = [];
            
            // Handle repeatability jika ada
            if ($request->filled('repeatability')) {
                $updateData['repeatability'] = trim($request->repeatability);
            }
            
            // Handle ulangan tambahan jika ada
            for ($i = 1; $i <= 10; $i++) {
                $fieldName = ($i < 10) ? 'ulangan0' . $i : 'ulangan' . $i;
                if ($request->filled($fieldName)) {
                    $fieldValue = $this->formatNumericValue($request->$fieldName);
                    if (!is_null($fieldValue)) {
                        $updateData[$fieldName] = $fieldValue;
                    }
                }
            }
            
            if (!empty($updateData)) {
                $add->update($updateData);
                \Log::info('✅ AddDepthCaliper updated');
            }
        }
        
        // ==================================================================
        // 5. FINAL VERIFICATION
        // ==================================================================
        $finalHead = HeadDepthCaliper::where('calibration_id', $calibration->id)->first();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'details_count' => $detailCount
        ]);
        
        \Log::info('🎉 updateDepthCaliper COMPLETED', [
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA'
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateDepthCaliper FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}
    private function storeCaliper($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1, $tabId = null)
{
    \Log::info('🚀 ===== START storeCaliper =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm,
        'tab_id' => $tabId
    ]);
    
    try {
        // Jika tabId tidak dikirim, coba ambil dari request
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // Jika tidak dikirim dari parameter, ambil dari request
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
            // ==================================================================
        // ==================================================================
        // HELPER FUNCTIONS UNTUK MENCARI DATA PER FORM (TAB-UNLIMITED & PREFIX-AGNOSTIC)
        // ==================================================================
        
        /**
         * Helper untuk mengecek apakah sebuah key cocok dengan baseKey untuk formIndex tertentu.
         * Mendukung tab berapa pun (tab1, tab2, tab15, tab99, dst - TIDAK dibatasi ke tab 10)
         * dan format prefix form_{formIndex}_ maupun tanpa prefix.
         */
        $keyMatches = function($keyName, $baseKey, $formIndex, $isFromScopedFormData = false) {
            if ($isFromScopedFormData) {
                if ($keyName === $baseKey || $keyName === "{$baseKey}_{$formIndex}") {
                    return true;
                }
                $quoted = preg_quote($baseKey, '/');
                if (preg_match('/^' . $quoted . '(_' . $formIndex . ')?(_tab\d+)?$/i', $keyName)) {
                    return true;
                }
            }
            
            // 1. Cek format persis tanpa suffix tab
            if ($keyName === "form_{$formIndex}_{$baseKey}_{$formIndex}" ||
                $keyName === "form_{$formIndex}_{$baseKey}" ||
                $keyName === "{$baseKey}_{$formIndex}") {
                return true;
            }
            if ($formIndex === 1 && $keyName === $baseKey) {
                return true;
            }
            
            // 2. Cek format dengan suffix tab berapa pun (_tab\d+)
            $quoted = preg_quote($baseKey, '/');
            if ($formIndex === 1) {
                // Form 1: form_1_baseKey_1_tabX, form_1_baseKey_tabX, baseKey_1_tabX, baseKey_tabX
                if (preg_match('/^(form_1_)?' . $quoted . '(_1)?_tab\d+$/i', $keyName)) {
                    return true;
                }
            } else {
                // Form > 1: WAJIB memiliki indikator formIndex di depan (form_{formIndex}_) atau tepat setelah baseKey (_{formIndex})
                if (preg_match('/^(form_' . $formIndex . '_' . $quoted . '(_' . $formIndex . ')?_tab\d+|' . $quoted . '_' . $formIndex . '_tab\d+)$/i', $keyName)) {
                    return true;
                }
            }
            
            return false;
        };

        /**
         * Mencari nilai skalar dari formData atau request (mendukung semua tab dan format)
         */
        $findValue = function($baseKey, $formIndex, $fData = []) use ($request, $keyMatches) {
            // 1. Cek di formData
            foreach ($fData as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, true)) {
                    return is_array($v) ? ($v[0] ?? null) : $v;
                }
            }
            // 2. Cek di request
            foreach ($request->all() as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, false)) {
                    return is_array($v) ? ($v[0] ?? null) : $v;
                }
            }
            return null;
        };

        /**
         * Mencari array measurements (outside, inside, depth titik ukur & ulangan)
         */
        $findArray = function($baseKey, $formIndex, $fData = []) use ($request, $keyMatches) {
            // 1. Cek di formData
            foreach ($fData as $k => $v) {
                if (!empty($v) && $keyMatches($k, $baseKey, $formIndex, true)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v) && count($v) > 0) return array_values($v);
                }
            }
            // 2. Cek di request
            foreach ($request->all() as $k => $v) {
                if (!empty($v) && $keyMatches($k, $baseKey, $formIndex, false)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v) && count($v) > 0) return array_values($v);
                    return [$v];
                }
            }
            return [];
        };

        /**
         * Mencari alat standar spesifik per form (independen untuk tiap form)
         */
        $findAlatStandar = function($formIndex, $fData = []) use ($request, $keyMatches) {
            // 1. Cek di formData
            foreach ($fData as $k => $v) {
                if (!empty($v) && $keyMatches($k, 'alat_standar', $formIndex, true)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v)) {
                        $filtered = array_values(array_filter($v, fn($x) => !empty(trim((string)$x))));
                        if (!empty($filtered)) return $filtered;
                    }
                }
            }
            // 2. Cek di request
            foreach ($request->all() as $k => $v) {
                if (!empty($v) && $keyMatches($k, 'alat_standar', $formIndex, false)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v)) {
                        $filtered = array_values(array_filter($v, fn($x) => !empty(trim((string)$x))));
                        if (!empty($filtered)) return $filtered;
                    }
                }
            }
            // Fallback form 1 jika ada field umum 'alat_standar'
            if ($formIndex === 1) {
                $val = $request->input('alat_standar');
                if (!empty($val)) {
                    if (is_string($val)) $val = json_decode($val, true) ?: [$val];
                    if (is_array($val)) {
                        return array_values(array_filter($val, fn($x) => !empty(trim((string)$x))));
                    }
                }
            }
            return [];
        };

        /**
         * Mencari satuan unit per form (outside, inside, depth)
         */
        $findSatuanUnit = function($type, $formIndex, $fData = []) use ($request, $keyMatches) {
            $baseKey = "satuan_unit_{$type}";
            foreach ($fData as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, true)) {
                    $val = is_array($v) ? ($v[0] ?? 'mm') : $v;
                    if (trim((string)$val) !== '') return trim((string)$val);
                }
            }
            foreach ($request->all() as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, false)) {
                    $val = is_array($v) ? ($v[0] ?? 'mm') : $val;
                    if (trim((string)$val) !== '') return trim((string)$val);
                }
            }
            return 'mm';
        };

        // Ekstrak data form ber-prefix form_{i}_ jika ada
        $allFormsData = [];
        for ($i = 1; $i <= $jumlahForm; $i++) {
            $fData = [];
            foreach ($request->all() as $key => $value) {
                if (strpos($key, "form_{$i}_") === 0) {
                    $originalKey = substr($key, strlen("form_{$i}_"));
                    $fData[$originalKey] = $value;
                }
            }
            $allFormsData[$i] = $fData;
        }

        // ==================================================================
        // 1. STORE HEADS UNTUK SETIAP FORM (Alat Standar & Satuan Unit per form)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $fData = $allFormsData[$formIndex] ?? [];
            
            $satuanUnitOutside = $findSatuanUnit('outside', $formIndex, $fData);
            $satuanUnitInside  = $findSatuanUnit('inside', $formIndex, $fData);
            $satuanUnitDepth   = $findSatuanUnit('depth', $formIndex, $fData);
            
            $stdArray = $findAlatStandar($formIndex, $fData);
            $stdValue = !empty($stdArray) ? implode(', ', $stdArray) : '';
            
            \Log::info("📝 Creating/Updating HeadCaliper for form {$formIndex}", [
                'satuan_unit_outside' => $satuanUnitOutside,
                'satuan_unit_inside'  => $satuanUnitInside,
                'satuan_unit_depth'   => $satuanUnitDepth,
                'standard'            => $stdValue,
                'count_standards'     => count($stdArray)
            ]);
            
            HeadCaliper::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'satuan_unit_inside'  => $satuanUnitInside,
                    'satuan_unit_outside' => $satuanUnitOutside,
                    'satuan_unit_depth'   => $satuanUnitDepth,
                    'standard'            => $stdValue,
                    'calibrationMethod'   => 'PAS-IK1102-03 (JIS B 7507:2022 (JMA/JSA); SNSU PK.P-02:2020).',
                    'certificate_id'      => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadCaliper::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();

        // ==================================================================
        // 2. STORE ADD & DETAIL MEASUREMENTS UNTUK SETIAP FORM
        // ==================================================================
        DetailCaliper::where('calibration_id', $calibration->id)->delete();
        AddCaliper::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Cleared existing DetailCaliper and AddCaliper for calibration_id: {$calibration->id}");
        
        $totalDetailCount = 0;
        $totalAddCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $fData = $allFormsData[$formIndex] ?? [];
            \Log::info("📊 Processing measurements for form {$formIndex}");
            
            // --- A. SIMPAN DATA ADD CALIPER (Kesejajaran & Pisau Bersilang) ---
            $titikUkurKesejajaran = $findValue('titikUkurKesejajaran', $formIndex, $fData);
            $kesejajaranAwal      = $findValue('kesejajaranAwal', $formIndex, $fData);
            $kesejajaranTengah    = $findValue('kesejajaranTengah', $formIndex, $fData);
            $kesejajaranAkhir     = $findValue('kesejajaranAkhir', $formIndex, $fData);
            $pengukuranDalam      = $findValue('pengukuranDalamPisauBersilang', $formIndex, $fData);
            $pembacaan1           = $findValue('pembacaan1', $formIndex, $fData);
            $pembacaan2           = $findValue('pembacaan2', $formIndex, $fData);
            $pembacaan3           = $findValue('pembacaan3', $formIndex, $fData);
            
            $addData = [
                'calibration_id'                => $calibration->id,
                'form_index'                    => $formIndex,
                'titikUkurKesajajaran'          => $titikUkurKesejajaran,
                'kesejajaranAwal'               => $kesejajaranAwal,
                'kesejajaranTengah'             => $kesejajaranTengah,
                'kesejajaranAkhir'              => $kesejajaranAkhir,
                'pengukuranDalamPisauBersilang' => $pengukuranDalam,
                'pembacaan1'                    => $pembacaan1,
                'pembacaan2'                    => $pembacaan2,
                'pembacaan3'                    => $pembacaan3,
            ];
            
            $hasAddData = !empty($titikUkurKesejajaran) || !empty($kesejajaranAwal) || 
                          !empty($kesejajaranTengah) || !empty($kesejajaranAkhir) ||
                          !empty($pengukuranDalam) || !empty($pembacaan1) || 
                          !empty($pembacaan2) || !empty($pembacaan3);
            
            if ($hasAddData) {
                AddCaliper::create($addData);
                $totalAddCount++;
                \Log::info("✅ AddCaliper saved for form {$formIndex}", $addData);
            }
            
            // --- B. SIMPAN DATA DETAIL (OUTSIDE, INSIDE, DEPTH) ---
            $outsideTitikUkur = $findArray('outside_titik_ukur', $formIndex, $fData);
            $outside01        = $findArray('outside_ulangan01', $formIndex, $fData);
            $outside02        = $findArray('outside_ulangan02', $formIndex, $fData);
            $outside03        = $findArray('outside_ulangan03', $formIndex, $fData);
            $outside04        = $findArray('outside_ulangan04', $formIndex, $fData);
            $outside05        = $findArray('outside_ulangan05', $formIndex, $fData);
            
            $insideTitikUkur  = $findArray('inside_titik_ukur', $formIndex, $fData);
            $inside01         = $findArray('inside_ulangan01', $formIndex, $fData);
            $inside02         = $findArray('inside_ulangan02', $formIndex, $fData);
            $inside03         = $findArray('inside_ulangan03', $formIndex, $fData);
            $inside04         = $findArray('inside_ulangan04', $formIndex, $fData);
            $inside05         = $findArray('inside_ulangan05', $formIndex, $fData);
            
            $depthTitikUkur   = $findArray('depth_titik_ukur', $formIndex, $fData);
            $depthKodeKiri    = $findArray('depth_kode_standard_kiri', $formIndex, $fData);
            if (empty($depthKodeKiri)) {
                $depthKodeKiri = $findArray('depth_kode_standar_kiri', $formIndex, $fData);
            }
            $depthKodeKanan   = $findArray('depth_kode_standard_kanan', $formIndex, $fData);
            if (empty($depthKodeKanan)) {
                $depthKodeKanan = $findArray('depth_kode_standar_kanan', $formIndex, $fData);
            }
            $depth01          = $findArray('depth_ulangan01', $formIndex, $fData);
            $depth02          = $findArray('depth_ulangan02', $formIndex, $fData);
            $depth03          = $findArray('depth_ulangan03', $formIndex, $fData);
            $depth04          = $findArray('depth_ulangan04', $formIndex, $fData);
            $depth05          = $findArray('depth_ulangan05', $formIndex, $fData);
            
            \Log::info("📊 Detail data counts for form {$formIndex}:", [
                'outside_titik' => count($outsideTitikUkur),
                'inside_titik'  => count($insideTitikUkur),
                'depth_titik'   => count($depthTitikUkur)
            ]);
            
            // Simpan Outside
            for ($i = 0; $i < count($outsideTitikUkur); $i++) {
                $titik = $outsideTitikUkur[$i] ?? null;
                if ($titik !== null && $titik !== '') {
                    DetailCaliper::create([
                        'calibration_id' => $calibration->id,
                        'form_index'     => $formIndex,
                        'titikUkur'      => $titik,
                        'outside01'      => $outside01[$i] ?? null,
                        'outside02'      => $outside02[$i] ?? null,
                        'outside03'      => $outside03[$i] ?? null,
                        'outside04'      => $outside04[$i] ?? null,
                        'outside05'      => $outside05[$i] ?? null,
                    ]);
                    $totalDetailCount++;
                }
            }
            
            // Simpan Inside
            for ($i = 0; $i < count($insideTitikUkur); $i++) {
                $titik = $insideTitikUkur[$i] ?? null;
                if ($titik !== null && $titik !== '') {
                    DetailCaliper::create([
                        'calibration_id' => $calibration->id,
                        'form_index'     => $formIndex,
                        'titikUkur'      => $titik,
                        'inside01'       => $inside01[$i] ?? null,
                        'inside02'       => $inside02[$i] ?? null,
                        'inside03'       => $inside03[$i] ?? null,
                        'inside04'       => $inside04[$i] ?? null,
                        'inside05'       => $inside05[$i] ?? null,
                    ]);
                    $totalDetailCount++;
                }
            }
            
            // Simpan Depth
            for ($i = 0; $i < count($depthTitikUkur); $i++) {
                $titik = $depthTitikUkur[$i] ?? null;
                if ($titik !== null && $titik !== '') {
                    DetailCaliper::create([
                        'calibration_id'  => $calibration->id,
                        'form_index'      => $formIndex,
                        'titikUkur'       => $titik,
                        'depth01'         => $depth01[$i] ?? null,
                        'depth02'         => $depth02[$i] ?? null,
                        'depth03'         => $depth03[$i] ?? null,
                        'depth04'         => $depth04[$i] ?? null,
                        'depth05'         => $depth05[$i] ?? null,
                        'KodeStandarKiri'  => $depthKodeKiri[$i] ?? null,
                        'KodeStandarKanan' => $depthKodeKanan[$i] ?? null,
                    ]);
                    $totalDetailCount++;
                }
            }
        }
        
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        \Log::info('✅ storeCaliper completed successfully', [
            'calibration_id' => $calibration->id,
            'total_details'  => $totalDetailCount,
            'total_add'      => $totalAddCount,
            'jumlah_form'    => $jumlahForm,
            'capacity'       => $request->input('capacity', 'N/A')
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeCaliper FAILED:', [
            'message' => $e->getMessage(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
    
    
      /**
 * Method update untuk Caliper - Multiple Form Support
 * Data diambil langsung dari database tanpa kapasitas
 */
private function updateCaliper($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateCaliper =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head form 1 untuk cek certificate_id
        $form1Head = HeadCaliper::where('calibration_id', $calibration->id)
            ->where('form_index', 1)
            ->first();
        
        $currentCertificateId = $form1Head->certificate_id ?? null;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // AMBIL JUMLAH FORM (TANPA CAPACITY)
        // ==================================================================
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        // Update calibration tanpa capacity
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        \Log::info('📊 UPDATE Caliper - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // HELPER FUNCTIONS & DATA PER FORM (TAB-UNLIMITED & PREFIX-AGNOSTIC)
        // ==================================================================
        $allFormsData = [];
        for ($i = 1; $i <= $jumlahForm; $i++) {
            $fData = [];
            foreach ($request->all() as $key => $value) {
                if (strpos($key, "form_{$i}_") === 0) {
                    $originalKey = substr($key, strlen("form_{$i}_"));
                    $fData[$originalKey] = $value;
                }
            }
            $allFormsData[$i] = $fData;
        }

        $keyMatches = function($keyName, $baseKey, $formIndex, $isFromScopedFormData = false) {
            if ($isFromScopedFormData) {
                if ($keyName === $baseKey || $keyName === "{$baseKey}_{$formIndex}") {
                    return true;
                }
                $quoted = preg_quote($baseKey, '/');
                if (preg_match('/^' . $quoted . '(_' . $formIndex . ')?(_tab\d+)?$/i', $keyName)) {
                    return true;
                }
            }
            
            if ($keyName === "form_{$formIndex}_{$baseKey}_{$formIndex}" ||
                $keyName === "form_{$formIndex}_{$baseKey}" ||
                $keyName === "{$baseKey}_{$formIndex}") {
                return true;
            }
            if ($formIndex === 1 && $keyName === $baseKey) {
                return true;
            }
            
            $quoted = preg_quote($baseKey, '/');
            if ($formIndex === 1) {
                if (preg_match('/^(form_1_)?' . $quoted . '(_1)?_tab\d+$/i', $keyName)) {
                    return true;
                }
            } else {
                if (preg_match('/^(form_' . $formIndex . '_' . $quoted . '(_' . $formIndex . ')?_tab\d+|' . $quoted . '_' . $formIndex . '_tab\d+)$/i', $keyName)) {
                    return true;
                }
            }
            
            return false;
        };

        $findValue = function($baseKey, $formIndex, $fData = []) use ($request, $keyMatches) {
            foreach ($fData as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, true)) {
                    return is_array($v) ? ($v[0] ?? null) : $v;
                }
            }
            foreach ($request->all() as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, false)) {
                    return is_array($v) ? ($v[0] ?? null) : $v;
                }
            }
            return null;
        };

        $findArray = function($baseKey, $formIndex, $fData = []) use ($request, $keyMatches) {
            foreach ($fData as $k => $v) {
                if (!empty($v) && $keyMatches($k, $baseKey, $formIndex, true)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v) && count($v) > 0) return array_values($v);
                }
            }
            foreach ($request->all() as $k => $v) {
                if (!empty($v) && $keyMatches($k, $baseKey, $formIndex, false)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v) && count($v) > 0) return array_values($v);
                    return [$v];
                }
            }
            return [];
        };

        $findAlatStandar = function($formIndex, $fData = []) use ($request, $keyMatches) {
            foreach ($fData as $k => $v) {
                if (!empty($v) && $keyMatches($k, 'alat_standar', $formIndex, true)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v)) {
                        $filtered = array_values(array_filter($v, fn($x) => !empty(trim((string)$x))));
                        if (!empty($filtered)) return $filtered;
                    }
                }
            }
            foreach ($request->all() as $k => $v) {
                if (!empty($v) && $keyMatches($k, 'alat_standar', $formIndex, false)) {
                    if (is_string($v)) $v = json_decode($v, true) ?: [$v];
                    if (is_array($v)) {
                        $filtered = array_values(array_filter($v, fn($x) => !empty(trim((string)$x))));
                        if (!empty($filtered)) return $filtered;
                    }
                }
            }
            if ($formIndex === 1) {
                $val = $request->input('alat_standar');
                if (!empty($val)) {
                    if (is_string($val)) $val = json_decode($val, true) ?: [$val];
                    if (is_array($val)) {
                        return array_values(array_filter($val, fn($x) => !empty(trim((string)$x))));
                    }
                }
            }
            return [];
        };

        $findSatuanUnit = function($type, $formIndex, $fData = []) use ($request, $keyMatches) {
            $baseKey = "satuan_unit_{$type}";
            foreach ($fData as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, true)) {
                    $val = is_array($v) ? ($v[0] ?? 'mm') : $v;
                    if (trim((string)$val) !== '') return trim((string)$val);
                }
            }
           foreach ($request->all() as $k => $v) {
                if ($v !== null && $v !== '' && $keyMatches($k, $baseKey, $formIndex, false)) {
                    $val = is_array($v) ? ($v[0] ?? 'mm') : $v;   // ✅
                    if (trim((string)$val) !== '') return trim((string)$val);
                }
            }
            return 'mm';
        };

        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM (gunakan updateOrCreate)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $fData = $allFormsData[$formIndex] ?? [];
            
            $satuanUnitOutside = $findSatuanUnit('outside', $formIndex, $fData);
            $satuanUnitInside  = $findSatuanUnit('inside', $formIndex, $fData);
            $satuanUnitDepth   = $findSatuanUnit('depth', $formIndex, $fData);
            
            $stdArray = $findAlatStandar($formIndex, $fData);
            $stdValue = !empty($stdArray) ? implode(', ', $stdArray) : '';
            
            $headData = [
                'satuan_unit_inside'  => $satuanUnitInside,
                'satuan_unit_outside' => $satuanUnitOutside,
                'satuan_unit_depth'   => $satuanUnitDepth,
                'standard'            => $stdValue,
                'calibrationMethod'   => 'PAS-IK1102-03 (JIS B 7507:2022 (JMA/JSA); SNSU PK.P-02:2020).',
            ];
            
            // UPDATE CERTIFICATE ID DI HEAD
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            $head = HeadCaliper::updateOrCreate(
                [
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex
                ],
                $headData
            );
            
            \Log::info("✅ Head updated for form {$formIndex}", [
                'head_id' => $head->id,
                'satuan_unit_inside' => $head->satuan_unit_inside,
                'satuan_unit_outside' => $head->satuan_unit_outside,
                'satuan_unit_depth' => $head->satuan_unit_depth,
                'standard' => $head->standard,
                'certificate_id' => $head->certificate_id ?? 'not_set'
            ]);
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadCaliper::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS (OUTSIDE, INSIDE, DEPTH)
        // ==================================================================
        DetailCaliper::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Old details deleted for calibration_id: ' . $calibration->id);
        
        $totalDetailCount = 0;
        
        $isNotNullOrEmpty = function($val) {
            if ($val === null) return false;
            $str = trim((string)$val);
            return strlen($str) > 0;
        };
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $fData = $allFormsData[$formIndex] ?? [];
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // OUTSIDE DATA
            $outsideTitikUkur = $findArray('outside_titik_ukur', $formIndex, $fData);
            $outside01 = $findArray('outside_ulangan01', $formIndex, $fData);
            $outside02 = $findArray('outside_ulangan02', $formIndex, $fData);
            $outside03 = $findArray('outside_ulangan03', $formIndex, $fData);
            $outside04 = $findArray('outside_ulangan04', $formIndex, $fData);
            $outside05 = $findArray('outside_ulangan05', $formIndex, $fData);
            
            for ($i = 0; $i < count($outsideTitikUkur); $i++) {
                $titikUkur = $outsideTitikUkur[$i] ?? null;
                $hasData = $isNotNullOrEmpty($titikUkur) || 
                          $isNotNullOrEmpty($outside01[$i] ?? null) || 
                          $isNotNullOrEmpty($outside02[$i] ?? null) || 
                          $isNotNullOrEmpty($outside03[$i] ?? null) || 
                          $isNotNullOrEmpty($outside04[$i] ?? null) || 
                          $isNotNullOrEmpty($outside05[$i] ?? null);
                
                if ($hasData) {
                    DetailCaliper::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'outside01' => $isNotNullOrEmpty($outside01[$i] ?? null) ? $outside01[$i] : null,
                        'outside02' => $isNotNullOrEmpty($outside02[$i] ?? null) ? $outside02[$i] : null,
                        'outside03' => $isNotNullOrEmpty($outside03[$i] ?? null) ? $outside03[$i] : null,
                        'outside04' => $isNotNullOrEmpty($outside04[$i] ?? null) ? $outside04[$i] : null,
                        'outside05' => $isNotNullOrEmpty($outside05[$i] ?? null) ? $outside05[$i] : null,
                    ]);
                    $totalDetailCount++;
                }
            }
            
            // INSIDE DATA
            $insideTitikUkur = $findArray('inside_titik_ukur', $formIndex, $fData);
            $inside01 = $findArray('inside_ulangan01', $formIndex, $fData);
            $inside02 = $findArray('inside_ulangan02', $formIndex, $fData);
            $inside03 = $findArray('inside_ulangan03', $formIndex, $fData);
            $inside04 = $findArray('inside_ulangan04', $formIndex, $fData);
            $inside05 = $findArray('inside_ulangan05', $formIndex, $fData);
            
            for ($i = 0; $i < count($insideTitikUkur); $i++) {
                $titikUkur = $insideTitikUkur[$i] ?? null;
                $hasData = $isNotNullOrEmpty($titikUkur) || 
                          $isNotNullOrEmpty($inside01[$i] ?? null) || 
                          $isNotNullOrEmpty($inside02[$i] ?? null) || 
                          $isNotNullOrEmpty($inside03[$i] ?? null) || 
                          $isNotNullOrEmpty($inside04[$i] ?? null) || 
                          $isNotNullOrEmpty($inside05[$i] ?? null);
                
                if ($hasData) {
                    DetailCaliper::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'inside01' => $isNotNullOrEmpty($inside01[$i] ?? null) ? $inside01[$i] : null,
                        'inside02' => $isNotNullOrEmpty($inside02[$i] ?? null) ? $inside02[$i] : null,
                        'inside03' => $isNotNullOrEmpty($inside03[$i] ?? null) ? $inside03[$i] : null,
                        'inside04' => $isNotNullOrEmpty($inside04[$i] ?? null) ? $inside04[$i] : null,
                        'inside05' => $isNotNullOrEmpty($inside05[$i] ?? null) ? $inside05[$i] : null,
                    ]);
                    $totalDetailCount++;
                }
            }
            
            // DEPTH DATA
            $depthTitikUkur = $findArray('depth_titik_ukur', $formIndex, $fData);
            $depthKodeKiri  = $findArray('depth_kode_standard_kiri', $formIndex, $fData);
            if (empty($depthKodeKiri)) $depthKodeKiri = $findArray('depth_kode_standar_kiri', $formIndex, $fData);
            $depthKodeKanan = $findArray('depth_kode_standard_kanan', $formIndex, $fData);
            if (empty($depthKodeKanan)) $depthKodeKanan = $findArray('depth_kode_standar_kanan', $formIndex, $fData);
            $depth01 = $findArray('depth_ulangan01', $formIndex, $fData);
            $depth02 = $findArray('depth_ulangan02', $formIndex, $fData);
            $depth03 = $findArray('depth_ulangan03', $formIndex, $fData);
            $depth04 = $findArray('depth_ulangan04', $formIndex, $fData);
            $depth05 = $findArray('depth_ulangan05', $formIndex, $fData);
            
            for ($i = 0; $i < count($depthTitikUkur); $i++) {
                $titikUkur = $depthTitikUkur[$i] ?? null;
                $hasData = $isNotNullOrEmpty($titikUkur) || 
                          $isNotNullOrEmpty($depthKodeKiri[$i] ?? null) || 
                          $isNotNullOrEmpty($depthKodeKanan[$i] ?? null) || 
                          $isNotNullOrEmpty($depth01[$i] ?? null) || 
                          $isNotNullOrEmpty($depth02[$i] ?? null) || 
                          $isNotNullOrEmpty($depth03[$i] ?? null) || 
                          $isNotNullOrEmpty($depth04[$i] ?? null) || 
                          $isNotNullOrEmpty($depth05[$i] ?? null);
                
                if ($hasData) {
                    DetailCaliper::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'KodeStandarKiri' => $isNotNullOrEmpty($depthKodeKiri[$i] ?? null) ? $depthKodeKiri[$i] : null,
                        'KodeStandarKanan' => $isNotNullOrEmpty($depthKodeKanan[$i] ?? null) ? $depthKodeKanan[$i] : null,
                        'depth01' => $isNotNullOrEmpty($depth01[$i] ?? null) ? $depth01[$i] : null,
                        'depth02' => $isNotNullOrEmpty($depth02[$i] ?? null) ? $depth02[$i] : null,
                        'depth03' => $isNotNullOrEmpty($depth03[$i] ?? null) ? $depth03[$i] : null,
                        'depth04' => $isNotNullOrEmpty($depth04[$i] ?? null) ? $depth04[$i] : null,
                        'depth05' => $isNotNullOrEmpty($depth05[$i] ?? null) ? $depth05[$i] : null,
                    ]);
                    $totalDetailCount++;
                }
            }
        }
        
        \Log::info("✅ Total details saved: {$totalDetailCount}");
        
        // ==================================================================
        // 3. UPDATE ADD CALIPER (KESEJAJARAN & PENGUKURAN DALAM)
        // ==================================================================
        AddCaliper::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Old AddCaliper deleted for calibration_id: ' . $calibration->id);
        
        $totalAddCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $fData = $allFormsData[$formIndex] ?? [];
            
            $titikUkurKesejajaran = $findValue('titikUkurKesejajaran', $formIndex, $fData) ?? $findValue('titikUkurKesajajaran', $formIndex, $fData);
            $kesejajaranAwal      = $findValue('kesejajaranAwal', $formIndex, $fData);
            $kesejajaranTengah    = $findValue('kesejajaranTengah', $formIndex, $fData);
            $kesejajaranAkhir     = $findValue('kesejajaranAkhir', $formIndex, $fData);
            $pengukuranDalam      = $findValue('pengukuranDalamPisauBersilang', $formIndex, $fData);
            $pembacaan1           = $findValue('pembacaan1', $formIndex, $fData);
            $pembacaan2           = $findValue('pembacaan2', $formIndex, $fData);
            $pembacaan3           = $findValue('pembacaan3', $formIndex, $fData);
            
            $hasData = $isNotNullOrEmpty($titikUkurKesejajaran) || 
                      $isNotNullOrEmpty($kesejajaranAwal) || 
                      $isNotNullOrEmpty($kesejajaranTengah) || 
                      $isNotNullOrEmpty($kesejajaranAkhir) ||
                      $isNotNullOrEmpty($pengukuranDalam) ||
                      $isNotNullOrEmpty($pembacaan1) ||
                      $isNotNullOrEmpty($pembacaan2) ||
                      $isNotNullOrEmpty($pembacaan3);
            
            if ($hasData) {
                AddCaliper::create([
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'titikUkurKesajajaran' => $titikUkurKesejajaran,
                    'kesejajaranAwal' => $kesejajaranAwal,
                    'kesejajaranTengah' => $kesejajaranTengah,
                    'kesejajaranAkhir' => $kesejajaranAkhir,
                    'pengukuranDalamPisauBersilang' => $pengukuranDalam,
                    'pembacaan1' => $pembacaan1,
                    'pembacaan2' => $pembacaan2,
                    'pembacaan3' => $pembacaan3,
                ]);
                $totalAddCount++;
                \Log::info("✅ AddCaliper saved for form {$formIndex}");
            }
        }
        
        // ==================================================================
        // 4. FINAL VERIFICATION
        // ==================================================================
        $finalDetails = DetailCaliper::where('calibration_id', $calibration->id)->orderBy('id')->get();
        $finalHeads = HeadCaliper::where('calibration_id', $calibration->id)->orderBy('form_index')->get();
        $finalAdds = AddCaliper::where('calibration_id', $calibration->id)->orderBy('form_index')->get();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_count' => $finalHeads->count(),
            'details_count' => $finalDetails->count(),
            'adds_count' => $finalAdds->count(),
            'certificate_id_calibration' => $calibration->certificate_id,
            'certificate_id_heads' => $finalHeads->pluck('certificate_id')->toArray()
        ]);
        
        \Log::info('🎉 updateCaliper COMPLETED', [
            'calibration_id' => $calibration->id,
            'details_saved' => $totalDetailCount,
            'add_saved' => $totalAddCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_head_form1' => $finalHeads->where('form_index', 1)->first()->certificate_id ?? 'TIDAK ADA'
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateCaliper FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
        private function sanitizeMeasurement($value)
        {
            if (is_null($value) || $value === '') {
                return null;
            }
            
            // Hapus spasi dan karakter non-numerik kecuali titik dan minus
            $cleaned = preg_replace('/[^\d\.\-]/', '', (string) $value);
            
            // Cek jika hasilnya kosong
            if ($cleaned === '' || $cleaned === null) {
                return null;
            }
            
            // Pastikan format angka yang valid
            if (!is_numeric($cleaned)) {
                return null;
            }
            
            // Konversi ke float dan format dengan 2 digit desimal
            return number_format((float) $cleaned, 2, '.', '');
        }



     private function storeTorqueWrench($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storeTorqueWrench', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (MENGGUNAKAN getRequestValue)
        // ==================================================================
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        
        // Handle alat standar (bisa array atau string)
        $alatStandarString = '';
        if (is_array($alatStandar)) {
            $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        } else {
            $alatStandarString = $alatStandar ?? '';
        }
        
        \Log::info('🔧 Alat standar selected:', [
            'alat_standar_raw' => $alatStandar,
            'alat_standar_string' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. SIMPAN KE HEAD TORQUE WRENCH
        // ==================================================================
        $head = HeadTorqueWrench::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-13 (JIS B 4652:2008)',
            'satuan_setting_alat' => $request->satuan_setting_alat ?? null,
            'satuan_cw' => $request->satuan_cw ?? null,
            'satuan_ccw' => $request->satuan_ccw ?? null,
        ]);
        
        \Log::info('✅ HeadTorqueWrench saved:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        
        // ==================================================================
        // 3. SIMPAN DETAIL KALIBRASI (13 BARIS) DENGAN getRequestValue
        // ==================================================================
        \Log::info('📊 Saving detail measurements...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 13; $i++) {
            // Gunakan getRequestValue untuk setiap field
            $titikUkur = $this->getRequestValue($request, "row{$i}_col0", $tabId);
            $cw1 = $this->getRequestValue($request, "row{$i}_col1", $tabId);
            $cw2 = $this->getRequestValue($request, "row{$i}_col2", $tabId);
            $cw3 = $this->getRequestValue($request, "row{$i}_col3", $tabId);
            $ccw1 = $this->getRequestValue($request, "row{$i}_col4", $tabId);
            $ccw2 = $this->getRequestValue($request, "row{$i}_col5", $tabId);
            $ccw3 = $this->getRequestValue($request, "row{$i}_col6", $tabId);
            
            // Simpan hanya jika ada data (minimal satu kolom terisi)
            if ($titikUkur !== null || $cw1 !== null || $cw2 !== null || $cw3 !== null || 
                $ccw1 !== null || $ccw2 !== null || $ccw3 !== null) {
                
                DetailTorqueWrench::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'cw1' => $cw1,
                    'cw2' => $cw2,
                    'cw3' => $cw3,
                    'ccw1' => $ccw1,
                    'ccw2' => $ccw2,
                    'ccw3' => $ccw3,
                ]);
                
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping detail row {$i} - no data found");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail records");
        
        // ==================================================================
        // 4. SIMPAN ADD TORQUE WRENCH (SEMUA 10 FIELD) DENGAN getRequestValue
        // ==================================================================
        \Log::info('🔄 Saving AddTorqueWrench data...');
        
        // Data untuk AddTorqueWrench - semua 10 field dengan getRequestValue
        $addData = [
            'calibration_id' => $calibration->id,
            
            // Clockwise 1-10
            'repCw01' => $this->getRequestValue($request, 'repeat_cw_1', $tabId),
            'repCw02' => $this->getRequestValue($request, 'repeat_cw_2', $tabId),
            'repCw03' => $this->getRequestValue($request, 'repeat_cw_3', $tabId),
            'repCw04' => $this->getRequestValue($request, 'repeat_cw_4', $tabId),
            'repCw05' => $this->getRequestValue($request, 'repeat_cw_5', $tabId),
            'repCw06' => $this->getRequestValue($request, 'repeat_cw_6', $tabId),
            'repCw07' => $this->getRequestValue($request, 'repeat_cw_7', $tabId),
            'repCw08' => $this->getRequestValue($request, 'repeat_cw_8', $tabId),
            'repCw09' => $this->getRequestValue($request, 'repeat_cw_9', $tabId),
            'repCw10' => $this->getRequestValue($request, 'repeat_cw_10', $tabId),
            
            // Counter Clockwise 1-10
            'repCcw01' => $this->getRequestValue($request, 'repeat_ccw_1', $tabId),
            'repCcw02' => $this->getRequestValue($request, 'repeat_ccw_2', $tabId),
            'repCcw03' => $this->getRequestValue($request, 'repeat_ccw_3', $tabId),
            'repCcw04' => $this->getRequestValue($request, 'repeat_ccw_4', $tabId),
            'repCcw05' => $this->getRequestValue($request, 'repeat_ccw_5', $tabId),
            'repCcw06' => $this->getRequestValue($request, 'repeat_ccw_6', $tabId),
            'repCcw07' => $this->getRequestValue($request, 'repeat_ccw_7', $tabId),
            'repCcw08' => $this->getRequestValue($request, 'repeat_ccw_8', $tabId),
            'repCcw09' => $this->getRequestValue($request, 'repeat_ccw_9', $tabId),
            'repCcw10' => $this->getRequestValue($request, 'repeat_ccw_10', $tabId),
        ];
        
        // Cek apakah ada data yang perlu disimpan (minimal satu field terisi)
        $hasData = false;
        foreach ($addData as $key => $value) {
            if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                $hasData = true;
                break;
            }
        }
        
        if ($hasData) {
            $addRecord = AddTorqueWrench::create($addData);
            \Log::info('✅ AddTorqueWrench saved:', ['add_id' => $addRecord->id]);
        } else {
            \Log::info('⚠️ No AddTorqueWrench data to save');
        }
        
        // ==================================================================
        // 5. UPDATE CALIBRATION JIKA ADA DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Ambil uncertainty dengan getRequestValue
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
        }
        
        // Ambil conclusion/keterangan
        $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
        if (!empty($conclusion)) {
            $updateData['keterangan'] = $conclusion;
        } else {
            $updateData['keterangan'] = ' ';
        }
        
        // Update calibrated_by dan verified_by jika ada
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 Calibration updated:', $updateData);
        }
        
        // ==================================================================
        // 6. LOG HASIL
        // ==================================================================
        $savedDetailCount = DetailTorqueWrench::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddTorqueWrench::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY:', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
        ]);
        
        \Log::info('🎉 storeTorqueWrench COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTorqueWrench:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A'
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailTorqueWrench::where('calibration_id', $calibration->id)->delete();
                AddTorqueWrench::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::info('🔄 Rollback completed successfully');
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Torque Wrench: " . $e->getMessage());
    }
}
      private function updateTorqueWrench($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateTorqueWrench =====', [
        'calibration_id' => $calibration->id,
        'certificate_id' => $calibration->headTorqueWrench->certificate_id ?? 'N/A',
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head torque wrench untuk cek certificate_id
        $headTorqueWrench = $calibration->headTorqueWrench;
        $currentCertificateId = $headTorqueWrench->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE ALAT STANDAR & HEAD DATA
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 ALAT STANDAR UPDATE:', [
            'count' => count($alatStandar),
            'items' => $alatStandar,
            'string_value' => $alatStandarString,
            'old_value' => $calibration->headTorqueWrench->standard ?? 'null'
        ]);

        // Prepare update data untuk HEAD
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-13 (JIS B 4652:2008)',
            'satuan_setting_alat' => $request->satuan_setting_alat ?? null,
            'satuan_cw' => $request->satuan_cw ?? null,
            'satuan_ccw' => $request->satuan_ccw ?? null,
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }

        // Update atau create head data
        if ($headTorqueWrench) {
            $headTorqueWrench->update($headData);
            \Log::info('✅ HEAD DATA UPDATED:', [
                'head_id' => $headTorqueWrench->id,
                'standard_updated' => true,
                'certificate_id' => $headTorqueWrench->certificate_id,
                'satuan_setting_alat' => $request->satuan_setting_alat ?? null,
                'satuan_cw' => $request->satuan_cw ?? null,
                'satuan_ccw' => $request->satuan_ccw ?? null,
            ]);
        } else {
            \Log::warning('⚠️ NO HEAD DATA FOUND, creating new...');
            
            $headData['calibration_id'] = $calibration->id;
            $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
            
            $headTorqueWrench = HeadTorqueWrench::create($headData);
            \Log::info('➕ NEW HEAD CREATED:', [
                'head_id' => $headTorqueWrench->id,
                'certificate_id' => $headTorqueWrench->certificate_id
            ]);
        }

        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS (13 baris)
        // ==================================================================
        \Log::info('📊 DETAIL MEASUREMENTS UPDATE:', [
            'old_records_count' => DetailTorqueWrench::where('calibration_id', $calibration->id)->count(),
            'detail_data_count' => is_array($request->detail) ? count($request->detail) : 0
        ]);
        
        // Log sample of incoming data
        if (is_array($request->detail) && count($request->detail) > 0) {
            \Log::debug('📝 INCOMING DETAIL DATA SAMPLE (first 3 rows):', [
                'row_0' => $request->detail[0] ?? [],
                'row_1' => $request->detail[1] ?? [],
                'row_2' => $request->detail[2] ?? [],
            ]);
        }
        
        // Hapus data detail lama
        $deletedCount = DetailTorqueWrench::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ OLD DETAIL DATA DELETED:', ['deleted_count' => $deletedCount]);
        
        // Simpan data detail baru - 13 BARIS (sesuai dengan input HTML)
        $detailCount = 0;
        $errors = [];
        
        for ($i = 0; $i < 13; $i++) {
            $detailData = $request->detail[$i] ?? [];
            
            // Check if row has data
            $hasData = !empty($detailData) && (
                !empty(trim($detailData['titikUkur'] ?? '')) || 
                !empty(trim($detailData['cw1'] ?? '')) || 
                !empty(trim($detailData['cw2'] ?? '')) || 
                !empty(trim($detailData['cw3'] ?? '')) || 
                !empty(trim($detailData['ccw1'] ?? '')) || 
                !empty(trim($detailData['ccw2'] ?? '')) || 
                !empty(trim($detailData['ccw3'] ?? ''))
            );
            
            if ($hasData) {
                try {
                    $dataToSave = [
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $detailData['titikUkur'] ?? null,
                        'cw1' => $detailData['cw1'] ?? null,
                        'cw2' => $detailData['cw2'] ?? null,
                        'cw3' => $detailData['cw3'] ?? null,
                        'ccw1' => $detailData['ccw1'] ?? null,
                        'ccw2' => $detailData['ccw2'] ?? null,
                        'ccw3' => $detailData['ccw3'] ?? null,
                    ];
                    
                    \Log::debug("💾 SAVING DETAIL ROW {$i}:", [
                        'row' => $i,
                        'data' => $dataToSave
                    ]);
                    
                    DetailTorqueWrench::create($dataToSave);
                    $detailCount++;
                    
                } catch (\Exception $rowError) {
                    $errors[] = "Row {$i}: " . $rowError->getMessage();
                    \Log::error("❌ DETAIL ROW {$i} SAVE ERROR:", [
                        'error' => $rowError->getMessage(),
                        'data' => $detailData
                    ]);
                }
            } else {
                \Log::debug("⏭️ SKIPPING EMPTY DETAIL ROW {$i}");
            }
        }
        
        \Log::info("✅ DETAIL DATA SAVED:", [
            'total_records' => $detailCount,
            'errors_count' => count($errors),
            'errors' => $errors
        ]);

        // ==================================================================
        // 3. UPDATE ADDITIONAL DATA (AddTorqueWrench)
        // ==================================================================
        \Log::info('📊 ADDITIONAL DATA UPDATE:');
        
        // Hapus data additional lama
        $deletedAddCount = AddTorqueWrench::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ OLD ADDITIONAL DATA DELETED:', ['deleted_count' => $deletedAddCount]);
        
        // Simpan data additional baru
        $addData = [
            'calibration_id' => $calibration->id,
        ];
        
        // Data Repeatability Clockwise (repCw01 - repCw10)
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = 'repCw' . str_pad($i, 2, '0', STR_PAD_LEFT);
            $addData[$fieldName] = $request->{$fieldName} ?? null;
        }
        
        // Data Repeatability Counter Clockwise (repCcw01 - repCcw10)
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = 'repCcw' . str_pad($i, 2, '0', STR_PAD_LEFT);
            $addData[$fieldName] = $request->{$fieldName} ?? null;
        }
        
        // Filter hanya field yang ada di fillable model
        $fillable = (new AddTorqueWrench())->getFillable();
        $filteredData = ['calibration_id' => $calibration->id];
        
        foreach ($addData as $key => $value) {
            if (in_array($key, $fillable) || $key === 'calibration_id') {
                $filteredData[$key] = $value;
            }
        }
        
        try {
            AddTorqueWrench::create($filteredData);
            \Log::info('✅ ADDITIONAL DATA SAVED:', [
                'total_fields' => count($filteredData),
                'sample_cw' => [
                    'repCw01' => $filteredData['repCw01'] ?? null, 
                    'repCw02' => $filteredData['repCw02'] ?? null
                ],
                'sample_ccw' => [
                    'repCcw01' => $filteredData['repCcw01'] ?? null, 
                    'repCcw02' => $filteredData['repCcw02'] ?? null
                ]
            ]);
        } catch (\Exception $addError) {
            \Log::error('❌ ADDITIONAL DATA SAVE ERROR:', [
                'error' => $addError->getMessage(),
                'data_sample' => array_slice($filteredData, 0, 5)
            ]);
            throw $addError;
        }

        // ==================================================================
        // 4. VERIFY SAVED DATA
        // ==================================================================
        $savedDetails = DetailTorqueWrench::where('calibration_id', $calibration->id)
            ->orderBy('id')
            ->get();
            
        \Log::info('🔍 VERIFY SAVED DETAIL DATA:', [
            'total_saved' => $savedDetails->count(),
            'first_3_rows_sample' => $savedDetails->take(3)->map(function($item) {
                return [
                    'id' => $item->id,
                    'titikUkur' => $item->titikUkur,
                    'cw1' => $item->cw1,
                    'cw2' => $item->cw2,
                    'cw3' => $item->cw3,
                    'ccw1' => $item->ccw1,
                    'created_at' => $item->created_at
                ];
            })->toArray()
        ]);

        // ==================================================================
        // 5. UPDATE CALIBRATION ADDITIONAL DATA (TANPA CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        if ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        // Tambahan khusus untuk Torque Wrench
        if ($request->filled('unit')) {
            $updateData['unit'] = $request->unit;
        }
        
        if ($request->filled('temperature')) {
            $updateData['temperature'] = $request->temperature;
        }
        
        if ($request->filled('humidity')) {
            $updateData['humidity'] = $request->humidity;
        }
        
        // Kosongkan certificate_id di calibration (biar null, tidak dipakai)
        // Certificate ID hanya disimpan di HEAD saja
        $updateData['certificate_id'] = null;
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 CALIBRATION ADDITIONAL DATA UPDATED:', $updateData);
        }

        // ==================================================================
        // 6. FINAL SUMMARY
        // ==================================================================
        $finalDetailCount = DetailTorqueWrench::where('calibration_id', $calibration->id)->count();
        $finalAddCount = AddTorqueWrench::where('calibration_id', $calibration->id)->count();
        $finalHead = HeadTorqueWrench::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📋 UPDATE SUMMARY:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'detail_records' => $finalDetailCount,
            'additional_records' => $finalAddCount,
            'alat_standar' => $alatStandarString,
            'satuan_setting_alat' => $headTorqueWrench->satuan_setting_alat,
            'satuan_cw' => $headTorqueWrench->satuan_cw,
            'satuan_ccw' => $headTorqueWrench->satuan_ccw,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
            'unit' => $calibration->unit,
            'temperature' => $calibration->temperature,
            'humidity' => $calibration->humidity,
            'execution_time' => microtime(true) - LARAVEL_START,
            'memory_peak' => round(memory_get_peak_usage() / 1024 / 1024, 2) . ' MB'
        ]);

        \Log::info('🎉 updateTorqueWrench COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 updateTorqueWrench FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}

    private function storeTorqueMeter($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storeTorqueMeter', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (MENGGUNAKAN getRequestValue)
        // ==================================================================
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        
        // Handle alat standar (bisa array dari checkbox atau string dari textarea)
        $standardValue = '';
        if (is_array($alatStandar)) {
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        } else {
            $standardValue = $alatStandar ?? '';
        }
        
        // Cek juga kemungkinan ada alat_standar_text (textarea)
        $alatStandarText = $this->getRequestValue($request, 'alat_standar_text', $tabId);
        if (!empty($alatStandarText) && empty($standardValue)) {
            $standardValue = $alatStandarText;
        }
        
        \Log::info('🔧 Alat standar selected:', [
            'alat_standar' => $alatStandar,
            'alat_standar_text' => $alatStandarText,
            'standard_value' => $standardValue,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN KE HEAD TORQUE METER
        // ==================================================================
        $headData = [
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-13B (ASTM D 3474-90 : 2018)',
            'satuan_titikUkur' => $request->satuan_titikUkur ?? null,
            'satuan_cw' => $request->satuan_cw ?? null,
            'satuan_ccw' => $request->satuan_ccw ?? null,
        ];
        
        $head = HeadTorqueMeter::create($headData);
        
        \Log::info('✅ HeadTorqueMeter saved:', [
            'head_id' => $head->id,
            'certificate_id' => $head->certificate_id
        ]);

        // ==================================================================
        // 3. SIMPAN DETAIL KALIBRASI (13 BARIS) DENGAN getRequestValue
        // ==================================================================
        \Log::info('📊 Saving detail measurements...');
        $detailCount = 0;
        $errors = [];
        
        for ($i = 0; $i < 13; $i++) {
            // Gunakan getRequestValue untuk setiap field detail
            $titikUkur = $this->getRequestValue($request, "detail.{$i}.titikUkur", $tabId);
            $kodeStandard = $this->getRequestValue($request, "detail.{$i}.kode_anak_timbang", $tabId);
            $cw1 = $this->getRequestValue($request, "detail.{$i}.cw1", $tabId);
            $cw2 = $this->getRequestValue($request, "detail.{$i}.cw2", $tabId);
            $cw3 = $this->getRequestValue($request, "detail.{$i}.cw3", $tabId);
            $ccw1 = $this->getRequestValue($request, "detail.{$i}.ccw1", $tabId);
            $ccw2 = $this->getRequestValue($request, "detail.{$i}.ccw2", $tabId);
            $ccw3 = $this->getRequestValue($request, "detail.{$i}.ccw3", $tabId);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($titikUkur) || !empty($kodeStandard) ||
                       !empty($cw1) || !empty($cw2) || !empty($cw3) ||
                       !empty($ccw1) || !empty($ccw2) || !empty($ccw3);
            
            if ($hasData) {
                try {
                    DetailTorqueMeter::create([
                        'calibration_id' => $calibration->id,
                        'titikUkurBeban' => $titikUkur,
                        'kodeStandard' => $kodeStandard,
                        'cw1' => $cw1,
                        'cw2' => $cw2,
                        'cw3' => $cw3,
                        'ccw1' => $ccw1,
                        'ccw2' => $ccw2,
                        'ccw3' => $ccw3,
                    ]);
                    $detailCount++;
                    \Log::debug("✅ Detail row {$i} saved successfully");
                } catch (\Exception $e) {
                    $errors[] = "Row {$i}: " . $e->getMessage();
                    \Log::error("❌ Detail row {$i} error: " . $e->getMessage());
                }
            } else {
                \Log::debug("⏭️ Skipping empty detail row {$i}");
            }
        }
        
        \Log::info("📋 Detail records saved:", [
            'total_saved' => $detailCount,
            'errors_count' => count($errors)
        ]);

        // ==================================================================
        // 4. SIMPAN ADD TORQUE METER - DIRECT APPROACH (PASTIKAN SEMUA DATA MASUK)
        // ==================================================================
        \Log::info('🔄 Saving AddTorqueMeter data (DIRECT APPROACH)...');
        
        // Ambil nilai langsung dari request dengan format yang benar
        // Data dikirim sebagai repeat_cw_1_tab1, repeat_cw_2_tab1, dll
        $cw1 = $request->input('repeat_cw_1_tab' . $tabId);
        $cw2 = $request->input('repeat_cw_2_tab' . $tabId);
        $cw3 = $request->input('repeat_cw_3_tab' . $tabId);
        $cw4 = $request->input('repeat_cw_4_tab' . $tabId);
        $cw5 = $request->input('repeat_cw_5_tab' . $tabId);
        $cw6 = $request->input('repeat_cw_6_tab' . $tabId);
        $cw7 = $request->input('repeat_cw_7_tab' . $tabId);
        $cw8 = $request->input('repeat_cw_8_tab' . $tabId);
        $cw9 = $request->input('repeat_cw_9_tab' . $tabId);
        $cw10 = $request->input('repeat_cw_10_tab' . $tabId);
        
        $ccw1 = $request->input('repeat_ccw_1_tab' . $tabId);
        $ccw2 = $request->input('repeat_ccw_2_tab' . $tabId);
        $ccw3 = $request->input('repeat_ccw_3_tab' . $tabId);
        $ccw4 = $request->input('repeat_ccw_4_tab' . $tabId);
        $ccw5 = $request->input('repeat_ccw_5_tab' . $tabId);
        $ccw6 = $request->input('repeat_ccw_6_tab' . $tabId);
        $ccw7 = $request->input('repeat_ccw_7_tab' . $tabId);
        $ccw8 = $request->input('repeat_ccw_8_tab' . $tabId);
        $ccw9 = $request->input('repeat_ccw_9_tab' . $tabId);
        $ccw10 = $request->input('repeat_ccw_10_tab' . $tabId);
        
        // Radius alat bantu
        $radiusValue = $request->input('radius_value');
        $radiusUnit = $request->input('radius_unit');
        
        // Log semua nilai yang ditemukan
        \Log::info('📊 DIRECT VALUES FOUND:', [
            'cw1' => $cw1, 'cw2' => $cw2, 'cw3' => $cw3, 'cw4' => $cw4, 'cw5' => $cw5,
            'cw6' => $cw6, 'cw7' => $cw7, 'cw8' => $cw8, 'cw9' => $cw9, 'cw10' => $cw10,
            'ccw1' => $ccw1, 'ccw2' => $ccw2, 'ccw3' => $ccw3, 'ccw4' => $ccw4, 'ccw5' => $ccw5,
            'ccw6' => $ccw6, 'ccw7' => $ccw7, 'ccw8' => $ccw8, 'ccw9' => $ccw9, 'ccw10' => $ccw10,
            'radius_value' => $radiusValue,
            'radius_unit' => $radiusUnit,
        ]);
        
        // Siapkan data untuk disimpan
        $addData = [
            'calibration_id' => $calibration->id,
            'repCw01' => $cw1,
            'repCw02' => $cw2,
            'repCw03' => $cw3,
            'repCw04' => $cw4,
            'repCw05' => $cw5,
            'repCw06' => $cw6,
            'repCw07' => $cw7,
            'repCw08' => $cw8,
            'repCw09' => $cw9,
            'repCw10' => $cw10,
            'repCcw01' => $ccw1,
            'repCcw02' => $ccw2,
            'repCcw03' => $ccw3,
            'repCcw04' => $ccw4,
            'repCcw05' => $ccw5,
            'repCcw06' => $ccw6,
            'repCcw07' => $ccw7,
            'repCcw08' => $ccw8,
            'repCcw09' => $ccw9,
            'repCcw10' => $ccw10,
            'radiusAlatBantuSTD' => $radiusValue,
            'kodeAlatBantuSTD' => $radiusUnit,
        ];
        
        \Log::info('📝 FINAL ADD DATA TO SAVE:', $addData);
        
        // Cek apakah ada data yang perlu disimpan
        $hasData = false;
        foreach ($addData as $key => $value) {
            if ($key !== 'calibration_id' && !empty($value)) {
                $hasData = true;
                break;
            }
        }
        
        if ($hasData) {
            try {
                $addRecord = AddTorqueMeter::create($addData);
                \Log::info('✅ AddTorqueMeter data saved successfully', [
                    'add_id' => $addRecord->id,
                    'record_data' => $addRecord->toArray()
                ]);
            } catch (\Exception $e) {
                \Log::error('❌ Failed to save AddTorqueMeter:', [
                    'error' => $e->getMessage(),
                    'file' => $e->getFile(),
                    'line' => $e->getLine(),
                    'data' => $addData
                ]);
                throw $e;
            }
        } else {
            \Log::info('⏭️ No AddTorqueMeter data to save (all values null/empty)');
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION
        // ==================================================================
        $updateData = [];
        
        // Calibrated by
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if (!empty($calibratedBy)) {
            $updateData['calibrated_by'] = $calibratedBy;
        }
        
        // Verified by
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if (!empty($verifiedBy)) {
            $updateData['verified_by'] = $verifiedBy;
        }
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
        }
        
        // Conclusion
        $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
        if (!empty($conclusion)) {
            $updateData['keterangan'] = $conclusion;
        } else {
            $updateData['keterangan'] = '';
        }
        
        // Kosongkan certificate_id di calibration (biar null, tidak dipakai)
        $updateData['certificate_id'] = null;
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 Calibration updated:', $updateData);
        }

        // ==================================================================
        // 6. VERIFY FINAL DATA
        // ==================================================================
        $finalDetailCount = DetailTorqueMeter::where('calibration_id', $calibration->id)->count();
        $finalAddCount = AddTorqueMeter::where('calibration_id', $calibration->id)->count();
        
        // Ambil data add yang baru saja disimpan untuk verifikasi
        $savedAddData = AddTorqueMeter::where('calibration_id', $calibration->id)->first();
        if ($savedAddData) {
            \Log::info('🔍 VERIFY SAVED ADD DATA:', [
                'repCw01' => $savedAddData->repCw01,
                'repCw02' => $savedAddData->repCw02,
                'repCw03' => $savedAddData->repCw03,
                'repCw04' => $savedAddData->repCw04,
                'repCw05' => $savedAddData->repCw05,
                'repCw06' => $savedAddData->repCw06,
                'repCw07' => $savedAddData->repCw07,
                'repCw08' => $savedAddData->repCw08,
                'repCw09' => $savedAddData->repCw09,
                'repCw10' => $savedAddData->repCw10,
            ]);
        }
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId,
            'detail_records' => $finalDetailCount,
            'additional_records' => $finalAddCount,
            'head_record' => $head ? 'Exists' : 'Missing',
        ]);

        \Log::info('🎉 storeTorqueMeter COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTorqueMeter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A'
        ]);

        // Cleanup jika ada error
        if (isset($head)) {
            try {
                DetailTorqueMeter::where('calibration_id', $calibration->id)->delete();
                AddTorqueMeter::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::warning('🧹 Cleaned up partially saved data due to error');
            } catch (\Exception $cleanupError) {
                \Log::error('❌ Cleanup failed:', ['error' => $cleanupError->getMessage()]);
            }
        }

        throw $e;
    }
}

        
     private function updateTorqueMeter($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 ===== START updateTorqueMeter =====', [
            'calibration_id' => $calibration->id,
            'timestamp' => now()->toDateTimeString()
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head torque meter untuk cek certificate_id
        $headTorqueMeter = $calibration->headTorqueMeter;
        $currentCertificateId = $headTorqueMeter->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // Debug: log semua data radius yang diterima
        \Log::info('📥 RADIUS DATA FROM REQUEST:', [
            'radiusAlatBantuSTD' => $request->radiusAlatBantuSTD ?? 'Not set',
            'kodeAlatBantuSTD' => $request->kodeAlatBantuSTD ?? 'Not set',
        ]);

        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $textValue  = trim($request->alat_standar_text ?? '');
        $arrayValue = $request->input('alat_standar', []);

        if (!empty($textValue)) {
            $standardValue = $textValue;
        } elseif (is_array($arrayValue) && count($arrayValue) > 0) {
            $standardValue = implode("\n", $arrayValue);
        } else {
            $standardValue = '';
        }

        \Log::info('Alat Standar Final:', ['saved_to_db' => $standardValue]);

        // ==================================================================
        // 2. UPDATE/CREATE HEAD TORQUE METER
        // ==================================================================
        $head = $calibration->headTorqueMeter ?? null;
        
        $headData = [
            'standard' => $standardValue,
            'satuan_titikUkur' => $request->satuan_titikUkur ?? ($head->satuan_titikUkur ?? null),
            'satuan_cw' => $request->satuan_cw ?? ($head->satuan_cw ?? null),
            'satuan_ccw' => $request->satuan_ccw ?? ($head->satuan_ccw ?? null),
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadTorqueMeter updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'satuan_cw' => $request->satuan_cw ?? 'kept old value',
                'satuan_ccw' => $request->satuan_ccw ?? 'kept old value',
                'satuan_titikUkur' => $request->satuan_titikUkur ?? 'kept old value',
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $headData['calibrationMethod'] = 'PAS-IK1102-13B (ASTM D 3474-90 : 2018)';
            $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
            
            $head = HeadTorqueMeter::create($headData);
            \Log::info('➕ HeadTorqueMeter created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        }

        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS (13 baris) - TANPA SANITIZE
        // ==================================================================
        \Log::info('🔄 Processing detail measurements (update per row)...');
        
        $detailCount = 0;
        $updatedDetailCount = 0;
        $createdDetailCount = 0;
        
        for ($i = 0; $i < 13; $i++) {
            $detailData = $request->input("detail.{$i}", []);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($detailData) && (
                isset($detailData['titikUkurBeban']) || 
                isset($detailData['kodeStandard']) || 
                isset($detailData['cw1']) || 
                isset($detailData['cw2']) || 
                isset($detailData['cw3']) || 
                isset($detailData['ccw1']) || 
                isset($detailData['ccw2']) || 
                isset($detailData['ccw3'])
            );
            
            if ($hasData) {
                // Cari data existing berdasarkan calibration_id dan row_index
                $existingDetail = null;
                if (isset($detailData['id'])) {
                    $existingDetail = DetailTorqueMeter::where('id', $detailData['id'])
                        ->where('calibration_id', $calibration->id)
                        ->first();
                }
                
                if ($existingDetail) {
                    // UPDATE existing record - TANPA SANITIZE
                    $existingDetail->update([
                        'titikUkurBeban' => $detailData['titikUkurBeban'] ?? $existingDetail->titikUkurBeban,
                        'kodeStandard' => $detailData['kodeStandard'] ?? $existingDetail->kodeStandard,
                        'cw1' => $detailData['cw1'] ?? $existingDetail->cw1,
                        'cw2' => $detailData['cw2'] ?? $existingDetail->cw2,
                        'cw3' => $detailData['cw3'] ?? $existingDetail->cw3,
                        'ccw1' => $detailData['ccw1'] ?? $existingDetail->ccw1,
                        'ccw2' => $detailData['ccw2'] ?? $existingDetail->ccw2,
                        'ccw3' => $detailData['ccw3'] ?? $existingDetail->ccw3,
                    ]);
                    $updatedDetailCount++;
                    \Log::debug("📝 Updated detail row {$i} (ID: {$existingDetail->id})");
                } else {
                    // CREATE new record jika tidak ada - TANPA SANITIZE
                    DetailTorqueMeter::create([
                        'calibration_id' => $calibration->id,
                        'titikUkurBeban' => $detailData['titikUkurBeban'] ?? null,
                        'kodeStandard' => $detailData['kodeStandard'] ?? null,
                        'cw1' => $detailData['cw1'] ?? null,
                        'cw2' => $detailData['cw2'] ?? null,
                        'cw3' => $detailData['cw3'] ?? null,
                        'ccw1' => $detailData['ccw1'] ?? null,
                        'ccw2' => $detailData['ccw2'] ?? null,
                        'ccw3' => $detailData['ccw3'] ?? null,
                    ]);
                    $createdDetailCount++;
                    \Log::debug("➕ Created new detail row {$i}");
                }
                $detailCount++;
            }
        }

        \Log::info("✅ Detail data processed:", [
            'total_rows_processed' => $detailCount,
            'updated' => $updatedDetailCount,
            'created' => $createdDetailCount,
        ]);

        // ==================================================================
        // 4. UPDATE ADDITIONAL DATA (AddTorqueMeter) - TANPA SANITIZE
        // ==================================================================
        \Log::info('🔄 Processing additional data (update only)...');
        
        // Cari data additional yang sudah ada
        $addDataRecord = AddTorqueMeter::where('calibration_id', $calibration->id)->first();
        
        if ($addDataRecord) {
            // UPDATE existing additional data - TANPA SANITIZE
            $updateData = [];
            
            // Repeatability Clockwise
            if ($request->has('repCw01')) $updateData['repCw01'] = $request->repCw01;
            if ($request->has('repCw02')) $updateData['repCw02'] = $request->repCw02;
            if ($request->has('repCw03')) $updateData['repCw03'] = $request->repCw03;
            if ($request->has('repCw04')) $updateData['repCw04'] = $request->repCw04;
            if ($request->has('repCw05')) $updateData['repCw05'] = $request->repCw05;
            if ($request->has('repCw06')) $updateData['repCw06'] = $request->repCw06;
            if ($request->has('repCw07')) $updateData['repCw07'] = $request->repCw07;
            if ($request->has('repCw08')) $updateData['repCw08'] = $request->repCw08;
            if ($request->has('repCw09')) $updateData['repCw09'] = $request->repCw09;
            if ($request->has('repCw10')) $updateData['repCw10'] = $request->repCw10;
            
            // Repeatability Counter Clockwise
            if ($request->has('repCcw01')) $updateData['repCcw01'] = $request->repCcw01;
            if ($request->has('repCcw02')) $updateData['repCcw02'] = $request->repCcw02;
            if ($request->has('repCcw03')) $updateData['repCcw03'] = $request->repCcw03;
            if ($request->has('repCcw04')) $updateData['repCcw04'] = $request->repCcw04;
            if ($request->has('repCcw05')) $updateData['repCcw05'] = $request->repCcw05;
            if ($request->has('repCcw06')) $updateData['repCcw06'] = $request->repCcw06;
            if ($request->has('repCcw07')) $updateData['repCcw07'] = $request->repCcw07;
            if ($request->has('repCcw08')) $updateData['repCcw08'] = $request->repCcw08;
            if ($request->has('repCcw09')) $updateData['repCcw09'] = $request->repCcw09;
            if ($request->has('repCcw10')) $updateData['repCcw10'] = $request->repCcw10;
            
            // Radius
            if ($request->has('radiusAlatBantuSTD')) {
                $updateData['radiusAlatBantuSTD'] = $request->radiusAlatBantuSTD;
                \Log::info('📝 Updating radiusAlatBantuSTD:', ['value' => $request->radiusAlatBantuSTD]);
            }
            
            if ($request->has('kodeAlatBantuSTD')) {
                $updateData['kodeAlatBantuSTD'] = $request->kodeAlatBantuSTD;
                \Log::info('📝 Updating kodeAlatBantuSTD:', ['value' => $request->kodeAlatBantuSTD]);
            }
            
            if (!empty($updateData)) {
                $addDataRecord->update($updateData);
                \Log::info('✅ Additional data UPDATED:', [
                    'record_id' => $addDataRecord->id,
                    'updated_fields' => array_keys($updateData),
                    'radiusAlatBantuSTD_new' => $updateData['radiusAlatBantuSTD'] ?? 'not changed',
                    'kodeAlatBantuSTD_new' => $updateData['kodeAlatBantuSTD'] ?? 'not changed',
                ]);
            } else {
                \Log::info('⏭️ No changes to additional data');
            }
        } else {
            // CREATE new additional data jika tidak ada - TANPA SANITIZE
            $addData = [
                'calibration_id' => $calibration->id,
                'repCw01' => $request->repCw01 ?? null,
                'repCw02' => $request->repCw02 ?? null,
                'repCw03' => $request->repCw03 ?? null,
                'repCw04' => $request->repCw04 ?? null,
                'repCw05' => $request->repCw05 ?? null,
                'repCw06' => $request->repCw06 ?? null,
                'repCw07' => $request->repCw07 ?? null,
                'repCw08' => $request->repCw08 ?? null,
                'repCw09' => $request->repCw09 ?? null,
                'repCw10' => $request->repCw10 ?? null,
                'repCcw01' => $request->repCcw01 ?? null,
                'repCcw02' => $request->repCcw02 ?? null,
                'repCcw03' => $request->repCcw03 ?? null,
                'repCcw04' => $request->repCcw04 ?? null,
                'repCcw05' => $request->repCcw05 ?? null,
                'repCcw06' => $request->repCcw06 ?? null,
                'repCcw07' => $request->repCcw07 ?? null,
                'repCcw08' => $request->repCcw08 ?? null,
                'repCcw09' => $request->repCcw09 ?? null,
                'repCcw10' => $request->repCcw10 ?? null,
                'radiusAlatBantuSTD' => $request->radiusAlatBantuSTD ?? null,
                'kodeAlatBantuSTD' => $request->kodeAlatBantuSTD ?? null,
            ];
            
            $addDataRecord = AddTorqueMeter::create($addData);
            \Log::info('➕ Additional data CREATED:', [
                'record_id' => $addDataRecord->id,
                'radiusAlatBantuSTD' => $addData['radiusAlatBantuSTD'],
                'kodeAlatBantuSTD' => $addData['kodeAlatBantuSTD'],
            ]);
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION ADDITIONAL DATA (TANPA CERTIFICATE ID)
        // ==================================================================
        $updateCalibrationData = [];
        
        if ($request->filled('calibratedBy')) {
            $updateCalibrationData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateCalibrationData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateCalibrationData['uncertainty'] = $request->uncertainty;
            $updateCalibrationData['keterangan'] = $request->conclusion ?? '';
        }
        
        if ($request->filled('unit')) {
            $updateCalibrationData['unit'] = $request->unit;
        }
        
        if ($request->filled('temperature')) {
            $updateCalibrationData['temperature'] = $request->temperature;
        }
        
        if ($request->filled('humidity')) {
            $updateCalibrationData['humidity'] = $request->humidity;
        }
        
        // Kosongkan certificate_id di calibration (biar null, tidak dipakai)
        // Certificate ID hanya disimpan di HEAD saja
        $updateCalibrationData['certificate_id'] = null;
        
        if (!empty($updateCalibrationData)) {
            $calibration->update($updateCalibrationData);
            \Log::info('📝 Calibration additional data updated:', $updateCalibrationData);
        }

        // ==================================================================
        // 6. FINAL VERIFICATION
        // ==================================================================
        $finalDetailCount = DetailTorqueMeter::where('calibration_id', $calibration->id)->count();
        $finalAddCount = AddTorqueMeter::where('calibration_id', $calibration->id)->count();
        $finalAddData = AddTorqueMeter::where('calibration_id', $calibration->id)->first();
        $finalHead = HeadTorqueMeter::where('calibration_id', $calibration->id)->first();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'detail_records' => $finalDetailCount,
            'additional_records' => $finalAddCount,
            'head_record' => $finalHead ? 'Exists (ID: ' . $finalHead->id . ')' : 'Missing',
            'radiusAlatBantuSTD' => $finalAddData->radiusAlatBantuSTD ?? 'null',
            'kodeAlatBantuSTD' => $finalAddData->kodeAlatBantuSTD ?? 'null',
            'satuan_cw' => $finalHead->satuan_cw ?? 'null',
            'satuan_ccw' => $finalHead->satuan_ccw ?? 'null',
            'satuan_titikUkur' => $finalHead->satuan_titikUkur ?? 'null',
        ]);

        \Log::info('🎉 updateTorqueMeter COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTorqueMeter:', [
            'message' => $e->getMessage(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

        
        private function storeThicknessGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeThicknessGauge');
        \Log::info('📋 Request data keys:', array_keys($request->all()));
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // ==================================================================
        // 1. ALAT STANDAR - NILAI TETAP (TIDAK ADA INPUT DARI FORM)
        // ==================================================================
        $alatStandarValue = 'Gauge Block Set Grade 0';
        
        \Log::info('🔧 Alat standar (fixed value):', ['alat_standar' => $alatStandarValue, 'tab_id' => $tabId]);

        // ==================================================================
        // 2. SIMPAN KE HEAD THICKNESS GAUGE
        // ==================================================================
        $head = HeadThicknessGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarValue,
            'calibrationMethod' => 'PAS-IK1102-21',
            'satuan_unit' => $request->satuan_unit ?? null,
        ]);

        \Log::info('✅ HeadThicknessGauge saved:', ['head_id' => $head->id, 'standard' => $alatStandarValue]);

        // ==================================================================
        // 3. SIMPAN DETAIL MEASUREMENTS (17 NILAI: 0.0 - 50.0)
        // ==================================================================
        \Log::info('📊 Saving Thickness Gauge detail measurements...');
        $detailCount = 0;
        
        // Array mapping: nilai nominal asli => format field name di form
        $nominalMapping = [
            ['0.0', '0'],
            ['0.5', '0_5'],
            ['1.0', '1_0'],
            ['2.0', '2_0'],
            ['3.0', '3_0'],
            ['4.0', '4_0'],
            ['5.0', '5_0'],
            ['6.0', '6_0'],
            ['7.0', '7_0'],
            ['8.0', '8_0'],
            ['9.0', '9_0'],
            ['10.0', '10_0'],
            ['15.0', '15_0'],
            ['20.0', '20_0'],
            ['30.0', '30_0'],
            ['40.0', '40_0'],
            ['50.0', '50_0'],
        ];
        
        // Loop melalui semua nominal
        foreach ($nominalMapping as $mapping) {
            $nominal = $mapping[0];
            $fieldSuffix = $mapping[1];
            
            // 🔥 CARI DATA ULANGAN DENGAN ATAU TANPA _tab
            $ulangan01 = $this->getRequestValue($request, "ulangan_{$fieldSuffix}_1", $tabId);
            $ulangan02 = $this->getRequestValue($request, "ulangan_{$fieldSuffix}_2", $tabId);
            $ulangan03 = $this->getRequestValue($request, "ulangan_{$fieldSuffix}_3", $tabId);
            $ulangan04 = $this->getRequestValue($request, "ulangan_{$fieldSuffix}_4", $tabId);
            $ulangan05 = $this->getRequestValue($request, "ulangan_{$fieldSuffix}_5", $tabId);
            
            \Log::debug("📝 Data ulangan untuk nominal {$nominal} (field suffix: {$fieldSuffix}):", [
                'ulangan_1' => $ulangan01,
                'ulangan_2' => $ulangan02,
                'ulangan_3' => $ulangan03,
                'ulangan_4' => $ulangan04,
                'ulangan_5' => $ulangan05,
            ]);
            
            // Validasi: Simpan hanya jika ada minimal satu data ulangan
            $hasUlangan = !empty($ulangan01) || !empty($ulangan02) || !empty($ulangan03) || 
                         !empty($ulangan04) || !empty($ulangan05);
            
            if ($hasUlangan) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $nominal,
                    'ulangan01' => $ulangan01,
                    'ulangan02' => $ulangan02,
                    'ulangan03' => $ulangan03,
                    'ulangan04' => $ulangan04,
                    'ulangan05' => $ulangan05,
                ];
                
                \Log::info("💾 Saving detail for nominal {$nominal}:", $detailData);
                
                DetailThicknessGauge::create($detailData);
                $detailCount++;
                
                \Log::info("✅ Detail saved for nominal {$nominal}");
            } else {
                \Log::debug("⏭️ Skipping nominal {$nominal} - no ulangan data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Thickness Gauge");

        // ==================================================================
        // 4. UPDATE CALIBRATION
        // ==================================================================
        $updateData = [];
        
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if ($request->filled('tanggal_kalibrasi')) {
            $updateData['calibration_date'] = $request->tanggal_kalibrasi;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration data updated:', $updateData);
        }

        \Log::info('📋 STORE SUMMARY:', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $detailCount,
        ]);

        \Log::info('🎉 storeThicknessGauge COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeThicknessGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
        ]);
        throw $e;
    }
}

/**
 * Helper function untuk mengambil nilai dari request dengan atau tanpa _tab
 */
private function getRequestValue($request, $fieldName, $tabId)
{
    // Untuk tab 2+: JS merenaming field dari "buffer_1" -> "buffer_1_tab2"
    // Untuk tab 1: field tidak di-rename, tetap "buffer_1"
    
    // Coba dengan _tab suffix dulu (untuk tab 2+)
    if ($tabId && $tabId != 1) {
        $value = $request->input("{$fieldName}_tab{$tabId}");
        if ($value !== null) {
            return $value;
        }
        // Fallback: coba juga tanpa suffix (jika tab 1 konten yg sama)
        $value = $request->input($fieldName);
        if ($value !== null) {
            return $value;
        }
        // Fallback: coba dengan _tab1 suffix
        $value = $request->input("{$fieldName}_tab1");
        return $value;
    }
    
    // Untuk tab 1: coba tanpa suffix dulu
    $value = $request->input($fieldName);
    if ($value !== null) {
        return $value;
    }
    
    // Fallback: coba dengan _tab1 suffix (jika tab 1 di-rename)
    $value = $request->input("{$fieldName}_tab1");
    if ($value !== null) {
        return $value;
    }
    
    // Fallback: coba dengan _tab suffix
    $value = $request->input("{$fieldName}_tab{$tabId}");
    return $value;
}
        
        
        /**
         * Format nilai numerik - untuk handling koma/point
         */
   private function formatNumericValue($value)
{
    // Jika null atau empty string, return null
    if ($value === null || $value === '') {
        return null;
    }
    
    // Bersihkan spasi di awal dan akhir, tapi pertahankan karakter asli
    $value = trim($value);
    
    // Jika setelah trim masih empty, return null
    if ($value === '') {
        return null;
    }
    
    // Kembalikan apa adanya (string)
    return $value;
}
        
        /**
         * Update Thickness Gauge data - VERSI SIMPLE (ALAT STANDAR TETAP)
         */
      private function updateThicknessGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 ===== START updateThicknessGauge =====', [
            'calibration_id' => $calibration->id,
            'timestamp' => now()->toDateTimeString()
        ]);
        
        \Log::info('📋 Request data keys:', array_keys($request->all()));
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head thickness gauge untuk cek certificate_id
        $headThicknessGauge = $calibration->headThicknessGauge;
        $currentCertificateId = $headThicknessGauge->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE HEAD THICKNESS GAUGE - NILAI TETAP
        // ==================================================================
        $alatStandarValue = 'Gauge Block Set Grade 0'; // NILAI TETAP
        
        $headData = [
            'standard' => $alatStandarValue,
            'calibrationMethod' => 'PAS-IK1102-21',
            'satuan_unit' => $request->satuan_unit ?? null,
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        if ($headThicknessGauge) {
            $headThicknessGauge->update($headData);
            \Log::info('✅ HeadThicknessGauge updated', [
                'id' => $headThicknessGauge->id,
                'standard' => $alatStandarValue,
                'certificate_id' => $headThicknessGauge->certificate_id,
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
            
            $headThicknessGauge = HeadThicknessGauge::create($headData);
            \Log::info('➕ HeadThicknessGauge created baru', [
                'id' => $headThicknessGauge->id,
                'calibration_id' => $calibration->id,
                'certificate_id' => $headThicknessGauge->certificate_id
            ]);
        }

        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS (DELETE & RECREATE) - TANPA SANITIZE
        // ==================================================================
        \Log::info('🔄 Updating detail measurements...');
        
        // Hapus data detail lama
        $deletedCount = DetailThicknessGauge::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Data lama dihapus', ['deleted_count' => $deletedCount]);
        
        // Simpan data detail baru
        $detailCount = 0;
        
        // Mapping antara nilai nominal dan format field name di form
        $nominalMapping = [
            ['0.0', '0'],      // Field: ulangan_0_1, ulangan_0_2, dst.
            ['0.5', '0_5'],    // Field: ulangan_0_5_1, ulangan_0_5_2, dst.
            ['1.0', '1_0'],    // Field: ulangan_1_0_1, ulangan_1_0_2, dst.
            ['2.0', '2_0'],    // Field: ulangan_2_0_1, ulangan_2_0_2, dst.
            ['3.0', '3_0'],    // Field: ulangan_3_0_1, ulangan_3_0_2, dst.
            ['4.0', '4_0'],    // Field: ulangan_4_0_1, ulangan_4_0_2, dst.
            ['5.0', '5_0'],    // Field: ulangan_5_0_1, ulangan_5_0_2, dst.
            ['6.0', '6_0'],    // Field: ulangan_6_0_1, ulangan_6_0_2, dst.
            ['7.0', '7_0'],    // Field: ulangan_7_0_1, ulangan_7_0_2, dst.
            ['8.0', '8_0'],    // Field: ulangan_8_0_1, ulangan_8_0_2, dst.
            ['9.0', '9_0'],    // Field: ulangan_9_0_1, ulangan_9_0_2, dst.
            ['10.0', '10_0'],  // Field: ulangan_10_0_1, ulangan_10_0_2, dst.
            ['15.0', '15_0'],  // Field: ulangan_15_0_1, ulangan_15_0_2, dst.
            ['20.0', '20_0'],  // Field: ulangan_20_0_1, ulangan_20_0_2, dst.
            ['30.0', '30_0'],  // Field: ulangan_30_0_1, ulangan_30_0_2, dst.
            ['40.0', '40_0'],  // Field: ulangan_40_0_1, ulangan_40_0_2, dst.
            ['50.0', '50_0'],  // Field: ulangan_50_0_1, ulangan_50_0_2, dst.
        ];
        
        // Log untuk debugging
        \Log::info('🔍 CHECKING ULANGAN FIELDS FROM REQUEST:');
        foreach ($nominalMapping as $mapping) {
            $fieldSuffix = $mapping[1];
            for ($i = 1; $i <= 5; $i++) {
                $fieldName = "ulangan_{$fieldSuffix}_{$i}";
                $value = $request->input($fieldName);
                if (!empty($value)) {
                    \Log::info("  ✅ {$fieldName}: {$value}");
                }
            }
        }
        
        foreach ($nominalMapping as $mapping) {
            $nominal = $mapping[0]; // Nilai asli dengan titik: 0.0, 0.5, dst.
            $fieldSuffix = $mapping[1]; // Format untuk field name: 0, 0_5, 1_0, dst.
            
            // AMBIL DATA ULANGAN (5 kolom) - TANPA SANITIZE
            $ulangan01 = $request->input("ulangan_{$fieldSuffix}_1");
            $ulangan02 = $request->input("ulangan_{$fieldSuffix}_2");
            $ulangan03 = $request->input("ulangan_{$fieldSuffix}_3");
            $ulangan04 = $request->input("ulangan_{$fieldSuffix}_4");
            $ulangan05 = $request->input("ulangan_{$fieldSuffix}_5");
            
            \Log::debug("📝 Data untuk nominal {$nominal} (field: {$fieldSuffix}):", [
                'ulangan_1' => $ulangan01,
                'ulangan_2' => $ulangan02,
                'ulangan_3' => $ulangan03,
                'ulangan_4' => $ulangan04,
                'ulangan_5' => $ulangan05,
            ]);
            
            // Validasi: Simpan hanya jika ada minimal satu data ulangan
            $hasUlangan = !empty($ulangan01) || !empty($ulangan02) || !empty($ulangan03) || 
                         !empty($ulangan04) || !empty($ulangan05);
            
            if ($hasUlangan) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $nominal, // Simpan nilai asli dengan titik
                    'ulangan01' => $ulangan01, // Langsung simpan tanpa format
                    'ulangan02' => $ulangan02,
                    'ulangan03' => $ulangan03,
                    'ulangan04' => $ulangan04,
                    'ulangan05' => $ulangan05,
                ];
                
                \Log::info("💾 Saving detail for nominal {$nominal}:", $detailData);
                
                DetailThicknessGauge::create($detailData);
                $detailCount++;
                
                \Log::info("✅ Detail saved for nominal {$nominal}");
            } else {
                \Log::debug("⏭️ Skipping nominal {$nominal} - no ulangan data");
            }
        }
        
        \Log::info('✅ Detail measurements updated', ['total_records' => $detailCount]);

        // ==================================================================
        // 3. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TANPA CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Nama untuk TTD Dikalibrasi
        if ($request->filled('nama_dikalibrasi')) {
            $updateData['calibrated_by'] = $request->nama_dikalibrasi;
            \Log::info('📝 Nama dikalibrasi updated:', ['nama' => $request->nama_dikalibrasi]);
        }
        
        // Nama untuk TTD Diperiksa
        if ($request->filled('nama_diperiksa')) {
            $updateData['verified_by'] = $request->nama_diperiksa;
            \Log::info('📝 Nama diperiksa updated:', ['nama' => $request->nama_diperiksa]);
        }
        
        // Tanggal Dikalibrasi
        if ($request->filled('tanggal_kalibrasi')) {
            $updateData['calibration_date'] = $request->tanggal_kalibrasi;
            \Log::info('📅 Tanggal dikalibrasi updated:', ['tanggal' => $request->tanggal_kalibrasi]);
        }
        
        // Tanggal Diperiksa
        if ($request->filled('tanggal_diperiksa')) {
            $updateData['verification_date'] = $request->tanggal_diperiksa;
            \Log::info('📅 Tanggal diperiksa updated:', ['tanggal' => $request->tanggal_diperiksa]);
        }
        
        // Uncertainty dan kesimpulan - TANPA SANITIZE
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
            \Log::info('📊 Uncertainty updated:', ['uncertainty' => $updateData['uncertainty']]);
        }
        
        // Status kalibrasi
        if ($request->filled('status')) {
            $updateData['status'] = $request->status;
            \Log::info('📈 Status updated:', ['status' => $request->status]);
        }
        
        // Kosongkan certificate_id di calibration (biar null, tidak dipakai)
        // Certificate ID hanya disimpan di HEAD saja
        $updateData['certificate_id'] = null;
        
        // Update calibration data
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration data updated:', $updateData);
        }

        // ==================================================================
        // 4. HANDLE TTD (TANDA TANGAN) - Jika ada di request
        // ==================================================================
        // TTD Dikalibrasi
        if ($request->filled('ttd_dikalibrasi') && strpos($request->ttd_dikalibrasi, 'data:image') === 0) {
            try {
                $ttdImage = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $request->ttd_dikalibrasi));
                $ttdFileName = 'ttd_dikalibrasi_' . $calibration->id . '_' . time() . '.png';
                
                Storage::disk('public')->put('ttd/' . $ttdFileName, $ttdImage);
                
                $calibration->update(['ttd_calibrated' => 'ttd/' . $ttdFileName]);
                \Log::info('💾 TTD dikalibrasi saved:', ['filename' => $ttdFileName]);
            } catch (\Exception $e) {
                \Log::error('❌ Failed to save TTD dikalibrasi:', ['error' => $e->getMessage()]);
            }
        }
        
        // TTD Diperiksa
        if ($request->filled('ttd_diperiksa') && strpos($request->ttd_diperiksa, 'data:image') === 0) {
            try {
                $ttdImage = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $request->ttd_diperiksa));
                $ttdFileName = 'ttd_diperiksa_' . $calibration->id . '_' . time() . '.png';
                
                Storage::disk('public')->put('ttd/' . $ttdFileName, $ttdImage);
                
                $calibration->update(['ttd_verified' => 'ttd/' . $ttdFileName]);
                \Log::info('💾 TTD diperiksa saved:', ['filename' => $ttdFileName]);
            } catch (\Exception $e) {
                \Log::error('❌ Failed to save TTD diperiksa:', ['error' => $e->getMessage()]);
            }
        }

        // ==================================================================
        // 5. FINAL VERIFICATION
        // ==================================================================
        $finalDetailCount = DetailThicknessGauge::where('calibration_id', $calibration->id)->count();
        $finalHead = HeadThicknessGauge::where('calibration_id', $calibration->id)->first();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'head_id' => $headThicknessGauge->id,
            'detail_records' => $finalDetailCount,
            'standard' => $alatStandarValue,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        // ==================================================================
        // 6. VALIDASI AKHIR
        // ==================================================================
        $savedDetails = DetailThicknessGauge::where('calibration_id', $calibration->id)
            ->select('titikUkur', 'ulangan01', 'ulangan02', 'ulangan03', 'ulangan04', 'ulangan05')
            ->get()
            ->toArray();
        
        \Log::info('🔍 FINAL VALIDATION - Saved details:', $savedDetails);

        \Log::info('🎉 updateThicknessGauge COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateThicknessGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        
        throw new \Exception("Gagal mengupdate data Thickness Gauge: " . $e->getMessage());
    }
}

       private function storePenggaris($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        $alatStandarValue = 'Reading Glass Scale, Metrology, OP-RS410/A';
        \Log::info('🔧 Alat standar selected:', ['alat_standar' => $alatStandarValue, 'tab_id' => $tabId]);

        // Simpan ke Head Penggaris
        $head = HeadPenggaris::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarValue,
            'calibrationMethod' => 'PAS-IK1102-28',
            'satuan_unit' => $request->satuan_unit ?? null,
        ]);

        \Log::info('✅ Head Penggaris saved:', ['head_id' => $head->id]);

        // ==================================================================
        // SIMPAN DETAIL MEASUREMENTS (DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving detail measurements...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 16; $i++) {
            // 🔥 CARI NOMINAL DENGAN ATAU TANPA _tab
            $nominal = $this->getRequestValue($request, "nominal_{$i}", $tabId);
            
            if (!empty($nominal)) {
                // 🔥 CARI PENUNJUKAN DENGAN ATAU TANPA _tab
                $penunjukan1 = $this->getRequestValue($request, "penunjukan_{$i}_1", $tabId);
                $penunjukan2 = $this->getRequestValue($request, "penunjukan_{$i}_2", $tabId);
                $penunjukan3 = $this->getRequestValue($request, "penunjukan_{$i}_3", $tabId);
                $penunjukan4 = $this->getRequestValue($request, "penunjukan_{$i}_4", $tabId);
                $penunjukan5 = $this->getRequestValue($request, "penunjukan_{$i}_5", $tabId);
                
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $nominal,
                    'ulangan01' => $penunjukan1,
                    'ulangan02' => $penunjukan2,
                    'ulangan03' => $penunjukan3,
                    'ulangan04' => $penunjukan4,
                    'ulangan05' => $penunjukan5,
                ];

                \Log::info("📝 Saving detail row {$i}:", $detailData);
                
                DetailPenggaris::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping row {$i} - no nominal value");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements");
        
        // ==================================================================
        // UPDATE CALIBRATION
        // ==================================================================
        $updateData = [];
        
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration data updated:', $updateData);
        }
        
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 Error storing Penggaris data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A'
        ]);
        throw $e;
    }
}



       private function updatePenggaris($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 ===== START updatePenggaris =====', [
            'calibration_id' => $calibration->id,
            'timestamp'      => now()->toDateTimeString()
        ]);

        \Log::info('📋 Request data keys:', array_keys($request->all()));

        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru    = $newCertificateId;
        $certificateIdUpdated = false;

        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;

        $headPenggaris        = $calibration->headPenggaris;
        $currentCertificateId = $headPenggaris->certificate_id ?? null;

        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat    = $originalCalibration->namaAlat;

        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request'       => $namaAlatDariRequest,
            'original_nama_alat'          => $originalNamaAlat,
            'current_nama_alat'           => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId,
        ]);

        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru    = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;

            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama'          => $originalNamaAlat,
                'new_nama'          => $namaAlatDariRequest,
                'old_certificate_id'=> $currentCertificateId,
                'new_certificate_id'=> $certificateIdBaru,
            ]);
        } elseif (empty($currentCertificateId)) {
            $certificateIdBaru    = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;

            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru,
            ]);
        }

        // ==================================================================
        // 1. UPDATE HEAD PENGGARIS
        // ==================================================================
        $alatStandarValue = 'Reading Glass Scale, Metrology, OP-RS410/A'; // NILAI TETAP

        $headData = [
            'standard'          => $alatStandarValue,
            'calibrationMethod' => 'PAS-IK1102-28',
            'satuan_unit'       => $request->satuan_unit ?? null,
        ];

        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }

        if ($headPenggaris) {
            $headPenggaris->update($headData);
            \Log::info('✅ HeadPenggaris updated', [
                'id'             => $headPenggaris->id,
                'standard'       => $alatStandarValue,
                'certificate_id' => $headPenggaris->certificate_id,
            ]);
        } else {
            $headData['calibration_id']  = $calibration->id;
            $headData['certificate_id']  = $headData['certificate_id']
                ?? $certificateIdBaru
                ?? $calibration->certificate_id
                ?? 'NEW-' . time();

            $headPenggaris = HeadPenggaris::create($headData);
            \Log::info('➕ HeadPenggaris created baru', [
                'id'             => $headPenggaris->id,
                'calibration_id' => $calibration->id,
                'certificate_id' => $headPenggaris->certificate_id,
            ]);
        }

        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS (16 BARIS) — UPDATE OR CREATE
        //    (TIDAK ADA delete() massal, data lama dipertahankan)
        // ==================================================================
        \Log::info('🔄 Updating detail measurements (16 baris) dengan updateOrCreate...');

        DB::transaction(function () use ($request, $calibration) {

            // Field nama sesuai form: titik_ukur_X & ulangan0N_X
            $titikDipakai = [];
            $savedCount   = 0;

            for ($i = 1; $i <= 16; $i++) {

                $nominalField = "titik_ukur_$i";
                $nominalValue = $request->$nominalField;

                \Log::debug("Checking row {$i}:", [
                    'field'     => $nominalField,
                    'value'     => $nominalValue,
                    'has_value' => !empty($nominalValue),
                ]);

                if (empty($nominalValue)) {
                    \Log::debug("⏭️ Skipping row {$i} - empty nominal");
                    continue;
                }

                $titikDipakai[] = $nominalValue;

                $payload = [
                    'ulangan01' => $request->{"ulangan01_$i"} ?? null,
                    'ulangan02' => $request->{"ulangan02_$i"} ?? null,
                    'ulangan03' => $request->{"ulangan03_$i"} ?? null,
                    'ulangan04' => $request->{"ulangan04_$i"} ?? null,
                    'ulangan05' => $request->{"ulangan05_$i"} ?? null,
                ];

                \Log::info("💾 updateOrCreate detail row {$i}:", [
                    'calibration_id' => $calibration->id,
                    'titikUkur'      => $nominalValue,
                    'payload'        => $payload,
                ]);

                DetailPenggaris::updateOrCreate(
                    [
                        'calibration_id' => $calibration->id,
                        'titikUkur'      => $nominalValue,
                    ],
                    $payload
                );

                $savedCount++;
            }

            // Hapus HANYA baris yang benar-benar tidak dipakai lagi,
            // dan HANYA jika ada minimal 1 titik valid di request.
            if (!empty($titikDipakai)) {

                $deletedCount = DetailPenggaris::where('calibration_id', $calibration->id)
                    ->whereNotIn('titikUkur', $titikDipakai)
                    ->delete();

                \Log::info('🧹 Hapus baris yang tidak dipakai lagi:', [
                    'deleted_count'   => $deletedCount,
                    'titik_dipakai'   => $titikDipakai,
                ]);
            } else {
                // SAFETY: request tidak punya titik valid → JANGAN hapus apapun
                \Log::warning('⚠️ Tidak ada titik ukur valid di request. Data lama dipertahankan utuh.');
            }

            \Log::info("✅ Saved {$savedCount} detail measurements (updateOrCreate)");
        });

        // ==================================================================
        // 3. UPDATE CALIBRATION UNIT (fix: satuan_unit, bukan unit)
        // ==================================================================
        if ($request->filled('satuan_unit')) {
            $calibration->update(['unit' => $request->satuan_unit]);
            \Log::info('📏 Unit updated:', ['unit' => $request->satuan_unit]);
        }

        // ==================================================================
        // 4. UPDATE DATA TAMBAHAN (TTD, NAMA, DLL) — TANPA CERTIFICATE ID
        // ==================================================================
        $updateData = [];

        if ($request->filled('nama_dikalibrasi')) {
            $updateData['calibrated_by'] = $request->nama_dikalibrasi;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->nama_dikalibrasi]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
            \Log::info('📝 Nama dikalibrasi (dari calibratedBy):', ['nama' => $request->calibratedBy]);
        }

        if ($request->filled('tanggal_dikalibrasi')) {
            $updateData['calibration_date'] = $request->tanggal_dikalibrasi;
            \Log::info('📅 Tanggal dikalibrasi:', ['tanggal' => $request->tanggal_dikalibrasi]);
        }

        if ($request->filled('nama_diperiksa')) {
            $updateData['verified_by'] = $request->nama_diperiksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->nama_diperiksa]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
            \Log::info('📝 Nama diperiksa (dari verifiedBy):', ['nama' => $request->verifiedBy]);
        }

        if ($request->filled('tanggal_diperiksa')) {
            $updateData['verification_date'] = $request->tanggal_diperiksa;
            \Log::info('📅 Tanggal diperiksa:', ['tanggal' => $request->tanggal_diperiksa]);
        }

        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan']  = $request->conclusion ?? '';
            \Log::info('📊 Uncertainty updated:', ['uncertainty' => $updateData['uncertainty']]);
        }

        if ($request->filled('status')) {
            $updateData['status'] = $request->status;
            \Log::info('📈 Status updated:', ['status' => $request->status]);
        }

        // Certificate ID hanya disimpan di HEAD saja
        $updateData['certificate_id'] = null;

        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration data updated:', $updateData);
        }

        // ==================================================================
        // 5. HANDLE TANDA TANGAN (TTD)
        // ==================================================================
        if ($request->filled('ttd_dikalibrasi') && strpos($request->ttd_dikalibrasi, 'data:image') === 0) {
            try {
                $ttdImage    = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $request->ttd_dikalibrasi));
                $ttdFileName = 'ttd_dikalibrasi_' . $calibration->id . '_' . time() . '.png';

                Storage::disk('public')->put('ttd/' . $ttdFileName, $ttdImage);
                $calibration->update(['ttd_calibrated' => 'ttd/' . $ttdFileName]);

                \Log::info('💾 TTD dikalibrasi saved:', ['filename' => $ttdFileName]);
            } catch (\Exception $e) {
                \Log::error('❌ Failed to save TTD dikalibrasi:', ['error' => $e->getMessage()]);
            }
        }

        if ($request->filled('ttd_diperiksa') && strpos($request->ttd_diperiksa, 'data:image') === 0) {
            try {
                $ttdImage    = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $request->ttd_diperiksa));
                $ttdFileName = 'ttd_diperiksa_' . $calibration->id . '_' . time() . '.png';

                Storage::disk('public')->put('ttd/' . $ttdFileName, $ttdImage);
                $calibration->update(['ttd_verified' => 'ttd/' . $ttdFileName]);

                \Log::info('💾 TTD diperiksa saved:', ['filename' => $ttdFileName]);
            } catch (\Exception $e) {
                \Log::error('❌ Failed to save TTD diperiksa:', ['error' => $e->getMessage()]);
            }
        }

        // ==================================================================
        // 6. FINAL VERIFICATION
        // ==================================================================
        $finalDetailCount = DetailPenggaris::where('calibration_id', $calibration->id)->count();
        $finalHead        = HeadPenggaris::where('calibration_id', $calibration->id)->first();

        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id'         => $calibration->id,
            'certificate_id_head'    => $finalHead->certificate_id ?? 'TIDAK ADA',
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id'     => $certificateIdBaru,
            'head_id'                => $headPenggaris->id,
            'detail_records'         => $finalDetailCount,
            'standard'               => $alatStandarValue,
            'unit'                   => $calibration->unit ?? null,
            'calibrated_by'          => $calibration->calibrated_by ?? null,
            'verified_by'            => $calibration->verified_by ?? null,
        ]);

        // ==================================================================
        // 7. VALIDASI AKHIR
        // ==================================================================
        $savedDetails = DetailPenggaris::where('calibration_id', $calibration->id)
            ->select('titikUkur', 'ulangan01', 'ulangan02', 'ulangan03', 'ulangan04', 'ulangan05')
            ->get()
            ->toArray();

        \Log::info('🔍 FINAL VALIDATION - Saved details:', $savedDetails);

        \Log::info('🎉 updatePenggaris COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePenggaris:', [
            'message'        => $e->getMessage(),
            'file'           => $e->getFile(),
            'line'           => $e->getLine(),
            'trace'          => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);

        throw new \Exception("Gagal mengupdate data Penggaris: " . $e->getMessage());
    }
}
