private function storeEnclosure($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeEnclosure - MULTIPLE REPETITION (CUSTOM INTERVAL)');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // ==================================================================
        // 1. TENTUKAN JUMLAH PENGULANGAN
        // ==================================================================
        $defaultIntervalKeys = [1, 2, 3, 4, 5, 13, 20, 30]; // hanya sebagai KEY loop
        
        $repetition = 0;
        for ($i = 1; $i <= 3; $i++) {
            $hasData = false;
            
            if ($this->getRequestValue($request, "suhu_setting_{$i}", $tabId)) {
                $hasData = true;
            }
            
            if (!$hasData) {
                foreach ($defaultIntervalKeys as $key) {
                    $alatField = $this->getRequestValue($request, "alat_{$i}_{$key}", $tabId);
                    if ($alatField) {
                        $hasData = true;
                        break;
                    }
                    
                    for ($s = 1; $s <= 9; $s++) {
                        $sensorField = $this->getRequestValue($request, "sensor_{$i}_{$key}_{$s}", $tabId);
                        if ($sensorField) {
                            $hasData = true;
                            break 2;
                        }
                    }
                }
            }
            
            if ($hasData) {
                $repetition = $i;
            }
        }
        
        if ($repetition === 0) {
            $repetition = 1;
        }
        
        \Log::info('📊 Jumlah pengulangan DITENTUKAN:', ['repetition' => $repetition]);
        
        // ==================================================================
        // 2. PROSES ALAT STANDAR
        // ==================================================================
        $textValue = trim($request->alat_standar_text ?? '');
        $arrayValue = $request->input('alat_standar', []);
        
        if (!empty($textValue)) {
            $standardValue = $textValue;
        } elseif (is_array($arrayValue) && count($arrayValue) > 0) {
            $standardValue = implode("\n", $arrayValue);
        } else {
            $standardValue = '';
        }
        
        // ==================================================================
        // 3. SIMPAN KE HEAD ENCLOSURE
        // ==================================================================
        $head = HeadEnclosure::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-29',
        ]);
        
        // ==================================================================
        // 3b. SIMPAN GAMBAR CANVAS
        // ==================================================================
        $kanvasBase64 = $request->input('keterangan_gambar', '');
        if (!empty($kanvasBase64) && strpos($kanvasBase64, 'data:image') === 0) {
            try {
                $imgFolder = public_path('img_Enclosure');
                if (!file_exists($imgFolder)) {
                    mkdir($imgFolder, 0755, true);
                }
                $imgData = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $kanvasBase64));
                $imgFileName = 'enclosure_' . $calibration->id . '_' . time() . '.png';
                $imgPath = $imgFolder . DIRECTORY_SEPARATOR . $imgFileName;
                file_put_contents($imgPath, $imgData);
                $head->update(['keterangan_gambar' => 'img_Enclosure/' . $imgFileName]);
            } catch (\Exception $e) {
                \Log::error('❌ Gagal simpan gambar canvas enclosure:', ['error' => $e->getMessage()]);
            }
        }
        
        // ==================================================================
        // 4. SIMPAN KE ADD ENCLOSURE + DETAIL (INTERVAL DARI INPUT)
        // ==================================================================
        $totalDetailCount = 0;
        
        for ($p = 1; $p <= $repetition; $p++) {
            $tsettingValue = $this->getRequestValue($request, "suhu_setting_{$p}", $tabId);
            
            // --- Kumpulkan interval dari input (custom, bisa berubah) ---
            $intervalsForThisRep = [];
            $intervalMapping = []; // key => nilai interval final
            
            foreach ($defaultIntervalKeys as $key) {
                $rawInterval = $this->getRequestValue($request, "interval_{$p}_{$key}", $tabId);
                
                // Jika user kosongkan, fallback ke key default
                if ($rawInterval === null || trim($rawInterval) === '') {
                    $intervalVal = $key;
                } else {
                    // Normalisasi: hanya angka
                    $intervalVal = (int) preg_replace('/[^0-9]/', '', trim($rawInterval));
                    if ($intervalVal <= 0) {
                        $intervalVal = $key;
                    }
                }
                
                $intervalMapping[$key] = $intervalVal;
                $intervalsForThisRep[] = $intervalVal;
            }
            
            // Sort ascending & unique untuk disimpan di JSON AddEnclosure
            $intervalsForThisRep = array_values(array_unique($intervalsForThisRep));
            sort($intervalsForThisRep, SORT_NUMERIC);
            
            $intervalJson = json_encode($intervalsForThisRep);
            
            \Log::info("📝 Repetition {$p} interval final:", [
                'mapping' => $intervalMapping,
                'json_saved' => $intervalJson,
            ]);
            
            // --- Simpan AddEnclosure ---
            try {
                AddEnclosure::create([
                    'calibration_id' => $calibration->id,
                    'head_enclosure_id' => $head->id,
                    'repetition_number' => $p,
                    'Tsetting' => $tsettingValue,
                    'Interval' => $intervalJson,
                ]);
            } catch (\Exception $e) {
                \Log::error("❌ AddEnclosure save failed for repetition {$p}:", [
                    'error' => $e->getMessage(),
                ]);
            }
            
            // --- Simpan DetailEnclosure per interval custom ---
            $detailCount = 0;
            
            foreach ($defaultIntervalKeys as $key) {
                $intervalVal = $intervalMapping[$key];
                
                $alatValue = $this->getRequestValue($request, "alat_{$p}_{$key}", $tabId);
                $hasAlatData = !empty($alatValue);
                
                $sensorData = [];
                $hasSensorData = false;
                
                for ($col = 1; $col <= 9; $col++) {
                    $rawValue = $this->getRequestValue($request, "sensor_{$p}_{$key}_{$col}", $tabId);
                    
                    if (!empty($rawValue)) {
                        $sensorData[$col] = str_replace(',', '.', $rawValue);
                        $hasSensorData = true;
                    } else {
                        $sensorData[$col] = null;
                    }
                }
                
                if ($hasAlatData || $hasSensorData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'head_enclosure_id' => $head->id,
                        'repetition_number' => $p,
                        'interval_number' => $intervalVal, // ← interval custom dari input
                        'readAlat' => $hasAlatData ? str_replace(',', '.', $alatValue) : null,
                        'readSensor1' => $sensorData[1] ?? null,
                        'readSensor2' => $sensorData[2] ?? null,
                        'readSensor3' => $sensorData[3] ?? null,
                        'readSensor4' => $sensorData[4] ?? null,
                        'readSensor5' => $sensorData[5] ?? null,
                        'readSensor6' => $sensorData[6] ?? null,
                        'readSensor7' => $sensorData[7] ?? null,
                        'readSensor8' => $sensorData[8] ?? null,
                        'readSensor9' => $sensorData[9] ?? null,
                    ];
                    
                    try {
                        DetailEnclosure::create($detailData);
                        $detailCount++;
                        $totalDetailCount++;
                    } catch (\Exception $e) {
                        \Log::error("❌ DetailEnclosure save failed:", [
                            'repetition' => $p,
                            'key' => $key,
                            'interval' => $intervalVal,
                            'error' => $e->getMessage(),
                        ]);
                    }
                }
            }
            
            \Log::info("✅ Saved {$detailCount} DetailEnclosure records for repetition {$p}");
        }
        
        \Log::info("✅ Saved {$totalDetailCount} DetailEnclosure records total (for {$repetition} repetitions)");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION
        // ==================================================================
        $updateData = [];
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        if (!empty($updateData)) {
            $calibration->update($updateData);
        }
        
        \Log::info('🎉 storeEnclosure COMPLETED (Custom Interval)');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeEnclosure:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
        ]);
        throw $e;
    }
}

public function updateEnclosure($request, $calibration)
{
    \Log::info('🚀 START updateEnclosure - UPDATE IN-PLACE (NO DELETE, NO NEW COLUMN)');

    $defaultIntervalKeys = [1, 2, 3, 4, 5, 13, 20, 30]; // slot key default

    // 1. ALAT STANDAR
    $arrayValue = $request->input('standard_list', []);
    if (is_array($arrayValue) && count($arrayValue) > 0) {
        $standardValue = implode("\n", $arrayValue);
    } else {
        $headEnclosure = HeadEnclosure::where('calibration_id', $calibration->id)->first();
        $standardValue = $headEnclosure->standard ?? '';
    }

    // 2. CERTIFICATE ID
    $certificateId = $this->generateCertificateId($calibration->namaAlat ?? 'Unknown', $calibration);

    // 3. HEAD ENCLOSURE
    $headEnclosure = HeadEnclosure::updateOrCreate(
        ['calibration_id' => $calibration->id],
        [
            'certificate_id' => $certificateId,
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-29 (SNSU PK.P-29:2020)',
        ]
    );

    // 3b. GAMBAR CANVAS
    $kanvasBase64 = $request->input('keterangan_gambar', '');
    if (!empty($kanvasBase64) && strpos($kanvasBase64, 'data:image') === 0) {
        try {
            $imgFolder = public_path('img_Enclosure');
            if (!file_exists($imgFolder)) mkdir($imgFolder, 0755, true);
            $oldImg = $headEnclosure->keterangan_gambar ?? null;
            if ($oldImg && file_exists(public_path($oldImg))) @unlink(public_path($oldImg));
            $imgData = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $kanvasBase64));
            $imgFileName = 'enclosure_' . $calibration->id . '_' . time() . '.png';
            file_put_contents($imgFolder . DIRECTORY_SEPARATOR . $imgFileName, $imgData);
            $headEnclosure->update(['keterangan_gambar' => 'img_Enclosure/' . $imgFileName]);
        } catch (\Exception $e) {
            \Log::error('❌ Gagal update gambar canvas:', ['error' => $e->getMessage()]);
        }
    }

    // 4. TENTUKAN REPETITION
    $maxRepetitionFromInput = 0;
    for ($i = 1; $i <= 10; $i++) {
        if ($request->has("suhu_setting_$i") && !empty(trim($request->input("suhu_setting_$i")))) {
            $maxRepetitionFromInput = $i;
        }
    }
    if ($maxRepetitionFromInput === 0) {
        $repetition = AddEnclosure::where('calibration_id', $calibration->id)->max('repetition_number') ?? 1;
    } else {
        $repetition = $maxRepetitionFromInput;
    }
    \Log::info('📊 Repetition:', ['repetition' => $repetition]);

    // 5. ADDENCLOSURE
    for ($p = 1; $p <= $repetition; $p++) {
        $tsettingValue = null;
        $hasInput = false;

        if ($request->has("suhu_setting_$p") && !empty(trim($request->input("suhu_setting_$p")))) {
            $tsettingValue = trim($request->input("suhu_setting_$p"));
            $hasInput = true;
        }
        if (!$hasInput) {
            $existing = AddEnclosure::where('calibration_id', $calibration->id)
                ->where('repetition_number', $p)->first();
            if ($existing) {
                $tsettingValue = $existing->TSetting ?? $existing->Tsetting ?? null;
            }
        }

        // JSON interval custom (dari input)
        $intervalsForRep = [];
        foreach ($defaultIntervalKeys as $key) {
            $raw = $request->input("interval_{$p}_{$key}", $key);
            $val = (int) preg_replace('/[^0-9]/', '', trim($raw));
            if ($val <= 0) $val = $key;
            $intervalsForRep[] = $val;
        }
        $intervalsForRep = array_values(array_unique($intervalsForRep));
        sort($intervalsForRep, SORT_NUMERIC);

        AddEnclosure::updateOrCreate(
            ['calibration_id' => $calibration->id, 'repetition_number' => $p],
            [
                'Interval' => json_encode($intervalsForRep),
                'TSetting' => $tsettingValue,
                'Tsetting' => $tsettingValue,
            ]
        );
    }

    // Hapus repetition ekstra (jika user kurangi repetition) — ini bukan "data lama yang diganti"
    if ($repetition > 0) {
        AddEnclosure::where('calibration_id', $calibration->id)
            ->where('repetition_number', '>', $repetition)->delete();
        DetailEnclosure::where('calibration_id', $calibration->id)
            ->where('repetition_number', '>', $repetition)->delete();
    }

    // ==================================================================
    // 6. DETAIL ENCLOSURE — UPDATE IN-PLACE BERDASARKAN URUTAN SLOT
    // ==================================================================
    $totalUpdated = 0;
    $totalCreated = 0;

    for ($p = 1; $p <= $repetition; $p++) {

        // --- Ambil record lama untuk repetition ini, urutkan ascending by interval_number ---
        $oldRecords = DetailEnclosure::where('calibration_id', $calibration->id)
            ->where('repetition_number', $p)
            ->orderBy('interval_number', 'asc')
            ->orderBy('id', 'asc')
            ->get()
            ->values(); // index 0..N-1

        // --- Bangun payload input per slot key, urutkan sesuai key default ---
        $inputPayloads = []; // [ ['interval' => x, 'alat' => y, 'sensors' => [...], 'hasData' => bool], ... ]

        foreach ($defaultIntervalKeys as $key) {
            $raw = $request->input("interval_{$p}_{$key}", $key);
            $intervalVal = (int) preg_replace('/[^0-9]/', '', trim($raw));
            if ($intervalVal <= 0) $intervalVal = $key;

            $alatValue = null;
            $hasData = false;
            $alatField = "alat_{$p}_{$key}";
            if ($request->has($alatField) && !empty(trim($request->input($alatField)))) {
                $alatValue = str_replace(',', '.', trim($request->input($alatField)));
                $hasData = true;
            }

            $sensorData = [];
            for ($col = 1; $col <= 9; $col++) {
                $f = "sensor_{$p}_{$key}_{$col}";
                $v = null;
                if ($request->has($f) && !empty(trim($request->input($f)))) {
                    $v = str_replace(',', '.', trim($request->input($f)));
                    $hasData = true;
                }
                $sensorData[$col] = $v;
            }

            $inputPayloads[] = [
                'interval' => $intervalVal,
                'alat' => $alatValue,
                'sensors' => $sensorData,
                'hasData' => $hasData,
            ];
        }

        // --- Cocokkan posisi: payload ke-i ↔ record lama ke-i ---
        $count = count($inputPayloads);
        for ($i = 0; $i < $count; $i++) {
            $payload = $inputPayloads[$i];
            $oldRecord = $oldRecords[$i] ?? null;

            // KASUS 1: Belum ada record lama di posisi ini → buat baru (hanya jika ada data)
            if (!$oldRecord) {
                if ($payload['hasData']) {
                    DetailEnclosure::create([
                        'calibration_id' => $calibration->id,
                        'head_enclosure_id' => $headEnclosure->id,
                        'repetition_number' => $p,
                        'interval_number' => $payload['interval'],
                        'readAlat' => $payload['alat'],
                        'readSensor1' => $payload['sensors'][1] ?? null,
                        'readSensor2' => $payload['sensors'][2] ?? null,
                        'readSensor3' => $payload['sensors'][3] ?? null,
                        'readSensor4' => $payload['sensors'][4] ?? null,
                        'readSensor5' => $payload['sensors'][5] ?? null,
                        'readSensor6' => $payload['sensors'][6] ?? null,
                        'readSensor7' => $payload['sensors'][7] ?? null,
                        'readSensor8' => $payload['sensors'][8] ?? null,
                        'readSensor9' => $payload['sensors'][9] ?? null,
                    ]);
                    $totalCreated++;
                }
                continue;
            }

            // KASUS 2: Record lama ada di posisi ini → UPDATE in-place
            if (!$payload['hasData']) {
                // User kosongkan data slot ini: JANGAN hapus. Hanya update interval_number jika berubah.
                if ((int) $oldRecord->interval_number !== (int) $payload['interval']) {
                    $oldRecord->update(['interval_number' => $payload['interval']]);
                    $totalUpdated++;
                }
                continue;
            }

            // Update semua field pada record lama (termasuk interval_number jika diedit)
            $oldRecord->update([
                'interval_number' => $payload['interval'],
                'readAlat' => $payload['alat'],
                'readSensor1' => $payload['sensors'][1] ?? null,
                'readSensor2' => $payload['sensors'][2] ?? null,
                'readSensor3' => $payload['sensors'][3] ?? null,
                'readSensor4' => $payload['sensors'][4] ?? null,
                'readSensor5' => $payload['sensors'][5] ?? null,
                'readSensor6' => $payload['sensors'][6] ?? null,
                'readSensor7' => $payload['sensors'][7] ?? null,
                'readSensor8' => $payload['sensors'][8] ?? null,
                'readSensor9' => $payload['sensors'][9] ?? null,
            ]);
            $totalUpdated++;
        }

        // KASUS 3: Record lama lebih banyak dari payload (data ekstra di DB, bukan dari form)
        // Sesuai permintaan "jangan hapus data lama" → biarkan. Hanya di-log.
        if ($oldRecords->count() > $count) {
            \Log::warning("⚠️ Repetition {$p}: ada " . ($oldRecords->count() - $count) .
                " record detail lama ekstra (tidak disentuh, tidak dihapus).");
        }
    }

    // 7. Update Calibration
    $updateData = [];
    if ($request->filled('calibratedBy')) $updateData['calibrated_by'] = $request->calibratedBy;
    if ($request->filled('verifiedBy'))   $updateData['verified_by']   = $request->verifiedBy;
    if ($request->filled('uncertainty'))  $updateData['uncertainty']   = $request->uncertainty;
    if ($request->filled('conclusion'))   $updateData['keterangan']    = $request->conclusion;
    if (!empty($updateData)) $calibration->update($updateData);

    \Log::info('📋 UPDATE ENCLOSURE FINAL (IN-PLACE, NO DELETE):', [
        'calibration_id' => $calibration->id,
        'repetition' => $repetition,
        'updated' => $totalUpdated,
        'created' => $totalCreated,
    ]);

    return true;
}
     private function storeClimaticChamber($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1, $tabId = null)
{
    \Log::info('🚀 ===== START storeClimaticChamber =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        // 🔥 AMBIL REPETITION DARI REQUEST
        $repetition = (int) ($request->repetition ?? 1);
        if ($repetition < 1) {
            $repetition = 1;
        }
        \Log::info('Repetition value from request:', ['repetition' => $repetition]);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm,
            'tab_id' => $tabId,
            'repetition' => $repetition
        ]);
        
        // ==================================================================
        // EKSTRAK DATA DARI SEMUA FORM
        // ==================================================================
        $allFormsData = [];
        
        if ($isMultipleSubmit) {
            for ($i = 1; $i <= $jumlahForm; $i++) {
                $formData = [];
                foreach ($request->all() as $key => $value) {
                    if (strpos($key, "form_{$i}_") === 0) {
                        $originalKey = substr($key, strlen("form_{$i}_"));
                        
                        // 🔥 TANGANI KHUSUS UNTUK ALAT STANDAR
                        if (strpos($originalKey, 'alat_standar_temp_') === 0) {
                            if (!isset($formData['alat_standar_temp'])) {
                                $formData['alat_standar_temp'] = [];
                            }
                            if (!is_array($value)) {
                                $formData['alat_standar_temp'][] = $value;
                            } else {
                                $formData['alat_standar_temp'] = array_merge($formData['alat_standar_temp'], $value);
                            }
                        } elseif (strpos($originalKey, 'alat_standar_humid_') === 0) {
                            if (!isset($formData['alat_standar_humid'])) {
                                $formData['alat_standar_humid'] = [];
                            }
                            if (!is_array($value)) {
                                $formData['alat_standar_humid'][] = $value;
                            } else {
                                $formData['alat_standar_humid'] = array_merge($formData['alat_standar_humid'], $value);
                            }
                        } elseif (strpos($originalKey, 'alat_standar') !== false) {
                            if (!isset($formData['alat_standar'])) {
                                $formData['alat_standar'] = [];
                            }
                            if (!is_array($value)) {
                                $formData['alat_standar'][] = $value;
                            } else {
                                $formData['alat_standar'] = array_merge($formData['alat_standar'], $value);
                            }
                        } else {
                            if (!is_array($value)) {
                                $formData[$originalKey] = $value;
                            } else {
                                $formData[$originalKey] = json_encode($value);
                            }
                        }
                    }
                }
                $formData['form_index'] = $i;
                $allFormsData[$i] = $formData;
            }
        } else {
            $allFormsData[1] = $request->all();
            $allFormsData[1]['form_index'] = 1;
        }
        
        // ==================================================================
        // 🔥 PROSES ALAT STANDAR (FIXED - SUPPORT SEMUA FORMAT KEY)
        // ==================================================================
        $form1Data = $allFormsData[1] ?? [];
        
        \Log::info('🔍 CEK DATA ALAT STANDAR DARI FORM 1:', [
            'keys_form1' => array_keys($form1Data),
            'alat_standar_temp' => $form1Data['alat_standar_temp'] ?? 'NOT SET',
            'alat_standar_humid' => $form1Data['alat_standar_humid'] ?? 'NOT SET',
            'alat_standar_1' => $form1Data['alat_standar_1'] ?? 'NOT SET',
        ]);
        
        // 🔥 KUMPULKAN SEMUA NILAI DARI SEMUA VARIASI KEY
        $alatStandarAll = [];
        
        // Priority 1: field dengan prefix _temp_ dan _humid_ (blade baru)
        foreach ($form1Data as $key => $value) {
            if (preg_match('/^alat_standar_temp(_\d+)?$/', $key)) {
                if (is_array($value)) {
                    $alatStandarAll = array_merge($alatStandarAll, $value);
                } elseif (!empty($value)) {
                    $alatStandarAll[] = $value;
                }
            }
            if (preg_match('/^alat_standar_humid(_\d+)?$/', $key)) {
                if (is_array($value)) {
                    $alatStandarAll = array_merge($alatStandarAll, $value);
                } elseif (!empty($value)) {
                    $alatStandarAll[] = $value;
                }
            }
        }
        
        // Priority 2: field generic 'alat_standar_X' (blade lama - yang kamu pakai sekarang)
        foreach ($form1Data as $key => $value) {
            if (preg_match('/^alat_standar(_\d+)?$/', $key)) {
                if (is_array($value)) {
                    $alatStandarAll = array_merge($alatStandarAll, $value);
                } elseif (!empty($value)) {
                    $alatStandarAll[] = $value;
                }
            }
        }
        
        // Priority 3: fallback ke request langsung
        if (empty($alatStandarAll)) {
            // Coba form_1_alat_standar_1, form_1_alat_standar_2, dst.
            $i = 1;
            while ($request->has("form_1_alat_standar_{$i}")) {
                $val = $request->input("form_1_alat_standar_{$i}");
                if (is_array($val)) {
                    $alatStandarAll = array_merge($alatStandarAll, $val);
                } else {
                    $alatStandarAll[] = $val;
                }
                $i++;
            }
            
            // Coba key generic tanpa angka
            if (empty($alatStandarAll) && $request->has('form_1_alat_standar')) {
                $val = $request->input('form_1_alat_standar');
                $alatStandarAll = is_array($val) ? $val : [$val];
            }
            
            // Coba key root (tanpa prefix form_1_)
            if (empty($alatStandarAll) && $request->has('alat_standar')) {
                $val = $request->input('alat_standar');
                $alatStandarAll = is_array($val) ? $val : [$val];
            }
            
            // Coba alat_standar_1, alat_standar_2, dst (tanpa prefix)
            if (empty($alatStandarAll)) {
                $i = 1;
                while ($request->has("alat_standar_{$i}")) {
                    $val = $request->input("alat_standar_{$i}");
                    if (is_array($val)) {
                        $alatStandarAll = array_merge($alatStandarAll, $val);
                    } else {
                        $alatStandarAll[] = $val;
                    }
                    $i++;
                }
            }
        }
        
        // 🔥 HAPUS DUPLIKAT
        $alatStandarAll = array_values(array_unique($alatStandarAll));
        
        \Log::info('📝 Alat Standar (semua yang dipilih):', [
            'items' => $alatStandarAll
        ]);
        
        // ==================================================================
        // 🔥 PISAHKAN TEMP vs HUMID BERDASARKAN NAMA ALAT
        // Mapping:
        //   TEMP : GL-220, GL-240, Huato
        //   HUMID: Rotronic, Lutron
        // ==================================================================
        $tempItems  = ['GL-220', 'GL-240', 'Huato'];
        $humidItems = ['Rotronic', 'Lutron'];
        
        $alatStandarTemp  = [];
        $alatStandarHumid = [];
        
        foreach ($alatStandarAll as $value) {
            $value = trim($value);
            if ($value === '') continue;
            
            if (in_array($value, $tempItems)) {
                $alatStandarTemp[] = $value;
            } elseif (in_array($value, $humidItems)) {
                $alatStandarHumid[] = $value;
            } else {
                // Alat tidak dikenal, log warning
                \Log::warning('⚠️ Alat standar tidak dikenal:', ['value' => $value]);
            }
        }
        
        // Buang duplikat
        $alatStandarTemp  = array_values(array_unique($alatStandarTemp));
        $alatStandarHumid = array_values(array_unique($alatStandarHumid));
        
        // Proses data temperature dengan prefix "[TEMP]"
        $processedTemp = [];
        foreach ($alatStandarTemp as $value) {
            $processedTemp[] = '[TEMP] ' . $value;
        }
        
        // Proses data kelembaban dengan prefix "[HUMID]"
        $processedHumid = [];
        foreach ($alatStandarHumid as $value) {
            $processedHumid[] = '[HUMID] ' . $value;
        }
        
        $arrayValueCombined = array_merge($processedTemp, $processedHumid);
        
        \Log::info('📝 Data Alat Standar FINAL:', [
            'temp_raw'        => $alatStandarTemp,
            'humid_raw'       => $alatStandarHumid,
            'temp_processed'  => $processedTemp,
            'humid_processed' => $processedHumid,
            'combined'        => $arrayValueCombined
        ]);
        
        // Simpan sebagai string dengan newline
        $standardValue = !empty($arrayValueCombined) ? implode("\n", $arrayValueCombined) : '';
        
        \Log::info('📝 Standard value yang akan disimpan:', [
            'standard' => $standardValue,
            'is_empty' => empty($standardValue)
        ]);
        
        // ==================================================================
        // 🔥 AMBIL KAPASITAS & RESOLUSI (C & RH) DARI FORM 1
        // ==================================================================
        $kapasitasC  = $this->getRequestValue($request, 'kapasitas_c', $tabId)
                       ?? ($form1Data['kapasitas_c'] ?? null)
                       ?? $request->input("form_1_kapasitas_c");
        
        $resolusiC   = $this->getRequestValue($request, 'resolusi_c', $tabId)
                       ?? ($form1Data['resolusi_c'] ?? null)
                       ?? $request->input("form_1_resolusi_c");
        
        $kapasitasRh = $this->getRequestValue($request, 'kapasitas_rh', $tabId)
                       ?? ($form1Data['kapasitas_rh'] ?? null)
                       ?? $request->input("form_1_kapasitas_rh");
        
        $resolusiRh  = $this->getRequestValue($request, 'resolusi_rh', $tabId)
                       ?? ($form1Data['resolusi_rh'] ?? null)
                       ?? $request->input("form_1_resolusi_rh");
        
        \Log::info('📝 Kapasitas & Resolusi yang akan disimpan ke Head:', [
            'kapasitas_c'  => $kapasitasC,
            'resolusi_c'   => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh'  => $resolusiRh,
        ]);
        
        // ==================================================================
        // STORE HEADS
        // ==================================================================
        $heads = [];
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadChamber::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard'          => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-29B',
                    'certificate_id'    => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                    'kapasitas_c'       => $kapasitasC,
                    'resolusi_c'        => $resolusiC,
                    'kapasitas_rh'      => $kapasitasRh,
                    'resolusi_rh'       => $resolusiRh,
                ]
            );
            $heads[$formIndex] = $head;
        }
        
        // ==================================================================
        // 🖼️ SIMPAN GAMBAR CANVAS (KETERANGAN_GAMBAR) - HANYA DARI FORM 1
        // ==================================================================
        $kanvasBase64 = $form1Data['keterangan_gambar'] 
                        ?? $request->input('form_1_keterangan_gambar')
                        ?? $request->input('keterangan_gambar', '');
        
        // Handle kalau datanya masih JSON-encoded
        if (is_string($kanvasBase64) && strpos($kanvasBase64, 'data:image') !== 0 && $kanvasBase64 !== '') {
            $decoded = json_decode($kanvasBase64, true);
            if (json_last_error() === JSON_ERROR_NONE && is_string($decoded)) {
                $kanvasBase64 = $decoded;
            }
        }
        
        if (!empty($kanvasBase64) && strpos($kanvasBase64, 'data:image') === 0) {
            try {
                $imgFolder = public_path('img_Chamber');
                if (!file_exists($imgFolder)) {
                    mkdir($imgFolder, 0755, true);
                }
                
                $imgData = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $kanvasBase64));
                $imgFileName = 'chamber_' . $calibration->id . '_' . time() . '.png';
                $imgPath = $imgFolder . DIRECTORY_SEPARATOR . $imgFileName;
                file_put_contents($imgPath, $imgData);
                
                // Update ke head Form 1 saja (karena canvas cuma di Form 1)
                if (isset($heads[1])) {
                    $heads[1]->update(['keterangan_gambar' => 'img_Chamber/' . $imgFileName]);
                }
                
                \Log::info('🖼️ Canvas gambar chamber disimpan:', [
                    'file' => $imgFileName,
                    'size' => strlen($imgData) . ' bytes',
                    'form_index' => 1
                ]);
            } catch (\Exception $e) {
                \Log::error('❌ Gagal simpan gambar canvas chamber:', ['error' => $e->getMessage()]);
            }
        } else {
            \Log::info('ℹ️ Tidak ada gambar canvas chamber untuk disimpan', [
                'base64_length' => is_string($kanvasBase64) ? strlen($kanvasBase64) : 0,
                'is_empty' => empty($kanvasBase64)
            ]);
        }
        
        // ==================================================================
        // DELETE OLD DATA
        // ==================================================================
        AddChamber::where('calibration_id', $calibration->id)->delete();
        DetailChamber::where('calibration_id', $calibration->id)->delete();
        
        $totalAddCount = 0;
        $totalDetailCount = 0;
        $allIntervals = [1, 2, 3, 4, 5, 13, 20, 30];
        $intervalJson = json_encode($allIntervals);
        
        // ==================================================================
        // LOOP FORM INDEX
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $formData = $allFormsData[$formIndex] ?? [];
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // ==============================================================
            // ADD CHAMBER (PER REPETITION)
            // ==============================================================
            for ($p = 1; $p <= $repetition; $p++) {
                // 🔥 CARI Tsetting DENGAN BERBAGAI POLA
                $tsettingValue = null;
                $patterns = [
                    "form_{$formIndex}_suhu_setting_{$formIndex}_{$p}_tab{$tabId}",
                    "suhu_setting_{$formIndex}_{$p}_tab{$tabId}",
                    "form_{$formIndex}_suhu_setting_{$formIndex}_{$p}",
                    "suhu_setting_{$formIndex}_{$p}",
                    "suhu_setting_{$p}"
                ];
                
                foreach ($patterns as $pattern) {
                    if (isset($formData[$pattern]) && $formData[$pattern] !== '') {
                        $tsettingValue = $formData[$pattern];
                        break;
                    }
                    if ($request->has($pattern) && $request->input($pattern) !== '') {
                        $tsettingValue = $request->input($pattern);
                        break;
                    }
                }
                
                AddChamber::create([
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'repetition_number' => $p,
                    'Tsetting' => $tsettingValue,
                    'Interval' => $intervalJson,
                ]);
                $totalAddCount++;
                \Log::info("✅ AddChamber saved for form {$formIndex}, repetition {$p}, Tsetting: {$tsettingValue}");
            }
            
            // ==============================================================
            // DETAIL CHAMBER (PER REPETITION & INTERVAL)
            // ==============================================================
            for ($p = 1; $p <= $repetition; $p++) {
                foreach ($allIntervals as $interval) {
                    // 🔥 CARI READ ALAT
                    $readAlatValue = null;
                    $patternsReadAlat = [
                        "form_{$formIndex}_alat_{$formIndex}_{$p}_{$interval}_tab{$tabId}",
                        "alat_{$formIndex}_{$p}_{$interval}_tab{$tabId}",
                        "form_{$formIndex}_alat_{$formIndex}_{$p}_{$interval}",
                        "alat_{$formIndex}_{$p}_{$interval}",
                        "alat_{$p}_{$interval}"
                    ];
                    
                    foreach ($patternsReadAlat as $pattern) {
                        if (isset($formData[$pattern]) && $formData[$pattern] !== '') {
                            $readAlatValue = $formData[$pattern];
                            break;
                        }
                        if ($request->has($pattern) && $request->input($pattern) !== '') {
                            $readAlatValue = $request->input($pattern);
                            break;
                        }
                    }
                    
                    // 🔥 CARI RH ALAT
                    $rhAlatValue = null;
                    $patternsRhAlat = [
                        "form_{$formIndex}_alat_percent_{$formIndex}_{$p}_{$interval}_tab{$tabId}",
                        "alat_percent_{$formIndex}_{$p}_{$interval}_tab{$tabId}",
                        "form_{$formIndex}_alat_percent_{$formIndex}_{$p}_{$interval}",
                        "alat_percent_{$formIndex}_{$p}_{$interval}",
                        "alat_percent_{$p}_{$interval}"
                    ];
                    
                    foreach ($patternsRhAlat as $pattern) {
                        if (isset($formData[$pattern]) && $formData[$pattern] !== '') {
                            $rhAlatValue = $formData[$pattern];
                            break;
                        }
                        if ($request->has($pattern) && $request->input($pattern) !== '') {
                            $rhAlatValue = $request->input($pattern);
                            break;
                        }
                    }
                    
                    // 🔥 CARI SENSOR VALUES (1-9)
                    $sensorValues = [];
                    for ($s = 1; $s <= 9; $s++) {
                        $sensorValue = null;
                        $patternsSensor = [
                            "form_{$formIndex}_sensor_{$formIndex}_{$p}_{$interval}_{$s}_tab{$tabId}",
                            "sensor_{$formIndex}_{$p}_{$interval}_{$s}_tab{$tabId}",
                            "form_{$formIndex}_sensor_{$formIndex}_{$p}_{$interval}_{$s}",
                            "sensor_{$formIndex}_{$p}_{$interval}_{$s}",
                            "sensor_{$p}_{$interval}_{$s}"
                        ];
                        
                        foreach ($patternsSensor as $pattern) {
                            if (isset($formData[$pattern]) && $formData[$pattern] !== '') {
                                $sensorValue = $formData[$pattern];
                                break;
                            }
                            if ($request->has($pattern) && $request->input($pattern) !== '') {
                                $sensorValue = $request->input($pattern);
                                break;
                            }
                        }
                        $sensorValues[$s] = $sensorValue;
                    }
                    
                    // 🔥 CARI RH ULANGAN
                    $rhUlanganValue = null;
                    $patternsRhUlangan = [
                        "form_{$formIndex}_sensor_percent_{$formIndex}_{$p}_{$interval}_tab{$tabId}",
                        "sensor_percent_{$formIndex}_{$p}_{$interval}_tab{$tabId}",
                        "form_{$formIndex}_sensor_percent_{$formIndex}_{$p}_{$interval}",
                        "sensor_percent_{$formIndex}_{$p}_{$interval}",
                        "sensor_percent_{$p}_{$interval}"
                    ];
                    
                    foreach ($patternsRhUlangan as $pattern) {
                        if (isset($formData[$pattern]) && $formData[$pattern] !== '') {
                            $rhUlanganValue = $formData[$pattern];
                            break;
                        }
                        if ($request->has($pattern) && $request->input($pattern) !== '') {
                            $rhUlanganValue = $request->input($pattern);
                            break;
                        }
                    }
                    
                    // Cek apakah ada data
                    $hasData = !empty($readAlatValue) || !empty($rhAlatValue) || 
                               !empty($sensorValues[1]) || !empty($sensorValues[2]) || 
                               !empty($sensorValues[3]) || !empty($sensorValues[4]) || 
                               !empty($sensorValues[5]) || !empty($sensorValues[6]) || 
                               !empty($sensorValues[7]) || !empty($sensorValues[8]) || 
                               !empty($sensorValues[9]) || !empty($rhUlanganValue);
                    
                    if ($hasData) {
                        DetailChamber::create([
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'repetition_number' => $p,
                            'interval_number' => $interval,
                            'readAlat' => $readAlatValue,
                            'RHAlat' => $rhAlatValue,
                            'ulangan01' => $sensorValues[1] ?? null,
                            'ulangan02' => $sensorValues[2] ?? null,
                            'ulangan03' => $sensorValues[3] ?? null,
                            'ulangan04' => $sensorValues[4] ?? null,
                            'ulangan05' => $sensorValues[5] ?? null,
                            'ulangan06' => $sensorValues[6] ?? null,
                            'ulangan07' => $sensorValues[7] ?? null,
                            'ulangan08' => $sensorValues[8] ?? null,
                            'ulangan09' => $sensorValues[9] ?? null,
                            'RHulangan' => $rhUlanganValue,
                        ]);
                        $totalDetailCount++;
                        \Log::debug("✅ Detail saved for form {$formIndex}, repetition {$p}, interval {$interval}");
                    }
                }
            }
        }
        
        // ==================================================================
        // UPDATE CALIBRATION
        // ==================================================================
        $calibration->update([
            'jumlah_form' => $jumlahForm,
            'repetition' => $repetition,
        ]);
        
        \Log::info('✅ storeClimaticChamber completed successfully', [
            'calibration_id' => $calibration->id,
            'total_add' => $totalAddCount,
            'total_details' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'repetition' => $repetition,
            'standard_saved' => $standardValue
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeClimaticChamber FAILED:', [
            'message' => $e->getMessage(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
/**
 * Helper function untuk mencari nilai dengan berbagai pola nama field
 */
private function getChamberValue($request, $formData, $formIndex, $repetition, $baseName, $tabId, $interval = null, $sensor = null)
{
    $value = null;
    
    // Bangun pola nama field berdasarkan parameter
    if ($sensor !== null) {
        // Untuk sensor: sensor_{formIndex}_{repetition}_{interval}_{sensor}
        $patterns = [
            "form_{$formIndex}_{$baseName}_{$formIndex}_{$repetition}_{$interval}_{$sensor}_tab{$tabId}",
            "{$baseName}_{$formIndex}_{$repetition}_{$interval}_{$sensor}_tab{$tabId}",
            "form_{$formIndex}_{$baseName}_{$formIndex}_{$repetition}_{$interval}_{$sensor}",
            "{$baseName}_{$formIndex}_{$repetition}_{$interval}_{$sensor}",
            "{$baseName}_{$repetition}_{$interval}_{$sensor}"
        ];
    } elseif ($interval !== null) {
        // Untuk alat: alat_{formIndex}_{repetition}_{interval}
        $patterns = [
            "form_{$formIndex}_{$baseName}_{$formIndex}_{$repetition}_{$interval}_tab{$tabId}",
            "{$baseName}_{$formIndex}_{$repetition}_{$interval}_tab{$tabId}",
            "form_{$formIndex}_{$baseName}_{$formIndex}_{$repetition}_{$interval}",
            "{$baseName}_{$formIndex}_{$repetition}_{$interval}",
            "{$baseName}_{$repetition}_{$interval}"
        ];
    } else {
        // Untuk Tsetting: suhu_setting_{formIndex}_{repetition}
        $patterns = [
            "form_{$formIndex}_{$baseName}_{$formIndex}_{$repetition}_tab{$tabId}",
            "{$baseName}_{$formIndex}_{$repetition}_tab{$tabId}",
            "form_{$formIndex}_{$baseName}_{$formIndex}_{$repetition}",
            "{$baseName}_{$formIndex}_{$repetition}",
            "{$baseName}_{$repetition}"
        ];
    }
    
    // Cari nilai dari patterns
    foreach ($patterns as $pattern) {
        if (isset($formData[$pattern]) && $formData[$pattern] !== '' && $formData[$pattern] !== null) {
            $value = $formData[$pattern];
            break;
        }
        if ($request->has($pattern) && $request->input($pattern) !== '' && $request->input($pattern) !== null) {
            $value = $request->input($pattern);
            break;
        }
    }
    
    // Jika masih null, coba dengan getRequestValue biasa
    if ($value === null) {
        $simpleKey = $interval !== null 
            ? ($sensor !== null 
                ? "{$baseName}_{$formIndex}_{$repetition}_{$interval}_{$sensor}"
                : "{$baseName}_{$formIndex}_{$repetition}_{$interval}")
            : "{$baseName}_{$formIndex}_{$repetition}";
        $value = $this->getRequestValue($request, $simpleKey, $tabId);
    }
    
    return $value;
}


   public function updateClimaticChamber($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateClimaticChamber =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        $headChamber = HeadChamber::where('calibration_id', $calibration->id)
            ->where('form_index', 1)
            ->first();
        
        $currentCertificateId = $headChamber->certificate_id ?? null;
        
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. AMBIL JUMLAH FORM
        // ==================================================================
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Climatic Chamber - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 2. PROSES ALAT STANDAR (TEMP & HUMID DENGAN PREFIX)
        // ==================================================================
        $arrayValueTemp = $request->input('alat_standar_temp', []);
        if (!is_array($arrayValueTemp)) {
            $arrayValueTemp = [];
        }
        
        $arrayValueHumid = $request->input('alat_standar_humid', []);
        if (!is_array($arrayValueHumid)) {
            $arrayValueHumid = [];
        }
        
        $processedTemp = [];
        foreach ($arrayValueTemp as $value) {
            if ($value === 'Huato') {
                $processedTemp[] = '[TEMP] Huato';
            } else {
                $processedTemp[] = $value;
            }
        }
        
        $processedHumid = [];
        foreach ($arrayValueHumid as $value) {
            if ($value === 'Huato') {
                $processedHumid[] = '[HUMID] Huato';
            } else {
                $processedHumid[] = $value;
            }
        }
        
        $arrayValueCombined = array_merge($processedTemp, $processedHumid);
        
        \Log::info('📝 Data Alat Standar:', [
            'alat_standar_temp_original' => $arrayValueTemp,
            'alat_standar_humid_original' => $arrayValueHumid,
            'alat_standar_temp_processed' => $processedTemp,
            'alat_standar_humid_processed' => $processedHumid,
            'combined' => $arrayValueCombined
        ]);
        
        if (count($arrayValueCombined) > 0) {
            $standardValue = implode("\n", $arrayValueCombined);
        } else {
            $headChamberForm1 = HeadChamber::where('calibration_id', $calibration->id)
                ->where('form_index', 1)
                ->first();
            $standardValue = $headChamberForm1->standard ?? '';
        }
        
        \Log::info('📝 Standard value yang akan disimpan:', [
            'standard' => $standardValue
        ]);

        // ==================================================================
        // 🔥 2b. AMBIL KAPASITAS & RESOLUSI (C & RH)
        // ==================================================================
        $kapasitasC  = $request->input('kapasitas_c')  ?? $request->input('form_1_kapasitas_c')  ?? ($headChamber->kapasitas_c  ?? null);
        $resolusiC   = $request->input('resolusi_c')   ?? $request->input('form_1_resolusi_c')   ?? ($headChamber->resolusi_c   ?? null);
        $kapasitasRh = $request->input('kapasitas_rh') ?? $request->input('form_1_kapasitas_rh') ?? ($headChamber->kapasitas_rh ?? null);
        $resolusiRh  = $request->input('resolusi_rh')  ?? $request->input('form_1_resolusi_rh')  ?? ($headChamber->resolusi_rh  ?? null);
        
        \Log::info('📝 Kapasitas & Resolusi yang akan disimpan ke Head:', [
            'kapasitas_c'  => $kapasitasC,
            'resolusi_c'   => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh'  => $resolusiRh,
        ]);
        
        // ==================================================================
        // 3. UPDATE HEAD CHAMBER UNTUK SETIAP FORM
        // ==================================================================
        $heads = [];
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $headData = [
                'standard'          => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-29B',
                'kapasitas_c'       => $kapasitasC,
                'resolusi_c'        => $resolusiC,
                'kapasitas_rh'      => $kapasitasRh,
                'resolusi_rh'       => $resolusiRh,
            ];
            
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            $head = HeadChamber::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                $headData
            );
            
            $heads[$formIndex] = $head;
            
            \Log::info("✅ HeadChamber updated for form {$formIndex}", [
                'id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'standard' => $head->standard
            ]);
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadChamber::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 🖼️ 3b. SIMPAN / UPDATE GAMBAR CANVAS PENEMPATAN SENSOR
        //         Pola sama seperti updateEnclosure
        // ==================================================================
        $kanvasBase64 = $request->input('keterangan_gambar', '');
        
        // Handle kalau datanya masih JSON-encoded
        if (is_string($kanvasBase64) && strpos($kanvasBase64, 'data:image') !== 0 && $kanvasBase64 !== '') {
            $decoded = json_decode($kanvasBase64, true);
            if (json_last_error() === JSON_ERROR_NONE && is_string($decoded)) {
                $kanvasBase64 = $decoded;
            }
        }
        
        if (!empty($kanvasBase64) && strpos($kanvasBase64, 'data:image') === 0) {
            try {
                $imgFolder = public_path('img_Chamber');
                if (!file_exists($imgFolder)) {
                    mkdir($imgFolder, 0755, true);
                }
                
                // Update ke Head Form 1 saja (karena canvas cuma di Form 1)
                if (isset($heads[1])) {
                    // Hapus gambar lama jika ada
                    $oldImg = $heads[1]->keterangan_gambar ?? null;
                    if ($oldImg && file_exists(public_path($oldImg))) {
                        @unlink(public_path($oldImg));
                    }
                    
                    $imgData = base64_decode(preg_replace('#^data:image/\w+;base64,#i', '', $kanvasBase64));
                    $imgFileName = 'chamber_' . $calibration->id . '_' . time() . '.png';
                    $imgPath = $imgFolder . DIRECTORY_SEPARATOR . $imgFileName;
                    file_put_contents($imgPath, $imgData);
                    
                    $heads[1]->update(['keterangan_gambar' => 'img_Chamber/' . $imgFileName]);
                    
                    \Log::info('🖼️ Canvas gambar chamber di-update:', [
                        'file' => $imgFileName,
                        'size' => strlen($imgData) . ' bytes',
                        'old_image' => $oldImg
                    ]);
                }
            } catch (\Exception $e) {
                \Log::error('❌ Gagal update gambar canvas chamber:', ['error' => $e->getMessage()]);
            }
        } else {
            \Log::info('ℹ️ Tidak ada gambar canvas chamber baru untuk di-update', [
                'base64_length' => is_string($kanvasBase64) ? strlen($kanvasBase64) : 0
            ]);
        }
        
        // ==================================================================
        // 4. AMBIL REPETITION DARI REQUEST
        // ==================================================================
        $repetition = 0;
        for ($i = 1; $i <= 3; $i++) {
            for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
                $fieldName = "suhu_setting_{$formIndex}_{$i}";
                if ($request->filled($fieldName)) {
                    $repetition = max($repetition, $i);
                }
            }
        }
        
        if ($repetition === 0) {
            $repetition = 1;
        }
        
        \Log::info('📊 Jumlah pengulangan untuk update:', ['repetition' => $repetition]);
        
        // ==================================================================
        // 5. HAPUS DATA LAMA
        // ==================================================================
        AddChamber::where('calibration_id', $calibration->id)->delete();
        DetailChamber::where('calibration_id', $calibration->id)->delete();
        
        $allIntervals = [1, 2, 3, 4, 5, 13, 20, 30];
        $intervalJson = json_encode($allIntervals);
        
        $totalAddCount = 0;
        $totalDetailCount = 0;
        
        // ==================================================================
        // 6. SIMPAN ADD CHAMBER & DETAIL CHAMBER UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing form {$formIndex}");
            
            // ==============================================================
            // 6a. SIMPAN ADD CHAMBER
            // ==============================================================
            for ($p = 1; $p <= $repetition; $p++) {
                $tsettingValue = null;
                $fieldName = "suhu_setting_{$formIndex}_{$p}";
                
                if ($request->filled($fieldName)) {
                    $rawValue = $request->input($fieldName);
                    if (!empty($rawValue)) {
                        $tsettingValue = trim($rawValue);
                    }
                }
                
                $addData = [
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'repetition_number' => $p,
                    'Tsetting' => $tsettingValue,
                    'Interval' => $intervalJson,
                ];
                
                AddChamber::create($addData);
                $totalAddCount++;
                \Log::debug("✅ AddChamber created for form {$formIndex}, repetition {$p}");
            }
            
            // ==============================================================
            // 6b. SIMPAN DETAIL CHAMBER
            // ==============================================================
            for ($p = 1; $p <= $repetition; $p++) {
                foreach ($allIntervals as $interval) {
                    $readAlatValue = null;
                    $readAlatField = "alat_{$formIndex}_{$p}_{$interval}";
                    if ($request->filled($readAlatField)) {
                        $rawValue = $request->input($readAlatField);
                        if (!empty($rawValue)) {
                            $readAlatValue = trim($rawValue);
                        }
                    }
                    
                    $rhAlatValue = null;
                    $rhAlatField = "alat_percent_{$formIndex}_{$p}_{$interval}";
                    if ($request->filled($rhAlatField)) {
                        $rawValue = $request->input($rhAlatField);
                        if (!empty($rawValue)) {
                            $rhAlatValue = trim($rawValue);
                        }
                    }
                    
                    $sensorValues = [];
                    for ($s = 1; $s <= 9; $s++) {
                        $sensorField = "sensor_{$formIndex}_{$p}_{$interval}_{$s}";
                        $sensorValue = null;
                        if ($request->filled($sensorField)) {
                            $rawValue = $request->input($sensorField);
                            if (!empty($rawValue)) {
                                $sensorValue = trim($rawValue);
                            }
                        }
                        $sensorValues[$s] = $sensorValue;
                    }
                    
                    $rhUlanganValue = null;
                    $rhUlanganField = "sensor_percent_{$formIndex}_{$p}_{$interval}";
                    if ($request->filled($rhUlanganField)) {
                        $rawValue = $request->input($rhUlanganField);
                        if (!empty($rawValue)) {
                            $rhUlanganValue = trim($rawValue);
                        }
                    }
                    
                    $hasData = !empty($readAlatValue) || !empty($rhAlatValue) || 
                               !empty($sensorValues[1]) || !empty($sensorValues[2]) || 
                               !empty($sensorValues[3]) || !empty($sensorValues[4]) || 
                               !empty($sensorValues[5]) || !empty($sensorValues[6]) || 
                               !empty($sensorValues[7]) || !empty($sensorValues[8]) || 
                               !empty($sensorValues[9]) || !empty($rhUlanganValue);
                    
                    if ($hasData) {
                        $detailData = [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'repetition_number' => $p,
                            'interval_number' => $interval,
                            'readAlat' => $readAlatValue,
                            'RHAlat' => $rhAlatValue,
                            'ulangan01' => $sensorValues[1] ?? null,
                            'ulangan02' => $sensorValues[2] ?? null,
                            'ulangan03' => $sensorValues[3] ?? null,
                            'ulangan04' => $sensorValues[4] ?? null,
                            'ulangan05' => $sensorValues[5] ?? null,
                            'ulangan06' => $sensorValues[6] ?? null,
                            'ulangan07' => $sensorValues[7] ?? null,
                            'ulangan08' => $sensorValues[8] ?? null,
                            'ulangan09' => $sensorValues[9] ?? null,
                            'RHulangan' => $rhUlanganValue,
                        ];
                        
                        DetailChamber::create($detailData);
                        $totalDetailCount++;
                    }
                }
            }
        }
        
        // ==================================================================
        // 7. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        if ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
        }
        
        if ($request->filled('conclusion')) {
            $updateData['keterangan'] = $request->conclusion;
        }
        
        $updateData['certificate_id'] = null;
        $updateData['jumlah_form'] = $jumlahForm;
        $updateData['repetition'] = $repetition;
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 Calibration updated with additional data', $updateData);
        }
        
        // ==================================================================
        // 8. FINAL VERIFICATION
        // ==================================================================
        $savedDetailCount = DetailChamber::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddChamber::where('calibration_id', $calibration->id)->count();
        $finalHeads = HeadChamber::where('calibration_id', $calibration->id)->orderBy('form_index')->get();
        
        $exampleTSettings = AddChamber::where('calibration_id', $calibration->id)
            ->orderBy('form_index')
            ->orderBy('repetition_number')
            ->limit(5)
            ->get(['form_index', 'repetition_number', 'Tsetting'])
            ->toArray();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_count' => $finalHeads->count(),
            'certificate_id_calibration' => $calibration->certificate_id,
            'certificate_id_heads' => $finalHeads->pluck('certificate_id')->toArray(),
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'repetition_count' => $repetition,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'keterangan_gambar_heads' => $finalHeads->pluck('keterangan_gambar')->toArray(),
            'tsetting_examples' => $exampleTSettings,
            'standard_saved' => $finalHeads->first()->standard ?? null,
        ]);
        
        \Log::info('🎉 updateClimaticChamber COMPLETED SUCCESSFULLY');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateClimaticChamber FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}

    
    private function storePressureGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storePressureGauge - 20 BARIS (10 KIRI + 10 KANAN)');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storePressureGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Pressure Gauge:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN KE HEAD PRESSURE GAUGE (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $satuanAlatKiri = $this->getRequestValue($request, 'satuan_alat_kiri', $tabId);
        $satuanStdKiri = $this->getRequestValue($request, 'satuan_std_kiri', $tabId);
        $satuanAlatKanan = $this->getRequestValue($request, 'satuan_alat_kanan', $tabId);
        $satuanStdKanan = $this->getRequestValue($request, 'satuan_std_kanan', $tabId);
        
        $head = HeadPressureGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-17',
            'satuan_alat_kiri' => $satuanAlatKiri,
            'satuan_std_kiri' => $satuanStdKiri,
            'satuan_alat_kanan' => $satuanAlatKanan,
            'satuan_std_kanan' => $satuanStdKanan,
        ]);

        \Log::info('✅ HeadPressureGauge saved:', [
            'head_id' => $head->id,
            'satuan_alat_kiri' => $satuanAlatKiri,
            'satuan_std_kiri' => $satuanStdKiri
        ]);

        // ==================================================================
        // 3. SIMPAN DETAIL PRESSURE GAUGE (20 BARIS: 10 KIRI + 10 KANAN)
        // ==================================================================
        \Log::info('📊 Saving Pressure Gauge detail measurements (20 rows)...');
        $detailCount = 0;
        
        // Proses 10 baris kiri
        for ($i = 1; $i <= 10; $i++) {
            // Cari pembacaan alat kiri dengan dukungan _tab
            $pembacaanAlatValue = $this->getRequestValue($request, "pembacaan_alat_kiri_{$i}", $tabId);
            if (!$pembacaanAlatValue) {
                $pembacaanAlatValue = $this->getRequestValue($request, "pembacaan_alat_kiri", $tabId);
                if (is_array($pembacaanAlatValue)) {
                    $pembacaanAlatValue = $pembacaanAlatValue[$i-1] ?? null;
                }
            }
            
            $stdNaik = $this->getRequestValue($request, "naik_kiri_{$i}", $tabId);
            $stdTurun = $this->getRequestValue($request, "turun_kiri_{$i}", $tabId);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($pembacaanAlatValue) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $pembacaanAlatValue,
                    'STDNaik' => $stdNaik,
                    'STDTurun' => $stdTurun,
                ];
                
                DetailPressureGauge::create($detailData);
                $detailCount++;
                \Log::debug("✅ Detail saved for row {$i} (kiri)");
            }
        }
        
        // Proses 10 baris kanan
        for ($i = 1; $i <= 10; $i++) {
            // Cari pembacaan alat kanan dengan dukungan _tab
            $pembacaanAlatValue = $this->getRequestValue($request, "pembacaan_alat_kanan_{$i}", $tabId);
            if (!$pembacaanAlatValue) {
                $pembacaanAlatValue = $this->getRequestValue($request, "pembacaan_alat_kanan", $tabId);
                if (is_array($pembacaanAlatValue)) {
                    $pembacaanAlatValue = $pembacaanAlatValue[$i-1] ?? null;
                }
            }
            
            $stdNaik = $this->getRequestValue($request, "naik_kanan_{$i}", $tabId);
            $stdTurun = $this->getRequestValue($request, "turun_kanan_{$i}", $tabId);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($pembacaanAlatValue) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $pembacaanAlatValue,
                    'STDNaik' => $stdNaik,
                    'STDTurun' => $stdTurun,
                ];
                
                DetailPressureGauge::create($detailData);
                $detailCount++;
                \Log::debug("✅ Detail saved for row {$i} (kanan)");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Pressure Gauge");

        // ==================================================================
        // 4. SIMPAN ADD PRESSURE GAUGE (DATA REPEATABILITY)
        // ==================================================================
        \Log::info('📊 Saving AddPressureGauge data (repeatability)...');
        
        $repeatData = [
            'calibration_id' => $calibration->id,
            'repeatability' => $this->getRequestValue($request, 'repeatability', $tabId),
            'repeatabilitySTD' => $this->getRequestValue($request, 'repeatability_unit', $tabId),
            'ulangan01' => $this->getRequestValue($request, 'row1_col1', $tabId),
            'ulangan02' => $this->getRequestValue($request, 'row1_col2', $tabId),
            'ulangan03' => $this->getRequestValue($request, 'row1_col3', $tabId),
            'ulangan04' => $this->getRequestValue($request, 'row2_col1', $tabId),
            'ulangan05' => $this->getRequestValue($request, 'row2_col2', $tabId),
        ];
        
        // Cek apakah ada data untuk disimpan
        $hasRepeatData = false;
        foreach ($repeatData as $key => $value) {
            if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                $hasRepeatData = true;
                break;
            }
        }
        
        if ($hasRepeatData) {
            $addRecord = AddPressureGauge::create($repeatData);
            \Log::info('✅ AddPressureGauge saved:', ['add_id' => $addRecord->id]);
        } else {
            \Log::info('⚠️ No AddPressureGauge data to save');
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Nama untuk TTD
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailPressureGauge::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddPressureGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Pressure Gauge - 20 rows):', [
            'calibration_id' => $calibration->id,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storePressureGauge COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storePressureGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailPressureGauge::where('calibration_id', $calibration->id)->delete();
                AddPressureGauge::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Pressure Gauge: " . $e->getMessage());
    }
}

/**
 * Update Pressure Gauge data - 20 BARIS (10 KIRI + 10 KANAN)
 */
private function updatePressureGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updatePressureGauge - 20 BARIS (10 KIRI + 10 KANAN)', [
            'calibration_id' => $calibration->id,
            'new_certificate_id' => $newCertificateId
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head pressure gauge untuk cek certificate_id
        $headPressureGauge = HeadPressureGauge::where('calibration_id', $calibration->id)->first();
        $currentCertificateId = $headPressureGauge->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE HEAD PRESSURE GAUGE
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        // Ambil data satuan dari request (menggunakan array notation)
        $headPressureData = $request->headPressureGauge ?? [];
        $satuanAlatKiri = $headPressureData['satuan_alat_kiri'] ?? null;
        $satuanStdKiri = $headPressureData['satuan_std_kiri'] ?? null;
        $satuanAlatKanan = $headPressureData['satuan_alat_kanan'] ?? null;
        $satuanStdKanan = $headPressureData['satuan_std_kanan'] ?? null;
        
        // Data untuk update head
        $headUpdateData = [
            'standard' => $alatStandarString,
            'satuan_alat_kiri' => $satuanAlatKiri,
            'satuan_std_kiri' => $satuanStdKiri,
            'satuan_alat_kanan' => $satuanAlatKanan,
            'satuan_std_kanan' => $satuanStdKanan,
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headUpdateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headUpdateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        if ($head = $calibration->headPressureGauge) {
            $head->update($headUpdateData);
            \Log::info('✅ HeadPressureGauge updated:', $headUpdateData);
        } else {
            // Jika head belum ada, buat baru
            $head = HeadPressureGauge::create(array_merge([
                'calibration_id' => $calibration->id,
                'calibrationMethod' => 'PAS-IK1102-17',
            ], $headUpdateData));
            \Log::info('➕ HeadPressureGauge created baru:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 2. UPDATE DETAIL PRESSURE GAUGE (DELETE & RECREATE 20 BARIS)
        // ==================================================================
        // Hapus data detail lama
        DetailPressureGauge::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        // Proses 10 baris KIRI (index 0-9)
        for ($i = 0; $i < 10; $i++) {
            $pembacaanAlat = $request->{"pembacaan_alat_kiri"} ?? [];
            $pembacaanAlatValue = $pembacaanAlat[$i] ?? null;
            $stdNaik = $request->{"naik_kiri_".$i} ?? null;
            $stdTurun = $request->{"turun_kiri_".$i} ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($pembacaanAlatValue) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                DetailPressureGauge::create([
                    'calibration_id' => $calibration->id,
                     'titikUkur' =>  $pembacaanAlatValue,
                    'STDNaik' =>  $stdNaik,
                    'STDTurun' =>  $stdTurun,
                ]);
                $detailCount++;
            }
        }
        
        // Proses 10 baris KANAN (index 0-9)
        for ($i = 0; $i < 10; $i++) {
            $pembacaanAlat = $request->{"pembacaan_alat_kanan"} ?? [];
            $pembacaanAlatValue = $pembacaanAlat[$i] ?? null;
            // Untuk kanan, $i + 10 karena di view menggunakan naik_kanan_10, naik_kanan_11, dst
            $stdNaik = $request->{"naik_kanan_".($i+10)} ?? null;
            $stdTurun = $request->{"turun_kanan_".($i+10)} ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($pembacaanAlatValue) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                DetailPressureGauge::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' =>  $pembacaanAlatValue,
                    'STDNaik' =>  $stdNaik,
                    'STDTurun' =>  $stdTurun,
                ]);
                $detailCount++;
            }
        }
        
        \Log::info('✅ DetailPressureGauge updated:', ['total_records' => $detailCount]);

        // ==================================================================
        // 3. UPDATE ADD PRESSURE GAUGE (REPEATABILITY)
        // ==================================================================
        // Ambil repeatability_in_bracket (ini adalah repeatabilitySTD)
        $repeatabilitySTD = $request->repeatabilitySTD ?? null;
        
        if ($addGauge = $calibration->addPressureGauge) {
            $addGauge->update([
                'repeatability' =>  $request->repeatability ?? $addGauge->repeatability,
                'repeatabilitySTD' => $repeatabilitySTD,
                'ulangan01' =>  $request->ulangan01 ?? $addGauge->ulangan01,
                'ulangan02' =>  $request->ulangan02 ?? $addGauge->ulangan02,
                'ulangan03' =>  $request->ulangan03 ?? $addGauge->ulangan03,
                'ulangan04' =>  $request->ulangan04 ?? $addGauge->ulangan04,
                'ulangan05' =>  $request->ulangan05 ?? $addGauge->ulangan05,
            ]);
            \Log::info('✅ AddPressureGauge updated', [
                'repeatability' => $request->repeatability,
                'repeatabilitySTD' => $repeatabilitySTD,
            ]);
        } else {
            // Buat baru jika belum ada
            AddPressureGauge::create([
                'calibration_id' => $calibration->id,
                'repeatability' =>  $request->repeatability ?? null,
                'repeatabilitySTD' => $repeatabilitySTD,
                'ulangan01' =>  $request->ulangan01 ?? null,
                'ulangan02' =>  $request->ulangan02 ?? null,
                'ulangan03' =>  $request->ulangan03 ?? null,
                'ulangan04' =>  $request->ulangan04 ?? null,
                'ulangan05' =>  $request->ulangan05 ?? null,
            ]);
            \Log::info('➕ AddPressureGauge created baru');
        }

        // ==================================================================
        // 4. UPDATE CALIBRATION (HANYA YANG PERLU)
        // ==================================================================
        $updateData = [];
        
        // Update certificate_id di calibration jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk calibration: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $updateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk calibration dari parameter: {$newCertificateId}");
        }
        
        // Update nama alat jika berubah (untuk keperluan generate certificate ID)
        if ($request->filled('namaAlat') && $request->namaAlat != $calibration->namaAlat) {
            $updateData['namaAlat'] = $request->namaAlat;
        }
        
        // Update calibrated_by dan verified_by
        if ($request->filled('nama_dikalibrasi')) {
            $updateData['calibrated_by'] = $request->nama_dikalibrasi;
        }
        
        if ($request->filled('nama_diperiksa')) {
            $updateData['verified_by'] = $request->nama_diperiksa;
        }
        
        // Update uncertainty dan conclusion
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
        }
        
        if ($request->filled('conclusion')) {
            $updateData['keterangan'] = $request->conclusion;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 Calibration updated', array_keys($updateData));
        }

        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $finalDetailCount = DetailPressureGauge::where('calibration_id', $calibration->id)->count();
        $finalAddCount = AddPressureGauge::where('calibration_id', $calibration->id)->count();
        
        // Ambil head terbaru untuk cek certificate_id
        $finalHead = HeadPressureGauge::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📋 UPDATE SUMMARY (Pressure Gauge - 20 rows):', [
            'calibration_id' => $calibration->id,
            'certificate_id_calibration' => $calibration->certificate_id,
            'certificate_id_head' => $finalHead->certificate_id ?? null,
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'detail_records' => $finalDetailCount,
            'add_records' => $finalAddCount,
            'standard' => $alatStandarString,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updatePressureGauge COMPLETED (20 rows total)');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePressureGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        throw $e;
    }
}


        private function storeDifferentialPressureGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeDifferentialPressureGauge - 20 BARIS (10 KIRI + 10 KANAN)');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeDifferentialPressureGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN KE HEAD DIFFERENTIAL PRESSURE GAUGE
        // ==================================================================
        $satuanAlatKiri = $this->getRequestValue($request, 'satuan_alat_kiri', $tabId);
        $satuanStdKiri = $this->getRequestValue($request, 'satuan_std_kiri', $tabId);
        $satuanAlatKanan = $this->getRequestValue($request, 'satuan_alat_kanan', $tabId);
        $satuanStdKanan = $this->getRequestValue($request, 'satuan_std_kanan', $tabId);
        
        $head = HeadDifferentialPressureGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-17',
            'satuan_alat_kiri' => $satuanAlatKiri,
            'satuan_std_kiri' => $satuanStdKiri,
            'satuan_alat_kanan' => $satuanAlatKanan,
            'satuan_std_kanan' => $satuanStdKanan,
        ]);

        \Log::info('✅ HeadDifferentialPressureGauge saved:', [
            'head_id' => $head->id,
            'satuan_alat_kiri' => $satuanAlatKiri,
            'satuan_std_kiri' => $satuanStdKiri
        ]);

        // ==================================================================
        // 3. SIMPAN DETAIL DIFFERENTIAL PRESSURE GAUGE (20 BARIS)
        // ==================================================================
        \Log::info('📊 Saving Differential Pressure Gauge detail measurements...');
        $detailCount = 0;
        
        // Ambil data pembacaan alat kiri dan kanan
        $pembacaanAlatKiri = [];
        $pembacaanAlatKanan = [];
        
        for ($i = 1; $i <= 10; $i++) {
            $val = $this->getRequestValue($request, "pembacaan_alat_kiri_{$i}", $tabId);
            if ($val) {
                $pembacaanAlatKiri[] = $val;
            }
        }
        
        // Jika tidak ditemukan dengan format individual, coba array
        if (empty($pembacaanAlatKiri)) {
            $pembacaanAlatKiri = $this->getRequestValue($request, 'pembacaan_alat_kiri', $tabId);
            if (!is_array($pembacaanAlatKiri)) {
                $pembacaanAlatKiri = [];
            }
        }
        
        for ($i = 1; $i <= 10; $i++) {
            $val = $this->getRequestValue($request, "pembacaan_alat_kanan_{$i}", $tabId);
            if ($val) {
                $pembacaanAlatKanan[] = $val;
            }
        }
        
        if (empty($pembacaanAlatKanan)) {
            $pembacaanAlatKanan = $this->getRequestValue($request, 'pembacaan_alat_kanan', $tabId);
            if (!is_array($pembacaanAlatKanan)) {
                $pembacaanAlatKanan = [];
            }
        }
        
        // Proses 10 baris kiri
        for ($i = 1; $i <= 10; $i++) {
            $titikUkur = isset($pembacaanAlatKiri[$i-1]) ? $pembacaanAlatKiri[$i-1] : null;
            $stdNaik = $this->getRequestValue($request, "naik_kiri_{$i}", $tabId);
            $stdTurun = $this->getRequestValue($request, "turun_kiri_{$i}", $tabId);
            
            $hasData = !empty($titikUkur) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                DetailDifferentialPressureGauge::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'STDNaik' => $stdNaik,
                    'STDTurun' => $stdTurun,
                ]);
                $detailCount++;
                \Log::debug("✅ Detail saved for row {$i} (kiri)");
            }
        }
        
        // Proses 10 baris kanan
        for ($i = 1; $i <= 10; $i++) {
            $titikUkur = isset($pembacaanAlatKanan[$i-1]) ? $pembacaanAlatKanan[$i-1] : null;
            $stdNaik = $this->getRequestValue($request, "naik_kanan_{$i}", $tabId);
            $stdTurun = $this->getRequestValue($request, "turun_kanan_{$i}", $tabId);
            
            $hasData = !empty($titikUkur) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                DetailDifferentialPressureGauge::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'STDNaik' => $stdNaik,
                    'STDTurun' => $stdTurun,
                ]);
                $detailCount++;
                \Log::debug("✅ Detail saved for row {$i} (kanan)");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Differential Pressure Gauge");

        // ==================================================================
        // 4. SIMPAN ADD DIFFERENTIAL PRESSURE GAUGE (REPEATABILITY)
        // ==================================================================
        \Log::info('📊 Saving AddDifferentialPressureGauge data (repeatability)...');
        
        $repeatabilitySTD = $this->getRequestValue($request, 'repeatability_unit', $tabId);
        
        $repeatData = [
            'calibration_id' => $calibration->id,
            'repeatability' => $this->getRequestValue($request, 'repeatability', $tabId),
            'repeatabilitySTD' => $repeatabilitySTD,
            'ulangan01' => $this->getRequestValue($request, 'row1_col1', $tabId),
            'ulangan02' => $this->getRequestValue($request, 'row1_col2', $tabId),
            'ulangan03' => $this->getRequestValue($request, 'row1_col3', $tabId),
            'ulangan04' => $this->getRequestValue($request, 'row2_col1', $tabId),
            'ulangan05' => $this->getRequestValue($request, 'row2_col2', $tabId),
        ];
        
        // Cek apakah ada data untuk disimpan
        $hasRepeatData = false;
        foreach ($repeatData as $key => $value) {
            if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                $hasRepeatData = true;
                break;
            }
        }
        
        if ($hasRepeatData) {
            $addRecord = AddDifferentialPressureGauge::create($repeatData);
            \Log::info('✅ AddDifferentialPressureGauge saved:', ['add_id' => $addRecord->id]);
        } else {
            \Log::info('⚠️ No AddDifferentialPressureGauge data to save');
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Nama untuk TTD
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailDifferentialPressureGauge::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddDifferentialPressureGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Differential Pressure Gauge - 20 rows):', [
            'calibration_id' => $calibration->id,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storeDifferentialPressureGauge COMPLETED (20 rows total)');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeDifferentialPressureGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailDifferentialPressureGauge::where('calibration_id', $calibration->id)->delete();
                AddDifferentialPressureGauge::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Differential Pressure Gauge: " . $e->getMessage());
    }
}
        /**
         * Update Pressure Gauge data - 20 BARIS (10 KIRI + 10 KANAN)
         */
      private function updateDifferentialPressureGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateDifferentialPressureGauge - 20 BARIS (10 KIRI + 10 KANAN)', [
            'calibration_id' => $calibration->id,
            'new_certificate_id' => $newCertificateId
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        // Ambil head differential pressure gauge untuk cek certificate_id
        $headDifferentialPressureGauge = HeadDifferentialPressureGauge::where('calibration_id', $calibration->id)->first();
        $currentCertificateId = $headDifferentialPressureGauge->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE HEAD DIFFERENTIAL PRESSURE GAUGE
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        $headDifferentialPressureData = $request->headDifferentialPressureGauge ?? [];
        $satuanAlatKiri = $headDifferentialPressureData['satuan_alat_kiri'] ?? null;
        $satuanStdKiri = $headDifferentialPressureData['satuan_std_kiri'] ?? null;
        $satuanAlatKanan = $headDifferentialPressureData['satuan_alat_kanan'] ?? null;
        $satuanStdKanan = $headDifferentialPressureData['satuan_std_kanan'] ?? null;
        
        // Data untuk update head
        $headUpdateData = [
            'standard' => $alatStandarString,
            'satuan_alat_kiri' => $satuanAlatKiri,
            'satuan_std_kiri' => $satuanStdKiri,
            'satuan_alat_kanan' => $satuanAlatKanan,
            'satuan_std_kanan' => $satuanStdKanan,
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headUpdateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headUpdateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        if ($head = $calibration->headDifferentialPressureGauge) {
            $head->update($headUpdateData);
            \Log::info('✅ HeadDifferentialPressureGauge updated:', $headUpdateData);
        } else {
            // Jika head belum ada, buat baru
            $head = HeadDifferentialPressureGauge::create(array_merge([
                'calibration_id' => $calibration->id,
                'calibrationMethod' => 'PAS-IK1102-17B',
            ], $headUpdateData));
            \Log::info('➕ HeadDifferentialPressureGauge created baru:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 2. UPDATE DETAIL DIFFERENTIAL PRESSURE GAUGE (20 BARIS)
        // ==================================================================
        // Hapus data detail lama
        DetailDifferentialPressureGauge::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        // Proses 10 baris KIRI (index 0-9)
        for ($i = 0; $i < 10; $i++) {
            $pembacaanAlat = $request->{"pembacaan_alat_kiri"} ?? [];
            $pembacaanAlatValue = $pembacaanAlat[$i] ?? null;
            $stdNaik = $request->{"naik_kiri_".$i} ?? null;
            $stdTurun = $request->{"turun_kiri_".$i} ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($pembacaanAlatValue) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                DetailDifferentialPressureGauge::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $pembacaanAlatValue,
                    'STDNaik' => $stdNaik,
                    'STDTurun' => $stdTurun,
                ]);
                $detailCount++;
            }
        }
        
        // Proses 10 baris KANAN (index 0-9)
        for ($i = 0; $i < 10; $i++) {
            $pembacaanAlat = $request->{"pembacaan_alat_kanan"} ?? [];
            $pembacaanAlatValue = $pembacaanAlat[$i] ?? null;
            // Untuk kanan, $i + 10 karena di view menggunakan naik_kanan_10, naik_kanan_11, dst
            $stdNaik = $request->{"naik_kanan_".($i+10)} ?? null;
            $stdTurun = $request->{"turun_kanan_".($i+10)} ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($pembacaanAlatValue) || !empty($stdNaik) || !empty($stdTurun);
            
            if ($hasData) {
                DetailDifferentialPressureGauge::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $pembacaanAlatValue,
                    'STDNaik' => $stdNaik,
                    'STDTurun' => $stdTurun,
                ]);
                $detailCount++;
            }
        }
        
        \Log::info('✅ DetailDifferentialPressureGauge updated:', ['total_records' => $detailCount]);

        // ==================================================================
        // 3. UPDATE ADD DIFFERENTIAL PRESSURE GAUGE (REPEATABILITY)
        // ==================================================================
        // Ambil repeatabilitySTD dari request (name="repeatability_unit")
        $repeatabilitySTD = $request->repeatability_unit ?? null;
        
        if ($addGauge = $calibration->addDifferentialPressureGauge) {
            $addGauge->update([
                'repeatability' => $request->repeatability ?? $addGauge->repeatability,
                'repeatabilitySTD' => $repeatabilitySTD ?? $addGauge->repeatabilitySTD,
                'ulangan01' => $request->row1_col1 ?? $addGauge->ulangan01,
                'ulangan02' => $request->row1_col2 ?? $addGauge->ulangan02,
                'ulangan03' => $request->row1_col3 ?? $addGauge->ulangan03,
                'ulangan04' => $request->row2_col1 ?? $addGauge->ulangan04,
                'ulangan05' => $request->row2_col2 ?? $addGauge->ulangan05,
            ]);
            \Log::info('✅ AddDifferentialPressureGauge updated', [
                'repeatability' => $request->repeatability,
                'repeatabilitySTD' => $repeatabilitySTD,
                'ulangan01' => $request->row1_col1,
                'ulangan02' => $request->row1_col2,
                'ulangan03' => $request->row1_col3,
                'ulangan04' => $request->row2_col1,
                'ulangan05' => $request->row2_col2,
            ]);
        } else {
            // Buat baru jika belum ada
            AddDifferentialPressureGauge::create([
                'calibration_id' => $calibration->id,
                'repeatability' => $request->repeatability ?? null,
                'repeatabilitySTD' => $repeatabilitySTD ?? null,
                'ulangan01' => $request->row1_col1 ?? null,
                'ulangan02' => $request->row1_col2 ?? null,
                'ulangan03' => $request->row1_col3 ?? null,
                'ulangan04' => $request->row2_col1 ?? null,
                'ulangan05' => $request->row2_col2 ?? null,
            ]);
            \Log::info('➕ AddDifferentialPressureGauge created baru');
        }

        // ==================================================================
        // 4. UPDATE CALIBRATION
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if ($request->filled('namaAlat') && $request->namaAlat != $calibration->namaAlat) {
            $updateData['namaAlat'] = $request->namaAlat;
        }
        
        // UPDATE CERTIFICATE ID DI CALIBRATION jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk calibration: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $updateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk calibration dari parameter: {$newCertificateId}");
        }
        
        // Update uncertainty dan conclusion
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        // Update nama dari input yang dikirim
        if ($request->filled('nama_dikalibrasi')) {
            $updateData['calibrated_by'] = $request->nama_dikalibrasi;
        }
        
        if ($request->filled('nama_diperiksa')) {
            $updateData['verified_by'] = $request->nama_diperiksa;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 Calibration updated', array_keys($updateData));
        }

        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $finalDetailCount = DetailDifferentialPressureGauge::where('calibration_id', $calibration->id)->count();
        $finalAddCount = AddDifferentialPressureGauge::where('calibration_id', $calibration->id)->count();
        
        // Ambil head terbaru untuk cek certificate_id
        $finalHead = HeadDifferentialPressureGauge::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📋 UPDATE SUMMARY (Differential Pressure Gauge - 20 rows):', [
            'calibration_id' => $calibration->id,
            'certificate_id_calibration' => $calibration->certificate_id,
            'certificate_id_head' => $finalHead->certificate_id ?? null,
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'detail_records' => $finalDetailCount,
            'add_records' => $finalAddCount,
            'standard' => $alatStandarString,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updateDifferentialPressureGauge COMPLETED (20 rows total)');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateDifferentialPressureGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        throw $e;
    }
}

        
    private function storeVolumetrik($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeVolumetrik - DENGAN INPUT MANUAL');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeVolumetrik called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. TENTUKAN NAMA ALAT YANG AKAN DIGUNAKAN (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $namaAlatFinal = $calibration->namaAlat; // Default: dari create awal
        
        // Cari nama alat dari request dengan dukungan _tab
        $namaAlatDropdown = $this->getRequestValue($request, 'nama_alat', $tabId);
        $namaAlatManual = $this->getRequestValue($request, 'nama_alat_manual', $tabId);
        
        \Log::info('🔍 Initial nama alat state:', [
            'calibration_namaAlat' => $calibration->namaAlat,
            'request_nama_alat' => $namaAlatDropdown,
            'request_nama_alat_manual' => $namaAlatManual,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId
        ]);
        
        // Jika ada input manual nama alat, update dengan itu
        if (!empty($namaAlatManual)) {
            $namaAlatFinal = $namaAlatManual;
            $calibration->update(['namaAlat' => $namaAlatFinal]);
            \Log::info('📝 Nama alat diupdate dari input manual:', ['nama_alat' => $namaAlatFinal]);
        } 
        // Jika dari dropdown dan bukan "MANUAL_INPUT"
        elseif (!empty($namaAlatDropdown) && $namaAlatDropdown !== 'MANUAL_INPUT') {
            // Update jika berbeda dengan yang sudah ada
            if ($calibration->namaAlat !== $namaAlatDropdown) {
                $namaAlatFinal = $namaAlatDropdown;
                $calibration->update(['namaAlat' => $namaAlatFinal]);
                \Log::info('📝 Nama alat diupdate dari dropdown:', ['nama_alat' => $namaAlatFinal]);
            }
        }
        
        // ==================================================================
        // 3. PASTIKAN CERTIFICATE ID PURE DARI CALIBRATION ID (TANPA NAMA ALAT)
        // ==================================================================
        $expectedCertificateId = $calibration->id;
        if (empty($certificateId) || $certificateId !== $expectedCertificateId || strpos($certificateId, 'MANUAL_INPUT') !== false) {
            $certificateId = $expectedCertificateId;
            $calibration->update(['certificate_id' => $certificateId]);
            \Log::info('🆔 Certificate ID disesuaikan menjadi pure calibration ID:', [
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId
            ]);
        } else {
            \Log::info('✅ Certificate ID sudah benar (pure calibration ID):', ['certificate_id' => $certificateId]);
        }

        // ==================================================================
        // 4. SIMPAN KE HEAD VOLUMETRIK (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $satuanAlatUkur = $this->getRequestValue($request, 'satuan_alatUkur', $tabId);
        $satuanRep = $this->getRequestValue($request, 'satuan_rep', $tabId);
        $satuanTimbanganNominal = $this->getRequestValue($request, 'satuan_timbangan_nominal', $tabId);
        $satuanTimbanganRepeatability = $this->getRequestValue($request, 'satuan_timbangan_repeatability', $tabId);
        
        $head = HeadVolumetrik::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-38 (Volumetrik Glassware)',
            'satuan_alatUkur' => $satuanAlatUkur,
            'satuan_rep' => $satuanRep,
            'satuan_timbangan_nominal' => $satuanTimbanganNominal,
            'satuan_timbangan_repeatability' => $satuanTimbanganRepeatability
        ]);

        \Log::info('✅ HeadVolumetrik saved:', ['head_id' => $head->id]);

        // ==================================================================
        // 5. SIMPAN DETAIL VOLUMETRIK (5 BARIS) - TANPA formatNumericValue
        // ==================================================================
        \Log::info('📊 Saving DetailVolumetrik data (5 rows)...');
        $detailCount = 0;
        
        for ($nominal = 1; $nominal <= 5; $nominal++) {
            // Ambil nilai nominal dari form dengan dukungan _tab
            $nominalValue = $this->getRequestValue($request, "nominal_{$nominal}", $tabId);
            
            // Jika ada nominal, simpan semua data untuk nominal tersebut
            if (!empty($nominalValue)) {
                // Kumpulkan data untuk 3 pengulangan (nilai asli, tanpa format)
                $massaKosong01 = $this->getRequestValue($request, "massa_kosong_{$nominal}_1", $tabId);
                $massaKosong02 = $this->getRequestValue($request, "massa_kosong_{$nominal}_2", $tabId);
                $massaKosong03 = $this->getRequestValue($request, "massa_kosong_{$nominal}_3", $tabId);
                
                $massaIsi01 = $this->getRequestValue($request, "massa_isi_{$nominal}_1", $tabId);
                $massaIsi02 = $this->getRequestValue($request, "massa_isi_{$nominal}_2", $tabId);
                $massaIsi03 = $this->getRequestValue($request, "massa_isi_{$nominal}_3", $tabId);
                
                $T_airSuling01 = $this->getRequestValue($request, "suhu_{$nominal}_1", $tabId);
                $T_airSuling02 = $this->getRequestValue($request, "suhu_{$nominal}_2", $tabId);
                $T_airSuling03 = $this->getRequestValue($request, "suhu_{$nominal}_3", $tabId);
                
                $P_Udara01 = $this->getRequestValue($request, "tekanan_{$nominal}_1", $tabId);
                $P_Udara02 = $this->getRequestValue($request, "tekanan_{$nominal}_2", $tabId);
                $P_Udara03 = $this->getRequestValue($request, "tekanan_{$nominal}_3", $tabId);
                
                // Cek apakah ada data minimal 1 nilai
                $hasData = !empty($massaKosong01) || !empty($massaKosong02) || !empty($massaKosong03) ||
                          !empty($massaIsi01) || !empty($massaIsi02) || !empty($massaIsi03) ||
                          !empty($T_airSuling01) || !empty($T_airSuling02) || !empty($T_airSuling03) ||
                          !empty($P_Udara01) || !empty($P_Udara02) || !empty($P_Udara03);
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'head_volumetrik_id' => $head->id,
                        'titikUkur' => $nominalValue,
                        'masssaKosong01' => $massaKosong01,
                        'masssaKosong02' => $massaKosong02,
                        'masssaKosong03' => $massaKosong03,
                        'massaIsi01' => $massaIsi01,
                        'massaIsi02' => $massaIsi02,
                        'massaIsi03' => $massaIsi03,
                        'T_airSuling01' => $T_airSuling01,
                        'T_airSuling02' => $T_airSuling02,
                        'T_airSuling03' => $T_airSuling03,
                        'P_Udara01' => $P_Udara01,
                        'P_Udara02' => $P_Udara02,
                        'P_Udara03' => $P_Udara03,
                    ];
                    
                    DetailVolumetrik::create($detailData);
                    $detailCount++;
                    \Log::info("💾 Saved detail for nominal: {$nominalValue}");
                }
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailVolumetrik records");

        // ==================================================================
        // 6. SIMPAN ADD VOLUMETRIK (REPEATABILITY - 10 BARIS) - TANPA formatNumericValue
        // ==================================================================
        \Log::info('📊 Saving AddVolumetrik data (repeatability - 10 repetitions)...');

        // Ambil nilai titik ukur (nominal) dari input repeatability_nominal
        $repeatabilityNominal = $this->getRequestValue($request, 'repeatability_nominal', $tabId);

        $addCount = 0;

        // Loop untuk 10 pengulangan
        for ($i = 1; $i <= 10; $i++) {
            // Ambil data dari masing-masing baris pengulangan (nilai asli, tanpa format)
            $massaKosong = $this->getRequestValue($request, "repeat_massa_kosong_{$i}", $tabId);
            $massaIsi    = $this->getRequestValue($request, "repeat_massa_isi_{$i}", $tabId);
            $suhu        = $this->getRequestValue($request, "repeat_suhu_{$i}", $tabId);
            $tekanan     = $this->getRequestValue($request, "repeat_tekanan_{$i}", $tabId);

            // Cek apakah ada setidaknya satu field yang terisi di baris ini
            if ($massaKosong !== null || $massaIsi !== null || $suhu !== null || $tekanan !== null) {
                
                $addData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur'      => $repeatabilityNominal,
                    'massaKosong'    => $massaKosong,
                    'massaIsi'       => $massaIsi,
                    'T_airSuling'    => $suhu,
                    'P_Udara'        => $tekanan,
                ];

                AddVolumetrik::create($addData);
                $addCount++;
                
                \Log::info("💾 Saved AddVolumetrik repetition {$i}", $addData);
            }
        }

        if ($addCount > 0) {
            \Log::info("✅ Successfully saved {$addCount} AddVolumetrik records (repeatability)");
        } else {
            \Log::info('⚠️ No AddVolumetrik data was filled or saved');
        }

        // ==================================================================
        // 7. UPDATE CALIBRATION DENGAN DATA TTD (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        // Nama untuk TTD Dikalibrasi
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        // Nama untuk TTD Diperiksa
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Juga update certificate_id di calibration jika sudah diregenerate
        if ($needRegenerate) {
            $updateData['certificate_id'] = $certificateId;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with TTD data' . ($needRegenerate ? ' and new certificate_id' : ''));
        }

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailVolumetrik::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddVolumetrik::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Volumetrik):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'nama_alat_final' => $namaAlatFinal,
        ]);

        \Log::info('🎉 storeVolumetrik COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeVolumetrik:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback
        if (isset($head) && $head->id) {
            try {
                DetailVolumetrik::where('calibration_id', $calibration->id)->delete();
                AddVolumetrik::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Volumetrik: " . $e->getMessage());
    }
}

private function updateVolumetrik($request, $calibration)
{
    \Log::info('🚀 START updateVolumetrik - WITH CERTIFICATE ID UPDATE (generateCertificateIdFromNamaAlat)');
    
    // ==================================================================
    // 1. TENTUKAN NAMA ALAT YANG BARU DARI BERBAGAI SUMBER
    // ==================================================================
    $namaAlatLama = $calibration->namaAlat;
    $namaAlatBaru = $namaAlatLama; // Default: tetap sama
    
    \Log::info('🔍 Nama alat sebelum update:', [
        'nama_alat_lama' => $namaAlatLama,
        'from_hidden_input' => $request->namaAlat ?? 'not_set',
        'from_manual_input' => $request->nama_alat_manual ?? 'not_set',
        'from_dropdown' => $request->nama_alat ?? 'not_set',
        'dropdown_value' => $request->nama_alat_select ?? 'not_set'
    ]);
    
    // Priority 1: Hidden input namaAlat (sudah diproses JavaScript)
    if ($request->has('namaAlat') && !empty($request->namaAlat)) {
        $namaAlatBaru = $request->namaAlat;
        \Log::info('📝 Nama alat dari hidden input:', ['nama_alat_baru' => $namaAlatBaru]);
    }
    // Priority 2: Input manual
    elseif ($request->has('nama_alat_manual') && !empty($request->nama_alat_manual)) {
        $namaAlatBaru = $request->nama_alat_manual;
        \Log::info('📝 Nama alat dari input manual:', ['nama_alat_baru' => $namaAlatBaru]);
    }
    // Priority 3: Dropdown (bukan MANUAL_INPUT)
    elseif ($request->filled('nama_alat') && $request->nama_alat !== 'MANUAL_INPUT') {
        $namaAlatBaru = $request->nama_alat;
        \Log::info('📝 Nama alat dari dropdown:', ['nama_alat_baru' => $namaAlatBaru]);
    }
    
    // ==================================================================
    // 2. PERBARUI NAMA ALAT DI CALIBRATION JIKA BERBEDA
    // ==================================================================
    $namaAlatUpdated = false;
    if ($namaAlatLama !== $namaAlatBaru) {
        $calibration->update(['namaAlat' => $namaAlatBaru]);
        $namaAlatUpdated = true;
        \Log::info('✅ Nama alat diupdate di calibration:', [
            'dari' => $namaAlatLama,
            'menjadi' => $namaAlatBaru
        ]);
    }
    
    // ==================================================================
    // 3. GENERATE CERTIFICATE ID BARU MENGGUNAKAN generateCertificateIdFromNamaAlat()
    // ==================================================================
    $certificateIdLama = $calibration->certificate_id;
    $certificateIdBaru = $certificateIdLama;
    $certificateIdUpdated = false;
    
    if ($namaAlatUpdated) {
        // Generate certificate ID baru menggunakan generateCertificateIdFromNamaAlat()
        $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatBaru, $calibration);
        $certificateIdUpdated = true;
        
        // Update certificate_id di calibration
        $calibration->update(['certificate_id' => $certificateIdBaru]);
        
        \Log::info('🆔 Certificate ID updated menggunakan generateCertificateIdFromNamaAlat():', [
            'nama_alat_lama' => $namaAlatLama,
            'nama_alat_baru' => $namaAlatBaru,
            'certificate_id_lama' => $certificateIdLama,
            'certificate_id_baru' => $certificateIdBaru,
            'method_used' => 'generateCertificateIdFromNamaAlat'
        ]);
    } elseif (empty($certificateIdLama) || strpos($certificateIdLama, 'MANUAL_INPUT') !== false) {
        // Jika certificate_id masih kosong atau mengandung MANUAL_INPUT, generate baru
        $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatBaru, $calibration);
        $calibration->update(['certificate_id' => $certificateIdBaru]);
        $certificateIdUpdated = true;
        
        \Log::info('🆔 Certificate ID generated menggunakan generateCertificateIdFromNamaAlat():', [
            'reason' => empty($certificateIdLama) ? 'certificate_id kosong' : 'mengandung MANUAL_INPUT',
            'certificate_id_baru' => $certificateIdBaru,
            'method_used' => 'generateCertificateIdFromNamaAlat'
        ]);
    } else {
        \Log::info('✅ Certificate ID tidak berubah:', [
            'certificate_id' => $certificateIdLama,
            'reason' => 'nama alat tidak berubah'
        ]);
    }
    
    // Gunakan certificate_id yang sudah ditentukan
    $certificateIdToUse = $certificateIdBaru;
    
    // ==================================================================
    // 4. PROSES ALAT STANDAR DARI CHECKBOX (TANPA formatNumericValue)
    // ==================================================================
    $arrayValue = $request->input('alat_standar', []);
    
    if (is_array($arrayValue) && count($arrayValue) > 0) {
        $standardValue = implode(", ", $arrayValue);
        \Log::info('🔧 Alat standar dari checkbox:', [
            'count' => count($arrayValue),
            'items' => $arrayValue,
            'string' => $standardValue
        ]);
    } else {
        // Coba ambil dari data yang sudah ada
        $headVolumetrik = HeadVolumetrik::where('calibration_id', $calibration->id)->first();
        $standardValue = $headVolumetrik->standard ?? '';
        \Log::info('🔧 Alat standar dari data lama:', ['standard' => $standardValue]);
    }
    
    // ==================================================================
    // 5. Update HeadVolumetrik dengan certificate_id yang benar
    // ==================================================================
    $headData = [
        'standard' => $standardValue,
        'calibrationMethod' => $request->calibration_method ?? 'PAS-IK1102-38 (Volumetrik Glassware)',
        'satuan_alatUkur' => $request->satuan_alatUkur ?? 'mL',
        'satuan_rep' => $request->satuan_rep ?? 'mL',
        'satuan_timbangan_nominal' => $request->satuan_timbangan_nominal ?? 'mL',
        'satuan_timbangan_repeatability' => $request->satuan_timbangan_repeatability ?? 'mL',
    ];
    
    // Update certificate_id hanya jika berubah
    if ($certificateIdUpdated) {
        $headData['certificate_id'] = $certificateIdToUse;
        \Log::info('📝 Certificate ID akan diupdate di HeadVolumetrik:', ['certificate_id' => $certificateIdToUse]);
    }
    
    $headVolumetrik = HeadVolumetrik::updateOrCreate(
        ['calibration_id' => $calibration->id],
        $headData
    );
    
    \Log::info('✅ HeadVolumetrik updated/created:', [
        'id' => $headVolumetrik->id,
        'standard' => $standardValue,
        'certificate_id' => $headVolumetrik->certificate_id,
        'certificate_updated' => $certificateIdUpdated ? 'Yes' : 'No'
    ]);
    
    // ==================================================================
    // 6. Hapus data DetailVolumetrik lama
    // ==================================================================
    $deletedDetailCount = DetailVolumetrik::where('calibration_id', $calibration->id)->delete();
    \Log::info('🗑️ Deleted old DetailVolumetrik records:', ['count' => $deletedDetailCount]);
    
    // ==================================================================
    // 7. Simpan DetailVolumetrik baru (Data utama kalibrasi) - TANPA formatNumericValue
    // ==================================================================
    $detailCount = 0;
    
    // Proses data untuk 5 nominal (nominal_1 sampai nominal_5)
    for ($nominalNumber = 1; $nominalNumber <= 5; $nominalNumber++) {
        // Ambil nilai nominal (nilai asli, tanpa format)
        $titikUkur = $request->input("nominal_{$nominalNumber}");
        
        // Ambil data untuk 3 pengulangan (nilai asli, tanpa format)
        $masssaKosong01 = $request->input("massa_kosong_{$nominalNumber}_1");
        $masssaKosong02 = $request->input("massa_kosong_{$nominalNumber}_2");
        $masssaKosong03 = $request->input("massa_kosong_{$nominalNumber}_3");
        
        $massaIsi01 = $request->input("massa_isi_{$nominalNumber}_1");
        $massaIsi02 = $request->input("massa_isi_{$nominalNumber}_2");
        $massaIsi03 = $request->input("massa_isi_{$nominalNumber}_3");
        
        $T_airSuling01 = $request->input("suhu_{$nominalNumber}_1");
        $T_airSuling02 = $request->input("suhu_{$nominalNumber}_2");
        $T_airSuling03 = $request->input("suhu_{$nominalNumber}_3");
        
        $P_Udara01 = $request->input("tekanan_{$nominalNumber}_1");
        $P_Udara02 = $request->input("tekanan_{$nominalNumber}_2");
        $P_Udara03 = $request->input("tekanan_{$nominalNumber}_3");
        
        // Cek apakah ada setidaknya satu data yang diisi
        $hasData = !empty($titikUkur) || 
                   !empty($masssaKosong01) || !empty($masssaKosong02) || !empty($masssaKosong03) ||
                   !empty($massaIsi01) || !empty($massaIsi02) || !empty($massaIsi03) ||
                   !empty($T_airSuling01) || !empty($T_airSuling02) || !empty($T_airSuling03) ||
                   !empty($P_Udara01) || !empty($P_Udara02) || !empty($P_Udara03);
        
        if ($hasData) {
            try {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_volumetrik_id' => $headVolumetrik->id,
                    'titikUkur' => $titikUkur,
                    
                    // Massa Kosong - 3 pengulangan
                    'masssaKosong01' => $masssaKosong01,
                    'masssaKosong02' => $masssaKosong02,
                    'masssaKosong03' => $masssaKosong03,
                    
                    // Massa Isi - 3 pengulangan
                    'massaIsi01' => $massaIsi01,
                    'massaIsi02' => $massaIsi02,
                    'massaIsi03' => $massaIsi03,
                    
                    // Suhu Air Suling - 3 pengulangan
                    'T_airSuling01' => $T_airSuling01,
                    'T_airSuling02' => $T_airSuling02,
                    'T_airSuling03' => $T_airSuling03,
                    
                    // Tekanan Udara - 3 pengulangan
                    'P_Udara01' => $P_Udara01,
                    'P_Udara02' => $P_Udara02,
                    'P_Udara03' => $P_Udara03,
                ];
                
                DetailVolumetrik::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ DetailVolumetrik nominal_{$nominalNumber} saved", [
                    'titikUkur' => $titikUkur,
                    'index' => $nominalNumber - 1
                ]);
                
            } catch (\Exception $e) {
                \Log::error("❌ Failed to save DetailVolumetrik nominal_{$nominalNumber}", [
                    'error' => $e->getMessage(),
                    'nominalNumber' => $nominalNumber
                ]);
            }
        }
    }
    
    \Log::info("✅ DetailVolumetrik saved: {$detailCount} records");
    
    // ==================================================================
    // 8. Hapus data AddVolumetrik lama
    // ==================================================================
    $deletedAddCount = AddVolumetrik::where('calibration_id', $calibration->id)->delete();
    \Log::info('🗑️ Deleted old AddVolumetrik records:', ['count' => $deletedAddCount]);
    
    // ==================================================================
    // 9. Simpan AddVolumetrik baru (Repeatability data) - TANPA formatNumericValue
    // ==================================================================
    $repeatCount = 0;
    $repeatabilityNominal = $request->repeatability_nominal;
    
    // Proses data dari input repeat_massa_kosong_1 sampai repeat_massa_kosong_10 (10 baris)
    for ($i = 1; $i <= 10; $i++) {
        // Ambil data dari request (nilai asli, tanpa format)
        $massaKosong = $request->input("repeat_massa_kosong_{$i}");
        $massaIsi = $request->input("repeat_massa_isi_{$i}");
        $T_airSuling = $request->input("repeat_suhu_{$i}");
        $P_Udara = $request->input("repeat_tekanan_{$i}");
        
        // Cek apakah ada data untuk baris ini
        $hasData = !empty($massaKosong) || !empty($massaIsi) || 
                   !empty($T_airSuling) || !empty($P_Udara);
        
        if ($hasData && !empty($repeatabilityNominal)) {
            try {
                $repeatData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $repeatabilityNominal,
                    'massaKosong' => $massaKosong,
                    'massaIsi' => $massaIsi,
                    'T_airSuling' => $T_airSuling,
                    'P_Udara' => $P_Udara,
                ];
                
                AddVolumetrik::create($repeatData);
                $repeatCount++;
                
            } catch (\Exception $e) {
                \Log::error("❌ Failed to save AddVolumetrik row {$i}", [
                    'error' => $e->getMessage(),
                    'row' => $i
                ]);
            }
        }
    }
    
    \Log::info("✅ AddVolumetrik saved: {$repeatCount} records");
    
    // ==================================================================
    // 10. Update Calibration dengan data tambahan
    // ==================================================================
    $updateData = [];
    
    // Periksa kedua kemungkinan nama field
    if ($request->filled('calibrated_by')) {
        $updateData['calibrated_by'] = $request->calibrated_by;
    } elseif ($request->filled('calibratedBy')) {
        $updateData['calibrated_by'] = $request->calibratedBy;
    }
    
    if ($request->filled('verified_by')) {
        $updateData['verified_by'] = $request->verified_by;
    } elseif ($request->filled('verifiedBy')) {
        $updateData['verified_by'] = $request->verifiedBy;
    }
    
    if ($request->filled('uncertainty')) {
        $updateData['uncertainty'] = $request->uncertainty;
    }
    
    if ($request->filled('conclusion')) {
        $updateData['keterangan'] = $request->conclusion;
    }
    
    if (!empty($updateData)) {
        $calibration->update($updateData);
        \Log::info('✅ Calibration additional data updated', $updateData);
    }
    
    // ==================================================================
    // 11. LOG HASIL AKHIR
    // ==================================================================
    $savedDetailCount = DetailVolumetrik::where('calibration_id', $calibration->id)->count();
    $savedAddCount = AddVolumetrik::where('calibration_id', $calibration->id)->count();
    
    \Log::info('📋 UPDATE VOLUMETRIK FINAL SUMMARY:', [
        'calibration_id' => $calibration->id,
        'nama_alat_lama' => $namaAlatLama,
        'nama_alat_baru' => $namaAlatBaru,
        'nama_alat_updated' => $namaAlatUpdated ? 'Yes' : 'No',
        'certificate_id_lama' => $certificateIdLama,
        'certificate_id_baru' => $certificateIdToUse,
        'certificate_updated' => $certificateIdUpdated ? 'Yes' : 'No',
        'certificate_method' => 'generateCertificateIdFromNamaAlat',
        'head_id' => $headVolumetrik->id,
        'detail_records' => $savedDetailCount,
        'add_records' => $savedAddCount,
        'standard' => $standardValue,
        'calibrated_by' => $calibration->calibrated_by ?? null,
        'verified_by' => $calibration->verified_by ?? null,
    ]);
    
    \Log::info('🎉 updateVolumetrik COMPLETED SUCCESSFULLY - menggunakan generateCertificateIdFromNamaAlat()');
    return true;
}


private function storeThermohygrometer($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeThermohygrometer');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeThermohygrometer called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. TENTUKAN TYPE (IN/OUT atau SINGLE)
        // ==================================================================
        $type = $this->getRequestValue($request, 'type', $tabId);
        if (empty($type) || !in_array($type, ['in_out', 'single'])) {
            $type = 'single';
            \Log::warning('⚠️ Type invalid or not found, set to default: single');
        }
        
        \Log::info('📊 Thermohygrometer type:', ['type' => $type, 'tab_id' => $tabId]);
        
        // ==================================================================
        // 2. SIMPAN TYPE KE CALIBRATION TABLE
        // ==================================================================
        $calibration->update([
            'type' => $type,
        ]);
        
        \Log::info('✅ Thermohygrometer type saved to calibration');
        
        // ==================================================================
        // 3. TENTUKAN STANDARD DAN METHOD
        // ==================================================================
        if ($type === 'in_out') {
            $alatStandarString = 'Temperature & Humidity Transmitter, Rotronic, 71946262; 20345594';
            $calibrationMethod = 'PAS-IK1102-50';
            \Log::info('🔧 Alat standar selected (IN/OUT fixed):', [
                'alat_standar' => $alatStandarString,
                'tab_id' => $tabId
            ]);
        } else {
            $alatStandar = [];
            
            for ($i = 1; $i <= 10; $i++) {
                $fieldName = "alat_standar_{$i}";
                $value = $this->getRequestValue($request, $fieldName, $tabId);
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
            
            $alatStandarArray = $request->input('alat_standar', []);
            if (is_array($alatStandarArray)) {
                foreach ($alatStandarArray as $value) {
                    if ($value && !in_array($value, $alatStandar)) {
                        $alatStandar[] = $value;
                    }
                }
            }
            
            $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            if (empty($alatStandarString)) {
                $alatStandarString = 'Temperature & Humidity Transmitter, Rotronic, 71946262; 20345594';
                \Log::warning('⚠️ No alat_standar provided for SINGLE type, using default');
            }
            
            $calibrationMethod = 'PAS-IK1102-50';
            
            \Log::info('📌 Using custom standard for SINGLE type', [
                'alat_standar_raw' => $alatStandar,
                'alat_standar_string' => $alatStandarString,
                'tab_id' => $tabId
            ]);
        }
        
        \Log::info('📊 Standard and method determined:', [
            'type' => $type,
            'standard' => $alatStandarString,
            'method' => $calibrationMethod,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 4. AMBIL DATA RENTANG UKUR, KAPASITAS, RESOLUSI DARI REQUEST
        // ==================================================================
        // Rentang Ukur °C
        $rentangUkurMinC = $request->input('rentang_ukur_min_c');
        $rentangUkurMaxC = $request->input('rentang_ukur_max_c');
        $rentangUkurC = $rentangUkurMinC;
        if (!empty($rentangUkurMaxC)) {
            $rentangUkurC .= ' - ' . $rentangUkurMaxC . ' °C';
        } elseif (!empty($rentangUkurMinC)) {
            $rentangUkurC .= ' °C';
        }
        
        // Rentang Ukur %RH
        $rentangUkurMinRh = $request->input('rentang_ukur_min_rh');
        $rentangUkurMaxRh = $request->input('rentang_ukur_max_rh');
        $rentangUkurRh = $rentangUkurMinRh;
        if (!empty($rentangUkurMaxRh)) {
            $rentangUkurRh .= ' - ' . $rentangUkurMaxRh . ' %RH';
        } elseif (!empty($rentangUkurMinRh)) {
            $rentangUkurRh .= ' %RH';
        }
        
        // Gabungkan rentang ukur
        $rentangUkur = $rentangUkurC;
        if (!empty($rentangUkurRh)) {
            $rentangUkur .= ' | ' . $rentangUkurRh;
        }
        
        // Kapasitas dan Resolusi
        $kapasitasC = $request->input('kapasitas_c');
        $resolusiC = $request->input('resolusi_c');
        $kapasitasRh = $request->input('kapasitas_rh');
        $resolusiRh = $request->input('resolusi_rh');
        
        \Log::info('📊 Rentang Ukur, Kapasitas, Resolusi:', [
            'rentang_ukur_c' => $rentangUkurC,
            'rentang_ukur_rh' => $rentangUkurRh,
            'rentang_ukur' => $rentangUkur,
            'kapasitas_c' => $kapasitasC,
            'resolusi_c' => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh' => $resolusiRh,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 5. SIMPAN KE HEAD THERMOHYGROMETER
        // ==================================================================
        $headData = [
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => $calibrationMethod,
            // Rentang Ukur
            'rentang_ukur' => $rentangUkur,
            'rentang_ukur_min_c' => $rentangUkurMinC,
            'rentang_ukur_max_c' => $rentangUkurMaxC,
            'rentang_ukur_min_rh' => $rentangUkurMinRh,
            'rentang_ukur_max_rh' => $rentangUkurMaxRh,
            // Kapasitas dan Resolusi
            'kapasitas_c' => $kapasitasC,
            'resolusi_c' => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh' => $resolusiRh,
        ];
        
        $headThermohygrometer = \App\Models\HeadThermohygrometer::where('calibration_id', $calibration->id)->first();
        
        if ($headThermohygrometer) {
            $headThermohygrometer->update($headData);
            \Log::info('✅ Updated existing HeadThermohygrometer with rentang ukur, kapasitas, resolusi');
        } else {
            \App\Models\HeadThermohygrometer::create($headData);
            \Log::info('✅ Created new HeadThermohygrometer with rentang ukur, kapasitas, resolusi');
        }
        
        // ==================================================================
        // 6. SIMPAN DETAIL BERDASARKAN TYPE (TANPA HAPUS DATA LAMA)
        // ==================================================================
        \Log::info('📊 Saving Thermohygrometer detail measurements...');
        
        $detailCount = 0;
        
        if ($type === 'in_out') {
            \Log::info('Processing IN/OUT data (7 rows)...');
            
            $tempData = $request->input('temp', []);
            $humidityData = $request->input('humidity', []);
            $maxRows = max(count($tempData), count($humidityData), 7);
            
            for ($i = 0; $i < $maxRows; $i++) {
                $tempRow = $tempData[$i] ?? [];
                $humidityRow = $humidityData[$i] ?? [];
                
                $tempSetPoint = $tempRow['set_point'] ?? null;
                $tempStdX1 = $tempRow['std_x1'] ?? null;
                $tempStdX2 = $tempRow['std_x2'] ?? null;
                $tempStdX3 = $tempRow['std_x3'] ?? null;
                $tempInX1 = $tempRow['in_x1'] ?? null;
                $tempInX2 = $tempRow['in_x2'] ?? null;
                $tempInX3 = $tempRow['in_x3'] ?? null;
                $tempOutX1 = $tempRow['out_x1'] ?? null;
                $tempOutX2 = $tempRow['out_x2'] ?? null;
                $tempOutX3 = $tempRow['out_x3'] ?? null;
                
                $humiditySetPoint = $humidityRow['set_point'] ?? null;
                $humidityStdX1 = $humidityRow['std_x1'] ?? null;
                $humidityStdX2 = $humidityRow['std_x2'] ?? null;
                $humidityStdX3 = $humidityRow['std_x3'] ?? null;
                $humidityAlatX1 = $humidityRow['alat_x1'] ?? null;
                $humidityAlatX2 = $humidityRow['alat_x2'] ?? null;
                $humidityAlatX3 = $humidityRow['alat_x3'] ?? null;
                
                $hasValidTempData = false;
                $tempValues = [$tempSetPoint, $tempStdX1, $tempStdX2, $tempStdX3, $tempInX1, $tempInX2, $tempInX3, $tempOutX1, $tempOutX2, $tempOutX3];
                foreach($tempValues as $value) {
                    if ($value !== null && $value !== '') {
                        $hasValidTempData = true;
                        break;
                    }
                }
                
                $hasValidHumidityData = false;
                $humidityValues = [$humiditySetPoint, $humidityStdX1, $humidityStdX2, $humidityStdX3, $humidityAlatX1, $humidityAlatX2, $humidityAlatX3];
                foreach($humidityValues as $value) {
                    if ($value !== null && $value !== '') {
                        $hasValidHumidityData = true;
                        break;
                    }
                }
                
                if ($hasValidTempData || $hasValidHumidityData) {
                    try {
                        \App\Models\DetailThermohygrometer::create([
                            'calibration_id' => $calibration->id,
                            'titikUkur_T' => $tempSetPoint,
                            'T_STD1' => $tempStdX1,
                            'T_STD2' => $tempStdX2,
                            'T_STD3' => $tempStdX3,
                            'T_IN1' => $tempInX1,
                            'T_IN2' => $tempInX2,
                            'T_IN3' => $tempInX3,
                            'T_OUT1' => $tempOutX1,
                            'T_OUT2' => $tempOutX2,
                            'T_OUT3' => $tempOutX3,
                            'titikUkur_RH' => $humiditySetPoint,
                            'RH_STD1' => $humidityStdX1,
                            'RH_STD2' => $humidityStdX2,
                            'RH_STD3' => $humidityStdX3,
                            'RH_ALAT1' => $humidityAlatX1,
                            'RH_ALAT2' => $humidityAlatX2,
                            'RH_ALAT3' => $humidityAlatX3,
                        ]);
                        
                        $detailCount++;
                        \Log::debug("✅ Saved IN/OUT row {$i}");
                        
                    } catch (\Exception $e) {
                        \Log::error("❌ Failed to save IN/OUT row {$i}: " . $e->getMessage());
                    }
                } else {
                    \Log::debug("⏭️ Skipping IN/OUT row {$i} - no data");
                }
            }
            
        } else {
            // ==============================================================
            // PROSES SINGLE TYPE - Menggunakan format field dengan _tab
            // ==============================================================
            \Log::info('Processing SINGLE data (10 rows)...');
            
            // Buat suffix untuk tab (contoh: _tab1, _tab2, dll)
            $tabSuffix = '_tab' . $tabId;
            
            for ($i = 1; $i <= 10; $i++) {
                // Ambil data temperatur dengan format t_set1, t_std1_1_tab1, dll
                $tSet = $request->input("t_set{$i}");
                $tStd1 = $request->input("t_std{$i}_1{$tabSuffix}");
                $tStd2 = $request->input("t_std{$i}_2{$tabSuffix}");
                $tStd3 = $request->input("t_std{$i}_3{$tabSuffix}");
                $tInst1 = $request->input("t_inst{$i}_1{$tabSuffix}");
                $tInst2 = $request->input("t_inst{$i}_2{$tabSuffix}");
                $tInst3 = $request->input("t_inst{$i}_3{$tabSuffix}");
                
                // Jika tidak ditemukan dengan format _tab, coba tanpa _tab
                if (empty($tStd1) && empty($tStd2) && empty($tStd3)) {
                    $tStd1 = $request->input("t_std{$i}_1");
                    $tStd2 = $request->input("t_std{$i}_2");
                    $tStd3 = $request->input("t_std{$i}_3");
                    $tInst1 = $request->input("t_inst{$i}_1");
                    $tInst2 = $request->input("t_inst{$i}_2");
                    $tInst3 = $request->input("t_inst{$i}_3");
                }
                
                // Ambil data humidity dengan format h_set1, h_std1_1_tab1, dll
                $hSet = $request->input("h_set{$i}");
                $hStd1 = $request->input("h_std{$i}_1{$tabSuffix}");
                $hStd2 = $request->input("h_std{$i}_2{$tabSuffix}");
                $hStd3 = $request->input("h_std{$i}_3{$tabSuffix}");
                $hInst1 = $request->input("h_inst{$i}_1{$tabSuffix}");
                $hInst2 = $request->input("h_inst{$i}_2{$tabSuffix}");
                $hInst3 = $request->input("h_inst{$i}_3{$tabSuffix}");
                
                // Jika tidak ditemukan dengan format _tab, coba tanpa _tab
                if (empty($hStd1) && empty($hStd2) && empty($hStd3)) {
                    $hStd1 = $request->input("h_std{$i}_1");
                    $hStd2 = $request->input("h_std{$i}_2");
                    $hStd3 = $request->input("h_std{$i}_3");
                    $hInst1 = $request->input("h_inst{$i}_1");
                    $hInst2 = $request->input("h_inst{$i}_2");
                    $hInst3 = $request->input("h_inst{$i}_3");
                }
                
                // Cek apakah ada data untuk baris ini
                $hasTempData = !empty($tSet) || !empty($tStd1) || !empty($tStd2) || !empty($tStd3) ||
                              !empty($tInst1) || !empty($tInst2) || !empty($tInst3);
                
                $hasHumidityData = !empty($hSet) || !empty($hStd1) || !empty($hStd2) || !empty($hStd3) ||
                                 !empty($hInst1) || !empty($hInst2) || !empty($hInst3);
                
                if ($hasTempData || $hasHumidityData) {
                    try {
                        \App\Models\DetailThermohygrometer::create([
                            'calibration_id' => $calibration->id,
                            
                            // Data Temperatur
                            'titikUkur_T' => $tSet,
                            'T_STD1' => $tStd1,
                            'T_STD2' => $tStd2,
                            'T_STD3' => $tStd3,
                            'T_IN1' => $tInst1,
                            'T_IN2' => $tInst2,
                            'T_IN3' => $tInst3,
                            'T_OUT1' => null,
                            'T_OUT2' => null,
                            'T_OUT3' => null,
                            
                            // Data Kelembaban
                            'titikUkur_RH' => $hSet,
                            'RH_STD1' => $hStd1,
                            'RH_STD2' => $hStd2,
                            'RH_STD3' => $hStd3,
                            'RH_ALAT1' => $hInst1,
                            'RH_ALAT2' => $hInst2,
                            'RH_ALAT3' => $hInst3,
                        ]);
                        
                        $detailCount++;
                        \Log::debug("✅ Saved SINGLE row {$i}", [
                            't_set' => $tSet,
                            'h_set' => $hSet,
                            'tab_suffix' => $tabSuffix
                        ]);
                        
                    } catch (\Exception $e) {
                        \Log::error("❌ Failed to save SINGLE row {$i}: " . $e->getMessage());
                    }
                } else {
                    \Log::debug("⏭️ Skipping SINGLE row {$i} - no data");
                }
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail records");
        
        // ==================================================================
        // 7. SIMPAN DATA TTD DAN NAMA
        // ==================================================================
        $additionalData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $additionalData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $additionalData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $additionalData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $additionalData['keterangan'] = $conclusion ?? '';
        }
        
        if (!empty($alatStandarString)) {
            $additionalData['alat_standar'] = $alatStandarString;
        }
        
        $calibrationMethodReq = $this->getRequestValue($request, 'calibration_method', $tabId);
        if ($calibrationMethodReq) {
            $additionalData['calibration_method'] = $calibrationMethodReq;
        }
        
        if (!empty($additionalData)) {
            $calibration->update($additionalData);
            \Log::info('✅ Additional data saved to calibration');
        }
        
        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = \App\Models\DetailThermohygrometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Thermohygrometer):', [
            'calibration_id' => $calibration->id,
            'type' => $type,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'alat_standar' => $alatStandarString,
            'calibration_method' => $calibrationMethod,
            'rentang_ukur' => $rentangUkur,
            'kapasitas_c' => $kapasitasC,
            'resolusi_c' => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh' => $resolusiRh,
        ]);
        
        \Log::info('🎉 storeThermohygrometer COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeThermohygrometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A'
        ]);
        
        throw new \Exception("Gagal menyimpan data Thermohygrometer: " . $e->getMessage());
    }
}

private function updateThermohygrometer($request, $calibration, $certificateId = null)
{
    try {
        \Log::info('🚀 START updateThermohygrometer', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $certificateId
        ]);

        // ==================================================================
        // 1. AMBIL NAMA ALAT BARU DARI REQUEST (name="nama_alat")
        // ==================================================================
        $namaAlatBaru = $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('📝 Nama alat untuk Thermohygrometer:', [
            'nama_alat' => $namaAlatBaru,
            'source' => 'nama_alat'
        ]);

        // ==================================================================
        // 2. GENERATE CERTIFICATE ID BARU BERDASARKAN NAMA ALAT
        // ==================================================================
        $finalCertificateId = $certificateId;
        
        // Jika certificateId dari parameter null atau nama alat berubah, generate baru
        if (empty($finalCertificateId) || $finalCertificateId != $calibration->certificate_id) {
            // Generate certificate ID baru berdasarkan nama alat
            $finalCertificateId = $this->generateCertificateIdFromNamaAlat($namaAlatBaru, $calibration);
            
            \Log::info('🆔 Generate certificate ID baru:', [
                'nama_alat' => $namaAlatBaru,
                'certificate_id_baru' => $finalCertificateId
            ]);
        }
        
        // Jika masih kosong, ambil dari calibration
        if (empty($finalCertificateId)) {
            $finalCertificateId = $calibration->certificate_id;
        }
        
        // Jika masih kosong, throw error
        if (empty($finalCertificateId)) {
            throw new \Exception('Certificate ID is required for Thermohygrometer update');
        }

        // ==================================================================
        // 3. UPDATE CERTIFICATE_ID DI TABEL HEAD DAN CALIBRATION
        // ==================================================================
        \Log::info('🔄 Update certificate_id di head_thermohygrometers dan calibration', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId
        ]);
        
        // Update di head_thermohygrometers
        \App\Models\HeadThermohygrometer::where('calibration_id', $calibration->id)
            ->update(['certificate_id' => $finalCertificateId]);
        
        // Update di tabel calibration
        $calibration->update(['certificate_id' => $finalCertificateId]);
        
        // Update nama alat di calibration jika berbeda
        if ($namaAlatBaru && $calibration->namaAlat !== $namaAlatBaru) {
            $calibration->update(['namaAlat' => $namaAlatBaru]);
            \Log::info('✅ Nama alat diupdate di calibration:', [
                'dari' => $calibration->getOriginal('namaAlat'),
                'menjadi' => $namaAlatBaru
            ]);
        }
        
        \Log::info('✅ Certificate ID updated di head_thermohygrometers dan calibration');

        // ==================================================================
        // 4. TENTUKAN TYPE (IN/OUT atau SINGLE)
        // ==================================================================
        $type = $calibration->type ?? 'single';
        
        if (!in_array($type, ['in_out', 'single'])) {
            $type = 'single';
            \Log::warning('⚠️ Type invalid, set to default: single');
        }
        
        \Log::info('📊 Thermohygrometer type for update:', ['type' => $type]);
        
        // ==================================================================
        // 5. TENTUKAN STANDARD DAN METHOD BERDASARKAN TYPE
        // ==================================================================
        if ($type === 'in_out') {
            $alatStandarString = $request->standard ?? $calibration->headThermohygrometer->standard ?? '';
            $calibrationMethod = $request->calibrationMethod ?? $calibration->headThermohygrometer->calibrationMethod ?? 'PAS-IK1102-50';
        } else {
            $alatStandarString = $request->standard ?? $calibration->headThermohygrometer->standard ?? 'Temperature & Humidity Transmitter, Rotronic,T017';
            $calibrationMethod = $request->calibrationMethod ?? $calibration->headThermohygrometer->calibrationMethod ?? 'PAS-IK1102-50';
        }
        
        \Log::info('📊 Standard and method for update:', [
            'type' => $type,
            'standard' => $alatStandarString,
            'method' => $calibrationMethod
        ]);
        
        // ==================================================================
        // 6. AMBIL DATA RENTANG UKUR, KAPASITAS, RESOLUSI DARI REQUEST
        // ==================================================================
        // Rentang Ukur °C
        $rentangUkurMinC = $request->input('rentang_ukur_min_c');
        $rentangUkurMaxC = $request->input('rentang_ukur_max_c');
        $rentangUkurC = $rentangUkurMinC;
        if (!empty($rentangUkurMaxC)) {
            $rentangUkurC .= ' - ' . $rentangUkurMaxC . ' °C';
        } elseif (!empty($rentangUkurMinC)) {
            $rentangUkurC .= ' °C';
        }
        
        // Rentang Ukur %RH
        $rentangUkurMinRh = $request->input('rentang_ukur_min_rh');
        $rentangUkurMaxRh = $request->input('rentang_ukur_max_rh');
        $rentangUkurRh = $rentangUkurMinRh;
        if (!empty($rentangUkurMaxRh)) {
            $rentangUkurRh .= ' - ' . $rentangUkurMaxRh . ' %RH';
        } elseif (!empty($rentangUkurMinRh)) {
            $rentangUkurRh .= ' %RH';
        }
        
        // Gabungkan rentang ukur
        $rentangUkur = $rentangUkurC;
        if (!empty($rentangUkurRh)) {
            $rentangUkur .= ' | ' . $rentangUkurRh;
        }
        
        // Kapasitas dan Resolusi
        $kapasitasC = $request->input('kapasitas_c');
        $resolusiC = $request->input('resolusi_c');
        $kapasitasRh = $request->input('kapasitas_rh');
        $resolusiRh = $request->input('resolusi_rh');
        
        \Log::info('📊 Rentang Ukur, Kapasitas, Resolusi for update:', [
            'rentang_ukur_c' => $rentangUkurC,
            'rentang_ukur_rh' => $rentangUkurRh,
            'rentang_ukur' => $rentangUkur,
            'kapasitas_c' => $kapasitasC,
            'resolusi_c' => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh' => $resolusiRh,
        ]);
        
        // ==================================================================
        // 7. UPDATE HEAD THERMOHYGROMETER
        // ==================================================================
        $headData = [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => $calibrationMethod,
            // Rentang Ukur
           
            'rentang_ukur_min_c' => $rentangUkurMinC,
            'rentang_ukur_max_c' => $rentangUkurMaxC,
            'rentang_ukur_min_rh' => $rentangUkurMinRh,
            'rentang_ukur_max_rh' => $rentangUkurMaxRh,
            // Kapasitas dan Resolusi
            'kapasitas_c' => $kapasitasC,
            'resolusi_c' => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh' => $resolusiRh,
        ];
        
        $headThermohygrometer = \App\Models\HeadThermohygrometer::where('calibration_id', $calibration->id)->first();
        
        if ($headThermohygrometer) {
            $headThermohygrometer->update($headData);
            \Log::info('✅ Updated existing HeadThermohygrometer with rentang ukur, kapasitas, resolusi', [
                'old_certificate_id' => $headThermohygrometer->certificate_id,
                'new_certificate_id' => $finalCertificateId
            ]);
        } else {
            $headThermohygrometer = \App\Models\HeadThermohygrometer::create($headData);
            \Log::info('✅ Created new HeadThermohygrometer with rentang ukur, kapasitas, resolusi', [
                'certificate_id' => $finalCertificateId
            ]);
        }
        
        // ==================================================================
        // 8. HAPUS DATA DETAIL LAMA
        // ==================================================================
        $existingDetails = \App\Models\DetailThermohygrometer::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            \App\Models\DetailThermohygrometer::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records");
        }
        
        // ==================================================================
        // 9. SIMPAN DETAIL BARU BERDASARKAN TYPE
        // ==================================================================
        \Log::info('📊 Updating Thermohygrometer detail measurements...');
        
        $detailCount = 0;
        
        if ($type === 'in_out') {
            for ($i = 0; $i < 7; $i++) {
                $tempSetPoint = $request->input("temp.{$i}.set_point");
                $tempStdX1 = $request->input("temp.{$i}.std_x1");
                $tempStdX2 = $request->input("temp.{$i}.std_x2");
                $tempStdX3 = $request->input("temp.{$i}.std_x3");
                $tempInX1 = $request->input("temp.{$i}.in_x1");
                $tempInX2 = $request->input("temp.{$i}.in_x2");
                $tempInX3 = $request->input("temp.{$i}.in_x3");
                $tempOutX1 = $request->input("temp.{$i}.out_x1");
                $tempOutX2 = $request->input("temp.{$i}.out_x2");
                $tempOutX3 = $request->input("temp.{$i}.out_x3");
                
                $humiditySetPoint = $request->input("humidity.{$i}.set_point");
                $humidityStdX1 = $request->input("humidity.{$i}.std_x1");
                $humidityStdX2 = $request->input("humidity.{$i}.std_x2");
                $humidityStdX3 = $request->input("humidity.{$i}.std_x3");
                $humidityAlatX1 = $request->input("humidity.{$i}.alat_x1");
                $humidityAlatX2 = $request->input("humidity.{$i}.alat_x2");
                $humidityAlatX3 = $request->input("humidity.{$i}.alat_x3");
                
                $hasTempData = $tempSetPoint !== null || $tempStdX1 !== null || $tempInX1 !== null;
                $hasHumidityData = $humiditySetPoint !== null || $humidityStdX1 !== null || $humidityAlatX1 !== null;
                
                if ($hasTempData || $hasHumidityData) {
                    \App\Models\DetailThermohygrometer::create([
                        'calibration_id' => $calibration->id,
                        'titikUkur_T' => $tempSetPoint,
                        'T_STD1' => $tempStdX1,
                        'T_STD2' => $tempStdX2,
                        'T_STD3' => $tempStdX3,
                        'T_IN1' => $tempInX1,
                        'T_IN2' => $tempInX2,
                        'T_IN3' => $tempInX3,
                        'T_OUT1' => $tempOutX1,
                        'T_OUT2' => $tempOutX2,
                        'T_OUT3' => $tempOutX3,
                        'titikUkur_RH' => $humiditySetPoint,
                        'RH_STD1' => $humidityStdX1,
                        'RH_STD2' => $humidityStdX2,
                        'RH_STD3' => $humidityStdX3,
                        'RH_ALAT1' => $humidityAlatX1,
                        'RH_ALAT2' => $humidityAlatX2,
                        'RH_ALAT3' => $humidityAlatX3,
                    ]);
                    $detailCount++;
                }
            }
            
        } else {
            // SINGLE type - SELALU 10 BARIS
            for ($i = 1; $i <= 10; $i++) {
                \App\Models\DetailThermohygrometer::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur_T' => $request->input("t_set{$i}"),
                    'T_STD1' => $request->input("t_std{$i}_1"),
                    'T_STD2' => $request->input("t_std{$i}_2"),
                    'T_STD3' => $request->input("t_std{$i}_3"),
                    'T_IN1' => $request->input("t_inst{$i}_1"),
                    'T_IN2' => $request->input("t_inst{$i}_2"),
                    'T_IN3' => $request->input("t_inst{$i}_3"),
                    'T_OUT1' => null,
                    'T_OUT2' => null,
                    'T_OUT3' => null,
                    'titikUkur_RH' => $request->input("h_set{$i}"),
                    'RH_STD1' => $request->input("h_std{$i}_1"),
                    'RH_STD2' => $request->input("h_std{$i}_2"),
                    'RH_STD3' => $request->input("h_std{$i}_3"),
                    'RH_ALAT1' => $request->input("h_inst{$i}_1"),
                    'RH_ALAT2' => $request->input("h_inst{$i}_2"),
                    'RH_ALAT3' => $request->input("h_inst{$i}_3"),
                ]);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Updated {$detailCount} detail records");
        
        // ==================================================================
        // 10. UPDATE DATA TAMBAHAN DI CALIBRATION TABLE
        // ==================================================================
        $additionalData = [];
         
        $calibratedByVal = $request->input('calibrated_by') ?? $request->input('calibratedBy');
        if (!empty($calibratedByVal)) {
            $additionalData['calibratedBy'] = $calibratedByVal;
        }
        
        $verifiedByVal = $request->input('verified_by') ?? $request->input('verifiedBy');
        if (!empty($verifiedByVal)) {
            $additionalData['verifiedBy'] = $verifiedByVal;
        }
        
        if ($request->filled('uncertainty')) {
            $additionalData['uncertainty'] = $request->uncertainty;
            $additionalData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($alatStandarString)) {
            $additionalData['alat_standar'] = $alatStandarString;
        }
        
        if (!empty($additionalData)) {
            $calibration->update($additionalData);
            \Log::info('✅ Additional data updated in calibration');
        }
        
        // ==================================================================
        // 11. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('🎉 updateThermohygrometer COMPLETED', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId,
            'nama_alat' => $namaAlatBaru,
            'type' => $type,
            'detail_records' => $detailCount,
            'alat_standar' => $alatStandarString,
            'calibration_method' => $calibrationMethod,
            'rentang_ukur' => $rentangUkur,
            'kapasitas_c' => $kapasitasC,
            'resolusi_c' => $resolusiC,
            'kapasitas_rh' => $kapasitasRh,
            'resolusi_rh' => $resolusiRh,
        ]);
        
        return $headThermohygrometer;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateThermohygrometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A'
        ]);
        
        throw new \Exception("Gagal mengupdate data Thermohygrometer: " . $e->getMessage());
    }
}

private function storeViscometer($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeViscometer with tab_id:', ['tab_id' => $tabId]);
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (8 CHECKBOX) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field (dengan dukungan _tab)
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array (tanpa _tab)
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Viscometer:', [
            'alat_standar' => $alatStandar,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN SATUAN STANDARD DAN SATUAN ALAT - DENGAN DUKUNGAN _tab
        // ==================================================================
        $satuanStd = $this->getRequestValue($request, 'satuan_std', $tabId) ?? '';
        $satuanAlat = $this->getRequestValue($request, 'satuan_alat', $tabId) ?? '';
        
        \Log::info('📏 Satuan:', [
            'satuan_std' => $satuanStd, 
            'satuan_alat' => $satuanAlat,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 3. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE)
        // ==================================================================
        $head = HeadViscometer::where('calibration_id', $calibration->id)->first();
        
        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $alatStandarString,
                'satuan_std' => $satuanStd,
                'satuan_alat' => $satuanAlat,
                'calibrationMethod' => 'PAS-IK1102-43',
            ]);
            \Log::info('✅ HeadViscometer updated:', ['head_id' => $head->id]);
        } else {
            // Buat head baru
            $head = HeadViscometer::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'satuan_std' => $satuanStd,
                'satuan_alat' => $satuanAlat,
                'calibrationMethod' => 'PAS-IK1102-43',
            ]);
            \Log::info('✅ HeadViscometer created:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 4. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE)
        // ==================================================================
        $existingDetails = DetailViscometer::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailViscometer::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records");
        }

        // ==================================================================
        // 5. SIMPAN DETAIL MEASUREMENTS (15 BARIS) - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving Viscometer detail measurements (15 rows)...');
        $detailCount = 0;
        
        for ($row = 0; $row < 15; $row++) {
            // Ambil data dari request dengan dukungan _tab
            $titikUkur = $this->getRequestValue($request, "nilai_standard_{$row}", $tabId);
            $spindle = $this->getRequestValue($request, "spindle_{$row}", $tabId);
            $rpm = $this->getRequestValue($request, "rpm_{$row}", $tabId);
            $ulangan01 = $this->getRequestValue($request, "pembacaan_1_{$row}", $tabId);
            $ulangan02 = $this->getRequestValue($request, "pembacaan_2_{$row}", $tabId);
            $ulangan03 = $this->getRequestValue($request, "pembacaan_3_{$row}", $tabId);
            $ulangan04 = $this->getRequestValue($request, "pembacaan_4_{$row}", $tabId);
            $ulangan05 = $this->getRequestValue($request, "pembacaan_5_{$row}", $tabId);
            $resolution = $this->getRequestValue($request, "resolusi_{$row}", $tabId);
            $tAwal = $this->getRequestValue($request, "suhu_awal_{$row}", $tabId);
            $tAkhir = $this->getRequestValue($request, "suhu_akhir_{$row}", $tabId);
            
            // Cek apakah ada data untuk baris ini (minimal satu kolom terisi)
            $hasData = !empty($titikUkur) || !empty($spindle) || !empty($rpm) || 
                      !empty($ulangan01) || !empty($ulangan02) || !empty($ulangan03) ||
                      !empty($ulangan04) || !empty($ulangan05) || !empty($resolution) ||
                      !empty($tAwal) || !empty($tAkhir);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'spindle' => $spindle,
                    'RPM' => $rpm,
                    'ulangan01' => $ulangan01,
                    'ulangan02' => $ulangan02,
                    'ulangan03' => $ulangan03,
                    'ulangan04' => $ulangan04,
                    'ulangan05' => $ulangan05,
                    'resolution' => $resolution,
                    'T_awal' => $tAwal,
                    'T_akhir' => $tAkhir,
                ];
                
                DetailViscometer::create($detailData);
                $detailCount++;
                
                \Log::debug("📝 Saved Viscometer row {$row}", [
                    'titikUkur' => $titikUkur,
                    'spindle' => $spindle,
                    'RPM' => $rpm,
                    'tab_id' => $tabId
                ]);
            } else {
                \Log::debug("⏭️ Skipping Viscometer row {$row} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Viscometer");

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $updateData = [];
        
        // Nama untuk TTD Dikalibrasi
        $dikalibrasiNama = $this->getRequestValue($request, 'dikalibrasi_nama', $tabId);
        if ($dikalibrasiNama) {
            $updateData['calibrated_by'] = $dikalibrasiNama;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $dikalibrasiNama, 'tab_id' => $tabId]);
        }
        
        // Nama untuk TTD Diperiksa
        $diperiksaNama = $this->getRequestValue($request, 'diperiksa_nama', $tabId);
        if ($diperiksaNama) {
            $updateData['verified_by'] = $diperiksaNama;
            \Log::info('📝 Nama diperiksa:', ['nama' => $diperiksaNama, 'tab_id' => $tabId]);
        }
        
        // TTD Dikalibrasi
        $dikalibrasiTtd = $this->getRequestValue($request, 'dikalibrasi_ttd', $tabId);
        if ($dikalibrasiTtd) {
            \Log::info('✍️ TTD dikalibrasi:', ['ttd' => $dikalibrasiTtd, 'tab_id' => $tabId]);
            if ($head) {
                $head->update(['ttd_kalibrator' => $dikalibrasiTtd]);
            }
        }
        
        // TTD Diperiksa
        $diperiksaTtd = $this->getRequestValue($request, 'diperiksa_ttd', $tabId);
        if ($diperiksaTtd) {
            \Log::info('✍️ TTD diperiksa:', ['ttd' => $diperiksaTtd, 'tab_id' => $tabId]);
            if ($head) {
                $head->update(['ttd_pemeriksa' => $diperiksaTtd]);
            }
        }
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Alat standar sudah ditentukan di atas
        if (!empty($alatStandarString)) {
            $updateData['alat_standar'] = $alatStandarString;
        }
        
        $calibrationMethodReq = $this->getRequestValue($request, 'calibration_method', $tabId);
        if ($calibrationMethodReq) {
            $updateData['calibration_method'] = $calibrationMethodReq;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailViscometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Viscometer):', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'alat_standar' => $alatStandarString,
            'satuan_std' => $satuanStd,
            'satuan_alat' => $satuanAlat,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 storeViscometer COMPLETED for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeViscometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailViscometer::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Viscometer: " . $e->getMessage());
    }
}

/**
 * Update Viscometer data
 */
private function updateViscometer($request, $calibration, $certificateId = null)
{
    try {
        \Log::info('🚀 START updateViscometer', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $certificateId
        ]);

        // ==================================================================
        // 1. AMBIL NAMA ALAT BARU DARI REQUEST
        // ==================================================================
        $namaAlatBaru = $request->namaAlat ?? $calibration->namaAlat;
        
        \Log::info('📝 Nama alat untuk Viscometer:', [
            'nama_alat' => $namaAlatBaru,
            'source' => 'namaAlat'
        ]);

        // ==================================================================
        // 2. GENERATE CERTIFICATE ID BARU BERDASARKAN NAMA ALAT
        // ==================================================================
        $finalCertificateId = $certificateId;
        
        // Jika certificateId dari parameter null atau nama alat berubah, generate baru
        if (empty($finalCertificateId) || $finalCertificateId != $calibration->certificate_id) {
            // Generate certificate ID baru berdasarkan nama alat
            $finalCertificateId = $this->generateCertificateIdFromNamaAlat($namaAlatBaru, $calibration);
            
            \Log::info('🆔 Generate certificate ID baru:', [
                'nama_alat' => $namaAlatBaru,
                'certificate_id_baru' => $finalCertificateId
            ]);
        }
        
        // Jika masih kosong, ambil dari calibration
        if (empty($finalCertificateId)) {
            $finalCertificateId = $calibration->certificate_id;
        }
        
        // Jika masih kosong, throw error
        if (empty($finalCertificateId)) {
            throw new \Exception('Certificate ID is required for Viscometer update');
        }

        // ==================================================================
        // 3. UPDATE CERTIFICATE_ID DI TABEL HEAD DAN CALIBRATION
        // ==================================================================
        \Log::info('🔄 Update certificate_id di head_viscometers dan calibration', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId
        ]);
        
        // Update di head_viscometers
        \App\Models\HeadViscometer::where('calibration_id', $calibration->id)
            ->update(['certificate_id' => $finalCertificateId]);
        
        // Update di tabel calibration
        $calibration->update(['certificate_id' => $finalCertificateId]);
        
        // Update nama alat di calibration jika berbeda
        if ($namaAlatBaru && $calibration->namaAlat !== $namaAlatBaru) {
            $calibration->update(['namaAlat' => $namaAlatBaru]);
            \Log::info('✅ Nama alat diupdate di calibration:', [
                'dari' => $calibration->getOriginal('namaAlat'),
                'menjadi' => $namaAlatBaru
            ]);
        }
        
        \Log::info('✅ Certificate ID updated di head_viscometers dan calibration');

        // ==================================================================
        // 4. PROSES ALAT STANDAR (MULTIPLE CHECKBOX)
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        
        // Proses viscosity types jika ada
        $viscosityTypes = $request->viscosity_types ?? [];
        $thermometerTypes = $request->thermometer_types ?? [];
        
        // Gabungkan semua tipe yang dipilih
        $allSelectedTypes = array_merge($viscosityTypes, $thermometerTypes);
        
        // Jika ada alat standar yang dipilih, gabungkan dengan tipe-tipenya
        if (!empty($alatStandar) || !empty($allSelectedTypes)) {
            $alatStandarString = !empty($allSelectedTypes) ? implode(', ', $allSelectedTypes) : implode(', ', $alatStandar);
        } else {
            $alatStandarString = '';
        }
        
        \Log::info('🔧 Alat standar:', ['standard' => $alatStandarString]);

        // ==================================================================
        // 5. UPDATE SATUAN STANDARD DAN SATUAN ALAT
        // ==================================================================
        $satuanStd = $request->satuan_std ?? '';
        $satuanAlat = $request->satuan_alat ?? '';
        $calibrationMethod = $request->calibrationMethod ?? 'PAS-IK1102-43B';
        
        \Log::info('📏 Satuan:', ['satuan_std' => $satuanStd, 'satuan_alat' => $satuanAlat]);

        // ==================================================================
        // 6. UPDATE HEAD VISCOMETER
        // ==================================================================
        if ($head = $calibration->headViscometer) {
            $head->update([
                'certificate_id' => $finalCertificateId,
                'standard' => $alatStandarString,
                'satuan_std' => $satuanStd,
                'satuan_alat' => $satuanAlat,
                'calibrationMethod' => $calibrationMethod,
                'ttd_kalibrator' => $request->ttd_kalibrator ?? $head->ttd_kalibrator,
                'ttd_pemeriksa' => $request->ttd_pemeriksa ?? $head->ttd_pemeriksa,
            ]);
            \Log::info('✅ HeadViscometer updated:', [
                'head_id' => $head->id,
                'certificate_id' => $finalCertificateId
            ]);
        } else {
            // Jika head belum ada, buat baru
            $head = HeadViscometer::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $finalCertificateId,
                'standard' => $alatStandarString,
                'satuan_std' => $satuanStd,
                'satuan_alat' => $satuanAlat,
                'calibrationMethod' => $calibrationMethod,
                'ttd_kalibrator' => $request->ttd_kalibrator ?? null,
                'ttd_pemeriksa' => $request->ttd_pemeriksa ?? null,
            ]);
            \Log::info('➕ HeadViscometer created baru:', [
                'head_id' => $head->id,
                'certificate_id' => $finalCertificateId
            ]);
        }

        // ==================================================================
        // 7. UPDATE DETAIL VISCOMETER (DELETE & RECREATE 15 BARIS)
        // ==================================================================
        // Hapus data detail lama
        $deleted = DetailViscometer::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old details:', ['count' => $deleted]);
        
        $detailCount = 0;
        
        // Proses 15 baris - TANPA formatNumericValue
        for ($row = 0; $row < 15; $row++) {
            // Ambil data dari request sesuai dengan form edit
            $titikUkur = $request->titikUkur[$row] ?? null;
            $spindle = $request->spindle[$row] ?? null;
            $rpm = $request->RPM[$row] ?? null;
            $ulangan01 = $request->ulangan01[$row] ?? null;
            $ulangan02 = $request->ulangan02[$row] ?? null;
            $ulangan03 = $request->ulangan03[$row] ?? null;
            $ulangan04 = $request->ulangan04[$row] ?? null;
            $ulangan05 = $request->ulangan05[$row] ?? null;
            $resolution = $request->resolution[$row] ?? null;
            $tAwal = $request->T_awal[$row] ?? null;
            $tAkhir = $request->T_akhir[$row] ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($titikUkur) || !empty($spindle) || !empty($rpm) || 
                      !empty($ulangan01) || !empty($ulangan02) || !empty($ulangan03) ||
                      !empty($ulangan04) || !empty($ulangan05) || !empty($resolution) ||
                      !empty($tAwal) || !empty($tAkhir);
            
            if ($hasData) {
                DetailViscometer::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'spindle' => $spindle,
                    'RPM' => $rpm,
                    'ulangan01' => $ulangan01,
                    'ulangan02' => $ulangan02,
                    'ulangan03' => $ulangan03,
                    'ulangan04' => $ulangan04,
                    'ulangan05' => $ulangan05,
                    'resolution' => $resolution,
                    'T_awal' => $tAwal,
                    'T_akhir' => $tAkhir,
                ]);
                $detailCount++;
                
                \Log::debug("📝 Saved Viscometer row {$row}", [
                    'titikUkur' => $titikUkur,
                    'spindle' => $spindle,
                    'RPM' => $rpm
                ]);
            }
        }
        
        \Log::info('✅ DetailViscometer updated:', ['total_records' => $detailCount]);

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $finalDetailCount = DetailViscometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Viscometer):', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId,
            'nama_alat' => $namaAlatBaru,
            'detail_records' => $finalDetailCount,
            'standard' => $alatStandarString,
            'satuan_std' => $satuanStd,
            'satuan_alat' => $satuanAlat,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updateViscometer COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateViscometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function storePushPull($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storePushPull with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 0. DEBUG SEMUA INPUT STD (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $debugStd = [];
        for ($i = 1; $i <= 10; $i++) {
            $debugStd["std_{$i}"] = $this->getRequestValue($request, "std_{$i}", $tabId) ?? 'NULL';
        }
        \Log::info('🔍 DEBUG STD INPUTS:', array_merge(['tab_id' => $tabId], $debugStd));

        // ==================================================================
        // 1. PROSES ALAT STANDAR (DENGAN DUKUNGAN _tab)
        // ==================================================================
        // Cek textarea terlebih dahulu
        $textValue = trim($this->getRequestValue($request, 'alat_standar_text', $tabId) ?? '');
        
        // Cek array checkbox
        $arrayValue = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (!is_array($arrayValue)) {
            $arrayValue = $request->input('alat_standar', []);
        }

        if (!empty($textValue)) {
            $standardValue = $textValue; // Prioritas: textarea
        } elseif (is_array($arrayValue) && count($arrayValue) > 0) {
            $standardValue = implode("\n", $arrayValue); // Fallback ke checkbox
        } else {
            $standardValue = '';
        }
        
        \Log::info('🔧 Alat standar selected for Push Pull:', [
            'standard' => $standardValue,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE)
        // ==================================================================
        $head = HeadPushPull::where('calibration_id', $calibration->id)->first();
        
        $satuanTitikUkur = $this->getRequestValue($request, 'satuan_titik_ukur', $tabId);
        $satuanTarik = $this->getRequestValue($request, 'satuan_tarik', $tabId);
        $satuanTekan = $this->getRequestValue($request, 'satuan_tekan', $tabId);
        
        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-34',
                'satuan_titik_ukur' => $satuanTitikUkur,
                'satuan_tarik' => $satuanTarik,
                'satuan_tekan' => $satuanTekan,
            ]);
            \Log::info('✅ HeadPushPull updated:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        } else {
            // Buat head baru
            $head = HeadPushPull::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-34',
                'satuan_titik_ukur' => $satuanTitikUkur,
                'satuan_tarik' => $satuanTarik,
                'satuan_tekan' => $satuanTekan,
            ]);
            \Log::info('✅ HeadPushPull created:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        }

        // ==================================================================
        // 3. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE)
        // ==================================================================
        $existingDetails = DetailPushPull::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailPushPull::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records");
        }
        
        $existingAddData = AddPushPull::where('calibration_id', $calibration->id)->count();
        if ($existingAddData > 0) {
            AddPushPull::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingAddData} old add data records");
        }

        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS (10 BARIS) - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving DetailPushPull detail measurements...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 10; $i++) {
            // Ambil data dengan dukungan _tab
            $titikUkur = $this->getRequestValue($request, "titik_ukur_{$i}", $tabId);
            $std = $this->getRequestValue($request, "std_{$i}", $tabId);
            
            // Data tarik
            $tarik01 = $this->getRequestValue($request, "tarik_{$i}_1", $tabId);
            $tarik02 = $this->getRequestValue($request, "tarik_{$i}_2", $tabId);
            $tarik03 = $this->getRequestValue($request, "tarik_{$i}_3", $tabId);
            
            // Data tekan
            $tekan01 = $this->getRequestValue($request, "tekan_{$i}_1", $tabId);
            $tekan02 = $this->getRequestValue($request, "tekan_{$i}_2", $tabId);
            $tekan03 = $this->getRequestValue($request, "tekan_{$i}_3", $tabId);
            
            // Debug setiap baris
            \Log::debug("📝 Row {$i} raw data (tab {$tabId}):", [
                'titik_ukur' => $titikUkur,
                'std' => $std,
                'tarik01' => $tarik01,
                'tarik02' => $tarik02,
                'tarik03' => $tarik03,
                'tekan01' => $tekan01,
                'tekan02' => $tekan02,
                'tekan03' => $tekan03,
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($titikUkur) || !empty($std) || 
                      !empty($tarik01) || !empty($tarik02) || !empty($tarik03) || 
                      !empty($tekan01) || !empty($tekan02) || !empty($tekan03);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'STD' => $std,
                    'ulanganTarik01' => $tarik01,
                    'ulanganTarik02' => $tarik02,
                    'ulanganTarik03' => $tarik03,
                    'ulanganTekan01' => $tekan01,
                    'ulanganTekan02' => $tekan02,
                    'ulanganTekan03' => $tekan03,
                ];

                // Debug sebelum menyimpan
                \Log::debug("💾 Saving row {$i}:", $detailData);
                
                // Simpan
                $detailRecord = DetailPushPull::create($detailData);
                $detailCount++;
                
                // Debug setelah menyimpan
                \Log::debug("✅ Saved row {$i}, ID: {$detailRecord->id}", [
                    'saved_STD' => $detailRecord->STD,
                    'saved_titikUkur' => $detailRecord->titikUkur
                ]);
            } else {
                \Log::debug("⏭️ Skipping row {$i} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Push Pull");

        // ==================================================================
        // 5. VERIFIKASI DATA YANG DISIMPAN
        // ==================================================================
        $savedDetails = DetailPushPull::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🔎 VERIFICATION - Saved details:', [
            'total_saved' => $savedDetails->count(),
            'tab_id' => $tabId,
            'data_sample' => $savedDetails->take(3)->map(function($item) {
                return [
                    'id' => $item->id,
                    'titikUkur' => $item->titikUkur,
                    'STD' => $item->STD,
                    'ulanganTarik01' => $item->ulanganTarik01,
                    'created_at' => $item->created_at
                ];
            })->toArray(),
            'all_STD_values' => $savedDetails->pluck('STD')->toArray()
        ]);

        // ==================================================================
        // 6. SIMPAN ADD PUSH PULL (REPEATABILITY) - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving AddPushPull data (repeatability)...');
        
        $addData = [
            'calibration_id' => $calibration->id,
            
            // Repeatability Tarik
            'repeatabilityTarik01' => $this->getRequestValue($request, 'repeat_tarik_1', $tabId),
            'repeatabilityTarik02' => $this->getRequestValue($request, 'repeat_tarik_2', $tabId),
            'repeatabilityTarik03' => $this->getRequestValue($request, 'repeat_tarik_3', $tabId),
            'repeatabilityTarik04' => $this->getRequestValue($request, 'repeat_tarik_4', $tabId),
            'repeatabilityTarik05' => $this->getRequestValue($request, 'repeat_tarik_5', $tabId),
            'repeatabilityTarik06' => $this->getRequestValue($request, 'repeat_tarik_6', $tabId),
            'repeatabilityTarik07' => $this->getRequestValue($request, 'repeat_tarik_7', $tabId),
            'repeatabilityTarik08' => $this->getRequestValue($request, 'repeat_tarik_8', $tabId),
            'repeatabilityTarik09' => $this->getRequestValue($request, 'repeat_tarik_9', $tabId),
            'repeatabilityTarik10' => $this->getRequestValue($request, 'repeat_tarik_10', $tabId),
            
            // Repeatability Tekan
            'repeatabilityTekan01' => $this->getRequestValue($request, 'repeat_tekan_1', $tabId),
            'repeatabilityTekan02' => $this->getRequestValue($request, 'repeat_tekan_2', $tabId),
            'repeatabilityTekan03' => $this->getRequestValue($request, 'repeat_tekan_3', $tabId),
            'repeatabilityTekan04' => $this->getRequestValue($request, 'repeat_tekan_4', $tabId),
            'repeatabilityTekan05' => $this->getRequestValue($request, 'repeat_tekan_5', $tabId),
            'repeatabilityTekan06' => $this->getRequestValue($request, 'repeat_tekan_6', $tabId),
            'repeatabilityTekan07' => $this->getRequestValue($request, 'repeat_tekan_7', $tabId),
            'repeatabilityTekan08' => $this->getRequestValue($request, 'repeat_tekan_8', $tabId),
            'repeatabilityTekan09' => $this->getRequestValue($request, 'repeat_tekan_9', $tabId),
            'repeatabilityTekan10' => $this->getRequestValue($request, 'repeat_tekan_10', $tabId),
        ];
        
        // Cek data untuk disimpan
        $hasAddData = false;
        foreach ($addData as $key => $value) {
            if (!in_array($key, ['calibration_id']) && $value !== null && $value !== '') {
                $hasAddData = true;
                break;
            }
        }
        
        if ($hasAddData) {
            $addRecord = AddPushPull::create($addData);
            \Log::info('✅ AddPushPull saved:', ['add_id' => $addRecord->id, 'tab_id' => $tabId]);
        } else {
            \Log::info('⚠️ No AddPushPull data to save');
        }

        // ==================================================================
        // 7. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $updateData = [];
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Calibrated by
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy, 'tab_id' => $tabId]);
        }
        
        // Verified by
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy, 'tab_id' => $tabId]);
        }
        
        // Alat standar
        if (!empty($standardValue)) {
            $updateData['alat_standar'] = $standardValue;
        }
        
        // Calibration method
        $calibrationMethodReq = $this->getRequestValue($request, 'calibration_method', $tabId);
        if ($calibrationMethodReq) {
            $updateData['calibration_method'] = $calibrationMethodReq;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 8. FINAL VERIFICATION
        // ==================================================================
        $allDetails = DetailPushPull::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🏁 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId,
            'total_details' => $allDetails->count(),
            'STD_values' => $allDetails->pluck('STD')->toArray(),
            'first_record_full' => $allDetails->first() ? $allDetails->first()->toArray() : null
        ]);

        \Log::info('🎉 storePushPull COMPLETED for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storePushPull:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal menyimpan data Push Pull: " . $e->getMessage());
    }
}
private function updatePushPull($request, $calibration, $certificateId = null)
{
    try {
        \Log::info('🚀 START updatePushPull', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $certificateId
        ]);

        // ==================================================================
        // 1. AMBIL NAMA ALAT BARU DARI REQUEST
        // ==================================================================
        $namaAlatBaru = $request->namaAlat ?? $calibration->namaAlat;
        
        \Log::info('📝 Nama alat untuk Push Pull:', [
            'nama_alat' => $namaAlatBaru,
            'source' => 'namaAlat'
        ]);

        // ==================================================================
        // 2. GENERATE CERTIFICATE ID BARU BERDASARKAN NAMA ALAT
        // ==================================================================
        $finalCertificateId = $certificateId;
        
        // Jika certificateId dari parameter null atau nama alat berubah, generate baru
        if (empty($finalCertificateId) || $finalCertificateId != $calibration->certificate_id) {
            // Generate certificate ID baru berdasarkan nama alat
            $finalCertificateId = $this->generateCertificateIdFromNamaAlat($namaAlatBaru, $calibration);
            
            \Log::info('🆔 Generate certificate ID baru:', [
                'nama_alat' => $namaAlatBaru,
                'certificate_id_baru' => $finalCertificateId
            ]);
        }
        
        // Jika masih kosong, ambil dari calibration
        if (empty($finalCertificateId)) {
            $finalCertificateId = $calibration->certificate_id;
        }
        
        // Jika masih kosong, throw error
        if (empty($finalCertificateId)) {
            throw new \Exception('Certificate ID is required for Push Pull update');
        }

        // ==================================================================
        // 3. UPDATE CERTIFICATE_ID DI TABEL HEAD DAN CALIBRATION
        // ==================================================================
        \Log::info('🔄 Update certificate_id di head_pushpulls dan calibration', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId
        ]);
        
        // Update di head_pushpulls
        \App\Models\HeadPushPull::where('calibration_id', $calibration->id)
            ->update(['certificate_id' => $finalCertificateId]);
        
        // Update di tabel calibration
        $calibration->update(['certificate_id' => $finalCertificateId]);
        
        // Update nama alat di calibration jika berbeda
        if ($namaAlatBaru && $calibration->namaAlat !== $namaAlatBaru) {
            $calibration->update(['namaAlat' => $namaAlatBaru]);
            \Log::info('✅ Nama alat diupdate di calibration:', [
                'dari' => $calibration->getOriginal('namaAlat'),
                'menjadi' => $namaAlatBaru
            ]);
        }
        
        \Log::info('✅ Certificate ID updated di head_pushpulls dan calibration');

        // ==================================================================
        // 4. UPDATE HEAD PUSH PULL (termasuk satuan)
        // ==================================================================
        $head = HeadPushPull::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'certificate_id' => $finalCertificateId,
            'standard' => $request->standard ?? '',
            'satuanTarik' => $request->satuan_tarik ?? 'N',
            'satuanTekan' => $request->satuan_tekan ?? 'N',
            'satuanTitikUkur' => $request->satuan_titik_ukur ?? 'N',
            'calibrationMethod' => 'PAS-IK1102-34',
        ];
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadPushpull updated:', [
                'head_id' => $head->id,
                'certificate_id' => $finalCertificateId
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadPushPull::create($headData);
            \Log::info('➕ HeadPushPull created:', [
                'head_id' => $head->id,
                'certificate_id' => $finalCertificateId
            ]);
        }

        // ==================================================================
        // 5. UPDATE DETAIL PUSH PULL (TANPA formatNumericValue)
        // ==================================================================
        // Hapus data detail lama
        DetailPushpull::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        // Ambil data dari request (dalam bentuk array)
        $titikUkurArray = $request->input('titikUkur', []);
        $stdArray = $request->input('STD', []);
        $ulanganTarik01Array = $request->input('ulanganTarik01', []);
        $ulanganTarik02Array = $request->input('ulanganTarik02', []);
        $ulanganTarik03Array = $request->input('ulanganTarik03', []);
        $ulanganTekan01Array = $request->input('ulanganTekan01', []);
        $ulanganTekan02Array = $request->input('ulanganTekan02', []);
        $ulanganTekan03Array = $request->input('ulanganTekan03', []);
        
        // Proses maksimal 10 baris
        for ($i = 0; $i < 10; $i++) {
            $titikUkur = $titikUkurArray[$i] ?? null;
            $std = $stdArray[$i] ?? null;
            
            // Data tarik (pull)
            $tarik01 = $ulanganTarik01Array[$i] ?? null;
            $tarik02 = $ulanganTarik02Array[$i] ?? null;
            $tarik03 = $ulanganTarik03Array[$i] ?? null;
            
            // Data tekan (push)
            $tekan01 = $ulanganTekan01Array[$i] ?? null;
            $tekan02 = $ulanganTekan02Array[$i] ?? null;
            $tekan03 = $ulanganTekan03Array[$i] ?? null;
            
            // Cek apakah ada data (tidak kosong)
            $hasData = !empty($titikUkur) || !empty($std) || 
                      !empty($tarik01) || !empty($tarik02) || !empty($tarik03) ||
                      !empty($tekan01) || !empty($tekan02) || !empty($tekan03);
            
            if ($hasData) {
                DetailPushpull::create([
                    'calibration_id' => $calibration->id,
                    'head_pushpull_id' => $head->id,
                    'titikUkur' => $titikUkur,  // LANGSUNG tanpa formatNumericValue
                    'STD' => $std,
                    'ulanganTarik01' => $tarik01,  // LANGSUNG tanpa formatNumericValue
                    'ulanganTarik02' => $tarik02,  // LANGSUNG tanpa formatNumericValue
                    'ulanganTarik03' => $tarik03,  // LANGSUNG tanpa formatNumericValue
                    'ulanganTekan01' => $tekan01,  // LANGSUNG tanpa formatNumericValue
                    'ulanganTekan02' => $tekan02,  // LANGSUNG tanpa formatNumericValue
                    'ulanganTekan03' => $tekan03,  // LANGSUNG tanpa formatNumericValue
                ]);
                $detailCount++;
            }
        }
        
        \Log::info('✅ DetailPushpull updated:', ['total_records' => $detailCount]);

        // ==================================================================
        // 6. UPDATE ADD PUSH PULL (repeatability) - TANPA formatNumericValue
        // ==================================================================
        $addPushpull = AddPushpull::where('calibration_id', $calibration->id)->first();
        
        // Data repeatability dari request - LANGSUNG tanpa formatNumericValue
        $addData = [
            'repeatabilityTarik01' => $request->repeatabilityTarik01 ?? null,
            'repeatabilityTarik02' => $request->repeatabilityTarik02 ?? null,
            'repeatabilityTarik03' => $request->repeatabilityTarik03 ?? null,
            'repeatabilityTarik04' => $request->repeatabilityTarik04 ?? null,
            'repeatabilityTarik05' => $request->repeatabilityTarik05 ?? null,
            'repeatabilityTarik06' => $request->repeatabilityTarik06 ?? null,
            'repeatabilityTarik07' => $request->repeatabilityTarik07 ?? null,
            'repeatabilityTarik08' => $request->repeatabilityTarik08 ?? null,
            'repeatabilityTarik09' => $request->repeatabilityTarik09 ?? null,
            'repeatabilityTarik10' => $request->repeatabilityTarik10 ?? null,
            
            'repeatabilityTekan01' => $request->repeatabilityTekan01 ?? null,
            'repeatabilityTekan02' => $request->repeatabilityTekan02 ?? null,
            'repeatabilityTekan03' => $request->repeatabilityTekan03 ?? null,
            'repeatabilityTekan04' => $request->repeatabilityTekan04 ?? null,
            'repeatabilityTekan05' => $request->repeatabilityTekan05 ?? null,
            'repeatabilityTekan06' => $request->repeatabilityTekan06 ?? null,
            'repeatabilityTekan07' => $request->repeatabilityTekan07 ?? null,
            'repeatabilityTekan08' => $request->repeatabilityTekan08 ?? null,
            'repeatabilityTekan09' => $request->repeatabilityTekan09 ?? null,
            'repeatabilityTekan10' => $request->repeatabilityTekan10 ?? null,
        ];
        
        // Cek apakah ada data repeatability yang terisi
        $hasAddData = false;
        foreach ($addData as $value) {
            if ($value !== null && $value !== '') {
                $hasAddData = true;
                break;
            }
        }
        
        if ($hasAddData) {
            if ($addPushpull) {
                $addPushpull->update($addData);
                \Log::info('✅ AddPushpull updated');
            } else {
                $addData['calibration_id'] = $calibration->id;
                AddPushpull::create($addData);
                \Log::info('➕ AddPushpull created');
            }
        }

        // ==================================================================
        // 7. UPDATE CALIBRATION (verified_by, calibrated_by)
        // ==================================================================
        $updateCalibration = [];
        
        if ($request->filled('calibratedBy')) {
            $updateCalibration['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateCalibration['verified_by'] = $request->verifiedBy;
        }
        
        if (!empty($updateCalibration)) {
            $calibration->update($updateCalibration);
            \Log::info('✅ Calibration updated with user data');
        }

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 UPDATE SUMMARY (Push Pull):', [
            'calibration_id' => $calibration->id,
            'certificate_id' => $finalCertificateId,
            'nama_alat' => $namaAlatBaru,
            'detail_records' => $detailCount,
            'satuan_tarik' => $headData['satuanTarik'],
            'satuan_tekan' => $headData['satuanTekan'],
            'satuan_titik_ukur' => $headData['satuanTitikUkur'],
        ]);

        \Log::info('🎉 updatePushPull COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePushPull:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}


private function storeTimbangan($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeTimbangan =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM & TAB
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        // Ambil tab_id untuk mendukung multiple tab dalam satu form
        $tabId = $request->input('tab_id', 1);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. AMBIL ALAT STANDAR DARI FORM 1
        // ==================================================================
        $alatStandar = [];
        
        // Coba dengan getRequestValue dulu
        $alatStandarValue = $this->getRequestValue($request, 'alat_standar', 1);
        if (is_array($alatStandarValue) && !empty($alatStandarValue)) {
            $alatStandar = $alatStandarValue;
        }
        
        // Jika tidak ditemukan, coba dari form_1_alat_standar[]
        if (empty($alatStandar)) {
            foreach ($request->all() as $key => $value) {
                if (strpos($key, 'form_1_alat_standar[]') !== false) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        // Jika masih tidak ditemukan, coba dari form_1_alat_standar (tanpa [])
        if (empty($alatStandar)) {
            $form1AlatStandar = $request->input('form_1_alat_standar');
            if (is_array($form1AlatStandar)) {
                $alatStandar = $form1AlatStandar;
            }
        }
        
        // Cek textarea alat standar
        $textValue = trim($this->getRequestValue($request, 'alat_standar_text', 1) ?? '');
        if (!empty($textValue)) {
            $standardValue = $textValue;
        } else {
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        }
        
        \Log::info('📋 Alat Standar:', ['standard_value' => $standardValue]);
        
        // ==================================================================
        // 3. LOOPING UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📝 Processing form {$formIndex}");
            
            // ==============================================================
            // 3.1. AMBIL DATA UNTUK FORM INI (DENGAN DUKUNGAN TAB)
            // ==============================================================
            $prefix = $isMultipleSubmit ? "form_{$formIndex}_" : "";
            
            // Gunakan getRequestValue dengan mempertimbangkan prefix dan tab
            $setengahKapasitas = $this->getRequestValueWithPrefix($request, $prefix . "setengah_kapasitas", $formIndex, $tabId);
            $kapasitasMax = $this->getRequestValueWithPrefix($request, $prefix . "kapasitas_max", $formIndex, $tabId);
            $catatanPenting = $this->getRequestValueWithPrefix($request, $prefix . "catatan_penting", $formIndex, $tabId);
            $calibrationMethod = $this->getRequestValueWithPrefix($request, $prefix . "calibration_method", $formIndex, $tabId);
            
            // ==============================================================
            // 3.2. SIMPAN HEAD TIMBANGAN
            // ==============================================================
            $head = HeadTimbangan::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard' => $standardValue,
                    'calibrationMethod' => $calibrationMethod ?? 'PAS-IK1102-15 (Monograph 4 : The Calibration of Weights and Balances, NMI Australia 2010)',
                    'note' => $catatanPenting,
                    'kapasitas_max' => $kapasitasMax,
                    'setengah_kapasitas' => $setengahKapasitas,
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id,
                ]
            );
            \Log::info("✅ HeadTimbangan saved for form {$formIndex}", ['head_id' => $head->id]);
            
            // ==============================================================
            // 3.3. HAPUS DETAIL LAMA (UNTUK UPDATE)
            // ==============================================================
            $existingDetails = DetailTimbangan::where('calibration_id', $calibration->id)
                                              ->where('form_index', $formIndex)
                                              ->count();
            if ($existingDetails > 0) {
                DetailTimbangan::where('calibration_id', $calibration->id)
                              ->where('form_index', $formIndex)
                              ->delete();
                \Log::info("🔄 Deleted {$existingDetails} old detail records for form {$formIndex}");
            }
            
            // ==============================================================
            // 3.4. SIMPAN DETAIL TIMBANGAN (10 baris)
            // ==============================================================
            for ($row = 1; $row <= 10; $row++) {
                // Ambil data untuk baris ini dengan getRequestValue
                if ($isMultipleSubmit) {
                    $skalaNominal = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_skala_nominal_{$formIndex}_{$row}", null, $tabId);
                    $Lz1 = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_z1_1_{$formIndex}_{$row}", null, $tabId);
                    $Lm1 = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_m1_1_{$formIndex}_{$row}", null, $tabId);
                    $Rm1 = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_m1_2_{$formIndex}_{$row}", null, $tabId);
                    $Rz1 = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_z1_2_{$formIndex}_{$row}", null, $tabId);
                    $STD = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_standar_{$formIndex}_{$row}", null, $tabId);
                } else {
                    $skalaNominal = $this->getRequestValueWithPrefix($request, "skala_nominal_{$formIndex}_{$row}", null, $tabId);
                    $Lz1 = $this->getRequestValueWithPrefix($request, "z1_1_{$formIndex}_{$row}", null, $tabId);
                    $Lm1 = $this->getRequestValueWithPrefix($request, "m1_1_{$formIndex}_{$row}", null, $tabId);
                    $Rm1 = $this->getRequestValueWithPrefix($request, "m1_2_{$formIndex}_{$row}", null, $tabId);
                    $Rz1 = $this->getRequestValueWithPrefix($request, "z1_2_{$formIndex}_{$row}", null, $tabId);
                    $STD = $this->getRequestValueWithPrefix($request, "standar_{$formIndex}_{$row}", null, $tabId);
                }
                
                // Log untuk debugging (hanya 2 baris pertama)
                if ($row <= 2) {
                    \Log::debug("Form {$formIndex} Row {$row} data (tab {$tabId}):", [
                        'skala_nominal' => $skalaNominal,
                        'Lz1' => $Lz1,
                        'Lm1' => $Lm1,
                        'Rm1' => $Rm1,
                        'Rz1' => $Rz1,
                        'STD' => $STD
                    ]);
                }
                
                $hasData = !empty($skalaNominal) || !empty($STD) || 
                          !empty($Lm1) || !empty($Lz1) || 
                          !empty($Rm1) || !empty($Rz1);
                
                if ($hasData) {
                    DetailTimbangan::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'head_timbangan_id' => $head->id,
                        'titikUkur' => $skalaNominal,
                        'Lz1' => $Lz1,
                        'Lm1' => $Lm1,
                        'Rm1' => $Rm1,
                        'Rz1' => $Rz1,
                        'STD' => $STD,
                    ]);
                    \Log::debug("✅ DetailTimbangan saved for form {$formIndex}, row {$row}");
                }
            }
            
            // ==============================================================
            // 3.5. HAPUS ADD DATA LAMA (UNTUK UPDATE)
            // ==============================================================
            $existingAddData = AddTimbangan::where('calibration_id', $calibration->id)
                                           ->where('form_index', $formIndex)
                                           ->count();
            if ($existingAddData > 0) {
                AddTimbangan::where('calibration_id', $calibration->id)
                            ->where('form_index', $formIndex)
                            ->delete();
                \Log::info("🔄 Deleted {$existingAddData} old add data records for form {$formIndex}");
            }
            
            // ==============================================================
            // 3.6. SIMPAN ADD TIMBANGAN (Repeatability & OffCenter)
            // ==============================================================
            $addData = [
                'calibration_id' => $calibration->id,
                'form_index' => $formIndex,
            ];
            
            for ($i = 1; $i <= 10; $i++) {
                if ($isMultipleSubmit) {
                    $addData["HalfMax_z1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_setengah_z1_{$formIndex}_{$i}", null, $tabId);
                    $addData["HalfMax_m1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_setengah_m1_{$formIndex}_{$i}", null, $tabId);
                    $addData["FullMax_z1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_kapasitas_z1_{$formIndex}_{$i}", null, $tabId);
                    $addData["FullMax_m1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_kapasitas_m1_{$formIndex}_{$i}", null, $tabId);
                } else {
                    $addData["HalfMax_z1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "setengah_z1_{$formIndex}_{$i}", null, $tabId);
                    $addData["HalfMax_m1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "setengah_m1_{$formIndex}_{$i}", null, $tabId);
                    $addData["FullMax_z1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "kapasitas_z1_{$formIndex}_{$i}", null, $tabId);
                    $addData["FullMax_m1_" . sprintf("%02d", $i)] = $this->getRequestValueWithPrefix($request, "kapasitas_m1_{$formIndex}_{$i}", null, $tabId);
                }
            }
            
            // Off Center Data
            if ($isMultipleSubmit) {
                $addData['bebanOffCenter'] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_beban_timbangan_{$formIndex}", null, $tabId);
                $addData['offCenterMiddle'] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_beban_tengah_{$formIndex}", null, $tabId);
                $addData['offCenterFront'] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_beban_depan_{$formIndex}", null, $tabId);
                $addData['offCenterBack'] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_beban_belakang_{$formIndex}", null, $tabId);
                $addData['offCenterRight'] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_beban_kanan_{$formIndex}", null, $tabId);
                $addData['offCenterLeft'] = $this->getRequestValueWithPrefix($request, "form_{$formIndex}_beban_kiri_{$formIndex}", null, $tabId);
            } else {
                $addData['bebanOffCenter'] = $this->getRequestValueWithPrefix($request, "beban_timbangan_{$formIndex}", null, $tabId);
                $addData['offCenterMiddle'] = $this->getRequestValueWithPrefix($request, "beban_tengah_{$formIndex}", null, $tabId);
                $addData['offCenterFront'] = $this->getRequestValueWithPrefix($request, "beban_depan_{$formIndex}", null, $tabId);
                $addData['offCenterBack'] = $this->getRequestValueWithPrefix($request, "beban_belakang_{$formIndex}", null, $tabId);
                $addData['offCenterRight'] = $this->getRequestValueWithPrefix($request, "beban_kanan_{$formIndex}", null, $tabId);
                $addData['offCenterLeft'] = $this->getRequestValueWithPrefix($request, "beban_kiri_{$formIndex}", null, $tabId);
            }
            
            AddTimbangan::create($addData);
            \Log::info("✅ AddTimbangan saved for form {$formIndex}");
        }
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD)
        // ==================================================================
        $updateData = [];
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Calibrated by
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy, 'tab_id' => $tabId]);
        }
        
        // Verified by
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy, 'tab_id' => $tabId]);
        }
        
        // Alat standar
        if (!empty($standardValue)) {
            $updateData['alat_standar'] = $standardValue;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }
        
        // Update jumlah form
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        \Log::info('✅ storeTimbangan completed successfully');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeTimbangan FAILED:', [
            'message' => $e->getMessage(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

/**
 * Helper function untuk mengambil nilai request dengan mempertimbangkan prefix dan tab
 */
private function getRequestValueWithPrefix($request, $baseKey, $formIndex = null, $tabId = null)
{
    // Coba dengan format yang paling spesifik dulu
    $possibleKeys = [];
    
    if ($formIndex !== null && $tabId !== null) {
        $possibleKeys[] = $baseKey . "_{$formIndex}_tab{$tabId}";
        $possibleKeys[] = $baseKey . "_tab{$tabId}_{$formIndex}";
        $possibleKeys[] = $baseKey . "_{$formIndex}";
    }
    
    if ($tabId !== null) {
        $possibleKeys[] = $baseKey . "_tab{$tabId}";
    }
    
    $possibleKeys[] = $baseKey;
    
    foreach ($possibleKeys as $key) {
        $value = $request->input($key);
        if ($value !== null && $value !== '') {
            return $value;
        }
    }
    
    return null;
}

private function updateTimbangan($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateTimbangan =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. AMBIL JUMLAH FORM
        // ==================================================================
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);
        
        // ==================================================================
        // 1. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        $namaAlatDariRequest = $request->namaAlat ?? $calibration->namaAlat;
        $headTimbangan = $calibration->headTimbangan;
        $currentCertificateId = $headTimbangan->certificate_id ?? null;
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->namaAlat;
        
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        } elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        // ==================================================================
        // 2. PROSES ALAT STANDAR (HANYA DARI FORM 1)
        // ==================================================================
        $alatStandar = $request->input('alat_standar', []);
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', ['alat_standar' => $alatStandar]);
        
        // ==================================================================
        // 3. LOOP UNTUK SETIAP FORM (1 - jumlahForm)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $isFirstForm = ($formIndex == 1);
            \Log::info("📝 Processing Form {$formIndex}");
            
            // ==============================================================
            // 3a. UPDATE HEAD TIMBANGAN PER FORM
            // ==============================================================
            $head = $calibration->headTimbangan()->where('form_index', $formIndex)->first();
            
            $headData = [
                'form_index' => $formIndex,
                'satuan_unit' => $request->input("satuan_unit_{$formIndex}", 'mm'),
                'note' => $request->input("catatan_penting_{$formIndex}"), // CATATAN PENTING PER FORM
                'standard' => $alatStandarString, // SEMUA FORM PAKAI STANDAR YANG SAMA
                'calibrated_by' => $request->input('calibratedBy', $request->calibrated_by ?? null),
                'verified_by' => $request->input('verifiedBy', $request->verified_by ?? null),
                'setengah_kapasitas' => $request->input("setengah_kap_max_{$formIndex}"),
                'kapasitas_max' => $request->input("kapasitas_max_{$formIndex}"),
            ];
            
            // Hanya form 1 yang dapat mengupdate certificate_id
            if ($isFirstForm && $certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
            } elseif ($isFirstForm && $newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ HeadTimbangan Form {$formIndex} updated", [
                    'note' => $headData['note'] ?? null,
                    'setengah_kapasitas' => $headData['setengah_kapasitas'] ?? null,
                    'kapasitas_max' => $headData['kapasitas_max'] ?? null,
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $head = HeadTimbangan::create($headData);
                \Log::info("➕ HeadTimbangan Form {$formIndex} created");
            }
            
            // ==============================================================
            // 3b. UPDATE DETAIL TIMBANGAN PER FORM (DELETE & RECREATE - 10 BARIS)
            // ==============================================================
            DetailTimbangan::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->delete();
            
            $detailCount = 0;
            
            // Ambil data array dari request
            $titikUkurArray = $request->input("titikUkur_{$formIndex}", []);
            $Lz1Array = $request->input("Lz1_{$formIndex}", []);
            $Lm1Array = $request->input("Lm1_{$formIndex}", []);
            $Rm1Array = $request->input("Rm1_{$formIndex}", []);
            $Rz1Array = $request->input("Rz1_{$formIndex}", []);
            $STDArray = $request->input("STD_{$formIndex}", []);
            
            for ($i = 0; $i < 10; $i++) {
                $titikUkur = $titikUkurArray[$i] ?? null;
                $Lz1 = $Lz1Array[$i] ?? null;
                $Lm1 = $Lm1Array[$i] ?? null;
                $Rm1 = $Rm1Array[$i] ?? null;
                $Rz1 = $Rz1Array[$i] ?? null;
                $STD = $STDArray[$i] ?? null;
                
                $hasData = !empty($titikUkur) || !empty($Lz1) || !empty($Lm1) || 
                          !empty($Rm1) || !empty($Rz1) || !empty($STD);
                
                if ($hasData) {
                    DetailTimbangan::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'Lz1' => $Lz1,
                        'Lm1' => $Lm1,
                        'Rm1' => $Rm1,
                        'Rz1' => $Rz1,
                        'STD' => $STD,
                    ]);
                    $detailCount++;
                }
            }
            
            \Log::info("✅ DetailTimbangan Form {$formIndex} updated", ['records' => $detailCount]);
            
            // ==============================================================
            // 3c. UPDATE ADD TIMBANGAN PER FORM (REPEATABILITY & OFF CENTER)
            // ==============================================================
            $addTimbangan = $calibration->addTimbangan()->where('form_index', $formIndex)->first();
            
            $addUpdateData = [
                'form_index' => $formIndex,
                
                // Setengah Kap. Max - Penunjukan z1
                'HalfMax_z1_01' => $request->input("setengah_z1_{$formIndex}_1"),
                'HalfMax_z1_02' => $request->input("setengah_z1_{$formIndex}_2"),
                'HalfMax_z1_03' => $request->input("setengah_z1_{$formIndex}_3"),
                'HalfMax_z1_04' => $request->input("setengah_z1_{$formIndex}_4"),
                'HalfMax_z1_05' => $request->input("setengah_z1_{$formIndex}_5"),
                'HalfMax_z1_06' => $request->input("setengah_z1_{$formIndex}_6"),
                'HalfMax_z1_07' => $request->input("setengah_z1_{$formIndex}_7"),
                'HalfMax_z1_08' => $request->input("setengah_z1_{$formIndex}_8"),
                'HalfMax_z1_09' => $request->input("setengah_z1_{$formIndex}_9"),
                'HalfMax_z1_10' => $request->input("setengah_z1_{$formIndex}_10"),
                
                // Setengah Kap. Max - Penunjukan m1
                'HalfMax_m1_01' => $request->input("setengah_m1_{$formIndex}_1"),
                'HalfMax_m1_02' => $request->input("setengah_m1_{$formIndex}_2"),
                'HalfMax_m1_03' => $request->input("setengah_m1_{$formIndex}_3"),
                'HalfMax_m1_04' => $request->input("setengah_m1_{$formIndex}_4"),
                'HalfMax_m1_05' => $request->input("setengah_m1_{$formIndex}_5"),
                'HalfMax_m1_06' => $request->input("setengah_m1_{$formIndex}_6"),
                'HalfMax_m1_07' => $request->input("setengah_m1_{$formIndex}_7"),
                'HalfMax_m1_08' => $request->input("setengah_m1_{$formIndex}_8"),
                'HalfMax_m1_09' => $request->input("setengah_m1_{$formIndex}_9"),
                'HalfMax_m1_10' => $request->input("setengah_m1_{$formIndex}_10"),
                
                // Kapasitas Max - Penunjukan z1
                'FullMax_z1_01' => $request->input("kapasitas_z1_{$formIndex}_1"),
                'FullMax_z1_02' => $request->input("kapasitas_z1_{$formIndex}_2"),
                'FullMax_z1_03' => $request->input("kapasitas_z1_{$formIndex}_3"),
                'FullMax_z1_04' => $request->input("kapasitas_z1_{$formIndex}_4"),
                'FullMax_z1_05' => $request->input("kapasitas_z1_{$formIndex}_5"),
                'FullMax_z1_06' => $request->input("kapasitas_z1_{$formIndex}_6"),
                'FullMax_z1_07' => $request->input("kapasitas_z1_{$formIndex}_7"),
                'FullMax_z1_08' => $request->input("kapasitas_z1_{$formIndex}_8"),
                'FullMax_z1_09' => $request->input("kapasitas_z1_{$formIndex}_9"),
                'FullMax_z1_10' => $request->input("kapasitas_z1_{$formIndex}_10"),
                
                // Kapasitas Max - Penunjukan m1
                'FullMax_m1_01' => $request->input("kapasitas_m1_{$formIndex}_1"),
                'FullMax_m1_02' => $request->input("kapasitas_m1_{$formIndex}_2"),
                'FullMax_m1_03' => $request->input("kapasitas_m1_{$formIndex}_3"),
                'FullMax_m1_04' => $request->input("kapasitas_m1_{$formIndex}_4"),
                'FullMax_m1_05' => $request->input("kapasitas_m1_{$formIndex}_5"),
                'FullMax_m1_06' => $request->input("kapasitas_m1_{$formIndex}_6"),
                'FullMax_m1_07' => $request->input("kapasitas_m1_{$formIndex}_7"),
                'FullMax_m1_08' => $request->input("kapasitas_m1_{$formIndex}_8"),
                'FullMax_m1_09' => $request->input("kapasitas_m1_{$formIndex}_9"),
                'FullMax_m1_10' => $request->input("kapasitas_m1_{$formIndex}_10"),
                
                // Off Center Data
                'bebanOffCenter' => $request->input("beban_timbangan_{$formIndex}"),
                'offCenterFront' => $request->input("beban_depan_{$formIndex}"),
                'offCenterMiddle' => $request->input("beban_tengah_{$formIndex}"),
                'offCenterBack' => $request->input("beban_belakang_{$formIndex}"),
                'offCenterRight' => $request->input("beban_kanan_{$formIndex}"),
                'offCenterLeft' => $request->input("beban_kiri_{$formIndex}"),
            ];
            
            // Filter null values
            $addUpdateData = array_filter($addUpdateData, function($value) {
                return $value !== null;
            });
            
            if ($addTimbangan) {
                $addTimbangan->update($addUpdateData);
                \Log::info("✅ AddTimbangan Form {$formIndex} updated");
            } else if (count($addUpdateData) > 1) {
                $addUpdateData['calibration_id'] = $calibration->id;
                AddTimbangan::create($addUpdateData);
                \Log::info("➕ AddTimbangan Form {$formIndex} created");
            }
        }
        
        // ==================================================================
        // 4. UPDATE CALIBRATION - DATA UMUM (HANYA DARI FORM 1)
        // ==================================================================
        $updateCalibrationData = [];
        
        $fieldsToUpdate = [
            'namaAlat', 'brandAlat', 'kodeAlat', 'typeAlat', 'NoSeri',
            'kapasitas', 'resolusi', 'pemilikAlat', 'tanggalMasuk', 
            'tanggalKalibrasi', 'jenisPembacaan', 'tempatKalibrasi', 
            'lokasiPT', 'kondisiAlat', 'keterangan',
            'RT_condition1', 'RT_condition2', 'RT_condition3',
            'RH_condition1', 'RH_condition2', 'RH_condition3'
        ];
        
        foreach ($fieldsToUpdate as $field) {
            if ($request->filled($field)) {
                $updateCalibrationData[$field] = $request->$field;
            }
        }
        
        if ($request->filled('calibratedBy')) {
            $updateCalibrationData['calibrated_by'] = $request->calibratedBy;
        }
        if ($request->filled('verifiedBy')) {
            $updateCalibrationData['verified_by'] = $request->verifiedBy;
        }
        
        $updateCalibrationData['certificate_id'] = null;
        
        if (!empty($updateCalibrationData)) {
            $calibration->update($updateCalibrationData);
            \Log::info('✅ Calibration updated:', array_keys($updateCalibrationData));
        }
        
        // ==================================================================
        // 5. FINAL VERIFICATION
        // ==================================================================
        $calibration->refresh();
        
        $allHeads = HeadTimbangan::where('calibration_id', $calibration->id)->get();
        foreach ($allHeads as $head) {
            \Log::info("📊 HeadTimbangan Form {$head->form_index}:", [
                'note' => $head->note,
                'certificate_id' => $head->certificate_id,
            ]);
        }
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_count' => $allHeads->count(),
            'detail_records' => DetailTimbangan::where('calibration_id', $calibration->id)->count(),
            'add_records' => AddTimbangan::where('calibration_id', $calibration->id)->count(),
        ]);

        \Log::info('🎉 updateTimbangan COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTimbangan:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        throw $e;
    }
}
private function storeTimbanganMoisture($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storeTimbanganMoisture - COMBINED TEMPERATURE & WEIGHT', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (DENGAN DUKUNGAN _tab)
        // ==================================================================
        // Cek textarea terlebih dahulu
        $textValue = trim($this->getRequestValue($request, 'alat_standar_text', $tabId) ?? '');
        
        // Cek array checkbox
        $arrayValue = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (!is_array($arrayValue)) {
            $arrayValue = $request->input('alat_standar', []);
        }
        
        if (!empty($textValue)) {
            $alatStandarString = $textValue; // Prioritas: textarea
        } elseif (is_array($arrayValue) && count($arrayValue) > 0) {
            $alatStandarString = implode(', ', $arrayValue); // Fallback ke checkbox
        } else {
            $alatStandarString = '';
        }
        
        \Log::info('🔧 Alat standar selected for Timbangan Moisture:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE)
        // ==================================================================
        $head = HeadTimbanganMoisture::where('calibration_id', $calibration->id)->first();
        
        $kapasitasMax = $this->getRequestValue($request, 'kapasitas_max', $tabId);
        $setengahKapasitas = $this->getRequestValue($request, 'setengah_kapasitas', $tabId);
        $calibrationMethod = $this->getRequestValue($request, 'calibration_method', $tabId);
        
        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod ?? 'PAS-IK1102-15 (Monograph 4 : The Calibration of Weights and Balances, NMI Australia 2010)',
                'kapasitas_max' => $kapasitasMax,
                'setengah_kapasitas' => $setengahKapasitas,
            ]);
            \Log::info('✅ HeadTimbanganMoisture updated:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        } else {
            // Buat head baru
            $head = HeadTimbanganMoisture::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod ?? 'PAS-IK1102-15 (Monograph 4 : The Calibration of Weights and Balances, NMI Australia 2010)',
                'kapasitas_max' => $kapasitasMax,
                'setengah_kapasitas' => $setengahKapasitas,
            ]);
            \Log::info('✅ HeadTimbanganMoisture created:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        }

        // ==================================================================
        // 3. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE)
        // ==================================================================
        $existingDetails = DetailTimbanganMoisture::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailTimbanganMoisture::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records for tab {$tabId}");
        }
        
        $existingAddData = AddTimbanganMoisture::where('calibration_id', $calibration->id)->count();
        if ($existingAddData > 0) {
            AddTimbanganMoisture::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingAddData} old add data records for tab {$tabId}");
        }
        
        // ==================================================================
        // 4. SIMPAN 10 RECORD DENGAN DATA GABUNGAN (SUHU DI RECORD 1-3)
        // ==================================================================
        \Log::info('📊 Saving 10 combined records (temperature in record 1-3, weight data)...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 10; $i++) {
            // Data timbangan untuk semua record (dengan dukungan _tab)
            $titikUkur = $this->getRequestValue($request, "skala_nominal_{$i}", $tabId);
            $Lz1 = $this->getRequestValue($request, "z1_1_{$i}", $tabId);
            $Lm1 = $this->getRequestValue($request, "m1_1_{$i}", $tabId);
            $Rm1 = $this->getRequestValue($request, "m1_2_{$i}", $tabId);
            $Rz1 = $this->getRequestValue($request, "z1_2_{$i}", $tabId);
            $STD = $this->getRequestValue($request, "standar_{$i}", $tabId);
            
            // Data suhu HANYA untuk record 1-3
            $tsetting = null;
            $readAlat01 = null;
            $readAlat02 = null;
            $readAlat03 = null;
            $readSTD01 = null;
            $readSTD02 = null;
            $readSTD03 = null;
            
            if ($i <= 3) {
                // Record 1-3: tambahkan data suhu (dengan dukungan _tab)
                $settingNum = $i; // setting suhu ke-1, ke-2, ke-3 sesuai record
                $tsetting = $this->getRequestValue($request, "setting_suhu_{$settingNum}", $tabId);
                
                $readAlat01 = $this->getRequestValue($request, "pembacaan_alat_{$settingNum}_1", $tabId);
                $readAlat02 = $this->getRequestValue($request, "pembacaan_alat_{$settingNum}_2", $tabId);
                $readAlat03 = $this->getRequestValue($request, "pembacaan_alat_{$settingNum}_3", $tabId);
                
                $readSTD01 = $this->getRequestValue($request, "pembacaan_standar_{$settingNum}_1", $tabId);
                $readSTD02 = $this->getRequestValue($request, "pembacaan_standar_{$settingNum}_2", $tabId);
                $readSTD03 = $this->getRequestValue($request, "pembacaan_standar_{$settingNum}_3", $tabId);
                
                \Log::debug("🌡️ Record {$i}: Temperature data added (tab {$tabId})", [
                    'Tsetting' => $tsetting,
                    'setting_num' => $settingNum
                ]);
            }
            
            // Cek apakah ada data untuk record ini
            $hasTimbanganData = !empty($titikUkur) || !empty($STD) || 
                              !empty($Lm1) || !empty($Lz1) || 
                              !empty($Rm1) || !empty($Rz1);
            
            $hasSuhuData = ($i <= 3) && ($tsetting !== null && $tsetting !== '' || 
                         $readAlat01 !== null && $readAlat01 !== '' ||
                         $readAlat02 !== null && $readAlat02 !== '' ||
                         $readAlat03 !== null && $readAlat03 !== '' ||
                         $readSTD01 !== null && $readSTD01 !== '' ||
                         $readSTD02 !== null && $readSTD02 !== '' ||
                         $readSTD03 !== null && $readSTD03 !== '');
            
            $hasData = $hasTimbanganData || $hasSuhuData;
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_timbangan_moisture_id' => $head->id,
                    // Data timbangan
                    'titikUkur' => $titikUkur,
                    'STD' => $STD,
                    'Lm1' => $Lm1,
                    'Lz1' => $Lz1,
                    'Rm1' => $Rm1,
                    'Rz1' => $Rz1,
                    // Data suhu (hanya untuk record 1-3, null untuk lainnya)
                    'Tsetting' => $tsetting,
                    'ReadAlat01' => $readAlat01,
                    'ReadAlat02' => $readAlat02,
                    'ReadAlat03' => $readAlat03,
                    'ReadSTD01' => $readSTD01,
                    'ReadSTD02' => $readSTD02,
                    'ReadSTD03' => $readSTD03,
                ];
                
                $record = DetailTimbanganMoisture::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ Record {$i} saved (tab {$tabId})", [
                    'record_id' => $record->id,
                    'has_temperature' => $i <= 3 ? 'YES' : 'NO',
                    'titikUkur' => $detailData['titikUkur'],
                    'Tsetting' => $detailData['Tsetting']
                ]);
            } else {
                \Log::debug("⏭️ Skipping record {$i} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} combined records (temperature in record 1-3) for tab {$tabId}");
        
        // ==================================================================
        // 5. SIMPAN ADD TIMBANGAN MOISTURE (DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving AddTimbanganMoisture data...');
        
        $addData = [
            'calibration_id' => $calibration->id,
            
            // Pemeriksaan Nilai Repeatability - Setengah Kap. Max
            'HalfMax_z1_01' => $this->getRequestValue($request, 'setengah_z1_1', $tabId),
            'HalfMax_z1_02' => $this->getRequestValue($request, 'setengah_z1_2', $tabId),
            'HalfMax_z1_03' => $this->getRequestValue($request, 'setengah_z1_3', $tabId),
            'HalfMax_z1_04' => $this->getRequestValue($request, 'setengah_z1_4', $tabId),
            'HalfMax_z1_05' => $this->getRequestValue($request, 'setengah_z1_5', $tabId),
            'HalfMax_z1_06' => $this->getRequestValue($request, 'setengah_z1_6', $tabId),
            'HalfMax_z1_07' => $this->getRequestValue($request, 'setengah_z1_7', $tabId),
            'HalfMax_z1_08' => $this->getRequestValue($request, 'setengah_z1_8', $tabId),
            'HalfMax_z1_09' => $this->getRequestValue($request, 'setengah_z1_9', $tabId),
            'HalfMax_z1_10' => $this->getRequestValue($request, 'setengah_z1_10', $tabId),
            
            'HalfMax_m1_01' => $this->getRequestValue($request, 'setengah_m1_1', $tabId),
            'HalfMax_m1_02' => $this->getRequestValue($request, 'setengah_m1_2', $tabId),
            'HalfMax_m1_03' => $this->getRequestValue($request, 'setengah_m1_3', $tabId),
            'HalfMax_m1_04' => $this->getRequestValue($request, 'setengah_m1_4', $tabId),
            'HalfMax_m1_05' => $this->getRequestValue($request, 'setengah_m1_5', $tabId),
            'HalfMax_m1_06' => $this->getRequestValue($request, 'setengah_m1_6', $tabId),
            'HalfMax_m1_07' => $this->getRequestValue($request, 'setengah_m1_7', $tabId),
            'HalfMax_m1_08' => $this->getRequestValue($request, 'setengah_m1_8', $tabId),
            'HalfMax_m1_09' => $this->getRequestValue($request, 'setengah_m1_9', $tabId),
            'HalfMax_m1_10' => $this->getRequestValue($request, 'setengah_m1_10', $tabId),
            
            // Pemeriksaan Nilai Repeatability - Kapasitas Max
            'FullMax_z1_01' => $this->getRequestValue($request, 'kapasitas_z1_1', $tabId),
            'FullMax_z1_02' => $this->getRequestValue($request, 'kapasitas_z1_2', $tabId),
            'FullMax_z1_03' => $this->getRequestValue($request, 'kapasitas_z1_3', $tabId),
            'FullMax_z1_04' => $this->getRequestValue($request, 'kapasitas_z1_4', $tabId),
            'FullMax_z1_05' => $this->getRequestValue($request, 'kapasitas_z1_5', $tabId),
            'FullMax_z1_06' => $this->getRequestValue($request, 'kapasitas_z1_6', $tabId),
            'FullMax_z1_07' => $this->getRequestValue($request, 'kapasitas_z1_7', $tabId),
            'FullMax_z1_08' => $this->getRequestValue($request, 'kapasitas_z1_8', $tabId),
            'FullMax_z1_09' => $this->getRequestValue($request, 'kapasitas_z1_9', $tabId),
            'FullMax_z1_10' => $this->getRequestValue($request, 'kapasitas_z1_10', $tabId),
            
            'FullMax_m1_01' => $this->getRequestValue($request, 'kapasitas_m1_1', $tabId),
            'FullMax_m1_02' => $this->getRequestValue($request, 'kapasitas_m1_2', $tabId),
            'FullMax_m1_03' => $this->getRequestValue($request, 'kapasitas_m1_3', $tabId),
            'FullMax_m1_04' => $this->getRequestValue($request, 'kapasitas_m1_4', $tabId),
            'FullMax_m1_05' => $this->getRequestValue($request, 'kapasitas_m1_5', $tabId),
            'FullMax_m1_06' => $this->getRequestValue($request, 'kapasitas_m1_6', $tabId),
            'FullMax_m1_07' => $this->getRequestValue($request, 'kapasitas_m1_7', $tabId),
            'FullMax_m1_08' => $this->getRequestValue($request, 'kapasitas_m1_8', $tabId),
            'FullMax_m1_09' => $this->getRequestValue($request, 'kapasitas_m1_9', $tabId),
            'FullMax_m1_10' => $this->getRequestValue($request, 'kapasitas_m1_10', $tabId),
            
            // Off-Center Loading Test
            'bebanOffCenter' => $this->getRequestValue($request, 'beban_timbangan', $tabId),
            'offCenterFront' => $this->getRequestValue($request, 'beban_depan', $tabId),
            'offCenterMiddle' => $this->getRequestValue($request, 'beban_tengah', $tabId),
            'offCenterBack' => $this->getRequestValue($request, 'beban_belakang', $tabId),
            'offCenterRight' => $this->getRequestValue($request, 'beban_kanan', $tabId),
            'offCenterLeft' => $this->getRequestValue($request, 'beban_kiri', $tabId),
        ];
        
        // Cek apakah ada data untuk disimpan
        $hasAddData = false;
        foreach ($addData as $key => $value) {
            if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                $hasAddData = true;
                break;
            }
        }
        
        if ($hasAddData) {
            $addRecord = AddTimbanganMoisture::create($addData);
            \Log::info('✅ AddTimbanganMoisture saved:', ['add_id' => $addRecord->id, 'tab_id' => $tabId]);
        } else {
            \Log::info('⚠️ No AddTimbanganMoisture data to save for tab ' . $tabId);
        }

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $updateData = [];
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Calibrated by (nama_dikalibrasi)
        $calibratedBy = $this->getRequestValue($request, 'nama_dikalibrasi', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy, 'tab_id' => $tabId]);
        }
        
        // Verified by (nama_diperiksa)
        $verifiedBy = $this->getRequestValue($request, 'nama_diperiksa', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy, 'tab_id' => $tabId]);
        }
        
        // Alat standar
        if (!empty($alatStandarString)) {
            $updateData['alat_standar'] = $alatStandarString;
        }
        
        // Calibration method
        if ($calibrationMethod) {
            $updateData['calibration_method'] = $calibrationMethod;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data for tab ' . $tabId);
        }

        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailTimbanganMoisture::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddTimbanganMoisture::where('calibration_id', $calibration->id)->count();
        
        // Cek record yang memiliki data suhu
        $temperatureRecords = DetailTimbanganMoisture::where('calibration_id', $calibration->id)
            ->where(function($query) {
                $query->whereNotNull('Tsetting')
                      ->orWhereNotNull('ReadAlat01')
                      ->orWhereNotNull('ReadAlat02')
                      ->orWhereNotNull('ReadAlat03')
                      ->orWhereNotNull('ReadSTD01')
                      ->orWhereNotNull('ReadSTD02')
                      ->orWhereNotNull('ReadSTD03');
            })
            ->count();
        
        \Log::info('📋 STORE SUMMARY (Timbangan Moisture - COMBINED DATA):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'tab_id' => $tabId,
            'total_records' => $savedDetailCount,
            'records_with_temperature' => $temperatureRecords . ' (should be 1-3)',
            'record_structure' => '✅ ALL 10 records have weight data, records 1-3 ALSO have temperature data',
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storeTimbanganMoisture COMPLETED (COMBINED TEMPERATURE & WEIGHT) for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTimbanganMoisture:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailTimbanganMoisture::where('calibration_id', $calibration->id)->delete();
                AddTimbanganMoisture::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Timbangan Moisture: " . $e->getMessage());
    }
}

private function updateTimbanganMoisture($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateTimbanganMoisture - COMBINED TEMPERATURE & WEIGHT');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdUpdated = false;
        $certificateIdBaru = $newCertificateId;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $calibration->certificate_id,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $calibration->certificate_id,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Timbangan Moisture:', ['alat_standar' => $alatStandar]);

        // ==================================================================
        // 2. UPDATE ATAU BUAT HEAD TIMBANGAN MOISTURE
        // ==================================================================
        if ($head = $calibration->headTimbanganMoisture) {
            $headUpdateData = [
                'standard' => $alatStandarString,
                'calibrationMethod' => 'PAS-IK1102-15 (Monograph 4 : The Calibration of Weights and Balances, NMI Australia 2010)',
                'kapasitas_max' => $request->kapasitas_max ?? $head->kapasitas_max,
                'setengah_kapasitas' => $request->setengah_kapasitas ?? $head->setengah_kapasitas,
            ];
            
            // Update certificate_id di head jika diperlukan
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headUpdateData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id di head: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headUpdateData['certificate_id'] = $newCertificateId;
            }
            
            $head->update($headUpdateData);
            \Log::info('✅ HeadTimbanganMoisture updated:', ['head_id' => $head->id]);
        } else {
            $headCreateData = [
                'calibration_id' => $calibration->id,
                'standard' => $alatStandarString,
                'calibrationMethod' => 'PAS-IK1102-15 (Monograph 4 : The Calibration of Weights and Balances, NMI Australia 2010)',
                'kapasitas_max' => $request->kapasitas_max ?? null,
                'setengah_kapasitas' => $request->setengah_kapasitas ?? null,
            ];
            
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headCreateData['certificate_id'] = $certificateIdBaru;
            } elseif ($newCertificateId) {
                $headCreateData['certificate_id'] = $newCertificateId;
            }
            
            $head = HeadTimbanganMoisture::create($headCreateData);
            \Log::info('➕ HeadTimbanganMoisture created baru:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 3. UPDATE DETAIL TIMBANGAN MOISTURE (HAPUS & BUAT BARU - 10 RECORD)
        // ==================================================================
        DetailTimbanganMoisture::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        \Log::info('📊 Updating 10 combined records (temperature in record 1-3, weight data)...');
        
        // Ambil data suhu dari format ARRAY (sesuai dengan form)
        $Tsetting = $request->input('Tsetting', []);
        $ReadAlat01 = $request->input('ReadAlat01', []);
        $ReadAlat02 = $request->input('ReadAlat02', []);
        $ReadAlat03 = $request->input('ReadAlat03', []);
        $ReadSTD01 = $request->input('ReadSTD01', []);
        $ReadSTD02 = $request->input('ReadSTD02', []);
        $ReadSTD03 = $request->input('ReadSTD03', []);
        
        for ($i = 1; $i <= 10; $i++) {
            // Data timbangan untuk semua record (format individual)
            $titikUkur = $request->input("titikUkur_$i");
            $Lz1 = $request->input("Lz1_$i");
            $Lm1 = $request->input("Lm1_$i");
            $Rm1 = $request->input("Rm1_$i");
            $Rz1 = $request->input("Rz1_$i");
            $STD = $request->input("STD_$i");
            
            // Data suhu HANYA untuk record 1-3 - ambil dari ARRAY berdasarkan index
            $tsetting = null;
            $readAlat01 = null;
            $readAlat02 = null;
            $readAlat03 = null;
            $readSTD01 = null;
            $readSTD02 = null;
            $readSTD03 = null;
            
            if ($i <= 3) {
                $index = $i - 1; // index array dimulai dari 0
                
                $tsetting = isset($Tsetting[$index]) ? $Tsetting[$index] : null;
                $readAlat01 = isset($ReadAlat01[$index]) ? $ReadAlat01[$index] : null;
                $readAlat02 = isset($ReadAlat02[$index]) ? $ReadAlat02[$index] : null;
                $readAlat03 = isset($ReadAlat03[$index]) ? $ReadAlat03[$index] : null;
                $readSTD01 = isset($ReadSTD01[$index]) ? $ReadSTD01[$index] : null;
                $readSTD02 = isset($ReadSTD02[$index]) ? $ReadSTD02[$index] : null;
                $readSTD03 = isset($ReadSTD03[$index]) ? $ReadSTD03[$index] : null;
            }
            
            $detailData = [
                'calibration_id' => $calibration->id,
                
                // Data timbangan (langsung simpan apa adanya)
                'titikUkur' => $titikUkur,
                'STD' => $STD,
                'Lm1' => $Lm1,
                'Lz1' => $Lz1,
                'Rm1' => $Rm1,
                'Rz1' => $Rz1,
                
                // Data suhu (hanya untuk record 1-3, null untuk lainnya)
                'Tsetting' => $tsetting,
                'ReadAlat01' => $readAlat01,
                'ReadAlat02' => $readAlat02,
                'ReadAlat03' => $readAlat03,
                'ReadSTD01' => $readSTD01,
                'ReadSTD02' => $readSTD02,
                'ReadSTD03' => $readSTD03,
            ];
            
            $record = DetailTimbanganMoisture::create($detailData);
            $detailCount++;
        }
        
        \Log::info("✅ Updated {$detailCount} combined records (temperature in record 1-3)");

        // ==================================================================
        // 4. UPDATE ADD TIMBANGAN MOISTURE (LANGSUNG SIMPAN APA ADANYA)
        // ==================================================================
        \Log::info('📊 Updating AddTimbanganMoisture data...');
        
        if ($addTimbangan = $calibration->addTimbanganMoisture) {
            $updateData = [
                // Pemeriksaan Nilai Repeatability - Setengah Kap. Max
                'HalfMax_z1_01' => $request->input('setengah_z1_1', $addTimbangan->HalfMax_z1_01),
                'HalfMax_z1_02' => $request->input('setengah_z1_2', $addTimbangan->HalfMax_z1_02),
                'HalfMax_z1_03' => $request->input('setengah_z1_3', $addTimbangan->HalfMax_z1_03),
                'HalfMax_z1_04' => $request->input('setengah_z1_4', $addTimbangan->HalfMax_z1_04),
                'HalfMax_z1_05' => $request->input('setengah_z1_5', $addTimbangan->HalfMax_z1_05),
                'HalfMax_z1_06' => $request->input('setengah_z1_6', $addTimbangan->HalfMax_z1_06),
                'HalfMax_z1_07' => $request->input('setengah_z1_7', $addTimbangan->HalfMax_z1_07),
                'HalfMax_z1_08' => $request->input('setengah_z1_8', $addTimbangan->HalfMax_z1_08),
                'HalfMax_z1_09' => $request->input('setengah_z1_9', $addTimbangan->HalfMax_z1_09),
                'HalfMax_z1_10' => $request->input('setengah_z1_10', $addTimbangan->HalfMax_z1_10),
                
                'HalfMax_m1_01' => $request->input('setengah_m1_1', $addTimbangan->HalfMax_m1_01),
                'HalfMax_m1_02' => $request->input('setengah_m1_2', $addTimbangan->HalfMax_m1_02),
                'HalfMax_m1_03' => $request->input('setengah_m1_3', $addTimbangan->HalfMax_m1_03),
                'HalfMax_m1_04' => $request->input('setengah_m1_4', $addTimbangan->HalfMax_m1_04),
                'HalfMax_m1_05' => $request->input('setengah_m1_5', $addTimbangan->HalfMax_m1_05),
                'HalfMax_m1_06' => $request->input('setengah_m1_6', $addTimbangan->HalfMax_m1_06),
                'HalfMax_m1_07' => $request->input('setengah_m1_7', $addTimbangan->HalfMax_m1_07),
                'HalfMax_m1_08' => $request->input('setengah_m1_8', $addTimbangan->HalfMax_m1_08),
                'HalfMax_m1_09' => $request->input('setengah_m1_9', $addTimbangan->HalfMax_m1_09),
                'HalfMax_m1_10' => $request->input('setengah_m1_10', $addTimbangan->HalfMax_m1_10),
                
                // Pemeriksaan Nilai Repeatability - Kapasitas Max
                'FullMax_z1_01' => $request->input('kapasitas_z1_1', $addTimbangan->FullMax_z1_01),
                'FullMax_z1_02' => $request->input('kapasitas_z1_2', $addTimbangan->FullMax_z1_02),
                'FullMax_z1_03' => $request->input('kapasitas_z1_3', $addTimbangan->FullMax_z1_03),
                'FullMax_z1_04' => $request->input('kapasitas_z1_4', $addTimbangan->FullMax_z1_04),
                'FullMax_z1_05' => $request->input('kapasitas_z1_5', $addTimbangan->FullMax_z1_05),
                'FullMax_z1_06' => $request->input('kapasitas_z1_6', $addTimbangan->FullMax_z1_06),
                'FullMax_z1_07' => $request->input('kapasitas_z1_7', $addTimbangan->FullMax_z1_07),
                'FullMax_z1_08' => $request->input('kapasitas_z1_8', $addTimbangan->FullMax_z1_08),
                'FullMax_z1_09' => $request->input('kapasitas_z1_9', $addTimbangan->FullMax_z1_09),
                'FullMax_z1_10' => $request->input('kapasitas_z1_10', $addTimbangan->FullMax_z1_10),
                
                'FullMax_m1_01' => $request->input('kapasitas_m1_1', $addTimbangan->FullMax_m1_01),
                'FullMax_m1_02' => $request->input('kapasitas_m1_2', $addTimbangan->FullMax_m1_02),
                'FullMax_m1_03' => $request->input('kapasitas_m1_3', $addTimbangan->FullMax_m1_03),
                'FullMax_m1_04' => $request->input('kapasitas_m1_4', $addTimbangan->FullMax_m1_04),
                'FullMax_m1_05' => $request->input('kapasitas_m1_5', $addTimbangan->FullMax_m1_05),
                'FullMax_m1_06' => $request->input('kapasitas_m1_6', $addTimbangan->FullMax_m1_06),
                'FullMax_m1_07' => $request->input('kapasitas_m1_7', $addTimbangan->FullMax_m1_07),
                'FullMax_m1_08' => $request->input('kapasitas_m1_8', $addTimbangan->FullMax_m1_08),
                'FullMax_m1_09' => $request->input('kapasitas_m1_9', $addTimbangan->FullMax_m1_09),
                'FullMax_m1_10' => $request->input('kapasitas_m1_10', $addTimbangan->FullMax_m1_10),
                
                // Off-Center Loading Test
                'bebanOffCenter' => $request->input('beban_timbangan', $addTimbangan->bebanOffCenter),
                'offCenterFront' => $request->input('beban_depan', $addTimbangan->offCenterFront),
                'offCenterMiddle' => $request->input('beban_tengah', $addTimbangan->offCenterMiddle),
                'offCenterBack' => $request->input('beban_belakang', $addTimbangan->offCenterBack),
                'offCenterRight' => $request->input('beban_kanan', $addTimbangan->offCenterRight),
                'offCenterLeft' => $request->input('beban_kiri', $addTimbangan->offCenterLeft),
            ];
            
            $addTimbangan->update($updateData);
            \Log::info('✅ AddTimbanganMoisture updated');
            
        } else {
            // Buat baru jika belum ada
            $addData = [
                'calibration_id' => $calibration->id,
                
                'HalfMax_z1_01' => $request->input('setengah_z1_1'),
                'HalfMax_z1_02' => $request->input('setengah_z1_2'),
                'HalfMax_z1_03' => $request->input('setengah_z1_3'),
                'HalfMax_z1_04' => $request->input('setengah_z1_4'),
                'HalfMax_z1_05' => $request->input('setengah_z1_5'),
                'HalfMax_z1_06' => $request->input('setengah_z1_6'),
                'HalfMax_z1_07' => $request->input('setengah_z1_7'),
                'HalfMax_z1_08' => $request->input('setengah_z1_8'),
                'HalfMax_z1_09' => $request->input('setengah_z1_9'),
                'HalfMax_z1_10' => $request->input('setengah_z1_10'),
                
                'HalfMax_m1_01' => $request->input('setengah_m1_1'),
                'HalfMax_m1_02' => $request->input('setengah_m1_2'),
                'HalfMax_m1_03' => $request->input('setengah_m1_3'),
                'HalfMax_m1_04' => $request->input('setengah_m1_4'),
                'HalfMax_m1_05' => $request->input('setengah_m1_5'),
                'HalfMax_m1_06' => $request->input('setengah_m1_6'),
                'HalfMax_m1_07' => $request->input('setengah_m1_7'),
                'HalfMax_m1_08' => $request->input('setengah_m1_8'),
                'HalfMax_m1_09' => $request->input('setengah_m1_9'),
                'HalfMax_m1_10' => $request->input('setengah_m1_10'),
                
                'FullMax_z1_01' => $request->input('kapasitas_z1_1'),
                'FullMax_z1_02' => $request->input('kapasitas_z1_2'),
                'FullMax_z1_03' => $request->input('kapasitas_z1_3'),
                'FullMax_z1_04' => $request->input('kapasitas_z1_4'),
                'FullMax_z1_05' => $request->input('kapasitas_z1_5'),
                'FullMax_z1_06' => $request->input('kapasitas_z1_6'),
                'FullMax_z1_07' => $request->input('kapasitas_z1_7'),
                'FullMax_z1_08' => $request->input('kapasitas_z1_8'),
                'FullMax_z1_09' => $request->input('kapasitas_z1_9'),
                'FullMax_z1_10' => $request->input('kapasitas_z1_10'),
                
                'FullMax_m1_01' => $request->input('kapasitas_m1_1'),
                'FullMax_m1_02' => $request->input('kapasitas_m1_2'),
                'FullMax_m1_03' => $request->input('kapasitas_m1_3'),
                'FullMax_m1_04' => $request->input('kapasitas_m1_4'),
                'FullMax_m1_05' => $request->input('kapasitas_m1_5'),
                'FullMax_m1_06' => $request->input('kapasitas_m1_6'),
                'FullMax_m1_07' => $request->input('kapasitas_m1_7'),
                'FullMax_m1_08' => $request->input('kapasitas_m1_8'),
                'FullMax_m1_09' => $request->input('kapasitas_m1_9'),
                'FullMax_m1_10' => $request->input('kapasitas_m1_10'),
                
                'bebanOffCenter' => $request->input('beban_timbangan'),
                'offCenterFront' => $request->input('beban_depan'),
                'offCenterMiddle' => $request->input('beban_tengah'),
                'offCenterBack' => $request->input('beban_belakang'),
                'offCenterRight' => $request->input('beban_kanan'),
                'offCenterLeft' => $request->input('beban_kiri'),
            ];
            
            $hasAddData = false;
            foreach ($addData as $key => $value) {
                if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                    $hasAddData = true;
                    break;
                }
            }
            
            if ($hasAddData) {
                $addRecord = AddTimbanganMoisture::create($addData);
                \Log::info('➕ AddTimbanganMoisture created baru:', ['add_id' => $addRecord->id]);
            }
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA BARU (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $finalUpdateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $finalUpdateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate:', ['old' => $originalNamaAlat, 'new' => $namaAlatDariRequest]);
        }
        
        // Update certificate_id di calibration jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $finalUpdateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di calibration:', ['new' => $certificateIdBaru]);
        }
        
        // Update calibrated_by dan verified_by
        if ($request->filled('calibrated_by')) {
            $finalUpdateData['calibratedBy'] = $request->calibrated_by;
        }
        if ($request->filled('verified_by')) {
            $finalUpdateData['verifiedBy'] = $request->verified_by;
        }
        
        if (!empty($finalUpdateData)) {
            $calibration->update($finalUpdateData);
            \Log::info('✅ Calibration updated:', array_keys($finalUpdateData));
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        
        $savedDetailCount = DetailTimbanganMoisture::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddTimbanganMoisture::where('calibration_id', $calibration->id)->count();
        
        $temperatureRecords = DetailTimbanganMoisture::where('calibration_id', $calibration->id)
            ->where(function($query) {
                $query->whereNotNull('Tsetting')
                      ->orWhereNotNull('ReadAlat01')
                      ->orWhereNotNull('ReadAlat02')
                      ->orWhereNotNull('ReadAlat03')
                      ->orWhereNotNull('ReadSTD01')
                      ->orWhereNotNull('ReadSTD02')
                      ->orWhereNotNull('ReadSTD03');
            })
            ->count();
        
        \Log::info('📋 UPDATE SUMMARY (Timbangan Moisture - COMBINED DATA):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'total_records' => $savedDetailCount,
            'records_with_temperature' => $temperatureRecords . ' (should be 1-3)',
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateIdBaru ?? $calibration->certificate_id,
            'alat_standar' => $alatStandarString,
            'calibrated_by' => $calibration->calibratedBy,
            'verified_by' => $calibration->verifiedBy,
        ]);

        \Log::info('🎉 updateTimbanganMoisture COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTimbanganMoisture:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        
        throw new \Exception("Gagal mengupdate data Timbangan Moisture: " . $e->getMessage());
    }
}
/**
 * Format nilai string (mengizinkan karakter apapun)
 */
private function formatStringValue($value)
{
    if ($value === null || $value === '') {
        return null;
    }
    
    return trim($value);
}



private function storeTimbanganBias($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storeTimbanganBias', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId
        ]);
        
       // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT CHECKBOX (M1/M2)
        // ==================================================================
        
        // Ambil data alat standar dari request (array)
        $alatStandarArray = $request->input('alat_standar', []);
        
        
        
        // Gabungkan dengan koma
        $alatStandarString = implode(',', $alatStandarArray);
        
        // Method kalibrasi tetap
        $calibrationMethod = 'The Calibration of Weight and Balance, Third Edition - NMI Australia.';
        
        \Log::info('🔧 Alat standar dari checkbox:', [
            'alat_standar_array' => $alatStandarArray,
            'alat_standar_string' => $alatStandarString,
            'method' => $calibrationMethod,
            'tab_id' => $tabId
        ]);


        // ==================================================================
        // 2. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE) - TANPA form_index
        // ==================================================================
        $head = HeadTimbanganBias::where('calibration_id', $calibration->id)->first();
        
        $note = $this->getRequestValue($request, 'catatan', $tabId);
        $bebanSetengahKapasitas = $this->getRequestValue($request, 'beban_setengah_kapasitas', $tabId);
        $bebanKapasitasMaks = $this->getRequestValue($request, 'beban_kapasitas_maks', $tabId);
        
        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'note' => $note,
                'beban_setengah_kapasitas' => $bebanSetengahKapasitas,
                'beban_kapasitas_maks' => $bebanKapasitasMaks,
            ]);
            \Log::info('✅ HeadTimbanganBias updated:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        } else {
            // Buat head baru
            $head = HeadTimbanganBias::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'note' => $note,
                'beban_setengah_kapasitas' => $bebanSetengahKapasitas,
                'beban_kapasitas_maks' => $bebanKapasitasMaks,
            ]);
            \Log::info('✅ HeadTimbanganBias created:', ['head_id' => $head->id, 'tab_id' => $tabId]);
        }

        // ==================================================================
        // 3. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE) - TANPA form_index
        // ==================================================================
        $existingDetails = DetailTimbanganBias::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailTimbanganBias::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records for tab {$tabId}");
        }
        
        $existingAddData = AddTimbanganBias::where('calibration_id', $calibration->id)->count();
        if ($existingAddData > 0) {
            AddTimbanganBias::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingAddData} old add data records for tab {$tabId}");
        }

        // ==================================================================
        // 4. SIMPAN DETAIL TIMBANGAN BIAS - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving DetailTimbanganBias data...');
        $detailCount = 0;

        // Array mapping untuk mengkonversi nama input HTML ke field database
        $dataMapping = [
            // Baris Umum (z M M z) - ini adalah baris pertama di HTML
            [
                'titik_ukir' => 'titik_umum',
                'Lz1' => 'val_z_umum',
                'Lm1' => 'val_m1_umum',
                'Rm1' => 'val_m2_umum',
                'Rz1' => 'val_z2_umum',
                'STD' => 'standar_umum',
            ],
            // Titik 1 sampai 9
            ['titik_ukir' => 'titik_1', 'Lz1' => 'val_z_1', 'Lm1' => 'val_m1_1', 'Rm1' => 'val_m2_1', 'Rz1' => 'val_z2_1', 'STD' => 'standar_1'],
            ['titik_ukir' => 'titik_2', 'Lz1' => 'val_z_2', 'Lm1' => 'val_m1_2', 'Rm1' => 'val_m2_2', 'Rz1' => 'val_z2_2', 'STD' => 'standar_2'],
            ['titik_ukir' => 'titik_3', 'Lz1' => 'val_z_3', 'Lm1' => 'val_m1_3', 'Rm1' => 'val_m2_3', 'Rz1' => 'val_z2_3', 'STD' => 'standar_3'],
            ['titik_ukir' => 'titik_4', 'Lz1' => 'val_z_4', 'Lm1' => 'val_m1_4', 'Rm1' => 'val_m2_4', 'Rz1' => 'val_z2_4', 'STD' => 'standar_4'],
            ['titik_ukir' => 'titik_5', 'Lz1' => 'val_z_5', 'Lm1' => 'val_m1_5', 'Rm1' => 'val_m2_5', 'Rz1' => 'val_z2_5', 'STD' => 'standar_5'],
            ['titik_ukir' => 'titik_6', 'Lz1' => 'val_z_6', 'Lm1' => 'val_m1_6', 'Rm1' => 'val_m2_6', 'Rz1' => 'val_z2_6', 'STD' => 'standar_6'],
            ['titik_ukir' => 'titik_7', 'Lz1' => 'val_z_7', 'Lm1' => 'val_m1_7', 'Rm1' => 'val_m2_7', 'Rz1' => 'val_z2_7', 'STD' => 'standar_7'],
            ['titik_ukir' => 'titik_8', 'Lz1' => 'val_z_8', 'Lm1' => 'val_m1_8', 'Rm1' => 'val_m2_8', 'Rz1' => 'val_z2_8', 'STD' => 'standar_8'],
            ['titik_ukir' => 'titik_9', 'Lz1' => 'val_z_9', 'Lm1' => 'val_m1_9', 'Rm1' => 'val_m2_9', 'Rz1' => 'val_z2_9', 'STD' => 'standar_9'],
        ];
        
        foreach ($dataMapping as $index => $mapping) {
            // Ambil data dari request dengan getRequestValue (dukungan _tab)
            $titikUkur = $this->getRequestValue($request, $mapping['titik_ukir'], $tabId);
            $Lz1 = $this->getRequestValue($request, $mapping['Lz1'], $tabId);
            $Lm1 = $this->getRequestValue($request, $mapping['Lm1'], $tabId);
            $Rm1 = $this->getRequestValue($request, $mapping['Rm1'], $tabId);
            $Rz1 = $this->getRequestValue($request, $mapping['Rz1'], $tabId);
            $STD = $this->getRequestValue($request, $mapping['STD'], $tabId);
            
            \Log::debug("🔍 Row " . ($index + 1) . " data from request (tab {$tabId}):", [
                'titik_ukir' => $titikUkur,
                'Lz1' => $Lz1,
                'Lm1' => $Lm1,
                'Rm1' => $Rm1,
                'Rz1' => $Rz1,
                'STD' => $STD,
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($titikUkur) || !empty($STD) || 
                      !empty($Lm1) || !empty($Lz1) || 
                      !empty($Rm1) || !empty($Rz1);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_timbangan_bias_id' => $head->id,
                    'titikUkur' => $titikUkur,
                    'STD' => $STD,
                    'Lm1' => $Lm1,
                    'Lz1' => $Lz1,
                    'Rm1' => $Rm1,
                    'Rz1' => $Rz1,
                ];
                
                \Log::debug("💾 Saving DetailTimbanganBias row " . ($index + 1) . ":", $detailData);
                
                DetailTimbanganBias::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping row " . ($index + 1) . " - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailTimbanganBias records for tab {$tabId}");

        // ==================================================================
        // 5. SIMPAN ADD TIMBANGAN BIAS - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving AddTimbanganBias data...');
        
        $addData = [
            'calibration_id' => $calibration->id,
            
            // HalfMax (Setengah Kapasitas) - m1
            'HalfMax_m1_01' => $this->getRequestValue($request, 'setengah_mi_1', $tabId),
            'HalfMax_m1_02' => $this->getRequestValue($request, 'setengah_mi_2', $tabId),
            'HalfMax_m1_03' => $this->getRequestValue($request, 'setengah_mi_3', $tabId),
            'HalfMax_m1_04' => $this->getRequestValue($request, 'setengah_mi_4', $tabId),
            'HalfMax_m1_05' => $this->getRequestValue($request, 'setengah_mi_5', $tabId),
            'HalfMax_m1_06' => $this->getRequestValue($request, 'setengah_mi_6', $tabId),
            'HalfMax_m1_07' => $this->getRequestValue($request, 'setengah_mi_7', $tabId),
            'HalfMax_m1_08' => $this->getRequestValue($request, 'setengah_mi_8', $tabId),
            'HalfMax_m1_09' => $this->getRequestValue($request, 'setengah_mi_9', $tabId),
            'HalfMax_m1_10' => $this->getRequestValue($request, 'setengah_mi_10', $tabId),
            
            // FullMax (Kapasitas Maks) - m1
            'FullMax_m1_01' => $this->getRequestValue($request, 'kapasitas_mi_1', $tabId),
            'FullMax_m1_02' => $this->getRequestValue($request, 'kapasitas_mi_2', $tabId),
            'FullMax_m1_03' => $this->getRequestValue($request, 'kapasitas_mi_3', $tabId),
            'FullMax_m1_04' => $this->getRequestValue($request, 'kapasitas_mi_4', $tabId),
            'FullMax_m1_05' => $this->getRequestValue($request, 'kapasitas_mi_5', $tabId),
            'FullMax_m1_06' => $this->getRequestValue($request, 'kapasitas_mi_6', $tabId),
            'FullMax_m1_07' => $this->getRequestValue($request, 'kapasitas_mi_7', $tabId),
            'FullMax_m1_08' => $this->getRequestValue($request, 'kapasitas_mi_8', $tabId),
            'FullMax_m1_09' => $this->getRequestValue($request, 'kapasitas_mi_9', $tabId),
            'FullMax_m1_10' => $this->getRequestValue($request, 'kapasitas_mi_10', $tabId),

            // HalfMax (Setengah Kapasitas) - z1
            'HalfMax_z1_01' => $this->getRequestValue($request, 'setengah_zi_1', $tabId),
            'HalfMax_z1_02' => $this->getRequestValue($request, 'setengah_zi_2', $tabId),
            'HalfMax_z1_03' => $this->getRequestValue($request, 'setengah_zi_3', $tabId),
            'HalfMax_z1_04' => $this->getRequestValue($request, 'setengah_zi_4', $tabId),
            'HalfMax_z1_05' => $this->getRequestValue($request, 'setengah_zi_5', $tabId),
            'HalfMax_z1_06' => $this->getRequestValue($request, 'setengah_zi_6', $tabId),
            'HalfMax_z1_07' => $this->getRequestValue($request, 'setengah_zi_7', $tabId),
            'HalfMax_z1_08' => $this->getRequestValue($request, 'setengah_zi_8', $tabId),
            'HalfMax_z1_09' => $this->getRequestValue($request, 'setengah_zi_9', $tabId),
            'HalfMax_z1_10' => $this->getRequestValue($request, 'setengah_zi_10', $tabId),
            
            // FullMax (Kapasitas Maks) - z1
            'FullMax_z1_01' => $this->getRequestValue($request, 'kapasitas_zi_1', $tabId),
            'FullMax_z1_02' => $this->getRequestValue($request, 'kapasitas_zi_2', $tabId),
            'FullMax_z1_03' => $this->getRequestValue($request, 'kapasitas_zi_3', $tabId),
            'FullMax_z1_04' => $this->getRequestValue($request, 'kapasitas_zi_4', $tabId),
            'FullMax_z1_05' => $this->getRequestValue($request, 'kapasitas_zi_5', $tabId),
            'FullMax_z1_06' => $this->getRequestValue($request, 'kapasitas_zi_6', $tabId),
            'FullMax_z1_07' => $this->getRequestValue($request, 'kapasitas_zi_7', $tabId),
            'FullMax_z1_08' => $this->getRequestValue($request, 'kapasitas_zi_8', $tabId),
            'FullMax_z1_09' => $this->getRequestValue($request, 'kapasitas_zi_9', $tabId),
            'FullMax_z1_10' => $this->getRequestValue($request, 'kapasitas_zi_10', $tabId),
            
            // Off-Center Loading Test
            'bebanOffCenter' => $this->getRequestValue($request, 'beban_massa', $tabId),
            'offCenterFront' => $this->getRequestValue($request, 'effect_depan', $tabId),
            'offCenterMiddle' => $this->getRequestValue($request, 'effect_tengah', $tabId),
            'offCenterBack' => $this->getRequestValue($request, 'effect_belakang', $tabId),
            'offCenterRight' => $this->getRequestValue($request, 'effect_kanan', $tabId),
            'offCenterLeft' => $this->getRequestValue($request, 'effect_kiri', $tabId),
        ];
        
        // Cek apakah ada data untuk disimpan
        $hasAddData = false;
        foreach ($addData as $key => $value) {
            if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                $hasAddData = true;
                break;
            }
        }
        
        if ($hasAddData) {
            $addRecord = AddTimbanganBias::create($addData);
            \Log::info('✅ AddTimbanganBias saved:', ['add_id' => $addRecord->id, 'tab_id' => $tabId]);
        } else {
            \Log::info('⚠️ No AddTimbanganBias data to save for tab ' . $tabId);
        }

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $updateData = [];
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Calibrated by (nama_dikalibrasi)
        $calibratedBy = $this->getRequestValue($request, 'nama_dikalibrasi', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy, 'tab_id' => $tabId]);
        }
        
        // Verified by (nama_diperiksa)
        $verifiedBy = $this->getRequestValue($request, 'nama_diperiksa', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy, 'tab_id' => $tabId]);
        }
        
        // Bias factor
        $biasFactor = $this->getRequestValue($request, 'bias_factor', $tabId);
        if ($biasFactor) {
            $updateData['correction_factor'] = $biasFactor;
        }
        
        // Beban massa
        $bebanMassa = $this->getRequestValue($request, 'beban_massa', $tabId);
        if ($bebanMassa) {
            $updateData['beban_massa'] = $bebanMassa;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data for tab ' . $tabId);
        }

        // ==================================================================
        // 7. UPDATE JUMLAH FORM DI CALIBRATION
        // ==================================================================
        $totalForms = $calibration->jumlah_form ?? 1;
        if ($tabId > $totalForms) {
            $calibration->update(['jumlah_form' => $tabId]);
            \Log::info("✅ Updated jumlah_form to {$tabId}");
        }

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailTimbanganBias::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddTimbanganBias::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Timbangan Bias):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storeTimbanganBias COMPLETED for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTimbanganBias:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback jika terjadi error
        if (isset($head) && $head->id) {
            try {
                DetailTimbanganBias::where('calibration_id', $calibration->id)->delete();
                AddTimbanganBias::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::info('🔄 Rollback completed for tab ' . $tabId);
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Timbangan Bias: " . $e->getMessage());
    }
}

private function updateTimbanganBias($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateTimbanganBias');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headTimbanganBias;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PRE-UPDATE: PASTIKAN calibratedBy dan verifiedBy TIDAK NULL
        // ==================================================================
        $preUpdateData = [];
        
        if ($request->filled('calibratedBy')) {
            $preUpdateData['calibratedBy'] = $request->calibratedBy;
            \Log::info('🔄 PRE-UPDATE calibratedBy from request:', ['value' => $request->calibratedBy]);
        }
        
        if ($request->filled('verifiedBy')) {
            $preUpdateData['verifiedBy'] = $request->verifiedBy;
            \Log::info('🔄 PRE-UPDATE verifiedBy from request:', ['value' => $request->verifiedBy]);
        }
        
        if (!empty($preUpdateData)) {
            $calibration->update($preUpdateData);
            \Log::info('✅ PRE-UPDATE calibration completed:', $preUpdateData);
        }
        
        $calibration->refresh();
        
        // ==================================================================
        // 2. PROSES ALAT STANDAR DARI CHECKBOX
        // ==================================================================
        // Ambil data alat standar dari checkbox (array)
        $alatStandarArray = $request->input('alat_standar', []);
        
        // Jika tidak ada yang dipilih, set sebagai array kosong
        if (!is_array($alatStandarArray)) {
            $alatStandarArray = [];
        }
        
        // Filter nilai yang kosong
        $alatStandarArray = array_filter($alatStandarArray, function($value) {
            return !empty($value);
        });
        
        // Format untuk disimpan ke database (misal: "M1, M2")
        $alatStandarString = !empty($alatStandarArray) ? implode(', ', $alatStandarArray) : '';
        
        // Format alternatif dengan pipe "M1 | M2"
        $alatStandarPipeString = !empty($alatStandarArray) ? implode(' | ', $alatStandarArray) : '';
        
        \Log::info('🔧 Alat standar selected for Timbangan Bias:', [
            'alat_standar_array' => $alatStandarArray,
            'alat_standar_string' => $alatStandarString,
            'alat_standar_pipe' => $alatStandarPipeString
        ]);
        
        // ==================================================================
        // 3. UPDATE ATAU BUAT HEAD TIMBANGAN BIAS
        // ==================================================================
        $headData = [
            'standard' => $alatStandarPipeString, // Simpan dengan format "M1 | M2"
            'calibrationMethod' => 'PAS-IK1102-15 (Monograph 4 : The Calibration of Weights and Balances, NMI Australia 2010)',
            'note' => $request->input('note'),
            'beban_setengah_kapasitas' => $request->input('beban_setengah_kapasitas'),
            'beban_kapasitas_maks' => $request->input('beban_kapasitas_maks'),
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head = $calibration->headTimbanganBias) {
            $head->update($headData);
            \Log::info('✅ HeadTimbanganBias updated', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'standard' => $head->standard
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadTimbanganBias::create($headData);
            \Log::info('➕ HeadTimbanganBias created', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 4. UPDATE ADD TIMBANGAN BIAS - SIMPAN ALAT STANDAR
        // ==================================================================
        \Log::info('📊 Updating AddTimbanganBias data...');
        
        $addUpdateData = [];
        
        // SIMPAN ALAT STANDAR KE ADD TIMBANGAN BIAS (jika diperlukan)
        $addUpdateData['alat_standar'] = $alatStandarPipeString; // Simpan dengan format "M1 | M2"
        // Atau jika ingin simpan sebagai JSON:
        // $addUpdateData['alat_standar'] = json_encode($alatStandarArray);
        
        // Off Center Data
        $addUpdateData['offCenterMiddle'] = $request->input('offCenterMiddle');
        $addUpdateData['offCenterFront'] = $request->input('offCenterFront');
        $addUpdateData['offCenterBack'] = $request->input('offCenterBack');
        $addUpdateData['offCenterRight'] = $request->input('offCenterRight');
        $addUpdateData['offCenterLeft'] = $request->input('offCenterLeft');
        
       for ($i = 1; $i <= 10; $i++) {
            $n = str_pad($i, 2, '0', STR_PAD_LEFT);
        
            foreach (['HalfMax_m1', 'HalfMax_z1', 'FullMax_m1', 'FullMax_z1'] as $base) {
                $addUpdateData["{$base}_{$n}"] = $request->input("{$base}_{$n}");
            }
        }
        
        // Filter null values
        $addUpdateData = array_filter($addUpdateData, function($value) {
            return $value !== null;
        });
        
        if ($addTimbangan = $calibration->addTimbanganBias) {
            if (!empty($addUpdateData)) {
                $addTimbangan->update($addUpdateData);
                \Log::info('✅ AddTimbanganBias updated', [
                    'alat_standar' => $addTimbangan->alat_standar ?? null
                ]);
            } else {
                \Log::info('⚠️ No AddTimbanganBias data to update');
            }
        } else {
            $addUpdateData['calibration_id'] = $calibration->id;
            AddTimbanganBias::create($addUpdateData);
            \Log::info('➕ AddTimbanganBias created');
        }
        
        // ==================================================================
        // 5. UPDATE DETAIL TIMBANGAN BIAS (HAPUS & BUAT BARU - 10 RECORD)
        // ==================================================================
        DetailTimbanganBias::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        \Log::info('📊 Updating 10 records for Timbangan Bias...');
        
        for ($i = 1; $i <= 10; $i++) {
            // Data untuk setiap baris
            $titikUkur = $request->input("titikUkur_$i");
            $Lz1 = $request->input("Lz1_$i");
            $Lm1 = $request->input("Lm1_$i");
            $Rm1 = $request->input("Rm1_$i");
            $Rz1 = $request->input("Rz1_$i");
            $STD = $request->input("STD_$i");
            
            // SELALU simpan 10 record (agar kotak selalu muncul)
            $detailData = [
                'calibration_id' => $calibration->id,
                'titikUkur' => $titikUkur,
                'Lz1' => $Lz1,
                'Lm1' => $Lm1,
                'Rm1' => $Rm1,
                'Rz1' => $Rz1,
                'STD' => $STD,
            ];
            
            $record = DetailTimbanganBias::create($detailData);
            $detailCount++;
            
            \Log::debug("✅ Record {$i} saved", [
                'record_id' => $record->id,
                'titikUkur' => $detailData['titikUkur']
            ]);
        }
        
        \Log::info("✅ Updated {$detailCount} records for Timbangan Bias");
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $finalUpdateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $finalUpdateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $finalUpdateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Update data lainnya
        $fieldsToUpdate = [
            'brandAlat', 'kodeAlat', 'typeAlat', 'NoSeri', 'kapasitas', 'resolusi',
            'pemilikAlat', 'tanggalMasuk', 'tanggalKalibrasi', 'jenisPembacaan',
            'tempatKalibrasi', 'lokasiPT', 'kondisiAlat', 'keterangan',
            'RT_condition1', 'RT_condition2', 'RT_condition3',
            'RH_condition1', 'RH_condition2', 'RH_condition3'
        ];
        
        foreach ($fieldsToUpdate as $field) {
            if ($request->filled($field)) {
                $finalUpdateData[$field] = $request->$field;
            }
        }
        
        if (!empty($finalUpdateData)) {
            $calibration->update($finalUpdateData);
            \Log::info('✅ Calibration updated:', array_keys($finalUpdateData));
        }
        
        // ==================================================================
        // 7. FINAL VERIFICATION
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headTimbanganBias;
        $detailCountFinal = DetailTimbanganBias::where('calibration_id', $calibration->id)->count();
        $addCountFinal = AddTimbanganBias::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Timbangan Bias):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $detailCountFinal,
            'add_records' => $addCountFinal,
            'alat_standar_array' => $alatStandarArray,
            'alat_standar_string' => $alatStandarString,
            'alat_standar_pipe' => $alatStandarPipeString,
            'calibrated_by' => $calibration->calibratedBy,
            'verified_by' => $calibration->verifiedBy,
            'beban_setengah_kapasitas' => $headBaru->beban_setengah_kapasitas ?? null,
            'beban_kapasitas_maks' => $headBaru->beban_kapasitas_maks ?? null,
        ]);

        \Log::info('🎉 updateTimbanganBias COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTimbanganBias:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        
        throw new \Exception("Gagal mengupdate data Timbangan Bias: " . $e->getMessage());
    }
}

private function storeGaugeBlock($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }

        \Log::info('🚀 START storeGaugeBlock', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId
        ]);

       // ==================================================================
        // DEBUG: CEK APAKAH FILE TERDETEKSI (DUKUNG attachments & attachments[])
        // ==================================================================
        $attachmentFiles = $request->file('attachments')
            ?? $request->file('attachments[]')
            ?? $request->file("attachments_{$tabId}")
            ?? $request->file("form_{$tabId}_attachments")
            ?? $request->file("form_{$tabId}_attachments[]")
            ?? [];

        if (empty($attachmentFiles)) {
            foreach ($request->allFiles() as $fileKey => $fileVal) {
                if (stripos($fileKey, 'attachment') !== false) {
                    $attachmentFiles = $fileVal;
                    break;
                }
            }
        }

        // Pastikan bentuknya array
        if (!is_array($attachmentFiles)) {
            $attachmentFiles = [$attachmentFiles];
        }

        // Filter null
        $attachmentFiles = array_filter($attachmentFiles);

        \Log::info('🔍 DEBUG - Request has files?', [
            'has_file' => !empty($attachmentFiles),
            'all_files' => array_keys($request->allFiles()),
            'files_count' => count($attachmentFiles),
            'tab_id' => $tabId
        ]);

        // Jika ada file, log detailnya
        if (!empty($attachmentFiles)) {
            foreach ($attachmentFiles as $index => $file) {
                \Log::info("🔍 DEBUG - File {$index}:", [
                    'name' => $file->getClientOriginalName(),
                    'size' => $file->getSize(),
                    'mime' => $file->getMimeType(),
                    'valid' => $file->isValid(),
                    'error' => $file->getError(),
                    'tab_id' => $tabId
                ]);
            }
        } else {
            \Log::warning('⚠️ DEBUG - TIDAK ADA FILE attachments DI REQUEST!', ['tab_id' => $tabId]);
        }

        // ==================================================================
        // 1. PROSES ALAT STANDAR (DENGAN DUKUNGAN _tab)
        // ==================================================================
        // Alat standar default
        $alatStandarDefault = 'Mesin ULM 01-600D';

        // Cek apakah ada alat standar dari checkbox atau textarea
        $alatStandarValues = [];

        // Cek checkbox
        $checkboxValue = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($checkboxValue) && count($checkboxValue) > 0) {
            $alatStandarValues = $checkboxValue;
        } else {
            // Cek textarea
            $textValue = trim($this->getRequestValue($request, 'alat_standar_text', $tabId) ?? '');
            if (!empty($textValue)) {
                $alatStandarValues = [$textValue];
            }
        }

        // Jika tidak ada, gunakan default
        $alatStandarString = !empty($alatStandarValues) ? implode(', ', $alatStandarValues) : $alatStandarDefault;

        // Calibration method (bisa dari request atau default)
        $calibrationMethod = $this->getRequestValue($request, 'calibration_method', $tabId);
        if (empty($calibrationMethod)) {
            $calibrationMethod = 'PAS-IK1102-65';
        }

        \Log::info('🔧 Alat standar:', [
            'standard' => $alatStandarString,
            'method' => $calibrationMethod,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // HANDLE MULTIPLE ATTACHMENTS (SIMPAN KE PUBLIC)
        // ==================================================================
        $attachmentPaths = [];
        $attachmentNames = [];
        $attachmentSizes = [];
        $attachmentMimes = [];

        if (!empty($attachmentFiles)) {
            foreach ($attachmentFiles as $file) {
                if ($file->isValid()) {
                    try {
                        $originalName = $file->getClientOriginalName();
                        $safeName = preg_replace('/[^a-zA-Z0-9._-]/', '', $originalName);
                        $fileName = time() . '_' . uniqid() . '_' . $safeName;

                        // Simpan ke folder public/uploads/gauge-block/
                        $destinationPath = public_path('uploads/gauge-block/' . $calibration->id);

                        // Buat folder jika belum ada
                        if (!file_exists($destinationPath)) {
                            mkdir($destinationPath, 0777, true);
                        }

                        // Simpan ukuran & mime SEBELUM move (karena setelah move, file temp hilang)
                        $fileSize = $file->getSize();
                        $fileMime = $file->getMimeType();

                        // Pindahkan file ke public
                        $file->move($destinationPath, $fileName);

                        // Path untuk disimpan di database (relatif dari public)
                        $filePath = 'uploads/gauge-block/' . $calibration->id . '/' . $fileName;

                        $attachmentPaths[] = $filePath;
                        $attachmentNames[] = $originalName;
                        $attachmentSizes[] = $fileSize;
                        $attachmentMimes[] = $fileMime;

                        \Log::info('📎 Attachment uploaded to public:', [
                            'path' => $filePath,
                            'name' => $originalName,
                            'size' => $fileSize,
                            'mime' => $fileMime,
                            'tab_id' => $tabId
                        ]);
                    } catch (\Exception $e) {
                        \Log::error('❌ Failed to upload attachment:', [
                            'error' => $e->getMessage(),
                            'tab_id' => $tabId
                        ]);
                    }
                } else {
                    \Log::warning('⚠️ File tidak valid, dilewati:', [
                        'name' => $file->getClientOriginalName(),
                        'error_code' => $file->getError(),
                        'tab_id' => $tabId
                    ]);
                }
            }
        }

        // ==================================================================
        // 2. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE)
        // ==================================================================
        $head = HeadGaugeBlock::where('calibration_id', $calibration->id)->first();

        $satuanUnit = $this->getRequestValue($request, 'satuan_unit', $tabId);

        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
                'attachment' => !empty($attachmentPaths) ? json_encode($attachmentPaths) : $head->attachment,
                'attachment_name' => !empty($attachmentNames) ? json_encode($attachmentNames) : $head->attachment_name,
                'attachment_size' => !empty($attachmentSizes) ? json_encode($attachmentSizes) : $head->attachment_size,
                'attachment_mime' => !empty($attachmentMimes) ? json_encode($attachmentMimes) : $head->attachment_mime,
                'certificate_id' => $certificateId,
            ]);
            \Log::info('✅ HeadGaugeBlock updated:', [
                'head_id' => $head->id,
                'attachments_count' => count($attachmentPaths),
                'tab_id' => $tabId
            ]);
        } else {
            // Buat head baru
            $head = HeadGaugeBlock::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
                'attachment' => !empty($attachmentPaths) ? json_encode($attachmentPaths) : null,
                'attachment_name' => !empty($attachmentNames) ? json_encode($attachmentNames) : null,
                'attachment_size' => !empty($attachmentSizes) ? json_encode($attachmentSizes) : null,
                'attachment_mime' => !empty($attachmentMimes) ? json_encode($attachmentMimes) : null,
            ]);
            \Log::info('✅ HeadGaugeBlock created:', [
                'head_id' => $head->id,
                'attachments_count' => count($attachmentPaths),
                'tab_id' => $tabId
            ]);
        }

        // ==================================================================
        // 3. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE)
        // ==================================================================
        $existingDetails = DetailGaugeBlock::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailGaugeBlock::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records for tab {$tabId}");
        }

        $existingAddData = AddGaugeBlock::where('calibration_id', $calibration->id)->count();
        if ($existingAddData > 0) {
            AddGaugeBlock::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingAddData} old add records for tab {$tabId}");
        }

        // ==================================================================
        // 4. SIMPAN DETAIL GAUGE BLOCK - 15 BARIS
        // ==================================================================
        \Log::info('📊 Saving DetailGaugeBlock...');
        $detailCount = 0;

        for ($i = 1; $i <= 15; $i++) {
            $titikUkur = $this->getRequestValue($request, "titikUkur_{$i}", $tabId);
            $noSeri = $this->getRequestValue($request, "NoSeri_{$i}", $tabId);
            $std = $this->getRequestValue($request, "STD_{$i}", $tabId);

            $hasData = ($titikUkur !== null && $titikUkur !== '') ||
                       ($noSeri !== null && $noSeri !== '') ||
                       ($std !== null && $std !== '');

            if ($hasData) {
                DetailGaugeBlock::create([
                    'calibration_id' => $calibration->id,
                    'head_gauge_block_id' => $head->id,
                    'titikUkur' => $titikUkur,
                    'NoSeri' => $noSeri,
                    'STD' => $std,
                    'C1M' => $this->getRequestValue($request, "C1M_{$i}", $tabId),
                    'C1UL' => $this->getRequestValue($request, "C1UL_{$i}", $tabId),
                    'C1LL' => $this->getRequestValue($request, "C1LL_{$i}", $tabId),
                    'C1UR' => $this->getRequestValue($request, "C1UR_{$i}", $tabId),
                    'C1LR' => $this->getRequestValue($request, "C1LR_{$i}", $tabId),
                    'C1C' => $this->getRequestValue($request, "C1C_{$i}", $tabId),
                    'C2M' => $this->getRequestValue($request, "C2M_{$i}", $tabId),
                    'C2UL' => $this->getRequestValue($request, "C2UL_{$i}", $tabId),
                    'C2LL' => $this->getRequestValue($request, "C2LL_{$i}", $tabId),
                    'C2UR' => $this->getRequestValue($request, "C2UR_{$i}", $tabId),
                    'C2LR' => $this->getRequestValue($request, "C2LR_{$i}", $tabId),
                    'C2C' => $this->getRequestValue($request, "C2C_{$i}", $tabId),
                ]);
                $detailCount++;
            }
        }

        \Log::info("✅ Saved {$detailCount} DetailGaugeBlock records for tab {$tabId}");

        // ==================================================================
        // 5. SIMPAN ADD GAUGE BLOCK - 3 RECORD (Uji Kerataan)
        // ==================================================================
        \Log::info('📊 Saving AddGaugeBlock...');
        $addCount = 0;

        for ($i = 1; $i <= 3; $i++) {
            $titikUkurKerataan = $this->getRequestValue($request, "nominal_gauge_{$i}", $tabId);
            $kiriValue = $this->getRequestValue($request, "kiri{$i}", $tabId);
            $kananValue = $this->getRequestValue($request, "kanan{$i}", $tabId);

            $hasData = ($titikUkurKerataan !== null && $titikUkurKerataan !== '') ||
                       ($kiriValue !== null && $kiriValue !== '') ||
                       ($kananValue !== null && $kananValue !== '');

            if ($hasData) {
                AddGaugeBlock::create([
                    'calibration_id' => $calibration->id,
                    'head_gauge_block_id' => $head->id,
                    'titikUkurKerataan' => $titikUkurKerataan,
                    'Lsurface' => $kiriValue,
                    'Rsurface' => $kananValue,
                ]);
                $addCount++;
            }
        }

        \Log::info("✅ Saved {$addCount} AddGaugeBlock records for tab {$tabId}");

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD)
        // ==================================================================
        $updateData = [];

        // Calibrated by
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy, 'tab_id' => $tabId]);
        }

        // Verified by
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy, 'tab_id' => $tabId]);
        }

        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }

        // Alat standar
        if (!empty($alatStandarString)) {
            $updateData['alat_standar'] = $alatStandarString;
        }

        // Calibration method
        if ($calibrationMethod) {
            $updateData['calibration_method'] = $calibrationMethod;
        }

        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data for tab ' . $tabId);
        }

        // ==================================================================
        // 7. UPDATE JUMLAH FORM DI CALIBRATION
        // ==================================================================
        $totalForms = $calibration->jumlah_form ?? 1;
        if ($tabId > $totalForms) {
            $calibration->update(['jumlah_form' => $tabId]);
            \Log::info("✅ Updated jumlah_form to {$tabId}");
        }

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailGaugeBlock::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddGaugeBlock::where('calibration_id', $calibration->id)->count();

        \Log::info('📋 STORE SUMMARY (Gauge Block):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'attachments_count' => count($attachmentPaths),
            'attachments' => $attachmentPaths,
        ]);

        \Log::info('🎉 storeGaugeBlock COMPLETED for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeGaugeBlock:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);

        // Rollback jika terjadi error
        if (isset($head) && $head->id) {
            try {
                DetailGaugeBlock::where('calibration_id', $calibration->id)->delete();
                AddGaugeBlock::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::info('🔄 Rollback completed for tab ' . $tabId);
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }

        throw new \Exception("Gagal menyimpan data Gauge Block: " . $e->getMessage());
    }
}

private function updateGaugeBlock($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateGaugeBlock');

        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;

        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $calibration->namaAlat;
        $originalNamaAlat = $calibration->namaAlat;

        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        } elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
        } else {
            $existingHead = $calibration->headGaugeBlock;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
            }
        }

        // ==================================================================
        // 1. HANDLE MULTIPLE ATTACHMENTS
        // ==================================================================
        $head = $calibration->headGaugeBlock;

        // Ambil data attachment yang sudah ada
        $existingAttachments = [];
        $existingAttachmentNames = [];
        $existingAttachmentSizes = [];
        $existingAttachmentMimes = [];

        if ($head) {
            $existingAttachments = $head->attachment ? (is_string($head->attachment) ? json_decode($head->attachment, true) : ($head->attachment ?? [])) : [];
            $existingAttachmentNames = $head->attachment_name ? (is_string($head->attachment_name) ? json_decode($head->attachment_name, true) : ($head->attachment_name ?? [])) : [];
            $existingAttachmentSizes = $head->attachment_size ? (is_string($head->attachment_size) ? json_decode($head->attachment_size, true) : ($head->attachment_size ?? [])) : [];
            $existingAttachmentMimes = $head->attachment_mime ? (is_string($head->attachment_mime) ? json_decode($head->attachment_mime, true) : ($head->attachment_mime ?? [])) : [];
        }

        // ==================================================================
        // 1a. HAPUS FILE YANG DIPILIH (files_to_delete)
        //     ✅ Hapus dari 2 KEMUNGKINAN LOKASI (public + storage)
        // ==================================================================
        $filesToDelete = json_decode($request->input('files_to_delete', '[]'), true);
        if (!empty($filesToDelete) && is_array($filesToDelete)) {
            foreach ($filesToDelete as $fileName) {
                $index = array_search($fileName, $existingAttachmentNames);
                if ($index !== false) {
                    $filePath = $existingAttachments[$index] ?? null;
                    
                    if ($filePath) {
                        $deleted = false;
                        
                        // 1. Hapus dari public/uploads/ (untuk file baru)
                        $publicFilePath = public_path($filePath);
                        if (file_exists($publicFilePath)) {
                            unlink($publicFilePath);
                            \Log::info('🗑️ Attachment deleted from PUBLIC:', ['path' => $publicFilePath]);
                            $deleted = true;
                        }
                        
                        // 2. Hapus dari storage/app/public/ (untuk file lama)
                        $storageFilePath = storage_path('app/public/' . $filePath);
                        if (file_exists($storageFilePath)) {
                            unlink($storageFilePath);
                            \Log::info('🗑️ Attachment deleted from STORAGE:', ['path' => $storageFilePath]);
                            $deleted = true;
                        }
                        
                        // 3. Fallback via Storage facade
                        if (!$deleted && Storage::disk('public')->exists($filePath)) {
                            Storage::disk('public')->delete($filePath);
                            \Log::info('🗑️ Attachment deleted via Storage facade:', ['path' => $filePath]);
                        }
                    }
                    
                    // Hapus dari array
                    unset($existingAttachments[$index]);
                    unset($existingAttachmentNames[$index]);
                    unset($existingAttachmentSizes[$index]);
                    unset($existingAttachmentMimes[$index]);
                }
            }
            // Reindex array
            $existingAttachments = array_values($existingAttachments);
            $existingAttachmentNames = array_values($existingAttachmentNames);
            $existingAttachmentSizes = array_values($existingAttachmentSizes);
            $existingAttachmentMimes = array_values($existingAttachmentMimes);
        }

        // ==================================================================
        // 1b. UPLOAD FILE BARU (SIMPAN KE PUBLIC — SAMA SEPERTI STORE)
        // ==================================================================
        $allFileKeys = [];
        $possibleKeys = ['attachments', 'attachments[]'];
        foreach ($possibleKeys as $key) {
            if ($request->hasFile($key)) {
                $allFileKeys[] = $key;
            }
        }
        // Cek juga key dinamis
        foreach ($request->files->all() as $key => $fileValue) {
            if (str_starts_with($key, 'attachment') && !in_array($key, $allFileKeys)) {
                $allFileKeys[] = $key;
            }
        }

        \Log::info('📎 updateGaugeBlock - Detected file keys:', [
            'all_file_keys' => $allFileKeys,
            'all_request_files' => array_keys($request->files->all()),
        ]);

        $collectedFiles = [];
        foreach ($allFileKeys as $fileKey) {
            $fileOrFiles = $request->file($fileKey);
            if ($fileOrFiles === null) continue;
            if (is_array($fileOrFiles)) {
                foreach ($fileOrFiles as $f) {
                    if ($f && $f->isValid()) $collectedFiles[] = $f;
                }
            } else {
                if ($fileOrFiles->isValid()) $collectedFiles[] = $fileOrFiles;
            }
        }

        \Log::info('📎 updateGaugeBlock - Files to process:', ['count' => count($collectedFiles)]);

        foreach ($collectedFiles as $file) {
            if (!$file->isValid()) {
                \Log::warning('⚠️ File tidak valid, dilewati:', [
                    'name' => $file->getClientOriginalName(),
                    'error_code' => $file->getError()
                ]);
                continue;
            }

            $originalName = $file->getClientOriginalName();

            // Cek duplikat nama file
            if (in_array($originalName, $existingAttachmentNames)) {
                \Log::warning('⚠️ Duplicate file skipped:', ['name' => $originalName]);
                continue;
            }

            // Cek ukuran file (max 25MB)
            if ($file->getSize() > 25 * 1024 * 1024) {
                \Log::warning('⚠️ File too large, skipped:', ['name' => $originalName, 'size' => $file->getSize()]);
                continue;
            }

            try {
                // Generate nama file unik
                $safeName = preg_replace('/[^a-zA-Z0-9._-]/', '', $originalName);
                $fileName = time() . '_' . uniqid() . '_' . $safeName;

                // ============================================================
                // ✅ SIMPAN KE public/uploads/gauge-block/{calibration_id}/
                //    SAMA PERSIS SEPERTI storeGaugeBlock
                // ============================================================
                $destinationPath = public_path('uploads/gauge-block/' . $calibration->id);

                // Buat folder jika belum ada
                if (!file_exists($destinationPath)) {
                    mkdir($destinationPath, 0777, true);
                }

                // Simpan ukuran & mime SEBELUM move (file temp hilang setelah move)
                $fileSize = $file->getSize();
                $fileMime = $file->getMimeType();

                // Pindahkan file ke public
                $file->move($destinationPath, $fileName);

                // Path untuk disimpan di database
                $filePath = 'uploads/gauge-block/' . $calibration->id . '/' . $fileName;

                // Simpan metadata ke array
                $existingAttachments[] = $filePath;
                $existingAttachmentNames[] = $originalName;
                $existingAttachmentSizes[] = $fileSize;
                $existingAttachmentMimes[] = $fileMime;

                \Log::info('📎 New attachment uploaded (update → public):', [
                    'original_name' => $originalName,
                    'saved_as' => $fileName,
                    'path' => $filePath,
                    'size' => $fileSize,
                    'mime' => $fileMime
                ]);

            } catch (\Exception $e) {
                \Log::error('❌ Failed to upload attachment (update):', [
                    'name' => $originalName,
                    'error' => $e->getMessage()
                ]);
                continue;
            }
        }

        // ==================================================================
        // 2. UPDATE HEAD GAUGE BLOCK (DENGAN MULTIPLE ATTACHMENTS)
        // ==================================================================
        $textValue = trim($request->alat_standar_text ?? '');
        $arrayValue = $request->input('alat_standar', []);

        if (!empty($textValue)) {
            $standardValue = $textValue;
        } elseif (is_array($arrayValue) && count($arrayValue) > 0) {
            $standardValue = implode("\n", $arrayValue);
        } else {
            $standardValue = '';
        }

        $headData = [
            'standard' => $standardValue,
            'satuan_unit' => $request->satuan_unit ?? null,
            'calibrationMethod' => 'PAS-IK1102-09 (JIS B 7506:2003 (JMA/JSA); SNSU PK.P-09:2020)',
            'attachment' => !empty($existingAttachments) ? json_encode($existingAttachments) : null,
            'attachment_name' => !empty($existingAttachmentNames) ? json_encode($existingAttachmentNames) : null,
            'attachment_size' => !empty($existingAttachmentSizes) ? json_encode($existingAttachmentSizes) : null,
            'attachment_mime' => !empty($existingAttachmentMimes) ? json_encode($existingAttachmentMimes) : null,
            'updated_at' => now(),
        ];

        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
        }

        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadGaugeBlock updated:', [
                'head_id' => $head->id,
                'attachments_count' => count($existingAttachments),
                'attachments' => $existingAttachmentNames
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadGaugeBlock::create($headData);
            \Log::info('➕ HeadGaugeBlock created baru:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 3. UPDATE DETAIL GAUGE BLOCK (DELETE & RECREATE)
        // ==================================================================
        DetailGaugeBlock::where('calibration_id', $calibration->id)->delete();
        $detailCount = 0;

        for ($i = 1; $i <= 15; $i++) {
            $hasData = false;

            $titikUkur = $request->input("titikUkur_{$i}");
            $noSeri = $request->input("NoSeri_{$i}");
            $STD = $request->input("STD_{$i}");

            if (($titikUkur !== null && $titikUkur !== '') || 
                ($noSeri !== null && $noSeri !== '') || 
                ($STD !== null && $STD !== '')) {
                $hasData = true;
            }

            $c1Fields = ['C1M', 'C1UL', 'C1LL', 'C1UR', 'C1LR', 'C1C'];
            foreach ($c1Fields as $field) {
                if (($request->input("{$field}_{$i}") ?? '') !== '') {
                    $hasData = true;
                    break;
                }
            }

            $c2Fields = ['C2M', 'C2UL', 'C2LL', 'C2UR', 'C2LR', 'C2C'];
            foreach ($c2Fields as $field) {
                if (($request->input("{$field}_{$i}") ?? '') !== '') {
                    $hasData = true;
                    break;
                }
            }

            if ($hasData) {
                DetailGaugeBlock::create([
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'NoSeri' => $noSeri,
                    'STD' => $STD,
                    'C1M' => $request->input("C1M_{$i}"),
                    'C1UL' => $request->input("C1UL_{$i}"),
                    'C1LL' => $request->input("C1LL_{$i}"),
                    'C1UR' => $request->input("C1UR_{$i}"),
                    'C1LR' => $request->input("C1LR_{$i}"),
                    'C1C' => $request->input("C1C_{$i}"),
                    'C2M' => $request->input("C2M_{$i}"),
                    'C2UL' => $request->input("C2UL_{$i}"),
                    'C2LL' => $request->input("C2LL_{$i}"),
                    'C2UR' => $request->input("C2UR_{$i}"),
                    'C2LR' => $request->input("C2LR_{$i}"),
                    'C2C' => $request->input("C2C_{$i}"),
                ]);
                $detailCount++;
            }
        }

        // ==================================================================
        // 4. UPDATE ADD GAUGE BLOCK
        // ==================================================================
        AddGaugeBlock::where('calibration_id', $calibration->id)->delete();
        $addCount = 0;

        for ($i = 1; $i <= 3; $i++) {
            $titikUkurKerataan = $request->input("titikUkurKerataan{$i}");
            $Lsurface = $request->input("Lsurface{$i}");
            $Rsurface = $request->input("Rsurface{$i}");

            $hasAddData = ($titikUkurKerataan !== null && $titikUkurKerataan !== '') || 
                          ($Lsurface !== null && $Lsurface !== '') || 
                          ($Rsurface !== null && $Rsurface !== '');

            if ($hasAddData) {
                AddGaugeBlock::create([
                    'calibration_id' => $calibration->id,
                    'titikUkurKerataan' => $titikUkurKerataan,
                    'Lsurface' => $Lsurface,
                    'Rsurface' => $Rsurface,
                    'note' => $request->input('note'),
                ]);
                $addCount++;
            }
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION
        // ==================================================================
        $updateData = [];

        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
        }

        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
        }

        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }

        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }

        if (!empty($updateData)) {
            $calibration->update($updateData);
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 UPDATE SUMMARY (Gauge Block):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $detailCount,
            'add_records' => $addCount,
            'certificate_id' => $head->certificate_id ?? null,
            'attachments_count' => count($existingAttachments),
            'attachments_deleted' => $filesToDelete ?? [],
            'attachments_new' => $existingAttachmentNames,
        ]);

        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateGaugeBlock:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
        ]);
        throw $e;
    }
}

/**
 * Hapus attachment secara langsung (via AJAX)
 * 
 * @param Request $request
 * @param string $id - Calibration ID
 * @param int $index - Index file di array
 * @return \Illuminate\Http\JsonResponse
 */
public function deleteAttachment(Request $request, $id, $index)
{
    try {
        \Log::info('🗑️ === DELETE ATTACHMENT (AJAX) ===', [
            'calibration_id' => $id,
            'index' => $index
        ]);

        // Cari calibration
        $calibration = \App\Models\Calibration::findOrFail($id);
        $head = $calibration->headGaugeBlock;

        if (!$head) {
            return response()->json([
                'success' => false,
                'message' => 'HeadGaugeBlock tidak ditemukan'
            ], 404);
        }

        // Ambil data attachment
        $existingAttachments = $head->attachment 
            ? (is_string($head->attachment) ? json_decode($head->attachment, true) : ($head->attachment ?? [])) 
            : [];
        $existingAttachmentNames = $head->attachment_name 
            ? (is_string($head->attachment_name) ? json_decode($head->attachment_name, true) : ($head->attachment_name ?? [])) 
            : [];
        $existingAttachmentSizes = $head->attachment_size 
            ? (is_string($head->attachment_size) ? json_decode($head->attachment_size, true) : ($head->attachment_size ?? [])) 
            : [];
        $existingAttachmentMimes = $head->attachment_mime 
            ? (is_string($head->attachment_mime) ? json_decode($head->attachment_mime, true) : ($head->attachment_mime ?? [])) 
            : [];

        // Validasi index
        if (!isset($existingAttachments[$index])) {
            return response()->json([
                'success' => false,
                'message' => "File di index {$index} tidak ditemukan"
            ], 404);
        }

        $filePath = $existingAttachments[$index];
        $fileName = $existingAttachmentNames[$index] ?? basename($filePath);

        \Log::info('🔍 File to delete:', [
            'path' => $filePath,
            'name' => $fileName,
            'index' => $index
        ]);

        // ==========================================================
        // HAPUS FILE FISIK DI BERBAGAI LOKASI
        // ==========================================================
        $deleted = false;

        // Lokasi 1: public/uploads/gauge-block/{id}/file
        $publicPath = public_path($filePath);
        if (file_exists($publicPath)) {
            if (@unlink($publicPath)) {
                \Log::info('✅ DELETED from PUBLIC:', ['path' => $publicPath]);
                $deleted = true;
            } else {
                \Log::error('❌ FAILED delete PUBLIC:', ['path' => $publicPath]);
            }
        }

        // Lokasi 2: storage/app/public/uploads/...
        $storagePath = storage_path('app/public/' . $filePath);
        if (file_exists($storagePath)) {
            if (@unlink($storagePath)) {
                \Log::info('✅ DELETED from STORAGE:', ['path' => $storagePath]);
                $deleted = true;
            } else {
                \Log::error('❌ FAILED delete STORAGE:', ['path' => $storagePath]);
            }
        }

        // Lokasi 3: public/storage/... (symlink)
        $symlinkPath = public_path('storage/' . $filePath);
        if (file_exists($symlinkPath)) {
            if (@unlink($symlinkPath)) {
                \Log::info('✅ DELETED from SYMLINK:', ['path' => $symlinkPath]);
                $deleted = true;
            }
        }

        // Lokasi 4: fallback glob search
        if (!$deleted) {
            $pattern = public_path('uploads/gauge-block/*/' . basename($filePath));
            $foundFiles = glob($pattern);
            
            foreach ($foundFiles as $found) {
                if (@unlink($found)) {
                    \Log::info('✅ DELETED via glob search:', ['path' => $found]);
                    $deleted = true;
                }
            }
        }

        if (!$deleted) {
            \Log::warning('⚠️ File tidak ditemukan di manapun, tapi tetap hapus dari database');
        }

        // ==========================================================
        // HAPUS DARI ARRAY & UPDATE DATABASE
        // ==========================================================
        unset($existingAttachments[$index]);
        unset($existingAttachmentNames[$index]);
        unset($existingAttachmentSizes[$index]);
        unset($existingAttachmentMimes[$index]);

        // Reindex
        $existingAttachments = array_values($existingAttachments);
        $existingAttachmentNames = array_values($existingAttachmentNames);
        $existingAttachmentSizes = array_values($existingAttachmentSizes);
        $existingAttachmentMimes = array_values($existingAttachmentMimes);

        // Update database
        $head->update([
            'attachment' => !empty($existingAttachments) ? json_encode($existingAttachments) : null,
            'attachment_name' => !empty($existingAttachmentNames) ? json_encode($existingAttachmentNames) : null,
            'attachment_size' => !empty($existingAttachmentSizes) ? json_encode($existingAttachmentSizes) : null,
            'attachment_mime' => !empty($existingAttachmentMimes) ? json_encode($existingAttachmentMimes) : null,
            'updated_at' => now(),
        ]);

        // Reload untuk verifikasi
        $head->refresh();

        \Log::info('✅ Database updated:', [
            'remaining_count' => count($existingAttachments),
            'remaining_names' => $existingAttachmentNames,
            'db_verified' => $head->attachment_name
        ]);

        return response()->json([
            'success' => true,
            'message' => "File '{$fileName}' berhasil dihapus",
            'deleted' => [
                'name' => $fileName,
                'path' => $filePath,
                'file_deleted' => $deleted
            ],
            'remaining' => [
                'count' => count($existingAttachments),
                'names' => $existingAttachmentNames,
                'paths' => $existingAttachments
            ]
        ]);

    } catch (\Exception $e) {
        \Log::error('💥 ERROR deleteAttachment:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);

        return response()->json([
            'success' => false,
            'message' => 'Gagal menghapus file: ' . $e->getMessage()
        ], 500);
    }
}

private function storeHoletest($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storeHoletest', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (DENGAN DUKUNGAN _tab)
        // ==================================================================
        // Alat standar default
        $alatStandarDefault = 'RING GAUGE 3 ~ 45 mm';
        
        // Cek apakah ada alat standar dari checkbox atau textarea
        $alatStandarValues = [];
        
        // Cek checkbox
        $checkboxValue = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($checkboxValue) && count($checkboxValue) > 0) {
            $alatStandarValues = $checkboxValue;
        } else {
            // Cek textarea
            $textValue = trim($this->getRequestValue($request, 'alat_standar_text', $tabId) ?? '');
            if (!empty($textValue)) {
                $alatStandarValues = [$textValue];
            }
        }
        
        // Jika tidak ada, gunakan default
        $alatStandarString = !empty($alatStandarValues) ? implode(', ', $alatStandarValues) : $alatStandarDefault;
        
        // Calibration method (bisa dari request atau default)
        $calibrationMethod = $this->getRequestValue($request, 'calibration_method', $tabId);
        if (empty($calibrationMethod)) {
            $calibrationMethod = 'PAS-IK1102-49';
        }
        
        \Log::info('🔧 Alat standar:', [
            'standard' => $alatStandarString,
            'method' => $calibrationMethod,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE) - TANPA form_index
        // ==================================================================
        $head = HeadHoletest::where('calibration_id', $calibration->id)->first();
        
        $satuanUnit = $this->getRequestValue($request, 'satuan_unit', $tabId);
        
        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
                'certificate_id' => $certificateId,
            ]);
            \Log::info('✅ HeadHoletest updated:', [
                'head_id' => $head->id,
                'tab_id' => $tabId
            ]);
        } else {
            // Buat head baru
            $head = HeadHoletest::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
            ]);
            \Log::info('✅ HeadHoletest created:', [
                'head_id' => $head->id,
                'tab_id' => $tabId
            ]);
        }

        // ==================================================================
        // 3. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE) - TANPA form_index
        // ==================================================================
        $existingDetails = DetailHoletest::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailHoletest::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records for tab {$tabId}");
        }

        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS - 14 BARIS (DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving detail measurements...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 14; $i++) {
            // Ambil data dengan getRequestValue
            $titikUkur = $this->getRequestValue($request, "nominal_{$i}", $tabId);
            
            // Cek apakah ada penunjukan yang diisi (minimal satu)
            $hasPenunjukan = false;
            $penunjukan = [];
            for ($j = 1; $j <= 5; $j++) {
                $value = $this->getRequestValue($request, "penunjukan_{$i}_{$j}", $tabId);
                $penunjukan[$j] = $value;
                if (!empty($value)) {
                    $hasPenunjukan = true;
                }
            }
            
            // Simpan jika ada data nominal atau penunjukan
            if (!empty($titikUkur) || $hasPenunjukan) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_holetest_id' => $head->id,
                    'titikUkur' => $titikUkur ?? '',
                    'rep01' => $penunjukan[1] ?? null,
                    'rep02' => $penunjukan[2] ?? null,
                    'rep03' => $penunjukan[3] ?? null,
                    'rep04' => $penunjukan[4] ?? null,
                    'rep05' => $penunjukan[5] ?? null,
                ];

                \Log::debug("📝 Saving detail row {$i}:", $detailData);
                
                DetailHoletest::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping row {$i} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for tab {$tabId}");

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $updateData = [];
        
        // Calibrated by
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy, 'tab_id' => $tabId]);
        }
        
        // Verified by
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy, 'tab_id' => $tabId]);
        }
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
        }
        
        // Alat standar
        if (!empty($alatStandarString)) {
            $updateData['alat_standar'] = $alatStandarString;
        }
        
        // Calibration method
        if ($calibrationMethod) {
            $updateData['calibration_method'] = $calibrationMethod;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data for tab ' . $tabId);
        }

        // ==================================================================
        // 6. UPDATE JUMLAH FORM DI CALIBRATION
        // ==================================================================
        $totalForms = $calibration->jumlah_form ?? 1;
        if ($tabId > $totalForms) {
            $calibration->update(['jumlah_form' => $tabId]);
            \Log::info("✅ Updated jumlah_form to {$tabId}");
        }

        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailHoletest::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Holetest):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storeHoletest COMPLETED for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeHoletest:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback jika terjadi error
        if (isset($head) && $head->id) {
            try {
                DetailHoletest::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::info('🔄 Rollback completed for tab ' . $tabId);
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Holetest: " . $e->getMessage());
    }
}

private function updateHoletest($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateHoletest =====', [
        'calibration_id' => $calibration->id,
        'certificate_id' => $calibration->headHoletest->certificate_id ?? 'N/A',
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. AMBIL DATA DARI HIDDEN INPUT
        // ==================================================================
        // Ambil alat standar dari hidden input
        $alatStandarText = $request->input('alat_standar_text', '');
        $alatStandarString = !empty($alatStandarText) ? $alatStandarText : '';
        
        // Ambil metode kalibrasi dari hidden input
        $metodeKalibrasi = $request->input('metode_kalibrasi', '');
        $calibrationMethod = !empty($metodeKalibrasi) ? $metodeKalibrasi : '';
        
        \Log::info('📥 HIDDEN INPUT DATA:', [
            'alat_standar_text' => $alatStandarText,
            'alat_standar_string' => $alatStandarString,
            'metode_kalibrasi' => $metodeKalibrasi,
            'calibration_method' => $calibrationMethod,
            'old_standard' => $calibration->headHoletest->standard ?? 'null',
            'old_method' => $calibration->headHoletest->calibrationMethod ?? 'null'
        ]);
        
        // ==================================================================
        // 1. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headHoletest;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 2. UPDATE ALAT STANDAR & METODE KALIBRASI
        // ==================================================================
        \Log::info('🔧 ALAT STANDAR & METODE UPDATE:', [
            'standard' => $alatStandarString,
            'calibrationMethod' => $calibrationMethod,
            'old_standard' => $calibration->headHoletest->standard ?? 'null',
            'old_method' => $calibration->headHoletest->calibrationMethod ?? 'null'
        ]);

        // Update head data
        $headData = [
            'standard' => $alatStandarString,
            'satuan_unit' => $request->satuan_unit,
            'calibrationMethod' => $calibrationMethod,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head = $calibration->headHoletest) {
            $head->update($headData);
            \Log::info('✅ HEAD DATA UPDATED:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'standard_updated' => true,
                'method_updated' => true,
                'satuan_unit_updated' => $request->satuan_unit,
            ]);
        } else {
            \Log::warning('⚠️ NO HEAD DATA FOUND, creating new...');
            
            $headData['calibration_id'] = $calibration->id;
            $head = HeadHoletest::create($headData);
            
            \Log::info('➕ NEW HEAD CREATED:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }

        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS - LANGSUNG TANPA FORMAT
        // ==================================================================
        \Log::info('📊 DETAIL MEASUREMENTS UPDATE:', [
            'old_records_count' => DetailHoletest::where('calibration_id', $calibration->id)->count(),
            'new_titikUkur_count' => is_array($request->titikUkur) ? count(array_filter($request->titikUkur)) : 0
        ]);
        
        // Hapus data detail lama
        $deletedCount = DetailHoletest::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ OLD DATA DELETED:', ['deleted_count' => $deletedCount]);
        
        // Simpan data detail baru - 10 BARIS
        $detailCount = 0;
        $errors = [];
        $maxRows = 10;
        
        for ($i = 0; $i < $maxRows; $i++) {
            // Ambil data - LANGSUNG tanpa format
            $titikUkur = $request->input("titikUkur.{$i}") ?? $request->titikUkur[$i] ?? null;
            $rep01 = $request->input("rep01.{$i}") ?? $request->rep01[$i] ?? null;
            $rep02 = $request->input("rep02.{$i}") ?? $request->rep02[$i] ?? null;
            $rep03 = $request->input("rep03.{$i}") ?? $request->rep03[$i] ?? null;
            $rep04 = $request->input("rep04.{$i}") ?? $request->rep04[$i] ?? null;
            $rep05 = $request->input("rep05.{$i}") ?? $request->rep05[$i] ?? null;
            
            // Check if row has data
            $hasData = !empty(trim($titikUkur ?? '')) || 
                      !empty(trim($rep01 ?? '')) || 
                      !empty(trim($rep02 ?? '')) || 
                      !empty(trim($rep03 ?? '')) || 
                      !empty(trim($rep04 ?? '')) || 
                      !empty(trim($rep05 ?? ''));
            
            if ($hasData) {
                try {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'titikUkur' => $titikUkur,  // LANGSUNG, tanpa format
                        'rep01' => $rep01,          // LANGSUNG, tanpa format
                        'rep02' => $rep02,          // LANGSUNG, tanpa format
                        'rep03' => $rep03,          // LANGSUNG, tanpa format
                        'rep04' => $rep04,          // LANGSUNG, tanpa format
                        'rep05' => $rep05,          // LANGSUNG, tanpa format
                    ];
                    
                    \Log::debug("💾 SAVING ROW {$i}:", ['data' => $detailData]);
                    
                    DetailHoletest::create($detailData);
                    $detailCount++;
                    
                } catch (\Exception $rowError) {
                    $errors[] = "Row {$i}: " . $rowError->getMessage();
                    \Log::error("❌ ROW {$i} SAVE ERROR:", [
                        'error' => $rowError->getMessage()
                    ]);
                }
            } else {
                \Log::debug("⏭️ SKIPPING EMPTY ROW {$i}");
            }
        }
        
        \Log::info("✅ DETAIL DATA SAVED:", [
            'total_records' => $detailCount,
            'errors_count' => count($errors)
        ]);

        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        if ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if ($request->filled('temperature')) {
            $updateData['temperature'] = $request->temperature;
        }
        
        if ($request->filled('humidity')) {
            $updateData['humidity'] = $request->humidity;
        }
        
        if ($request->filled('calibration_date')) {
            $updateData['calibration_date'] = $request->calibration_date;
        }
        
        if ($request->filled('next_calibration_date')) {
            $updateData['next_calibration_date'] = $request->next_calibration_date;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 CALIBRATION ADDITIONAL DATA UPDATED:', array_keys($updateData));
        }

        // ==================================================================
        // 5. VERIFY SAVED DATA
        // ==================================================================
        $savedDetails = DetailHoletest::where('calibration_id', $calibration->id)
            ->orderBy('id')
            ->get();
            
        \Log::info('🔍 VERIFY SAVED DATA:', [
            'total_saved' => $savedDetails->count(),
            'first_3_rows_sample' => $savedDetails->take(3)->map(function($item) {
                return [
                    'id' => $item->id,
                    'titikUkur' => $item->titikUkur,
                    'rep01' => $item->rep01,
                    'rep02' => $item->rep02,
                    'rep03' => $item->rep03,
                    'rep04' => $item->rep04,
                    'rep05' => $item->rep05,
                ];
            })->toArray()
        ]);

        // ==================================================================
        // 6. FINAL SUMMARY
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headHoletest;
        $finalDetailCount = DetailHoletest::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY:', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $finalDetailCount,
            'alat_standar' => $alatStandarString,
            'metode_kalibrasi' => $calibrationMethod,
            'satuan_unit' => $headBaru->satuan_unit ?? 'N/A',
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
            'temperature' => $calibration->temperature,
            'humidity' => $calibration->humidity,
        ]);

        \Log::info('🎉 updateHoletest COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 updateHoletest FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'unknown'
        ]);
        throw $e;
    }
}



private function storeConductivityMeter($request, $calibration, $certificateId, $isMultipleSubmit = false, $jumlahForm = 1)
{
    try {
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);

        \Log::info('🚀 START storeConductivityMeter', [
            'calibration_id' => $calibration->id,
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);

        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_{$formIndex}_tab{$tab}";
            }
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_{$formIndex}";
            $possibleKeys[] = "{$baseKey}{$suffix}_{$formIndex}";

            if ($formIndex == 1 || empty($additionalParams)) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                    $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                }
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }

            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    return $value;
                }
            }
            return null;
        };

        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) return array_filter($value);
                    return [$value];
                }
            }
            return [];
        };

        $lastStandardValue = '';
        $lastCalibrationMethod = '';

        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $alatStandar = $findArrayValue('alat_standar', $formIndex);
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
                if (!is_array($alatStandar)) $alatStandar = [$alatStandar];
            }
            if (!is_array($alatStandar)) $alatStandar = [$alatStandar];
            $alatStandar = array_filter($alatStandar, function($val) { return !empty($val) && $val !== 'on'; });
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : 'CRM, Thermoscientific';
            $standardValue = rtrim($standardValue, '.');
            $lastStandardValue = $standardValue;

            $calibrationMethod = $findValue('calibration_method', $formIndex) ?? 'PAS-IK1102-41';
            $lastCalibrationMethod = $calibrationMethod;

            $keteranganFungsiKomponen = $findValue('keterangan_fungsi_komponen', $formIndex) ?? $findValue('keterangan', $formIndex);
           $kapasitasVal = $findValue('kapasitas', $formIndex) ?? $request->input("head_kapasitas_{$formIndex}") ?? $request->input("kapasitas_{$formIndex}") ?? $request->input('kapasitas');
            $resolusiVal = $findValue('resolusi', $formIndex) ?? $request->input("head_resolusi_{$formIndex}") ?? $request->input("resolusi_{$formIndex}") ?? $request->input('resolusi');

            $head = HeadConductivityMeter::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard' => $standardValue,
                    'calibrationMethod' => $calibrationMethod,
                    'certificate_id' => $certificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                    'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                    'kapasitas' => $kapasitasVal,
                    'resolusi' => $resolusiVal,
                ]
            );

            DetailConductivityMeter::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->delete();

            $detailCount = 0;
            for ($i = 1; $i <= 6; $i++) {
                $nilaiCRM = $findValue('nilai_crm', $formIndex, [$i]);
                if (empty($nilaiCRM)) {
                    $nilaiCRM = $findValue('nilaiCRM', $formIndex, [$i]);
                }
                
                $rep1 = $findValue('pembacaan', $formIndex, [$i, 1]);
                $rep2 = $findValue('pembacaan', $formIndex, [$i, 2]);
                $rep3 = $findValue('pembacaan', $formIndex, [$i, 3]);
                $rep4 = $findValue('pembacaan', $formIndex, [$i, 4]);
                $rep5 = $findValue('pembacaan', $formIndex, [$i, 5]);

                $resolusi = $findValue('resolusi', $formIndex, [$i]);
                $suhuCRM = $findValue('suhu_crm', $formIndex, [$i]);
                if (empty($suhuCRM)) {
                    $suhuCRM = $findValue('suhuCRM', $formIndex, [$i]);
                }

                $hasData = !empty($nilaiCRM) || !empty($rep1) || !empty($rep2) || !empty($rep3) || !empty($rep4) || !empty($rep5) || !empty($resolusi) || !empty($suhuCRM);

                if ($hasData) {
                    DetailConductivityMeter::create([
                        'calibration_id' => $calibration->id,
                        'head_conductivity_meter_id' => $head->id,
                        'head_condictivity_meter_id' => $head->id,
                        'form_index' => $formIndex,
                        'nilaiCRM' => $nilaiCRM,
                        'rep01' => $rep1,
                        'rep02' => $rep2,
                        'rep03' => $rep3,
                        'rep04' => $rep4,
                        'rep05' => $rep5,
                        'Resolusi' => $resolusi,
                        'suhuCRM' => $suhuCRM,
                    ]);
                    $detailCount++;
                }
            }
        }

        $calibration->update([
            'jumlah_form' => $jumlahForm,
            'alat_standar' => $lastStandardValue,
            'calibration_method' => $lastCalibrationMethod,
        ]);

        \Log::info('📋 STORE SUMMARY (Conductivity Meter Multi-Form):', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'certificate_id' => $certificateId,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 storeConductivityMeter COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeConductivityMeter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback jika terjadi error
        if (isset($head) && $head->id) {
            try {
                DetailConductivityMeter::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::info('🔄 Rollback completed for tab ' . $tabId);
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Conductivity Meter: " . $e->getMessage());
    }
}

private function updateConductivityMeter($request, $calibration, $newCertificateId = null)
{
    try {
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);

        \Log::info('🚀 START updateConductivityMeter', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm
        ]);
        
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
        }
        
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_{$formIndex}_tab{$tab}";
            }
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_{$formIndex}";
            $possibleKeys[] = "{$baseKey}{$suffix}_{$formIndex}";

            if ($formIndex == 1 || empty($additionalParams)) {
                for ($tab = 1; $tab <= 10; $tab++) {
                    $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                    $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                }
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }

            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    return $value;
                }
            }
            return null;
        };

        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
            }
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            $alatStandar = array_filter($alatStandar, function($val) { return !empty($val) && $val !== 'on'; });
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : 'CRM, Thermoscientific';
            $standardValue = rtrim($standardValue, '.');
            $lastStandardValue = $standardValue;

            $calibrationMethod = $request->input("calibration_method_{$formIndex}", $request->input('calibration_method', 'PAS-IK1102-41'));
            $lastCalibrationMethod = $calibrationMethod;

            $keteranganFungsiKomponen = $request->input("keterangan_fungsi_komponen_{$formIndex}")
                ?? $request->input("keterangan_{$formIndex}")
                ?? $request->input("form_{$formIndex}_keterangan_fungsi_komponen")
                ?? $request->input("form_{$formIndex}_keterangan")
                ?? $request->input('keterangan_fungsi_komponen')
                ?? $request->input('keterangan');

              $kapasitasVal = $findValue('kapasitas', $formIndex) ?? $request->input("head_kapasitas_{$formIndex}") ?? $request->input("kapasitas_{$formIndex}") ?? $request->input('kapasitas');
            $resolusiVal = $findValue('resolusi', $formIndex) ?? $request->input("head_resolusi_{$formIndex}") ?? $request->input("resolusi_{$formIndex}") ?? $request->input('resolusi');

            $head = HeadConductivityMeter::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();

            $headData = [
                'standard' => $standardValue,
                'calibrationMethod' => $calibrationMethod,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                'kapasitas' => $kapasitasVal,
                'resolusi' => $resolusiVal,
            ];
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
            }

            if ($head) {
                $head->update($headData);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                $head = HeadConductivityMeter::create($headData);
            }

            // Detail rows for formIndex
            DetailConductivityMeter::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->delete();

            // Try getting details from request array details_{formIndex} or details
            $details = $request->input("details_{$formIndex}", []);
            if (empty($details) && $formIndex == 1) {
                $details = $request->input('details', []);
            }

            if (!empty($details) && is_array($details)) {
                foreach ($details as $index => $detail) {
                    $nilaiCRM = $detail['nilaiCRM'] ?? $detail['nilai_crm'] ?? null;
                    $rep01 = $detail['rep01'] ?? $detail['pembacaan_1'] ?? null;
                    $rep02 = $detail['rep02'] ?? $detail['pembacaan_2'] ?? null;
                    $rep03 = $detail['rep03'] ?? $detail['pembacaan_3'] ?? null;
                    $rep04 = $detail['rep04'] ?? $detail['pembacaan_4'] ?? null;
                    $rep05 = $detail['rep05'] ?? $detail['pembacaan_5'] ?? null;
                    $resolusi = $detail['Resolusi'] ?? $detail['resolusi'] ?? null;
                    $suhuCRM = $detail['suhuCRM'] ?? $detail['suhu_crm'] ?? null;

                    $hasData = !empty($nilaiCRM) || !empty($rep01) || !empty($rep02) || !empty($rep03) || !empty($rep04) || !empty($rep05) || !empty($resolusi) || !empty($suhuCRM);

                    if ($hasData) {
                        DetailConductivityMeter::create([
                            'calibration_id' => $calibration->id,
                            'head_conductivity_meter_id' => $head->id,
                            'head_condictivity_meter_id' => $head->id,
                            'form_index' => $formIndex,
                            'nilaiCRM' => $nilaiCRM,
                            'rep01' => $rep01,
                            'rep02' => $rep02,
                            'rep03' => $rep03,
                            'rep04' => $rep04,
                            'rep05' => $rep05,
                            'Resolusi' => $resolusi,
                            'suhuCRM' => $suhuCRM,
                        ]);
                    }
                }
            } else {
                for ($i = 1; $i <= 6; $i++) {
                    $nilaiCRM = $findValue('nilai_crm', $formIndex, [$i]) ?? $findValue('nilaiCRM', $formIndex, [$i]);
                    $rep1 = $findValue('pembacaan', $formIndex, [$i, 1]);
                    $rep2 = $findValue('pembacaan', $formIndex, [$i, 2]);
                    $rep3 = $findValue('pembacaan', $formIndex, [$i, 3]);
                    $rep4 = $findValue('pembacaan', $formIndex, [$i, 4]);
                    $rep5 = $findValue('pembacaan', $formIndex, [$i, 5]);
                    $resolusi = $findValue('resolusi', $formIndex, [$i]);
                    $suhuCRM = $findValue('suhu_crm', $formIndex, [$i]) ?? $findValue('suhuCRM', $formIndex, [$i]);

                    $hasData = !empty($nilaiCRM) || !empty($rep1) || !empty($rep2) || !empty($rep3) || !empty($rep4) || !empty($rep5) || !empty($resolusi) || !empty($suhuCRM);

                    if ($hasData) {
                        DetailConductivityMeter::create([
                            'calibration_id' => $calibration->id,
                            'head_conductivity_meter_id' => $head->id,
                            'head_condictivity_meter_id' => $head->id,
                            'form_index' => $formIndex,
                            'nilaiCRM' => $nilaiCRM,
                            'rep01' => $rep1,
                            'rep02' => $rep2,
                            'rep03' => $rep3,
                            'rep04' => $rep4,
                            'rep05' => $rep5,
                            'Resolusi' => $resolusi,
                            'suhuCRM' => $suhuCRM,
                        ]);
                    }
                }
            }
        }

        HeadConductivityMeter::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();

        DetailConductivityMeter::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();

        $updateData = [
            'jumlah_form' => $jumlahForm,
            'alat_standar' => $lastStandardValue,
            'calibration_method' => $lastCalibrationMethod,
        ];
        
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $calibration->namaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
        }
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
        }
        if ($request->filled('ttd_dikalibrasi')) {
            $updateData['calibrated_by'] = $request->ttd_dikalibrasi;
        }
        if ($request->filled('ttd_diperiksa')) {
            $updateData['verified_by'] = $request->ttd_diperiksa;
        }
        if ($request->filled('RT_condition1')) {
            $updateData['temperature'] = $request->RT_condition1;
        }
        if ($request->filled('RH_condition1')) {
            $updateData['humidity'] = $request->RH_condition1;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
        }

        \Log::info('🎉 updateConductivityMeter COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateConductivityMeter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}


private function storeCoatingThickness($request, $calibration, $certificateId, $tabId = null)
{
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('🚀 START storeCoatingThickness', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR: Coating Film Standar + No Seri yang dipilih (CHECKBOX - bisa multi)
        // ==================================================================
        // Item pertama: selalu Coating Film Standar
        $alatStandar = ['Coating Film Standar'];

        // Ambil checkbox yang dipilih (no_seri_pilihan[] - bisa lebih dari satu)
        $selectedCheckboxes = $this->getRequestValue($request, 'no_seri_pilihan', $tabId);
        
        // Handle jika hanya 1 checkbox atau multiple (array)
        if (!is_array($selectedCheckboxes)) {
            $selectedCheckboxes = $selectedCheckboxes ? [$selectedCheckboxes] : [];
        }
        
        \Log::info('📋 Selected checkboxes:', [
            'checkboxes' => $selectedCheckboxes,
            'tab_id' => $tabId
        ]);
        
        if (empty($selectedCheckboxes)) {
            throw new \Exception('Pilih minimal satu No Seri (Input Manual, T99022255-1 (D.013B), atau FJ202719 (D.013C))!');
        }
        
        // Proses setiap checkbox yang dipilih
        foreach ($selectedCheckboxes as $checkboxValue) {
            if ($checkboxValue === 'manual') {
                // Input manual: ambil dari text input no_seri_manual
                $manualValue = $this->getRequestValue($request, 'no_seri_manual', $tabId);
                if (empty($manualValue)) {
                    throw new \Exception('Silakan isi No Seri manual terlebih dahulu!');
                }
                $alatStandar[] = 'No. Seri ' . trim($manualValue);
            } else {
                // Nilai preset: T99022255-1 (D.013B) atau FJ202719 (D.013C)
                $alatStandar[] = $checkboxValue;
            }
        }
        
        // Gabungkan dengan koma
        $finalStandard = implode(', ', $alatStandar);
        
        \Log::info('🔧 Final standard value (saved to DB):', [
            'standard' => $finalStandard,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. CALIBRATION METHOD
        // ==================================================================
        $calibrationMethod = $this->getRequestValue($request, 'calibration_method', $tabId);
        if (empty($calibrationMethod)) {
            $calibrationMethod = 'PAS-IK1102-46';
        }

        // ==================================================================
        // 3. CEK APAKAH HEAD SUDAH ADA (UNTUK UPDATE) - TANPA form_index
        // ==================================================================
        $head = HeadCoatingThickness::where('calibration_id', $calibration->id)->first();
        
        $satuanUnit = $this->getRequestValue($request, 'satuan_unit', $tabId);
        
        if ($head) {
            // Update head yang sudah ada
            $head->update([
                'standard' => $finalStandard,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
                'certificate_id' => $certificateId,
            ]);
            \Log::info('✅ HeadCoatingThickness updated:', [
                'head_id' => $head->id,
                'standard' => $head->standard,
                'tab_id' => $tabId
            ]);
        } else {
            // Buat head baru
            $head = HeadCoatingThickness::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $finalStandard,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
            ]);
            \Log::info('✅ HeadCoatingThickness created:', [
                'head_id' => $head->id,
                'standard' => $head->standard,
                'tab_id' => $tabId
            ]);
        }

        // ==================================================================
        // 4. HAPUS DETAIL LAMA JIKA ADA (UNTUK UPDATE) - TANPA form_index
        // ==================================================================
        $existingDetails = DetailCoatingThickness::where('calibration_id', $calibration->id)->count();
        if ($existingDetails > 0) {
            DetailCoatingThickness::where('calibration_id', $calibration->id)->delete();
            \Log::info("🔄 Deleted {$existingDetails} old detail records for tab {$tabId}");
        }

        // ==================================================================
        // 5. SIMPAN DETAIL COATING THICKNESS - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving detailCoatingThickness data...');
        $detailCount = 0;

        $jumlah_baris = 12;
        
        for ($row = 1; $row <= $jumlah_baris; $row++) {
            // Ambil data dengan getRequestValue
            $titikUkur = $this->getRequestValue($request, "nominal_{$row}", $tabId);
            
            $hasData = false;
            
            if ($titikUkur !== null && $titikUkur !== '') {
                $hasData = true;
            } else {
                for ($col = 1; $col <= 5; $col++) {
                    $value = $this->getRequestValue($request, "pembacaan_{$row}_{$col}", $tabId);
                    if (!empty($value)) {
                        $hasData = true;
                        break;
                    }
                }
                
                if (!$hasData) {
                    $resolusi = $this->getRequestValue($request, "resolusi_{$row}", $tabId);
                    if (!empty($resolusi)) {
                        $hasData = true;
                    }
                }
            }
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_coating_thickness_id' => $head->id,
                    'titikUkur' => $titikUkur,
                    'rep01' => $this->getRequestValue($request, "pembacaan_{$row}_1", $tabId),
                    'rep02' => $this->getRequestValue($request, "pembacaan_{$row}_2", $tabId),
                    'rep03' => $this->getRequestValue($request, "pembacaan_{$row}_3", $tabId),
                    'rep04' => $this->getRequestValue($request, "pembacaan_{$row}_4", $tabId),
                    'rep05' => $this->getRequestValue($request, "pembacaan_{$row}_5", $tabId),
                    'resolusi' => $this->getRequestValue($request, "resolusi_{$row}", $tabId),
                ];

                DetailCoatingThickness::create($detailData);
                $detailCount++;
                
                \Log::debug("📝 Saved Coating Thickness row {$row} for tab {$tabId}", [
                    'titikUkur' => $titikUkur,
                    'pembacaan_1' => $this->getRequestValue($request, "pembacaan_{$row}_1", $tabId),
                ]);
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detailCoatingThickness records for tab {$tabId}");

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (TTD) - DENGAN DUKUNGAN _tab
        // ==================================================================
        $updateData = [];
        
        // Calibrated by
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibratedBy'] = $calibratedBy;
        } else {
            $updateData['calibratedBy'] = '-';
            \Log::warning('⚠️ calibrated_by kosong, set calibratedBy = "-" for tab ' . $tabId);
        }
        
        // Verified by
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verifiedBy'] = $verifiedBy;
        } else {
            $updateData['verifiedBy'] = '-';
            \Log::warning('⚠️ verified_by kosong, set verifiedBy = "-" for tab ' . $tabId);
        }
        
        // Nama kalibrator
        $namaKalibrator = $this->getRequestValue($request, 'nama_kalibrator', $tabId);
        if ($namaKalibrator) {
            $updateData['calibrator_name'] = $namaKalibrator;
        }
        
        // Nama pemeriksa
        $namaPemeriksa = $this->getRequestValue($request, 'nama_pemeriksa', $tabId);
        if ($namaPemeriksa) {
            $updateData['verifier_name'] = $namaPemeriksa;
        }
        
        // Uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
        }
        
        // Conclusion
        $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
        if ($conclusion) {
            $updateData['keterangan'] = $conclusion;
        }
        
        // Alat standar
        if (!empty($finalStandard)) {
            $updateData['alat_standar'] = $finalStandard;
        }
        
        // Calibration method
        if ($calibrationMethod) {
            $updateData['calibration_method'] = $calibrationMethod;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data for tab ' . $tabId, $updateData);
        }

        // ==================================================================
        // 7. UPDATE JUMLAH FORM DI CALIBRATION
        // ==================================================================
        $totalForms = $calibration->jumlah_form ?? 1;
        if ($tabId > $totalForms) {
            $calibration->update(['jumlah_form' => $tabId]);
            \Log::info("✅ Updated jumlah_form to {$tabId}");
        }

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailCoatingThickness::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Coating Thickness):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'tab_id' => $tabId,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'standard' => $finalStandard,
            'calibratedBy' => $calibration->calibratedBy ?? null,
            'verifiedBy' => $calibration->verifiedBy ?? null,
        ]);

        \Log::info('🎉 storeCoatingThickness COMPLETED for tab ' . $tabId);
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeCoatingThickness:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback jika terjadi error
        if (isset($head) && $head->id) {
            try {
                DetailCoatingThickness::where('calibration_id', $calibration->id)->delete();
                $head->delete();
                \Log::info('🔄 Rollback completed for tab ' . $tabId);
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Coating Thickness: " . $e->getMessage());
    }
}

private function updateCoatingThickness($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateCoatingThickness');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headCoatingThickness;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. AMBIL ATAU BUAT HEAD COATING THICKNESS
        // ==================================================================
        $head = HeadCoatingThickness::where('calibration_id', $calibration->id)->first();
        
        // ==================================================================
        // 2. PROSES ALAT STANDAR: Coating Film Standar + No Seri yang dipilih (CHECKBOX - bisa multi)
        // ==================================================================
        // Item pertama: selalu Coating Film Standar
        $alatStandar = ['Coating Film Standar'];
        
        // Ambil checkbox yang dipilih (no_seri_pilihan[] - bisa lebih dari satu)
        $selectedCheckboxes = $request->input('no_seri_pilihan', []);
        
        // Handle jika hanya 1 checkbox atau multiple (array)
        if (!is_array($selectedCheckboxes)) {
            $selectedCheckboxes = $selectedCheckboxes ? [$selectedCheckboxes] : [];
        }
        
        \Log::info('📋 Selected checkboxes (update):', [
            'checkboxes' => $selectedCheckboxes,
            'calibration_id' => $calibration->id
        ]);
        
        // Proses setiap checkbox yang dipilih
        $hasManualWithValue = false;
        
        foreach ($selectedCheckboxes as $checkboxValue) {
            if ($checkboxValue === 'manual') {
                // Input manual: ambil dari text input no_seri_manual
                $manualValue = $request->input('no_seri_manual', '');
                if (!empty($manualValue)) {
                    $alatStandar[] = 'No. Seri ' . trim($manualValue);
                    $hasManualWithValue = true;
                } else {
                    // Jika checkbox manual dicentang tapi tidak diisi, skip atau log warning
                    \Log::warning('⚠️ Checkbox manual dicentang tapi no_seri_manual kosong', [
                        'calibration_id' => $calibration->id
                    ]);
                }
            } else {
                // Nilai preset: T99022255-1 (D.013B) atau FJ202719 (D.013C)
                $alatStandar[] = $checkboxValue;
            }
        }
        
        // Gabungkan dengan koma
        $finalStandard = implode(', ', $alatStandar);
        
        \Log::info('🔧 Final standard value (saved to DB):', [
            'standard' => $finalStandard,
            'calibration_id' => $calibration->id
        ]);
        
        // ==================================================================
        // 3. UPDATE ATAU BUAT HEAD COATING THICKNESS
        // ==================================================================
        $headData = [
            'standard' => $finalStandard,
            'calibrationMethod' => $request->input('calibration_method', 'PAS-IK1102-46'),
            'satuan_unit' => $request->input('satuan_unit'),
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadCoatingThickness updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'standard' => $head->standard
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadCoatingThickness::create($headData);
            \Log::info('➕ HeadCoatingThickness created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null,
                'standard' => $head->standard
            ]);
        }
        
        // ==================================================================
        // 4. UPDATE DETAIL COATING THICKNESS
        // ==================================================================
        \Log::info('📊 Updating detailCoatingThickness data...');
        
        // Hapus detail lama
        DetailCoatingThickness::where('calibration_id', $calibration->id)->delete();
        \Log::info('🔄 Deleted old detail records');
        
        // Simpan detail baru
        $detailCount = 0;
        $jumlah_baris = 12;
        
        for ($row = 1; $row <= $jumlah_baris; $row++) {
            // Ambil data dengan format _tab jika ada, atau langsung
            $titikUkur = $request->input("nominal_{$row}") ?? $request->input("detail.{$row}.titikUkur");
            
            $hasData = false;
            
            if ($titikUkur !== null && $titikUkur !== '') {
                $hasData = true;
            } else {
                for ($col = 1; $col <= 5; $col++) {
                    $value = $request->input("pembacaan_{$row}_{$col}") ?? $request->input("detail.{$row}.rep0{$col}");
                    if (!empty($value)) {
                        $hasData = true;
                        break;
                    }
                }
                
                if (!$hasData) {
                    $resolusi = $request->input("resolusi_{$row}") ?? $request->input("detail.{$row}.resolusi");
                    if (!empty($resolusi)) {
                        $hasData = true;
                    }
                }
            }
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_coating_thickness_id' => $head->id,
                    'titikUkur' => $titikUkur,
                    'rep01' => $request->input("pembacaan_{$row}_1") ?? $request->input("detail.{$row}.rep01"),
                    'rep02' => $request->input("pembacaan_{$row}_2") ?? $request->input("detail.{$row}.rep02"),
                    'rep03' => $request->input("pembacaan_{$row}_3") ?? $request->input("detail.{$row}.rep03"),
                    'rep04' => $request->input("pembacaan_{$row}_4") ?? $request->input("detail.{$row}.rep04"),
                    'rep05' => $request->input("pembacaan_{$row}_5") ?? $request->input("detail.{$row}.rep05"),
                    'resolusi' => $request->input("resolusi_{$row}") ?? $request->input("detail.{$row}.resolusi"),
                ];

                DetailCoatingThickness::create($detailData);
                $detailCount++;
                
                \Log::debug("📝 Saved Coating Thickness row {$row}", ['titikUkur' => $titikUkur]);
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detailCoatingThickness records");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Update alat_standar
        if (!empty($finalStandard)) {
            $updateData['alat_standar'] = $finalStandard;
        }
        
        // Update calibration_method
        $calibrationMethod = $request->input('calibration_method', 'PAS-IK1102-46');
        if ($calibrationMethod) {
            $updateData['calibration_method'] = $calibrationMethod;
        }
        
        // Update calibratedBy dari input calibrated_by
        if ($request->filled('calibratedBy')) {
            $updateData['calibratedBy'] = $request->calibratedBy;
        } elseif ($request->filled('calibrated_by')) {
            $updateData['calibratedBy'] = $request->calibrated_by;
        } else {
            $updateData['calibratedBy'] = '-';
        }
        
        // Update verifiedBy dari input verified_by
        if ($request->filled('verifiedBy')) {
            $updateData['verifiedBy'] = $request->verifiedBy;
        } elseif ($request->filled('verified_by')) {
            $updateData['verifiedBy'] = $request->verified_by;
        } else {
            $updateData['verifiedBy'] = '-';
        }
        
        // Field tambahan jika ada
        if ($request->filled('nama_kalibrator')) {
            $updateData['calibrator_name'] = $request->nama_kalibrator;
        }
        
        if ($request->filled('nama_pemeriksa')) {
            $updateData['verifier_name'] = $request->nama_pemeriksa;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
        }
        
        if ($request->filled('conclusion')) {
            $updateData['keterangan'] = $request->conclusion;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', array_keys($updateData));
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headCoatingThickness;
        $savedDetailCount = DetailCoatingThickness::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Coating Thickness):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'standard' => $finalStandard,
            'selected_checkboxes' => $selectedCheckboxes,
            'calibratedBy' => $calibration->calibratedBy,
            'verifiedBy' => $calibration->verifiedBy,
        ]);

        \Log::info('🎉 updateCoatingThickness COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateCoatingThickness:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Coating Thickness: " . $e->getMessage());
    }
}

private function storeDurometer($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('🚀 ===== START storeDurometer =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeDurometer called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar for Durometer:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. SIMPAN KE HEAD DUROMETER
        // ==================================================================
        $head = HeadDurometer::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-56',
            'form_index' => 1,
            'satuan' => $request->satuan,
        ]);
        
        \Log::info('✅ HeadDurometer saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 3. SIMPAN DETAIL DUROMETER (10 TITIK UKUR) - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving DetailDurometer data (10 titik ukur)...');
        $detailCount = 0;
        
        for ($row = 1; $row <= 10; $row++) {
            // Ambil titik ukur dengan berbagai kemungkinan format
            $titikUkur = $this->getRequestValue($request, "titikUkur_{$row}", $tabId);
            if (!$titikUkur) {
                $titikUkur = $this->getRequestValue($request, "titikUkur", $tabId);
                if (is_array($titikUkur)) {
                    $titikUkur = $titikUkur[$row - 1] ?? null;
                }
            }
            if (!$titikUkur) {
                $titikUkur = $this->getRequestValue($request, "titik_ukur_{$row}", $tabId);
            }
            
            // Ambil data pembacaan x1, x2, x3
            $x1 = $this->getRequestValue($request, "x1_{$row}", $tabId);
            $x2 = $this->getRequestValue($request, "x2_{$row}", $tabId);
            $x3 = $this->getRequestValue($request, "x3_{$row}", $tabId);
            
            // Jika tidak ditemukan, coba format array
            if (!$x1) {
                $x1Array = $this->getRequestValue($request, "x1", $tabId);
                if (is_array($x1Array)) {
                    $x1 = $x1Array[$row - 1] ?? null;
                }
            }
            if (!$x2) {
                $x2Array = $this->getRequestValue($request, "x2", $tabId);
                if (is_array($x2Array)) {
                    $x2 = $x2Array[$row - 1] ?? null;
                }
            }
            if (!$x3) {
                $x3Array = $this->getRequestValue($request, "x3", $tabId);
                if (is_array($x3Array)) {
                    $x3 = $x3Array[$row - 1] ?? null;
                }
            }
            
            // Cek apakah ada data untuk titik ukur ini
            $hasData = !empty($titikUkur) || !empty($x1) || !empty($x2) || !empty($x3);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'form_index' => 1,
                    'titikUkur' => $titikUkur,
                    'x1' => $x1,
                    'x2' => $x2,
                    'x3' => $x3,
                ];
                
                \Log::debug("💾 Saving DetailDurometer row {$row}:", [
                    'titikUkur' => $detailData['titikUkur'],
                    'x1' => $detailData['x1'],
                    'x2' => $detailData['x2'],
                    'x3' => $detailData['x3']
                ]);
                
                DetailDurometer::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping row {$row} - no data found");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailDurometer records");
        
        // ==================================================================
        // 4. SIMPAN ADD DUROMETER (DATA REPEATABILITY) - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving AddDurometer data (repeatability)...');
        
        $addData = [
            'calibration_id' => $calibration->id,
            'form_index' => 1,
        ];
        
        // Ambil 10 nilai repeatability (5 baris atas + 5 baris bawah)
        for ($row = 1; $row <= 2; $row++) {
            for ($col = 1; $col <= 5; $col++) {
                $value = $this->getRequestValue($request, "repeatability_{$row}_{$col}", $tabId);
                if (!$value) {
                    $value = $this->getRequestValue($request, "repeatability", $tabId);
                    if (is_array($value)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $value = $value[$index] ?? null;
                    }
                }
                if (!$value) {
                    $value = $this->getRequestValue($request, "rep_{$row}_{$col}", $tabId);
                }
                
                $repKey = "rep" . str_pad((($row - 1) * 5 + $col), 2, '0', STR_PAD_LEFT);
                $addData[$repKey] = $value;
            }
        }
        
        // Cek apakah ada data untuk disimpan
        $hasAddData = false;
        foreach ($addData as $key => $value) {
            if ($key !== 'calibration_id' && $key !== 'form_index' && $value !== null && $value !== '') {
                $hasAddData = true;
                break;
            }
        }
        
        if ($hasAddData) {
            $addRecord = AddDurometer::create($addData);
            \Log::info('✅ AddDurometer saved:', ['add_id' => $addRecord->id]);
        } else {
            \Log::info('⚠️ No AddDurometer data to save');
        }
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TTD DAN NAMA (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $conclusion = $this->getRequestValue($request, 'conclusion', $tabId);
            $updateData['keterangan'] = $conclusion ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailDurometer::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddDurometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Durometer):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);
        
        \Log::info('🎉 storeDurometer COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeDurometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal menyimpan data Durometer: " . $e->getMessage());
    }
}

private function updateDurometer($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateDurometer');
        \Log::info('📝 Updating Durometer data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headDurometer;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR DARI CHECKBOX
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Durometer:', ['alat_standar' => $alatStandar]);
        
        // ==================================================================
        // 2. UPDATE ATAU CREATE HEAD DUROMETER
        // ==================================================================
        $head = HeadDurometer::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-56',
            'satuan' => $request->satuan,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadDurometer updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadDurometer::create($headData);
            \Log::info('➕ HeadDurometer created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL DUROMETER (TITIK UKUR) - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating DetailDurometer data...');
        
        // Hapus data lama terlebih dahulu
        $deletedDetails = DetailDurometer::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old DetailDurometer records");
        
        // Proses 10 titik ukur (sesuai form HTML) - LANGSUNG TANPA FORMAT
        $detailCount = 0;
        for ($i = 1; $i <= 10; $i++) {
            // Ambil titik ukur dari input
            $titikUkur = $request->input("titikUkur_{$i}");
            
            // Ambil data pembacaan
            $x1 = $request->input("x1_{$i}");
            $x2 = $request->input("x2_{$i}");
            $x3 = $request->input("x3_{$i}");
            
            // Cek apakah ada data untuk titik ukur ini
            $hasData = !empty($titikUkur) || !empty($x1) || !empty($x2) || !empty($x3);
            
            // HANYA simpan jika ada data - LANGSUNG TANPA FORMAT
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,  // LANGSUNG, tanpa format
                    'x1' => $x1,                // LANGSUNG, tanpa format
                    'x2' => $x2,                // LANGSUNG, tanpa format
                    'x3' => $x3,                // LANGSUNG, tanpa format
                ];
                
                \Log::debug("💾 Saving DetailDurometer row {$i}:", [
                    'titikUkur' => $detailData['titikUkur'],
                    'x1' => $detailData['x1'],
                    'x2' => $detailData['x2'],
                    'x3' => $detailData['x3'],
                ]);
                
                DetailDurometer::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping row {$i} - no data found");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailDurometer records");
        
        // ==================================================================
        // 4. UPDATE ADD DUROMETER (DATA REPEATABILITY) - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating AddDurometer data (repeatability)...');
        
        $addData = [
            'calibration_id' => $calibration->id,
            
            // Ulangan 1-10 - ambil dari input - LANGSUNG TANPA FORMAT
            'rep01' => $request->input('repeatability_1_1'),
            'rep02' => $request->input('repeatability_1_2'),
            'rep03' => $request->input('repeatability_1_3'),
            'rep04' => $request->input('repeatability_1_4'),
            'rep05' => $request->input('repeatability_1_5'),
            'rep06' => $request->input('repeatability_2_1'),
            'rep07' => $request->input('repeatability_2_2'),
            'rep08' => $request->input('repeatability_2_3'),
            'rep09' => $request->input('repeatability_2_4'),
            'rep10' => $request->input('repeatability_2_5'),
        ];
        
        // Cek apakah ada data untuk disimpan
        $hasAddData = false;
        foreach ($addData as $key => $value) {
            if ($key !== 'calibration_id' && $value !== null && $value !== '') {
                $hasAddData = true;
                break;
            }
        }
        
        if ($hasAddData) {
            $existingAdd = AddDurometer::where('calibration_id', $calibration->id)->first();
            
            if ($existingAdd) {
                $existingAdd->update($addData);
                \Log::info('✅ AddDurometer updated:', ['add_id' => $existingAdd->id]);
            } else {
                $addRecord = AddDurometer::create($addData);
                \Log::info('✅ AddDurometer created:', ['add_id' => $addRecord->id]);
            }
        } else {
            \Log::info('⚠️ No AddDurometer data to save');
            AddDurometer::where('calibration_id', $calibration->id)->delete();
            \Log::info('🗑️ Deleted AddDurometer records (no data)');
        }
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Ambil nama dari input calibrated_by dan verified_by
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headDurometer;
        $savedDetailCount = DetailDurometer::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddDurometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Durometer):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'alat_standar' => $alatStandarString,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);
        
        \Log::info('🎉 updateDurometer COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateDurometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Durometer: " . $e->getMessage());
    }
}

private function storeMikropipetDispenset($request, $calibration, $certificateId, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeMikropipetDispenset =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
            }
            
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
            $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
            $possibleKeys[] = "{$baseKey}{$suffix}";
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
            $possibleKeys[] = $baseKey;
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai satuan
         */
        $findSatuanValue = function($baseKey, $formIndex, $posisi = null) use ($request, $findValue) {
            if ($posisi) {
                return $findValue($baseKey, $formIndex, [$posisi]);
            }
            return $findValue($baseKey, $formIndex, []);
        };
        
        // ==================================================================
        // 3. 🔥 AMBIL SEMUA DATA (ALAT STANDAR, STOPWATCH, TERMOMETER)
        //    DAN GABUNGKAN MENJADI SATU STRING DI COLUMN standard
        // ==================================================================
        $allStandardValues = [];
        $allMetode = [];
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $standardParts = [];
            
            // ==========================================================
            // 🔥 1. AMBIL ALAT STANDAR - format: form_{formIndex}_alat_standar
            // ==========================================================
            $standarKey = "form_{$formIndex}_alat_standar";
            $alatStandar = $request->input($standarKey);
            
            // 🔥 FIX: Jika null, coba format lain
            if ($alatStandar === null) {
                $alatStandar = $request->input("alat_standar_{$formIndex}");
            }
            
            // 🔥 FIX: Jika masih null, coba cari dengan findValue
            if ($alatStandar === null) {
                $alatStandar = $findValue('alat_standar', $formIndex);
            }
            
            \Log::info("📋 Raw Alat Standar Form {$formIndex}:", [
                'key' => $standarKey,
                'values' => $alatStandar,
                'is_array' => is_array($alatStandar),
                'type' => gettype($alatStandar)
            ]);
            
            // 🔥 FIX: Proses dengan aman
            if (is_array($alatStandar) && !empty($alatStandar)) {
                // Filter nilai kosong
                $filtered = array_filter($alatStandar, function($val) {
                    return !empty($val) && trim($val) !== '';
                });
                if (!empty($filtered)) {
                    $standardParts = array_merge($standardParts, $filtered);
                }
            } elseif (is_string($alatStandar) && !empty($alatStandar)) {
                // Jika string, tambahkan langsung
                $standardParts[] = $alatStandar;
            }
            
            // ==========================================================
            // 🔥 2. AMBIL STOPWATCH
            // ==========================================================
            $stopwatch = $request->input("stopwatch_{$formIndex}");
            if (empty($stopwatch)) {
                $stopwatch = $findValue('stopwatch', $formIndex);
            }
            
            \Log::info("⏱️ Stopwatch Form {$formIndex}:", [
                'value' => $stopwatch,
                'type' => gettype($stopwatch)
            ]);
            
            if (is_string($stopwatch) && !empty($stopwatch)) {
                $standardParts[] = $stopwatch;
            } elseif (is_array($stopwatch) && !empty($stopwatch)) {
                $standardParts = array_merge($standardParts, $stopwatch);
            }
            
            // ==========================================================
            // 🔥 3. AMBIL TERMOMETER
            // ==========================================================
            $termometer = $request->input("termometer_{$formIndex}");
            if (empty($termometer)) {
                $termometer = $findValue('termometer', $formIndex);
            }
            
            \Log::info("🌡️ Termometer Form {$formIndex}:", [
                'value' => $termometer,
                'type' => gettype($termometer)
            ]);
            
            if (is_string($termometer) && !empty($termometer)) {
                $standardParts[] = $termometer;
            } elseif (is_array($termometer) && !empty($termometer)) {
                $standardParts = array_merge($standardParts, $termometer);
            }
            
            // ==========================================================
            // 🔥 4. AMBIL METODE KALIBRASI
            // ==========================================================
            $metode = $request->input("metode_kalibrasi_{$formIndex}");
            if (empty($metode)) {
                $metode = $findValue('metode_kalibrasi', $formIndex);
            }
            
            // 🔥 FIX: Jika metode adalah array, gabungkan
            if (is_array($metode)) {
                $metode = implode(', ', array_filter($metode));
            }
            $allMetode[$formIndex] = $metode ?? 'PAS-IK102-39 (Volumetrik Piston)';
            
            // ==========================================================
            // 🔥 5. GABUNGKAN SEMUA MENJADI SATU STRING
            // ==========================================================
            // Filter nilai kosong
            $standardParts = array_filter($standardParts, function($val) {
                return !empty($val) && trim($val) !== '';
            });
            
            // 🔥 FIX: Konversi semua ke string
            $standardParts = array_map('strval', $standardParts);
            
            // 🔥 FIX: Hapus duplikat
            $standardParts = array_unique($standardParts);
            
            // 🔥 FIX: Gabungkan dengan koma
            $allStandardValues[$formIndex] = implode(', ', $standardParts);
            
            \Log::info("📋 Standard Value Form {$formIndex} (Gabungan):", [
                'parts' => $standardParts,
                'result' => $allStandardValues[$formIndex]
            ]);
        }
        
        // ==================================================================
        // 4. LOOP UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex}");
            \Log::info("=========================================");
            
            // ==========================================================
            // AMBIL SATUAN UNTUK MASING-MASING POSISI
            // ==========================================================
            $satuanKiriAtas = $findSatuanValue('satuan_alat_ukur_kiri', $formIndex);
            $satuanKananAtas = $findSatuanValue('satuan_alat_ukur_kanan', $formIndex);
            $satuanKiriBawah = $findSatuanValue('satuan_alat_ukur_bawah_kiri', $formIndex);
            $satuanKananBawah = $findSatuanValue('satuan_alat_ukur_bawah_kanan', $formIndex);
            
            \Log::info("📝 Satuan values for form {$formIndex}", [
                'satuan_kiri_atas' => $satuanKiriAtas,
                'satuan_kanan_atas' => $satuanKananAtas,
                'satuan_kiri_bawah' => $satuanKiriBawah,
                'satuan_kanan_bawah' => $satuanKananBawah
            ]);
            
            // ==========================================================
            // 🔥 AMBIL STANDARD PER FORM (SUDAH JADI STRING)
            // ==========================================================
            $formStandard = $allStandardValues[$formIndex] ?? '';
            $formMetode = $allMetode[$formIndex] ?? 'PAS-IK102-39 (Volumetrik Piston)';
            
            // 🔥 FIX: Pastikan $formStandard adalah string
            if (is_array($formStandard)) {
                $formStandard = implode(', ', array_filter($formStandard));
            }
            $formStandard = (string) $formStandard;
            
            \Log::info("📝 Saving Head for form {$formIndex}:", [
                'standard' => $formStandard,
                'metode' => $formMetode
            ]);
            
            // ==========================================================
            // 🔥 SIMPAN HEAD MIKROPIPET DISPENSET
            // ==========================================================
            HeadMikropipetDispenset::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard' => $formStandard,  // 🔥 SUDAH PASTI STRING
                    'calibrationMethod' => $formMetode,
                    'certificate_id' => $certificateId,
                    'satuan_alat_ukur_kiri' => $satuanKiriAtas,
                    'satuan_alat_ukur_kanan' => $satuanKananAtas,
                    'satuan_alat_ukur_bawah_kiri' => $satuanKiriBawah,
                    'satuan_alat_ukur_bawah_kanan' => $satuanKananBawah,
                    'satuan_alat_ukur_tambahan_kiri' => $findSatuanValue('satuan_alat_ukur_tambahan_kiri', $formIndex),
                ]
            );
            
            // ==========================================================
            // SIMPAN DETAIL UNTUK MASING-MASING POSISI
            // ==========================================================
            $this->saveMikropipetDetailWithFinder($findValue, $calibration->id, $formIndex, 'kiri', 'atas');
            $this->saveMikropipetDetailWithFinder($findValue, $calibration->id, $formIndex, 'kanan', 'atas');
            $this->saveMikropipetDetailWithFinder($findValue, $calibration->id, $formIndex, 'kiri', 'bawah');
            $this->saveMikropipetDetailWithFinder($findValue, $calibration->id, $formIndex, 'kanan', 'bawah');
            $this->saveMikropipetDetailWithFinder($findValue, $calibration->id, $formIndex, 'kiri', 'tambahan');
        }
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $totalHeadRecords = HeadMikropipetDispenset::where('calibration_id', $calibration->id)->count();
        $totalDetailRecords = DetailMikropipetDispenset::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Mikropipet/Dispenset):', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'head_records' => $totalHeadRecords,
            'detail_records' => $totalDetailRecords,
            'certificate_id' => $certificateId,
            'standard_gabungan' => $allStandardValues[1] ?? '',
        ]);
        
        \Log::info('🎉 storeMikropipetDispenset COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeMikropipetDispenset:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback
        try {
            DetailMikropipetDispenset::where('calibration_id', $calibration->id)->delete();
            HeadMikropipetDispenset::where('calibration_id', $calibration->id)->delete();
        } catch (\Exception $rollbackError) {
            \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
        }
        
        throw new \Exception("Gagal menyimpan data Mikropipet/Dispenset: " . $e->getMessage());
    }
}
/**
 * Helper method untuk menyimpan satu record DetailMikropipetDispenset DENGAN FINDER
 */
private function saveMikropipetDetailWithFinder($findValue, $calibrationId, $formIndex, $posisi, $bagian)
{
    $posisiPrefix = ($posisi === 'kiri') ? 'kiri' : 'kanan';
    $isBawah = ($bagian === 'bawah');
    $isTambahan = ($bagian === 'tambahan');
    
    // Cari nilai titik ukur (nominal)
    if ($isTambahan) {
        $titikUkur = $findValue("nominal_tambahan_{$posisiPrefix}", $formIndex);
        if (empty($titikUkur)) {
            $titikUkur = $findValue("satuan_alat_ukur_tambahan_{$posisiPrefix}", $formIndex);
        }
    } elseif ($isBawah) {
        $titikUkur = $findValue("nominal_{$posisiPrefix}_bawah", $formIndex);
        if (empty($titikUkur)) {
            $titikUkur = $findValue("nominal_bawah_{$posisiPrefix}", $formIndex);
        }
    } else {
        $titikUkur = $findValue("nominal_{$posisiPrefix}", $formIndex);
    }
    
    if (empty($titikUkur)) {
        $titikUkur = $findValue("titik_ukur_{$posisiPrefix}", $formIndex);
    }
    
    \Log::debug("🔍 Checking data for form {$formIndex}, {$posisi}-{$bagian}", [
        'titikUkur' => $titikUkur
    ]);
    
    // Cek apakah ada data (titik ukur tidak kosong)
    $hasData = !empty($titikUkur);
    
    // Cek nilai m0 sampai m11
    for ($i = 0; $i <= 11; $i++) {
        if ($isTambahan) {
            $value = $findValue("m{$i}_tambahan_{$posisiPrefix}", $formIndex);
        } elseif ($isBawah) {
            $value = $findValue("m{$i}_{$posisiPrefix}_bawah", $formIndex);
            if (empty($value)) {
                $value = $findValue("m{$i}_bawah_{$posisiPrefix}", $formIndex);
            }
        } else {
            $value = $findValue("m{$i}_{$posisiPrefix}", $formIndex);
        }
        
        if (!empty($value)) {
            $hasData = true;
            break;
        }
    }
    
    // Cek parameter pendukung jika belum ada data
    if (!$hasData) {
        $paramKeys = [];
        if ($isTambahan) {
            $paramKeys = [
                "suhu_awal_tambahan_{$posisiPrefix}",
                "suhu_akhir_tambahan_{$posisiPrefix}",
                "kelembaban_awal_tambahan_{$posisiPrefix}",
                "kelembaban_akhir_tambahan_{$posisiPrefix}",
                "tekanan_awal_tambahan_{$posisiPrefix}",
                "tekanan_akhir_tambahan_{$posisiPrefix}",
                "suhu_air_awal_tambahan_{$posisiPrefix}",
                "suhu_air_akhir_tambahan_{$posisiPrefix}",
                "waktu_tambahan_{$posisiPrefix}"
            ];
        } elseif ($isBawah) {
            $paramKeys = [
                "suhu_awal_{$posisiPrefix}_bawah",
                "suhu_akhir_{$posisiPrefix}_bawah",
                "kelembaban_awal_{$posisiPrefix}_bawah",
                "kelembaban_akhir_{$posisiPrefix}_bawah",
                "tekanan_awal_{$posisiPrefix}_bawah",
                "tekanan_akhir_{$posisiPrefix}_bawah",
                "suhu_air_awal_{$posisiPrefix}_bawah",
                "suhu_air_akhir_{$posisiPrefix}_bawah",
                "waktu_{$posisiPrefix}_bawah"
            ];
        } else {
            $paramKeys = [
                "suhu_awal_{$posisiPrefix}",
                "suhu_akhir_{$posisiPrefix}",
                "kelembaban_awal_{$posisiPrefix}",
                "kelembaban_akhir_{$posisiPrefix}",
                "tekanan_awal_{$posisiPrefix}",
                "tekanan_akhir_{$posisiPrefix}",
                "suhu_air_awal_{$posisiPrefix}",
                "suhu_air_akhir_{$posisiPrefix}",
                "waktu_{$posisiPrefix}"
            ];
        }
        
        foreach ($paramKeys as $key) {
            $value = $findValue($key, $formIndex);
            if (!empty($value)) {
                $hasData = true;
                break;
            }
        }
    }
    
    if (!$hasData) {
        \Log::debug("⏭️ Skipping form {$formIndex} {$posisi}-{$bagian} - no data");
        return false;
    }
    
    // Persiapkan data untuk DetailMikropipetDispenset
    $detailData = [
        'calibration_id' => $calibrationId,
        'form_index' => $formIndex,
        'posisi' => $posisi,
        'bagian' => $bagian,
        'titikUkur' => $titikUkur,
    ];
    
    // Tambahkan nilai m0 sampai m11
    for ($i = 0; $i <= 11; $i++) {
        if ($isTambahan) {
            $value = $findValue("m{$i}_tambahan_{$posisiPrefix}", $formIndex);
        } elseif ($isBawah) {
            $value = $findValue("m{$i}_{$posisiPrefix}_bawah", $formIndex);
            if (empty($value)) {
                $value = $findValue("m{$i}_bawah_{$posisiPrefix}", $formIndex);
            }
        } else {
            $value = $findValue("m{$i}_{$posisiPrefix}", $formIndex);
        }
        
        $detailData["m{$i}"] = $value;
    }
    
    // Tambahkan parameter pendukung
    if ($isTambahan) {
        $detailData['TUdaraS'] = $findValue("suhu_awal_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['TUdaraE'] = $findValue("suhu_akhir_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['RHS'] = $findValue("kelembaban_awal_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['RHE'] = $findValue("kelembaban_akhir_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['PUdaraS'] = $findValue("tekanan_awal_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['PUdaraE'] = $findValue("tekanan_akhir_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['TAirS'] = $findValue("suhu_air_awal_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['TAirE'] = $findValue("suhu_air_akhir_tambahan_{$posisiPrefix}", $formIndex);
        $detailData['waktu'] = $findValue("waktu_tambahan_{$posisiPrefix}", $formIndex);
    } elseif ($isBawah) {
        $detailData['TUdaraS'] = $findValue("suhu_awal_{$posisiPrefix}_bawah", $formIndex);
        $detailData['TUdaraE'] = $findValue("suhu_akhir_{$posisiPrefix}_bawah", $formIndex);
        $detailData['RHS'] = $findValue("kelembaban_awal_{$posisiPrefix}_bawah", $formIndex);
        $detailData['RHE'] = $findValue("kelembaban_akhir_{$posisiPrefix}_bawah", $formIndex);
        $detailData['PUdaraS'] = $findValue("tekanan_awal_{$posisiPrefix}_bawah", $formIndex);
        $detailData['PUdaraE'] = $findValue("tekanan_akhir_{$posisiPrefix}_bawah", $formIndex);
        $detailData['TAirS'] = $findValue("suhu_air_awal_{$posisiPrefix}_bawah", $formIndex);
        $detailData['TAirE'] = $findValue("suhu_air_akhir_{$posisiPrefix}_bawah", $formIndex);
        $detailData['waktu'] = $findValue("waktu_{$posisiPrefix}_bawah", $formIndex);
    } else {
        $detailData['TUdaraS'] = $findValue("suhu_awal_{$posisiPrefix}", $formIndex);
        $detailData['TUdaraE'] = $findValue("suhu_akhir_{$posisiPrefix}", $formIndex);
        $detailData['RHS'] = $findValue("kelembaban_awal_{$posisiPrefix}", $formIndex);
        $detailData['RHE'] = $findValue("kelembaban_akhir_{$posisiPrefix}", $formIndex);
        $detailData['PUdaraS'] = $findValue("tekanan_awal_{$posisiPrefix}", $formIndex);
        $detailData['PUdaraE'] = $findValue("tekanan_akhir_{$posisiPrefix}", $formIndex);
        $detailData['TAirS'] = $findValue("suhu_air_awal_{$posisiPrefix}", $formIndex);
        $detailData['TAirE'] = $findValue("suhu_air_akhir_{$posisiPrefix}", $formIndex);
        $detailData['waktu'] = $findValue("waktu_{$posisiPrefix}", $formIndex);
    }
    
    \Log::debug("💾 Saving DetailMikropipetDispenset [form {$formIndex}, {$posisi}-{$bagian}]:", [
        'titikUkur' => $detailData['titikUkur'],
        'calibration_id' => $calibrationId,
        'form_index' => $formIndex,
        'm0' => $detailData['m0'] ?? null
    ]);
    
    DetailMikropipetDispenset::create($detailData);
    return true;
}



private function updateMikropipetDispenset($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateMikropipetDispenset');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request (prioritaskan dari hidden input namaAlat)
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headMikropipetDispenset;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        // Cek berbagai kemungkinan key untuk alat standar (bisa dari form 1 atau multiple form)
        $alatStandar = [];
        if ($request->has('alat_standar_1')) {
            $alatStandar = $request->input('alat_standar_1', []);
            if (is_string($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
        } elseif ($request->has('alat_standar')) {
            $alatStandar = $request->input('alat_standar', []);
            if (is_string($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Mikropipet/Dispenset:', ['alat_standar' => $alatStandar]);
        
        // ==================================================================
        // 2. AMBIL ATAU BUAT HEAD MIKROPIPET DISPENSET
        // ==================================================================
        $head = HeadMikropipetDispenset::where('calibration_id', $calibration->id)->first();
        
        // ==================================================================
        // 3. UPDATE ATAU BUAT HEAD MIKROPIPET DISPENSET
        // ==================================================================
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK102-39 (Volumetrik Piston)',
            'satuan_alat_ukur_kiri' => $request->input("satuan_alat_ukur_kiri_1"),
            'satuan_alat_ukur_kanan' => $request->input("satuan_alat_ukur_kanan_1"),
            'satuan_alat_ukur_bawah_kiri' => $request->input("satuan_alat_ukur_bawah_kiri_1"),
            'satuan_alat_ukur_bawah_kanan' => $request->input("satuan_alat_ukur_bawah_kanan_1"),
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadMikropipetDispenset updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadMikropipetDispenset::create($headData);
            \Log::info('➕ HeadMikropipetDispenset created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 4. UPDATE DETAIL MIKROPIPET DISPENSET (4 REKAMAN PER FORM)
        // ==================================================================
        \Log::info('📊 Updating DetailMikropipetDispenset data...');
        
        // Hapus detail lama
        $deletedEloquent = DetailMikropipetDispenset::where('calibration_id', $calibration->id)->delete();
        $deletedDB = \Illuminate\Support\Facades\DB::table('detail_mikropipet_dispensets')->where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ DELETE OLD DETAILS: Eloquent deleted {$deletedEloquent} rows, DB Builder deleted {$deletedDB} rows.");
        // Ambil jumlah form
        $jumlahForm = (int) ($request->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        $savedCount = 0;
        
        // Loop untuk setiap form
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Simpan 4 record berdasarkan posisi dan bagian untuk setiap form
            $positions = [
                ['posisi' => 'kiri', 'bagian' => 'atas'],
                ['posisi' => 'kanan', 'bagian' => 'atas'],
                ['posisi' => 'kiri', 'bagian' => 'bawah'],
                ['posisi' => 'kanan', 'bagian' => 'bawah'],
                ['posisi' => 'kiri', 'bagian' => 'tambahan'],
            ];
            
            foreach ($positions as $pos) {
                if ($this->updateMikropipetRecord($request, $calibration->id, $formIndex, $pos['posisi'], $pos['bagian'])) {
                    $savedCount++;
                }
            }
        }
        
        \Log::info("✅ Saved {$savedCount} DetailMikropipetDispenset records");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Data TTD dan nama dari calibration (ambil dari form 1)
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        } else {
            $updateData['calibrated_by'] = '-';
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        } else {
            $updateData['verified_by'] = '-';
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        $updateData['jumlah_form'] = $jumlahForm;
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', array_keys($updateData));
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headMikropipetDispenset;
        $totalDetailRecords = DetailMikropipetDispenset::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Mikropipet/Dispenset):', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $totalDetailRecords,
            'nama_alat' => $calibration->namaAlat,
            'alat_standar' => $alatStandarString,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);

        \Log::info('🎉 updateMikropipetDispenset COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateMikropipetDispenset:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Mikropipet/Dispenset: " . $e->getMessage());
    }
}
/**
 * Helper method untuk menyimpan satu record DetailMikropipetDispenset
 * dengan format name input yang sudah disesuaikan (suffix _formIndex)
 */
private function updateMikropipetRecord($request, $calibrationId, $formIndex, $posisi, $bagian)
{
    // Tentukan prefix berdasarkan posisi
    $posisiPrefix = ($posisi === 'kiri') ? 'kiri' : 'kanan';
    $isBawah = ($bagian === 'bawah');
    $isTambahan = ($bagian === 'tambahan');
    
    // Bangun key name untuk nominal
    $nominalKey = $isTambahan
        ? "nominal_tambahan_{$posisiPrefix}_{$formIndex}"
        : ($isBawah 
            ? "nominal_{$posisiPrefix}_bawah_{$formIndex}"
            : "nominal_{$posisiPrefix}_{$formIndex}");
    
    $titikUkur = $request->input($nominalKey);
    
    // Log untuk debugging
    \Log::debug("🔍 Checking data for form {$formIndex}, {$posisi}-{$bagian}", [
        'nominalKey' => $nominalKey,
        'titikUkur' => $titikUkur
    ]);
    
    // Check if any data exists for this position
    $hasData = !empty($titikUkur);
    
    // Check m0-m11 values
    for ($i = 0; $i <= 11; $i++) {
        $valueKey = $isTambahan
            ? "m{$i}_tambahan_{$posisiPrefix}_{$formIndex}"
            : ($isBawah
                ? "m{$i}_{$posisiPrefix}_bawah_{$formIndex}"
                : "m{$i}_{$posisiPrefix}_{$formIndex}");
        
        $value = $request->input($valueKey);
        if (!empty($value)) {
            $hasData = true;
            break;
        }
    }
    
    // Check parameter pendukung jika belum ada data
    if (!$hasData) {
        if ($isTambahan) {
            $paramKeys = [
                "suhu_awal_tambahan_{$posisiPrefix}_{$formIndex}",
                "suhu_akhir_tambahan_{$posisiPrefix}_{$formIndex}",
                "kelembaban_awal_tambahan_{$posisiPrefix}_{$formIndex}",
                "kelembaban_akhir_tambahan_{$posisiPrefix}_{$formIndex}",
                "tekanan_awal_tambahan_{$posisiPrefix}_{$formIndex}",
                "tekanan_akhir_tambahan_{$posisiPrefix}_{$formIndex}",
                "suhu_air_awal_tambahan_{$posisiPrefix}_{$formIndex}",
                "suhu_air_akhir_tambahan_{$posisiPrefix}_{$formIndex}",
                "waktu_tambahan_{$posisiPrefix}_{$formIndex}"
            ];
        } elseif ($isBawah) {
            $paramKeys = [
                "suhu_awal_{$posisiPrefix}_bawah_{$formIndex}",
                "suhu_akhir_{$posisiPrefix}_bawah_{$formIndex}",
                "kelembaban_awal_{$posisiPrefix}_bawah_{$formIndex}",
                "kelembaban_akhir_{$posisiPrefix}_bawah_{$formIndex}",
                "tekanan_awal_{$posisiPrefix}_bawah_{$formIndex}",
                "tekanan_akhir_{$posisiPrefix}_bawah_{$formIndex}",
                "suhu_air_awal_{$posisiPrefix}_bawah_{$formIndex}",
                "suhu_air_akhir_{$posisiPrefix}_bawah_{$formIndex}",
                "waktu_{$posisiPrefix}_bawah_{$formIndex}"
            ];
        } else {
            $paramKeys = [
                "suhu_awal_{$posisiPrefix}_{$formIndex}",
                "suhu_akhir_{$posisiPrefix}_{$formIndex}",
                "kelembaban_awal_{$posisiPrefix}_{$formIndex}",
                "kelembaban_akhir_{$posisiPrefix}_{$formIndex}",
                "tekanan_awal_{$posisiPrefix}_{$formIndex}",
                "tekanan_akhir_{$posisiPrefix}_{$formIndex}",
                "suhu_air_awal_{$posisiPrefix}_{$formIndex}",
                "suhu_air_akhir_{$posisiPrefix}_{$formIndex}",
                "waktu_{$posisiPrefix}_{$formIndex}"
            ];
        }
        
        foreach ($paramKeys as $key) {
            if ($request->filled($key)) {
                $hasData = true;
                break;
            }
        }
    }
    
    if (!$hasData) {
        \Log::debug("⏭️ Skipping form {$formIndex} {$posisi}-{$bagian} - no data");
        return false;
    }
    
    // Persiapkan data untuk DetailMikropipetDispenset
    $detailData = [
        'calibration_id' => $calibrationId,
        'form_index' => $formIndex,
        'posisi' => $posisi,
        'bagian' => $bagian,
        'titikUkur' => $titikUkur,
    ];
    
    // Tambahkan nilai m0 sampai m11
    for ($i = 0; $i <= 11; $i++) {
        $valueKey = $isTambahan
            ? "m{$i}_tambahan_{$posisiPrefix}_{$formIndex}"
            : ($isBawah
                ? "m{$i}_{$posisiPrefix}_bawah_{$formIndex}"
                : "m{$i}_{$posisiPrefix}_{$formIndex}");
        
        $detailData["m{$i}"] = $request->input($valueKey);
    }
    
    // Tambahkan parameter pendukung dengan mapping ke field database
    if ($isTambahan) {
        $detailData['TUdaraS'] = $request->input("suhu_awal_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['TUdaraE'] = $request->input("suhu_akhir_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['RHS'] = $request->input("kelembaban_awal_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['RHE'] = $request->input("kelembaban_akhir_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['PUdaraS'] = $request->input("tekanan_awal_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['PUdaraE'] = $request->input("tekanan_akhir_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['TAirS'] = $request->input("suhu_air_awal_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['TAirE'] = $request->input("suhu_air_akhir_tambahan_{$posisiPrefix}_{$formIndex}");
        $detailData['waktu'] = $request->input("waktu_tambahan_{$posisiPrefix}_{$formIndex}");
    } elseif ($isBawah) {
        $detailData['TUdaraS'] = $request->input("suhu_awal_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['TUdaraE'] = $request->input("suhu_akhir_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['RHS'] = $request->input("kelembaban_awal_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['RHE'] = $request->input("kelembaban_akhir_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['PUdaraS'] = $request->input("tekanan_awal_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['PUdaraE'] = $request->input("tekanan_akhir_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['TAirS'] = $request->input("suhu_air_awal_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['TAirE'] = $request->input("suhu_air_akhir_{$posisiPrefix}_bawah_{$formIndex}");
        $detailData['waktu'] = $request->input("waktu_{$posisiPrefix}_bawah_{$formIndex}");
    } else {
        $detailData['TUdaraS'] = $request->input("suhu_awal_{$posisiPrefix}_{$formIndex}");
        $detailData['TUdaraE'] = $request->input("suhu_akhir_{$posisiPrefix}_{$formIndex}");
        $detailData['RHS'] = $request->input("kelembaban_awal_{$posisiPrefix}_{$formIndex}");
        $detailData['RHE'] = $request->input("kelembaban_akhir_{$posisiPrefix}_{$formIndex}");
        $detailData['PUdaraS'] = $request->input("tekanan_awal_{$posisiPrefix}_{$formIndex}");
        $detailData['PUdaraE'] = $request->input("tekanan_akhir_{$posisiPrefix}_{$formIndex}");
        $detailData['TAirS'] = $request->input("suhu_air_awal_{$posisiPrefix}_{$formIndex}");
        $detailData['TAirE'] = $request->input("suhu_air_akhir_{$posisiPrefix}_{$formIndex}");
        $detailData['waktu'] = $request->input("waktu_{$posisiPrefix}_{$formIndex}");
    }
    
    \Log::debug("💾 Saving DetailMikropipetDispenset [form {$formIndex}, {$posisi}-{$bagian}]:", [
        'titikUkur' => $detailData['titikUkur'],
        'calibration_id' => $calibrationId,
        'form_index' => $formIndex,
        'm0' => $detailData['m0'] ?? null
    ]);
    
    DetailMikropipetDispenset::create($detailData);
    return true;
}

private function storeTaperGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeTaperGauge');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeTaperGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandarString = 'GAUGE BLOCK SET GRADE 0 (1160776)';
        
        \Log::info('🔧 Alat standar FIXED for Taper Gauge:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN KE HEAD TAPER GAUGE
        // ==================================================================
        $head = HeadTaperGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-57',
            'satuan_unit' => $this->getRequestValue($request, 'satuan_unit', $tabId),
        ]);

        \Log::info('✅ Head Taper Gauge saved:', [
            'head_id' => $head->id,
            'satuan_unit' => $this->getRequestValue($request, 'satuan_unit', $tabId)
        ]);

        // ==================================================================
        // 3. SIMPAN DETAIL TAPER GAUGE (15 BARIS x 5 ULANGAN)
        // ==================================================================
        \Log::info('📊 Saving Taper Gauge detail measurements (15 rows x 5 ulangan)...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 15; $i++) {
            // Ambil nilai nominal dengan getRequestValue
            $nominal = $this->getRequestValue($request, "nominal_{$i}", $tabId);
            
            // Ambil nilai penunjukan untuk 5 ulangan
            $ulangan1 = $this->getRequestValue($request, "penunjukan_{$i}_1", $tabId);
            $ulangan2 = $this->getRequestValue($request, "penunjukan_{$i}_2", $tabId);
            $ulangan3 = $this->getRequestValue($request, "penunjukan_{$i}_3", $tabId);
            $ulangan4 = $this->getRequestValue($request, "penunjukan_{$i}_4", $tabId);
            $ulangan5 = $this->getRequestValue($request, "penunjukan_{$i}_5", $tabId);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($nominal) || 
                       !empty($ulangan1) || !empty($ulangan2) || !empty($ulangan3) || 
                       !empty($ulangan4) || !empty($ulangan5);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $nominal,
                    'ulangan01' => $ulangan1,
                    'ulangan02' => $ulangan2,
                    'ulangan03' => $ulangan3,
                    'ulangan04' => $ulangan4,
                    'ulangan05' => $ulangan5,
                ];

                \Log::debug("📝 Saving Taper Gauge detail row {$i}:", $detailData);
                
                DetailTaperGauge::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Taper Gauge");

        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika ada)
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        // Update nama pemeriksa (jika ada)
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Update kondisi lingkungan (jika ada)
        $environmentData = [];
        
        $temperature = $this->getRequestValue($request, 'temperature', $tabId);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $this->getRequestValue($request, 'humidity', $tabId);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Environment condition saved:', $environmentData);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailTaperGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Taper Gauge):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storeTaperGauge COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTaperGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailTaperGauge::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Taper Gauge: " . $e->getMessage());
    }
}

private function updateTaperGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateTaperGauge');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headTaperGauge;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR (FIXED)
        // ==================================================================
        $alatStandarString = 'GAUGE BLOCK SET GRADE 0 (1160776)';
        
        \Log::info('🔧 Alat standar FIXED for TaperGauge:', [
            'alat_standar' => $alatStandarString,
        ]);
        
        // ==================================================================
        // 2. UPDATE HEAD TAPER GAUGE
        // ==================================================================
        
        // Cari head yang sudah ada
        $head = HeadTaperGauge::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-57',
            'satuan_unit' => $request->c,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ Head TaperGauge updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'satuan_unit' => $request->satuan_unit
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadTaperGauge::create($headData);
            \Log::info('✅ Head TaperGauge created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null,
                'satuan_unit' => $request->satuan_unit
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS - DELETE & RECREATE (TANPA FORMAT)
        // ==================================================================
        \Log::info('📊 Updating detail measurements for TaperGauge...');
        
        // Delete existing details untuk calibration ini
        $detailDeleted = DetailTaperGauge::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$detailDeleted} existing details");
        
        $detailCount = 0;
        
        // Proses 15 baris data (1-15) - LANGSUNG TANPA FORMAT
        for ($i = 1; $i <= 15; $i++) {
            // Cek apakah ada data untuk baris ini
            $hasData = false;
            
            // Cek apakah ada penunjukan yang diisi (minimal satu)
            for ($j = 1; $j <= 5; $j++) {
                $fieldName = "penunjukan_{$i}_{$j}";
                $value = $request->input($fieldName);
                if (!empty(trim($value ?? ''))) {
                    $hasData = true;
                    break;
                }
            }
            
            // Ambil nilai nominal
            $nominalField = "nominal_{$i}";
            $nominalValue = $request->input($nominalField);
            
            // Simpan jika ada data nominal atau penunjukan
            if (!empty(trim($nominalValue ?? '')) || $hasData) {
                
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $nominalValue,                                    // LANGSUNG, tanpa format
                    'ulangan01' => $request->input("penunjukan_{$i}_1"),            // LANGSUNG, tanpa format
                    'ulangan02' => $request->input("penunjukan_{$i}_2"),            // LANGSUNG, tanpa format
                    'ulangan03' => $request->input("penunjukan_{$i}_3"),            // LANGSUNG, tanpa format
                    'ulangan04' => $request->input("penunjukan_{$i}_4"),            // LANGSUNG, tanpa format
                    'ulangan05' => $request->input("penunjukan_{$i}_5"),            // LANGSUNG, tanpa format
                ];

                \Log::debug("📝 Saving detail row {$i}:", [
                    'titikUkur' => $nominalValue,
                    'ulangan01' => $request->input("penunjukan_{$i}_1"),
                    'ulangan02' => $request->input("penunjukan_{$i}_2"),
                    'ulangan03' => $request->input("penunjukan_{$i}_3"),
                    'ulangan04' => $request->input("penunjukan_{$i}_4"),
                    'ulangan05' => $request->input("penunjukan_{$i}_5"),
                ]);
                
                DetailTaperGauge::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for TaperGauge");
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Update satuan unit jika ada
        if ($request->filled('unit')) {
            $updateData['unit'] = $request->unit;
        }
        
        // Update uncertainty jika ada
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        // Update range jika ada
        if ($request->filled('range')) {
            $updateData['range'] = $request->range;
        }
        
        // Update kondisi lingkungan
        $environmentData = [];
        if ($request->filled('temperature')) {
            $environmentData['temperature'] = $request->temperature;
        }
        if ($request->filled('humidity')) {
            $environmentData['humidity'] = $request->humidity;
        }
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
        }
        
        // Update nama kalibrator dan pemeriksa jika ada
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headTaperGauge;
        $savedDetailCount = DetailTaperGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (TaperGauge):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'satuan_unit' => $request->satuan_unit,
            'unit' => $request->unit,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
            'nama_alat' => $calibration->namaAlat,
        ]);

        \Log::info('🎉 updateTaperGauge COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTaperGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data TaperGauge: " . $e->getMessage());
    }
}
    private function storeBoreGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeBoreGauge');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeBoreGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ============================================
        // 1. PROSES ALAT STANDAR DENGAN HANDLE "LAINNYA"
        // ============================================
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        
        // Jika masih null atau bukan array, coba dari request langsung
        if (empty($alatStandar)) {
            $alatStandar = $request->input('alat_standar', []);
        }
        
        // Pastikan dalam bentuk array
        if (!is_array($alatStandar)) {
            $alatStandar = [$alatStandar];
        }
        
        $alatStandarString = '';
        $processedAlatStandar = [];
        
        if (!empty($alatStandar)) {
            foreach ($alatStandar as $value) {
                if ($value === 'lainnya') {
                    $alatStandarTambahan = $this->getRequestValue($request, 'alat_standar_tambahan', $tabId);
                    if (empty($alatStandarTambahan)) {
                        $alatStandarTambahan = $request->input('alat_standar_tambahan');
                    }
                    if (!empty(trim($alatStandarTambahan))) {
                        $processedAlatStandar[] = trim($alatStandarTambahan);
                    }
                } else {
                    switch ($value) {
                        case 'dial_gauge_tester_0_25mm':
                            $processedAlatStandar[] = 'Dial Gauge Tester 0~25mm';
                            break;
                        case 'dial_indicator_1mm':
                            $processedAlatStandar[] = 'Dial Indicator 1 mm';
                            break;
                        default:
                            $processedAlatStandar[] = $value;
                    }
                }
            }
            
            $alatStandarString = implode(', ', $processedAlatStandar);
        }
        
        \Log::info('🔧 Alat standar Bore Gauge processed:', [
            'raw' => $alatStandar,
            'processed' => $processedAlatStandar,
            'string' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ============================================
        // 2. SIMPAN HEAD BORE GAUGE
        // ============================================
        $head = HeadBoreGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-58 (berdasarkan JIS B 7515-1982)',
            'satuan_unit_bawah' => $this->getRequestValue($request, 'satuan_unit_bawah', $tabId),
            'satuan_unit_atas' => $this->getRequestValue($request, 'satuan_unit_atas', $tabId),
        ]);

        \Log::info('✅ Head Bore Gauge saved:', [
            'head_id' => $head->id,
            'satuan_unit_bawah' => $this->getRequestValue($request, 'satuan_unit_bawah', $tabId),
            'satuan_unit_atas' => $this->getRequestValue($request, 'satuan_unit_atas', $tabId)
        ]);

        // ============================================
        // 3. SIMPAN DETAIL BORE GAUGE
        // ============================================
        \Log::info('📊 Saving Bore Gauge detail measurements...');
        $detailCount = 0;
        
        // Hapus data lama jika ada (untuk update)
        DetailBoreGauge::where('calibration_id', $calibration->id)->delete();
        
        // Ambil data dari request dengan getRequestValue
        // Coba dari format array dulu
        $penunjukAlatArray = $request->input('penunjukanAlat', []);
        $stdNaikArray = $request->input('pembacaanNaik', []);
        $stdTurunArray = $request->input('pembacaanTurun', []);
        
        // Jika tidak ada dalam format array, coba dari format individual dengan getRequestValue
        if (empty($penunjukAlatArray)) {
            $penunjukAlatArray = [];
            $stdNaikArray = [];
            $stdTurunArray = [];
            
            // Coba ambil dari format nominal_{i} atau titik_ukur_{i}
            for ($i = 1; $i <= 40; $i++) {
                $penunjukAlat = $this->getRequestValue($request, "nominal_{$i}", $tabId);
                if (empty($penunjukAlat)) {
                    $penunjukAlat = $this->getRequestValue($request, "titik_ukur_{$i}", $tabId);
                }
                $penunjukAlatArray[] = $penunjukAlat;
                
                // Ambil pembacaan (bisa 1-3 kali)
                $stdNaik = $this->getRequestValue($request, "pembacaan_{$i}_1", $tabId);
                $stdNaikArray[] = $stdNaik;
                
                $stdTurun = $this->getRequestValue($request, "pembacaan_{$i}_2", $tabId);
                $stdTurunArray[] = $stdTurun;
            }
        }
        
        \Log::info('📊 Data received:', [
            'penunjukAlat_count' => count($penunjukAlatArray),
            'stdNaik_count' => count($stdNaikArray),
            'stdTurun_count' => count($stdTurunArray),
            'tab_id' => $tabId
        ]);
        
        // Loop untuk data yang ada
        $maxRows = max(count($penunjukAlatArray), count($stdNaikArray), count($stdTurunArray));
        
        for ($i = 0; $i < $maxRows; $i++) {
            $penunjukAlat = $penunjukAlatArray[$i] ?? '';
            $stdNaik = $stdNaikArray[$i] ?? null;
            $stdTurun = $stdTurunArray[$i] ?? null;
            
            // Bersihkan data
            $penunjukAlat = trim($penunjukAlat);
            
            // Simpan jika ada data
            if (!empty($penunjukAlat) || !is_null($stdNaik) || !is_null($stdTurun)) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'penunjukAlat' => $penunjukAlat,
                    'std_naik' => $stdNaik,
                    'std_turun' => $stdTurun,
                ];

                \Log::debug("📝 Saving Bore Gauge detail row {$i}:", $detailData);
                
                DetailBoreGauge::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} Bore Gauge detail measurements");

        // ============================================
        // 4. SIMPAN REPEATABILITY (ADD BORE GAUGE)
        // ============================================
        \Log::info('📊 Saving Bore Gauge repeatability data...');
        
        // Hapus data lama jika ada
        AddBoreGauge::where('calibration_id', $calibration->id)->delete();
        
        $repeatabilityData = [
            'calibration_id' => $calibration->id,
            'repeatability' => $this->getRequestValue($request, 'repeatability', $tabId),
            'rep01' => $this->getRequestValue($request, 'rep01', $tabId),
            'rep02' => $this->getRequestValue($request, 'rep02', $tabId),
            'rep03' => $this->getRequestValue($request, 'rep03', $tabId),
            'rep04' => $this->getRequestValue($request, 'rep04', $tabId),
            'rep05' => $this->getRequestValue($request, 'rep05', $tabId),
            'rep06' => $this->getRequestValue($request, 'rep06', $tabId),
            'rep07' => $this->getRequestValue($request, 'rep07', $tabId),
            'rep08' => $this->getRequestValue($request, 'rep08', $tabId),
            'rep09' => $this->getRequestValue($request, 'rep09', $tabId),
            'rep10' => $this->getRequestValue($request, 'rep10', $tabId),
        ];

        // Filter hanya yang tidak null
        $repeatabilityDataFiltered = array_filter($repeatabilityData, function($value) {
            return !is_null($value) && $value !== '';
        });

        if (count($repeatabilityDataFiltered) > 1) { // >1 karena calibration_id selalu ada
            AddBoreGauge::create($repeatabilityDataFiltered);
            \Log::info("✅ Bore Gauge repeatability saved");
        } else {
            \Log::info("⚠️ No repeatability data to save");
        }

        // ============================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ============================================
        $updateData = [];
        
        // Update rentang ukur
        $rentangMin = $this->getRequestValue($request, 'rentang_ukur_min', $tabId);
        if ($rentangMin !== null && $rentangMin !== '') {
            $updateData['range_min'] = $rentangMin;
        }
        
        $rentangMax = $this->getRequestValue($request, 'rentang_ukur_max', $tabId);
        if ($rentangMax !== null && $rentangMax !== '') {
            $updateData['range_max'] = $rentangMax;
        }
        
        // Update nama kalibrator
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
        }
        
        // Update nama pemeriksa
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
        }
        
        // Update uncertainty
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', $updateData);
        }

        // ============================================
        // 6. LOG HASIL AKHIR
        // ============================================
        $savedDetailCount = DetailBoreGauge::where('calibration_id', $calibration->id)->count();
        $savedAddCount = AddBoreGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Bore Gauge):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'add_records' => $savedAddCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);

        \Log::info('🎉 storeBoreGauge COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeBoreGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailBoreGauge::where('calibration_id', $calibration->id)->delete();
                AddBoreGauge::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Bore Gauge: " . $e->getMessage());
    }
}

private function updateBoreGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateBoreGauge');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headBoreGauge;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // Jika certificate_id masih kosong, gunakan dari parameter atau generate
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $calibration->certificate_id;
        }
        
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        $finalCertificateId = $certificateIdBaru;
        
        \Log::info('📋 Final Certificate ID:', [
            'certificate_id' => $finalCertificateId,
            'certificate_id_updated' => $certificateIdUpdated
        ]);

        // ============================================
        // PROSES ALAT STANDAR DENGAN HANDLE "LAINNYA"
        // ============================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = '';
        
        if (!empty($alatStandar)) {
            $processedAlatStandar = [];
            
            foreach ($alatStandar as $index => $value) {
                if ($value === 'lainnya') {
                    $alatStandarTambahan = $request->alat_standar_tambahan;
                    if (!empty(trim($alatStandarTambahan ?? ''))) {
                        $processedAlatStandar[] = trim($alatStandarTambahan);
                    }
                } else {
                    switch ($value) {
                        case 'dial_gauge_tester_0_25mm':
                            $processedAlatStandar[] = 'Dial Gauge Tester 0~25mm';
                            break;
                        case 'dial_indicator_1mm':
                            $processedAlatStandar[] = 'Dial Indicator 1 mm';
                            break;
                        default:
                            $processedAlatStandar[] = $value;
                    }
                }
            }
            
            $alatStandarString = implode(', ', $processedAlatStandar);
        }
        
        \Log::info('🔧 Alat standar Bore Gauge processed for update:', [
            'raw' => $alatStandar,
            'processed' => $processedAlatStandar ?? [],
            'string' => $alatStandarString,
            'calibration_id' => $calibration->id
        ]);

        // ============================================
        // 1. UPDATE HEAD BORE GAUGE
        // ============================================
        $head = HeadBoreGauge::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📊 Head Bore Gauge BEFORE update:', [
            'head_exists' => $head ? true : false,
            'head_id' => $head->id ?? null,
            'certificate_id_before' => $head->certificate_id ?? null,
            'calibration_id' => $calibration->id
        ]);
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-58 (berdasarkan JIS B 7515-1982)',
            'satuan_unit_bawah' => $request->satuan_unit_bawah,
            'satuan_unit_atas' => $request->satuan_unit_atas,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $headData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $finalCertificateId]);
        }
        
        if ($head) {
            $head->update($headData);
            $head->refresh();
            \Log::info('✅ Head Bore Gauge updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadBoreGauge::create($headData);
            \Log::info('✅ Head Bore Gauge created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }

        // ============================================
        // 2. UPDATE DETAIL BORE GAUGE - TANPA FORMAT
        // ============================================
        \Log::info('📊 Updating Bore Gauge detail measurements...');
        $detailCount = 0;
        
        // Hapus data lama jika ada
        $deletedDetails = DetailBoreGauge::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old detail records:', [
            'count' => $deletedDetails,
            'calibration_id' => $calibration->id
        ]);
        
        // Ambil data dari request - LANGSUNG TANPA FORMAT
        $penunjukAlatArray = $request->penunjukanAlat ?? [];
        $stdNaikArray = $request->pembacaanNaik ?? [];
        $stdTurunArray = $request->pembacaanTurun ?? [];
        
        // Loop untuk 40 baris data (0-39) - LANGSUNG TANPA FORMAT
        for ($i = 0; $i < 40; $i++) {
            $penunjukAlat = isset($penunjukAlatArray[$i]) ? trim($penunjukAlatArray[$i]) : '';
            $stdNaik = $stdNaikArray[$i] ?? null;
            $stdTurun = $stdTurunArray[$i] ?? null;
            
            if (!empty($penunjukAlat) || !is_null($stdNaik) || !is_null($stdTurun)) {
                DetailBoreGauge::create([
                    'calibration_id' => $calibration->id,
                    'penunjukAlat' => $penunjukAlat,  // LANGSUNG, tanpa format
                    'std_naik' => $stdNaik,           // LANGSUNG, tanpa format
                    'std_turun' => $stdTurun,         // LANGSUNG, tanpa format
                ]);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Updated {$detailCount} Bore Gauge detail measurements");

        // ============================================
        // 3. UPDATE REPEATABILITY - TANPA FORMAT
        // ============================================
        \Log::info('📊 Updating Bore Gauge repeatability data...');
        
        // Hapus data lama
        $deletedRepeatability = AddBoreGauge::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old repeatability records:', [
            'count' => $deletedRepeatability,
            'calibration_id' => $calibration->id
        ]);
        
        // Siapkan data repeatability - LANGSUNG TANPA FORMAT
        $repeatabilityData = [
            'calibration_id' => $calibration->id,
            'repeatability' => $request->repeatability,
            'rep01' => $request->rep01,
            'rep02' => $request->rep02,
            'rep03' => $request->rep03,
            'rep04' => $request->rep04,
            'rep05' => $request->rep05,
            'rep06' => $request->rep06,
            'rep07' => $request->rep07,
            'rep08' => $request->rep08,
            'rep09' => $request->rep09,
            'rep10' => $request->rep10,
        ];

        // Filter hanya yang tidak null
        $filteredRepeatabilityData = array_filter($repeatabilityData, function($value) {
            return !is_null($value);
        });

        if (count($filteredRepeatabilityData) > 2) {
            AddBoreGauge::create($filteredRepeatabilityData);
            \Log::info("✅ Bore Gauge repeatability updated");
        } else {
            \Log::info("⚠️ No repeatability data to update");
        }

        // ============================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ============================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $finalCertificateId]);
        }
        
        // Update nama kalibrator dan pemeriksa jika ada
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        // Update uncertainty jika ada
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ============================================
        // 5. FINAL CHECK
        // ============================================
        $calibration->refresh();
        $head->refresh();
        
        \Log::info('🏁 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'certificate_id_di_head' => $head->certificate_id,
            'certificate_id_di_calibration' => $calibration->certificate_id,
            'detail_records' => $detailCount,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);

        \Log::info('🎉 updateBoreGauge COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateBoreGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Bore Gauge: " . $e->getMessage());
    }
}
/**
 * FORMAT DECIMAL VALUE - CEK KOSONG DAN NULL
 */
private function formatDecimalValue($value)
{
    // Jika null atau undefined
    if (is_null($value)) {
        return null;
    }
    
    // Jika string kosong
    if ($value === '') {
        return null;
    }
    
    // Jika array kosong
    if (is_array($value) && empty($value)) {
        return null;
    }
    
    // Trim dan cek
    $trimmed = trim($value);
    if ($trimmed === '') {
        return null;
    }
    
    // Cek apakah numeric
    if (is_numeric($trimmed)) {
        return $trimmed;
    }
    
    // Jika tidak numeric, return null
    return null;
}

private function storeFeelerGauge($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1, $tabId = null)
{
    \Log::info('🚀 ===== START storeFeelerGauge =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI (DENGAN DUKUNGAN TAB)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key (termasuk tab)
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request, $tabId) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request, $tabId) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tabId}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}_tab{$tabId}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        // ==================================================================
        // 3. AMBIL ALAT STANDAR DARI FORM 1
        // ==================================================================
        $alatStandar = $findArrayValue('alat_standar', 1);
        $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : 'Mesin ULM 01-600D, Micrometer, Gauge Block';
        
        \Log::info('📋 Alat Standar:', ['standard_value' => $standardValue]);
        
        // Hapus semua detail yang lama untuk calibration ini
        DetailFeelerGauge::where('calibration_id', $calibration->id)->delete();
        
        // ==================================================================
        // 4. LOOP UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex} - Feeler Gauge");
            \Log::info("=========================================");
            
            // ==========================================================
            // AMBIL SATUAN UNIT
            // ==========================================================
            $satuanUnitUUT = $findValue('satuan_unit_uut', $formIndex);
            if (empty($satuanUnitUUT)) {
                $satuanUnitUUT = 'mm';
            }
            
            $satuanUnitGaugeBlock = $findValue('satuan_unit_gauge_block', $formIndex);
            if (empty($satuanUnitGaugeBlock)) {
                $satuanUnitGaugeBlock = 'mm';
            }
            
            // ==========================================================
            // SIMPAN HEAD FEELER GAUGE
            // ==========================================================
            HeadFeelerGauge::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'satuan_unit_uut' => $satuanUnitUUT,
                    'satuan_unit_gauge_block' => $satuanUnitGaugeBlock,
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-62',
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
            \Log::info("✅ HeadFeelerGauge saved for form {$formIndex}");
            
            // ==========================================================
            // SIMPAN DETAILS (25 BARIS)
            // ==========================================================
            $detailCount = 0;
            
            for ($row = 1; $row <= 25; $row++) {
                // Ambil nilai nominal UUT
                $nominalUUT = $findValue('nominal_uut', $formIndex, [$row]);
                if (empty($nominalUUT)) {
                    $nominalUUT = $findValue('nominalUUT', $formIndex, [$row]);
                }
                
                // Ambil nilai nominal Gauge Block
                $nominalGB = $findValue('nominal_gb', $formIndex, [$row]);
                if (empty($nominalGB)) {
                    $nominalGB = $findValue('nominalGB', $formIndex, [$row]);
                }
                
                // Ambil data pengukuran A dan B (AB)
                $ab_gb_a = $findValue('ab_gb_a', $formIndex, [$row]);
                $ab_uut_b = $findValue('ab_uut_b', $formIndex, [$row]);
                $ab_gb_a2 = $findValue('ab_gb_a2', $formIndex, [$row]);
                $ab_uut_b2 = $findValue('ab_uut_b2', $formIndex, [$row]);
                
                // Ambil data pengukuran A dan C (AC)
                $ac_gb_a = $findValue('ac_gb_a', $formIndex, [$row]);
                $ac_uut_c = $findValue('ac_uut_c', $formIndex, [$row]);
                $ac_gb_a2 = $findValue('ac_gb_a2', $formIndex, [$row]);
                $ac_uut_c2 = $findValue('ac_uut_c2', $formIndex, [$row]);
                
                $hasData = !empty($nominalUUT) || !empty($nominalGB) || 
                           !empty($ab_gb_a) || !empty($ab_uut_b) ||
                           !empty($ab_gb_a2) || !empty($ab_uut_b2) ||
                           !empty($ac_gb_a) || !empty($ac_uut_c) ||
                           !empty($ac_gb_a2) || !empty($ac_uut_c2);
                
                if ($hasData) {
                    DetailFeelerGauge::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'nominalUUT' => $nominalUUT,
                        'nominalGB' => $nominalGB,
                        'GBA1' => $ab_gb_a,
                        'UUTB1' => $ab_uut_b,
                        'GBA2' => $ab_gb_a2,
                        'UUTB2' => $ab_uut_b2,
                        'GBA3' => $ac_gb_a,
                        'UUTC3' => $ac_uut_c,
                        'GBA4' => $ac_gb_a2,
                        'UUTC4' => $ac_uut_c2,
                    ]);
                    $detailCount++;
                    \Log::debug("Detail saved for form {$formIndex}, row {$row}");
                }
            }
            \Log::info("✅ Saved {$detailCount} details for form {$formIndex}");
        }
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedHeadCount = HeadFeelerGauge::where('calibration_id', $calibration->id)->count();
        $savedDetailCount = DetailFeelerGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Feeler Gauge):', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_count' => $savedHeadCount,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $calibration->certificate_id,
            'tab_id' => $tabId,
            'alat_standar' => $standardValue,
        ]);

        \Log::info('🎉 storeFeelerGauge COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeFeelerGauge FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback
        try {
            DetailFeelerGauge::where('calibration_id', $calibration->id)->delete();
            HeadFeelerGauge::where('calibration_id', $calibration->id)->delete();
        } catch (\Exception $rollbackError) {
            \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
        }
        
        throw new \Exception("Gagal menyimpan data Feeler Gauge: " . $e->getMessage());
    }
}

private function updateFeelerGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateFeelerGauge');
        \Log::info('📝 Updating Feeler Gauge data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. AMBIL JUMLAH FORM
        // ==================================================================
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Jumlah form:', ['jumlah_form' => $jumlahForm]);
        
        // ==================================================================
        // 2. PROSES ALAT STANDAR (DARI FORM 1)
        // ==================================================================
        // Cek berbagai kemungkinan key untuk alat standar
        $alatStandar = [];
        if ($request->has('alat_standar_1')) {
            $alatStandar = $request->input('alat_standar_1', []);
        } elseif ($request->has('alat_standar')) {
            $alatStandar = $request->input('alat_standar', []);
        }
        
        if (is_string($alatStandar)) {
            $alatStandar = [$alatStandar];
        }
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar for Feeler Gauge:', ['alat_standar' => $alatStandarString]);
        
        // ==================================================================
        // 3. AMBIL DATA DARI FORM 1 UNTUK DISYNC KE FORM LAINNYA
        // ==================================================================
        // Data dari form 1 akan digunakan sebagai referensi untuk form lain
        $form1Data = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->input('brandAlat', $calibration->brandAlat),
            'kodeAlat' => $request->input('kodeAlat', $calibration->kodeAlat),
            'typeAlat' => $request->input('typeAlat', $calibration->typeAlat),
            'NoSeri' => $request->input('NoSeri', $calibration->NoSeri),
            'kapasitas' => $request->input('kapasitas', $calibration->kapasitas),
            'resolusi' => $request->input('resolusi', $calibration->resolusi),
            'pemilikAlat' => $request->input('pemilikAlat', $calibration->pemilikAlat),
             'no_po' => $request->input('no_po', $calibration->no_po),
            'tanggalMasuk' => $request->input('tanggalMasuk', $calibration->tanggalMasuk),
            'tanggalKalibrasi' => $request->input('tanggalKalibrasi', $calibration->tanggalKalibrasi),
            'tempatKalibrasi' => $request->input('tempatKalibrasi', $calibration->tempatKalibrasi),
            'lokasiPT' => $request->input('lokasiPT', $calibration->lokasiPT),
            'kondisiAlat' => $request->input('kondisiAlat', $calibration->kondisiAlat),
            'keterangan' => $request->input('keterangan', $calibration->keterangan),
            'RT_condition1' => $request->input('RT_condition1', $calibration->RT_condition1),
            'RT_condition2' => $request->input('RT_condition2', $calibration->RT_condition2),
            'RT_condition3' => $request->input('RT_condition3', $calibration->RT_condition3),
            'RH_condition1' => $request->input('RH_condition1', $calibration->RH_condition1),
            'RH_condition2' => $request->input('RH_condition2', $calibration->RH_condition2),
            'RH_condition3' => $request->input('RH_condition3', $calibration->RH_condition3),
            'calibratedBy' => $request->input('calibratedBy', $calibration->calibrated_by),
            'verifiedBy' => $request->input('verifiedBy', $calibration->verified_by),
        ];
        
        \Log::info('📋 Form 1 data untuk referensi:', array_keys($form1Data));
        
        // ==================================================================
        // 4. UPDATE ATAU CREATE HEAD FEELER GAUGE UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Cari satuan unit untuk form ini
            $satuanUnitUUT = $request->input("satuan_unit_uut_{$formIndex}") ?? 
                            $request->input('satuan_unit_uut') ?? 
                            $calibration->{'headFeelerGaugeForm' . $formIndex}->satuan_unit_uut ?? 'mm';
            
            $satuanUnitGaugeBlock = $request->input("satuan_unit_gauge_block_{$formIndex}") ?? 
                                   $request->input('satuan_unit_gauge_block') ?? 
                                   $calibration->{'headFeelerGaugeForm' . $formIndex}->satuan_unit_gauge_block ?? 'mm';
            
            $headData = [
                'standard' => $alatStandarString,
                'calibrationMethod' => 'PAS-IK1102-62',
                'satuan_unit_uut' => $satuanUnitUUT,
                'satuan_unit_gauge_block' => $satuanUnitGaugeBlock,
            ];
            
            // Update certificate_id di HEAD hanya untuk form 1 jika diperlukan
            if ($formIndex == 1 && $certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info('📝 Setting certificate_id di HEAD form 1:', ['certificate_id' => $certificateIdBaru]);
            }
            
            // Untuk form > 1, copy certificate_id dari form 1
            if ($formIndex > 1 && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
            }
            
            $head = HeadFeelerGauge::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                $headData
            );
            
            \Log::info("✅ HeadFeelerGauge updated for form {$formIndex}:", [
                'head_id' => $head->id,
                'satuan_unit_uut' => $satuanUnitUUT,
                'satuan_unit_gauge_block' => $satuanUnitGaugeBlock
            ]);
        }
        
        // ==================================================================
        // 5. HAPUS DATA DETAIL LAMA UNTUK SEMUA FORM
        // ==================================================================
        $deletedDetails = DetailFeelerGauge::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old detail records");
        
        // ==================================================================
        // 6. SIMPAN DETAIL FEELER GAUGE UNTUK SETIAP FORM
        // ==================================================================
        $totalDetailCount = 0;
        
        // Proses untuk setiap form
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $detailCount = 0;
            
            // Proses 25 baris data untuk form ini
            for ($i = 1; $i <= 25; $i++) {
                // Ambil data dari request dengan format nama_{formIndex}_{row}
                $nominalUUT = $request->input("nominal_uut_{$formIndex}_{$i}");
                $nominalGB = $request->input("nominal_gb_{$formIndex}_{$i}");
                
                // Data untuk Pengukuran A dan B
                $ab_gb_a = $request->input("ab_gb_a_{$formIndex}_{$i}");
                $ab_uut_b = $request->input("ab_uut_b_{$formIndex}_{$i}");
                $ab_gb_a2 = $request->input("ab_gb_a2_{$formIndex}_{$i}");
                $ab_uut_b2 = $request->input("ab_uut_b2_{$formIndex}_{$i}");
                
                // Data untuk Pengukuran A dan C
                $ac_gb_a = $request->input("ac_gb_a_{$formIndex}_{$i}");
                $ac_uut_c = $request->input("ac_uut_c_{$formIndex}_{$i}");
                $ac_gb_a2 = $request->input("ac_gb_a2_{$formIndex}_{$i}");
                $ac_uut_c2 = $request->input("ac_uut_c2_{$formIndex}_{$i}");
                
                // Cek apakah ada data untuk baris ini (dari form tersebut)
                $hasData = !empty($nominalUUT) || !empty($nominalGB) || 
                          !empty($ab_gb_a) || !empty($ab_uut_b) ||
                          !empty($ab_gb_a2) || !empty($ab_uut_b2) ||
                          !empty($ac_gb_a) || !empty($ac_uut_c) ||
                          !empty($ac_gb_a2) || !empty($ac_uut_c2);
                
                // Jika form 1 memiliki data, form lain bisa ikut menyimpan data kosong
                // atau kita bisa menyimpan semua data yang ada
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'nominalUUT' => $nominalUUT,
                        'nominalGB' => $nominalGB,
                        'GBA1' => $ab_gb_a,
                        'UUTB1' => $ab_uut_b,
                        'GBA2' => $ab_gb_a2,
                        'UUTB2' => $ab_uut_b2,
                        'GBA3' => $ac_gb_a,
                        'UUTC3' => $ac_uut_c,
                        'GBA4' => $ac_gb_a2,
                        'UUTC4' => $ac_uut_c2,
                    ];
                    
                    DetailFeelerGauge::create($detailData);
                    $detailCount++;
                    $totalDetailCount++;
                }
            }
            
            // Log untuk form ini
            if ($detailCount > 0) {
                \Log::info("✅ Saved {$detailCount} DetailFeelerGauge records for form {$formIndex}");
            } else {
                \Log::info("ℹ️ No data saved for form {$formIndex} (empty rows)");
            }
        }
        
        // ==================================================================
        // 7. UPDATE ATAU CREATE DETAIL UNTUK FORM YANG TIDAK ADA DATA (KOSONG)
        //    TAPI TETAP BUAT RECORD KOSONG AGAR STRUKTUR FORM TETAP ADA
        // ==================================================================
        // Cek apakah ada form yang tidak memiliki detail sama sekali
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $existingDetails = DetailFeelerGauge::where('calibration_id', $calibration->id)
                                ->where('form_index', $formIndex)
                                ->count();
            
            // Jika tidak ada detail sama sekali untuk form ini, buat 1 record kosong
            // agar form tetap memiliki struktur
            if ($existingDetails == 0) {
                // Cek apakah form ini adalah form > 1 dan tidak ada data dari request
                // Kita tetap buat record kosong sebagai placeholder
                $hasAnyData = false;
                for ($i = 1; $i <= 25; $i++) {
                    $nominalUUT = $request->input("nominal_uut_{$formIndex}_{$i}");
                    if (!empty($nominalUUT)) {
                        $hasAnyData = true;
                        break;
                    }
                }
                
                // Jika benar-benar tidak ada data, buat 1 record kosong
                if (!$hasAnyData && $formIndex > 1) {
                    // Form > 1 yang kosong, kita buat record kosong saja
                    DetailFeelerGauge::create([
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'nominalUUT' => '',
                        'nominalGB' => '',
                        'GBA1' => '',
                        'UUTB1' => '',
                        'GBA2' => '',
                        'UUTB2' => '',
                        'GBA3' => '',
                        'UUTC3' => '',
                        'GBA4' => '',
                        'UUTC4' => '',
                    ]);
                    \Log::info("📝 Created empty placeholder detail for form {$formIndex}");
                }
            }
        }
        
        \Log::info("✅ TOTAL Saved {$totalDetailCount} DetailFeelerGauge records");
        
        // ==================================================================
        // 8. UPDATE CALIBRATION DENGAN DATA DARI FORM 1
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Update jumlah form
        $updateData['jumlah_form'] = $jumlahForm;
        
        // Data TTD dan nama dari calibration
        $calibratedBy = $request->input('calibratedBy') ?? $request->input('calibrated_by');
        if (!empty($calibratedBy)) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        $verifiedBy = $request->input('verifiedBy') ?? $request->input('verified_by');
        if (!empty($verifiedBy)) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        // Data dari form 1 (merek, type, dll)
        if ($request->filled('brandAlat')) {
            $updateData['brandAlat'] = $request->brandAlat;
        }
        if ($request->filled('kodeAlat')) {
            $updateData['kodeAlat'] = $request->kodeAlat;
        }
        if ($request->filled('typeAlat')) {
            $updateData['typeAlat'] = $request->typeAlat;
        }
        if ($request->filled('NoSeri')) {
            $updateData['NoSeri'] = $request->NoSeri;
        }
        if ($request->filled('kapasitas')) {
            $updateData['kapasitas'] = $request->kapasitas;
        }
        if ($request->filled('resolusi')) {
            $updateData['resolusi'] = $request->resolusi;
        }
        if ($request->filled('pemilikAlat')) {
            $updateData['pemilikAlat'] = $request->pemilikAlat;
        }
         if ($request->filled('no_po')) {
            $updateData['no_po'] = $request->no_po;
        }
        if ($request->filled('tanggalMasuk')) {
            $updateData['tanggalMasuk'] = $request->tanggalMasuk;
        }
        if ($request->filled('tanggalKalibrasi')) {
            $updateData['tanggalKalibrasi'] = $request->tanggalKalibrasi;
        }
        if ($request->filled('jenisPembacaan')) {
            $updateData['jenisPembacaan'] = $request->jenisPembacaan;
        }
        if ($request->filled('tempatKalibrasi')) {
            $updateData['tempatKalibrasi'] = $request->tempatKalibrasi;
        }
        if ($request->filled('lokasiPT')) {
            $updateData['lokasiPT'] = $request->lokasiPT;
        }
        if ($request->filled('kondisiAlat')) {
            $updateData['kondisiAlat'] = $request->kondisiAlat;
        }
        if ($request->filled('keterangan')) {
            $updateData['keterangan'] = $request->keterangan;
        }
        
        // Data suhu dan RH
        $suhuFields = ['RT_condition1', 'RT_condition2', 'RT_condition3'];
        $rhFields = ['RH_condition1', 'RH_condition2', 'RH_condition3'];
        
        foreach ($suhuFields as $field) {
            if ($request->filled($field)) {
                $updateData[$field] = $request->$field;
            }
        }
        
        foreach ($rhFields as $field) {
            if ($request->filled($field)) {
                $updateData[$field] = $request->$field;
            }
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', array_keys($updateData));
        }
        
        // ==================================================================
        // 9. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headsCount = HeadFeelerGauge::where('calibration_id', $calibration->id)->count();
        $totalDetailRecords = DetailFeelerGauge::where('calibration_id', $calibration->id)->count();
        $headForm1 = HeadFeelerGauge::where('calibration_id', $calibration->id)->where('form_index', 1)->first();
        
        // Ambil detail per form untuk logging
        $detailPerForm = [];
        for ($i = 1; $i <= $jumlahForm; $i++) {
            $detailPerForm[$i] = DetailFeelerGauge::where('calibration_id', $calibration->id)
                                ->where('form_index', $i)
                                ->count();
        }
        
        \Log::info('📋 UPDATE SUMMARY (Feeler Gauge):', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'heads_count' => $headsCount,
            'detail_records_total' => $totalDetailRecords,
            'detail_per_form' => $detailPerForm,
            'certificate_id_di_head_form1' => $headForm1->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'satuan_unit_uut_form1' => $headForm1->satuan_unit_uut ?? null,
            'satuan_unit_gauge_block_form1' => $headForm1->satuan_unit_gauge_block ?? null,
            'alat_standar' => $alatStandarString,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);
        
        \Log::info('🎉 updateFeelerGauge COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateFeelerGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Feeler Gauge: " . $e->getMessage());
    }
}

private function storePHMeter($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storePHMeter');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storePHMeter called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - KOMBINASI HIDDEN INPUT + CHECKBOX
        // ==================================================================
        
        // Sumber 1: Hidden input (nilai default - HARUS SELALU ADA)
        $hiddenAlatStandar = trim($this->getRequestValue($request, 'alat_standar_text', $tabId) ?? '');
        \Log::info('🔧 Hidden alat standar:', ['hidden_value' => $hiddenAlatStandar]);
        
        // Sumber 2: Checkbox array (pilihan tambahan user)
        $checkboxAlatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (empty($checkboxAlatStandar)) {
            $checkboxAlatStandar = $request->input('alat_standar', []);
        }
        
        // Pastikan dalam bentuk array
        if (!is_array($checkboxAlatStandar)) {
            $checkboxAlatStandar = [$checkboxAlatStandar];
        }
        
        \Log::info('🔧 Checkbox alat standar:', ['checkbox_values' => $checkboxAlatStandar]);
        
        // KOMBINASI KEDUA DATA:
        // 1. Hidden input selalu dimasukkan
        // 2. Jika ada checkbox, tambahkan setelah hidden input
        
        $standardParts = [];
        
        // Tambahkan hidden input terlebih dahulu
        if (!empty($hiddenAlatStandar)) {
            $standardParts[] = $hiddenAlatStandar;
        } else {
            // Fallback jika hidden input kosong
            $standardParts[] = 'CRM Buffer pH, Merck, 4, 7, & 10';
        }
        
        // Tambahkan checkbox jika ada
        if (!empty($checkboxAlatStandar)) {
            // Filter checkbox yang kosong
            $checkboxValues = array_filter($checkboxAlatStandar, function($value) {
                return !empty($value);
            });
            
            if (!empty($checkboxValues)) {
                $standardParts[] = implode(", ", $checkboxValues);
            }
        }
        
        // Gabungkan kedua bagian
        $standardValue = implode("; ", $standardParts);
        
        \Log::info('🔧 Alat standar kombinasi:', [
            'hidden' => $hiddenAlatStandar,
            'checkbox' => $checkboxAlatStandar,
            'combined_result' => $standardValue,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. PROSES NAMA KALIBRATOR DAN PEMERIKSA
        // ==================================================================
        $namaKalibrator = trim($this->getRequestValue($request, 'calibrated_by', $tabId) ?? '');
        $namaPemeriksa = trim($this->getRequestValue($request, 'verified_by', $tabId) ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);

        // ==================================================================
        // 3. SIMPAN KE HEAD PH METER
        // ==================================================================
        $head = HeadPhMeter::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-40',
        ]);

        \Log::info('✅ HeadPhMeter saved:', [
            'head_id' => $head->id,
            'standard' => $standardValue
        ]);

        // ==================================================================
        // 4. SIMPAN DETAIL PH METER (5 TITIK UKUR)
        // ==================================================================
        \Log::info('📊 Saving DetailPhMeter data (5 titik ukur)...');
        $detailCount = 0;
        
        // Proses 5 titik ukur (sesuai form HTML)
        for ($i = 1; $i <= 5; $i++) {
            // Ambil data dari input form dengan getRequestValue
            $buffer = $this->getRequestValue($request, "buffer_{$i}", $tabId);
            $pembacaan_1 = $this->getRequestValue($request, "pembacaan_{$i}_1", $tabId);
            $pembacaan_2 = $this->getRequestValue($request, "pembacaan_{$i}_2", $tabId);
            $pembacaan_3 = $this->getRequestValue($request, "pembacaan_{$i}_3", $tabId);
            $pembacaan_4 = $this->getRequestValue($request, "pembacaan_{$i}_4", $tabId);
            $pembacaan_5 = $this->getRequestValue($request, "pembacaan_{$i}_5", $tabId);
            $resolusi = $this->getRequestValue($request, "resolusi_{$i}", $tabId);
            $suhu = $this->getRequestValue($request, "suhu_{$i}", $tabId);
            
            \Log::debug("🔍 Row {$i} data from request:", [
                'buffer' => $buffer,
                'pembacaan_1' => $pembacaan_1,
                'pembacaan_2' => $pembacaan_2,
                'pembacaan_3' => $pembacaan_3,
                'pembacaan_4' => $pembacaan_4,
                'pembacaan_5' => $pembacaan_5,
                'resolusi' => $resolusi,
                'suhu' => $suhu,
                'tab_id' => $tabId
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($buffer) || 
                      !empty($pembacaan_1) || !empty($pembacaan_2) || !empty($pembacaan_3) || 
                      !empty($pembacaan_4) || !empty($pembacaan_5) || 
                      !empty($resolusi) || !empty($suhu);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'nilaiBuffer' => $buffer,
                    'rep01' => $pembacaan_1,
                    'rep02' => $pembacaan_2,
                    'rep03' => $pembacaan_3,
                    'rep04' => $pembacaan_4,
                    'rep05' => $pembacaan_5,
                    'Resolusi' => $resolusi,
                    'TBuffer' => $suhu,
                ];
                
                \Log::debug("💾 Saving DetailPhMeter row {$i}:", $detailData);
                
                DetailPhMeter::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⏭️ Skipping row {$i} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailPhMeter records");

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Update satuan (jika ada)
        $satuan = $this->getRequestValue($request, 'satuan', $tabId);
        if (!empty($satuan)) {
            $updateData['satuan'] = $satuan;
        }
        
        // Update rentang ukur (jika ada)
        $rentangMin = $this->getRequestValue($request, 'rentang_ukur_min', $tabId);
        if ($rentangMin !== null && $rentangMin !== '') {
            $updateData['range_min'] = $rentangMin;
        }
        
        $rentangMax = $this->getRequestValue($request, 'rentang_ukur_max', $tabId);
        if ($rentangMax !== null && $rentangMax !== '') {
            $updateData['range_max'] = $rentangMax;
        }
        
        // Update kondisi lingkungan (jika ada)
        $environmentData = [];
        
        $temperature = $this->getRequestValue($request, 'temperature', $tabId);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $this->getRequestValue($request, 'humidity', $tabId);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Environment condition saved:', $environmentData);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailPhMeter::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (pH Meter):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $standardValue,
            'hidden_alat_standar' => $hiddenAlatStandar,
            'checkbox_alat_standar' => $checkboxAlatStandar,
        ]);

        \Log::info('🎉 storePHMeter COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storePHMeter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailPhMeter::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data pH Meter: " . $e->getMessage());
    }
}
private function updatePhMeter($request, $calibration, $certificateId)
{
    try {
        \Log::info('🚀 START updatePhMeter', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $certificateId
        ]);

        // ==================================================================
        // 1. VALIDASI DAN AMBIL CERTIFICATE ID
        // ==================================================================
        $finalCertificateId = $certificateId;
        
        // Jika certificate_id dari parameter null, ambil dari calibration
        if (empty($finalCertificateId)) {
            $finalCertificateId = $calibration->certificate_id;
            \Log::info('📋 Mengambil certificate_id dari calibration:', [
                'certificate_id' => $finalCertificateId
            ]);
        }
        
        // Jika masih null, ambil dari head yang sudah ada di database
        if (empty($finalCertificateId)) {
            $existingHead = HeadPhMeter::where('calibration_id', $calibration->id)->first();
            if ($existingHead && !empty($existingHead->certificate_id)) {
                $finalCertificateId = $existingHead->certificate_id;
                \Log::info('📋 Mengambil certificate_id dari existing head:', [
                    'certificate_id' => $finalCertificateId,
                    'head_id' => $existingHead->id
                ]);
            }
        }
        
        // Jika masih null, coba ambil dari detail
        if (empty($finalCertificateId)) {
            $existingDetail = DetailPhMeter::where('calibration_id', $calibration->id)->first();
            if ($existingDetail && !empty($existingDetail->certificate_id)) {
                $finalCertificateId = $existingDetail->certificate_id;
                \Log::info('📋 Mengambil certificate_id dari existing detail:', [
                    'certificate_id' => $finalCertificateId
                ]);
            }
        }
        
        // Jika masih null, throw error
        if (empty($finalCertificateId)) {
            \Log::error('❌ Certificate ID tidak ditemukan untuk pH Meter update', [
                'calibration_id' => $calibration->id,
                'certificate_id_from_param' => $certificateId,
                'certificate_id_from_calibration' => $calibration->certificate_id
            ]);
            throw new \Exception('Certificate ID is required for pH Meter update');
        }

        // ==================================================================
        // 2. PROSES ALAT STANDAR - KOMBINASI HIDDEN INPUT + CHECKBOX
        // ==================================================================
        
        // Sumber 1: Hidden input (nilai default - HARUS SELALU ADA)
        $hiddenAlatStandar = trim($request->alat_standar_text ?? '');
        \Log::info('🔧 Hidden alat standar:', ['hidden_value' => $hiddenAlatStandar]);
        
        // Sumber 2: Checkbox array (pilihan tambahan user)
        $checkboxAlatStandar = $request->input('alat_standar', []);
        \Log::info('🔧 Checkbox alat standar:', ['checkbox_values' => $checkboxAlatStandar]);
        
        // KOMBINASI KEDUA DATA:
        $standardParts = [];
        
        // Tambahkan hidden input terlebih dahulu
        if (!empty($hiddenAlatStandar)) {
            $standardParts[] = $hiddenAlatStandar;
        } else {
            // Fallback jika hidden input kosong
            $standardParts[] = 'CRM Buffer pH, Merck, 4, 7, & 10';
        }
        
        // Tambahkan checkbox jika ada
        if (is_array($checkboxAlatStandar) && count($checkboxAlatStandar) > 0) {
            $checkboxValues = implode(", ", $checkboxAlatStandar);
            $standardParts[] = $checkboxValues;
        }
        
        // Gabungkan kedua bagian
        $standardValue = implode("; ", $standardParts);
        $source = 'combined';
        
        \Log::info('🔧 Alat standar kombinasi (update):', [
            'hidden' => $hiddenAlatStandar,
            'checkbox' => $checkboxAlatStandar,
            'combined_result' => $standardValue
        ]);

        // ==================================================================
        // 3. PROSES NAMA KALIBRATOR DAN PEMERIKSA
        // ==================================================================
        $namaKalibrator = trim($request->calibrated_by ?? '');
        $namaPemeriksa = trim($request->verified_by ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);

        // ==================================================================
        // 4. UPDATE HEAD PH METER
        // ==================================================================
        $head = HeadPhMeter::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📊 Head PhMeter BEFORE update:', [
            'head_exists' => $head ? true : false,
            'head_id' => $head->id ?? null,
            'certificate_id_before' => $head->certificate_id ?? null,
        ]);
        
        $headData = [
            'certificate_id' => $finalCertificateId,
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-40',
        ];
        
        if ($head) {
            $head->update($headData);
            $head->refresh();
            \Log::info('✅ HeadPhMeter updated:', ['head_id' => $head->id]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadPhMeter::create($headData);
            \Log::info('✅ HeadPhMeter created:', ['head_id' => $head->id]);
        }
        
        \Log::info('✅ HeadPhMeter AFTER update:', [
            'head_id' => $head->id,
            'certificate_id_after' => $head->certificate_id,
        ]);

        // ==================================================================
        // 5. UPDATE DETAIL PH METER (5 TITIK UKUR)
        // ==================================================================
        \Log::info('📊 Updating DetailPhMeter data (5 titik ukur)...');
        
        // Hapus data lama
        $deletedCount = DetailPhMeter::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old detail records:', ['count' => $deletedCount]);
        
        $detailCount = 0;
        
        // Ambil data dari request (sesuai dengan name input di tabel edit)
        $nilaiBufferArray = $request->input('nilaiBuffer', []);
        $rep01Array = $request->input('rep01', []);
        $rep02Array = $request->input('rep02', []);
        $rep03Array = $request->input('rep03', []);
        $rep04Array = $request->input('rep04', []);
        $rep05Array = $request->input('rep05', []);
        $resolusiArray = $request->input('Resolusi', []);
        $tBufferArray = $request->input('TBuffer', []);
        
        \Log::info('📊 Data arrays received:', [
            'nilaiBuffer_count' => count($nilaiBufferArray),
            'rep01_count' => count($rep01Array),
            'rep02_count' => count($rep02Array),
            'rep03_count' => count($rep03Array),
            'rep04_count' => count($rep04Array),
            'rep05_count' => count($rep05Array),
            'resolusi_count' => count($resolusiArray),
            'tBuffer_count' => count($tBufferArray),
        ]);
        
        // Proses 5 titik ukur (sesuai form HTML)
        for ($i = 0; $i < 5; $i++) {
            // Ambil data dari array
            $buffer = $nilaiBufferArray[$i] ?? null;
            $pembacaan_1 = $rep01Array[$i] ?? null;
            $pembacaan_2 = $rep02Array[$i] ?? null;
            $pembacaan_3 = $rep03Array[$i] ?? null;
            $pembacaan_4 = $rep04Array[$i] ?? null;
            $pembacaan_5 = $rep05Array[$i] ?? null;
            $resolusi = $resolusiArray[$i] ?? null;
            $suhu = $tBufferArray[$i] ?? null;
            
            \Log::debug("🔍 Row " . ($i + 1) . " data from request (update):", [
                'buffer' => $buffer,
                'pembacaan_1' => $pembacaan_1,
                'pembacaan_2' => $pembacaan_2,
                'pembacaan_3' => $pembacaan_3,
                'pembacaan_4' => $pembacaan_4,
                'pembacaan_5' => $pembacaan_5,
                'resolusi' => $resolusi,
                'suhu' => $suhu,
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($buffer) || 
                      !empty($pembacaan_1) || !empty($pembacaan_2) || !empty($pembacaan_3) || 
                      !empty($pembacaan_4) || !empty($pembacaan_5) || 
                      !empty($resolusi) || !empty($suhu);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'certificate_id' => $finalCertificateId,
                    'nilaiBuffer' => $buffer,
                    'rep01' => $pembacaan_1,
                    'rep02' => $pembacaan_2,
                    'rep03' => $pembacaan_3,
                    'rep04' => $pembacaan_4,
                    'rep05' => $pembacaan_5,
                    'Resolusi' => $resolusi,
                    'TBuffer' => $suhu,
                ];
                
                \Log::debug("💾 Saving DetailPhMeter row " . ($i + 1) . " (update):", $detailData);
                
                DetailPhMeter::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ Saved pH Meter row " . ($i + 1) . " (update)");
            } else {
                \Log::debug("⏭️ Skipping row " . ($i + 1) . " - no data");
            }
        }
        
        \Log::info("✅ Updated {$detailCount} DetailPhMeter records");

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi (update):', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa (update):', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        // Pastikan certificate_id di calibration juga terupdate
        if (!empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data', $updateData);
        }

        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailPhMeter::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (pH Meter):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $finalCertificateId,
            'certificate_id_source' => $certificateId ? 'parameter' : ($calibration->certificate_id ? 'calibration' : 'existing_data'),
            'alat_standar' => $standardValue,
            'alat_standar_source' => $source,
            'hidden_alat_standar' => $hiddenAlatStandar,
            'checkbox_alat_standar' => $checkboxAlatStandar,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updatePhMeter COMPLETED');
        
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePhMeter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'certificate_id' => $certificateId ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data pH Meter: " . $e->getMessage());
    }
}



private function storeTachometer($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeTachometer', [
            'calibration_id' => $calibration->id,
            'tab_id' => $tabId
        ]);
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Ambil alat standar dari checkbox dengan dukungan tab
        $alatStandarArray = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        } elseif ($alatStandarArray) {
            $alatStandar[] = $alatStandarArray;
        }
        
        // Coba juga dengan format alat_standar_1, alat_standar_2, dll
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', [
            'alat_standar' => $standardValue,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. PROSES NAMA KALIBRATOR DAN PEMERIKSA (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $namaKalibrator = trim($this->getRequestValue($request, 'calibrated_by', $tabId) ?? '');
        $namaPemeriksa = trim($this->getRequestValue($request, 'verified_by', $tabId) ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);

        // ==================================================================
        // 3. SIMPAN KE HEAD TACHOMETER
        // ==================================================================
        $head = HeadTachometer::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-48',
            'satuan_unit' => $this->getRequestValue($request, 'satuan_unit', $tabId),
        ]);

        \Log::info('✅ HeadTachometer saved:', ['head_id' => $head->id]);

        // ==================================================================
        // 4. SIMPAN DETAIL TACHOMETER (BERDASARKAN $jumlah_baris DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving DetailTachometer data...');
        $detailCount = 0;
        
        // Tentukan jumlah baris (dari form atau default)
        $jumlahBaris = (int)($this->getRequestValue($request, 'jumlah_baris', $tabId) ?? 12);
        
        \Log::info('📝 Jumlah baris tachometer:', ['jumlah_baris' => $jumlahBaris]);
        
        // Proses setiap baris
        for ($row = 1; $row <= $jumlahBaris; $row++) {
            // Ambil data dari input form dengan dukungan tab
            $nominal = $this->getRequestValue($request, "nominal_{$row}", $tabId);
            $pembacaan_1 = $this->getRequestValue($request, "pembacaan_{$row}_1", $tabId);
            $pembacaan_2 = $this->getRequestValue($request, "pembacaan_{$row}_2", $tabId);
            $pembacaan_3 = $this->getRequestValue($request, "pembacaan_{$row}_3", $tabId);
            $pembacaan_4 = $this->getRequestValue($request, "pembacaan_{$row}_4", $tabId);
            $pembacaan_5 = $this->getRequestValue($request, "pembacaan_{$row}_5", $tabId);
            $resolusi = $this->getRequestValue($request, "resolusi_{$row}", $tabId);
            
            \Log::debug("🔍 Row {$row} data from request:", [
                'nominal' => $nominal,
                'pembacaan_1' => $pembacaan_1,
                'pembacaan_2' => $pembacaan_2,
                'pembacaan_3' => $pembacaan_3,
                'pembacaan_4' => $pembacaan_4,
                'pembacaan_5' => $pembacaan_5,
                'resolusi' => $resolusi,
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($nominal) || 
                      !empty($pembacaan_1) || !empty($pembacaan_2) || !empty($pembacaan_3) || 
                      !empty($pembacaan_4) || !empty($pembacaan_5) || 
                      !empty($resolusi);
            
            if ($hasData) {
                // MAPPING KE MODEL DetailTachometer
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_tachometer_id' => $head->id,
                    'nilaiStandard' => $nominal,
                    'rep01' => $pembacaan_1,
                    'rep02' => $pembacaan_2,
                    'rep03' => $pembacaan_3,
                    'rep04' => $pembacaan_4,
                    'rep05' => $pembacaan_5,
                    'resolusiAlat' => $resolusi,
                ];
                
                \Log::debug("💾 Saving DetailTachometer row {$row}:", $detailData);
                
                DetailTachometer::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ Saved Tachometer row {$row}");
            } else {
                \Log::debug("⏭️ Skipping row {$row} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailTachometer records");

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
        }
        
        // Update satuan jika ada (sesuai input "Unit (......)")
        $unitTachometer = $this->getRequestValue($request, 'unit_tachometer', $tabId);
        if ($unitTachometer) {
            $updateData['unit'] = $unitTachometer;
            \Log::info('📏 Satuan tachometer:', ['unit' => $unitTachometer]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailTachometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Tachometer):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'total_rows' => $jumlahBaris,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $standardValue,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
            'unit' => $calibration->unit ?? null,
        ]);

        \Log::info('🎉 storeTachometer COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTachometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailTachometer::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Tachometer: " . $e->getMessage());
    }
}

private function updateTachometer($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateTachometer');
        \Log::info('📝 Updating Tachometer data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headTachometer;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - HANYA DARI CHECKBOX INPUTAN
        // ==================================================================
        
        // Ambil checkbox array (pilihan user)
        $checkboxAlatStandar = $request->input('alat_standar', []);
        \Log::info('🔧 Checkbox alat standar:', ['checkbox_values' => $checkboxAlatStandar]);
        
        // HANYA gunakan checkbox yang dipilih
        if (is_array($checkboxAlatStandar) && count($checkboxAlatStandar) > 0) {
            $standardValue = implode(", ", $checkboxAlatStandar);
            \Log::info('🔧 Menggunakan alat standar dari checkbox user:', ['alat_standar' => $standardValue]);
        } else {
            $standardValue = '';
            \Log::info('🔧 Tidak ada alat standar yang dipilih');
        }
        
        // ==================================================================
        // 2. PROSES NAMA KALIBRATOR DAN PEMERIKSA
        // ==================================================================
        $namaKalibrator = trim($request->calibrated_by ?? '');
        $namaPemeriksa = trim($request->verified_by ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);
        
        // ==================================================================
        // 3. UPDATE ATAU CREATE HEAD TACHOMETER
        // ==================================================================
        $head = HeadTachometer::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-48',
            'satuan_unit' => $request->satuan_unit,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadTachometer updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadTachometer::create($headData);
            \Log::info('➕ HeadTachometer created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 4. UPDATE DETAIL TACHOMETER - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating DetailTachometer data...');
        
        // Hapus data lama terlebih dahulu
        $deletedDetails = DetailTachometer::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old detail records");
        
        $detailCount = 0;
        
        // Tentukan jumlah baris (dari form atau default)
        $jumlahBaris = $request->jumlah_baris ?? 12;
        
        \Log::info('📝 Jumlah baris tachometer:', ['jumlah_baris' => $jumlahBaris]);
        
        // Proses setiap baris - LANGSUNG TANPA FORMAT
        for ($row = 1; $row <= $jumlahBaris; $row++) {
            // Ambil data dari input form - LANGSUNG TANPA FORMAT
            $nominal = $request->input("nominal_{$row}");
            $pembacaan_1 = $request->input("pembacaan_{$row}_1");
            $pembacaan_2 = $request->input("pembacaan_{$row}_2");
            $pembacaan_3 = $request->input("pembacaan_{$row}_3");
            $pembacaan_4 = $request->input("pembacaan_{$row}_4");
            $pembacaan_5 = $request->input("pembacaan_{$row}_5");
            $resolusi = $request->input("resolusi_{$row}");
            
            \Log::debug("🔍 Row {$row} data from request:", [
                'nominal' => $nominal,
                'pembacaan_1' => $pembacaan_1,
                'pembacaan_2' => $pembacaan_2,
                'pembacaan_3' => $pembacaan_3,
                'pembacaan_4' => $pembacaan_4,
                'pembacaan_5' => $pembacaan_5,
                'resolusi' => $resolusi,
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($nominal) || 
                      !empty($pembacaan_1) || !empty($pembacaan_2) || !empty($pembacaan_3) || 
                      !empty($pembacaan_4) || !empty($pembacaan_5) || 
                      !empty($resolusi);
            
            if ($hasData) {
                // Mapping ke model DetailTachometer - LANGSUNG TANPA FORMAT
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'nilaiStandard' => $nominal,           // LANGSUNG, tanpa format
                    'rep01' => $pembacaan_1,               // LANGSUNG, tanpa format
                    'rep02' => $pembacaan_2,               // LANGSUNG, tanpa format
                    'rep03' => $pembacaan_3,               // LANGSUNG, tanpa format
                    'rep04' => $pembacaan_4,               // LANGSUNG, tanpa format
                    'rep05' => $pembacaan_5,               // LANGSUNG, tanpa format
                    'resolusiAlat' => $resolusi,           // LANGSUNG, tanpa format
                ];
                
                \Log::debug("💾 Saving DetailTachometer row {$row}:", $detailData);
                
                DetailTachometer::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ Saved Tachometer row {$row}");
            } else {
                \Log::debug("⏭️ Skipping row {$row} - no data");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailTachometer records");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        // Update uncertainty dan keterangan (jika ada)
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        // Update satuan jika ada (sesuai input "Unit (......)")
        if ($request->filled('unit_tachometer')) {
            $updateData['unit'] = $request->unit_tachometer;
            \Log::info('📏 Satuan tachometer:', ['unit' => $request->unit_tachometer]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headTachometer;
        $savedDetailCount = DetailTachometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Tachometer):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'total_rows' => $jumlahBaris,
            'alat_standar' => $standardValue,
            'satuan_unit' => $request->satuan_unit,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
            'nama_alat' => $calibration->namaAlat,
        ]);
        
        \Log::info('🎉 updateTachometer COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTachometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Tachometer: " . $e->getMessage());
    }
}

private function storePinGauge($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storePinGauge =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI (LOOPING SEMUA KEMUNGKINAN TAB)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                // Format dengan double formIndex dan tab
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                
                // Format tanpa tab suffix
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        // ==================================================================
        // 3. LOOP UNTUK SETIAP FORM
        // ==================================================================
        $headsUpdated = 0;
        $firstHead = null;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex}");
            \Log::info("=========================================");
            
            // ==============================================================
            // 3.1. PROSES ALAT STANDAR - HANYA DARI CHECKBOX INPUTAN (PER FORM)
            // ==============================================================
            $checkboxAlatStandar = $findArrayValue('alat_standar', $formIndex);
            
            // Fallback: jika kosong dan form 1, coba dari alat_standar biasa
            if (empty($checkboxAlatStandar) && $formIndex == 1) {
                $checkboxAlatStandar = $request->input('alat_standar', []);
                if (!is_array($checkboxAlatStandar)) {
                    $checkboxAlatStandar = [$checkboxAlatStandar];
                }
            }
            
            if (!is_array($checkboxAlatStandar)) {
                $checkboxAlatStandar = [$checkboxAlatStandar];
            }
            
            \Log::info("🔧 Checkbox alat standar form {$formIndex}:", [
                'checkbox_values' => $checkboxAlatStandar
            ]);
            
            // HANYA gunakan checkbox yang dipilih
            if (!empty($checkboxAlatStandar)) {
                $checkboxValues = array_filter($checkboxAlatStandar, function($value) {
                    return !empty($value);
                });
                $standardValue = implode(", ", $checkboxValues);
                \Log::info("🔧 Menggunakan alat standar dari checkbox form {$formIndex}:", ['alat_standar' => $standardValue]);
            } else {
                $standardValue = '';
                \Log::info("🔧 Tidak ada alat standar yang dipilih di form {$formIndex}");
            }
            
            // ==============================================================
            // 3.2. PROSES NAMA KALIBRATOR DAN PEMERIKSA (PER FORM)
            // ==============================================================
            $namaKalibrator = trim($findValue('calibrated_by', $formIndex) ?? '');
            $namaPemeriksa = trim($findValue('verified_by', $formIndex) ?? '');
            
            \Log::info("👤 Nama Kalibrator form {$formIndex}:", ['nama' => $namaKalibrator]);
            \Log::info("👤 Nama Pemeriksa form {$formIndex}:", ['nama' => $namaPemeriksa]);
            
            // ==============================================================
            // 3.3. SIMPAN KE HEAD PIN GAUGE (PER FORM)
            // ==============================================================
            $head = HeadPinGauge::updateOrCreate(
                [
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex
                ],
                [
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-49',
                ]
            );
            
            if ($firstHead === null) {
                $firstHead = $head;
            }
            $headsUpdated++;
            
            \Log::info("✅ HeadPinGauge saved for form {$formIndex}:", [
                'head_id' => $head->id,
                'standard' => $standardValue
            ]);
            
            // ==============================================================
            // 3.4. SIMPAN DETAIL PIN GAUGE (22 BARIS PER FORM)
            // ==============================================================
            \Log::info("📊 Saving DetailPinGauge data for form {$formIndex}...");
            $detailCount = 0;
            
            // PIN GAUGE selalu 22 baris (1-22)
            $jumlahBaris = 22;
            
            for ($row = 1; $row <= $jumlahBaris; $row++) {
                // 🔥 FIX: Ambil nominal LANGSUNG dari key yang benar (jangan lewat $findValue)
                // agar tidak "bocor" ke form lain.
                // Format view Create: form_{formIndex}_nominal_{formIndex}_{row}_tab{tab}
                //                     nominal_{formIndex}_{row} (sebelum ditambah prefix JS)
                $nominal = $request->input("form_{$formIndex}_nominal_{$formIndex}_{$row}_tab1");
                if ($nominal === null || $nominal === '') {
                    $nominal = $request->input("form_{$formIndex}_nominal_{$formIndex}_{$row}");
                }
                if ($nominal === null || $nominal === '') {
                    $nominal = $request->input("nominal_{$formIndex}_{$row}_tab1");
                }
                if ($nominal === null || $nominal === '') {
                    $nominal = $request->input("nominal_{$formIndex}_{$row}");
                }
                if ($nominal === null || $nominal === '') {
                    $nominal = $request->input("form_{$formIndex}_titikUkur_{$formIndex}_" . ($row - 1));
                }
                if ($nominal === null || $nominal === '') {
                    $nominal = $request->input("titikUkur_{$formIndex}_" . ($row - 1));
                }
                
                // Untuk kolom lainnya tetap pakai $findValue
                $atas1 = $findValue("atas_{$row}_1", $formIndex);
                if (empty($atas1)) {
                    $atas1 = $findValue("atas", $formIndex, [$row, 1]);
                }
                
                $tengah2 = $findValue("tengah_{$row}_2", $formIndex);
                if (empty($tengah2)) {
                    $tengah2 = $findValue("tengah", $formIndex, [$row, 2]);
                }
                
                $bawah3 = $findValue("bawah_{$row}_3", $formIndex);
                if (empty($bawah3)) {
                    $bawah3 = $findValue("bawah", $formIndex, [$row, 3]);
                }
                
                $atas4 = $findValue("atas_{$row}_4", $formIndex);
                if (empty($atas4)) {
                    $atas4 = $findValue("atas", $formIndex, [$row, 4]);
                }
                
                $tengah5 = $findValue("tengah_{$row}_5", $formIndex);
                if (empty($tengah5)) {
                    $tengah5 = $findValue("tengah", $formIndex, [$row, 5]);
                }
                
                $bawah6 = $findValue("bawah_{$row}_6", $formIndex);
                if (empty($bawah6)) {
                    $bawah6 = $findValue("bawah", $formIndex, [$row, 6]);
                }
                
                \Log::debug("🔍 Form {$formIndex} Row {$row} data:", [
                    'nominal' => $nominal,
                    'atas_1' => $atas1,
                    'tengah_2' => $tengah2,
                    'bawah_3' => $bawah3,
                    'atas_4' => $atas4,
                    'tengah_5' => $tengah5,
                    'bawah_6' => $bawah6,
                ]);
                
                // Cek apakah ada data untuk baris ini
                $hasData = !empty($nominal) || 
                          !empty($atas1) || !empty($tengah2) || !empty($bawah3) || 
                          !empty($atas4) || !empty($tengah5) || !empty($bawah6);
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $nominal,
                        'ulangan1' => $atas1,
                        'ulangan2' => $tengah2,
                        'ulangan3' => $bawah3,
                        'ulangan4' => $atas4,
                        'ulangan5' => $tengah5,
                        'ulangan6' => $bawah6,
                    ];
                    
                    \Log::debug("💾 Saving DetailPinGauge form {$formIndex} row {$row}:", $detailData);
                    
                    DetailPinGauge::updateOrCreate(
                        [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'titikUkur' => $nominal
                        ],
                        $detailData
                    );
                    $detailCount++;
                } else {
                    \Log::debug("⏭️ Skipping form {$formIndex} row {$row} - no data");
                }
            }
            
            \Log::info("✅ Saved {$detailCount} DetailPinGauge records for form {$formIndex}");
        }
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (HANYA DARI FORM 1)
        // ==================================================================
        $updateData = [];
        
        // Ambil data dari form 1
        $namaKalibrator = trim($findValue('calibrated_by', 1) ?? '');
        $namaPemeriksa = trim($findValue('verified_by', 1) ?? '');
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $findValue('uncertainty', 1);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $findValue('conclusion', 1) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Update satuan (unit_pin_gauge)
        $unitPinGauge = $findValue('unit_pin_gauge', 1);
        if (!empty($unitPinGauge)) {
            $updateData['unit'] = $unitPinGauge;
            \Log::info('📏 Satuan pin gauge:', ['unit' => $unitPinGauge]);
        }
        
        // Update kondisi lingkungan
        $environmentData = [];
        
        $temperature = $findValue('temperature', 1);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $findValue('humidity', 1);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Kondisi lingkungan:', $environmentData);
        }
        
        // Update range (range_pin_gauge)
        $rangePinGauge = $findValue('range_pin_gauge', 1);
        if (!empty($rangePinGauge)) {
            $updateData['range'] = $rangePinGauge;
            \Log::info('📐 Range pin gauge:', ['range' => $rangePinGauge]);
        }
        
        // Update resolusi (resolution_pin_gauge)
        $resolutionPinGauge = $findValue('resolution_pin_gauge', 1);
        if (!empty($resolutionPinGauge)) {
            $updateData['resolution'] = $resolutionPinGauge;
            \Log::info('🔍 Resolusi pin gauge:', ['resolution' => $resolutionPinGauge]);
        }
        
        // Update rentang ukur min/max (jika ada)
        $rentangMin = $findValue('rentang_ukur_min', 1);
        if ($rentangMin !== null && $rentangMin !== '') {
            $updateData['range_min'] = $rentangMin;
        }
        
        $rentangMax = $findValue('rentang_ukur_max', 1);
        if ($rentangMax !== null && $rentangMax !== '') {
            $updateData['range_max'] = $rentangMax;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }
        
        // ==================================================================
        // 5. HAPUS DATA LAMA UNTUK FORM YANG TIDAK ADA
        // ==================================================================
        HeadPinGauge::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        DetailPinGauge::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        $allHeads = HeadPinGauge::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailPinGauge::where('calibration_id', $calibration->id)->get();
        
        \Log::info('📋 STORE SUMMARY (Pin Gauge):', [
            'calibration_id' => $calibration->id,
            'total_head_records' => $allHeads->count(),
            'head_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_detail_records' => $allDetails->count(),
            'detail_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'heads_updated' => $headsUpdated,
            'certificate_id' => $newCertificateId,
        ]);

        \Log::info('🎉 storePinGauge COMPLETED');
        
        // Return head pertama untuk backward compatibility
        return $firstHead ?? $allHeads->first();

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storePinGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'jumlah_form' => $jumlahForm ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        try {
            HeadPinGauge::where('calibration_id', $calibration->id)->delete();
            DetailPinGauge::where('calibration_id', $calibration->id)->delete();
        } catch (\Exception $rollbackError) {
            \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
        }
        
        throw new \Exception("Gagal menyimpan data Pin Gauge: " . $e->getMessage());
    }
}
private function updatePinGauge($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updatePinGauge =====', [
        'calibration_id' => $calibration->id,
        'new_certificate_id_received' => $newCertificateId,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. VALIDASI DAN AMBIL CERTIFICATE ID
        // ==================================================================
        $finalCertificateId = $newCertificateId;
        
        // Jika certificate_id dari parameter null, ambil dari calibration
        if (empty($finalCertificateId)) {
            $finalCertificateId = $calibration->certificate_id;
            \Log::info('📋 Mengambil certificate_id dari calibration:', [
                'certificate_id' => $finalCertificateId
            ]);
        }
        
        // Jika masih null, ambil dari head yang sudah ada di database
        if (empty($finalCertificateId)) {
            $existingHead = HeadPinGauge::where('calibration_id', $calibration->id)->first();
            if ($existingHead && !empty($existingHead->certificate_id)) {
                $finalCertificateId = $existingHead->certificate_id;
                \Log::info('📋 Mengambil certificate_id dari existing head:', [
                    'certificate_id' => $finalCertificateId,
                    'head_id' => $existingHead->id
                ]);
            }
        }
        
        // Jika masih null, coba ambil dari detail
        if (empty($finalCertificateId)) {
            $existingDetail = DetailPinGauge::where('calibration_id', $calibration->id)->first();
            if ($existingDetail && !empty($existingDetail->certificate_id)) {
                $finalCertificateId = $existingDetail->certificate_id;
                \Log::info('📋 Mengambil certificate_id dari existing detail:', [
                    'certificate_id' => $finalCertificateId
                ]);
            }
        }
        
        // Jika masih null, throw error
        if (empty($finalCertificateId)) {
            \Log::error('❌ Certificate ID tidak ditemukan untuk Pin Gauge update', [
                'calibration_id' => $calibration->id,
                'certificate_id_from_param' => $newCertificateId,
                'certificate_id_from_calibration' => $calibration->certificate_id
            ]);
            throw new \Exception('Certificate ID is required for Pin Gauge update');
        }
        
        // ==================================================================
        // 1. AMBIL JUMLAH FORM DARI REQUEST
        // ==================================================================
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Pin Gauge - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'certificate_id' => $finalCertificateId
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI (LOOPING SEMUA KEMUNGKINAN TAB)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        // ==================================================================
        // 3. LOOP UNTUK SETIAP FORM
        // ==================================================================
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex} (UPDATE)");
            \Log::info("=========================================");
            
            // ==============================================================
            // 3.1. PROSES ALAT STANDAR - HANYA DARI CHECKBOX INPUTAN (PER FORM)
            // ==============================================================
            $checkboxAlatStandar = $findArrayValue('alat_standar', $formIndex);
            
            // Fallback: jika kosong dan form 1, coba dari alat_standar biasa
            if (empty($checkboxAlatStandar) && $formIndex == 1) {
                $checkboxAlatStandar = $request->input('alat_standar', []);
                if (!is_array($checkboxAlatStandar)) {
                    $checkboxAlatStandar = [$checkboxAlatStandar];
                }
            }
            
            if (!is_array($checkboxAlatStandar)) {
                $checkboxAlatStandar = [$checkboxAlatStandar];
            }
            
            \Log::info("🔧 Checkbox alat standar form {$formIndex}:", [
                'checkbox_values' => $checkboxAlatStandar
            ]);
            
            // HANYA gunakan checkbox yang dipilih
            if (!empty($checkboxAlatStandar)) {
                $checkboxValues = array_filter($checkboxAlatStandar, function($value) {
                    return !empty($value);
                });
                $standardValue = implode(", ", $checkboxValues);
                \Log::info("🔧 Menggunakan alat standar dari checkbox form {$formIndex}:", ['alat_standar' => $standardValue]);
            } else {
                $standardValue = '';
                \Log::info("🔧 Tidak ada alat standar yang dipilih di form {$formIndex}");
            }
            
            // ==============================================================
            // 3.2. PROSES NAMA KALIBRATOR DAN PEMERIKSA (PER FORM)
            // ==============================================================
            $namaKalibrator = trim($findValue('calibrated_by', $formIndex) ?? '');
            $namaPemeriksa = trim($findValue('verified_by', $formIndex) ?? '');
            
            \Log::info("👤 Nama Kalibrator form {$formIndex}:", ['nama' => $namaKalibrator]);
            \Log::info("👤 Nama Pemeriksa form {$formIndex}:", ['nama' => $namaPemeriksa]);
            
            // ==============================================================
            // 3.3. UPDATE HEAD PIN GAUGE (PER FORM)
            // ==============================================================
            $head = HeadPinGauge::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            \Log::info("📊 Head PinGauge BEFORE update form {$formIndex}:", [
                'head_exists' => $head ? true : false,
                'head_id' => $head->id ?? null,
                'certificate_id_before' => $head->certificate_id ?? null,
            ]);
            
            $headData = [
                'certificate_id' => $finalCertificateId,
                'standard' => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-49',
            ];
            
            if ($head) {
                $head->update($headData);
                $head->refresh();
                \Log::info("✅ HeadPinGauge updated form {$formIndex}:", ['head_id' => $head->id]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $head = HeadPinGauge::create($headData);
                \Log::info("➕ HeadPinGauge created form {$formIndex}:", ['head_id' => $head->id]);
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadPinGauge::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
                // ==================================================================
        // 4. UPDATE DETAIL PIN GAUGE (22 BARIS PER FORM)
        // ==================================================================
        
        // Hapus data lama untuk semua form
        $deletedCount = DetailPinGauge::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old detail records:', ['count' => $deletedCount]);
        
        $totalDetailCount = 0;
        $jumlahBaris = 22;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex} (UPDATE)");
            
            // 🔥 AMBIL ARRAY DARI REQUEST SESUAI NAME DI VIEW
            // View mengirim: titikUkur_{formIndex}[], ulangan1_{formIndex}[], ulangan2_{formIndex}[], dst.
            $titikUkurArray = $request->input("titikUkur_{$formIndex}", []);
            $ulangan1Array  = $request->input("ulangan1_{$formIndex}", []);
            $ulangan2Array  = $request->input("ulangan2_{$formIndex}", []);
            $ulangan3Array  = $request->input("ulangan3_{$formIndex}", []);
            $ulangan4Array  = $request->input("ulangan4_{$formIndex}", []);
            $ulangan5Array  = $request->input("ulangan5_{$formIndex}", []);
            $ulangan6Array  = $request->input("ulangan6_{$formIndex}", []);
            
            // Fallback: coba format tanpa formIndex (untuk backward compatibility / form tunggal)
            if (empty($titikUkurArray) && $formIndex == 1) {
                $titikUkurArray = $request->input("titikUkur", []);
                $ulangan1Array  = $request->input("ulangan1", []);
                $ulangan2Array  = $request->input("ulangan2", []);
                $ulangan3Array  = $request->input("ulangan3", []);
                $ulangan4Array  = $request->input("ulangan4", []);
                $ulangan5Array  = $request->input("ulangan5", []);
                $ulangan6Array  = $request->input("ulangan6", []);
                \Log::info("Using fallback array format for form {$formIndex}");
            }
            
            \Log::info("📊 Data arrays form {$formIndex}:", [
                'titikUkur_count' => count($titikUkurArray),
                'ulangan1_count' => count($ulangan1Array),
                'ulangan2_count' => count($ulangan2Array),
                'ulangan3_count' => count($ulangan3Array),
                'ulangan4_count' => count($ulangan4Array),
                'ulangan5_count' => count($ulangan5Array),
                'ulangan6_count' => count($ulangan6Array),
            ]);
            
            // Pastikan array (kalau single value, bungkus jadi array)
            if (!is_array($titikUkurArray)) $titikUkurArray = [$titikUkurArray];
            if (!is_array($ulangan1Array))  $ulangan1Array  = [$ulangan1Array];
            if (!is_array($ulangan2Array))  $ulangan2Array  = [$ulangan2Array];
            if (!is_array($ulangan3Array))  $ulangan3Array  = [$ulangan3Array];
            if (!is_array($ulangan4Array))  $ulangan4Array  = [$ulangan4Array];
            if (!is_array($ulangan5Array))  $ulangan5Array  = [$ulangan5Array];
            if (!is_array($ulangan6Array))  $ulangan6Array  = [$ulangan6Array];
            
            // Loop 22 baris (index 0-21)
            for ($i = 0; $i < $jumlahBaris; $i++) {
                $nominal  = $titikUkurArray[$i] ?? null;
                $ulangan1 = $ulangan1Array[$i] ?? null;
                $ulangan2 = $ulangan2Array[$i] ?? null;
                $ulangan3 = $ulangan3Array[$i] ?? null;
                $ulangan4 = $ulangan4Array[$i] ?? null;
                $ulangan5 = $ulangan5Array[$i] ?? null;
                $ulangan6 = $ulangan6Array[$i] ?? null;
                
                \Log::debug("🔍 Form {$formIndex} Row " . ($i+1) . " data (update):", [
                    'nominal' => $nominal,
                    'ulangan1' => $ulangan1,
                    'ulangan2' => $ulangan2,
                    'ulangan3' => $ulangan3,
                    'ulangan4' => $ulangan4,
                    'ulangan5' => $ulangan5,
                    'ulangan6' => $ulangan6,
                ]);
                
                // Cek apakah ada data untuk baris ini
                $hasData = !empty(trim($nominal ?? '')) || 
                           !empty(trim($ulangan1 ?? '')) || 
                           !empty(trim($ulangan2 ?? '')) || 
                           !empty(trim($ulangan3 ?? '')) || 
                           !empty(trim($ulangan4 ?? '')) || 
                           !empty(trim($ulangan5 ?? '')) || 
                           !empty(trim($ulangan6 ?? ''));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'certificate_id' => $finalCertificateId,
                        'titikUkur' => $nominal,
                        'ulangan1' => $ulangan1,
                        'ulangan2' => $ulangan2,
                        'ulangan3' => $ulangan3,
                        'ulangan4' => $ulangan4,
                        'ulangan5' => $ulangan5,
                        'ulangan6' => $ulangan6,
                    ];
                    
                    \Log::debug("💾 Saving DetailPinGauge form {$formIndex} row " . ($i+1) . " (update):", $detailData);
                    
                    DetailPinGauge::create($detailData);
                    $totalDetailCount++;
                } else {
                    \Log::debug("⏭️ Skipping form {$formIndex} row " . ($i+1) . " - no data");
                }
            }
        }
        
        \Log::info("✅ Updated {$totalDetailCount} DetailPinGauge records");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN (HANYA DARI FORM 1)
        // ==================================================================
        $updateData = [];
        
        // Ambil data dari form 1
        $namaKalibrator = trim($findValue('calibrated_by', 1) ?? '');
        $namaPemeriksa = trim($findValue('verified_by', 1) ?? '');
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi (update):', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa (update):', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan global (jika ada)
        $uncertainty = $findValue('uncertainty', 1);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $findValue('conclusion', 1) ?? '';
        }
        
        // Update satuan jika ada
        $unitPinGauge = $findValue('unit_pin_gauge', 1);
        if (!empty($unitPinGauge)) {
            $updateData['unit'] = $unitPinGauge;
            \Log::info('📏 Satuan pin gauge (update):', ['unit' => $unitPinGauge]);
        }
        
        // Update kondisi lingkungan
        $environmentData = [];
        
        $temperature = $findValue('temperature', 1);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $findValue('humidity', 1);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Kondisi lingkungan (update):', $environmentData);
        }
        
        // Update range
        $rangePinGauge = $findValue('range_pin_gauge', 1);
        if (!empty($rangePinGauge)) {
            $updateData['range'] = $rangePinGauge;
            \Log::info('📐 Range pin gauge (update):', ['range' => $rangePinGauge]);
        }
        
        // Update resolusi
        $resolutionPinGauge = $findValue('resolution_pin_gauge', 1);
        if (!empty($resolutionPinGauge)) {
            $updateData['resolution'] = $resolutionPinGauge;
            \Log::info('🔍 Resolusi pin gauge (update):', ['resolution' => $resolutionPinGauge]);
        }
        
        // Update rentang ukur min/max
        $rentangMin = $findValue('rentang_ukur_min', 1);
        if ($rentangMin !== null && $rentangMin !== '') {
            $updateData['range_min'] = $rentangMin;
        }
        
        $rentangMax = $findValue('rentang_ukur_max', 1);
        if ($rentangMax !== null && $rentangMax !== '') {
            $updateData['range_max'] = $rentangMax;
        }
        
        // Pastikan certificate_id di calibration juga terupdate
        if (!empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
        }
        
        // Update jumlah_form
        $updateData['jumlah_form'] = $jumlahForm;
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data', $updateData);
        }
        
        // Refresh calibration
        $calibration->refresh();
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $allHeads = HeadPinGauge::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailPinGauge::where('calibration_id', $calibration->id)->get();
        
        \Log::info('📋 UPDATE SUMMARY (Pin Gauge):', [
            'calibration_id' => $calibration->id,
            'total_head_records' => $allHeads->count(),
            'head_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_detail_records' => $allDetails->count(),
            'detail_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'certificate_id' => $finalCertificateId,
            'certificate_id_source' => $newCertificateId ? 'parameter' : ($calibration->certificate_id ? 'calibration' : 'existing_data'),
        ]);
        
        \Log::info('🎉 updatePinGauge COMPLETED');
        
        // Return head pertama untuk backward compatibility
        return $allHeads->first();
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePinGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'new_certificate_id' => $newCertificateId ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Pin Gauge: " . $e->getMessage());
    }
}
 

    private function storeViscoCup($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeViscoCup');
        
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeViscoCup called with tab_id:', ['tab_id' => $tabId]);
        
        // ==============================================================
        // DEBUG: TAMPILKAN SEMUA DATA REQUEST
        // ==============================================================
        \Log::info('🔍 ALL REQUEST DATA:', $request->all());
        
        // ==============================================================
        // 1. PROSES ALAT STANDAR
        // ==============================================================
        
        // Ambil type dari request
        $viscosityTypes = $request->input('viscosity_type', []);
        if (!is_array($viscosityTypes)) {
            $viscosityTypes = [$viscosityTypes];
        }
        $viscosityTypes = array_filter($viscosityTypes);
        
        $stopwatchTypes = $request->input('stopwatch_type', []);
        if (!is_array($stopwatchTypes)) {
            $stopwatchTypes = [$stopwatchTypes];
        }
        $stopwatchTypes = array_filter($stopwatchTypes);
        
        $thermometerTypes = $request->input('thermometer_type', []);
        if (!is_array($thermometerTypes)) {
            $thermometerTypes = [$thermometerTypes];
        }
        $thermometerTypes = array_filter($thermometerTypes);
        
        \Log::info('🔧 Types selected:', [
            'viscosity_types' => $viscosityTypes,
            'stopwatch_types' => $stopwatchTypes,
            'thermometer_types' => $thermometerTypes,
        ]);
        
        // ==============================================================
        // 2. BANGUN STANDARD VALUE
        // ==============================================================
        
        $standardParts = [];
        
        if (!empty($viscosityTypes)) {
            foreach ($viscosityTypes as $type) {
                $standardParts[] = 'Viscosity Standard Paragon ' . $type;
            }
        }
        
        if (!empty($stopwatchTypes)) {
            foreach ($stopwatchTypes as $type) {
                $standardParts[] = 'Digital Stopwatch ' . $type;
            }
        }
        
        if (!empty($thermometerTypes)) {
            foreach ($thermometerTypes as $type) {
                $standardParts[] = 'Thermometer ' . $type;
            }
        }
        
        $standardFinal = !empty($standardParts) ? implode(', ', $standardParts) : '';
        \Log::info('🔧 STANDARD FINAL:', ['standard' => $standardFinal]);
        
        // ==============================================================
        // 3. PROSES TYPE CUP DAN KODE NOMOR
        // ==============================================================
        
        $typeCupArray = $request->input('type_cup', []);
        if (!is_array($typeCupArray)) {
            $typeCupArray = [$typeCupArray];
        }
        $typeCupArray = array_filter($typeCupArray, function($value) {
            return !empty($value) && $value !== 'Others';
        });
        
        $kodeNomor = $request->input('kode_nomor', '');
        
        $othersInput = $request->input('others', '');
        $typeOtherInput = $request->input('type_other', '');
        
        $othersValue = '';
        if (!empty($typeOtherInput)) {
            $othersValue = $typeOtherInput;
            if (!in_array('Others', $typeCupArray)) {
                $typeCupArray[] = 'Others';
            }
        } elseif (!empty($othersInput) && $othersInput === 'Others') {
            $othersValue = $typeOtherInput;
            if (!in_array('Others', $typeCupArray)) {
                $typeCupArray[] = 'Others';
            }
        }
        
        $typeCupCombined = !empty($typeCupArray) ? implode(', ', $typeCupArray) : '';
        
        \Log::info('🥤 AddViscoCup Data:', [
            'type_cup_array' => $typeCupArray,
            'type_cup_combined' => $typeCupCombined,
            'kode_nomor' => $kodeNomor,
            'others_value' => $othersValue,
        ]);
        
        AddViscoCup::updateOrCreate(
            ['calibration_id' => $calibration->id],
            [
                'type' => $typeCupCombined,
                'kodeNomor' => $kodeNomor,
                'others' => $othersValue,
            ]
        );
        \Log::info('✅ AddViscoCup saved/updated');
        
        // ==============================================================
        // 4. AMBIL DATA LAINNYA
        // ==============================================================
        
        $catatan = $request->input('catatan_penting', '');
        $namaKalibrator = $request->input('calibrated_by', '');
        $namaPemeriksa = $request->input('verified_by', '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);

        // ==============================================================
        // 5. SIMPAN KE HEAD VISCOCUP
        // ==============================================================
        
        $head = HeadViscoCup::updateOrCreate(
            ['calibration_id' => $calibration->id],
            [
                'certificate_id' => $certificateId,
                'standard' => $standardFinal,
                'calibrationMethod' => 'PAS-IK1102-43B',
                'catatan' => $catatan,
            ]
        );

        \Log::info('✅ HeadViscoCup saved:', [
            'head_id' => $head->id,
            'standard' => $standardFinal,
            'catatan' => $catatan
        ]);

        // ==============================================================
        // 6. SIMPAN DETAIL VISCOCUP - PERBAIKAN!
        // ==============================================================
        \Log::info('📊 Saving DetailViscoCup data...');
        
        // Hapus detail lama
        DetailViscoCup::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        // Loop untuk 3 baris data (1-3)
        for ($row = 1; $row <= 3; $row++) {
            // 🔥 PERBAIKAN: Gunakan nama field dengan suffix _tab1
            $nilaiStandar = $request->input("kode_nilai_{$row}_tab1", '');
            $ulangan1 = $request->input("stopwatch_{$row}_1_tab1", '');
            $ulangan2 = $request->input("stopwatch_{$row}_2_tab1", '');
            $ulangan3 = $request->input("stopwatch_{$row}_3_tab1", '');
            $ulangan4 = $request->input("stopwatch_{$row}_4_tab1", '');
            $ulangan5 = $request->input("stopwatch_{$row}_5_tab1", '');
            $suhuCRM = $request->input("suhu_{$row}_tab1", '');
            
            // Log data yang diambil
            \Log::debug("📝 Row {$row} data:", [
                'nilaiStandar' => $nilaiStandar,
                'ulangan1' => $ulangan1,
                'ulangan2' => $ulangan2,
                'ulangan3' => $ulangan3,
                'ulangan4' => $ulangan4,
                'ulangan5' => $ulangan5,
                'suhuCRM' => $suhuCRM,
            ]);
            
            // Cek apakah ada data
            $hasData = !empty($nilaiStandar) || 
                      !empty($ulangan1) || !empty($ulangan2) || !empty($ulangan3) || 
                      !empty($ulangan4) || !empty($ulangan5) || !empty($suhuCRM);
            
            if ($hasData) {
                DetailViscoCup::create([
                    'calibration_id' => $calibration->id,
                    'nilaiStandar' => $nilaiStandar,
                    'ulangan1' => $ulangan1,
                    'ulangan2' => $ulangan2,
                    'ulangan3' => $ulangan3,
                    'ulangan4' => $ulangan4,
                    'ulangan5' => $ulangan5,
                    'suhuCRM' => $suhuCRM,
                ]);
                $detailCount++;
                \Log::debug("✅ Saved ViscoCup row {$row}");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailViscoCup records");

        // ==============================================================
        // 7. UPDATE CALIBRATION
        // ==============================================================
        $updateData = [];
        
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
        }
        
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', $updateData);
        }

        // ==============================================================
        // 8. LOG HASIL AKHIR
        // ==============================================================
        $savedDetailCount = DetailViscoCup::where('calibration_id', $calibration->id)->count();
        $addViscoCupCount = AddViscoCup::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (ViscoCup):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'add_visco_cup_records' => $addViscoCupCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'standard_value' => $standardFinal,
            'type_cup_combined' => $typeCupCombined,
            'kode_nomor' => $kodeNomor,
            'catatan' => $catatan,
        ]);

        \Log::info('🎉 storeViscoCup COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeViscoCup:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
        ]);
        
        throw new \Exception("Gagal menyimpan data ViscoCup: " . $e->getMessage());
    }
}
 private function updateViscoCup($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateViscoCup');
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headViscoCup;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR DAN TYPE
        // ==================================================================
        
        // Ambil semua alat standar yang dipilih
        $alatStandarArray = $request->alat_standar ?? [];
        \Log::info('🔧 Alat standar selected:', ['alat_standar_array' => $alatStandarArray]);
        
        // Untuk menyimpan semua type yang dipilih
        $selectedTypes = [];
        
        // Proses setiap alat standar yang dipilih
        foreach ($alatStandarArray as $alatStandar) {
            if ($alatStandar === 'Viscosity Standard Paragon') {
                $typeSelected = $request->viscosity_type ?? '';
                if (!empty($typeSelected)) {
                    $selectedTypes[] = $alatStandar . ' ' . $typeSelected;
                } else {
                    $selectedTypes[] = $alatStandar;
                }
                \Log::info('🔧 Viscosity type selected:', ['type' => $typeSelected]);
            } elseif ($alatStandar === 'Digital Stopwatch') {
                $typeSelected = $request->stopwatch_type ?? '';
                if (!empty($typeSelected)) {
                    $selectedTypes[] = $alatStandar . ' ' . $typeSelected;
                } else {
                    $selectedTypes[] = $alatStandar;
                }
                \Log::info('🔧 Stopwatch type selected:', ['type' => $typeSelected]);
            } elseif ($alatStandar === 'Thermometer') {
                $typeSelected = $request->thermometer_type ?? '';
                if (!empty($typeSelected)) {
                    $selectedTypes[] = $alatStandar . ' ' . $typeSelected;
                } else {
                    $selectedTypes[] = $alatStandar;
                }
                \Log::info('🔧 Thermometer type selected:', ['type' => $typeSelected]);
            }
        }
        
        // Gabungkan semua alat standar dengan separator (misalnya koma)
        $standardValue = implode(', ', $selectedTypes);
        
        \Log::info('📝 Combined standard value:', ['standard' => $standardValue]);
        
        // ==================================================================
        // 2. PROSES TYPE CUP DAN KODE NOMOR (untuk AddViscoCup) - TANPA FORMAT
        // ==================================================================
        
        // Kumpulkan semua pilihan type cup dalam array
        $typeCupArray = [];
        
        // 1. Cek radio button type_cup (bisa multiple karena mungkin array)
        $typeCupInput = $request->type_cup;
        
        if (is_array($typeCupInput)) {
            foreach ($typeCupInput as $type) {
                if (!empty($type) && $type !== 'Others') {
                    $typeCupArray[] = $type;
                }
            }
        } elseif (!empty($typeCupInput) && $typeCupInput !== 'Others') {
            $typeCupArray[] = $typeCupInput;
        }
        
        // 2. Cek jika ada Others yang dipilih
        $othersRadio = $request->others ?? '';
        $typeOtherInput = trim($request->type_other ?? '');
        $othersValue = '';
        
        if ($othersRadio === 'Others' && !empty($typeOtherInput)) {
            $othersValue = $typeOtherInput;
            if (!in_array('Others', $typeCupArray)) {
                $typeCupArray[] = 'Others';
            }
        } elseif (!empty($typeOtherInput) && $othersRadio !== 'Others') {
            $othersValue = $typeOtherInput;
            if (!in_array('Others', $typeCupArray)) {
                $typeCupArray[] = 'Others';
            }
        }
        
        $typeCupCombined = !empty($typeCupArray) ? implode(', ', $typeCupArray) : '';
        $kodeNomor = $request->kode_nomor ?? '';
        
        \Log::info('🥤 Update AddViscoCup Data:', [
            'type_cup_array' => $typeCupArray,
            'type_cup_combined' => $typeCupCombined,
            'kode_nomor' => $kodeNomor,
            'others_value' => $othersValue,
        ]);
        
        // Update or create AddViscoCup
        $addViscoCup = AddViscoCup::where('calibration_id', $calibration->id)->first();
        
        if (!empty($typeCupCombined) || !empty($kodeNomor) || !empty($othersValue)) {
            if ($addViscoCup) {
                $addViscoCup->update([
                    'type' => $typeCupCombined,
                    'kodeNomor' => $kodeNomor,
                    'others' => $othersValue,
                ]);
                \Log::info('✅ AddViscoCup updated');
            } else {
                AddViscoCup::create([
                    'calibration_id' => $calibration->id,
                    'type' => $typeCupCombined,
                    'kodeNomor' => $kodeNomor,
                    'others' => $othersValue,
                ]);
                \Log::info('✅ AddViscoCup created');
            }
        } elseif ($addViscoCup) {
            $addViscoCup->delete();
            \Log::info('✅ AddViscoCup deleted (no data)');
        }
        
        $catatan = trim($request->catatan_penting ?? '');
        $namaKalibrator = trim($request->calibrated_by ?? '');
        $namaPemeriksa = trim($request->verified_by ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);
        
        // ==================================================================
        // 3. UPDATE HEAD VISCOCUP
        // ==================================================================
        $head = HeadViscoCup::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $standardValue,
            'calibrationMethod' => 'PAS-IK1102-43B',
            'catatan' => $catatan,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ HeadViscoCup updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'standard' => $standardValue,
                'catatan' => $catatan
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadViscoCup::create($headData);
            \Log::info('✅ HeadViscoCup created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null,
                'standard' => $standardValue,
                'catatan' => $catatan
            ]);
        }
        
        // ==================================================================
        // 4. UPDATE DETAIL VISCOCUP - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating DetailViscoCup data...');
        
        // Delete existing details untuk calibration ini
        $detailDeleted = DetailViscoCup::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$detailDeleted} existing details");
        
        $detailCount = 0;
        
        // Proses 3 baris data - LANGSUNG TANPA FORMAT
        for ($row = 1; $row <= 3; $row++) {
            // Ambil data dari input form - LANGSUNG TANPA FORMAT
            $nilaiStandar = $request->input("kode_nilai_$row");
            $ulangan1 = $request->input("stopwatch_{$row}_1");
            $ulangan2 = $request->input("stopwatch_{$row}_2");
            $ulangan3 = $request->input("stopwatch_{$row}_3");
            $ulangan4 = $request->input("stopwatch_{$row}_4");
            $ulangan5 = $request->input("stopwatch_{$row}_5");
            $suhuCRM = $request->input("suhu_$row");
            
            $hasData = !empty($nilaiStandar) || 
                      !empty($ulangan1) || !empty($ulangan2) || !empty($ulangan3) || 
                      !empty($ulangan4) || !empty($ulangan5) || 
                      !empty($suhuCRM);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'nilaiStandar' => $nilaiStandar,  // LANGSUNG, tanpa format
                    'ulangan1' => $ulangan1,          // LANGSUNG, tanpa format
                    'ulangan2' => $ulangan2,          // LANGSUNG, tanpa format
                    'ulangan3' => $ulangan3,          // LANGSUNG, tanpa format
                    'ulangan4' => $ulangan4,          // LANGSUNG, tanpa format
                    'ulangan5' => $ulangan5,          // LANGSUNG, tanpa format
                    'suhuCRM' => $suhuCRM,            // LANGSUNG, tanpa format
                ];
                
                DetailViscoCup::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ Saved ViscoCup row {$row}");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailViscoCup records");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if ($request->filled('unit')) {
            $updateData['unit'] = $request->unit;
        }
        
        if ($request->filled('range')) {
            $updateData['range'] = $request->range;
        }
        
        $environmentData = [];
        if ($request->filled('temperature')) {
            $environmentData['temperature'] = $request->temperature;
        }
        if ($request->filled('humidity')) {
            $environmentData['humidity'] = $request->humidity;
        }
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headViscoCup;
        $savedDetailCount = DetailViscoCup::where('calibration_id', $calibration->id)->count();
        $addViscoCupCount = AddViscoCup::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (ViscoCup):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'add_visco_cup_records' => $addViscoCupCount,
            'standard_value' => $standardValue,
            'catatan' => $catatan,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
            'nama_alat' => $calibration->namaAlat,
        ]);
        
        \Log::info('🎉 updateViscoCup COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateViscoCup:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data ViscoCup: " . $e->getMessage());
    }
}
    private function storePlainLimitGauge($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('🔧 ===== START storePlainLimitGauge =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storePlainLimitGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandarArray = [];
        
        // Cari alat standar dari checkbox/select dengan berbagai format
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($alatStandar)) {
            foreach ($alatStandar as $value) {
                if ($value && !in_array($value, $alatStandarArray)) {
                    $alatStandarArray[] = $value;
                }
            }
        } elseif ($alatStandar) {
            $alatStandarArray[] = $alatStandar;
        }
        
        // Coba juga dengan format alat_standar_1, alat_standar_2, dll
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandarArray)) {
                $alatStandarArray[] = $value;
            }
        }
        
        // Ambil Gauge Block mm dengan dukungan tab
        $gaugeBlockMm = $this->getRequestValue($request, 'gauge_block_mm', $tabId);
        if ($gaugeBlockMm) {
            $alatStandarArray[] = "Gauge Block {$gaugeBlockMm} mm";
            \Log::info('📏 Gauge Block mm:', ['value' => $gaugeBlockMm]);
        }
        
        // Ambil Ring Gauge mm dengan dukungan tab
        $ringGaugeMm = $this->getRequestValue($request, 'ring_gauge_mm', $tabId);
        if ($ringGaugeMm) {
            $alatStandarArray[] = "Ring Gauge {$ringGaugeMm} mm";
            \Log::info('📏 Ring Gauge mm:', ['value' => $ringGaugeMm]);
        }
        
        $alatStandarString = !empty($alatStandarArray) ? implode(', ', $alatStandarArray) : '';
        
        \Log::info('📋 Final alat standar string:', [
            'alat_standar_string' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. AMBIL FIELD LAINNYA (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $catatan = $this->getRequestValue($request, 'catatan', $tabId);
        $satuanGo = $this->getRequestValue($request, 'satuan_go', $tabId);
        $satuanNoGo = $this->getRequestValue($request, 'satuan_no_go', $tabId);
        
        // ==================================================================
        // 3. SIMPAN KE HEAD PLAIN LIMIT GAUGE
        // ==================================================================
        $head = HeadPlainLimitGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-63',
            'catatan' => $catatan,
            'satuan_go' => $satuanGo,
            'satuan_no_go' => $satuanNoGo,
            'form_index' => 1,
        ]);
        
        \Log::info('✅ Head Plain Limit Gauge saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS (GO DAN NO GO) - DENGAN DUKUNGAN _tab
        // ==================================================================
        \Log::info('📊 Saving detail measurements...');
        
        // DATA GO
        $goNominal = $this->getRequestValue($request, 'go_nominal', $tabId);
        
        // POSISI ATAS GO
        $goAtasX1 = $this->getRequestValue($request, 'go_atas_x', $tabId);
        if (!$goAtasX1) {
            $goAtasX1 = $this->getRequestValue($request, 'go_atas_x1', $tabId);
        }
        
        $goAtasX2 = $this->getRequestValue($request, 'go_atas_x2', $tabId);
        $goAtasY1 = $this->getRequestValue($request, 'go_atas_y', $tabId);
        if (!$goAtasY1) {
            $goAtasY1 = $this->getRequestValue($request, 'go_atas_y1', $tabId);
        }
        
        $goAtasY2 = $this->getRequestValue($request, 'go_atas_y2', $tabId);
        
        // POSISI BAWAH GO
        $goBawahX1 = $this->getRequestValue($request, 'go_bawah_x', $tabId);
        if (!$goBawahX1) {
            $goBawahX1 = $this->getRequestValue($request, 'go_bawah_x1', $tabId);
        }
        
        $goBawahX2 = $this->getRequestValue($request, 'go_bawah_x2', $tabId);
        $goBawahY1 = $this->getRequestValue($request, 'go_bawah_y', $tabId);
        if (!$goBawahY1) {
            $goBawahY1 = $this->getRequestValue($request, 'go_bawah_y1', $tabId);
        }
        
        $goBawahY2 = $this->getRequestValue($request, 'go_bawah_y2', $tabId);
        
        // DATA NO GO
        $nogoNominal = $this->getRequestValue($request, 'nogo_nominal', $tabId);
        
        // SUMBU ATAS NO GO
        $nogoAtasX1 = $this->getRequestValue($request, 'nogo_atas_x', $tabId);
        if (!$nogoAtasX1) {
            $nogoAtasX1 = $this->getRequestValue($request, 'nogo_atas_x1', $tabId);
        }
        
        $nogoAtasX2 = $this->getRequestValue($request, 'nogo_atas_x2', $tabId);
        $nogoAtasY1 = $this->getRequestValue($request, 'nogo_atas_y', $tabId);
        if (!$nogoAtasY1) {
            $nogoAtasY1 = $this->getRequestValue($request, 'nogo_atas_y1', $tabId);
        }
        
        $nogoAtasY2 = $this->getRequestValue($request, 'nogo_atas_y2', $tabId);
        
        // SUMBU BAWAH NO GO
        $nogoBawahX1 = $this->getRequestValue($request, 'nogo_bawah_x', $tabId);
        if (!$nogoBawahX1) {
            $nogoBawahX1 = $this->getRequestValue($request, 'nogo_bawah_x1', $tabId);
        }
        
        $nogoBawahX2 = $this->getRequestValue($request, 'nogo_bawah_x2', $tabId);
        $nogoBawahY1 = $this->getRequestValue($request, 'nogo_bawah_y', $tabId);
        if (!$nogoBawahY1) {
            $nogoBawahY1 = $this->getRequestValue($request, 'nogo_bawah_y1', $tabId);
        }
        
        $nogoBawahY2 = $this->getRequestValue($request, 'nogo_bawah_y2', $tabId);
        
        $detailData = [
            'calibration_id' => $calibration->id,
            'form_index' => 1,
            'titikUkurGO' => $goNominal,
            'posisiAtasX1' => $goAtasX1,
            'posisiAtasX2' => $goAtasX2,
            'posisiAtasY1' => $goAtasY1,
            'posisiAtasY2' => $goAtasY2,
            'posisiBawahX1' => $goBawahX1,
            'posisiBawahX2' => $goBawahX2,
            'posisiBawahY1' => $goBawahY1,
            'posisiBawahY2' => $goBawahY2,
            'titikUkurNOGO' => $nogoNominal,
            'sumbuAtasX1' => $nogoAtasX1,
            'sumbuAtasX2' => $nogoAtasX2,
            'sumbuAtasY1' => $nogoAtasY1,
            'sumbuAtasY2' => $nogoAtasY2,
            'sumbuBawahX1' => $nogoBawahX1,
            'sumbuBawahX2' => $nogoBawahX2,
            'sumbuBawahY1' => $nogoBawahY1,
            'sumbuBawahY2' => $nogoBawahY2,
        ];
        
        \Log::info('📝 Saving detail measurement:', [
            'titikUkurGO' => $detailData['titikUkurGO'],
            'titikUkurNOGO' => $detailData['titikUkurNOGO']
        ]);
        
        DetailPlainLimitGauge::create($detailData);
        \Log::info('✅ Detail Plain Limit Gauge saved successfully');
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TTD (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('👤 Calibrated by saved:', ['name' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('👤 Verified by saved:', ['name' => $verifiedBy]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with signature data');
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (Plain Limit Gauge):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'satuan_go' => $satuanGo,
            'satuan_no_go' => $satuanNoGo,
        ]);
        
        \Log::info('🎉 storePlainLimitGauge COMPLETED');
        
    } catch (\Exception $e) {
        \Log::error('💥 Error storing Plain Limit Gauge data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

    private function updatePlainLimitGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updatePlainLimitGauge');
        \Log::info('📝 Updating Plain Limit Gauge data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headPlainLimitGauge;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        // Inisialisasi array untuk menyimpan alat standar
        $alatStandarArray = [];
        
        // Cek checkbox yang dipilih
        $alatStandar = $request->alat_standar ?? [];
        
        \Log::info('🔧 Alat standar selected for Plain Limit Gauge:', ['alat_standar' => $alatStandar]);

        // Get additional mm selections
        $gaugeBlockMm = $request->gauge_block_mm ?? '';
        $ringGaugeMm = $request->ring_gauge_mm ?? '';
        
        \Log::info('📏 Additional mm selections:', [
            'gauge_block_mm' => $gaugeBlockMm,
            'ring_gauge_mm' => $ringGaugeMm
        ]);

        // Proses checkbox untuk menambahkan ke array alat standar
        if (!empty($alatStandar)) {
            foreach ($alatStandar as $alat) {
                if (empty($alat)) continue;
                $alatStandarArray[] = $alat;
            }
        }

        // Tambahkan Gauge Block dengan ukuran mm jika dipilih
        if ($gaugeBlockMm) {
            $alatStandarArray[] = "Gauge Block {$gaugeBlockMm} mm";
        }

        // Tambahkan Ring Gauge dengan ukuran mm jika dipilih
        if ($ringGaugeMm) {
            $alatStandarArray[] = "Ring Gauge {$ringGaugeMm} mm";
        }

        // Hapus duplikat (jika ada)
        $alatStandarArray = array_unique($alatStandarArray);
        
        // Konversi array menjadi string dengan pemisah koma
        $alatStandarString = !empty($alatStandarArray) ? implode(', ', $alatStandarArray) : '';
        
        \Log::info('📋 Final alat standar string:', ['alat_standar_string' => $alatStandarString]);
        
        // ==================================================================
        // 2. UPDATE ATAU CREATE HEAD PLAIN LIMIT GAUGE
        // ==================================================================
        $head = HeadPlainLimitGauge::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-63',
            'catatan' => $request->catatan ?? '',
            'satuan_go' => $request->satuan_go ?? '',
            'satuan_no_go' => $request->satuan_no_go ?? '',
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ Head Plain Limit Gauge updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadPlainLimitGauge::create($headData);
            \Log::info('➕ Head Plain Limit Gauge created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL PLAIN LIMIT GAUGE - TANPA FORMAT NUMERIC
        // ==================================================================
        \Log::info('📊 Updating detail measurements...');
        
        // Data GO - LANGSUNG TANPA FORMAT
        $goData = [
            'calibration_id' => $calibration->id,
            'titikUkurGO' => $request->go_nominal,
            'posisiAtasX1' => $request->go_atas_x,
            'posisiAtasX2' => $request->go_atas_x2,
            'posisiAtasY1' => $request->go_atas_y,
            'posisiAtasY2' => $request->go_atas_y2,
            'posisiBawahX1' => $request->go_bawah_x,
            'posisiBawahX2' => $request->go_bawah_x2,
            'posisiBawahY1' => $request->go_bawah_y,
            'posisiBawahY2' => $request->go_bawah_y2,
        ];
        
        // Data NO GO - LANGSUNG TANPA FORMAT
        $nogoData = [
            'titikUkurNOGO' => $request->nogo_nominal,
            'sumbuAtasX1' => $request->nogo_atas_x,
            'sumbuAtasX2' => $request->nogo_atas_x2,
            'sumbuAtasY1' => $request->nogo_atas_y,
            'sumbuAtasY2' => $request->nogo_atas_y2,
            'sumbuBawahX1' => $request->nogo_bawah_x,
            'sumbuBawahX2' => $request->nogo_bawah_x2,
            'sumbuBawahY1' => $request->nogo_bawah_y,
            'sumbuBawahY2' => $request->nogo_bawah_y2,
        ];
        
        // Gabungkan data GO dan NO GO
        $detailData = array_merge($goData, $nogoData);
        
        \Log::info('📝 Saving detail measurement:', $detailData);
        
        // Cek apakah detail sudah ada
        $existingDetail = DetailPlainLimitGauge::where('calibration_id', $calibration->id)->first();
        
        if ($existingDetail) {
            $existingDetail->update($detailData);
            \Log::info('✅ Detail Plain Limit Gauge updated:', ['detail_id' => $existingDetail->id]);
        } else {
            $detail = DetailPlainLimitGauge::create($detailData);
            \Log::info('✅ Detail Plain Limit Gauge created:', ['detail_id' => $detail->id]);
        }
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Ambil nama dari input calibrated_by dan verified_by
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headPlainLimitGauge;
        
        \Log::info('📋 UPDATE SUMMARY (Plain Limit Gauge):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'alat_standar' => $alatStandarString,
            'satuan_go' => $request->satuan_go ?? '',
            'satuan_no_go' => $request->satuan_no_go ?? '',
            'go_nominal' => $request->go_nominal ?? '',
            'nogo_nominal' => $request->nogo_nominal ?? '',
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);
        
        \Log::info('🎉 updatePlainLimitGauge COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePlainLimitGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Plain Limit Gauge: " . $e->getMessage());
    }
}

private function storeTempHumidTransmitter($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('🌡️ ===== START storeTempHumidTransmitter =====', [
        'calibration_id' => $calibration->id
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeTempHumidTransmitter called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🌡️ Alat standar selected for TempHumidTransmitter:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. SIMPAN HEAD TEMP HUMID TRANSMITTER (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $head = HeadTempHumidTransmitter::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-67',
            'tertelusur' => 'Certus Metrology',
            'form_index' => 1,
            'kapasitas_min_c' => $request->kapasitas_min_c,
            'kapasitas_max_c' => $request->kapasitas_max_c,
            'resolusi_c' => $request->resolusi_c,
            'kapasitas_min_rh' => $request->kapasitas_min_rh,
            'kapasitas_max_rh' => $request->kapasitas_max_rh,
            'resolusi_rh' => $request->resolusi_rh,
            'kapasitas_min_ma' => $request->kapasitas_min_ma,
            'kapasitas_max_ma' => $request->kapasitas_max_ma,
            'resolusi_ma' => $request->resolusi_ma,
        ]);
        
        \Log::info('✅ HeadTempHumidTransmitter saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 3. SIMPAN DETAIL MEASUREMENTS UNTUK TEMPERATURE (T) - 8 BARIS
        // ==================================================================
        \Log::info('🌡️ Saving temperature (T) detail measurements...');
        $temperatureCount = 0;
        
        for ($row = 1; $row <= 8; $row++) {
            // Cari T_setting dengan dukungan _tab
            $tSetting = $this->getRequestValue($request, "T_setting_{$row}", $tabId);
            if (!$tSetting) {
                $tSetting = $this->getRequestValue($request, "T_setting", $tabId);
                if (is_array($tSetting)) {
                    $tSetting = $tSetting[$row - 1] ?? null;
                }
            }
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($tSetting);
            
            // Cek T_STD1, T_STD2, T_STD3
            for ($j = 1; $j <= 3; $j++) {
                $tStd = $this->getRequestValue($request, "T_STD{$row}_{$j}", $tabId);
                if (!$tStd) {
                    $tStd = $this->getRequestValue($request, "T_STD", $tabId);
                    if (is_array($tStd)) {
                        $index = ($row - 1) * 3 + ($j - 1);
                        $tStd = $tStd[$index] ?? null;
                    }
                }
                if (!empty($tStd)) {
                    $hasData = true;
                    break;
                }
            }
            
            // Cek T_OSmA1, T_OSmA2, T_OSmA3
            for ($j = 1; $j <= 3; $j++) {
                $tOsmA = $this->getRequestValue($request, "T_OSmA{$row}_{$j}", $tabId);
                if (!$tOsmA) {
                    $tOsmA = $this->getRequestValue($request, "T_OSmA", $tabId);
                    if (is_array($tOsmA)) {
                        $index = ($row - 1) * 3 + ($j - 1);
                        $tOsmA = $tOsmA[$index] ?? null;
                    }
                }
                if (!empty($tOsmA)) {
                    $hasData = true;
                    break;
                }
            }
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'form_index' => 1,
                    'T_setting' => $tSetting,
                    'T_STD1' => $this->getRequestValue($request, "T_STD{$row}_1", $tabId),
                    'T_STD2' => $this->getRequestValue($request, "T_STD{$row}_2", $tabId),
                    'T_STD3' => $this->getRequestValue($request, "T_STD{$row}_3", $tabId),
                    'T_OSmA1' => $this->getRequestValue($request, "T_OSmA{$row}_1", $tabId),
                    'T_OSmA2' => $this->getRequestValue($request, "T_OSmA{$row}_2", $tabId),
                    'T_OSmA3' => $this->getRequestValue($request, "T_OSmA{$row}_3", $tabId),
                ];
                
                // Jika tidak ditemukan dengan format baris per kolom, coba format array
                if (empty($detailData['T_STD1']) && empty($detailData['T_STD2']) && empty($detailData['T_STD3'])) {
                    $tStdArray = $this->getRequestValue($request, "T_STD", $tabId);
                    if (is_array($tStdArray)) {
                        $index = ($row - 1) * 3;
                        $detailData['T_STD1'] = $tStdArray[$index] ?? null;
                        $detailData['T_STD2'] = $tStdArray[$index + 1] ?? null;
                        $detailData['T_STD3'] = $tStdArray[$index + 2] ?? null;
                    }
                }
                
                if (empty($detailData['T_OSmA1']) && empty($detailData['T_OSmA2']) && empty($detailData['T_OSmA3'])) {
                    $tOsmAArray = $this->getRequestValue($request, "T_OSmA", $tabId);
                    if (is_array($tOsmAArray)) {
                        $index = ($row - 1) * 3;
                        $detailData['T_OSmA1'] = $tOsmAArray[$index] ?? null;
                        $detailData['T_OSmA2'] = $tOsmAArray[$index + 1] ?? null;
                        $detailData['T_OSmA3'] = $tOsmAArray[$index + 2] ?? null;
                    }
                }
                
                Detail_T_TempHumidTransmitter::create($detailData);
                $temperatureCount++;
                \Log::debug("🌡️ Temperature detail saved for row {$row}");
            }
        }
        
        \Log::info("✅ Saved {$temperatureCount} temperature (T) detail measurements");
        
        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS UNTUK HUMIDITY (RH) - 7 BARIS
        // ==================================================================
        \Log::info('💧 Saving humidity (RH) detail measurements...');
        $humidityCount = 0;
        
        for ($row = 1; $row <= 7; $row++) {
            // Cari RH_setting dengan dukungan _tab
            $rhSetting = $this->getRequestValue($request, "RH_setting_{$row}", $tabId);
            if (!$rhSetting) {
                $rhSetting = $this->getRequestValue($request, "RH_setting", $tabId);
                if (is_array($rhSetting)) {
                    $rhSetting = $rhSetting[$row - 1] ?? null;
                }
            }
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($rhSetting);
            
            // Cek RH_STD1, RH_STD2, RH_STD3
            for ($j = 1; $j <= 3; $j++) {
                $rhStd = $this->getRequestValue($request, "RH_STD{$row}_{$j}", $tabId);
                if (!$rhStd) {
                    $rhStd = $this->getRequestValue($request, "RH_STD", $tabId);
                    if (is_array($rhStd)) {
                        $index = ($row - 1) * 3 + ($j - 1);
                        $rhStd = $rhStd[$index] ?? null;
                    }
                }
                if (!empty($rhStd)) {
                    $hasData = true;
                    break;
                }
            }
            
            // Cek RH_OSmA1, RH_OSmA2, RH_OSmA3
            for ($j = 1; $j <= 3; $j++) {
                $rhOsmA = $this->getRequestValue($request, "RH_OSmA{$row}_{$j}", $tabId);
                if (!$rhOsmA) {
                    $rhOsmA = $this->getRequestValue($request, "RH_OSmA", $tabId);
                    if (is_array($rhOsmA)) {
                        $index = ($row - 1) * 3 + ($j - 1);
                        $rhOsmA = $rhOsmA[$index] ?? null;
                    }
                }
                if (!empty($rhOsmA)) {
                    $hasData = true;
                    break;
                }
            }
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'form_index' => 1,
                    'RH_setting' => $rhSetting,
                    'RH_STD1' => $this->getRequestValue($request, "RH_STD{$row}_1", $tabId),
                    'RH_STD2' => $this->getRequestValue($request, "RH_STD{$row}_2", $tabId),
                    'RH_STD3' => $this->getRequestValue($request, "RH_STD{$row}_3", $tabId),
                    'RH_OSmA1' => $this->getRequestValue($request, "RH_OSmA{$row}_1", $tabId),
                    'RH_OSmA2' => $this->getRequestValue($request, "RH_OSmA{$row}_2", $tabId),
                    'RH_OSmA3' => $this->getRequestValue($request, "RH_OSmA{$row}_3", $tabId),
                ];
                
                // Jika tidak ditemukan dengan format baris per kolom, coba format array
                if (empty($detailData['RH_STD1']) && empty($detailData['RH_STD2']) && empty($detailData['RH_STD3'])) {
                    $rhStdArray = $this->getRequestValue($request, "RH_STD", $tabId);
                    if (is_array($rhStdArray)) {
                        $index = ($row - 1) * 3;
                        $detailData['RH_STD1'] = $rhStdArray[$index] ?? null;
                        $detailData['RH_STD2'] = $rhStdArray[$index + 1] ?? null;
                        $detailData['RH_STD3'] = $rhStdArray[$index + 2] ?? null;
                    }
                }
                
                if (empty($detailData['RH_OSmA1']) && empty($detailData['RH_OSmA2']) && empty($detailData['RH_OSmA3'])) {
                    $rhOsmAArray = $this->getRequestValue($request, "RH_OSmA", $tabId);
                    if (is_array($rhOsmAArray)) {
                        $index = ($row - 1) * 3;
                        $detailData['RH_OSmA1'] = $rhOsmAArray[$index] ?? null;
                        $detailData['RH_OSmA2'] = $rhOsmAArray[$index + 1] ?? null;
                        $detailData['RH_OSmA3'] = $rhOsmAArray[$index + 2] ?? null;
                    }
                }
                
                Detail_RH_TempHumidTransmitter::create($detailData);
                $humidityCount++;
                \Log::debug("💧 Humidity detail saved for row {$row}");
            }
        }
        
        \Log::info("✅ Saved {$humidityCount} humidity (RH) detail measurements");
        
        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (TempHumidTransmitter):', [
            'calibration_id' => $calibration->id,
            'temperature_details' => $temperatureCount,
            'humidity_details' => $humidityCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);
        
        \Log::info('🎉 storeTempHumidTransmitter COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTempHumidTransmitter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                Detail_T_TempHumidTransmitter::where('calibration_id', $calibration->id)->delete();
                Detail_RH_TempHumidTransmitter::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data TempHumidTransmitter: " . $e->getMessage());
    }
}

private function updateTempHumidTransmitter($request, $calibration, $certificateId)
{
    try {
        \Log::info('🚀 START updateTempHumidTransmitter - WITH CERTIFICATE ID UPDATE');
        
        // ==================================================================
        // 1. TENTUKAN NAMA ALAT YANG BARU DARI BERBAGAI SUMBER
        // ==================================================================
        $namaAlatLama = $calibration->namaAlat;
        $namaAlatBaru = $namaAlatLama; // Default: tetap sama
        
        \Log::info('🔍 Nama alat sebelum update:', [
            'nama_alat_lama' => $namaAlatLama,
            'from_dropdown' => $request->nama_alat ?? 'not_set'
        ]);
        
        // Priority: Dari dropdown nama_alat
        if ($request->filled('nama_alat') && $request->nama_alat !== 'MANUAL_INPUT') {
            $namaAlatBaru = $request->nama_alat;
            \Log::info('📝 Nama alat dari dropdown:', ['nama_alat_baru' => $namaAlatBaru]);
        }
        
        // ==================================================================
        // 2. PERBARUI NAMA ALAT DI CALIBRATION JIKA BERBEDA
        // ==================================================================
        $namaAlatUpdated = false;
        if ($namaAlatLama !== $namaAlatBaru) {
            $calibration->update(['namaAlat' => $namaAlatBaru]);
            $namaAlatUpdated = true;
            \Log::info('✅ Nama alat diupdate di calibration:', [
                'dari' => $namaAlatLama,
                'menjadi' => $namaAlatBaru
            ]);
        }
        
        // ==================================================================
        // 3. GENERATE CERTIFICATE ID BARU JIKA NAMA ALAT BERUBAH
        // ==================================================================
        $certificateIdLama = $calibration->certificate_id;
        $certificateIdBaru = $certificateIdLama;
        $certificateIdUpdated = false;
        
        if ($namaAlatUpdated) {
            // Generate certificate ID baru menggunakan generateCertificateIdFromNamaAlat()
            // Hasilnya akan seperti: PAS-00115-K26-Humidity Transmitter
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatBaru);
            $certificateIdUpdated = true;
            
            // Update certificate_id di calibration
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            
            \Log::info('🆔 Certificate ID updated menggunakan generateCertificateIdFromNamaAlat():', [
                'nama_alat_lama' => $namaAlatLama,
                'nama_alat_baru' => $namaAlatBaru,
                'certificate_id_lama' => $certificateIdLama,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        } elseif (empty($certificateIdLama) || strpos($certificateIdLama, 'MANUAL_INPUT') !== false) {
            // Jika certificate_id masih kosong atau mengandung MANUAL_INPUT, generate baru
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatBaru);
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID generated menggunakan generateCertificateIdFromNamaAlat():', [
                'reason' => empty($certificateIdLama) ? 'certificate_id kosong' : 'mengandung MANUAL_INPUT',
                'certificate_id_baru' => $certificateIdBaru
            ]);
        } else {
            \Log::info('✅ Certificate ID tidak berubah:', [
                'certificate_id' => $certificateIdLama,
                'reason' => 'nama alat tidak berubah'
            ]);
        }
        
        // Gunakan certificate_id yang sudah ditentukan
        $certificateIdToUse = $certificateIdBaru;
        
        // ==================================================================
        // 4. AMBIL ATAU BUAT HEAD TEMP HUMID TRANSMITTER
        // ==================================================================
        $head = HeadTempHumidTransmitter::where('calibration_id', $calibration->id)->first();
        
        // ==================================================================
        // 5. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🌡️ Alat standar selected for TempHumidTransmitter:', ['alat_standar' => $alatStandar]);

        // ==================================================================
        // 6. UPDATE ATAU BUAT HEAD TEMP HUMID TRANSMITTER
        // ==================================================================
        if ($head) {
            // Update existing head
            $head->update([
                'certificate_id' => $certificateIdToUse,
                'standard' => $alatStandarString,
                'calibrationMethod' => 'PAS-IK1102-67',
                'tertelusur' => 'Certus Metrology',
                'kapasitas_min_c' => $request->kapasitas_min_c,
                'kapasitas_max_c' => $request->kapasitas_max_c,
                'resolusi_c' => $request->resolusi_c,
                'kapasitas_min_rh' => $request->kapasitas_min_rh,
                'kapasitas_max_rh' => $request->kapasitas_max_rh,
                'resolusi_rh' => $request->resolusi_rh,
                'kapasitas_min_ma' => $request->kapasitas_min_ma,
                'kapasitas_max_ma' => $request->kapasitas_max_ma,
                'resolusi_ma' => $request->resolusi_ma,
            ]);
            \Log::info('✅ Head TempHumidTransmitter updated:', ['head_id' => $head->id, 'certificate_id' => $certificateIdToUse]);
        } else {
            // Create new head if doesn't exist
            $head = HeadTempHumidTransmitter::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateIdToUse,
                'standard' => $alatStandarString,
                'calibrationMethod' => 'PAS-IK1102-67',
                'tertelusur' => 'Certus Metrology',
                 'kapasitas_min_c' => $request->kapasitas_min_c,
                'kapasitas_max_c' => $request->kapasitas_max_c,
                'resolusi_c' => $request->resolusi_c,
                'kapasitas_min_rh' => $request->kapasitas_min_rh,
                'kapasitas_max_rh' => $request->kapasitas_max_rh,
                'resolusi_rh' => $request->resolusi_rh,
                'kapasitas_min_ma' => $request->kapasitas_min_ma,
                'kapasitas_max_ma' => $request->kapasitas_max_ma,
                'resolusi_ma' => $request->resolusi_ma,
            ]);
            \Log::info('✅ Head TempHumidTransmitter created:', ['head_id' => $head->id, 'certificate_id' => $certificateIdToUse]);
        }

        // ==================================================================
        // 7. UPDATE DETAIL MEASUREMENTS UNTUK TEMPERATURE (T) - 8 BARIS
        // ==================================================================
        \Log::info('🌡️ Updating temperature (T) detail measurements...');
        
        // Hapus detail temperature lama
        $deletedTempCount = Detail_T_TempHumidTransmitter::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old temperature (T) detail records:', ['count' => $deletedTempCount]);
        
        $temperatureCount = 0;
        
        for ($i = 1; $i <= 8; $i++) { // 8 BARIS UNTUK TEMPERATURE
            // Cek apakah ada data untuk baris ini
            $hasTemperatureData = false;
            
            // Cek apakah ada T_STD atau T_OSmA yang diisi
            for ($j = 1; $j <= 3; $j++) {
                if ($request->has("T_STD{$i}_{$j}") && !empty(trim($request->{"T_STD{$i}_{$j}"}))) {
                    $hasTemperatureData = true;
                    break;
                }
                if ($request->has("T_OSmA{$i}_{$j}") && !empty(trim($request->{"T_OSmA{$i}_{$j}"}))) {
                    $hasTemperatureData = true;
                    break;
                }
            }
            
            // Simpan jika ada data T_setting atau T_STD/T_OSmA
            if (($request->has("T_setting_{$i}") && !empty(trim($request->{"T_setting_{$i}"}))) || $hasTemperatureData) {
                
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'T_setting' => $request->{"T_setting_{$i}"} ?? null,
                    'T_STD1' => $request->{"T_STD{$i}_1"} ?? null,
                    'T_STD2' => $request->{"T_STD{$i}_2"} ?? null,
                    'T_STD3' => $request->{"T_STD{$i}_3"} ?? null,
                    'T_OSmA1' => $request->{"T_OSmA{$i}_1"} ?? null,
                    'T_OSmA2' => $request->{"T_OSmA{$i}_2"} ?? null,
                    'T_OSmA3' => $request->{"T_OSmA{$i}_3"} ?? null,
                ];

                \Log::info("🌡️ Saving temperature (T) detail row $i:", $detailData);
                
                Detail_T_TempHumidTransmitter::create($detailData);
                $temperatureCount++;
            }
        }
        
        \Log::info("✅ Saved $temperatureCount temperature (T) detail measurements");

        // ==================================================================
        // 8. UPDATE DETAIL MEASUREMENTS UNTUK HUMIDITY (RH) - 7 BARIS
        // ==================================================================
        \Log::info('💧 Updating humidity (RH) detail measurements...');
        
        // Hapus detail humidity lama
        $deletedRhCount = Detail_RH_TempHumidTransmitter::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old humidity (RH) detail records:', ['count' => $deletedRhCount]);
        
        $humidityCount = 0;
        
        for ($i = 1; $i <= 7; $i++) { // 7 BARIS UNTUK HUMIDITY
            // Cek apakah ada data untuk baris ini
            $hasHumidityData = false;
            
            // Cek apakah ada RH_STD atau RH_OSmA yang diisi
            for ($j = 1; $j <= 3; $j++) {
                if ($request->has("RH_STD{$i}_{$j}") && !empty(trim($request->{"RH_STD{$i}_{$j}"}))) {
                    $hasHumidityData = true;
                    break;
                }
                if ($request->has("RH_OSmA{$i}_{$j}") && !empty(trim($request->{"RH_OSmA{$i}_{$j}"}))) {
                    $hasHumidityData = true;
                    break;
                }
            }
            
            // Simpan jika ada data RH_setting atau RH_STD/RH_OSmA
            if (($request->has("RH_setting_{$i}") && !empty(trim($request->{"RH_setting_{$i}"}))) || $hasHumidityData) {
                
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'RH_setting' => $request->{"RH_setting_{$i}"} ?? null,
                    'RH_STD1' => $request->{"RH_STD{$i}_1"} ?? null,
                    'RH_STD2' => $request->{"RH_STD{$i}_2"} ?? null,
                    'RH_STD3' => $request->{"RH_STD{$i}_3"} ?? null,
                    'RH_OSmA1' => $request->{"RH_OSmA{$i}_1"} ?? null,
                    'RH_OSmA2' => $request->{"RH_OSmA{$i}_2"} ?? null,
                    'RH_OSmA3' => $request->{"RH_OSmA{$i}_3"} ?? null,
                ];

                \Log::info("💧 Saving humidity (RH) detail row $i:", $detailData);
                
                Detail_RH_TempHumidTransmitter::create($detailData);
                $humidityCount++;
            }
        }
        
        \Log::info("✅ Saved $humidityCount humidity (RH) detail measurements");

        // ==================================================================
        // 9. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Data TTD dan nama dari calibration
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } else {
            $updateData['calibrated_by'] = '-';
            \Log::warning('⚠️ calibrated_by kosong, set calibrated_by = "-"');
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } else {
            $updateData['verified_by'] = '-';
            \Log::warning('⚠️ verified_by kosong, set verified_by = "-"');
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', $updateData);
        }

        // ==================================================================
        // 10. LOG HASIL AKHIR
        // ==================================================================
        $totalTempRecords = Detail_T_TempHumidTransmitter::where('calibration_id', $calibration->id)->count();
        $totalRhRecords = Detail_RH_TempHumidTransmitter::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (TempHumidTransmitter):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'temperature_records' => $totalTempRecords,
            'humidity_records' => $totalRhRecords,
            'certificate_id' => $certificateIdToUse,
            'nama_alat' => $namaAlatBaru,
            'nama_alat_updated' => $namaAlatUpdated,
            'certificate_id_updated' => $certificateIdUpdated,
            'alat_standar' => $alatStandarString,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updateTempHumidTransmitter COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTempHumidTransmitter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Temperature/Humidity Transmitter: " . $e->getMessage());
    }
}

private function storeTempTransmitter($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeTempTransmitter');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeTempTransmitter called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (empty($alatStandar)) {
            $alatStandar = $request->input('alat_standar', []);
        }
        
        // Pastikan dalam bentuk array
        if (!is_array($alatStandar)) {
            $alatStandar = [$alatStandar];
        }
        
        // Filter nilai kosong
        $alatStandar = array_filter($alatStandar, function($value) {
            return !empty($value);
        });
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        // ==================================================================
        // 2. PROSES INDICATOR
        // ==================================================================
        $indicator = $this->getRequestValue($request, 'indicator', $tabId);
        if (empty($indicator)) {
            $indicator = $request->input('indicator', []);
        }
        
        if (!is_array($indicator)) {
            $indicator = [$indicator];
        }
        
        $indicator = array_filter($indicator, function($value) {
            return !empty($value);
        });
        
        $indicatorString = !empty($indicator) ? implode(', ', $indicator) : '';
        
        // ==================================================================
        // 3. PROSES MEDIA
        // ==================================================================
        $media = $this->getRequestValue($request, 'media', $tabId);
        if (empty($media)) {
            $media = $request->input('media', []);
        }
        
        if (!is_array($media)) {
            $media = [$media];
        }
        
        $media = array_filter($media, function($value) {
            return !empty($value);
        });
        
        $mediaString = !empty($media) ? implode(', ', $media) : '';
        
        // Debug log untuk melihat data yang diterima
        \Log::info('🌡️ Data untuk TempTransmitter:', [
            'alat_standar' => $alatStandar,
            'alat_standar_string' => $alatStandarString,
            'indicator' => $indicator,
            'indicator_string' => $indicatorString,
            'media' => $media,
            'media_string' => $mediaString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 4. PROSES NAMA KALIBRATOR DAN PEMERIKSA
        // ==================================================================
        $namaKalibrator = trim($this->getRequestValue($request, 'calibrated_by', $tabId) ?? '');
        $namaPemeriksa = trim($this->getRequestValue($request, 'verified_by', $tabId) ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);
        
        // ==================================================================
        // 5. SIMPAN KE HEAD TEMP TRANSMITTER
        // ==================================================================
        $head = HeadTempTransmitter::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-66 (Temp. Transmitter)',
            'indicator' => $indicatorString,
            'media' => $mediaString,
            'satuan_suhu_kiri' => $this->getRequestValue($request, 'satuan_setting_suhu_kiri', $tabId),
            'satuan_suhu_kanan' => $this->getRequestValue($request, 'satuan_setting_suhu_kanan', $tabId),
            'satuan_std_kiri' => $this->getRequestValue($request, 'satuan_std_kiri', $tabId),
            'satuan_std_kanan' => $this->getRequestValue($request, 'satuan_std_kanan', $tabId),
            'satuan_indicator_kiri' => $this->getRequestValue($request, 'satuan_indicator_kiri', $tabId),
            'satuan_indicator_kanan' => $this->getRequestValue($request, 'satuan_indicator_kanan', $tabId),
            'kapasitas_min_c' => $this->getRequestValue($request, 'kapasitas_min_c', $tabId),
            'kapasitas_max_c' => $this->getRequestValue($request, 'kapasitas_max_c', $tabId),
            'resolusi_c' => $this->getRequestValue($request, 'resolusi_c', $tabId),
            'kapasitas_min_ma' => $this->getRequestValue($request, 'kapasitas_min_ma', $tabId),
            'kapasitas_max_ma' => $this->getRequestValue($request, 'kapasitas_max_ma', $tabId),
            'resolusi_ma' => $this->getRequestValue($request, 'resolusi_ma', $tabId),
        ]);
        
        \Log::info('✅ Head TempTransmitter saved:', [
            'head_id' => $head->id,
            'standard' => $alatStandarString,
            'indicator' => $indicatorString,
            'media' => $mediaString
        ]);
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN NAMA PENANDATANGAN
        // ==================================================================
        $updateData = [];
        
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
        }
        
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Update rentang ukur (jika ada)
        $rentangMin = $this->getRequestValue($request, 'rentang_ukur_min', $tabId);
        if ($rentangMin !== null && $rentangMin !== '') {
            $updateData['range_min'] = $rentangMin;
        }
        
        $rentangMax = $this->getRequestValue($request, 'rentang_ukur_max', $tabId);
        if ($rentangMax !== null && $rentangMax !== '') {
            $updateData['range_max'] = $rentangMax;
        }
        
        // Update kondisi lingkungan (jika ada)
        $environmentData = [];
        
        $temperature = $this->getRequestValue($request, 'temperature', $tabId);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $this->getRequestValue($request, 'humidity', $tabId);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Kondisi lingkungan:', $environmentData);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }
        
        // ==================================================================
        // 7. SIMPAN DETAIL MEASUREMENTS (5 KIRI + 5 KANAN)
        // ==================================================================
        \Log::info('🌡️ Saving temperature detail measurements...');
        $detailCount = 0;
        
        // SIMPAN DATA KIRI (5 records)
        for ($group = 1; $group <= 5; $group++) {
            $T_setting_kiri = $this->getRequestValue($request, "setting_suhu_kiri_{$group}", $tabId);
            
            // Ambil data STD dan Indicator untuk 3 baris
            $std1 = $this->getRequestValue($request, "std_kiri_{$group}_1", $tabId);
            $std2 = $this->getRequestValue($request, "std_kiri_{$group}_2", $tabId);
            $std3 = $this->getRequestValue($request, "std_kiri_{$group}_3", $tabId);
            $indicator1 = $this->getRequestValue($request, "indicator_kiri_{$group}_1", $tabId);
            $indicator2 = $this->getRequestValue($request, "indicator_kiri_{$group}_2", $tabId);
            $indicator3 = $this->getRequestValue($request, "indicator_kiri_{$group}_3", $tabId);
            
            // Cek apakah ada data untuk grup kiri ini
            $hasLeftData = !empty($T_setting_kiri) || 
                           !empty($std1) || !empty($std2) || !empty($std3) ||
                           !empty($indicator1) || !empty($indicator2) || !empty($indicator3);
            
            // Simpan jika ada data
            if ($hasLeftData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'T_setting' => $T_setting_kiri,
                    'T_STD1' => $std1,
                    'T_STD2' => $std2,
                    'T_STD3' => $std3,
                    'T_Indicator1' => $indicator1,
                    'T_Indicator2' => $indicator2,
                    'T_Indicator3' => $indicator3,
                ];
                
                \Log::debug("🌡️ Saving LEFT data - Group {$group}:", $detailData);
                
                DetailTempTransmitter::create($detailData);
                $detailCount++;
            }
        }
        
        // SIMPAN DATA KANAN (5 records)
        for ($group = 1; $group <= 5; $group++) {
            $T_setting_kanan = $this->getRequestValue($request, "setting_suhu_kanan_{$group}", $tabId);
            
            // Ambil data STD dan Indicator untuk 3 baris
            $std1 = $this->getRequestValue($request, "std_kanan_{$group}_1", $tabId);
            $std2 = $this->getRequestValue($request, "std_kanan_{$group}_2", $tabId);
            $std3 = $this->getRequestValue($request, "std_kanan_{$group}_3", $tabId);
            $indicator1 = $this->getRequestValue($request, "indicator_kanan_{$group}_1", $tabId);
            $indicator2 = $this->getRequestValue($request, "indicator_kanan_{$group}_2", $tabId);
            $indicator3 = $this->getRequestValue($request, "indicator_kanan_{$group}_3", $tabId);
            
            // Cek apakah ada data untuk grup kanan ini
            $hasRightData = !empty($T_setting_kanan) || 
                            !empty($std1) || !empty($std2) || !empty($std3) ||
                            !empty($indicator1) || !empty($indicator2) || !empty($indicator3);
            
            // Simpan jika ada data
            if ($hasRightData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'T_setting' => $T_setting_kanan,
                    'T_STD1' => $std1,
                    'T_STD2' => $std2,
                    'T_STD3' => $std3,
                    'T_Indicator1' => $indicator1,
                    'T_Indicator2' => $indicator2,
                    'T_Indicator3' => $indicator3,
                ];
                
                \Log::debug("🌡️ Saving RIGHT data - Group {$group}:", $detailData);
                
                DetailTempTransmitter::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements");
        
        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailTempTransmitter::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Temperature Transmitter):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'indicator' => $indicatorString,
            'media' => $mediaString,
        ]);
        
        \Log::info('🎉 storeTempTransmitter COMPLETED');
        return $head;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeTempTransmitter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailTempTransmitter::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Temperature Transmitter: " . $e->getMessage());
    }
}
private function updateTempTransmitter($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateTempTransmitter', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $newCertificateId
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = HeadTempTransmitter::where('calibration_id', $calibration->id)->first();
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // Jika certificate_id masih kosong, gunakan dari parameter atau generate
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $calibration->certificate_id;
        }
        
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        $finalCertificateId = $certificateIdBaru;
        
        \Log::info('📋 Final Certificate ID:', [
            'certificate_id' => $finalCertificateId,
            'certificate_id_updated' => $certificateIdUpdated
        ]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR, INDICATOR, DAN MEDIA
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        $indicator = $request->indicator ?? [];
        $indicatorString = !empty($indicator) ? implode(', ', $indicator) : '';
        
        $media = $request->media ?? [];
        $mediaString = !empty($media) ? implode(', ', $media) : '';
        
        \Log::info('🌡️ Data untuk TempTransmitter update:', [
            'alat_standar' => $alatStandar,
            'indicator' => $indicator,
            'media' => $media,
        ]);
        
        // ==================================================================
        // 2. UPDATE HEAD TEMP TRANSMITTER
        // ==================================================================
        $head = HeadTempTransmitter::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-66 (Temp. Transmitter)',
            'indicator' => $indicatorString,
            'media' => $mediaString,
            'satuan_suhu_kiri' => $request->satuan_suhu_kiri,
            'satuan_suhu_kanan' => $request->satuan_suhu_kanan,
            'satuan_std_kiri' => $request->satuan_std_kiri,
            'satuan_std_kanan' => $request->satuan_std_kanan,
            'satuan_indicator_kiri' => $request->satuan_indicator_kiri,
            'satuan_indicator_kanan' => $request->satuan_indicator_kanan,
            'kapasitas_min_c' => $request->kapasitas_min_c,
            'kapasitas_max_c' => $request->kapasitas_max_c,
            'resolusi_c' => $request->resolusi_c,
            'kapasitas_min_ma' => $request->kapasitas_min_ma,
            'kapasitas_max_ma' => $request->kapasitas_max_ma,
            'resolusi_ma' => $request->resolusi_ma,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $headData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $finalCertificateId]);
        }
        
        if ($head) {
            $head->update($headData);
            $head->refresh();
            \Log::info('✅ Head TempTransmitter updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadTempTransmitter::create($headData);
            \Log::info('✅ Head TempTransmitter created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS - 10 RECORDS (5 KIRI + 5 KANAN)
        // ==================================================================
        \Log::info('🌡️ Updating temperature detail measurements...');
        
        // Hapus data lama
        DetailTempTransmitter::where('calibration_id', $calibration->id)->delete();
        
        $detailCount = 0;
        
        // SIMPAN DATA KIRI (5 records) - LANGSUNG TANPA FORMAT
        for ($group = 1; $group <= 5; $group++) {
            $T_setting_kiri = $request->input("setting_suhu_kiri_{$group}");
            
            // Cek apakah ada data untuk grup kiri ini
            $hasLeftData = false;
            
            // Cek apakah ada STD atau Indicator yang diisi
            for ($row = 1; $row <= 3; $row++) {
                $stdValue = $request->input("std_kiri_{$group}_{$row}");
                $indicatorValue = $request->input("indicator_kiri_{$group}_{$row}");
                
                if (!empty(trim($stdValue ?? ''))) {
                    $hasLeftData = true;
                    break;
                }
                if (!empty(trim($indicatorValue ?? ''))) {
                    $hasLeftData = true;
                    break;
                }
            }
            
            // Simpan jika ada data
            if (!empty($T_setting_kiri) || $hasLeftData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'T_setting' => $T_setting_kiri,
                    'T_STD1' => $request->input("std_kiri_{$group}_1"),
                    'T_STD2' => $request->input("std_kiri_{$group}_2"),
                    'T_STD3' => $request->input("std_kiri_{$group}_3"),
                    'T_Indicator1' => $request->input("indicator_kiri_{$group}_1"),
                    'T_Indicator2' => $request->input("indicator_kiri_{$group}_2"),
                    'T_Indicator3' => $request->input("indicator_kiri_{$group}_3"),
                ];

                \Log::debug("🌡️ Saving LEFT data - Group {$group}:", $detailData);
                
                DetailTempTransmitter::create($detailData);
                $detailCount++;
            }
        }
        
        // SIMPAN DATA KANAN (5 records) - LANGSUNG TANPA FORMAT
        for ($group = 1; $group <= 5; $group++) {
            $T_setting_kanan = $request->input("setting_suhu_kanan_{$group}");
            
            // Cek apakah ada data untuk grup kanan ini
            $hasRightData = false;
            
            // Cek apakah ada STD atau Indicator yang diisi
            for ($row = 1; $row <= 3; $row++) {
                $stdValue = $request->input("std_kanan_{$group}_{$row}");
                $indicatorValue = $request->input("indicator_kanan_{$group}_{$row}");
                
                if (!empty(trim($stdValue ?? ''))) {
                    $hasRightData = true;
                    break;
                }
                if (!empty(trim($indicatorValue ?? ''))) {
                    $hasRightData = true;
                    break;
                }
            }
            
            // Simpan jika ada data
            if (!empty($T_setting_kanan) || $hasRightData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'T_setting' => $T_setting_kanan,
                    'T_STD1' => $request->input("std_kanan_{$group}_1"),
                    'T_STD2' => $request->input("std_kanan_{$group}_2"),
                    'T_STD3' => $request->input("std_kanan_{$group}_3"),
                    'T_Indicator1' => $request->input("indicator_kanan_{$group}_1"),
                    'T_Indicator2' => $request->input("indicator_kanan_{$group}_2"),
                    'T_Indicator3' => $request->input("indicator_kanan_{$group}_3"),
                ];

                \Log::debug("🌡️ Saving RIGHT data - Group {$group}:", $detailData);
                
                DetailTempTransmitter::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements");
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $finalCertificateId]);
        }
        
        // Update nama penandatangan ke calibration
        if ($request->filled('calibrated_by')) {
            $updateData['calibratedBy'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibratedBy'] = $request->calibratedBy;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verifiedBy'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verifiedBy'] = $request->verifiedBy;
        }
        
        // Update uncertainty jika ada
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $head->refresh();
        $savedDetailCount = DetailTempTransmitter::where('calibration_id', $calibration->id)->count();
        
        \Log::info('🏁 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'certificate_id_di_head' => $head->certificate_id,
            'certificate_id_di_calibration' => $calibration->certificate_id,
            'detail_records' => $savedDetailCount,
            'nama_alat' => $calibration->namaAlat,
            'calibratedBy' => $calibration->calibratedBy,
            'verifiedBy' => $calibration->verifiedBy,
        ]);

        \Log::info('🎉 updateTempTransmitter COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateTempTransmitter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data TempTransmitter: " . $e->getMessage());
    }
}


private function storeIrThermometer($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('🌡️ ===== START storeIrThermometer =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeIrThermometer called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dari checkbox dengan berbagai format
        $alatStandarArray = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        } elseif ($alatStandarArray) {
            $alatStandar[] = $alatStandarArray;
        }
        
        // Coba juga dengan format alat_standar_1, alat_standar_2, dll
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. AMBIL SATUAN SUHU (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $satuanSuhuKiri = $this->getRequestValue($request, 'satuan_suhu_kiri', $tabId);
        $satuanSuhuKanan = $this->getRequestValue($request, 'satuan_suhu_kanan', $tabId);
        
        // ==================================================================
        // 3. SIMPAN KE HEAD IR THERMOMETER
        // ==================================================================
        $head = HeadIrThermometer::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-47',
            'satuan_suhu_kiri' => $satuanSuhuKiri,
            'satuan_suhu_kanan' => $satuanSuhuKanan,
            'form_index' => 1,
        ]);
        
        \Log::info('✅ Head IrThermometer saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 4. SIMPAN DATA JARAK KALIBRASI KE ADD_IR_THERMOMETER (DENGAN DUKUNGAN _tab)
        // ==================================================================
              $jarakKalibrasi = $this->getRequestValue($request, 'jarak_kalibrasi', $tabId);
        $emisivitas = $this->getRequestValue($request, 'emisivitas', $tabId);
        $merek = $this->getRequestValue($request, 'merek', $tabId);
        
        if (($merek && !empty(trim($merek))) || !empty($jarakKalibrasi) || !empty($emisivitas) || $request->has('jarak_kalibrasi') || $request->has('emisivitas')) {
            AddIrThermometer::create([
                'calibration_id' => $calibration->id,
                'jarakKalibrasi' => $jarakKalibrasi,
                'emisivitas' => $emisivitas,
                'form_index' => 1,
            ]);
            \Log::info('✅ AddIrThermometer saved:', [
                'jarak' => $jarakKalibrasi,
                'emisivitas' => $emisivitas
            ]);
        }
        
        // ==================================================================
        // 5. SIMPAN DETAIL MEASUREMENTS UNTUK TABEL KIRI (1-5) DAN KANAN (6-10)
        // ==================================================================
        \Log::info('📊 Saving detail measurements for IrThermometer...');
        $detailCount = 0;
        
        for ($row = 1; $row <= 10; $row++) {
            // Ambil titik ukur (setting suhu)
            $titikUkur = $this->getRequestValue($request, "setting_suhu_{$row}", $tabId);
            if (!$titikUkur) {
                $titikUkur = $this->getRequestValue($request, "titik_ukur_{$row}", $tabId);
            }
            
            // Hitung index STD/UUT (1-30)
            $startStd = (($row - 1) * 3) + 1;
            
            // Ambil nilai STD (3 nilai per baris)
            $stdValues = [];
            for ($col = 0; $col < 3; $col++) {
                $stdKey = "std_" . ($startStd + $col);
                $value = $this->getRequestValue($request, $stdKey, $tabId);
                
                // Coba format alternatif
                if (!$value) {
                    $value = $this->getRequestValue($request, "std_{$row}_" . ($col + 1), $tabId);
                }
                if (!$value) {
                    $value = $this->getRequestValue($request, "STD_{$row}_" . ($col + 1), $tabId);
                }
                
                $stdValues[] = $value;
            }
            
            // Ambil nilai UUT (3 nilai per baris)
            $uutValues = [];
            for ($col = 0; $col < 3; $col++) {
                $uutKey = "uut_" . ($startStd + $col);
                $value = $this->getRequestValue($request, $uutKey, $tabId);
                
                // Coba format alternatif
                if (!$value) {
                    $value = $this->getRequestValue($request, "uut_{$row}_" . ($col + 1), $tabId);
                }
                if (!$value) {
                    $value = $this->getRequestValue($request, "UUT_{$row}_" . ($col + 1), $tabId);
                }
                
                $uutValues[] = $value;
            }
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($titikUkur) || 
                       !empty($stdValues[0]) || !empty($stdValues[1]) || !empty($stdValues[2]) ||
                       !empty($uutValues[0]) || !empty($uutValues[1]) || !empty($uutValues[2]);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_ir_thermometer_id' => $head->id,
                    'form_index' => 1,
                    'titikUkur' => $titikUkur,
                    'STD01' => $stdValues[0] ?? null,
                    'STD02' => $stdValues[1] ?? null,
                    'STD03' => $stdValues[2] ?? null,
                    'UUT01' => $uutValues[0] ?? null,
                    'UUT02' => $uutValues[1] ?? null,
                    'UUT03' => $uutValues[2] ?? null,
                ];
                
                \Log::debug("📝 Saving IrThermometer detail row {$row}:", [
                    'titikUkur' => $detailData['titikUkur'],
                    'STD01' => $detailData['STD01'],
                    'UUT01' => $detailData['UUT01']
                ]);
                
                DetailIrThermometer::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for IrThermometer");
        
        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TTD (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('👤 Calibrated by saved:', ['name' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('👤 Verified by saved:', ['name' => $verifiedBy]);
        }
        
        // Ambil satuan suhu umum jika ada
        $satuanSuhu = $this->getRequestValue($request, 'satuan_suhu', $tabId);
        if ($satuanSuhu) {
            $updateData['satuan_suhu'] = $satuanSuhu;
            \Log::info('🌡️ Satuan suhu:', ['satuan' => $satuanSuhu]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with signature data');
        }
        
        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (IrThermometer):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $detailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'satuan_suhu_kiri' => $satuanSuhuKiri,
            'satuan_suhu_kanan' => $satuanSuhuKanan,
        ]);
        
        \Log::info('🎉 storeIrThermometer COMPLETED');
        return $head;
        
    } catch (\Exception $e) {
        \Log::error('💥 Error storing IrThermometer data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
private function updateIrThermometer($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateIrThermometer');
        \Log::info('📝 Updating IrThermometer data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headIrThermometer;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', ['alat_standar' => $alatStandar]);
        
        $satuanSuhuKiri = $request->satuan_suhu_kiri;
        $satuanSuhuKanan = $request->satuan_suhu_kanan;
        
        // ==================================================================
        // 2. UPDATE ATAU CREATE HEAD IR THERMOMETER
        // ==================================================================
        $head = HeadIrThermometer::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-47',
            'satuan_suhu_kiri' => $satuanSuhuKiri,
            'satuan_suhu_kanan' => $satuanSuhuKanan,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ Head IrThermometer updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadIrThermometer::create($headData);
            \Log::info('➕ Head IrThermometer created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE ATAU CREATE ADD IR THERMOMETER (JARAK KALIBRASI) - TANPA FORMAT
        // ==================================================================
        // ==================================================================
        if ($request->has('jarak_kalibrasi') || $request->has('emisivitas')) {
            $addData = [];
            
            if ($request->has('jarak_kalibrasi')) {
                $addData['jarakKalibrasi'] = $request->jarak_kalibrasi;  // LANGSUNG, tanpa format
            }
            
            if ($request->has('emisivitas')) {
                $addData['emisivitas'] = $request->emisivitas;
            }
            
            $add = AddIrThermometer::where('calibration_id', $calibration->id)->first();
            
            if ($add) {
                $add->update($addData);
                \Log::info('✅ AddIrThermometer updated:', $addData);
            } else {
                $addData['calibration_id'] = $calibration->id;
                $addData['form_index'] = 1;
                AddIrThermometer::create($addData);
                \Log::info('✅ AddIrThermometer created:', $addData);
            }
        }
        
        // ==================================================================
        // 4. UPDATE DETAIL IR THERMOMETER - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating detail measurements...');
        
        // Hapus data lama terlebih dahulu
        $deletedDetails = DetailIrThermometer::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old detail records");
        
        $detailCount = 0;
        
        // Proses data untuk tabel kiri (1-5) dan kanan (6-10) - LANGSUNG TANPA FORMAT
        for ($i = 1; $i <= 10; $i++) {
            $settingSuhuField = "setting_suhu_$i";
            
            // Cek apakah ada data untuk baris ini
            $hasData = false;
            
            // Cek apakah ada STD/UUT yang diisi
            $startStd = (($i - 1) * 3) + 1;
            for ($j = 0; $j < 3; $j++) {
                $stdField = "std_" . ($startStd + $j);
                $uutField = "uut_" . ($startStd + $j);
                
                $stdValue = $request->input($stdField);
                $uutValue = $request->input($uutField);
                
                if ((!empty($stdValue)) || (!empty($uutValue))) {
                    $hasData = true;
                    break;
                }
            }
            
            // Simpan jika ada data setting suhu atau STD/UUT
            $titikUkur = $request->input($settingSuhuField);
            if ((!empty($titikUkur)) || $hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_ir_thermometer_id' => $head->id,
                    'titikUkur' => $titikUkur,  // LANGSUNG, tanpa format
                    'STD01' => $request->input("std_" . $startStd),      // LANGSUNG, tanpa format
                    'STD02' => $request->input("std_" . ($startStd + 1)), // LANGSUNG, tanpa format
                    'STD03' => $request->input("std_" . ($startStd + 2)), // LANGSUNG, tanpa format
                    'UUT01' => $request->input("uut_" . $startStd),       // LANGSUNG, tanpa format
                    'UUT02' => $request->input("uut_" . ($startStd + 1)),  // LANGSUNG, tanpa format
                    'UUT03' => $request->input("uut_" . ($startStd + 2)),  // LANGSUNG, tanpa format
                ];
                
                \Log::debug("📝 Saving detail row {$i}:", $detailData);
                
                DetailIrThermometer::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for IrThermometer");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Nama untuk TTD Dikalibrasi
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        // Nama untuk TTD Diperiksa
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        // Data uncertainty dan conclusion
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headIrThermometer;
        $savedDetailCount = DetailIrThermometer::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (IrThermometer):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'alat_standar' => $alatStandarString,
            'satuan_suhu_kiri' => $satuanSuhuKiri,
            'satuan_suhu_kanan' => $satuanSuhuKanan,
            'jarak_kalibrasi' => $request->jarak_kalibrasi,
             'emisivitas' => $request->emisivitas,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);
        
        \Log::info('🎉 updateIrThermometer COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateIrThermometer:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data IrThermometer: " . $e->getMessage());
    }
}

