private function storeThermoindicator($request, $calibration, $certificateId, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeThermoindicator =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==========================================================
        // 🔥 FUNGSI BANTU MENCARI NILAI (DIPERBAIKI)
        // ==========================================================
        $findValue = function($baseKey, $formIndex, $rowIndex = null, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            
            // Format 1: form_{formIndex}_{baseKey}_{formIndex}_{rowIndex}_tab1
            if ($rowIndex !== null) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_{$rowIndex}_tab1";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_{$rowIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$rowIndex}_tab1";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$rowIndex}";
            }
            
            // Format 2: form_{formIndex}_{baseKey}_tab1
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab1";
            $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
            
            // Format 3: {baseKey}_{formIndex}_{rowIndex}_tab1 (tanpa prefix form)
            if ($rowIndex !== null) {
                $possibleKeys[] = "{$baseKey}_{$formIndex}_{$rowIndex}_tab1";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_{$rowIndex}";
            }
            
            // Format 4: {baseKey}_{formIndex}_tab1
            $possibleKeys[] = "{$baseKey}_{$formIndex}_tab1";
            $possibleKeys[] = "{$baseKey}_{$formIndex}";
            
            // Format 5: baseKey saja (untuk form 1)
            $possibleKeys[] = $baseKey;
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [
                "form_{$formIndex}_{$baseKey}_{$formIndex}",
                "form_{$formIndex}_{$baseKey}",
                "{$baseKey}_{$formIndex}",
                $baseKey
            ];
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        // ==========================================================
        // 🔥 AMBIL FUNGSI KOMPONEN DARI FORM 1
        // ==========================================================
        $fungsiKomponenForm1 = null;
        
        $fungsiKeys = [
            "form_1_fungsi_komponen",
            "fungsi_komponen_1",
            "fungsi_komponen"
        ];
        
        foreach ($fungsiKeys as $key) {
            $value = $request->input($key);
            if ($value !== null && $value !== '') {
                $fungsiKomponenForm1 = $value;
                \Log::info("✅ Found fungsi_komponen from Form 1 using key: {$key} = {$fungsiKomponenForm1}");
                break;
            }
        }
        
        if ($fungsiKomponenForm1 === null) {
            $existingHead = HeadThermoIndicator::where('calibration_id', $calibration->id)
                ->where('form_index', 1)
                ->first();
            if ($existingHead) {
                $fungsiKomponenForm1 = $existingHead->fungsi_komponen;
                \Log::info("✅ Using existing fungsi_komponen from database (Form 1): {$fungsiKomponenForm1}");
            }
        }
        
        if ($fungsiKomponenForm1 === null) {
            $fungsiKomponenForm1 = 'ok';
            \Log::info("⚠️ Using default fungsi_komponen: ok");
        }
        
        \Log::info("📌 FUNGSI KOMPONEN FORM 1 (akan digunakan untuk semua form): {$fungsiKomponenForm1}");
        
        // ==========================================================
        // LOOP UNTUK SETIAP FORM
        // ==========================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING THERMOINDICATOR FORM {$formIndex}");
            \Log::info("=========================================");
            
            // AMBIL ALAT STANDAR
            $alatStandar = $findArrayValue('alat_standar', $formIndex);
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
                if (!is_array($alatStandar)) {
                    $alatStandar = [$alatStandar];
                }
            }
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            $alatStandar = array_filter($alatStandar);
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            // AMBIL TIPE WIRE
            $tipeWire = $findValue('tipe_wire', $formIndex);
            if (empty($tipeWire) && $formIndex == 1) {
                $tipeWire = $request->input('tipe_wire', null);
            }
            
            // ==========================================================
            // 🔥 AMBIL KETERANGAN FUNGSI KOMPONEN
            // ==========================================================
            $keteranganFungsiKomponen = null;
            
            $keteranganKeys = [
                "form_{$formIndex}_keterangan_fungsi_komponen",
                "keterangan_fungsi_komponen_{$formIndex}",
                "keterangan_fungsi_komponen"
            ];
            
            foreach ($keteranganKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    $keteranganFungsiKomponen = $value;
                    \Log::info("✅ Found keterangan_fungsi_komponen for form {$formIndex} using key: {$key} = {$keteranganFungsiKomponen}");
                    break;
                }
            }
            
            $fungsiKomponen = $fungsiKomponenForm1;
            
            if ($formIndex > 1) {
                \Log::info("📌 Form {$formIndex} using fungsi_komponen from Form 1: {$fungsiKomponen}");
            }
            
            \Log::info("📝 Data untuk form {$formIndex}:", [
                'standard' => $standardValue,
                'tipe_wire' => $tipeWire,
                'fungsi_komponen' => $fungsiKomponen,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                'is_form1' => ($formIndex == 1)
            ]);
            
            // ==========================================================
            // SIMPAN HEAD THERMOINDICATOR
            // ==========================================================
            HeadThermoIndicator::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'certificate_id' => $certificateId,
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-37',
                    'satuan_std' => '°C',
                    'satuan_uut' => '°C',
                    'fungsi_komponen' => $fungsiKomponen,
                    'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                ]
            );
            
            \Log::info("✅ HeadThermoIndicator saved for form {$formIndex}", [
                'fungsi_komponen' => $fungsiKomponen,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen
            ]);
            
            // ==========================================================
            // 🔥 SIMPAN DETAIL MEASUREMENTS (DIPERBAIKI)
            // ==========================================================
            $detailCount = 0;
            
            // LOG SEMUA DATA YANG MASUK UNTUK DEBUG
            $allInput = $request->all();
            $detailKeys = array_filter(array_keys($allInput), function($key) use ($formIndex) {
                return (strpos($key, "form_{$formIndex}_pembacaan_alat") === 0 || 
                        strpos($key, "form_{$formIndex}_naik_") === 0 || 
                        strpos($key, "form_{$formIndex}_turun_") === 0 ||
                        strpos($key, 'pembacaan_alat') === 0 || 
                        strpos($key, 'naik_') === 0 || 
                        strpos($key, 'turun_') === 0);
            });
            \Log::info("📊 Detail keys found in request for form {$formIndex}:", $detailKeys);
            
            // 🔥 AMBIL DATA DARI FORM REQUEST
            // Untuk row 1-10 (kiri)
            for ($row = 1; $row <= 10; $row++) {
                $PenunjukanSTD = null;
                $UUTnaik = null;
                $UUTturun = null;
                
                // ==========================================
                // FORMAT 1: form_{formIndex}_pembacaan_alat_kiri_{formIndex}_{row}_tab1
                // ==========================================
                $keyStd = "form_{$formIndex}_pembacaan_alat_kiri_{$formIndex}_{$row}_tab1";
                $keyNaik = "form_{$formIndex}_naik_kiri_{$formIndex}_{$row}_tab1";
                $keyTurun = "form_{$formIndex}_turun_kiri_{$formIndex}_{$row}_tab1";
                
                $PenunjukanSTD = $request->input($keyStd);
                $UUTnaik = $request->input($keyNaik);
                $UUTturun = $request->input($keyTurun);
                
                // ==========================================
                // FORMAT 2: form_{formIndex}_pembacaan_alat_kiri_{row}_tab1
                // ==========================================
                if ($PenunjukanSTD === null && $UUTnaik === null && $UUTturun === null) {
                    $keyStd = "form_{$formIndex}_pembacaan_alat_kiri_{$row}_tab1";
                    $keyNaik = "form_{$formIndex}_naik_kiri_{$row}_tab1";
                    $keyTurun = "form_{$formIndex}_turun_kiri_{$row}_tab1";
                    
                    $PenunjukanSTD = $request->input($keyStd);
                    $UUTnaik = $request->input($keyNaik);
                    $UUTturun = $request->input($keyTurun);
                }
                
                // ==========================================
                // FORMAT 3: pembacaan_alat_kiri_{formIndex}_{row}_tab1 (tanpa prefix form)
                // ==========================================
                if ($PenunjukanSTD === null && $UUTnaik === null && $UUTturun === null) {
                    $keyStd = "pembacaan_alat_kiri_{$formIndex}_{$row}_tab1";
                    $keyNaik = "naik_kiri_{$formIndex}_{$row}_tab1";
                    $keyTurun = "turun_kiri_{$formIndex}_{$row}_tab1";
                    
                    $PenunjukanSTD = $request->input($keyStd);
                    $UUTnaik = $request->input($keyNaik);
                    $UUTturun = $request->input($keyTurun);
                }
                
                // ==========================================
                // FORMAT 4: pembacaan_alat_kiri_{row}_tab1 (untuk form 1)
                // ==========================================
                if (($PenunjukanSTD === null && $UUTnaik === null && $UUTturun === null) && $formIndex == 1) {
                    $keyStd = "pembacaan_alat_kiri_{$row}_tab1";
                    $keyNaik = "naik_kiri_{$row}_tab1";
                    $keyTurun = "turun_kiri_{$row}_tab1";
                    
                    $PenunjukanSTD = $request->input($keyStd);
                    $UUTnaik = $request->input($keyNaik);
                    $UUTturun = $request->input($keyTurun);
                }
                
                // Log untuk debugging
                if ($PenunjukanSTD !== null || $UUTnaik !== null || $UUTturun !== null) {
                    \Log::info("📊 Form {$formIndex} Row {$row} (kiri) - STD: {$PenunjukanSTD}, Naik: {$UUTnaik}, Turun: {$UUTturun}");
                }
                
                if (!empty($PenunjukanSTD) || !empty($UUTnaik) || !empty($UUTturun)) {
                    DetailThermoIndicator::updateOrCreate(
                        [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'row_number' => $row,
                            'side' => 'kiri'
                        ],
                        [
                            'PenunjukanSTD' => $PenunjukanSTD,
                            'UUTnaik' => $UUTnaik,
                            'UUTturun' => $UUTturun,
                        ]
                    );
                    $detailCount++;
                }
            }
            
            // 🔥 Untuk row 11-20 (kanan)
            for ($row = 11; $row <= 20; $row++) {
                $PenunjukanSTD = null;
                $UUTnaik = null;
                $UUTturun = null;
                
                // ==========================================
                // FORMAT 1: form_{formIndex}_pembacaan_alat_kanan_{formIndex}_{row}_tab1
                // ==========================================
                $keyStd = "form_{$formIndex}_pembacaan_alat_kanan_{$formIndex}_{$row}_tab1";
                $keyNaik = "form_{$formIndex}_naik_kanan_{$formIndex}_{$row}_tab1";
                $keyTurun = "form_{$formIndex}_turun_kanan_{$formIndex}_{$row}_tab1";
                
                $PenunjukanSTD = $request->input($keyStd);
                $UUTnaik = $request->input($keyNaik);
                $UUTturun = $request->input($keyTurun);
                
                // ==========================================
                // FORMAT 2: form_{formIndex}_pembacaan_alat_kanan_{row}_tab1
                // ==========================================
                if ($PenunjukanSTD === null && $UUTnaik === null && $UUTturun === null) {
                    $keyStd = "form_{$formIndex}_pembacaan_alat_kanan_{$row}_tab1";
                    $keyNaik = "form_{$formIndex}_naik_kanan_{$row}_tab1";
                    $keyTurun = "form_{$formIndex}_turun_kanan_{$row}_tab1";
                    
                    $PenunjukanSTD = $request->input($keyStd);
                    $UUTnaik = $request->input($keyNaik);
                    $UUTturun = $request->input($keyTurun);
                }
                
                // ==========================================
                // FORMAT 3: pembacaan_alat_kanan_{formIndex}_{row}_tab1
                // ==========================================
                if ($PenunjukanSTD === null && $UUTnaik === null && $UUTturun === null) {
                    $keyStd = "pembacaan_alat_kanan_{$formIndex}_{$row}_tab1";
                    $keyNaik = "naik_kanan_{$formIndex}_{$row}_tab1";
                    $keyTurun = "turun_kanan_{$formIndex}_{$row}_tab1";
                    
                    $PenunjukanSTD = $request->input($keyStd);
                    $UUTnaik = $request->input($keyNaik);
                    $UUTturun = $request->input($keyTurun);
                }
                
                if (!empty($PenunjukanSTD) || !empty($UUTnaik) || !empty($UUTturun)) {
                    DetailThermoIndicator::updateOrCreate(
                        [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'row_number' => $row,
                            'side' => 'kanan'
                        ],
                        [
                            'PenunjukanSTD' => $PenunjukanSTD,
                            'UUTnaik' => $UUTnaik,
                            'UUTturun' => $UUTturun,
                        ]
                    );
                    $detailCount++;
                }
            }
            
            \Log::info("📊 DETAIL SAVED FOR FORM {$formIndex}: {$detailCount} records");
            
            // ==========================================================
            // SIMPAN DATA REPEATABILITY (DIPERBAIKI)
            // ==========================================================
            $repeatabilityData = [];
            for ($row = 1; $row <= 2; $row++) {
                for ($col = 1; $col <= 3; $col++) {
                    $value = null;
                    
                    // Coba berbagai format dengan prefix form
                    $keyFormats = [
                        "form_{$formIndex}_rep{$row}_col{$col}_{$formIndex}_tab1",
                        "form_{$formIndex}_rep{$row}_col{$col}_{$formIndex}",
                        "form_{$formIndex}_rep{$row}_col{$col}_tab1",
                        "form_{$formIndex}_rep{$row}_col{$col}",
                        "rep{$row}_col{$col}_{$formIndex}_tab1",
                        "rep{$row}_col{$col}_{$formIndex}",
                        "rep{$row}_col{$col}",
                    ];
                    
                    foreach ($keyFormats as $key) {
                        $temp = $request->input($key);
                        if ($temp !== null && $temp !== '') {
                            $value = $temp;
                            \Log::debug("Found repeatability for key: {$key} = {$value}");
                            break;
                        }
                    }
                    
                    if ($value !== null && $value !== '') {
                        $fieldName = "rep0" . (($row-1)*3 + $col);
                        $repeatabilityData[$fieldName] = $value;
                    }
                }
            }
            
            $addData = [
                'calibration_id' => $calibration->id,
                'form_index' => $formIndex,
                'wireType' => $tipeWire,
            ];
            
            $addData = array_merge($addData, $repeatabilityData);
            
            $hasData = !empty($tipeWire) || count($repeatabilityData) > 0;
            
            if ($hasData) {
                AddThermoIndicator::updateOrCreate(
                    [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex
                    ],
                    $addData
                );
                \Log::info("✅ AddThermoIndicator saved for form {$formIndex}");
            }
        }
        
        // HAPUS DATA LAMA
        HeadThermoIndicator::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)->delete();
        
        DetailThermoIndicator::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)->delete();
        
        AddThermoIndicator::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)->delete();
        
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        \Log::info('✅ storeThermoindicator completed successfully');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeThermoindicator FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
private function updateThermoindicator($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateThermoindicator =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong atau MANUAL_INPUT):', [
                'certificate_id_lama' => $calibration->certificate_id,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        }
        
        // Update certificate_id di tabel calibration
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
            
            \Log::info('📝 UPDATE CERTIFICATE ID DI CALIBRATION:', [
                'certificate_id_baru' => $certificateIdBaru,
                'current_certificate_id' => $calibration->certificate_id
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Thermoindicator - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 1. AMBIL FUNGSI KOMPONEN DARI FORM 1 (UNTUK SEMUA FORM)
        // ==================================================================
        $fungsiKomponenForm1 = null;
        
        // Cari fungsi komponen dari request (Form 1)
        $fungsiKeys = [
            "form_1_fungsi_komponen",
            "fungsi_komponen_1",
            "fungsi_komponen"
        ];
        
        foreach ($fungsiKeys as $key) {
            $value = $request->input($key);
            if ($value !== null && $value !== '') {
                $fungsiKomponenForm1 = $value;
                \Log::info("✅ Found fungsi_komponen from Form 1 using key: {$key} = {$fungsiKomponenForm1}");
                break;
            }
        }
        
        // Jika tidak ditemukan di request, coba ambil dari database (Form 1)
        if ($fungsiKomponenForm1 === null) {
            $existingHead = HeadThermoIndicator::where('calibration_id', $calibration->id)
                ->where('form_index', 1)
                ->first();
            if ($existingHead) {
                $fungsiKomponenForm1 = $existingHead->fungsi_komponen;
                \Log::info("✅ Using existing fungsi_komponen from database (Form 1): {$fungsiKomponenForm1}");
            }
        }
        
        // Jika masih null, gunakan dari calibration
        if ($fungsiKomponenForm1 === null) {
            $fungsiKomponenForm1 = $calibration->kondisiAlat ?? null;
            \Log::info("✅ Using fungsi_komponen from calibration: {$fungsiKomponenForm1}");
        }
        
        \Log::info("📌 FUNGSI KOMPONEN FORM 1 (digunakan untuk semua form): {$fungsiKomponenForm1}");
        
        // ==================================================================
        // 2. UPDATE HEAD UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadThermoIndicator::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // 🔥 AMBIL ALAT STANDAR DARI alat_standar_{formIndex}[]
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            
            // Log untuk debugging
            \Log::info("📝 Raw alat_standar untuk form {$formIndex}:", [
                'alat_standar_raw' => $alatStandar,
                'alat_standar_type' => gettype($alatStandar)
            ]);
            
            // Pastikan dalam bentuk array
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            // Filter nilai kosong
            $alatStandar = array_filter($alatStandar);
            
            // Log setelah filter
            \Log::info("📝 Alat standar setelah filter untuk form {$formIndex}:", [
                'alatStandar_filtered' => $alatStandar,
                'count' => count($alatStandar)
            ]);
            
            // Simpan ke database
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            \Log::info("📝 Standard value untuk form {$formIndex}:", [
                'standardValue' => $standardValue
            ]);
            
            // AMBIL CALIBRATION METHOD
            $calibrationMethod = $request->input("calibrationMethod_{$formIndex}", 
                                $request->input("calibrationMethod", 'PAS-IK1102-37'));
            
            // ==========================================================
            // TENTUKAN FUNGSI KOMPONEN UNTUK FORM INI
            // - Form 1: ambil dari request
            // - Form > 1: gunakan nilai dari Form 1
            // ==========================================================
            $fungsiKomponen = null;
            $keteranganFungsiKomponen = null;
            
            if ($formIndex == 1) {
                // Form 1: ambil dari request
                $fungsiKomponen = $fungsiKomponenForm1;
            } else {
                // Form > 1: gunakan nilai dari Form 1
                $fungsiKomponen = $fungsiKomponenForm1;
                \Log::info("📌 Form {$formIndex} using fungsi_komponen from Form 1: {$fungsiKomponen}");
            }
            
            // AMBIL KETERANGAN FUNGSI KOMPONEN (UNTUK SETIAP FORM)
            $keteranganKeys = [
                "form_{$formIndex}_keterangan_fungsi_komponen",
                "keterangan_fungsi_komponen_{$formIndex}",
                "keterangan_fungsi_komponen"
            ];
            
            foreach ($keteranganKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    $keteranganFungsiKomponen = $value;
                    \Log::debug("Found keterangan_fungsi_komponen for form {$formIndex} using key: {$key} = {$keteranganFungsiKomponen}");
                    break;
                }
            }
            
            // Jika tidak ditemukan di request, gunakan yang sudah ada di database
            if ($keteranganFungsiKomponen === null && $head) {
                $keteranganFungsiKomponen = $head->keterangan_fungsi_komponen;
                \Log::debug("Using existing keterangan_fungsi_komponen from database: {$keteranganFungsiKomponen}");
            }
            
            $headData = [
                'standard' => $standardValue,
                'calibrationMethod' => $calibrationMethod,
                'satuan_std' => '°C',
                'satuan_uut' => '°C',
                // ==========================================================
                // FUNGSI KOMPONEN: Mengikuti Form 1 untuk semua form
                // KETERANGAN: Bisa diisi sendiri per form
                // ==========================================================
                'fungsi_komponen' => $fungsiKomponen,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
            ];
            
            // UPDATE CERTIFICATE ID UNTUK SEMUA HEAD
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'standard' => $head->standard,
                    'calibrationMethod' => $head->calibrationMethod,
                    'fungsi_komponen' => $head->fungsi_komponen,
                    'keterangan_fungsi_komponen' => $head->keterangan_fungsi_komponen,
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                $head = HeadThermoIndicator::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        $deletedHead = HeadThermoIndicator::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        \Log::info("🗑️ Deleted {$deletedHead} head records for excess forms");
        
        // ==================================================================
        // 3. UPDATE ADD THERMOINDICATOR (TYPE WIRE & REPEATABILITY) PER FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $add = AddThermoIndicator::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // AMBIL TIPE WIRE
            $wireType = $request->input("wireType_{$formIndex}", '');
            
            // AMBIL REPEATABILITY DATA
            $addData = [
                'wireType' => $wireType,
                'rep01' => $request->input("rep01_{$formIndex}"),
                'rep02' => $request->input("rep02_{$formIndex}"),
                'rep03' => $request->input("rep03_{$formIndex}"),
                'rep04' => $request->input("rep04_{$formIndex}"),
                'rep05' => $request->input("rep05_{$formIndex}"),
            ];
            
            // Hapus nilai null
            $addData = array_filter($addData, function($value) {
                return $value !== null && $value !== '';
            });
            
            \Log::info("📝 Add data untuk form {$formIndex}:", $addData);
            
            if (!empty($addData)) {
                if ($add) {
                    $add->update($addData);
                    \Log::info("✅ Add data updated for form {$formIndex}", ['add_id' => $add->id]);
                } else {
                    $addData['calibration_id'] = $calibration->id;
                    $addData['form_index'] = $formIndex;
                    AddThermoIndicator::create($addData);
                    \Log::info("➕ New add data created for form {$formIndex}");
                }
            } else {
                if ($add) {
                    $add->delete();
                    \Log::info("🗑️ Add data deleted for form {$formIndex} (no data)");
                }
            }
        }
        
        // Hapus add data untuk form yang tidak digunakan
        $deletedAdd = AddThermoIndicator::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        \Log::info("🗑️ Deleted {$deletedAdd} add records for excess forms");
        
        // ==================================================================
        // 4. UPDATE DETAIL MEASUREMENTS (DATA KALIBRASI) PER FORM
        // ==================================================================
        // Hapus semua detail lama
        DetailThermoIndicator::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Ambil data detail dari request dengan suffix _formIndex
            $penunjukanSTDArray = $request->input("PenunjukanSTD_{$formIndex}", []);
            $uutNaikArray = $request->input("UUTnaik_{$formIndex}", []);
            $uutTurunArray = $request->input("UUTturun_{$formIndex}", []);
            
            \Log::info("📊 Detail data untuk form {$formIndex}:", [
                'penunjukanSTD_count' => count($penunjukanSTDArray),
                'uutNaik_count' => count($uutNaikArray),
                'uutTurun_count' => count($uutTurunArray)
            ]);
            
            // Loop untuk 20 baris (kiri 10 + kanan 10)
            for ($i = 0; $i < 20; $i++) {
                $penunjukanSTD = $penunjukanSTDArray[$i] ?? '';
                $uutNaik = $uutNaikArray[$i] ?? '';
                $uutTurun = $uutTurunArray[$i] ?? '';
                
                // ✅ PERBAIKAN: Cek apakah ada data (termasuk nilai 0)
                // Nilai 0 atau 0.0 dianggap valid dan tetap disimpan
                $hasPenunjukanSTD = $penunjukanSTD !== '' && $penunjukanSTD !== null;
                $hasUutNaik = $uutNaik !== '' && $uutNaik !== null;
                $hasUutTurun = $uutTurun !== '' && $uutTurun !== null;
                
                $hasData = $hasPenunjukanSTD || $hasUutNaik || $hasUutTurun;
                
                // Log khusus untuk data 0
                if ($penunjukanSTD === '0' || $penunjukanSTD === '0.0' || $penunjukanSTD === 0) {
                    \Log::debug("📝 Data STD 0 ditemukan di baris {$i}, form {$formIndex}: akan disimpan");
                }
                
                if ($hasData) {
                    // Tentukan side dan row_number
                    $side = ($i < 10) ? 'kiri' : 'kanan';
                    $rowNumber = $i + 1;
                    
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'row_number' => $rowNumber,
                        'side' => $side,
                        'PenunjukanSTD' => $hasPenunjukanSTD ? str_replace(',', '.', $penunjukanSTD) : null,
                        'UUTnaik' => $hasUutNaik ? str_replace(',', '.', $uutNaik) : null,
                        'UUTturun' => $hasUutTurun ? str_replace(',', '.', $uutTurun) : null,
                    ];
                    
                    DetailThermoIndicator::create($detailData);
                    $totalDetailCount++;
                    
                    // Log data yang disimpan
                    if ($penunjukanSTD === '0' || $penunjukanSTD === '0.0') {
                        \Log::debug("✅ Data STD 0 berhasil disimpan:", [
                            'row' => $rowNumber,
                            'value' => $penunjukanSTD,
                            'detail_id' => $detailData['PenunjukanSTD']
                        ]);
                    }
                }
            }
        }
        
        \Log::info("✅ Saved {$totalDetailCount} detail measurements for Thermoindicator");
        
        // ==================================================================
        // 5. UPDATE FIELD LAINNYA DI CALIBRATION
        // ==================================================================
        $updateData = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->brandAlat ?? $calibration->brandAlat,
            'kodeAlat' => $request->kodeAlat ?? $calibration->kodeAlat,
            'typeAlat' => $request->typeAlat ?? $calibration->typeAlat,
            'NoSeri' => $request->NoSeri ?? $calibration->NoSeri,
            // ✅ TAMBAHKAN INI UNTUK RENTANG UKUR
            'rangeMin' => $request->rentang_ukur_min ?? $calibration->rangeMin,
            'rangeMax' => $request->rentang_ukur_max ?? $calibration->rangeMax,
            'kapasitas' => $request->kapasitas ?? $calibration->kapasitas,
            'resolusi' => $request->resolusi ?? $calibration->resolusi,
            'pemilikAlat' => $request->pemilikAlat ?? $calibration->pemilikAlat,
            'tanggalMasuk' => $request->tanggalMasuk ?? $calibration->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi ?? $calibration->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $calibration->tempatKalibrasi,
            'jenisPembacaan' => $request->jenisPembacaan ?? $calibration->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT ?? $calibration->lokasiPT,
            'kode_th' => $request->kode_th ?? $calibration->kode_th,
            // FUNGSI KOMPONEN: Ambil dari Form 1 (sudah disimpan di head form 1)
            'kondisiAlat' => $fungsiKomponenForm1 ?? $calibration->kondisiAlat,
            // KETERANGAN: Untuk calibration, ambil dari form 1 (sebagai default)
            'keterangan' => $request->input('keterangan_fungsi_komponen') ?? 
                           $request->input('keterangan') ?? 
                           $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1 ?? $calibration->RT_condition1,
            'RT_condition2' => $request->RT_condition2 ?? $calibration->RT_condition2,
            'RT_condition3' => $request->RT_condition3 ?? $calibration->RT_condition3,
            'RH_condition1' => $request->RH_condition1 ?? $calibration->RH_condition1,
            'RH_condition2' => $request->RH_condition2 ?? $calibration->RH_condition2,
            'RH_condition3' => $request->RH_condition3 ?? $calibration->RH_condition3,
            'calibratedBy' => $request->calibratedBy ?? $calibration->calibratedBy,
            'verifiedBy' => $request->verifiedBy ?? $calibration->verifiedBy,
            'jumlah_form' => $jumlahForm,
        ];
        
        // Log data yang akan diupdate
        \Log::info('📝 UPDATE CALIBRATION DATA:', [
            'rangeMin' => $updateData['rangeMin'],
            'rangeMax' => $updateData['rangeMax'],
            'kapasitas' => $updateData['kapasitas'],
            'resolusi' => $updateData['resolusi'],
        ]);
        
        $calibration->update($updateData);
        $calibration->refresh();
        
        // ==================================================================
        // 6. FINAL VERIFICATION
        // ==================================================================
        $allHeads = HeadThermoIndicator::where('calibration_id', $calibration->id)->get();
        $allAdd = AddThermoIndicator::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailThermoIndicator::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🎯 FINAL SUMMARY AFTER UPDATE:', [
            'total_heads' => $allHeads->count(),
            'heads_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_add' => $allAdd->count(),
            'add_by_form' => $allAdd->groupBy('form_index')->map->count(),
            'total_details' => $allDetails->count(),
            'details_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id,
            'fungsi_komponen_form1' => $fungsiKomponenForm1,
            'rangeMin' => $calibration->rangeMin,
            'rangeMax' => $calibration->rangeMax,
        ]);
        
        \Log::info('🎉 updateThermoindicator completed successfully', [
            'calibration_id' => $calibration->id,
            'details_created' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateThermoindicator FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function storePlasticShim($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('🔧 ===== START storePlasticShim =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storePlasticShim called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dengan berbagai kemungkinan nama field
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        // Coba juga dengan format array
        $alatStandarArray = $request->input('alat_standar', []);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        // Coba dengan alat_standar_text (fallback)
        $alatStandarText = $this->getRequestValue($request, 'alat_standar_text', $tabId);
        if ($alatStandarText && !in_array($alatStandarText, $alatStandar)) {
            $alatStandar[] = $alatStandarText;
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar for Plastic Shim:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. AMBIL SATUAN UNIT
        // ==================================================================
        $satuanUnit = $this->getRequestValue($request, 'unit_nominal', $tabId);
        if (empty($satuanUnit)) {
            $satuanUnit = $this->getRequestValue($request, 'satuan_unit', $tabId);
        }
        
        \Log::info('📏 Satuan unit:', ['satuan_unit' => $satuanUnit]);
        
        // ==================================================================
        // 3. SIMPAN KE HEAD PLASTIC SHIM
        // ==================================================================
        $head = HeadPlasticShim::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-60',
            'satuan_unit' => $satuanUnit,
            'form_index' => 1,
        ]);
        
        \Log::info('✅ Head Plastic Shim saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS - 20 BARIS (DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving Plastic Shim detail measurements...');
        $detailCount = 0;
        
        for ($row = 1; $row <= 20; $row++) {
            // Ambil nilai nominal dengan berbagai kemungkinan format
            $nominalValue = $this->getRequestValue($request, "nominal_{$row}", $tabId);
            if (!$nominalValue) {
                $nominalValue = $this->getRequestValue($request, "nominal", $tabId);
                if (is_array($nominalValue)) {
                    $nominalValue = $nominalValue[$row - 1] ?? null;
                }
            }
            if (!$nominalValue) {
                $nominalValue = $this->getRequestValue($request, "nilai_nominal_{$row}", $tabId);
            }
            
            // Ambil serial number
            $serialNumber = $this->getRequestValue($request, "serial_number_{$row}", $tabId);
            if (!$serialNumber) {
                $serialNumber = $this->getRequestValue($request, "serial_number", $tabId);
                if (is_array($serialNumber)) {
                    $serialNumber = $serialNumber[$row - 1] ?? null;
                }
            }
            if (!$serialNumber) {
                $serialNumber = $this->getRequestValue($request, "sn_{$row}", $tabId);
            }
            
            // Ambil 5 nilai penunjukan (STD01 - STD05)
            $penunjukanValues = [];
            for ($col = 1; $col <= 5; $col++) {
                $penunjukan = $this->getRequestValue($request, "penunjukan_{$row}_{$col}", $tabId);
                if (!$penunjukan) {
                    $penunjukan = $this->getRequestValue($request, "penunjukan", $tabId);
                    if (is_array($penunjukan)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $penunjukan = $penunjukan[$index] ?? null;
                    }
                }
                if (!$penunjukan) {
                    $penunjukan = $this->getRequestValue($request, "STD{$col}_{$row}", $tabId);
                }
                if (!$penunjukan) {
                    $penunjukan = $this->getRequestValue($request, "pembacaan_{$row}_{$col}", $tabId);
                }
                $penunjukanValues[] = $penunjukan;
            }
            
            // Cek apakah ada data untuk baris ini
            $hasNominal = !empty($nominalValue);
            $hasSerial = !empty($serialNumber);
            $hasPenunjukan = !empty($penunjukanValues[0]) || !empty($penunjukanValues[1]) || 
                            !empty($penunjukanValues[2]) || !empty($penunjukanValues[3]) || 
                            !empty($penunjukanValues[4]);
            
            if ($hasNominal || $hasSerial || $hasPenunjukan) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'form_index' => 1,
                    'nominal' => $nominalValue,
                    'sn' => $serialNumber ?? '',
                    'STD01' => $penunjukanValues[0] ?? null,
                    'STD02' => $penunjukanValues[1] ?? null,
                    'STD03' => $penunjukanValues[2] ?? null,
                    'STD04' => $penunjukanValues[3] ?? null,
                    'STD05' => $penunjukanValues[4] ?? null,
                ];
                
                // Jika masih ada yang kosong, coba cari dengan format array STD values
                if (empty($detailData['STD01']) && empty($detailData['STD02']) && 
                    empty($detailData['STD03']) && empty($detailData['STD04']) && 
                    empty($detailData['STD05'])) {
                    
                    $stdArray = $this->getRequestValue($request, "STD", $tabId);
                    if (is_array($stdArray)) {
                        $index = ($row - 1) * 5;
                        $detailData['STD01'] = $stdArray[$index] ?? null;
                        $detailData['STD02'] = $stdArray[$index + 1] ?? null;
                        $detailData['STD03'] = $stdArray[$index + 2] ?? null;
                        $detailData['STD04'] = $stdArray[$index + 3] ?? null;
                        $detailData['STD05'] = $stdArray[$index + 4] ?? null;
                    }
                }
                
                \Log::debug("📝 Saving Plastic Shim detail row {$row}:", [
                    'nominal' => $detailData['nominal'],
                    'sn' => $detailData['sn'],
                ]);
                
                DetailPlasticShim::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} Plastic Shim detail measurements");
        
        // ==================================================================
        // 5. SIMPAN INFORMASI TANDA TANGAN (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $signatureData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $signatureData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $signatureData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        if (!empty($signatureData)) {
            $calibration->update($signatureData);
            \Log::info('✅ Signature data saved:', $signatureData);
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $totalDetailRecords = DetailPlasticShim::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Plastic Shim):', [
            'calibration_id' => $calibration->id,
            'detail_records' => $totalDetailRecords,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'satuan_unit' => $satuanUnit,
        ]);
        
        \Log::info('🎉 storePlasticShim COMPLETED');
        return $head;
        
    } catch (\Exception $e) {
        \Log::error('💥 Error storing Plastic Shim data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailPlasticShim::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Plastic Shim: " . $e->getMessage());
    }
}

private function updatePlasticShim($request, $calibration, $certificateId)
{
    try {
        \Log::info('🚀 START updatePlasticShim');
        
        // ==================================================================
        // 1. TENTUKAN NAMA ALAT YANG BARU
        // ==================================================================
        $namaAlatLama = $calibration->namaAlat;
        $namaAlatBaru = $namaAlatLama;
        
        if ($request->filled('nama_alat') && $request->nama_alat !== 'MANUAL_INPUT') {
            $namaAlatBaru = $request->nama_alat;
        }
        
        // Update nama alat jika berubah
        $namaAlatUpdated = false;
        if ($namaAlatLama !== $namaAlatBaru) {
            $calibration->update(['namaAlat' => $namaAlatBaru]);
            $namaAlatUpdated = true;
            \Log::info('✅ Nama alat diupdate:', ['dari' => $namaAlatLama, 'menjadi' => $namaAlatBaru]);
        }
        
        // ==================================================================
        // 2. GENERATE CERTIFICATE ID BARU JIKA NAMA ALAT BERUBAH
        // ==================================================================
        $certificateIdLama = $calibration->certificate_id;
        $certificateIdBaru = $certificateIdLama;
        
        if ($namaAlatUpdated || empty($certificateIdLama) || strpos($certificateIdLama, 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatBaru);
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            \Log::info('🆔 Certificate ID updated:', [
                'lama' => $certificateIdLama,
                'baru' => $certificateIdBaru
            ]);
        }
        
        $certificateIdToUse = $certificateIdBaru;
        
        // ==================================================================
        // 3. AMBIL ATAU BUAT HEAD PLASTIC SHIM
        // ==================================================================
        $head = HeadPlasticShim::where('calibration_id', $calibration->id)->first();
        
        // ==================================================================
        // 4. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandarText = $request->alat_standar_text ?? '';
        
        // ==================================================================
        // 5. UPDATE ATAU BUAT HEAD
        // ==================================================================
        if ($head) {
            $head->update([
                'certificate_id' => $certificateIdToUse,
                'standard' => $alatStandarText,
                'calibrationMethod' => 'PAS-IK1102-60',
                'satuan_unit' => $request->unit_nominal ?? $head->satuan_unit,
            ]);
            \Log::info('✅ Head Plastic Shim updated:', ['head_id' => $head->id]);
        } else {
            $head = HeadPlasticShim::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateIdToUse,
                'standard' => $alatStandarText,
                'calibrationMethod' => 'PAS-IK1102-60',
                'satuan_unit' => $request->unit_nominal ?? '',
            ]);
            \Log::info('✅ Head Plastic Shim created:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 6. UPDATE DETAIL PLASTIC SHIM
        // ==================================================================
        \Log::info('📊 Updating Plastic Shim detail measurements...');
        
        // Hapus detail lama
  
        
        $detailCount = 0;
        
        // ✅ PERBAIKAN: Ambil data dari array 'detail' sesuai format form
        if ($request->has('detail') && is_array($request->detail)) {
            foreach ($request->detail as $index => $detailData) {
                // Cek apakah baris ini memiliki data
                $hasData = false;
                
                // Cek nominal
                if (!empty($detailData['nominal'])) {
                    $hasData = true;
                }
                
                // Cek serial number
                if (!empty($detailData['sn'])) {
                    $hasData = true;
                }
                
                // Cek STD01 - STD05
                for ($j = 1; $j <= 5; $j++) {
                    $field = "STD0" . $j;
                    if (!empty($detailData[$field])) {
                        $hasData = true;
                        break;
                    }
                }
                
                // Simpan jika ada data
                if ($hasData) {
                    $saveData = [
                        'calibration_id' => $calibration->id,
                        'nominal' => $detailData['nominal'] ?? null,
                        'sn' => $detailData['sn'] ?? null,
                        'STD01' => $detailData['STD01'] ?? null,
                        'STD02' => $detailData['STD02'] ?? null,
                        'STD03' => $detailData['STD03'] ?? null,
                        'STD04' => $detailData['STD04'] ?? null,
                        'STD05' => $detailData['STD05'] ?? null,
                    ];

                    \Log::info("📝 Saving Plastic Shim detail row " . ($index) . ":", [
                        'nominal' => $saveData['nominal'],
                        'sn' => $saveData['sn'],
                        'STD01' => $saveData['STD01'],
                        'STD02' => $saveData['STD02'],
                        'STD03' => $saveData['STD03'],
                        'STD04' => $saveData['STD04'],
                        'STD05' => $saveData['STD05'],
                    ]);
                    
                    DetailPlasticShim::create($saveData);
                    $detailCount++;
                }
            }
        } else {
            \Log::warning('⚠️ Tidak ada data detail yang dikirim');
        }
        
        \Log::info("✅ Saved $detailCount Plastic Shim detail measurements");

        // ==================================================================
        // 7. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', $updateData);
        }

        \Log::info('🎉 updatePlasticShim COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePlasticShim:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Plastic Shim: " . $e->getMessage());
    }
}
private function storeProfilProjector($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeProfilProjector');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeProfilProjector called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (empty($alatStandar)) {
            $alatStandar = $request->input('alat_standar', []);
        }
        
        // Pastikan dalam bentuk array
        if (!is_array($alatStandar)) {
            $alatStandar = [$alatStandar];
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar Profil Projector:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. PROSES NAMA KALIBRATOR DAN PEMERIKSA
        // ==================================================================
        $namaKalibrator = trim($this->getRequestValue($request, 'calibrated_by', $tabId) ?? '');
        $namaPemeriksa = trim($this->getRequestValue($request, 'verified_by', $tabId) ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);
        
       // ==================================================================
        // 3. SIMPAN KE HEAD PROFIL PROJECTOR
        // ==================================================================
        $head = HeadProfilProjector::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'satuan_titik_ukur' => $this->getRequestValue($request, 'satuan_titik_ukur', $tabId) ?? '',
            'satuan_alat_x' => $this->getRequestValue($request, 'satuan_alat_x', $tabId) ?? '',
            'satuan_alat_y' => $this->getRequestValue($request, 'satuan_alat_y', $tabId) ?? '',
            'kapasitas_x' => $this->getRequestValue($request, 'kapasitas_x', $tabId) ?? '',
            'kapasitas_y' => $this->getRequestValue($request, 'kapasitas_y', $tabId) ?? '',
            'resolusi_x' => $this->getRequestValue($request, 'resolusi_x', $tabId) ?? '',
            'resolusi_y' => $this->getRequestValue($request, 'resolusi_y', $tabId) ?? '',
            'calibrationMethod' => 'PAS-IK1102-42',
        ]);
        
        \Log::info('✅ HeadProfilProjector saved:', [
            'head_id' => $head->id,
            'satuan_titik_ukur' => $this->getRequestValue($request, 'satuan_titik_ukur', $tabId),
            'satuan_alat_x' => $this->getRequestValue($request, 'satuan_alat_x', $tabId),
            'satuan_alat_y' => $this->getRequestValue($request, 'satuan_alat_y', $tabId),
            'kapasitas_x' => $this->getRequestValue($request, 'kapasitas_x', $tabId),
            'kapasitas_y' => $this->getRequestValue($request, 'kapasitas_y', $tabId),
            'resolusi_x' => $this->getRequestValue($request, 'resolusi_x', $tabId),
            'resolusi_y' => $this->getRequestValue($request, 'resolusi_y', $tabId)
        ]);
        
        // ==================================================================
        // 4. SIMPAN DETAIL PROFIL PROJECTOR
        // ==================================================================
        \Log::info('📊 Saving DetailProfilProjector data...');
        $detailCount = 0;
        
        // Cari semua titik ukur yang ada (pattern: titik_ukur_{i} atau titik_ukur_{i}_tab{tabId})
        $maxRows = 0;
        
        // Cari jumlah maksimum baris
        for ($i = 1; $i <= 50; $i++) {
            $titikUkurValue = $this->getRequestValue($request, "titik_ukur_{$i}", $tabId);
            if (!empty($titikUkurValue)) {
                $maxRows = $i;
            }
        }
        
        // Jika menggunakan pattern _tab1, cari juga
        if ($maxRows == 0) {
            for ($i = 1; $i <= 50; $i++) {
                $fieldName = "titik_ukur_{$i}_tab{$tabId}";
                $titikUkurValue = $request->input($fieldName);
                if (!empty($titikUkurValue)) {
                    $maxRows = $i;
                }
            }
        }
        
        if ($maxRows == 0) {
            $maxRows = 10; // default jika tidak ada data
        }
        
        \Log::info('📝 Jumlah baris profil projector:', [
            'jumlah_baris' => $maxRows,
            'tab_id' => $tabId
        ]);
        
        // Proses setiap baris
        for ($i = 1; $i <= $maxRows; $i++) {
            // Ambil titik ukur
            $titikUkur = $this->getRequestValue($request, "titik_ukur_{$i}", $tabId);
            if (empty($titikUkur)) {
                // Coba dengan format _tab
                $titikUkur = $request->input("titik_ukur_{$i}_tab{$tabId}");
            }
            
            if (empty($titikUkur)) {
                continue;
            }
            
            // Ambil nilai X1..X5 dan Y1..Y5
            $xValues = [];
            $yValues = [];
            $hasData = false;
            
            for ($j = 1; $j <= 5; $j++) {
                // Ambil nilai X
                $xVal = $this->getRequestValue($request, "x_{$i}_{$j}", $tabId);
                if (empty($xVal)) {
                    $xVal = $request->input("x_{$i}_{$j}_tab{$tabId}");
                }
                if ($xVal !== null && $xVal !== '') {
                    $xVal = str_replace(',', '.', $xVal);
                    $hasData = true;
                }
                
                // Ambil nilai Y
                $yVal = $this->getRequestValue($request, "y_{$i}_{$j}", $tabId);
                if (empty($yVal)) {
                    $yVal = $request->input("y_{$i}_{$j}_tab{$tabId}");
                }
                if ($yVal !== null && $yVal !== '') {
                    $yVal = str_replace(',', '.', $yVal);
                    $hasData = true;
                }
                
                $xValues[] = $xVal;
                $yValues[] = $yVal;
            }
            
            if ($hasData) {
                // Konversi titik ukur (ganti koma dengan titik jika perlu)
                $titikUkur = str_replace(',', '.', $titikUkur);
                
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'titikUkur' => $titikUkur,
                    'X1' => $xValues[0] ?? null,
                    'X2' => $xValues[1] ?? null,
                    'X3' => $xValues[2] ?? null,
                    'X4' => $xValues[3] ?? null,
                    'X5' => $xValues[4] ?? null,
                    'Y1' => $yValues[0] ?? null,
                    'Y2' => $yValues[1] ?? null,
                    'Y3' => $yValues[2] ?? null,
                    'Y4' => $yValues[3] ?? null,
                    'Y5' => $yValues[4] ?? null,
                ];
                
                \Log::debug("💾 Saving DetailProfilProjector row {$i}:", $detailData);
                
                DetailProfilProjector::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} DetailProfilProjector records");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Update kondisi lingkungan
        $environmentData = [];
        
        $temperature = $this->getRequestValue($request, 'temperature', $tabId);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $this->getRequestValue($request, 'humidity', $tabId);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Kondisi lingkungan:', $environmentData);
        }
        
        // Update rentang ukur (jika ada)
        $rentangMin = $this->getRequestValue($request, 'rentang_ukur_min', $tabId);
        if ($rentangMin !== null && $rentangMin !== '') {
            $updateData['range_min'] = $rentangMin;
        }
        
        $rentangMax = $this->getRequestValue($request, 'rentang_ukur_max', $tabId);
        if ($rentangMax !== null && $rentangMax !== '') {
            $updateData['range_max'] = $rentangMax;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailProfilProjector::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Profil Projector):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'total_rows' => $maxRows,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);
        
        \Log::info('🎉 storeProfilProjector COMPLETED');
        return $head;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeProfilProjector:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailProfilProjector::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Profil Projector: " . $e->getMessage());
    }
}

private function updateProfilProjector($request, $calibration, $certificateId)
{
    try {
        \Log::info('🚀 START updateProfilProjector', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $certificateId
        ]);

        // ==================================================================
        // 1. VALIDASI DAN AMBIL CERTIFICATE ID
        // ==================================================================
        $finalCertificateId = $certificateId;
        
        // Jika certificate_id dari parameter null, ambil dari calibration
        if (empty($finalCertificateId)) {
            $finalCertificateId = $calibration->certificate_id;
            \Log::info('📋 Mengambil certificate_id dari calibration:', [
                'certificate_id' => $finalCertificateId
            ]);
        }
        
        // Jika masih null, ambil dari head yang sudah ada di database
        if (empty($finalCertificateId)) {
            $existingHead = HeadProfilProjector::where('calibration_id', $calibration->id)->first();
            if ($existingHead && !empty($existingHead->certificate_id)) {
                $finalCertificateId = $existingHead->certificate_id;
                \Log::info('📋 Mengambil certificate_id dari existing head:', [
                    'certificate_id' => $finalCertificateId,
                    'head_id' => $existingHead->id
                ]);
            }
        }
        
        // Jika masih null, coba ambil dari detail
        if (empty($finalCertificateId)) {
            $existingDetail = DetailProfilProjector::where('calibration_id', $calibration->id)->first();
            if ($existingDetail && !empty($existingDetail->certificate_id)) {
                $finalCertificateId = $existingDetail->certificate_id;
                \Log::info('📋 Mengambil certificate_id dari existing detail:', [
                    'certificate_id' => $finalCertificateId
                ]);
            }
        }
        
        // Jika masih null, throw error
        if (empty($finalCertificateId)) {
            \Log::error('❌ Certificate ID tidak ditemukan untuk Profil Projector update', [
                'calibration_id' => $calibration->id,
                'certificate_id_from_param' => $certificateId,
                'certificate_id_from_calibration' => $calibration->certificate_id
            ]);
            throw new \Exception('Certificate ID is required for Profil Projector update');
        }

        // ==================================================================
        // 2. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Profil Projector (update):', [
            'alat_standar' => $alatStandar,
            'alat_standar_string' => $alatStandarString
        ]);

        // ==================================================================
        // 3. PROSES NAMA KALIBRATOR DAN PEMERIKSA (jika ada)
        // ==================================================================
        $namaKalibrator = trim($request->calibrated_by ?? '');
        $namaPemeriksa = trim($request->verified_by ?? '');
        
        \Log::info('👤 Nama Kalibrator (update):', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa (update):', ['nama' => $namaPemeriksa]);

        // ==================================================================
        // 4. UPDATE HEAD PROFIL PROJECTOR
        // ==================================================================
        $head = HeadProfilProjector::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📊 Head Profil Projector BEFORE update:', [
            'head_exists' => $head ? true : false,
            'head_id' => $head->id ?? null,
            'certificate_id_before' => $head->certificate_id ?? null,
        ]);
        
       $headData = [
            'certificate_id' => $finalCertificateId,
            'standard' => $alatStandarString,
            'satuan_titik_ukur' => $request->satuan_titik_ukur ?? '',
            'satuan_alat_x' => $request->satuan_alat_x ?? '',
            'satuan_alat_y' => $request->satuan_alat_y ?? '',
            'kapasitas_x' => $request->kapasitas_x ?? '',
            'kapasitas_y' => $request->kapasitas_y ?? '',
            'resolusi_x' => $request->resolusi_x ?? '',
            'resolusi_y' => $request->resolusi_y ?? '',
            'calibrationMethod' => 'PAS-IK1102-42',
        ];
        
        if ($head) {
            $head->update($headData);
            $head->refresh();
            \Log::info('✅ Head Profil Projector updated:', ['head_id' => $head->id]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadProfilProjector::create($headData);
            \Log::info('✅ Head Profil Projector created:', ['head_id' => $head->id]);
        }
        
        \Log::info('✅ Head Profil Projector AFTER update:', [
            'head_id' => $head->id,
            'certificate_id_after' => $head->certificate_id,
            'satuan_titik_ukur' => $head->satuan_titik_ukur,
            'satuan_alat_x' => $head->satuan_alat_x,
            'satuan_alat_y' => $head->satuan_alat_y,
        ]);

        // ==================================================================
        // 5. UPDATE DETAIL PROFIL PROJECTOR (20 BARIS)
        // ==================================================================
        \Log::info('📊 Updating Profil Projector detail measurements (20 baris)...');
        
        // Hapus data lama
        $deletedCount = DetailProfilProjector::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old detail records:', ['count' => $deletedCount]);
        
        $detailCount = 0;
        
        // Proses 20 baris (sesuai tabel)
        for ($i = 1; $i <= 20; $i++) {
            // Ambil data dari request
            $titikUkur = $request->{"titik_ukur_{$i}"} ?? null;
            
            // Data X
            $x1 = $request->{"x_{$i}_1"} ?? null;
            $x2 = $request->{"x_{$i}_2"} ?? null;
            $x3 = $request->{"x_{$i}_3"} ?? null;
            $x4 = $request->{"x_{$i}_4"} ?? null;
            $x5 = $request->{"x_{$i}_5"} ?? null;
            
            // Data Y
            $y1 = $request->{"y_{$i}_1"} ?? null;
            $y2 = $request->{"y_{$i}_2"} ?? null;
            $y3 = $request->{"y_{$i}_3"} ?? null;
            $y4 = $request->{"y_{$i}_4"} ?? null;
            $y5 = $request->{"y_{$i}_5"} ?? null;
            
            \Log::debug("🔍 Row {$i} data from request (update):", [
                'titikUkur' => $titikUkur,
                'X1' => $x1, 'X2' => $x2, 'X3' => $x3, 'X4' => $x4, 'X5' => $x5,
                'Y1' => $y1, 'Y2' => $y2, 'Y3' => $y3, 'Y4' => $y4, 'Y5' => $y5,
            ]);
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($titikUkur) ||
                      !empty($x1) || !empty($x2) || !empty($x3) || !empty($x4) || !empty($x5) ||
                      !empty($y1) || !empty($y2) || !empty($y3) || !empty($y4) || !empty($y5);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'certificate_id' => $finalCertificateId,
                    'titikUkur' => $titikUkur,
                    'X1' => $x1,
                    'X2' => $x2,
                    'X3' => $x3,
                    'X4' => $x4,
                    'X5' => $x5,
                    'Y1' => $y1,
                    'Y2' => $y2,
                    'Y3' => $y3,
                    'Y4' => $y4,
                    'Y5' => $y5,
                ];

                \Log::debug("💾 Saving Profil Projector detail row {$i} (update):", $detailData);
                
                DetailProfilProjector::create($detailData);
                $detailCount++;
                
                \Log::debug("✅ Saved Profil Projector row {$i} (update)");
            } else {
                \Log::debug("⏭️ Skipping row {$i} - no data");
            }
        }
        
        \Log::info("✅ Updated {$detailCount} Profil Projector detail measurements");

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi (update):', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa (update):', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        // Pastikan certificate_id di calibration juga terupdate
        if (!empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data', $updateData);
        }

        // ==================================================================
        // 7. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailProfilProjector::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Profil Projector):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'total_rows' => 20,
            'certificate_id' => $finalCertificateId,
            'certificate_id_source' => $certificateId ? 'parameter' : ($calibration->certificate_id ? 'calibration' : 'existing_data'),
            'alat_standar' => $alatStandarString,
            'satuan_titik_ukur' => $head->satuan_titik_ukur,
            'satuan_alat_x' => $head->satuan_alat_x,
            'satuan_alat_y' => $head->satuan_alat_y,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updateProfilProjector COMPLETED');
        
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateProfilProjector:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'certificate_id' => $certificateId ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Profil Projector: " . $e->getMessage());
    }
}


private function storeSurfaceRoughnessTester($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('🔧 ===== START storeSurfaceRoughnessTester =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeSurfaceRoughnessTester called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandarArray = [];
        
        // Cari alat standar dari checkbox/select dengan berbagai format
        $alatStandar = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($alatStandar)) {
            foreach ($alatStandar as $value) {
                if ($value && !in_array($value, $alatStandarArray)) {
                    $alatStandarArray[] = $value;
                }
            }
        } elseif ($alatStandar) {
            $alatStandarArray[] = $alatStandar;
        }
        
        // Coba juga dengan format alat_standar_1, alat_standar_2, dll
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandarArray)) {
                $alatStandarArray[] = $value;
            }
        }
        
        // Coba dengan alat_standar_text (fallback)
        $alatStandarText = $this->getRequestValue($request, 'alat_standar_text', $tabId);
        if ($alatStandarText && !in_array($alatStandarText, $alatStandarArray)) {
            if (is_array($alatStandarText)) {
                foreach ($alatStandarText as $value) {
                    if ($value && !in_array($value, $alatStandarArray)) {
                        $alatStandarArray[] = $value;
                    }
                }
            } else {
                $alatStandarArray[] = $alatStandarText;
            }
        }
        
        $alatStandarString = !empty($alatStandarArray) ? implode(', ', $alatStandarArray) : '';
        
        \Log::info('🔧 Alat standar Surface Roughness Tester:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. AMBIL SATUAN UNIT (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $satuanUnit = $this->getRequestValue($request, 'satuan_unit', $tabId);
        $satuanPenunjukanAlat = $this->getRequestValue($request, 'satuan_penunjukan_alat', $tabId);
        $satuanCutOff = $this->getRequestValue($request, 'satuan_cut_off', $tabId);
        
        // ==================================================================
        // 3. SIMPAN KE HEAD SURFACE ROUGHNESS TESTER
        // ==================================================================
        $head = HeadSurfaceRoughnessTester::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-60',
            'satuan_unit' => $satuanUnit,
            'satuan_penunjukan_alat' => $satuanPenunjukanAlat,
            'satuan_cut_off' => $satuanCutOff,
            'form_index' => 1,
        ]);
        
        \Log::info('✅ Head Surface Roughness Tester saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS (DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving detail Surface Roughness Tester measurements...');
        $detailCount = 0;
        
        for ($row = 1; $row <= 10; $row++) {
            // Ambil nominal STD
            $nominalSTD = $this->getRequestValue($request, "nominalSTD_{$row}", $tabId);
            if (!$nominalSTD) {
                $nominalSTD = $this->getRequestValue($request, "nominalSTD", $tabId);
                if (is_array($nominalSTD)) {
                    $nominalSTD = $nominalSTD[$row - 1] ?? null;
                }
            }
            
            // Ambil parameter
            $parameter = $this->getRequestValue($request, "parameter_{$row}", $tabId);
            if (!$parameter) {
                $parameter = $this->getRequestValue($request, "parameter", $tabId);
                if (is_array($parameter)) {
                    $parameter = $parameter[$row - 1] ?? null;
                }
            }
            
            // Ambil nilai ukurAlat1, ukurAlat2, ukurAlat3
            $ukurAlat1 = $this->getRequestValue($request, "ukurAlat1_{$row}", $tabId);
            if (!$ukurAlat1) {
                $ukurAlat1 = $this->getRequestValue($request, "ukurAlat1", $tabId);
                if (is_array($ukurAlat1)) {
                    $ukurAlat1 = $ukurAlat1[$row - 1] ?? null;
                }
            }
            
            $ukurAlat2 = $this->getRequestValue($request, "ukurAlat2_{$row}", $tabId);
            if (!$ukurAlat2) {
                $ukurAlat2 = $this->getRequestValue($request, "ukurAlat2", $tabId);
                if (is_array($ukurAlat2)) {
                    $ukurAlat2 = $ukurAlat2[$row - 1] ?? null;
                }
            }
            
            $ukurAlat3 = $this->getRequestValue($request, "ukurAlat3_{$row}", $tabId);
            if (!$ukurAlat3) {
                $ukurAlat3 = $this->getRequestValue($request, "ukurAlat3", $tabId);
                if (is_array($ukurAlat3)) {
                    $ukurAlat3 = $ukurAlat3[$row - 1] ?? null;
                }
            }
            
            // Ambil CutOff
            $cutOff = $this->getRequestValue($request, "CutOff_{$row}", $tabId);
            if (!$cutOff) {
                $cutOff = $this->getRequestValue($request, "CutOff", $tabId);
                if (is_array($cutOff)) {
                    $cutOff = $cutOff[$row - 1] ?? null;
                }
            }
            if (!$cutOff) {
                $cutOff = $this->getRequestValue($request, "cut_off_{$row}", $tabId);
            }
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($nominalSTD) || !empty($parameter) || 
                       !empty($ukurAlat1) || !empty($ukurAlat2) || !empty($ukurAlat3) || 
                       !empty($cutOff);
            
            if ($hasData) {
                $detailData = [
                    'head_surface_roughness_tester_id' => $head->id,
                    'calibration_id' => $calibration->id,
                    'form_index' => 1,
                    'nominalSTD' => $nominalSTD,
                    'parameter' => $parameter,
                    'ukurAlat1' => $ukurAlat1,
                    'ukurAlat2' => $ukurAlat2,
                    'ukurAlat3' => $ukurAlat3,
                    'CutOff' => $cutOff,
                ];
                
                \Log::debug("📝 Saving Surface Roughness Tester detail row {$row}:", [
                    'nominalSTD' => $detailData['nominalSTD'],
                    'parameter' => $detailData['parameter']
                ]);
                
                DetailSurfaceRoughnessTester::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Surface Roughness Tester");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TTD (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('👤 Calibrated by saved:', ['name' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('👤 Verified by saved:', ['name' => $verifiedBy]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with signature data');
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (Surface Roughness Tester):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $detailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'satuan_unit' => $satuanUnit,
        ]);
        
        \Log::info('🎉 storeSurfaceRoughnessTester COMPLETED');
        return $head;
        
    } catch (\Exception $e) {
        \Log::error('💥 Error storing Surface Roughness Tester data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function updateSurfaceRoughnessTester($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateSurfaceRoughnessTester');
        \Log::info('📝 Updating Surface Roughness Tester data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headSurfaceRoughnessTester;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandarString = $request->alat_standar_text ?? '';
        
        \Log::info('🔧 Alat standar Surface Roughness Tester selected:', ['alat_standar' => $alatStandarString]);
        
        // ==================================================================
        // 2. UPDATE ATAU CREATE HEAD SURFACE ROUGHNESS TESTER
        // ==================================================================
        $head = HeadSurfaceRoughnessTester::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-60',
            'satuan_unit' => $request->satuan_unit,
            'satuan_penunjukan_alat' => $request->satuan_penunjukan_alat,
            'satuan_cut_off' => $request->satuan_cut_off,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ Head Surface Roughness Tester updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadSurfaceRoughnessTester::create($headData);
            \Log::info('➕ Head Surface Roughness Tester created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL SURFACE ROUGHNESS TESTER - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating detail Surface Roughness Tester measurements...');
        
        // Hapus data lama terlebih dahulu
        $deletedDetails = DetailSurfaceRoughnessTester::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old detail records");
        
        $detailCount = 0;
        
        // Proses 10 baris data - LANGSUNG TANPA FORMAT
        for ($i = 1; $i <= 10; $i++) {
            // Ambil data dari request - LANGSUNG TANPA FORMAT
            $nominalSTD = $request->input("nominalSTD_{$i}");
            $parameter = $request->input("parameter_{$i}");
            $ukurAlat1 = $request->input("ukurAlat1_{$i}");
            $ukurAlat2 = $request->input("ukurAlat2_{$i}");
            $ukurAlat3 = $request->input("ukurAlat3_{$i}");
            $cutOff = $request->input("CutOff_{$i}");
            
            $hasData = !empty($nominalSTD) || !empty($parameter) || 
                       !empty($ukurAlat1) || !empty($ukurAlat2) || 
                       !empty($ukurAlat3) || !empty($cutOff);
            
            if ($hasData) {
                $detailData = [
                    'head_surface_roughness_tester_id' => $head->id,
                    'calibration_id' => $calibration->id,
                    'nominalSTD' => $nominalSTD,    // LANGSUNG, tanpa format
                    'parameter' => $parameter,      // LANGSUNG, tanpa format
                    'ukurAlat1' => $ukurAlat1,      // LANGSUNG, tanpa format
                    'ukurAlat2' => $ukurAlat2,      // LANGSUNG, tanpa format
                    'ukurAlat3' => $ukurAlat3,      // LANGSUNG, tanpa format
                    'CutOff' => $cutOff,            // LANGSUNG, tanpa format
                ];
                
                \Log::debug("📝 Saving Surface Roughness Tester detail row {$i}:", $detailData);
                
                DetailSurfaceRoughnessTester::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Surface Roughness Tester");
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Ambil nama dari input calibrated_by dan verified_by
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headSurfaceRoughnessTester;
        $totalDetailRecords = DetailSurfaceRoughnessTester::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Surface Roughness Tester):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $totalDetailRecords,
            'satuan_unit' => $request->satuan_unit,
            'satuan_penunjukan_alat' => $request->satuan_penunjukan_alat,
            'satuan_cut_off' => $request->satuan_cut_off,
            'alat_standar' => $alatStandarString,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);
        
        \Log::info('🎉 updateSurfaceRoughnessTester COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateSurfaceRoughnessTester:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Surface Roughness Tester: " . $e->getMessage());
    }
}

private function storeUltrasonicThicknessGauge($request, $calibration, $certificateId, $tabId = null, $isMultipleSubmit = false, $jumlahForm = 1)
{
    try {
        \Log::info('🚀 START storeUltrasonicThicknessGauge', [
            'calibration_id' => $calibration->id,
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI
        // ==================================================================
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            $legacyKey = empty($additionalParams) ? $baseKey : $baseKey . '_' . implode('_', $additionalParams);
            $legacyValue = $request->input($legacyKey);
            if ($legacyValue !== null && $legacyValue !== '') {
                 return $legacyValue;
            }
            
            return null;
        };

        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        $headsCreated = [];
        $savedDetailCount = 0;
        
        // ==================================================================
        // 3. LOOP UNTUK SETIAP FORM (1 SAMPAI JUMLAH FORM)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("🔄 Processing Form {$formIndex} of {$jumlahForm}");
            
            // Generate Sub-Certificate ID
            $currentCertificateId = $certificateId;
            if ($jumlahForm > 1 && $formIndex > 1) {
                $suffix = chr(64 + $formIndex); // A=65, B=66, etc
                $currentCertificateId = $certificateId . '-' . $suffix;
            }
            
            // Ambil Satuan Unit
            $satuanUnit = $findValue('satuan_unit', $formIndex);
        
            
            // Ambil Keterangan Fungsi Komponen per form (independent, tidak diikuti form 1)
            $keteranganFungsiKomponen = $findValue('keterangan_fungsi_komponen', $formIndex);
            \Log::info("📝 keterangan_fungsi_komponen for form {$formIndex}: " . ($keteranganFungsiKomponen ?? 'null'));

            
            // Ambil Alat Standar
            $alatStandarArray = $findArrayValue('alat_standar', $formIndex);
            if (empty($alatStandarArray) && $formIndex == 1) {
                $alatStandarArray = $request->input('alat_standar', []);
                if (!is_array($alatStandarArray)) {
                    $alatStandarArray = [$alatStandarArray];
                }
            }
            $alatStandarString = implode(', ', array_filter($alatStandarArray));
            if (empty($alatStandarString)) {
                $alatStandarString = $findValue('alat_standar_text', $formIndex) ?? '';
            }
            if (empty($alatStandarString)) {
                $alatStandarString = $findValue('alat_standar', $formIndex) ?? '';
            }
            
            // Simpan ke Head Ultrasonic Thickness Gauge
            $head = HeadUltrasonicThicknessGauge::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $currentCertificateId,
                'standard' => 'GAUGE BLOCK SET',
                'calibrationMethod' => 'PAS-IK1102-01 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)',
                'satuan_unit' => $satuanUnit,
                'form_index' => $formIndex,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
            ]);
            
            $headsCreated[] = $head;
            
            // Simpan Detail
            $jumlahBaris = 15;
            for ($i = 1; $i <= $jumlahBaris; $i++) {
                $nominal = $findValue('nominal', $formIndex, [$i]);
                $ulangan1 = $findValue('penunjukan', $formIndex, [$i, 1]);
                $ulangan2 = $findValue('penunjukan', $formIndex, [$i, 2]);
                $ulangan3 = $findValue('penunjukan', $formIndex, [$i, 3]);
                $ulangan4 = $findValue('penunjukan', $formIndex, [$i, 4]);
                $ulangan5 = $findValue('penunjukan', $formIndex, [$i, 5]);
                
                $hasData = !empty($nominal) || 
                           !empty($ulangan1) || !empty($ulangan2) || !empty($ulangan3) || 
                           !empty($ulangan4) || !empty($ulangan5);
                           
                if ($hasData) {
                    DetailUltrasonicThicknessGauge::create([
                        'calibration_id' => $calibration->id,
                        'nominalSTD' => $nominal,
                        'ulangan01' => $ulangan1,
                        'ulangan02' => $ulangan2,
                        'ulangan03' => $ulangan3,
                        'ulangan04' => $ulangan4,
                        'ulangan05' => $ulangan5,
                        'form_index' => $formIndex,
                    ]);
                    $savedDetailCount++;
                }
            }
            
            // Data untuk Update Calibration
            if ($formIndex === 1) {
                $updateData = [];
                
                $namaKalibrator = trim($findValue('calibrated_by', $formIndex) ?? '');
                if (!empty($namaKalibrator)) {
                    $updateData['calibrated_by'] = $namaKalibrator;
                }
                
                $namaPemeriksa = trim($findValue('verified_by', $formIndex) ?? '');
                if (!empty($namaPemeriksa)) {
                    $updateData['verified_by'] = $namaPemeriksa;
                }
                
                $uncertainty = $findValue('uncertainty', $formIndex);
                if (!empty($uncertainty)) {
                    $updateData['uncertainty'] = $uncertainty;
                    $updateData['keterangan'] = $findValue('conclusion', $formIndex) ?? '';
                }
                
                $environmentData = [];
                $temperature = $findValue('temperature', $formIndex);
                if ($temperature) {
                    $environmentData['temperature'] = $temperature;
                }
                $humidity = $findValue('humidity', $formIndex);
                if ($humidity) {
                    $environmentData['humidity'] = $humidity;
                }
                
                if (!empty($environmentData)) {
                    $updateData['environment_condition'] = json_encode($environmentData);
                }
                
                $rentangMin = $findValue('rentang_ukur_min', $formIndex);
                if ($rentangMin !== null && $rentangMin !== '') {
                    $updateData['range_min'] = $rentangMin;
                }
                
                $rentangMax = $findValue('rentang_ukur_max', $formIndex);
                if ($rentangMax !== null && $rentangMax !== '') {
                    $updateData['range_max'] = $rentangMax;
                }
                
                if (!empty($updateData)) {
                    $calibration->update($updateData);
                    \Log::info('✅ Calibration updated with additional data from Form 1');
                }
            }
        }
        
        \Log::info('📋 STORE SUMMARY (Ultrasonic Thickness Gauge):', [
            'calibration_id' => $calibration->id,
            'heads_created' => count($headsCreated),
            'detail_records' => $savedDetailCount,
            'certificate_id_base' => $certificateId,
        ]);
        
        \Log::info('🎉 storeUltrasonicThicknessGauge COMPLETED');
        return $headsCreated[0] ?? null;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeUltrasonicThicknessGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        try {
            DetailUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->delete();
            HeadUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->delete();
        } catch (\Exception $rollbackError) {
            \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
        }
        
        throw new \Exception("Gagal menyimpan data Ultrasonic Thickness Gauge: " . $e->getMessage());
    }
}
private function updateUltrasonicThicknessGauge($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateUltrasonicThicknessGauge =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong atau MANUAL_INPUT):', [
                'certificate_id_lama' => $calibration->certificate_id,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        }
        
        // Update certificate_id di tabel calibration
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
            
            \Log::info('📝 UPDATE CERTIFICATE ID DI CALIBRATION:', [
                'certificate_id_baru' => $certificateIdBaru,
                'current_certificate_id' => $calibration->certificate_id
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Ultrasonic Thickness Gauge - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);

        // ==================================================================
        // 1. UPDATE CALIBRATION DENGAN DATA DARI FORM PERTAMA
        //    (Kapasitas, Resolusi, dan field lainnya)
        // ==================================================================
        // 🔥 KAPASITAS & RESOLUSI diambil dari form pertama (kapasitas_1, resolusi_1)
        // Atau fallback ke field tanpa suffix (kapasitas, resolusi)
        $kapasitas = $request->input("kapasitas_1", $request->input("kapasitas", $calibration->kapasitas));
        $resolusi = $request->input("resolusi_1", $request->input("resolusi", $calibration->resolusi));
        
        $updateData = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->brandAlat ?? $request->merek ?? $calibration->brandAlat,
            'kodeAlat' => $request->kodeAlat ?? $calibration->kodeAlat,
            'typeAlat' => $request->typeAlat ?? $calibration->typeAlat,
            'NoSeri' => $request->NoSeri ?? $request->no_seri ?? $calibration->NoSeri,
            'pemilikAlat' => $request->pemilikAlat ?? $request->nama_pemilik ?? $calibration->pemilikAlat,
            'tanggalMasuk' => $request->tanggalMasuk ?? $request->tanggal_alat_masuk ?? $calibration->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi ?? $request->tanggal_kalibrasi ?? $calibration->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $request->tempat_kalibrasi ?? $calibration->tempatKalibrasi,
            'jenisPembacaan' => $request->jenisPembacaan ?? $request->jenis_pembacaan ?? $calibration->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT ?? $request->lokasi_pt ?? $calibration->lokasiPT,
            'kode_th' => $request->kode_th ?? $calibration->kode_th,
            'kondisiAlat' => $request->kondisiAlat ?? $request->fungsi_komponen ?? $calibration->kondisiAlat,
            'keterangan' => $request->keterangan ?? $request->keterangan_fungsi_komponen ?? $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1 ?? $request->suhu_awal ?? $calibration->RT_condition1,
            'RT_condition2' => $request->RT_condition2 ?? $request->suhu_tengah ?? $calibration->RT_condition2,
            'RT_condition3' => $request->RT_condition3 ?? $request->suhu_akhir ?? $calibration->RT_condition3,
            'RH_condition1' => $request->RH_condition1 ?? $request->rh_awal ?? $calibration->RH_condition1,
            'RH_condition2' => $request->RH_condition2 ?? $request->rh_tengah ?? $calibration->RH_condition2,
            'RH_condition3' => $request->RH_condition3 ?? $request->rh_akhir ?? $calibration->RH_condition3,
            'calibratedBy' => $request->calibratedBy ?? $request->calibrated_by ?? $calibration->calibratedBy,
            'verifiedBy' => $request->verifiedBy ?? $request->verified_by ?? $calibration->verifiedBy,
            'jumlah_form' => $jumlahForm,
            // 🔥 KAPASITAS & RESOLUSI DISIMPAN DI CALIBRATION
            'kapasitas' => $kapasitas,
            'resolusi' => $resolusi,
        ];
        
        // Filter data yang null/empty untuk tidak mengupdate jika tidak diisi
        $updateData = array_filter($updateData, function($value) {
            return $value !== null && $value !== '';
        });
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            $calibration->refresh();
            \Log::info('✅ Calibration updated with data:', [
                'kapasitas' => $calibration->kapasitas,
                'resolusi' => $calibration->resolusi,
                'fields' => array_keys($updateData)
            ]);
        }

        // ==================================================================
        // 2. UPDATE HEAD UNTUK SETIAP FORM (SATUAN UNIT, STANDARD, DLL)
        //    TIDAK ADA RENTANG UKUR DI ULTRASONIC THICKNESS GAUGE
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadUltrasonicThicknessGauge::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // 🔥 AMBIL DATA DARI REQUEST (PER FORM)
            $satuanUnit = $request->input("satuan_unit_{$formIndex}", 
                          $request->input("satuan_unit", 'mm'));
            
            // Alat Standar & Metode Kalibrasi
            $alatStandarText = $request->input("alat_standar_text_{$formIndex}", 
                               $request->input("alat_standar_text", 'GAUGE BLOCK SET'));
            
            $calibrationMethod = $request->input("calibrationMethod_{$formIndex}", 
                                $request->input("calibrationMethod", 'PAS-IK1102-59 (IS 15468 : 2004)'));
            
            $headData = [
                'standard' => $alatStandarText,
                'calibrationMethod' => $calibrationMethod,
                'satuan_unit' => $satuanUnit,
                // ❌ TIDAK ADA rentang_ukur_min & rentang_ukur_max
            ];
            
            \Log::info("📝 Head data untuk form {$formIndex}:", [
                'satuan_unit' => $satuanUnit,
                'standard' => $alatStandarText,
                'calibrationMethod' => $calibrationMethod,
            ]);
            
            // 🔥 UPDATE CERTIFICATE ID UNTUK SEMUA HEAD
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'satuan_unit' => $head->satuan_unit,
                    'standard' => $head->standard,
                    'certificate_id' => $head->certificate_id ?? 'not_set'
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                $head = HeadUltrasonicThicknessGauge::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadUltrasonicThicknessGauge::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();

        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS (UJI SKALA NOMINAL) PER FORM
        // ==================================================================
        \Log::info('📊 Updating detail measurements...');
        
        // Hapus data lama
        DetailUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            for ($i = 1; $i <= 15; $i++) {
                // Cek apakah ada data untuk baris ini
                $hasData = false;
                
                // 🔥 Ambil data dengan prefix form index
                $nominalValue = $request->input("nominal_{$formIndex}_{$i}");
                
                // Cek penunjukan dengan prefix form index
                for ($j = 1; $j <= 5; $j++) {
                    $penunjukanValue = $request->input("penunjukan_{$formIndex}_{$i}_{$j}");
                    if (!empty(trim($penunjukanValue ?? ''))) {
                        $hasData = true;
                        break;
                    }
                }
                
                // Jika nominal tidak kosong, anggap ada data
                if (!empty(trim($nominalValue ?? ''))) {
                    $hasData = true;
                }
                
                // Simpan jika ada data
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'nominalSTD' => $nominalValue,
                        'ulangan01' => $request->input("penunjukan_{$formIndex}_{$i}_1"),
                        'ulangan02' => $request->input("penunjukan_{$formIndex}_{$i}_2"),
                        'ulangan03' => $request->input("penunjukan_{$formIndex}_{$i}_3"),
                        'ulangan04' => $request->input("penunjukan_{$formIndex}_{$i}_4"),
                        'ulangan05' => $request->input("penunjukan_{$formIndex}_{$i}_5"),
                    ];

                    \Log::debug("📝 Saving detail row {$i} for form {$formIndex}:", $detailData);
                    
                    DetailUltrasonicThicknessGauge::create($detailData);
                    $totalDetailCount++;
                }
            }
        }
        
        \Log::info("✅ Saved {$totalDetailCount} detail measurements for Ultrasonic Thickness Gauge");

        // Refresh untuk memastikan data terbaru
        $calibration->refresh();
        
        // ==================================================================
        // 4. FINAL VERIFICATION
        // ==================================================================
        $allHeads = HeadUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🎯 FINAL SUMMARY AFTER UPDATE:', [
            'calibration_id' => $calibration->id,
            'calibration_kapasitas' => $calibration->kapasitas,
            'calibration_resolusi' => $calibration->resolusi,
            'total_heads' => $allHeads->count(),
            'heads_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'heads_data' => $allHeads->map(function($h) {
                return [
                    'form_index' => $h->form_index,
                    'satuan_unit' => $h->satuan_unit,
                    'standard' => $h->standard,
                ];
            })->values(),
            'total_details' => $allDetails->count(),
            'details_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id,
            'nama_alat' => $calibration->namaAlat,
            'pemilik_alat' => $calibration->pemilikAlat,
        ]);

        \Log::info('🎉 updateUltrasonicThicknessGauge COMPLETED successfully', [
            'calibration_id' => $calibration->id,
            'details_created' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateUltrasonicThicknessGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Ultrasonic Thickness Gauge: " . $e->getMessage());
    }
}


private function storeThreadGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeThreadGauge');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeThreadGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. KELOLA ALAT STANDAR DENGAN DETAIL UKURAN
        // ==================================================================
        $alatStandarArray = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (empty($alatStandarArray)) {
            $alatStandarArray = $request->input('alat_standar', []);
        }
        
        // Pastikan dalam bentuk array
        if (!is_array($alatStandarArray)) {
            $alatStandarArray = [$alatStandarArray];
        }
        
        $alatStandarItems = [];
        
        // Iterasi setiap alat standar yang dipilih
        foreach ($alatStandarArray as $alat) {
            switch ($alat) {
                case 'Mesin ULM 01-600D':
                    $alatStandarItems[] = $alat;
                    break;
                    
                case 'Gauge Block':
                    // Cek apakah ada nilai gauge block yang dipilih
                    $gaugeBlock = $this->getRequestValue($request, 'gauge_block', $tabId);
                    if (!empty($gaugeBlock)) {
                        $alatStandarItems[] = $alat . ' ' . $gaugeBlock . ' mm';
                    } else {
                        $alatStandarItems[] = $alat . ' (tidak ada pilihan ukuran)';
                    }
                    break;
                    
                case 'Ring Gauge':
                    // Cek apakah ada nilai dari select atau manual
                    $ringGaugeSelect = $this->getRequestValue($request, 'ring_gauge_select', $tabId);
                    $ringGaugeManual = $this->getRequestValue($request, 'ring_gauge_manual', $tabId);
                    
                    if (!empty($ringGaugeSelect)) {
                        $alatStandarItems[] = $alat . ' ' . $ringGaugeSelect . ' mm';
                    } elseif (!empty($ringGaugeManual)) {
                        $alatStandarItems[] = $alat . ' ' . trim($ringGaugeManual) . ' mm';
                    } else {
                        $alatStandarItems[] = $alat . ' (tidak ada ukuran)';
                    }
                    break;
                    
                default:
                    $alatStandarItems[] = $alat;
            }
        }
        
        $alatStandarString = !empty($alatStandarItems) ? implode(', ', $alatStandarItems) : '';
        
        \Log::info('🔧 Alat standar with measurements:', [
            'alat_standar_array' => $alatStandarArray,
            'gauge_block' => $this->getRequestValue($request, 'gauge_block', $tabId),
            'ring_gauge_select' => $this->getRequestValue($request, 'ring_gauge_select', $tabId),
            'ring_gauge_manual' => $this->getRequestValue($request, 'ring_gauge_manual', $tabId),
            'alat_standar_string' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SENSOR TYPE HANDLING
        // ==================================================================
        $sensorType = $this->getRequestValue($request, 'sensor_type', $tabId);
        $sensorValue = null;
        $sensor = null;
        
        switch ($sensorType) {
            case 't_probe':
                $sensorValue = $this->getRequestValue($request, 't_probe_value', $tabId);
                $sensor = 'T-Probe: ' . $sensorValue;
                break;
            case 'hanging_wire':
                $sensorValue = $this->getRequestValue($request, 'hanging_wire_value', $tabId);
                $sensor = 'Hanging Wire: ' . $sensorValue;
                break;
            case 'wire_holder':
                $sensorValue = $this->getRequestValue($request, 'wire_holder_value', $tabId);
                $sensor = 'Wire (Holder): ' . $sensorValue;
                break;
            case 'ball':
                $sensorValue = $this->getRequestValue($request, 'ball_value', $tabId);
                $sensor = 'Ball: ' . $sensorValue;
                break;
            default:
                $sensor = null;
        }

        // ==================================================================
        // 3. HANDLE SUDUT ULIR
        // ==================================================================
        $sudutUlir = null;
        $sudutUlirType = $this->getRequestValue($request, 'sudut_ulir_type', $tabId);
        
        switch ($sudutUlirType) {
            case 'metrik':
                $sudutUlir = '60° (Ulir Metrik)';
                break;
            case 'non_metrik':
                $sudutUlir = '55° (Ulir Non Metrik)';
                break;
            case 'lainnya':
                $sudutUlirValue = $this->getRequestValue($request, 'sudut_ulir_lainnya', $tabId);
                $sudutUlir = $sudutUlirValue ? $sudutUlirValue . '' : null;
                break;
            default:
                $sudutUlir = null;
        }

        // ==================================================================
        // 4. NAMA KALIBRATOR & PEMERIKSA
        // ==================================================================
        $namaKalibrator = trim($this->getRequestValue($request, 'calibrated_by', $tabId) ?? '');
        $namaPemeriksa = trim($this->getRequestValue($request, 'verified_by', $tabId) ?? '');
        
        \Log::info('👤 Nama Kalibrator:', ['nama' => $namaKalibrator]);
        \Log::info('👤 Nama Pemeriksa:', ['nama' => $namaPemeriksa]);

        // ==================================================================
        // 5. CATATAN
        // ==================================================================
        $catatan = $this->getRequestValue($request, 'catatan', $tabId);

        \Log::info('📏 Thread Gauge Complete Data:', [
            'alat_standar' => $alatStandarString,
            'sensor_type' => $sensorType,
            'sensor_value' => $sensorValue,
            'sudut_ulir_type' => $sudutUlirType,
            'sudut_ulir' => $sudutUlir,
            'catatan' => substr($catatan, 0, 100) . (strlen($catatan) > 100 ? '...' : ''),
            'calibrated_by' => $namaKalibrator,
            'verified_by' => $namaPemeriksa,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 6. SIMPAN KE HEAD THREAD GAUGE
        // ==================================================================
        $head = HeadThreadGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-64',
            'catatan' => $catatan,
            'jenis_thread' => $request->jenis_thread,
        ]);

        \Log::info('✅ Head Thread Gauge saved:', ['head_id' => $head->id]);

        // ==================================================================
        // 7. SIMPAN DETAIL THREAD GAUGE
        // ==================================================================
        \Log::info('📊 Saving Thread Gauge detail measurements...');
        
        // Ambil data GO Side dengan getRequestValue
        $nilaiNominalGo = $this->getRequestValue($request, 'nilai_nominal_go', $tabId);
        $kodeGo = $this->getRequestValue($request, 'kode_go', $tabId);
        $satuanGo = $this->getRequestValue($request, 'satuan_go', $tabId);
        $goAtasX = $this->getRequestValue($request, 'go_atas_x', $tabId);
        $goAtasY = $this->getRequestValue($request, 'go_atas_y', $tabId);
        $goBawahX = $this->getRequestValue($request, 'go_bawah_x', $tabId);
        $goBawahY = $this->getRequestValue($request, 'go_bawah_y', $tabId);
        
        // Ambil data NOT GO Side dengan getRequestValue
        $nilaiNominalNotGo = $this->getRequestValue($request, 'nilai_nominal_not_go', $tabId);
        $kodeNotGo = $this->getRequestValue($request, 'kode_not_go', $tabId);
        $satuanNotGo = $this->getRequestValue($request, 'satuan_not_go', $tabId);
        $notGoAtasX = $this->getRequestValue($request, 'not_go_atas_x', $tabId);
        $notGoAtasY = $this->getRequestValue($request, 'not_go_atas_y', $tabId);
        $notGoBawahX = $this->getRequestValue($request, 'not_go_bawah_x', $tabId);
        $notGoBawahY = $this->getRequestValue($request, 'not_go_bawah_y', $tabId);
        
        // Ambil data pitch
        $ukuranPitch = $this->getRequestValue($request, 'ukuran_pitch', $tabId);
        $satuanPitch = $this->getRequestValue($request, 'satuan_pitch', $tabId);
        
        // Cek apakah ada data yang perlu disimpan
        $hasGoData = !empty($nilaiNominalGo) || !empty($goAtasX) || !empty($goAtasY) ||
                     !empty($goBawahX) || !empty($goBawahY);
        
        $hasNotGoData = !empty($nilaiNominalNotGo) || !empty($notGoAtasX) || !empty($notGoAtasY) ||
                        !empty($notGoBawahX) || !empty($notGoBawahY);
        
        // Simpan detail jika ada data
        if ($hasGoData || $hasNotGoData || !empty($sensor) || !empty($ukuranPitch)) {
            $detailData = [
                'calibration_id' => $calibration->id,
                'head_thread_gauge_id' => $head->id,
                
                // Sensor Data
                'sensor' => $sensor,
                
                // GO Data
                'kodeGO' => $kodeGo,
                'satuan_go' => $satuanGo,
                'nominalGO' => $nilaiNominalGo,
                'GOatasX1' => $goAtasX,
                'GOatasY1' => $goAtasY,
                'GObawahX1' => $goBawahX,
                'GObawahY1' => $goBawahY,
                
                // NOT GO Data
                'kodeNOTGO' => $kodeNotGo,
                'satuan_not_go' => $satuanNotGo,
                'nominalNOTGO' => $nilaiNominalNotGo,
                'NOTGOatasX1' => $notGoAtasX,
                'NOTGOatasY1' => $notGoAtasY,
                'NOTGObawahX1' => $notGoBawahX,
                'NOTGObawahY1' => $notGoBawahY,
                
                // Pitch dan Sudut Ulir
                'ukuranPitch' => $ukuranPitch,
                'satuan_pitch' => $satuanPitch,
                'sudutUlir' => $sudutUlir,
            ];

            // Filter nilai null
            $detailDataFiltered = array_filter($detailData, function($value) {
                return $value !== null && $value !== '';
            });
            
            \Log::info('📝 Thread Gauge detail data to save:', $detailDataFiltered);
            
            $detail = DetailThreadGauge::create($detailDataFiltered);
            \Log::info('✅ Detail Thread Gauge saved:', ['detail_id' => $detail->id]);
            
            $detailCount = 1;
        } else {
            \Log::info('ℹ️ No detail data to save for Thread Gauge');
            $detailCount = 0;
        }

        // ==================================================================
        // 8. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Update nama kalibrator (jika diisi)
        if (!empty($namaKalibrator)) {
            $updateData['calibrated_by'] = $namaKalibrator;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $namaKalibrator]);
        }
        
        // Update nama pemeriksa (jika diisi)
        if (!empty($namaPemeriksa)) {
            $updateData['verified_by'] = $namaPemeriksa;
            \Log::info('📝 Nama diperiksa:', ['nama' => $namaPemeriksa]);
        }
        
        // Update uncertainty dan keterangan (jika ada)
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if (!empty($uncertainty)) {
            $updateData['uncertainty'] = $uncertainty;
            $updateData['keterangan'] = $this->getRequestValue($request, 'conclusion', $tabId) ?? '';
            \Log::info('📝 Uncertainty data:', ['uncertainty' => $uncertainty]);
        }
        
        // Update kondisi lingkungan (jika ada)
        $environmentData = [];
        
        $temperature = $this->getRequestValue($request, 'temperature', $tabId);
        if ($temperature) {
            $environmentData['temperature'] = $temperature;
        }
        
        $humidity = $this->getRequestValue($request, 'humidity', $tabId);
        if ($humidity) {
            $environmentData['humidity'] = $humidity;
        }
        
        if (!empty($environmentData)) {
            $updateData['environment_condition'] = json_encode($environmentData);
            \Log::info('🌡️ Kondisi lingkungan:', $environmentData);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data');
        }

        // ==================================================================
        // 9. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailThreadGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Thread Gauge):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'sensor' => $sensor,
            'sudut_ulir' => $sudutUlir,
        ]);

        \Log::info('🎉 storeThreadGauge COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeThreadGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailThreadGauge::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Thread Gauge: " . $e->getMessage());
    }
}

private function updateThreadGauge($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateThreadGauge', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $newCertificateId
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headThreadGauge;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // Jika certificate_id masih kosong, gunakan dari parameter atau generate
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $calibration->certificate_id;
        }
        
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        $finalCertificateId = $certificateIdBaru;
        
        \Log::info('📋 Final Certificate ID:', [
            'certificate_id' => $finalCertificateId,
            'certificate_id_updated' => $certificateIdUpdated
        ]);

        // ==================================================================
        // 1. KELOLA ALAT STANDAR DENGAN DETAIL UKURAN - TANPA FORMAT
        // ==================================================================
        $alatStandarItems = [];
        $alatStandarArray = $request->alat_standar ?? [];
        
        foreach ($alatStandarArray as $alat) {
            switch ($alat) {
                case 'Mesin ULM 01-600D':
                    $alatStandarItems[] = $alat;
                    break;
                    
                case 'Gauge Block':
                    $gaugeBlockValue = $request->gauge_block_value;
                    if (!empty($gaugeBlockValue) && $gaugeBlockValue !== '') {
                        $alatStandarItems[] = $alat . ' ' . $gaugeBlockValue . ' mm';
                    } else {
                        $alatStandarItems[] = $alat;
                    }
                    break;
                    
                case 'Ring Gauge':
                    $ringGaugeSelect = $request->ring_gauge_select;
                    $ringGaugeManual = $request->ring_gauge_manual;
                    
                    if (!empty($ringGaugeSelect) && $ringGaugeSelect !== '') {
                        if ($ringGaugeSelect == 'lainnya') {
                            if (!empty(trim($ringGaugeManual ?? ''))) {
                                $alatStandarItems[] = $alat . ' ' . trim($ringGaugeManual) . ' mm';
                            } else {
                                $alatStandarItems[] = $alat;
                            }
                        } else {
                            $alatStandarItems[] = $alat . ' ' . $ringGaugeSelect . ' mm';
                        }
                    } elseif (!empty(trim($ringGaugeManual ?? ''))) {
                        $alatStandarItems[] = $alat . ' ' . trim($ringGaugeManual) . ' mm';
                    } else {
                        $alatStandarItems[] = $alat;
                    }
                    break;
                    
                default:
                    $alatStandarItems[] = $alat;
            }
        }
        
        $alatStandarString = !empty($alatStandarItems) ? implode(', ', $alatStandarItems) : '';

        // ==================================================================
        // 2. SENSOR TYPE HANDLING - TANPA FORMAT
        // ==================================================================
        $sensorType = $request->sensor_type ?? null;
        $sensor = null;
        
        switch ($sensorType) {
            case 'T-Probe':
                $sensorValue = $request->t_probe_value;
                $sensor = 'T-Probe: ' . $sensorValue;
                break;
            case 'Hanging Wire':
                $sensorValue = $request->hanging_wire_value;
                $sensor = 'Hanging Wire: ' . $sensorValue;
                break;
            case 'Wire (Holder)':
                $sensorValue = $request->wire_holder_value;
                $sensor = 'Wire (Holder): ' . $sensorValue;
                break;
            case 'Ball':
                $sensorValue = $request->ball_value;
                $sensor = 'Ball: ' . $sensorValue;
                break;
            default:
                $sensor = null;
        }

        // ==================================================================
        // 3. HANDLE SUDUT ULIR - TANPA FORMAT
        // ==================================================================
        $sudutUlir = null;
        $sudutUlirType = $request->sudut_ulir ?? null;
        
        if ($sudutUlirType) {
            if ($sudutUlirType == 'Ulir Metrik : 60°') {
                $sudutUlir = 'Ulir Metrik : 60°';
            } elseif ($sudutUlirType == 'Ulir Non Metrik : 55°') {
                $sudutUlir = 'Ulir Non Metrik : 55°';
            } elseif ($sudutUlirType == 'lainnya') {
                $sudutLainnyaValue = $request->sudut_lainnya_value;
                if (!empty(trim($sudutLainnyaValue ?? ''))) {
                    $sudutUlir = trim($sudutLainnyaValue) . '°';
                } else {
                    $sudutUlir = null;
                }
            }
        }

        // ==================================================================
        // 4. UPDATE HEAD THREAD GAUGE
        // ==================================================================
        $head = HeadThreadGauge::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-64',
            'catatan' => $request->catatan,
            'jenis_thread' => $request->jenis_thread,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $headData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $finalCertificateId]);
        }
        
        if ($head) {
            $head->update($headData);
            $head->refresh();
            \Log::info('✅ Head Thread Gauge updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadThreadGauge::create($headData);
            \Log::info('✅ Head Thread Gauge created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }

        // ==================================================================
        // 5. UPDATE DETAIL THREAD GAUGE - TANPA FORMAT
        // ==================================================================
        DetailThreadGauge::where('calibration_id', $calibration->id)->delete();
        
        $detailData = [
            'calibration_id' => $calibration->id,
            
            // Sensor
            'sensor' => $sensor,
            
            // GO Data - LANGSUNG TANPA FORMAT
            'kodeGO' => $request->kodeGO,
            'satuan_go' => $request->satuan_go,
            'nominalGO' => $request->nominalGO,
            'GOatasX1' => $request->GOatasX1,
            'GOatasY1' => $request->GOatasY1,
            'GObawahX1' => $request->GObawahX1,
            'GObawahY1' => $request->GObawahY1,
            
            // NOT GO Data - LANGSUNG TANPA FORMAT
            'kodeNOTGO' => $request->kodeNOTGO,
            'satuan_not_go' => $request->satuan_not_go,
            'nominalNOTGO' => $request->nominalNOTGO,
            'NOTGOatasX1' => $request->NOTGOatasX1,
            'NOTGOatasY1' => $request->NOTGOatasY1,
            'NOTGObawahX1' => $request->NOTGObawahX1,
            'NOTGObawahY1' => $request->NOTGObawahY1,
            
            // Pitch dan Sudut Ulir - LANGSUNG TANPA FORMAT
            'ukuranPitch' => $request->ukuranPitch,
            'satuan_pitch' => $request->satuan_pitch,
            'sudutUlir' => $sudutUlir,
        ];
        
        // Filter data yang null
        $detailData = array_filter($detailData, function($value) {
            return $value !== null && $value !== '';
        });
        
        if (!empty($detailData)) {
            DetailThreadGauge::create($detailData);
            \Log::info('✅ Detail Thread Gauge created');
        }

        // ==================================================================
        // 6. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $finalCertificateId]);
        }
        
        if ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibratedBy]);
        } elseif ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verifiedBy]);
        } elseif ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 7. FINAL VERIFICATION
        // ==================================================================
        $calibration->refresh();
        $head->refresh();
        
        \Log::info('🏁 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'certificate_id_di_head' => $head->certificate_id,
            'certificate_id_di_calibration' => $calibration->certificate_id,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);

        \Log::info('🎉 updateThreadGauge COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateThreadGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Thread Gauge: " . $e->getMessage());
    }
}
// Helper function untuk parsing decimal
private function parseDecimal($value)
{
    if (empty($value) || trim($value) === '') {
        return null;
    }
    
    // Hapus karakter non-numerik kecuali titik dan minus
    $value = preg_replace('/[^0-9\.\-]/', '', $value);
    
    if ($value === '' || $value === null) {
        return null;
    }
    
    return (float) $value;
}


private function storeStopwatch($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('⏱️ ===== START storeStopwatch =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeStopwatch called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI INPUT FORM (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $alatStandar = [];
        
        // Cari alat standar dari checkbox dengan berbagai format
        $alatStandarArray = $this->getRequestValue($request, 'alat_standar', $tabId);
        if (is_array($alatStandarArray)) {
            foreach ($alatStandarArray as $value) {
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        } elseif ($alatStandarArray) {
            $alatStandar[] = $alatStandarArray;
        }
        
        // Coba juga dengan format alat_standar_1, alat_standar_2, dll
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar stopwatch:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. AMBIL CATATAN (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $catatan = $this->getRequestValue($request, 'catatan', $tabId);
        
        // ==================================================================
        // 3. SIMPAN KE HEAD STOPWATCH
        // ==================================================================
        $head = HeadStopwatch::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-45',
            'catatan' => $catatan,
            'form_index' => 1,
            'satuan_titik_ukur' => $request->satuan_titik_ukur,
        ]);
        
        \Log::info('✅ Head Stopwatch saved:', ['head_id' => $head->id]);
        
        // ==================================================================
        // 4. SIMPAN DETAIL MEASUREMENTS - 10 TITIK UKUR (DENGAN DUKUNGAN _tab)
        // ==================================================================
        \Log::info('📊 Saving stopwatch measurements...');
        $detailCount = 0;
        
        for ($row = 1; $row <= 10; $row++) {
            // Ambil titik ukur
            $titikUkur = $this->getRequestValue($request, "titik_ukur_{$row}", $tabId);
            if (!$titikUkur) {
                $titikUkur = $this->getRequestValue($request, "titik_ukur", $tabId);
                if (is_array($titikUkur)) {
                    $titikUkur = $titikUkur[$row - 1] ?? null;
                }
            }
            
            // Cek apakah ada data untuk titik ukur ini
            $hasData = !empty($titikUkur);
            
            // Persiapkan data detail
            $detailData = [
                'calibration_id' => $calibration->id,
                'head_stopwatch_id' => $head->id,
                'form_index' => 1,
                'titikUkur' => $titikUkur,
            ];
            
            // Mapping data STANDAR untuk 5 pengulangan
            for ($col = 1; $col <= 5; $col++) {
                $menit = $this->getRequestValue($request, "standar_{$row}_p{$col}_menit", $tabId);
                if (!$menit) {
                    $menit = $this->getRequestValue($request, "standar", $tabId);
                    if (is_array($menit)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $menit = $menit[$index]['menit'] ?? null;
                    }
                }
                
                $second = $this->getRequestValue($request, "standar_{$row}_p{$col}_second", $tabId);
                if (!$second) {
                    $second = $this->getRequestValue($request, "standar", $tabId);
                    if (is_array($second)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $second = $second[$index]['second'] ?? null;
                    }
                }
                
                $milisecond = $this->getRequestValue($request, "standar_{$row}_p{$col}_milisecond", $tabId);
                if (!$milisecond) {
                    $milisecond = $this->getRequestValue($request, "standar", $tabId);
                    if (is_array($milisecond)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $milisecond = $milisecond[$index]['milisecond'] ?? null;
                    }
                }
                
                $detailData["STDm{$col}"] = $menit;
                $detailData["STDs{$col}"] = $second;
                $detailData["STDms{$col}"] = $milisecond;
                
                if (!empty($menit) || !empty($second) || !empty($milisecond)) {
                    $hasData = true;
                }
            }
            
            // Mapping data ALAT (UUT) untuk 5 pengulangan
            for ($col = 1; $col <= 5; $col++) {
                $menit = $this->getRequestValue($request, "alat_{$row}_p{$col}_menit", $tabId);
                if (!$menit) {
                    $menit = $this->getRequestValue($request, "alat", $tabId);
                    if (is_array($menit)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $menit = $menit[$index]['menit'] ?? null;
                    }
                }
                
                $second = $this->getRequestValue($request, "alat_{$row}_p{$col}_second", $tabId);
                if (!$second) {
                    $second = $this->getRequestValue($request, "alat", $tabId);
                    if (is_array($second)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $second = $second[$index]['second'] ?? null;
                    }
                }
                
                $milisecond = $this->getRequestValue($request, "alat_{$row}_p{$col}_milisecond", $tabId);
                if (!$milisecond) {
                    $milisecond = $this->getRequestValue($request, "alat", $tabId);
                    if (is_array($milisecond)) {
                        $index = ($row - 1) * 5 + ($col - 1);
                        $milisecond = $milisecond[$index]['milisecond'] ?? null;
                    }
                }
                
                $detailData["UUTm{$col}"] = $menit;
                $detailData["UUTs{$col}"] = $second;
                $detailData["UUTms{$col}"] = $milisecond;
                
                if (!empty($menit) || !empty($second) || !empty($milisecond)) {
                    $hasData = true;
                }
            }
            
            if ($hasData) {
                \Log::debug("📝 Saving stopwatch detail row {$row}:", [
                    'titik_ukur' => $detailData['titikUkur'],
                    'std_p1_menit' => $detailData['STDm1'] ?? null,
                    'uut_p1_menit' => $detailData['UUTm1'] ?? null
                ]);
                
                DetailStopwatch::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} stopwatch detail measurements");
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA TTD (DENGAN DUKUNGAN _tab)
        // ==================================================================
        $updateData = [];
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('👤 Calibrated by saved:', ['name' => $calibratedBy]);
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('👤 Verified by saved:', ['name' => $verifiedBy]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with signature data');
        }
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (Stopwatch):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $detailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
        ]);
        
        \Log::info('🎉 storeStopwatch COMPLETED');
        return $head;
        
    } catch (\Exception $e) {
        \Log::error('💥 Error storing Stopwatch data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}


private function updateStopwatch($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateStopwatch');
        \Log::info('📝 Updating Stopwatch data for calibration ID: ' . $calibration->id);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = $calibration->headStopwatch;
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar stopwatch:', ['alat_standar' => $alatStandarString]);
        
        // ==================================================================
        // 2. UPDATE ATAU CREATE HEAD STOPWATCH
        // ==================================================================
        $head = HeadStopwatch::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-45',
            'catatan' => $request->catatan,
            'satuan_titik_ukur' => $request->satuan_titik_ukur,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $certificateIdBaru]);
        }
        
        if ($head) {
            $head->update($headData);
            \Log::info('✅ Head Stopwatch updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadStopwatch::create($headData);
            \Log::info('➕ Head Stopwatch created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }
        
        // ==================================================================
        // 3. UPDATE DETAIL STOPWATCH - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating stopwatch measurements...');
        
        // Hapus data lama terlebih dahulu
        $deletedDetails = DetailStopwatch::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old detail records");
        
        $detailCount = 0;
        
        // Proses 10 titik ukur - LANGSUNG TANPA FORMAT
        for ($i = 1; $i <= 10; $i++) {
            // Cek apakah ada data untuk titik ukur ini
            $hasData = false;
            
            // Cek data STANDAR untuk titik ukur ini
            for ($p = 1; $p <= 5; $p++) {
                if ($request->has("standar_{$i}_p{$p}_menit") && !empty(trim($request->input("standar_{$i}_p{$p}_menit")))) {
                    $hasData = true;
                    break;
                }
                if ($request->has("standar_{$i}_p{$p}_second") && !empty(trim($request->input("standar_{$i}_p{$p}_second")))) {
                    $hasData = true;
                    break;
                }
                if ($request->has("standar_{$i}_p{$p}_milisecond") && !empty(trim($request->input("standar_{$i}_p{$p}_milisecond")))) {
                    $hasData = true;
                    break;
                }
            }
            
            // Cek data ALAT (UUT) untuk titik ukur ini
            if (!$hasData) {
                for ($p = 1; $p <= 5; $p++) {
                    if ($request->has("alat_{$i}_p{$p}_menit") && !empty(trim($request->input("alat_{$i}_p{$p}_menit")))) {
                        $hasData = true;
                        break;
                    }
                    if ($request->has("alat_{$i}_p{$p}_second") && !empty(trim($request->input("alat_{$i}_p{$p}_second")))) {
                        $hasData = true;
                        break;
                    }
                    if ($request->has("alat_{$i}_p{$p}_milisecond") && !empty(trim($request->input("alat_{$i}_p{$p}_milisecond")))) {
                        $hasData = true;
                        break;
                    }
                }
            }
            
            // Simpan jika ada titik ukur atau data pengukuran
            $titikUkur = $request->input("titik_ukur_{$i}");
            if ((!empty($titikUkur)) || $hasData) {
                
                // Persiapkan data detail - LANGSUNG TANPA FORMAT
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_stopwatch_id' => $head->id,
                    'titikUkur' => $titikUkur,
                ];
                
                // Mapping data STANDAR untuk 5 pengulangan - LANGSUNG TANPA FORMAT
                $detailData["STDm1"] = $request->input("standar_{$i}_p1_menit");
                $detailData["STDs1"] = $request->input("standar_{$i}_p1_second");
                $detailData["STDms1"] = $request->input("standar_{$i}_p1_milisecond");
                
                $detailData["STDm2"] = $request->input("standar_{$i}_p2_menit");
                $detailData["STDs2"] = $request->input("standar_{$i}_p2_second");
                $detailData["STDms2"] = $request->input("standar_{$i}_p2_milisecond");
                
                $detailData["STDm3"] = $request->input("standar_{$i}_p3_menit");
                $detailData["STDs3"] = $request->input("standar_{$i}_p3_second");
                $detailData["STDms3"] = $request->input("standar_{$i}_p3_milisecond");
                
                $detailData["STDm4"] = $request->input("standar_{$i}_p4_menit");
                $detailData["STDs4"] = $request->input("standar_{$i}_p4_second");
                $detailData["STDms4"] = $request->input("standar_{$i}_p4_milisecond");
                
                $detailData["STDm5"] = $request->input("standar_{$i}_p5_menit");
                $detailData["STDs5"] = $request->input("standar_{$i}_p5_second");
                $detailData["STDms5"] = $request->input("standar_{$i}_p5_milisecond");
                
                // Mapping data ALAT (UUT) untuk 5 pengulangan - LANGSUNG TANPA FORMAT
                $detailData["UUTm1"] = $request->input("alat_{$i}_p1_menit");
                $detailData["UUTs1"] = $request->input("alat_{$i}_p1_second");
                $detailData["UUTms1"] = $request->input("alat_{$i}_p1_milisecond");
                
                $detailData["UUTm2"] = $request->input("alat_{$i}_p2_menit");
                $detailData["UUTs2"] = $request->input("alat_{$i}_p2_second");
                $detailData["UUTms2"] = $request->input("alat_{$i}_p2_milisecond");
                
                $detailData["UUTm3"] = $request->input("alat_{$i}_p3_menit");
                $detailData["UUTs3"] = $request->input("alat_{$i}_p3_second");
                $detailData["UUTms3"] = $request->input("alat_{$i}_p3_milisecond");
                
                $detailData["UUTm4"] = $request->input("alat_{$i}_p4_menit");
                $detailData["UUTs4"] = $request->input("alat_{$i}_p4_second");
                $detailData["UUTms4"] = $request->input("alat_{$i}_p4_milisecond");
                
                $detailData["UUTm5"] = $request->input("alat_{$i}_p5_menit");
                $detailData["UUTs5"] = $request->input("alat_{$i}_p5_second");
                $detailData["UUTms5"] = $request->input("alat_{$i}_p5_milisecond");

                \Log::debug("📝 Saving stopwatch detail row {$i}:", [
                    'titik_ukur' => $detailData['titikUkur']
                ]);
                
                DetailStopwatch::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Saved {$detailCount} stopwatch detail measurements");
        
        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $certificateIdBaru]);
        }
        
        // Nama untuk TTD Dikalibrasi
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
        } elseif ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
        }
        
        // Nama untuk TTD Diperiksa
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
        } elseif ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
        }
        
        // Data uncertainty dan conclusion
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }
        
        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $headBaru = $calibration->headStopwatch;
        $savedDetailCount = DetailStopwatch::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Stopwatch):', [
            'calibration_id' => $calibration->id,
            'head_id' => $headBaru->id ?? null,
            'certificate_id_di_head' => $headBaru->certificate_id ?? null,
            'certificate_id_di_calibration' => $calibration->certificate_id ?? null,
            'detail_records' => $savedDetailCount,
            'alat_standar' => $alatStandarString,
            'catatan' => $request->catatan,
            'nama_alat' => $calibration->namaAlat,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);
        
        \Log::info('🎉 updateStopwatch COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateStopwatch:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Stopwatch: " . $e->getMessage());
    }
}

private function storeCentrifuge($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1, $tabId = null)
{
    \Log::info('🚀 ===== START storeCentrifuge =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm,
        'tab_id' => $tabId
    ]);
    
    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm,
            'tab_id' => $tabId
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI
        // ==================================================================
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request, $tabId) {
            $possibleKeys = [];
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tabId}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tabId}";
                
                $possibleKeys[] = $baseKey;
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tabId}";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        $filtered = array_filter($value);
                        if (!empty($filtered)) {
                            \Log::debug("Found array value for key: {$key}", ['value' => $filtered]);
                            return $filtered;
                        }
                    } else {
                        \Log::debug("Found value for key: {$key} = {$value}");
                        return [$value];
                    }
                }
            }
            
            return [];
        };
        
        /**
         * Mencari nilai tunggal dengan berbagai format
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request, $tabId) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tabId}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tabId}";
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        // ==================================================================
        // 3. AMBIL ALAT STANDAR DARI FORM 1
        // ==================================================================
        $alatStandar = [];
        
        // Coba dari form_1_alat_standar[]
        $form1AlatStandar = $request->input('form_1_alat_standar', []);
        if (is_array($form1AlatStandar) && !empty($form1AlatStandar)) {
            $alatStandar = array_filter($form1AlatStandar);
        }
        
        // Jika kosong, coba dari alat_standar[]
        if (empty($alatStandar)) {
            $alatStandarFromRequest = $request->input('alat_standar', []);
            if (is_array($alatStandarFromRequest) && !empty($alatStandarFromRequest)) {
                $alatStandar = array_filter($alatStandarFromRequest);
            }
        }
        
        // Jika masih kosong, coba dari findArrayValue
        if (empty($alatStandar)) {
            $alatStandar = $findArrayValue('alat_standar', 1);
        }
        
        // Konversi ke string dengan newline
        $standardValue = !empty($alatStandar) ? implode("\n", $alatStandar) : '';
        
        \Log::info('📋 Alat Standar:', [
            'alat_standar_array' => $alatStandar,
            'standard_value' => $standardValue
        ]);
        
        // ==================================================================
        // 4. LOOP UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex} - Centrifuge");
            \Log::info("=========================================");
            
            // ==========================================================
            // SIMPAN HEAD CENTRIFUGE
            // ==========================================================
            HeadCentrifuge::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-52',
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
            \Log::info("✅ HeadCentrifuge saved for form {$formIndex}");
            
            // ==========================================================
            // HAPUS DATA DETAIL LAMA UNTUK FORM INI
            // ==========================================================
            DetailCentrifuge::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->delete();
            
            // ==========================================================
            // SIMPAN DETAILS UNTUK CENTRIFUGE (12 BARIS)
            // ==========================================================
            $detailCount = 0;
            
            for ($row = 1; $row <= 12; $row++) {
                // Cari nilai setpoint (nominal RPM)
                $setpoint = $findValue("setpoint", $formIndex, [$row]);
                if (empty($setpoint)) {
                    $setpoint = $findValue("nominalRPM", $formIndex, [$row]);
                }
                if (empty($setpoint)) {
                    $setpoint = $findValue("nominal_rpm", $formIndex, [$row]);
                }
                if (empty($setpoint)) {
                    $setpoint = $findValue("rpm", $formIndex, [$row]);
                }
                
                // Cari 5 nilai STD
                $stdValues = [];
                for ($col = 1; $col <= 5; $col++) {
                    $value = $findValue("std", $formIndex, [$row, $col]);
                    if (empty($value)) {
                        $value = $findValue("STD", $formIndex, [$row, $col]);
                    }
                    if (empty($value)) {
                        $value = $findValue("pembacaan", $formIndex, [$row, $col]);
                    }
                    $stdValues[] = $value;
                }
                
                // Cari resolusi alat
                $resolusi = $findValue("resolusi", $formIndex, [$row]);
                if (empty($resolusi)) {
                    $resolusi = $findValue("resolusi_alat", $formIndex, [$row]);
                }
                if (empty($resolusi)) {
                    $resolusi = $findValue("resolution", $formIndex, [$row]);
                }
                
                $hasSetpoint = !empty(trim($setpoint ?? ''));
                $hasAnyStd = !empty($stdValues[0]) || !empty($stdValues[1]) || 
                            !empty($stdValues[2]) || !empty($stdValues[3]) || 
                            !empty($stdValues[4]);
                $hasResolusi = !empty(trim($resolusi ?? ''));
                
                if ($hasSetpoint || $hasAnyStd || $hasResolusi) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'nominalRPM' => $setpoint,
                        'STD1' => !empty($stdValues[0]) ? $stdValues[0] : null,
                        'STD2' => !empty($stdValues[1]) ? $stdValues[1] : null,
                        'STD3' => !empty($stdValues[2]) ? $stdValues[2] : null,
                        'STD4' => !empty($stdValues[3]) ? $stdValues[3] : null,
                        'STD5' => !empty($stdValues[4]) ? $stdValues[4] : null,
                        'resolusi' => $resolusi,
                    ];
                    
                    // 🔥 GUNAKAN CREATE BUKAN UPDATE OR CREATE
                    DetailCentrifuge::create($detailData);
                    $detailCount++;
                    \Log::debug("Detail saved for form {$formIndex}, row {$row}", ['setpoint' => $setpoint]);
                }
            }
            
            \Log::info("✅ Saved {$detailCount} details for form {$formIndex}");
        }
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN JUMLAH FORM DAN SIGNATURE
        // ==================================================================
        $updateData = ['jumlah_form' => $jumlahForm];
        
        // Ambil signature dari form 1 dengan dukungan tab
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
        }
        
        $calibration->update($updateData);
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $totalHeadRecords = HeadCentrifuge::where('calibration_id', $calibration->id)->count();
        $totalDetailRecords = DetailCentrifuge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Centrifuge):', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
            'head_records' => $totalHeadRecords,
            'detail_records' => $totalDetailRecords,
            'certificate_id' => $newCertificateId ?? $calibration->certificate_id,
            'alat_standar' => $standardValue,
            'tab_id' => $tabId
        ]);
        
        \Log::info('🎉 storeCentrifuge COMPLETED');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeCentrifuge FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback
        try {
            DetailCentrifuge::where('calibration_id', $calibration->id)->delete();
            HeadCentrifuge::where('calibration_id', $calibration->id)->delete();
        } catch (\Exception $rollbackError) {
            \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
        }
        
        throw $e;
    }
}

private function updateCentrifuge($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateCentrifuge =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong atau MANUAL_INPUT):', [
                'certificate_id_lama' => $calibration->certificate_id,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        }
        
        // Update certificate_id di tabel calibration
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
            
            \Log::info('📝 UPDATE CERTIFICATE ID DI CALIBRATION:', [
                'certificate_id_baru' => $certificateIdBaru,
                'current_certificate_id' => $calibration->certificate_id
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Centrifuge - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadCentrifuge::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            $headData = [];
            
            // Alat standar untuk form 1
            if ($formIndex == 1) {
                // 🔥 AMBIL ALAT STANDAR DARI REQUEST
                $alatStandar = [];
                
                // Coba dari alat_standar[] (checkbox)
                $alatStandarFromRequest = $request->input('alat_standar', []);
                if (is_array($alatStandarFromRequest) && !empty($alatStandarFromRequest)) {
                    $alatStandar = array_filter($alatStandarFromRequest);
                }
                
                // Jika kosong, coba dari form_1_alat_standar[]
                if (empty($alatStandar)) {
                    $form1AlatStandar = $request->input('form_1_alat_standar', []);
                    if (is_array($form1AlatStandar) && !empty($form1AlatStandar)) {
                        $alatStandar = array_filter($form1AlatStandar);
                    }
                }
                
                // Jika masih kosong, coba dari form_1_alat_standar_1[]
                if (empty($alatStandar)) {
                    $form1AlatStandar1 = $request->input('form_1_alat_standar_1', []);
                    if (is_array($form1AlatStandar1) && !empty($form1AlatStandar1)) {
                        $alatStandar = array_filter($form1AlatStandar1);
                    }
                }
                
                // Simpan sebagai string dengan newline
                $headData['standard'] = !empty($alatStandar) ? implode("\n", $alatStandar) : '';
                
                \Log::info('📋 Alat Standar (Update):', [
                    'alat_standar' => $alatStandar,
                    'standard_value' => $headData['standard']
                ]);
            }
            
            // 🔥 UPDATE CERTIFICATE ID UNTUK SEMUA HEAD (FORM 1-4) 🔥
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'certificate_id' => $head->certificate_id ?? 'not_set'
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['calibrationMethod'] = 'PAS-IK1102-52';
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                $head = HeadCentrifuge::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadCentrifuge::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS
        // ==================================================================
        DetailCentrifuge::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            $nominalArray = $request->input("nominal_{$formIndex}", []);
            $std1Array = $request->input("std1_{$formIndex}", []);
            $std2Array = $request->input("std2_{$formIndex}", []);
            $std3Array = $request->input("std3_{$formIndex}", []);
            $std4Array = $request->input("std4_{$formIndex}", []);
            $std5Array = $request->input("std5_{$formIndex}", []);
            $resolusiArray = $request->input("resolusi_alat_{$formIndex}", []);
            
            for ($i = 0; $i < 12; $i++) {
                $nominal = $nominalArray[$i] ?? '';
                $std1 = $std1Array[$i] ?? '';
                $std2 = $std2Array[$i] ?? '';
                $std3 = $std3Array[$i] ?? '';
                $std4 = $std4Array[$i] ?? '';
                $std5 = $std5Array[$i] ?? '';
                $resolusi = $resolusiArray[$i] ?? '';
                
                $hasData = !empty(trim($nominal)) || 
                          !empty(trim($std1)) || 
                          !empty(trim($std2)) || 
                          !empty(trim($std3)) || 
                          !empty(trim($std4)) || 
                          !empty(trim($std5)) ||
                          !empty(trim($resolusi));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'nominalRPM' => $nominal,
                        'STD1' => !empty($std1) ? $std1 : null,
                        'STD2' => !empty($std2) ? $std2 : null,
                        'STD3' => !empty($std3) ? $std3 : null,
                        'STD4' => !empty($std4) ? $std4 : null,
                        'STD5' => !empty($std5) ? $std5 : null,
                        'resolusi' => !empty($resolusi) ? $resolusi : null,
                    ];
                    
                    DetailCentrifuge::create($detailData);
                    $totalDetailCount++;
                }
            }
        }
        
        // ==================================================================
        // 3. UPDATE CALIBRATION DENGAN DATA TAMBAHAN
        // ==================================================================
        $updateData = [];
        
        // Data TTD dari form 1 (calibratedBy dan verifiedBy)
        if ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibratedBy]);
        } else {
            $updateData['calibrated_by'] = '-';
        }
        
        if ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verifiedBy]);
        } else {
            $updateData['verified_by'] = '-';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with signature data:', $updateData);
        }
        
        // Update jumlah_form di calibration
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // Refresh untuk memastikan data terbaru
        $calibration->refresh();
        
        \Log::info('🎉 updateCentrifuge completed successfully', [
            'calibration_id' => $calibration->id,
            'details_created' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateCentrifuge FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
        ]);
        throw $e;
    }
}

private function storeUtm($request, $calibration, $newCertificateId = null, $isMultipleSubmit = false, $jumlahForm = 1)
{
    \Log::info('🚀 ===== START storeUtm =====', [
        'calibration_id' => $calibration->id,
        'is_multiple_submit' => $isMultipleSubmit,
        'jumlah_form' => $jumlahForm
    ]);
    
    try {
        // ==================================================================
        // 1. KONFIGURASI MULTIPLE FORM
        // ==================================================================
        if (!$isMultipleSubmit) {
            $isMultipleSubmit = $request->has('submit_all') && $request->submit_all == 'true';
        }
        if ($jumlahForm <= 1) {
            $jumlahForm = (int) ($request->jumlah_form ?? 1);
        }
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 Form configuration:', [
            'is_multiple_submit' => $isMultipleSubmit,
            'jumlah_form' => $jumlahForm
        ]);
        
        // ==================================================================
        // 2. FUNGSI BANTU UNTUK MENCARI NILAI (LOOPING SEMUA KEMUNGKINAN TAB)
        // ==================================================================
        
        /**
         * Mencari nilai dari request dengan berbagai kemungkinan format key (termasuk tab)
         */
        $findValue = function($baseKey, $formIndex, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            $suffix = !empty($additionalParams) ? '_' . implode('_', $additionalParams) : '';
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                // Format dengan double formIndex dan tab
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}{$suffix}_tab{$tab}";
                
                // Format tanpa tab suffix
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}{$suffix}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}{$suffix}";
                $possibleKeys[] = "{$baseKey}{$suffix}";
            }
            
            // Hapus duplikasi
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key} = {$value}");
                    return $value;
                }
            }
            
            return null;
        };
        
        /**
         * Mencari nilai array (alat_standar) dengan berbagai format (termasuk tab)
         */
        $findArrayValue = function($baseKey, $formIndex) use ($request) {
            $possibleKeys = [];
            
            // Loop untuk tab 1-10
            for ($tab = 1; $tab <= 10; $tab++) {
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}_tab{$tab}";
                $possibleKeys[] = "{$baseKey}_tab{$tab}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}_{$formIndex}";
                $possibleKeys[] = "form_{$formIndex}_{$baseKey}";
                $possibleKeys[] = "{$baseKey}_{$formIndex}";
                $possibleKeys[] = $baseKey;
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value);
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        // ==================================================================
        // 3. LOOP UNTUK SETIAP FORM
        // ==================================================================
        $headsUpdated = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("=========================================");
            \Log::info("📝 PROCESSING FORM {$formIndex}");
            \Log::info("=========================================");
            
            // 🔥 AMBIL DATA DARI REQUEST (PER FORM)
            $satuanTitikTekan = $findValue('satuan_titik_tekan', $formIndex, []);
            $satuanTekanStandar = $findValue('satuan_tekan_standar', $formIndex, []);
            $satuanTekanUut = $findValue('satuan_tekan_uut', $formIndex, []);
            $satuanTitikTarik = $findValue('satuan_titik_tarik', $formIndex, []);
            $satuanTarikStandar = $findValue('satuan_tarik_standar', $formIndex, []);
            $satuanTarikUut = $findValue('satuan_tarik_uut', $formIndex, []);
            
            // 🔥 AMBIL ALAT STANDAR PER FORM (MASING-MASING FORM PUNYA SENDIRI)
            $alatStandar = $findArrayValue('alat_standar', $formIndex);
            
            // Jika masih kosong dan ini form 1, coba dari alat_standar biasa (backward compatibility)
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
                if (!is_array($alatStandar)) {
                    $alatStandar = [$alatStandar];
                }
            }
            
            // Pastikan dalam bentuk array
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            // Filter nilai kosong
            $alatStandar = array_filter($alatStandar);
            
            // Simpan ke database
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            \Log::info("📝 Head data untuk form {$formIndex}:", [
                'satuan_titik_tekan' => $satuanTitikTekan,
                'satuan_tekan_standar' => $satuanTekanStandar,
                'satuan_tekan_uut' => $satuanTekanUut,
                'satuan_titik_tarik' => $satuanTitikTarik,
                'satuan_tarik_standar' => $satuanTarikStandar,
                'satuan_tarik_uut' => $satuanTarikUut,
                'standard' => $standardValue,
            ]);
            
            // ==========================================================
            // SIMPAN HEAD UTM (DENGAN FIELD PER FORM)
            // ==========================================================
            HeadUtm::updateOrCreate(
                ['calibration_id' => $calibration->id, 'form_index' => $formIndex],
                [
                    'standard' => $standardValue,
                    'calibrationMethod' => 'PAS-IK1102-54',
                    'satuan_titik_ukur_tekan' => $satuanTitikTekan,
                    'satuan_read_tekan_std' => $satuanTekanStandar,
                    'satuan_read_tekan_uut' => $satuanTekanUut,
                    'satuan_titik_ukur_tarik' => $satuanTitikTarik,
                    'satuan_read_tarik_std' => $satuanTarikStandar,
                    'satuan_read_tarik_uut' => $satuanTarikUut,
                    'certificate_id' => $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time(),
                ]
            );
            $headsUpdated++;
            
            // ==========================================================
            // SIMPAN DETAIL MEASUREMENTS UNTUK TEKAN (10 BARIS)
            // ==========================================================
            $detailCountTekan = 0;
            
            for ($i = 1; $i <= 10; $i++) {
                // Cari nilai titik ukur tekan
                $titikUkur = $findValue('titik_ukur_tekan', $formIndex, [$i]);
                
                // Cari semua pembacaan
                $std1 = $findValue('tekan_standar', $formIndex, [$i, '0', '1']);
                $std2 = $findValue('tekan_standar', $formIndex, [$i, '120', '2']);
                $std3 = $findValue('tekan_standar', $formIndex, [$i, '240', '3']);
                $uut1 = $findValue('tekan_uut', $formIndex, [$i, '0', '1']);
                $uut2 = $findValue('tekan_uut', $formIndex, [$i, '120', '2']);
                $uut3 = $findValue('tekan_uut', $formIndex, [$i, '240', '3']);
                
                // Cek jika ada data
                $hasData = !empty(trim($titikUkur ?? '')) || 
                           !empty(trim($std1 ?? '')) || 
                           !empty(trim($std2 ?? '')) || 
                           !empty(trim($std3 ?? '')) || 
                           !empty(trim($uut1 ?? '')) || 
                           !empty(trim($uut2 ?? '')) || 
                           !empty(trim($uut3 ?? ''));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'readTekanSTD1' => $std1,
                        'readTekanSTD2' => $std2,
                        'readTekanSTD3' => $std3,
                        'readTekanUUT1' => $uut1,
                        'readTekanUUT2' => $uut2,
                        'readTekanUUT3' => $uut3,
                        'readTarikSTD1' => null,
                        'readTarikSTD2' => null,
                        'readTarikSTD3' => null,
                        'readTarikUUT1' => null,
                        'readTarikUUT2' => null,
                        'readTarikUUT3' => null,
                    ];

                    DetailUtm::create($detailData);
                    $detailCountTekan++;
                }
            }
            
            \Log::info("✅ Saved {$detailCountTekan} TEKAN detail measurements for form {$formIndex}");
            
            // ==========================================================
            // SIMPAN DETAIL MEASUREMENTS UNTUK TARIK (10 BARIS)
            // ==========================================================
            $detailCountTarik = 0;
            
            for ($i = 1; $i <= 10; $i++) {
                // Cari nilai titik ukur tarik
                $titikUkur = $findValue('titik_ukur_tarik', $formIndex, [$i]);
                
                // Cari semua pembacaan
                $std1 = $findValue('tarik_standar', $formIndex, [$i, '0', '1']);
                $std2 = $findValue('tarik_standar', $formIndex, [$i, '120', '2']);
                $std3 = $findValue('tarik_standar', $formIndex, [$i, '240', '3']);
                $uut1 = $findValue('tarik_uut', $formIndex, [$i, '0', '1']);
                $uut2 = $findValue('tarik_uut', $formIndex, [$i, '120', '2']);
                $uut3 = $findValue('tarik_uut', $formIndex, [$i, '240', '3']);
                
                // Cek jika ada data
                $hasData = !empty(trim($titikUkur ?? '')) || 
                           !empty(trim($std1 ?? '')) || 
                           !empty(trim($std2 ?? '')) || 
                           !empty(trim($std3 ?? '')) || 
                           !empty(trim($uut1 ?? '')) || 
                           !empty(trim($uut2 ?? '')) || 
                           !empty(trim($uut3 ?? ''));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'readTekanSTD1' => null,
                        'readTekanSTD2' => null,
                        'readTekanSTD3' => null,
                        'readTekanUUT1' => null,
                        'readTekanUUT2' => null,
                        'readTekanUUT3' => null,
                        'readTarikSTD1' => $std1,
                        'readTarikSTD2' => $std2,
                        'readTarikSTD3' => $std3,
                        'readTarikUUT1' => $uut1,
                        'readTarikUUT2' => $uut2,
                        'readTarikUUT3' => $uut3,
                    ];

                    DetailUtm::create($detailData);
                    $detailCountTarik++;
                }
            }
            
            \Log::info("✅ Saved {$detailCountTarik} TARIK detail measurements for form {$formIndex}");
        }
        
        // ==================================================================
        // 4. HAPUS DATA LAMA UNTUK FORM YANG TIDAK ADA
        // ==================================================================
        HeadUtm::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        DetailUtm::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN JUMLAH FORM
        // ==================================================================
        $calibration->update(['jumlah_form' => $jumlahForm]);
        
        // FINAL VERIFICATION
        $allHeads = HeadUtm::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailUtm::where('calibration_id', $calibration->id)->get();
        
        \Log::info("🎯 FINAL SUMMARY:", [
            'total_head_records' => $allHeads->count(),
            'head_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_detail_records' => $allDetails->count(),
            'detail_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'heads_updated' => $headsUpdated
        ]);
        
        \Log::info('✅ storeUtm completed successfully');
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeUtm FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function updateUtm($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateUtm =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
        }
        
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE UTM - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadUtm::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            $satuanTitikTekan = $request->input("satuan_titik_ukur_tekan_{$formIndex}");
            $satuanTekanStandar = $request->input("satuan_read_tekan_std_{$formIndex}");
            $satuanTekanUut = $request->input("satuan_read_tekan_uut_{$formIndex}");
            $satuanTitikTarik = $request->input("satuan_titik_ukur_tarik_{$formIndex}");
            $satuanTarikStandar = $request->input("satuan_read_tarik_std_{$formIndex}");
            $satuanTarikUut = $request->input("satuan_read_tarik_uut_{$formIndex}");
            
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
            }
            
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            $alatStandar = array_filter($alatStandar);
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            $headData = [
                'standard' => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-54',
                'satuan_titik_ukur_tekan' => $satuanTitikTekan,
                'satuan_read_tekan_std' => $satuanTekanStandar,
                'satuan_read_tekan_uut' => $satuanTekanUut,
                'satuan_titik_ukur_tarik' => $satuanTitikTarik,
                'satuan_read_tarik_std' => $satuanTarikStandar,
                'satuan_read_tarik_uut' => $satuanTarikUut,
            ];
            
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}");
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                HeadUtm::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        HeadUtm::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS - AMBIL DARI ARRAY PER FORM
        // ==================================================================
        DetailUtm::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        $detailCountTekan = 0;
        $detailCountTarik = 0;
        
        // ================================================================
        // 🔥 PROSES DATA TEKAN - AMBIL DARI ARRAY "tekan_{formIndex}[]"
        // ================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $tekanData = $request->input("tekan_{$formIndex}", []);
            
            if (!empty($tekanData) && is_array($tekanData)) {
                \Log::info("📊 Processing TEKAN data for form {$formIndex}", ['count' => count($tekanData)]);
                
                foreach ($tekanData as $data) {
                    $titikUkur = $data['titikUkur'] ?? null;
                    $readTekanSTD1 = $data['readTekanSTD1'] ?? null;
                    $readTekanSTD2 = $data['readTekanSTD2'] ?? null;
                    $readTekanSTD3 = $data['readTekanSTD3'] ?? null;
                    $readTekanUUT1 = $data['readTekanUUT1'] ?? null;
                    $readTekanUUT2 = $data['readTekanUUT2'] ?? null;
                    $readTekanUUT3 = $data['readTekanUUT3'] ?? null;
                    
                    $hasData = !empty(trim($titikUkur ?? '')) || 
                               !empty(trim($readTekanSTD1 ?? '')) || 
                               !empty(trim($readTekanSTD2 ?? '')) || 
                               !empty(trim($readTekanSTD3 ?? '')) || 
                               !empty(trim($readTekanUUT1 ?? '')) || 
                               !empty(trim($readTekanUUT2 ?? '')) || 
                               !empty(trim($readTekanUUT3 ?? ''));
                    
                    if ($hasData) {
                        $detailData = [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'titikUkur' => $titikUkur,
                            'readTekanSTD1' => !empty($readTekanSTD1) ? str_replace(',', '.', $readTekanSTD1) : null,
                            'readTekanSTD2' => !empty($readTekanSTD2) ? str_replace(',', '.', $readTekanSTD2) : null,
                            'readTekanSTD3' => !empty($readTekanSTD3) ? str_replace(',', '.', $readTekanSTD3) : null,
                            'readTekanUUT1' => !empty($readTekanUUT1) ? str_replace(',', '.', $readTekanUUT1) : null,
                            'readTekanUUT2' => !empty($readTekanUUT2) ? str_replace(',', '.', $readTekanUUT2) : null,
                            'readTekanUUT3' => !empty($readTekanUUT3) ? str_replace(',', '.', $readTekanUUT3) : null,
                            'readTarikSTD1' => null,
                            'readTarikSTD2' => null,
                            'readTarikSTD3' => null,
                            'readTarikUUT1' => null,
                            'readTarikUUT2' => null,
                            'readTarikUUT3' => null,
                        ];
                        
                        DetailUtm::create($detailData);
                        $detailCountTekan++;
                        $totalDetailCount++;
                    }
                }
            }
        }
        
        // ================================================================
        // 🔥 PROSES DATA TARIK - AMBIL DARI ARRAY "tarik_{formIndex}[]"
        // ================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $tarikData = $request->input("tarik_{$formIndex}", []);
            
            if (!empty($tarikData) && is_array($tarikData)) {
                \Log::info("📊 Processing TARIK data for form {$formIndex}", ['count' => count($tarikData)]);
                
                foreach ($tarikData as $data) {
                    $titikUkur = $data['titikUkur'] ?? null;
                    $readTarikSTD1 = $data['readTarikSTD1'] ?? null;
                    $readTarikSTD2 = $data['readTarikSTD2'] ?? null;
                    $readTarikSTD3 = $data['readTarikSTD3'] ?? null;
                    $readTarikUUT1 = $data['readTarikUUT1'] ?? null;
                    $readTarikUUT2 = $data['readTarikUUT2'] ?? null;
                    $readTarikUUT3 = $data['readTarikUUT3'] ?? null;
                    
                    $hasData = !empty(trim($titikUkur ?? '')) || 
                               !empty(trim($readTarikSTD1 ?? '')) || 
                               !empty(trim($readTarikSTD2 ?? '')) || 
                               !empty(trim($readTarikSTD3 ?? '')) || 
                               !empty(trim($readTarikUUT1 ?? '')) || 
                               !empty(trim($readTarikUUT2 ?? '')) || 
                               !empty(trim($readTarikUUT3 ?? ''));
                    
                    if ($hasData) {
                        $detailData = [
                            'calibration_id' => $calibration->id,
                            'form_index' => $formIndex,
                            'titikUkur' => $titikUkur,
                            'readTekanSTD1' => null,
                            'readTekanSTD2' => null,
                            'readTekanSTD3' => null,
                            'readTekanUUT1' => null,
                            'readTekanUUT2' => null,
                            'readTekanUUT3' => null,
                            'readTarikSTD1' => !empty($readTarikSTD1) ? str_replace(',', '.', $readTarikSTD1) : null,
                            'readTarikSTD2' => !empty($readTarikSTD2) ? str_replace(',', '.', $readTarikSTD2) : null,
                            'readTarikSTD3' => !empty($readTarikSTD3) ? str_replace(',', '.', $readTarikSTD3) : null,
                            'readTarikUUT1' => !empty($readTarikUUT1) ? str_replace(',', '.', $readTarikUUT1) : null,
                            'readTarikUUT2' => !empty($readTarikUUT2) ? str_replace(',', '.', $readTarikUUT2) : null,
                            'readTarikUUT3' => !empty($readTarikUUT3) ? str_replace(',', '.', $readTarikUUT3) : null,
                        ];
                        
                        DetailUtm::create($detailData);
                        $detailCountTarik++;
                        $totalDetailCount++;
                    }
                }
            }
        }
        
        \Log::info("✅ Saved detail measurements for UTM:", [
            'total_details' => $totalDetailCount,
            'tekan' => $detailCountTekan,
            'tarik' => $detailCountTarik
        ]);
        
        // ==================================================================
        // 3. UPDATE FIELD LAINNYA DI CALIBRATION
        // ==================================================================
        $updateData = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->brandAlat ?? $calibration->brandAlat,
            'kodeAlat' => $request->kodeAlat ?? $calibration->kodeAlat,
            'typeAlat' => $request->typeAlat ?? $calibration->typeAlat,
            'NoSeri' => $request->NoSeri ?? $calibration->NoSeri,
            'pemilikAlat' => $request->pemilikAlat ?? $calibration->pemilikAlat,
            'tanggalMasuk' => $request->tanggalMasuk ?? $calibration->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi ?? $calibration->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $calibration->tempatKalibrasi,
            'jenisPembacaan' => $request->jenisPembacaan ?? $calibration->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT ?? $calibration->lokasiPT,
            'kode_th' => $request->kode_th ?? $calibration->kode_th,
            'kondisiAlat' => $request->kondisiAlat ?? $calibration->kondisiAlat,
            'keterangan' => $request->keterangan ?? $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1 ?? $calibration->RT_condition1,
            'RT_condition2' => $request->RT_condition2 ?? $calibration->RT_condition2,
            'RT_condition3' => $request->RT_condition3 ?? $calibration->RT_condition3,
            'RH_condition1' => $request->RH_condition1 ?? $calibration->RH_condition1,
            'RH_condition2' => $request->RH_condition2 ?? $calibration->RH_condition2,
            'RH_condition3' => $request->RH_condition3 ?? $calibration->RH_condition3,
            'calibratedBy' => $request->calibratedBy ?? $calibration->calibratedBy,
            'verifiedBy' => $request->verifiedBy ?? $calibration->verifiedBy,
            'jumlah_form' => $jumlahForm,
        ];
        
        $calibration->update($updateData);
        $calibration->refresh();
        
        // FINAL VERIFICATION
        $allHeads = HeadUtm::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailUtm::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🎯 FINAL SUMMARY AFTER UPDATE:', [
            'total_heads' => $allHeads->count(),
            'heads_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_details' => $allDetails->count(),
            'details_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        \Log::info('🎉 updateUtm completed successfully', [
            'calibration_id' => $calibration->id,
            'details_created' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateUtm FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function storeAnakTimbangan($request, $calibration, $certificateId)
{
    try {
        \Log::info('🔧 Starting storeAnakTimbangan function...');
        
        $tabId = $request->input('tab_id', 1);
        $jumlahForm = (int) ($request->input('jumlah_form', 1));
        $formIndex = (int) ($request->input('form_index', 1));
        
        $getValue = function($baseName) use ($request, $formIndex, $tabId) {
            $candidates = [
                "form_{$formIndex}_{$baseName}_tab{$tabId}",
                "form_1_{$baseName}_tab{$tabId}",
                "{$baseName}_{$formIndex}_tab{$tabId}",
                "{$baseName}_tab{$tabId}",
                "form_{$formIndex}_{$baseName}",
                "{$baseName}_{$formIndex}",
                $baseName
            ];
            
            foreach ($candidates as $candidate) {
                if ($request->has($candidate)) {
                    $val = $request->input($candidate);
                    if ($val !== null && $val !== '') {
                        return $val;
                    }
                }
            }
            return null;
        };

        $alatStandar = $getValue('alat_standar') ?? $request->alat_standar ?? [];
        if (is_string($alatStandar)) {
            $alatStandar = [$alatStandar];
        }
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected:', ['alat_standar' => $alatStandarString]);

        // Simpan ke Head Anak Timbangan
        $head = HeadAnakTimbangan::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'satuan_unit01' => $getValue('satuan_unit01') ?? '',
            'satuan_unit02' => $getValue('satuan_unit02') ?? '',
            'calibrationMethod' => 'PAS-IK1102-16',
        ]);

        \Log::info('✅ Head Anak Timbangan saved:', ['head_id' => $head->id]);

        // Simpan detail measurements - 5 NOMOR
        \Log::info('📊 Saving detail measurements for Anak Timbangan...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 5; $i++) {
            $massaNominal = $getValue("massa_nominal_$i");
            $atStandard = $getValue("at_standard_$i");
            
            $ulstd = $getValue("unit01_s_{$i}_1");
            $urstd = $getValue("unit02_s_{$i}_1");
            $uluut = $getValue("unit01_t_{$i}_1");
            $uruut = $getValue("unit02_t_{$i}_1");
            $lluut = $getValue("unit01_t_{$i}_2");
            $lruut = $getValue("unit02_t_{$i}_2");
            $llstd = $getValue("unit01_s_{$i}_2");
            $lrstd = $getValue("unit02_s_{$i}_2");

            $hasData = (!empty($massaNominal) && trim($massaNominal) !== '') ||
                       (!empty($atStandard) && trim($atStandard) !== '') ||
                       (!empty($ulstd) && trim($ulstd) !== '') ||
                       (!empty($uluut) && trim($uluut) !== '');
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'nominalAlat' => $massaNominal ?? '',
                    'ATSTD' => $atStandard ?? '',
                    'ULSTD' => $ulstd,
                    'URSTD' => $urstd,
                    'ULUUT' => $uluut,
                    'URUUT' => $uruut,
                    'LLUUT' => $lluut,
                    'LRUUT' => $lruut,
                    'LLSTD' => $llstd,
                    'LRSTD' => $lrstd,
                ];
                
                \Log::debug("📝 Saving Anak Timbangan - Nomor {$i}:", $detailData);
                
                DetailAnakTimbangan::create($detailData);
                $detailCount++;
            } else {
                \Log::debug("⚠️ Skipping Nomor {$i} - No data found");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Anak Timbangan");

    } catch (\Exception $e) {
        \Log::error('💥 Error storing Anak Timbangan data:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function updateAnakTimbangan($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateAnakTimbangan (MULTIPLE FORM)', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $newCertificateId,
            'jumlah_form' => $request->input('jumlah_form', 1)
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request (name="namaAlat")
        $namaAlatDariRequest = $request->input('namaAlat') ?? $calibration->namaAlat;
        $originalNamaAlat = $calibration->namaAlat;
        
        // Ambil head form 1 yang sudah ada
        $existingHead = HeadAnakTimbangan::where('calibration_id', $calibration->id)
            ->where('form_index', 1)
            ->first();
        $currentHeadCertificateId = $existingHead ? $existingHead->certificate_id : null;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_head_certificate_id' => $currentHeadCertificateId,
        ]);
        
        $expectedCertificateId = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
        
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $expectedCertificateId;
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah)');
        } elseif ($currentHeadCertificateId != $expectedCertificateId && !empty($expectedCertificateId)) {
            $certificateIdBaru = $expectedCertificateId;
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (tidak sesuai)');
        } elseif (empty($currentHeadCertificateId) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (head kosong)');
        }
        
        if (empty($certificateIdBaru) && !empty($newCertificateId)) {
            $certificateIdBaru = $newCertificateId;
            $certificateIdUpdated = true;
        }
        
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $expectedCertificateId;
            $certificateIdUpdated = true;
        }
        
        $finalCertificateId = $certificateIdBaru;
        
        // ==================================================================
        // 1. AMBIL JUMLAH FORM
        // ==================================================================
        $jumlahForm = (int) ($request->input('jumlah_form', $calibration->jumlah_form ?? 1));
        $jumlahForm = max(1, min(4, $jumlahForm));
        
        // ==================================================================
        // 2. AMBIL KAPASITAS DAN RESOLUSI DARI REQUEST
        // ==================================================================
        // 🔥 Kapasitas dari form 1 (kapasitas_1) atau kapasitas
        $kapasitasCalibration = $request->input('kapasitas_1') ?? $request->input('kapasitas');
        $resolusiCalibration = $request->input('resolusi_1') ?? $request->input('resolusi');
        
        \Log::info('📊 KAPASITAS & RESOLUSI DARI REQUEST:', [
            'kapasitas_1' => $request->input('kapasitas_1'),
            'kapasitas' => $request->input('kapasitas'),
            'kapasitas_final' => $kapasitasCalibration,
            'resolusi_1' => $request->input('resolusi_1'),
            'resolusi' => $request->input('resolusi'),
            'resolusi_final' => $resolusiCalibration
        ]);
        
        // ==================================================================
        // 3. UPDATE CALIBRATION (FIELD UTAMA + KAPASITAS & RESOLUSI)
        // ==================================================================
        $updateData = [];
        
        // Field dasar
        if ($request->filled('namaAlat')) {
            $updateData['namaAlat'] = $request->namaAlat;
        }
        if ($request->filled('brandAlat')) {
            $updateData['brandAlat'] = $request->brandAlat;
        }
        if ($request->filled('kodeAlat')) {
            $updateData['kodeAlat'] = $request->kodeAlat;
        }
        if ($request->filled('typeAlat')) {
            $updateData['typeAlat'] = $request->typeAlat;
        }
        if ($request->filled('NoSeri')) {
            $updateData['NoSeri'] = $request->NoSeri;
        }
        if ($request->filled('pemilikAlat')) {
            $updateData['pemilikAlat'] = $request->pemilikAlat;
        }
        if ($request->filled('tanggalMasuk')) {
            $updateData['tanggalMasuk'] = $request->tanggalMasuk;
        }
        if ($request->filled('tanggalKalibrasi')) {
            $updateData['tanggalKalibrasi'] = $request->tanggalKalibrasi;
        }
        if ($request->filled('tempatKalibrasi')) {
            $updateData['tempatKalibrasi'] = $request->tempatKalibrasi;
        }
        if ($request->filled('lokasiPT')) {
            $updateData['lokasiPT'] = $request->lokasiPT;
        }
        if ($request->filled('kode_th')) {
            $updateData['kode_th'] = $request->kode_th;
        }
        if ($request->filled('kondisiAlat')) {
            $updateData['kondisiAlat'] = $request->kondisiAlat;
        }
        if ($request->filled('keterangan')) {
            $updateData['keterangan'] = $request->keterangan;
        }
        if ($request->filled('RT_condition1')) {
            $updateData['RT_condition1'] = $request->RT_condition1;
            $updateData['RT_condition2'] = $request->RT_condition2;
            $updateData['RT_condition3'] = $request->RT_condition3;
        }
        if ($request->filled('RH_condition1')) {
            $updateData['RH_condition1'] = $request->RH_condition1;
            $updateData['RH_condition2'] = $request->RH_condition2;
            $updateData['RH_condition3'] = $request->RH_condition3;
        }
        
        // 🔥 KAPASITAS - SIMPAN KE CALIBRATION
        if (!empty($kapasitasCalibration)) {
            $updateData['kapasitas'] = $kapasitasCalibration;
        }
        
        // 🔥 RESOLUSI - SIMPAN KE CALIBRATION
        if (!empty($resolusiCalibration)) {
            $updateData['resolusi'] = $resolusiCalibration;
        }
        
        // Calibrated By - dari form 1
        $calibratedBy = $request->input('calibratedBy_1') ?? $request->input('calibratedBy');
        if (!empty($calibratedBy)) {
            $updateData['calibratedBy'] = $calibratedBy;
        }
        
        // Verified By - dari form 1
        $verifiedBy = $request->input('verifiedBy_1') ?? $request->input('verifiedBy');
        if (!empty($verifiedBy)) {
            $updateData['verifiedBy'] = $verifiedBy;
        }
        
        $updateData['jumlah_form'] = $jumlahForm;
        $updateData['certificate_id'] = null;
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ CALIBRATION UPDATED', [
                'fields' => array_keys($updateData),
                'kapasitas' => $updateData['kapasitas'] ?? 'tidak diupdate',
                'resolusi' => $updateData['resolusi'] ?? 'tidak diupdate'
            ]);
        }
        
        // ==================================================================
        // 4. PROSES HEAD UNTUK SETIAP FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            
            // Cari head yang sudah ada untuk form ini
            $head = HeadAnakTimbangan::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // ALAT STANDAR - name="alat_standar_{{ $formIndex }}[]"
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            // SATUAN UNIT - name="satuan_unit01_{{ $formIndex }}"
            $satuanUnit01 = $request->input("satuan_unit01_{$formIndex}") ?? '';
            $satuanUnit02 = $request->input("satuan_unit02_{$formIndex}") ?? '';
            
            // KAPASITAS & RESOLUSI PER FORM - name="kapasitas_{{ $formIndex }}"
            $kapasitasForm = $request->input("kapasitas_{$formIndex}") ?? '';
            $resolusiForm = $request->input("resolusi_{$formIndex}") ?? '';
            
            // KETERANGAN FUNGSI KOMPONEN - name="keterangan_{{ $formIndex }}"
            $keteranganFungsiKomponen = $request->input("keterangan_{$formIndex}") ?? '';
            if (empty($keteranganFungsiKomponen) && $formIndex == 1) {
                $keteranganFungsiKomponen = $request->input("keterangan") ?? '';
            }
            
            // VERIFIED BY PER FORM - name="verifiedBy_{{ $formIndex }}"
            $verifiedByForm = $request->input("verifiedBy_{$formIndex}") ?? '';
            if (empty($verifiedByForm) && $formIndex == 1) {
                $verifiedByForm = $request->input("verifiedBy") ?? '';
            }
            
            $headData = [
                'standard' => $alatStandarString,
                'satuan_unit01' => $satuanUnit01,
                'satuan_unit02' => $satuanUnit02,
                'calibrationMethod' => 'PAS-IK1102-16',
                'kapasitas' => $kapasitasForm,
                'resolusi' => $resolusiForm,
                'keterangan_fungsi_komponen' => $keteranganFungsiKomponen,
                'verified_by' => $verifiedByForm,
            ];
            
            // Update certificate_id di HEAD
            if (!empty($finalCertificateId)) {
                $headData['certificate_id'] = $finalCertificateId;
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'satuan_unit01' => $satuanUnit01,
                    'satuan_unit02' => $satuanUnit02,
                    'kapasitas' => $kapasitasForm,
                    'resolusi' => $resolusiForm
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                if (empty($headData['certificate_id'])) {
                    $headData['certificate_id'] = $finalCertificateId ?? 'NEW-' . time();
                }
                $head = HeadAnakTimbangan::create($headData);
                \Log::info("✅ Head created for form {$formIndex}", [
                    'head_id' => $head->id,
                    'satuan_unit01' => $satuanUnit01,
                    'satuan_unit02' => $satuanUnit02,
                    'kapasitas' => $kapasitasForm,
                    'resolusi' => $resolusiForm
                ]);
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadAnakTimbangan::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 5. PROSES DETAIL UNTUK SETIAP FORM
        // ==================================================================
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            
            // Hapus detail lama untuk form ini (akan di-replace)
            DetailAnakTimbangan::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->delete();
            
            for ($i = 1; $i <= 5; $i++) {
                // MASSA NOMINAL - name="massa_nominal_{{ $formIndex }}_{{ $i }}"
                $massaNominal = $request->input("massa_nominal_{$formIndex}_{$i}");
                
                // Jika tidak ada massa nominal, skip
                if (empty($massaNominal) && $massaNominal !== '0') {
                    continue;
                }
                
                // AT STANDARD - name="at_standard_{{ $formIndex }}_{{ $i }}"
                $atStandard = $request->input("at_standard_{$formIndex}_{$i}") ?? '';
                
                // BARIS 1: S - S - name="unit01_s_{{ $formIndex }}_{{ $i }}_1"
                $unit01_s_1 = $request->input("unit01_s_{$formIndex}_{$i}_1") ?? '';
                $unit02_s_1 = $request->input("unit02_s_{$formIndex}_{$i}_1") ?? '';
                
                // BARIS 2: T - T - name="unit01_t_{{ $formIndex }}_{{ $i }}_1"
                $unit01_t_1 = $request->input("unit01_t_{$formIndex}_{$i}_1") ?? '';
                $unit02_t_1 = $request->input("unit02_t_{$formIndex}_{$i}_1") ?? '';
                
                // BARIS 3: T - T - name="unit01_t_{{ $formIndex }}_{{ $i }}_2"
                $unit01_t_2 = $request->input("unit01_t_{$formIndex}_{$i}_2") ?? '';
                $unit02_t_2 = $request->input("unit02_t_{$formIndex}_{$i}_2") ?? '';
                
                // BARIS 4: S - S - name="unit01_s_{{ $formIndex }}_{{ $i }}_2"
                $unit01_s_2 = $request->input("unit01_s_{$formIndex}_{$i}_2") ?? '';
                $unit02_s_2 = $request->input("unit02_s_{$formIndex}_{$i}_2") ?? '';
                
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'nominalAlat' => $massaNominal,
                    'ATSTD' => $atStandard,
                    'ULSTD' => $unit01_s_1,
                    'URSTD' => $unit02_s_1,
                    'ULUUT' => $unit01_t_1,
                    'URUUT' => $unit02_t_1,
                    'LLUUT' => $unit01_t_2,
                    'LRUUT' => $unit02_t_2,
                    'LLSTD' => $unit01_s_2,
                    'LRSTD' => $unit02_s_2,
                ];
                
                DetailAnakTimbangan::create($detailData);
                $totalDetailCount++;
            }
        }
        
        \Log::info("✅ Saved {$totalDetailCount} detail measurements for Anak Timbangan");
        
        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $heads = HeadAnakTimbangan::where('calibration_id', $calibration->id)->get();
        $details = DetailAnakTimbangan::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🏁 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $calibration->jumlah_form,
            'heads_count' => $heads->count(),
            'details_count' => $details->count(),
            'certificate_id_heads' => $heads->pluck('certificate_id')->toArray(),
            'kapasitas_calibration' => $calibration->kapasitas,
            'resolusi_calibration' => $calibration->resolusi,
            'heads_kapasitas' => $heads->pluck('kapasitas')->toArray(),
            'heads_resolusi' => $heads->pluck('resolusi')->toArray(),
            'calibratedBy' => $calibration->calibratedBy,
            'verifiedBy' => $calibration->verifiedBy,
        ]);

        \Log::info('🎉 updateAnakTimbangan COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateAnakTimbangan:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        
        throw new \Exception("Gagal mengupdate data Anak Timbangan: " . $e->getMessage());
    }
}
/**
 * Helper function untuk membersihkan nilai numerik
 */
private function cleanNumericValue($value)
{
    if (empty($value) || trim($value) === '') {
        return null;
    }
    
    // Hapus spasi dan karakter non-numerik kecuali titik dan minus
    $cleaned = preg_replace('/[^\d\.\-]/', '', $value);
    
    // Cek jika kosong setelah dibersihkan
    if ($cleaned === '' || $cleaned === '-') {
        return null;
    }
    
    return $cleaned;
}

private function storePressureTransmitter($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storePressureTransmitter');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storePressureTransmitter called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = [];
        
        // Ambil alat standar dari input (bisa berupa array atau string)
        $alatStandarInput = $request->input('alat_standar', []);
        if (is_array($alatStandarInput)) {
            $alatStandar = $alatStandarInput;
        } elseif (!empty($alatStandarInput)) {
            $alatStandar = [$alatStandarInput];
        }
        
        // Coba ambil dari field alternatif
        if (empty($alatStandar)) {
            for ($i = 1; $i <= 10; $i++) {
                $value = $this->getRequestValue($request, "alat_standar_{$i}", $tabId);
                if ($value && !in_array($value, $alatStandar)) {
                    $alatStandar[] = $value;
                }
            }
        }
        
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        \Log::info('🔧 Alat standar selected for Pressure Transmitter:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN KE HEAD PRESSURE TRANSMITTER
        // ==================================================================
        $head = HeadPressureTransmitter::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-55',
            'satuan_set_point' => $this->getRequestValue($request, 'satuan_set_point', $tabId),
            'satuan_p_naik' => $this->getRequestValue($request, 'satuan_p_naik', $tabId),
            'satuan_so_naik' => $this->getRequestValue($request, 'satuan_signal_naik', $tabId),
            'satuan_p_turun' => $this->getRequestValue($request, 'satuan_p_turun', $tabId),
            'satuan_so_turun' => $this->getRequestValue($request, 'satuan_signal_turun', $tabId),
            'tertelusur' => $this->getRequestValue($request, 'tertelusur', $tabId),
        ]);

        \Log::info('✅ HeadPressureTransmitter saved:', ['head_id' => $head->id]);

        // ==================================================================
        // 3. SIMPAN DETAIL PRESSURE TRANSMITTER (11 TITIK)
        // ==================================================================
        \Log::info('📊 Saving Pressure Transmitter detail measurements (11 rows)...');
        $detailCount = 0;
        
        for ($i = 1; $i <= 11; $i++) {
            // Ambil nilai dengan getRequestValue
            $setPoint = $this->getRequestValue($request, "set_point_{$i}", $tabId);
            $readPUp = $this->getRequestValue($request, "pembacaan_naik_{$i}", $tabId);
            $readSUp = $this->getRequestValue($request, "signal_naik_{$i}", $tabId);
            $readPDown = $this->getRequestValue($request, "pembacaan_turun_{$i}", $tabId);
            $readSDown = $this->getRequestValue($request, "signal_turun_{$i}", $tabId);
            
            // Cek apakah ada data
            $hasData = !empty($setPoint) || !empty($readPUp) || !empty($readSUp) || !empty($readPDown) || !empty($readSDown);
            
            if ($hasData) {
                DetailPressureTransmitter::create([
                    'calibration_id' => $calibration->id,
                    'head_pressure_transmitter_id' => $head->id,
                    'setPoint' => $setPoint,
                    'readP_UP' => $readPUp,
                    'readS_UP' => $readSUp,
                    'readP_DOWN' => $readPDown,
                    'readS_DOWN' => $readSDown,
                ]);
                $detailCount++;
                \Log::debug("✅ Detail saved for row {$i}");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Pressure Transmitter");

        // ==================================================================
        // 4. SIMPAN ADD PRESSURE TRANSMITTER (REPEATABILITY)
        // ==================================================================
        \Log::info('📊 Saving AddPressureTransmitter data...');
        
        $additionalData = [
            'calibration_id' => $calibration->id,
            'repeatibility_P' => $this->getRequestValue($request, 'repeatability_p', $tabId),
            'satuan_P' => $this->getRequestValue($request, 'satuan_p', $tabId),
            'repeatibility_SO' => $this->getRequestValue($request, 'repeatibility_SO', $tabId),
            'satuan_SO' => $this->getRequestValue($request, 'satuan_SO', $tabId),
        ];
        
        // Data repeatability pressure (repP01 - repP10)
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = 'repP' . sprintf('%02d', $i);
            $additionalData[$fieldName] = $this->getRequestValue($request, $fieldName, $tabId);
        }
        
        // Data repeatability signal (repSO01 - repSO10)
        for ($i = 1; $i <= 10; $i++) {
            $fieldName = 'repSO' . sprintf('%02d', $i);
            $additionalData[$fieldName] = $this->getRequestValue($request, $fieldName, $tabId);
        }
        
        // Cek apakah ada data yang akan disimpan
        $hasData = false;
        foreach ($additionalData as $key => $value) {
            if ($key !== 'calibration_id' && !empty($value)) {
                $hasData = true;
                break;
            }
        }
        
        if ($hasData) {
            AddPressureTransmitter::create($additionalData);
            \Log::info('✅ AddPressureTransmitter saved');
        } else {
            \Log::info('⚠️ No AddPressureTransmitter data to save');
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION (jika ada data tambahan)
        // ==================================================================
        $updateData = [];
        
        $uncertainty = $this->getRequestValue($request, 'uncertainty', $tabId);
        if ($uncertainty) {
            $updateData['uncertainty'] = $uncertainty;
        }
        
        $keterangan = $this->getRequestValue($request, 'conclusion', $tabId);
        if ($keterangan) {
            $updateData['keterangan'] = $keterangan;
        }
        
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', $updateData);
        }

        // ==================================================================
        // 6. LOG SUMMARY
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (Pressure Transmitter):', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'detail_records' => $detailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
        ]);

        \Log::info('🎉 storePressureTransmitter COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storePressureTransmitter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
        ]);
        
        throw $e;
    }
}

private function updatePressureTransmitter($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updatePressureTransmitter', [
            'calibration_id' => $calibration->id,
            'certificate_id_received' => $newCertificateId
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->input('namaAlat') ?? $request->input('nama_alat') ?? $request->input('nama_alat_final') ?? $calibration->namaAlat;
        
        // Ambil nama alat asli dari database
        $originalNamaAlat = $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT UNTUK CERTIFICATE ID:', [
            'nama_alat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'new_certificate_id_from_param' => $newCertificateId,
            'current_certificate_id_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di calibration kosong
        elseif (empty($calibration->certificate_id) && !empty($certificateIdBaru)) {
            $certificateIdUpdated = true;
            \Log::info('🆔 Certificate ID akan diupdate (kosong):', [
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        // Jika certificate_id di head kosong
        else {
            $existingHead = HeadPressureTransmitter::where('calibration_id', $calibration->id)->first();
            if ($existingHead && empty($existingHead->certificate_id) && !empty($certificateIdBaru)) {
                $certificateIdUpdated = true;
                \Log::info('🆔 Certificate ID akan diupdate (head kosong):', [
                    'new_certificate_id' => $certificateIdBaru
                ]);
            }
        }
        
        // Jika certificate_id masih kosong, gunakan dari parameter atau generate
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $calibration->certificate_id;
        }
        
        if (empty($certificateIdBaru)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
        }
        
        $finalCertificateId = $certificateIdBaru;
        
        \Log::info('📋 Final Certificate ID:', [
            'certificate_id' => $finalCertificateId,
            'certificate_id_updated' => $certificateIdUpdated
        ]);

        // ==================================================================
        // 1. PROSES ALAT STANDAR (CHECKBOX) - TANPA FORMAT
        // ==================================================================
        $alatStandarItems = [];
        
        if ($request->has('const_P001') && $request->const_P001 == '1') {
            $alatStandarItems[] = 'Const P.001 (0 ~ 700 bar ; Hydraulic)';
        }
        
        if ($request->has('adittel_P002') && $request->adittel_P002 == '1') {
            $alatStandarItems[] = 'Adittel P.002 (-125 ~ 1000 Pa ; Pneumatic)';
        }
        
        if ($request->has('adittel_P003') && $request->adittel_P003 == '1') {
            $alatStandarItems[] = 'Adittel P.003 (-1 ~ 20 bar ; Pneumatic)';
        }
        
        if ($request->has('adittel_P004') && $request->adittel_P004 == '1') {
            $alatStandarItems[] = 'Adittel P.004 (0 ~ 700 bar ; Hydraulic)';
        }
        
        $alatStandarString = !empty($alatStandarItems) ? implode(', ', $alatStandarItems) : '';
        
        \Log::info('🔧 Alat standar selected:', ['alat_standar' => $alatStandarItems]);

        // ==================================================================
        // 2. UPDATE HEAD PRESSURE TRANSMITTER
        // ==================================================================
        $head = HeadPressureTransmitter::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => 'PAS-IK1102-55',
            'satuan_set_point' => $request->satuan_set_point,
            'satuan_p_naik' => $request->satuan_p_naik,
            'satuan_so_naik' => $request->satuan_so_naik,
            'satuan_p_turun' => $request->satuan_p_turun,
            'satuan_so_turun' => $request->satuan_so_turun,
            'tertelusur' => $request->tertelusur,
        ];
        
        // Update certificate_id di HEAD jika diperlukan
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $headData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Setting certificate_id di HEAD:', ['certificate_id' => $finalCertificateId]);
        }
        
        if ($head) {
            $head->update($headData);
            $head->refresh();
            \Log::info('✅ Head Pressure Transmitter updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $head = HeadPressureTransmitter::create($headData);
            \Log::info('✅ Head Pressure Transmitter created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null
            ]);
        }

        // ==================================================================
        // 3. UPDATE DETAIL PRESSURE TRANSMITTER (11 BARIS) - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating Pressure Transmitter detail measurements...');
        
        DetailPressureTransmitter::where('calibration_id', $calibration->id)->delete();
        
        $setPointArray = $request->setPoint ?? [];
        $readP_UPArray = $request->readP_UP ?? [];
        $readS_UPArray = $request->readS_UP ?? [];
        $readP_DOWNArray = $request->readP_DOWN ?? [];
        $readS_DOWNArray = $request->readS_DOWN ?? [];
        
        $detailCount = 0;
        
        for ($i = 0; $i < 11; $i++) {
            $setPoint = $setPointArray[$i] ?? null;
            $readP_UP = $readP_UPArray[$i] ?? null;
            $readS_UP = $readS_UPArray[$i] ?? null;
            $readP_DOWN = $readP_DOWNArray[$i] ?? null;
            $readS_DOWN = $readS_DOWNArray[$i] ?? null;
            
            $hasData = !empty($setPoint) || !empty($readP_UP) || !empty($readS_UP) || !empty($readP_DOWN) || !empty($readS_DOWN);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'head_pressure_transmitter_id' => $head->id,
                    'setPoint' => $setPoint,        // LANGSUNG, tanpa format
                    'readP_UP' => $readP_UP,        // LANGSUNG, tanpa format
                    'readS_UP' => $readS_UP,        // LANGSUNG, tanpa format
                    'readP_DOWN' => $readP_DOWN,    // LANGSUNG, tanpa format
                    'readS_DOWN' => $readS_DOWN,    // LANGSUNG, tanpa format
                ];
                
                DetailPressureTransmitter::create($detailData);
                $detailCount++;
            }
        }
        
        \Log::info("✅ Updated {$detailCount} detail measurements");

        // ==================================================================
        // 4. UPDATE ADD PRESSURE TRANSMITTER (REPEATABILITY) - TANPA FORMAT
        // ==================================================================
        \Log::info('📊 Updating Add Pressure Transmitter data...');
        
        AddPressureTransmitter::where('calibration_id', $calibration->id)->delete();
        
        $additionalData = [
            'calibration_id' => $calibration->id,
            'repeatibility_P' => $request->repeatibility_P,
            'satuan_P' => $request->satuan_P,
            'repeatibility_SO' => $request->repeatibility_SO,
            'satuan_SO' => $request->satuan_SO,
        ];

        $repPValues = $request->repP_value ?? [];
        for ($i = 0; $i < 10; $i++) {
            $fieldName = 'repP' . sprintf('%02d', $i + 1);
            $additionalData[$fieldName] = $repPValues[$i] ?? null;
        }
        
        $repSOValues = $request->repSO_value ?? [];
        for ($i = 0; $i < 10; $i++) {
            $fieldName = 'repSO' . sprintf('%02d', $i + 1);
            $additionalData[$fieldName] = $repSOValues[$i] ?? null;
        }
        
        $filteredData = array_filter($additionalData, function($value) {
            return $value !== null && $value !== '';
        });
        
        $filteredData['calibration_id'] = $calibration->id;
        
        if (count($filteredData) > 1) {
            AddPressureTransmitter::create($filteredData);
            \Log::info('✅ Add Pressure Transmitter data updated');
        }

        // ==================================================================
        // 5. UPDATE CALIBRATION DENGAN DATA DARI FORM (TERMASUK CERTIFICATE ID)
        // ==================================================================
        $updateData = [];
        
        // Update nama alat jika berubah
        if (!empty($namaAlatDariRequest) && $namaAlatDariRequest != $originalNamaAlat) {
            $updateData['namaAlat'] = $namaAlatDariRequest;
            \Log::info('📝 Nama alat diupdate di calibration:', [
                'old' => $originalNamaAlat,
                'new' => $namaAlatDariRequest
            ]);
        }
        
        // Update certificate_id di CALIBRATION (opsional, untuk memudahkan query)
        if ($certificateIdUpdated && !empty($finalCertificateId)) {
            $updateData['certificate_id'] = $finalCertificateId;
            \Log::info('📝 Certificate ID diupdate di CALIBRATION:', ['new' => $finalCertificateId]);
        }
        
        if ($request->filled('calibratedBy')) {
            $updateData['calibrated_by'] = $request->calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibratedBy]);
        } elseif ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verifiedBy')) {
            $updateData['verified_by'] = $request->verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $request->verifiedBy]);
        } elseif ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if ($request->filled('uncertainty')) {
            $updateData['uncertainty'] = $request->uncertainty;
            $updateData['keterangan'] = $request->conclusion ?? '';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with additional data:', array_keys($updateData));
        }

        // ==================================================================
        // 6. LOG HASIL AKHIR
        // ==================================================================
        $calibration->refresh();
        $head->refresh();
        
        \Log::info('🏁 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'head_id' => $head->id,
            'certificate_id_di_head' => $head->certificate_id,
            'certificate_id_di_calibration' => $calibration->certificate_id,
            'nama_alat' => $calibration->namaAlat,
            'alat_standar' => $alatStandarString,
            'calibrated_by' => $calibration->calibrated_by,
            'verified_by' => $calibration->verified_by,
        ]);

        \Log::info('🎉 updatePressureTransmitter COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updatePressureTransmitter:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Pressure Transmitter: " . $e->getMessage());
    }
}
private function storeSurfacePlate($request, $calibration, $certificateId, $tabId = null)
{
    \Log::info('📐 ===== START storeSurfacePlate =====', [
        'calibration_id' => $calibration->id,
        'tab_id' => $tabId
    ]);

    try {
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }

        \Log::info('📌 storeSurfacePlate called with tab_id:', ['tab_id' => $tabId]);

        // ==================================================================
        // 1. PROSES ALAT STANDAR
        // ==================================================================
        $alatStandar = [];

        $alatStandarText = $this->getRequestValue($request, 'alat_standar_text', $tabId);
        if ($alatStandarText && !in_array($alatStandarText, $alatStandar)) {
            $alatStandar[] = $alatStandarText;
        }

        for ($i = 1; $i <= 10; $i++) {
            $fieldName = "alat_standar_{$i}";
            $value = $this->getRequestValue($request, $fieldName, $tabId);
            if ($value && !in_array($value, $alatStandar)) {
                $alatStandar[] = $value;
            }
        }

        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';

        \Log::info('🔧 Alat standar selected:', [
            'alat_standar' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SETTING SUHU (13 baris × 10 kolom)
        // ==================================================================
        $settingSuhuData = [];

        for ($i = 1; $i <= 13; $i++) {
            for ($j = 1; $j <= 10; $j++) {
                $fieldName = "a{$i}_{$j}";
                $value = $this->getRequestValue($request, $fieldName, $tabId);
                if ($value !== null && $value !== '') {
                    $settingSuhuData["a{$i}_{$j}"] = $value;
                }
            }
        }

        \Log::info('🌡️ Setting suhu collected:', [
            'count' => count($settingSuhuData),
        ]);

        // ==================================================================
        // 3. REPEATABILITY MATRIX (tbl1 - tbl12)
        // ==================================================================
        $repeatabilityData = [];

        $mapping = [
            'tbl1'  => ['prefix' => 'repeat_a', 'input_prefix' => 'repeat_a', 'is_group_a' => true],
            'tbl2'  => ['prefix' => 'b', 'input_prefix' => 'b'],
            'tbl3'  => ['prefix' => 'c', 'input_prefix' => 'c'],
            'tbl4'  => ['prefix' => 'd', 'input_prefix' => 'd'],
            'tbl5'  => ['prefix' => 'e', 'input_prefix' => 'e'],
            'tbl6'  => ['prefix' => 'f', 'input_prefix' => 'f'],
            'tbl7'  => ['prefix' => 'g', 'input_prefix' => 'g'],
            'tbl8'  => ['prefix' => 'h', 'input_prefix' => 'h'],
            'tbl9'  => ['prefix' => 'i', 'input_prefix' => 'i'],
            'tbl10' => ['prefix' => 'j', 'input_prefix' => 'j'],
            'tbl11' => ['prefix' => 'k', 'input_prefix' => 'k'],
            'tbl12' => ['prefix' => 'l', 'input_prefix' => 'l'],
        ];

        foreach ($mapping as $tbl => $config) {
            $isGroupA = $config['is_group_a'] ?? false;

            if ($isGroupA) {
                // Group A: repeat_a{1..10}_{1,2}
                for ($i = 1; $i <= 10; $i++) {
                    $value1 = $this->getRequestValue($request, "repeat_a{$i}_1", $tabId);
                    $value2 = $this->getRequestValue($request, "repeat_a{$i}_2", $tabId);

                    if ($value1 !== null && $value1 !== '') {
                        $repeatabilityData["a{$i}_1_{$tbl}"] = $value1;
                    }
                    if ($value2 !== null && $value2 !== '') {
                        $repeatabilityData["a{$i}_2_{$tbl}"] = $value2;
                    }
                }
            } else {
                $prefix      = $config['prefix'];
                $inputPrefix = $config['input_prefix'];

                // Kolom pertama: a1_1_tblX / a1_2_tblX
                $v1 = $this->getRequestValue($request, "{$inputPrefix}_row1_col1", $tabId);
                $v2 = $this->getRequestValue($request, "{$inputPrefix}_row2_col1", $tabId);

                if ($v1 !== null && $v1 !== '') {
                    $repeatabilityData["a1_1_{$tbl}"] = $v1;
                }
                if ($v2 !== null && $v2 !== '') {
                    $repeatabilityData["a1_2_{$tbl}"] = $v2;
                }

                // Kolom berikutnya (b1..b10 / c1..c10 / dst)
                for ($i = 1; $i <= 10; $i++) {
                    $v1 = $this->getRequestValue($request, "{$inputPrefix}_row1_col" . ($i + 1), $tabId);
                    $v2 = $this->getRequestValue($request, "{$inputPrefix}_row2_col" . ($i + 1), $tabId);

                    if ($v1 !== null && $v1 !== '') {
                        $repeatabilityData["{$prefix}{$i}_1_{$tbl}"] = $v1;
                    }
                    if ($v2 !== null && $v2 !== '') {
                        $repeatabilityData["{$prefix}{$i}_2_{$tbl}"] = $v2;
                    }
                }
            }
        }

        \Log::info('📊 Repeatability collected:', [
            'count' => count($repeatabilityData),
        ]);

        // ==================================================================
        // 4. KETERANGAN / CANVAS
        // ==================================================================
        $keteranganValue = $this->getRequestValue($request, 'keterangan', $tabId) 
            ?? $request->input('keterangan')
            ?? $request->input('keterangan_tab' . $tabId);

        $keteranganText = '';
        if ($keteranganValue && strpos($keteranganValue, 'data:image') === 0) {
            $canvasImagePath = $this->saveCanvasImage($keteranganValue, $calibration->id, $tabId);
            if ($canvasImagePath) {
                $keteranganText = $canvasImagePath;
            }
        } else {
            $keteranganText = $keteranganValue ?? '';
        }

        // ==================================================================
        // 5. SIMPAN KE HEAD SURFACE PLATE
        // ==================================================================
        $head = HeadSurfacePlate::create([
            'calibration_id'     => $calibration->id,
            'certificate_id'     => $certificateId,
            'standard'           => $alatStandarString,
            'calibrationMethod'  => 'PAS-IK1102-53',
            'keterangan'         => $keteranganText,
        ]);

        \Log::info('✅ Head SurfacePlate saved:', ['head_id' => $head->id]);

        // ==================================================================
        // 6. SIMPAN KE DETAIL SURFACE PLATE
        //    TANPA head_surface_plate_id & form_index (kolom tidak ada di DB)
        // ==================================================================
        $detailData = array_merge(
            [
                'calibration_id' => $calibration->id,
            ],
            $settingSuhuData,
            $repeatabilityData
        );

        \Log::info('📊 Detail data yang akan disimpan:', [
            'setting_suhu_count'   => count($settingSuhuData),
            'repeatability_count'  => count($repeatabilityData),
            'total_fields'         => count($detailData),
            'tab_id'               => $tabId
        ]);

        $detail = DetailSurfacePlate::create($detailData);

        \Log::info('✅ Detail SurfacePlate saved:', [
            'detail_id' => $detail->id,
        ]);

        // ==================================================================
        // 7. UPDATE CALIBRATION DENGAN DATA TTD
        // ==================================================================
        $updateData = [];

        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
        }

        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
        }

        if (!empty($updateData)) {
            $calibration->update($updateData);
        }

        // ==================================================================
        // 8. LOG HASIL AKHIR
        // ==================================================================
        \Log::info('📋 STORE SUMMARY (SurfacePlate):', [
            'calibration_id'        => $calibration->id,
            'head_id'               => $head->id,
            'detail_id'             => $detail->id,
            'certificate_id'        => $certificateId,
            'tab_id'                => $tabId,
            'alat_standar'          => $alatStandarString,
            'setting_suhu_count'    => count($settingSuhuData),
            'repeatability_count'   => count($repeatabilityData),
        ]);

        \Log::info('🎉 storeSurfacePlate COMPLETED');
        return $head;

    } catch (\Exception $e) {
        \Log::error('💥 Error storing Surface Plate data:', [
            'message'          => $e->getMessage(),
            'file'             => $e->getFile(),
            'line'             => $e->getLine(),
            'calibration_id'   => $calibration->id ?? 'N/A',
            'tab_id'           => $tabId ?? 'N/A',
            'trace'            => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
private function updateSurfacePlate($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateSurfacePlate', [
            'calibration_id' => $calibration->id,
            'new_certificate_id' => $newCertificateId
        ]);

        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;

        $namaAlatDariRequest = $request->nama_alat ?? $request->nama_alat_final ?? $calibration->namaAlat;
        $originalNamaAlat = $calibration->namaAlat;

        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->namaAlat,
            'current_certificate_id' => $calibration->certificate_id
        ]);

        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;

            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $calibration->certificate_id,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;

            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $calibration->certificate_id,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }

        // ============================================
        // 1. PROSES ALAT STANDAR
        // ============================================
        $alatStandar = $request->alat_standar_text ?? [];
        \Log::info('🔧 Alat standar:', ['alat_standar' => $alatStandar]);

        // ============================================
        // 2. AMBIL DATA HEAD LAMA (UNTUK GAMBAR LAMA)
        // ============================================
        $oldHead = HeadSurfacePlate::where('calibration_id', $calibration->id)->first();
        $oldImagePath = $oldHead ? $oldHead->keterangan : null;

        // ============================================
        // 3. PROSES GAMBAR CANVAS
        // ============================================
        // Cek kedua input: keterangan_gambar (halaman edit) atau keterangan (halaman input)
        $keteranganGambar = $request->input('keterangan_gambar')
                         ?? $request->input('keterangan');
        
        $keteranganText = '';
        $isNewImageUploaded = false;

        if ($keteranganGambar && strpos($keteranganGambar, 'data:image') === 0) {
            $data = substr($keteranganGambar, strpos($keteranganGambar, ',') + 1);
            $decodedData = base64_decode($data, true);

            if (strlen($decodedData) > 500) {
                \Log::info('🖼️ Valid canvas image detected! Size: ' . strlen($decodedData) . ' bytes');
                $isNewImageUploaded = true;

                $canvasImagePath = $this->saveCanvasImage($keteranganGambar, $calibration->id);

                if ($canvasImagePath) {
                    $keteranganText = $canvasImagePath;
                    \Log::info('✅ New canvas image saved. Path: ' . $canvasImagePath);
                } else {
                    $oldHead = HeadSurfacePlate::where('calibration_id', $calibration->id)->first();
                    $keteranganText = $oldHead ? $oldHead->keterangan : '';
                    \Log::warning('⚠️ Failed to save new image, keeping old image');
                    $isNewImageUploaded = false;
                }
            } else {
                \Log::info('📝 Canvas empty, skipping image save');
                $oldHead = HeadSurfacePlate::where('calibration_id', $calibration->id)->first();
                $keteranganText = $oldHead ? $oldHead->keterangan : '';
            }
        } else {
            $oldHead = HeadSurfacePlate::where('calibration_id', $calibration->id)->first();
            $keteranganText = $oldHead ? $oldHead->keterangan : '';
            \Log::info('📝 No new image, keeping existing image: ' . ($keteranganText ?: '(empty)'));
        }

        // ============================================
        // 4. UPDATE ATAU CREATE HEAD SURFACE PLATE
        // ============================================
        $head = HeadSurfacePlate::where('calibration_id', $calibration->id)->first();

        $headData = [
            'standard' => $alatStandar,
            'calibrationMethod' => 'PAS-IK1102-53',
            'keterangan' => $keteranganText,
        ];

        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headData['certificate_id'] = $certificateIdBaru;
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headData['certificate_id'] = $newCertificateId;
        }

        if ($head) {
            $head->update($headData);
            \Log::info('✅ Head Surface Plate updated:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id ?? null,
                'keterangan_saved' => $keteranganText,
                'is_new_image' => $isNewImageUploaded
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            $headData['certificate_id'] = $certificateIdBaru ?? $newCertificateId ?? $calibration->certificate_id;
            $head = HeadSurfacePlate::create($headData);
            \Log::info('✅ Head Surface Plate created:', [
                'head_id' => $head->id,
                'certificate_id' => $head->certificate_id,
                'keterangan_saved' => $keteranganText
            ]);
        }

        // ============================================
        // 5. UPDATE DETAIL SURFACE PLATE
        // ============================================
        \Log::info('📊 Updating detail measurements for Surface Plate...');

        // Hapus data detail lama
        $deletedDetails = DetailSurfacePlate::where('calibration_id', $calibration->id)->delete();
        \Log::info("🗑️ Deleted {$deletedDetails} old detail records");

        $detailData = [
            'calibration_id' => $calibration->id,
        ];

        // ============================================
        // 5A. SETTING SUHU — 13 baris × 10 kolom (a1_1 s/d a13_10)
        // ============================================
        for ($row = 1; $row <= 13; $row++) {
            for ($col = 1; $col <= 10; $col++) {
                $key = "a{$row}_{$col}";
                $value = $request->input($key, null);
                $detailData[$key] = $value;
            }
        }

        \Log::info('🌡️ Setting suhu collected:', ['count' => 130]);

        // ============================================
        // 5B. REPEATABILITY MATRIX — TBL1 (Group A)
        //     10 baris × 2 kolom: a1_1_tbl1 .. a10_2_tbl1
        // ============================================
        for ($i = 1; $i <= 10; $i++) {
            $detailData["a{$i}_1_tbl1"] = $request->input("a{$i}_1_tbl1", null);
            $detailData["a{$i}_2_tbl1"] = $request->input("a{$i}_2_tbl1", null);
        }

        // ============================================
        // 5C. REPEATABILITY MATRIX — TBL2 s/d TBL12 (Group B–L)
        //     Nama input di HTML: a1_1_tblX, a1_2_tblX,
        //                         {letter}1_1_tblX, {letter}1_2_tblX,
        //                         ...
        //                         {letter}10_1_tblX, {letter}10_2_tblX
        // ============================================
        $groups = [
            2  => 'b',
            3  => 'c',
            4  => 'd',
            5  => 'e',
            6  => 'f',
            7  => 'g',
            8  => 'h',
            9  => 'i',
            10 => 'j',
            11 => 'k',   // Group K
            12 => 'l',   // Group L
        ];
        
        foreach ($groups as $tableNum => $letter) {
            // Kolom pertama — a1_1_tblX / a1_2_tblX
            $detailData["a1_1_tbl{$tableNum}"] = $request->input("a1_1_tbl{$tableNum}", null);
            $detailData["a1_2_tbl{$tableNum}"] = $request->input("a1_2_tbl{$tableNum}", null);
        
            // Kolom 2..11 → baris 1..10: {letter}1_1_tblX, {letter}2_1_tblX, ..., {letter}10_1_tblX
            for ($i = 1; $i <= 10; $i++) {
                $detailData["{$letter}{$i}_1_tbl{$tableNum}"] = $request->input("{$letter}{$i}_1_tbl{$tableNum}", null);
                $detailData["{$letter}{$i}_2_tbl{$tableNum}"] = $request->input("{$letter}{$i}_2_tbl{$tableNum}", null);
            }
        }

        \Log::info('📊 Detail data collected:', [
            'setting_suhu_count' => 130,
            'repeatability_count' => count($detailData) - 1, // -1 untuk calibration_id
            'total_fields' => count($detailData),
        ]);

        // ============================================
        // 6. SIMPAN KE DATABASE
        // ============================================
        $detail = DetailSurfacePlate::create($detailData);
        \Log::info('✅ Detail saved, record ID: ' . $detail->id);

        // ============================================
        // 7. UPDATE CALIBRATION
        // ============================================
        $updateData = [];

        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk calibration: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $updateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk calibration dari parameter: {$newCertificateId}");
        }

        if ($request->filled('nama_alat_final') && $request->nama_alat_final != $calibration->namaAlat) {
            $updateData['namaAlat'] = $request->nama_alat_final;
        } elseif ($request->filled('nama_alat') && $request->nama_alat != $calibration->namaAlat) {
            $updateData['namaAlat'] = $request->nama_alat;
        }

        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }

        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }

        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated:', array_keys($updateData));
        }

        // ============================================
        // 8. VERIFIKASI FINAL
        // ============================================
        $savedHead = HeadSurfacePlate::where('calibration_id', $calibration->id)->first();

        \Log::info('📋 UPDATE SUMMARY (Surface Plate):', [
            'calibration_id' => $calibration->id,
            'certificate_id_calibration' => $calibration->certificate_id,
            'certificate_id_head' => $savedHead->certificate_id ?? null,
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'head_id' => $head->id,
            'detail_records' => DetailSurfacePlate::where('calibration_id', $calibration->id)->count(),
            'is_new_image_uploaded' => $isNewImageUploaded
        ]);

        \Log::info('🎉 updateSurfacePlate COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateSurfacePlate:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);

        throw new \Exception("Gagal mengupdate data Surface Plate: " . $e->getMessage());
    }
}

private function saveCanvasImage($canvasData, $calibrationId)
{
    try {
        \Log::info('💾 Starting saveCanvasImage...');
        
        // ============================================
        // 1. VALIDASI DAN CEK APAKAH GAMBAR VALID (BUKAN KOSONG)
        // ============================================
        if (empty($canvasData) || !is_string($canvasData)) {
            \Log::warning('⚠️ Canvas data is empty or not string');
            return null;
        }
        
        \Log::info('📏 Canvas data length: ' . strlen($canvasData));
        
        // Validasi base64 image
        if (!preg_match('/^data:image\/(png|jpeg|jpg|gif);base64,/', $canvasData)) {
            \Log::warning('⚠️ Not a valid base64 image data');
            return null;
        }
        
        // Decode base64 image
        preg_match('/^data:image\/(\w+);base64,/', $canvasData, $matches);
        $type = strtolower($matches[1]);
        \Log::info('📸 Image type detected: ' . $type);
        
        $data = substr($canvasData, strpos($canvasData, ',') + 1);
        $decodedData = base64_decode($data, true);
        
        if ($decodedData === false) {
            \Log::error('❌ base64_decode failed');
            return null;
        }
        
        \Log::info('✅ Base64 decoded successfully, size: ' . strlen($decodedData) . ' bytes');
        
        // ============================================
        // 2. CEK APAKAH GAMBAR KOSONG (PUTIH SEMUA)
        // ============================================
        // Cek ukuran decoded data - gambar kosong biasanya sangat kecil (< 500 bytes)
        if (strlen($decodedData) < 500) {
            \Log::info('📝 Image too small (' . strlen($decodedData) . ' bytes), likely empty canvas, NOT saving');
            return null;
        }
        
        // ============================================
        // 3. HAPUS GAMBAR LAMA (HANYA JIKA GAMBAR VALID)
        // ============================================
        $pattern = public_path('img_SurfacePlate/surface_plate_' . $calibrationId . '_*.png');
        $oldFiles = glob($pattern);
        
        \Log::info('📁 Mencari gambar lama dengan pattern: ' . $pattern);
        \Log::info('📁 Ditemukan ' . count($oldFiles) . ' file gambar lama');
        
        foreach ($oldFiles as $oldFile) {
            if (file_exists($oldFile)) {
                if (@unlink($oldFile)) {
                    \Log::info('🗑️ Berhasil hapus gambar lama: ' . basename($oldFile));
                } else {
                    \Log::warning('⚠️ Gagal hapus gambar lama: ' . basename($oldFile));
                }
            }
        }
        
        // ============================================
        // 4. SIMPAN GAMBAR BARU
        // ============================================
        $filename = 'surface_plate_' . $calibrationId . '_' . time() . '.' . $type;
        
        $directory = public_path('img_SurfacePlate');
        if (!file_exists($directory)) {
            \Log::info('📁 Creating directory: ' . $directory);
            if (!mkdir($directory, 0755, true)) {
                \Log::error('❌ Failed to create directory: ' . $directory);
                return null;
            }
        }
        
        if (!is_writable($directory)) {
            \Log::error('❌ Directory not writable: ' . $directory);
            return null;
        }
        
        $fullPath = $directory . '/' . $filename;
        $bytesWritten = file_put_contents($fullPath, $decodedData);
        
        if ($bytesWritten === false) {
            \Log::error('❌ Failed to write file to: ' . $fullPath);
            return null;
        }
        
        $webPath = 'img_SurfacePlate/' . $filename;
        
        \Log::info('🎉 Canvas image saved successfully!', [
            'filename' => $filename,
            'web_path' => $webPath,
            'size' => $this->formatBytes($bytesWritten)
        ]);
        
        return $webPath;
        
    } catch (\Exception $e) {
        \Log::error('💥 Error in saveCanvasImage:', [
            'message' => $e->getMessage(),
            'trace' => $e->getTraceAsString()
        ]);
        return null;
    }
}

private function storeAbrationTester($request, $calibration, $certificateId)
{
    try {
        \Log::info('🚀 START storeAbrationTester - Abration Tester Calibration');
        
        // ==========================================================
        // FUNGSI BANTU MENCARI NILAI
        // ==========================================================
        $getRequestValue = function($baseKey, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            
            // Format tanpa prefix
            $possibleKeys[] = $baseKey;
            $possibleKeys[] = $baseKey . '[]';
            
            // Dengan additional params
            if (!empty($additionalParams)) {
                foreach ($additionalParams as $param) {
                    $possibleKeys[] = "{$baseKey}_{$param}";
                    $possibleKeys[] = "{$baseKey}_{$param}[]";
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '') {
                    \Log::debug("Found value for key: {$key}");
                    return $value;
                }
            }
            
            return null;
        };
        
        $getArrayValue = function($baseKey, $additionalParams = []) use ($request) {
            $possibleKeys = [];
            
            $possibleKeys[] = $baseKey;
            $possibleKeys[] = $baseKey . '[]';
            
            if (!empty($additionalParams)) {
                foreach ($additionalParams as $param) {
                    $possibleKeys[] = "{$baseKey}_{$param}";
                    $possibleKeys[] = "{$baseKey}_{$param}[]";
                }
            }
            
            $possibleKeys = array_unique($possibleKeys);
            
            foreach ($possibleKeys as $key) {
                $value = $request->input($key);
                if ($value !== null && !empty($value)) {
                    if (is_array($value)) {
                        return array_filter($value, function($item) {
                            return $item !== null && $item !== '';
                        });
                    }
                    return [$value];
                }
            }
            
            return [];
        };
        
        // AMBIL ALAT STANDAR
        $alatStandar = $getArrayValue('alat_standar');
        if (!is_array($alatStandar)) {
            $alatStandar = [$alatStandar];
        }
        $alatStandar = array_filter($alatStandar);
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        // AMBIL CATATAN
        $catatan = $getRequestValue('catatan');
        
        // AMBIL CALIBRATED BY DAN VERIFIED BY
        $calibratedBy = $getRequestValue('calibrated_by');
        if (empty($calibratedBy)) {
            $calibratedBy = $getRequestValue('calibratedBy');
        }
        $verifiedBy = $getRequestValue('verified_by');
        if (empty($verifiedBy)) {
            $verifiedBy = $getRequestValue('verifiedBy');
        }
        
        \Log::info('📝 Data Abration Tester:', [
            'alat_standar' => $alatStandarString,
            'catatan' => $catatan,
            'calibratedBy' => $calibratedBy,
            'verifiedBy' => $verifiedBy
        ]);
        
        // ==========================================================
        // SIMPAN HEAD ABRATION TESTER (TANPA form_index)
        // ==========================================================
        $head = HeadAbrationTester::updateOrCreate(
            ['calibration_id' => $calibration->id],
            [
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'calibrationMethod' => 'PAS-IK1102-52, PAS-IK1102-45',
                'catatan' => $catatan,
                'calibrated_by' => $calibratedBy,
                'verified_by' => $verifiedBy,
            ]
        );
        
        \Log::info('✅ HeadAbrationTester saved', ['head_id' => $head->id]);
        
        // ==========================================================
        // AMBIL DATA DETAIL (ARRAY UNTUK 10 BARIS)
        // ==========================================================
        $titikUkur = $getArrayValue('titikUkur');
        $nominalRPM = $getArrayValue('nominalRPM');
        $resolusi = $getArrayValue('resolusi_alat');
        
        // Data STD untuk 5 pengulangan
        $STD1 = $getArrayValue('STD1');
        $STD2 = $getArrayValue('STD2');
        $STD3 = $getArrayValue('STD3');
        $STD4 = $getArrayValue('STD4');
        $STD5 = $getArrayValue('STD5');
        
        // Data STD terpisah (menit, second, milisecond)
        $STDm1 = $getArrayValue('STDm1');
        $STDs1 = $getArrayValue('STDs1');
        $STDms1 = $getArrayValue('STDms1');
        $STDm2 = $getArrayValue('STDm2');
        $STDs2 = $getArrayValue('STDs2');
        $STDms2 = $getArrayValue('STDms2');
        $STDm3 = $getArrayValue('STDm3');
        $STDs3 = $getArrayValue('STDs3');
        $STDms3 = $getArrayValue('STDms3');
        $STDm4 = $getArrayValue('STDm4');
        $STDs4 = $getArrayValue('STDs4');
        $STDms4 = $getArrayValue('STDms4');
        $STDm5 = $getArrayValue('STDm5');
        $STDs5 = $getArrayValue('STDs5');
        $STDms5 = $getArrayValue('STDms5');
        
        // Data UUT (10 baris)
        $UUTm1 = $getArrayValue('UUTm1');
        $UUTs1 = $getArrayValue('UUTs1');
        $UUTms1 = $getArrayValue('UUTms1');
        $UUTm2 = $getArrayValue('UUTm2');
        $UUTs2 = $getArrayValue('UUTs2');
        $UUTms2 = $getArrayValue('UUTms2');
        $UUTm3 = $getArrayValue('UUTm3');
        $UUTs3 = $getArrayValue('UUTs3');
        $UUTms3 = $getArrayValue('UUTms3');
        $UUTm4 = $getArrayValue('UUTm4');
        $UUTs4 = $getArrayValue('UUTs4');
        $UUTms4 = $getArrayValue('UUTms4');
        $UUTm5 = $getArrayValue('UUTm5');
        $UUTs5 = $getArrayValue('UUTs5');
        $UUTms5 = $getArrayValue('UUTms5');
        
        \Log::info('📊 Data Abration Tester Detail:', [
            'nominalRPM_count' => count($nominalRPM),
            'resolusi_count' => count($resolusi),
            'titikUkur_count' => count($titikUkur),
        ]);
        
        // ==========================================================
        // HAPUS DETAIL LAMA
        // ==========================================================
        DetailAbrationTester::where('calibration_id', $calibration->id)->delete();
        
        // ==========================================================
        // LOOP UNTUK 10 TITIK UKUR
        // ==========================================================
        $maxRows = max(count($titikUkur), count($nominalRPM), count($resolusi));
        $maxRows = min($maxRows, 10); // Maksimal 10 baris
        
        for ($i = 0; $i < $maxRows; $i++) {
            $detailData = [
                'calibration_id' => $calibration->id,
                'head_abration_tester_id' => $head->id,
                'nominalRPM' => $nominalRPM[$i] ?? null,
                'resolusi' => $resolusi[$i] ?? null,
                'titikUkur' => $titikUkur[$i] ?? null,
                // STD gabungan
                'STD1' => $STD1[$i] ?? null,
                'STD2' => $STD2[$i] ?? null,
                'STD3' => $STD3[$i] ?? null,
                'STD4' => $STD4[$i] ?? null,
                'STD5' => $STD5[$i] ?? null,
                // STD terpisah
                'STDm1' => $STDm1[$i] ?? null,
                'STDs1' => $STDs1[$i] ?? null,
                'STDms1' => $STDms1[$i] ?? null,
                'STDm2' => $STDm2[$i] ?? null,
                'STDs2' => $STDs2[$i] ?? null,
                'STDms2' => $STDms2[$i] ?? null,
                'STDm3' => $STDm3[$i] ?? null,
                'STDs3' => $STDs3[$i] ?? null,
                'STDms3' => $STDms3[$i] ?? null,
                'STDm4' => $STDm4[$i] ?? null,
                'STDs4' => $STDs4[$i] ?? null,
                'STDms4' => $STDms4[$i] ?? null,
                'STDm5' => $STDm5[$i] ?? null,
                'STDs5' => $STDs5[$i] ?? null,
                'STDms5' => $STDms5[$i] ?? null,
                // UUT
                'UUTm1' => $UUTm1[$i] ?? null,
                'UUTs1' => $UUTs1[$i] ?? null,
                'UUTms1' => $UUTms1[$i] ?? null,
                'UUTm2' => $UUTm2[$i] ?? null,
                'UUTs2' => $UUTs2[$i] ?? null,
                'UUTms2' => $UUTms2[$i] ?? null,
                'UUTm3' => $UUTm3[$i] ?? null,
                'UUTs3' => $UUTs3[$i] ?? null,
                'UUTms3' => $UUTms3[$i] ?? null,
                'UUTm4' => $UUTm4[$i] ?? null,
                'UUTs4' => $UUTs4[$i] ?? null,
                'UUTms4' => $UUTms4[$i] ?? null,
                'UUTm5' => $UUTm5[$i] ?? null,
                'UUTs5' => $UUTs5[$i] ?? null,
                'UUTms5' => $UUTms5[$i] ?? null,
            ];
            
            DetailAbrationTester::create($detailData);
            \Log::debug("✅ Detail saved for titik ukur {$i}", [
                'nominalRPM' => $detailData['nominalRPM'],
                'resolusi' => $detailData['resolusi']
            ]);
        }
        
        \Log::info('✅ storeAbrationTester completed', [
            'head_id' => $head->id,
            'detail_count' => $maxRows
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 storeAbrationTester FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

private function updateAbrationTester($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 START updateAbrationTester - Abration Tester Calibration', [
            'calibration_id' => $calibration->id,
            'new_certificate_id' => $newCertificateId
        ]);
        
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID DI HEAD
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->nama_alat_final ?? $request->nama_alat ?? $calibration->nama_alat;
        
        // Ambil head abration tester untuk cek certificate_id
        $headAbrationTester = HeadAbrationTester::where('calibration_id', $calibration->id)->first();
        $currentCertificateId = $headAbrationTester->certificate_id ?? null;
        
        // Ambil nama alat asli dari database
        $originalCalibration = Calibration::find($calibration->id);
        $originalNamaAlat = $originalCalibration->nama_alat;
        
        \Log::info('🔍 CEK NAMA ALAT & CERTIFICATE:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'original_nama_alat' => $originalNamaAlat,
            'current_nama_alat' => $calibration->nama_alat,
            'certificate_id_lama_di_head' => $currentCertificateId
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $originalNamaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $originalNamaAlat,
                'new_nama' => $namaAlatDariRequest,
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } 
        // Jika certificate_id di head kosong
        elseif (empty($currentCertificateId)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong):', [
                'old_certificate_id' => $currentCertificateId,
                'new_certificate_id' => $certificateIdBaru
            ]);
        }
        
        // ==================================================================
        // 1. UPDATE HEAD ABRATION TESTER
        // ==================================================================
        $alatStandar = $request->alat_standar ?? [];
        $alatStandarString = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
        
        // Data untuk update head
        $headUpdateData = [
            'standard' => $alatStandarString,
            'calibrationMethod' => $request->calibrationMethod ?? 'Metode Kalibrasi Abration Tester',
            'catatan' => $request->catatan ?? null,
        ];
        
        // UPDATE CERTIFICATE ID DI HEAD jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $headUpdateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk head: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $headUpdateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk head dari parameter: {$newCertificateId}");
        }
        
        if ($head = $calibration->headAbrationTester) {
            $head->update($headUpdateData);
            \Log::info('✅ HeadAbrationTester updated:', $headUpdateData);
        } else {
            // Jika head belum ada, buat baru
            $head = HeadAbrationTester::create(array_merge([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateIdBaru ?? $calibration->certificate_id,
            ], $headUpdateData));
            \Log::info('➕ HeadAbrationTester created baru:', ['head_id' => $head->id]);
        }

        // ==================================================================
        // 2. UPDATE DETAIL ABRATION TESTER (DELETE & RECREATE 10 BARIS)
        // ==================================================================
        // Hapus data detail lama
        DetailAbrationTester::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Deleted old detail records');
        
        // Ambil data dari form (ARRAY)
        $titikUkur = $request->titikUkur ?? [];
        $nominalRPM = $request->nominalRPM ?? [];
        $resolusi = $request->resolusi_alat ?? [];
        
        // Data STD (array)
        $STD1 = $request->STD1 ?? [];
        $STD2 = $request->STD2 ?? [];
        $STD3 = $request->STD3 ?? [];
        $STD4 = $request->STD4 ?? [];
        $STD5 = $request->STD5 ?? [];
        
        // Data STD terpisah
        $STDm1 = $request->STDm1 ?? [];
        $STDs1 = $request->STDs1 ?? [];
        $STDms1 = $request->STDms1 ?? [];
        $STDm2 = $request->STDm2 ?? [];
        $STDs2 = $request->STDs2 ?? [];
        $STDms2 = $request->STDms2 ?? [];
        $STDm3 = $request->STDm3 ?? [];
        $STDs3 = $request->STDs3 ?? [];
        $STDms3 = $request->STDms3 ?? [];
        $STDm4 = $request->STDm4 ?? [];
        $STDs4 = $request->STDs4 ?? [];
        $STDms4 = $request->STDms4 ?? [];
        $STDm5 = $request->STDm5 ?? [];
        $STDs5 = $request->STDs5 ?? [];
        $STDms5 = $request->STDms5 ?? [];
        
        // Data UUT
        $UUTm1 = $request->UUTm1 ?? [];
        $UUTs1 = $request->UUTs1 ?? [];
        $UUTms1 = $request->UUTms1 ?? [];
        $UUTm2 = $request->UUTm2 ?? [];
        $UUTs2 = $request->UUTs2 ?? [];
        $UUTms2 = $request->UUTms2 ?? [];
        $UUTm3 = $request->UUTm3 ?? [];
        $UUTs3 = $request->UUTs3 ?? [];
        $UUTms3 = $request->UUTms3 ?? [];
        $UUTm4 = $request->UUTm4 ?? [];
        $UUTs4 = $request->UUTs4 ?? [];
        $UUTms4 = $request->UUTms4 ?? [];
        $UUTm5 = $request->UUTm5 ?? [];
        $UUTs5 = $request->UUTs5 ?? [];
        $UUTms5 = $request->UUTms5 ?? [];
        
        $detailCount = 0;
        
        // Loop untuk 10 titik ukur
        for ($i = 0; $i < 10; $i++) {
            $detailData = [
                'calibration_id' => $calibration->id,
                'head_abration_tester_id' => $head->id,
                'nominalRPM' => $nominalRPM[$i] ?? null,
                'resolusi' => $resolusi[$i] ?? null,
                'titikUkur' => $titikUkur[$i] ?? null,
                // STD gabungan
                'STD1' => $STD1[$i] ?? null,
                'STD2' => $STD2[$i] ?? null,
                'STD3' => $STD3[$i] ?? null,
                'STD4' => $STD4[$i] ?? null,
                'STD5' => $STD5[$i] ?? null,
                // STD terpisah
                'STDm1' => $STDm1[$i] ?? null,
                'STDs1' => $STDs1[$i] ?? null,
                'STDms1' => $STDms1[$i] ?? null,
                'STDm2' => $STDm2[$i] ?? null,
                'STDs2' => $STDs2[$i] ?? null,
                'STDms2' => $STDms2[$i] ?? null,
                'STDm3' => $STDm3[$i] ?? null,
                'STDs3' => $STDs3[$i] ?? null,
                'STDms3' => $STDms3[$i] ?? null,
                'STDm4' => $STDm4[$i] ?? null,
                'STDs4' => $STDs4[$i] ?? null,
                'STDms4' => $STDms4[$i] ?? null,
                'STDm5' => $STDm5[$i] ?? null,
                'STDs5' => $STDs5[$i] ?? null,
                'STDms5' => $STDms5[$i] ?? null,
                // UUT
                'UUTm1' => $UUTm1[$i] ?? null,
                'UUTs1' => $UUTs1[$i] ?? null,
                'UUTms1' => $UUTms1[$i] ?? null,
                'UUTm2' => $UUTm2[$i] ?? null,
                'UUTs2' => $UUTs2[$i] ?? null,
                'UUTms2' => $UUTms2[$i] ?? null,
                'UUTm3' => $UUTm3[$i] ?? null,
                'UUTs3' => $UUTs3[$i] ?? null,
                'UUTms3' => $UUTms3[$i] ?? null,
                'UUTm4' => $UUTm4[$i] ?? null,
                'UUTs4' => $UUTs4[$i] ?? null,
                'UUTms4' => $UUTms4[$i] ?? null,
                'UUTm5' => $UUTm5[$i] ?? null,
                'UUTs5' => $UUTs5[$i] ?? null,
                'UUTms5' => $UUTms5[$i] ?? null,
            ];
            
            DetailAbrationTester::create($detailData);
            $detailCount++;
        }
        
        \Log::info('✅ DetailAbrationTester updated:', ['total_records' => $detailCount]);

        // ==================================================================
        // 3. UPDATE CALIBRATION (HANYA YANG PERLU)
        // ==================================================================
        $updateData = [];
        
        // Update certificate_id di calibration jika ada perubahan
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $updateData['certificate_id'] = $certificateIdBaru;
            \Log::info("📝 Setting certificate_id untuk calibration: {$certificateIdBaru}");
        } elseif ($newCertificateId && !$certificateIdUpdated) {
            $updateData['certificate_id'] = $newCertificateId;
            \Log::info("📝 Setting certificate_id untuk calibration dari parameter: {$newCertificateId}");
        }
        
        // Update nama alat jika berubah (untuk keperluan generate certificate ID)
        if ($request->filled('nama_alat') && $request->nama_alat != $calibration->nama_alat) {
            $updateData['nama_alat'] = $request->nama_alat;
        }
        
        // Update calibrated_by dan verified_by
        if ($request->filled('calibrated_by')) {
            $updateData['calibrated_by'] = $request->calibrated_by;
        }
        
        if ($request->filled('verified_by')) {
            $updateData['verified_by'] = $request->verified_by;
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('📝 Calibration updated', array_keys($updateData));
        }

        // ==================================================================
        // 4. LOG HASIL AKHIR
        // ==================================================================
        $finalDetailCount = DetailAbrationTester::where('calibration_id', $calibration->id)->count();
        
        // Ambil head terbaru untuk cek certificate_id
        $finalHead = HeadAbrationTester::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📋 UPDATE SUMMARY (Abration Tester):', [
            'calibration_id' => $calibration->id,
            'certificate_id_calibration' => $calibration->certificate_id,
            'certificate_id_head' => $finalHead->certificate_id ?? null,
            'certificate_id_updated' => $certificateIdUpdated,
            'new_certificate_id' => $certificateIdBaru,
            'detail_records' => $finalDetailCount,
            'standard' => $alatStandarString,
            'calibrated_by' => $calibration->calibrated_by ?? null,
            'verified_by' => $calibration->verified_by ?? null,
        ]);

        \Log::info('🎉 updateAbrationTester COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateAbrationTester:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        throw $e;
    }
}

private function storeHeightGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeHeightGauge');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 storeHeightGauge called with tab_id:', ['tab_id' => $tabId]);
        
        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI HIDDEN INPUT
        // ==================================================================
        $alatStandarString = $this->getRequestValue($request, 'alat_standar_teks', $tabId);
        if (empty($alatStandarString)) {
            $alatStandarString = 'Master Check, Mitutoyo, 515-742, 1100033';
        }
        
        \Log::info('🔧 Alat standar for Height Gauge:', [
            'alat_standar_teks' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. SIMPAN KE HEAD HEIGHT GAUGE
        // ==================================================================
        $satuanTitikUkur = $this->getRequestValue($request, 'satuan_titik_ukur', $tabId);
        if (empty($satuanTitikUkur)) {
            $satuanTitikUkur = 'mm';
        }
        
        $calibrationMethod = $this->getRequestValue($request, 'metode_kalibrasi', $tabId);
        if (empty($calibrationMethod)) {
            $calibrationMethod = 'PAS-IK1102-10 (JIS B 7517:2018 JMA/JSA)';
        }
        
        $head = HeadHeightGauge::create([
            'calibration_id' => $calibration->id,
            'certificate_id' => $certificateId,
            'standard' => $alatStandarString,
            'calibrationMethod' => $calibrationMethod,
            'satuan_titik_ukur' => $satuanTitikUkur,
        ]);

        \Log::info('✅ HeadHeightGauge saved:', [
            'head_id' => $head->id,
            'satuan_titik_ukur' => $satuanTitikUkur,
            'calibrationMethod' => $calibrationMethod
        ]);

        // ==================================================================
        // 3. SIMPAN DETAIL HEIGHT GAUGE (NILAI NOMINAL + 5 PENUNJUKAN ALAT)
        // ==================================================================
        \Log::info('📊 Saving Height Gauge detail measurements...');
        
        $nominalValues = $request->input('nominal', []);
        $alat1Values = $request->input('alat_1', []);
        $alat2Values = $request->input('alat_2', []);
        $alat3Values = $request->input('alat_3', []);
        $alat4Values = $request->input('alat_4', []);
        $alat5Values = $request->input('alat_5', []);
        
        $detailCount = 0;
        
        // Loop untuk setiap baris data
        for ($i = 0; $i < count($nominalValues); $i++) {
            $nominalValue = $nominalValues[$i] ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($nominalValue) || 
                       !empty($alat1Values[$i] ?? '') || 
                       !empty($alat2Values[$i] ?? '') || 
                       !empty($alat3Values[$i] ?? '') || 
                       !empty($alat4Values[$i] ?? '') || 
                       !empty($alat5Values[$i] ?? '');
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'nominal_value' => $nominalValue,
                    'alat_1' => $alat1Values[$i] ?? null,
                    'alat_2' => $alat2Values[$i] ?? null,
                    'alat_3' => $alat3Values[$i] ?? null,
                    'alat_4' => $alat4Values[$i] ?? null,
                    'alat_5' => $alat5Values[$i] ?? null,
                ];
                
                DetailHeightGauge::create($detailData);
                $detailCount++;
                \Log::debug("✅ Detail saved for row {$i}: nominal = {$nominalValue}");
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Height Gauge");

        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA NAMA TTD
        // ==================================================================
        $updateData = [];
        
        // Nama untuk TTD
        $calibratedBy = $this->getRequestValue($request, 'calibrated_by', $tabId);
        if ($calibratedBy) {
            $updateData['calibrated_by'] = $calibratedBy;
            \Log::info('📝 Nama dikalibrasi:', ['nama' => $calibratedBy]);
        } else {
            // Default dari user yang login
            $updateData['calibrated_by'] = auth()->user()->nama ?? 'System';
        }
        
        $verifiedBy = $this->getRequestValue($request, 'verified_by', $tabId);
        if ($verifiedBy) {
            $updateData['verified_by'] = $verifiedBy;
            \Log::info('📝 Nama diperiksa:', ['nama' => $verifiedBy]);
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with TTD names');
        }

        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailHeightGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 STORE SUMMARY (Height Gauge):', [
            'calibration_id' => $calibration->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'total_nominal_points' => count($nominalValues)
        ]);

        \Log::info('🎉 storeHeightGauge COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeHeightGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        // Rollback sederhana
        if (isset($head) && $head->id) {
            try {
                DetailHeightGauge::where('calibration_id', $calibration->id)->delete();
                $head->delete();
            } catch (\Exception $rollbackError) {
                \Log::error('💥 Rollback failed:', ['error' => $rollbackError->getMessage()]);
            }
        }
        
        throw new \Exception("Gagal menyimpan data Height Gauge: " . $e->getMessage());
    }
}

private function updateHeightGauge($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START updateHeightGauge');
        
        // Ambil tabId dari request jika tidak dikirim
        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }
        
        \Log::info('📌 updateHeightGauge called with tab_id:', ['tab_id' => $tabId]);

        // ==================================================================
        // 1. PROSES ALAT STANDAR - DARI HIDDEN INPUT
        // ==================================================================
        $alatStandarString = $this->getRequestValue($request, 'alat_standar_teks', $tabId);
        if (empty($alatStandarString)) {
            $alatStandarString = 'Master Check, Mitutoyo, 515-742, 1100033';
        }
        
        \Log::info('🔧 Alat standar for Height Gauge:', [
            'alat_standar_teks' => $alatStandarString,
            'tab_id' => $tabId
        ]);

        // ==================================================================
        // 2. UPDATE / CREATE HEAD HEIGHT GAUGE
        // ==================================================================
        $satuanTitikUkur = $this->getRequestValue($request, 'satuan_titik_ukur', $tabId);
        if (empty($satuanTitikUkur)) {
            $satuanTitikUkur = 'mm';
        }
        
        $calibrationMethod = $this->getRequestValue($request, 'metode_kalibrasi', $tabId);
        if (empty($calibrationMethod)) {
            $calibrationMethod = 'PAS-IK1102-10 (JIS B 7517:2018 JMA/JSA)';
        }
        
        $head = HeadHeightGauge::updateOrCreate(
            ['calibration_id' => $calibration->id],
            [
                'certificate_id' => $certificateId,
                'standard' => $alatStandarString,
                'calibrationMethod' => $calibrationMethod,
                'satuan_titik_ukur' => $satuanTitikUkur,
            ]
        );

        \Log::info('✅ HeadHeightGauge updated:', [
            'head_id' => $head->id,
            'satuan_titik_ukur' => $satuanTitikUkur,
            'calibrationMethod' => $calibrationMethod
        ]);

        // ==================================================================
        // 3. UPDATE DETAIL HEIGHT GAUGE (NILAI NOMINAL + 5 PENUNJUKAN ALAT)
        // ==================================================================
        \Log::info('📊 Updating Height Gauge detail measurements...');
        
        // Hapus semua detail lama
        DetailHeightGauge::where('calibration_id', $calibration->id)->delete();
        
        // Ambil detail_ids yang ada (untuk referensi)
        $detailIds = $request->input('detail_ids', []);
        
        // Cari semua input yang dimulai dengan 'nominal_'
        $nominalInputs = [];
        $alatInputs = [];
        
        // Kumpulkan semua input dari request
        foreach ($request->all() as $key => $value) {
            if (preg_match('/^nominal_(\d+)$/', $key, $matches)) {
                $rowNumber = $matches[1];
                $nominalInputs[$rowNumber] = $value;
            }
            
            if (preg_match('/^alat_(\d+)_(\d+)$/', $key, $matches)) {
                $alatNumber = $matches[1]; // 1-5
                $rowNumber = $matches[2];
                if (!isset($alatInputs[$rowNumber])) {
                    $alatInputs[$rowNumber] = [];
                }
                $alatInputs[$rowNumber]["alat_{$alatNumber}"] = $value;
            }
        }
        
        // Tentukan jumlah baris maksimal
        $totalRows = max(count($nominalInputs), count($alatInputs));
        if ($totalRows == 0) {
            // Default 13 baris untuk Height Gauge
            $totalRows = 13;
        }
        
        $detailCount = 0;
        
        // Loop untuk setiap baris data (1 sampai totalRows)
        for ($i = 1; $i <= $totalRows; $i++) {
            $rowNumber = $i;
            
            // Ambil nilai nominal
            $nominalValue = $nominalInputs[$rowNumber] ?? null;
            
            // Ambil nilai alat 1-5
            $alat1 = $alatInputs[$rowNumber]['alat_1'] ?? null;
            $alat2 = $alatInputs[$rowNumber]['alat_2'] ?? null;
            $alat3 = $alatInputs[$rowNumber]['alat_3'] ?? null;
            $alat4 = $alatInputs[$rowNumber]['alat_4'] ?? null;
            $alat5 = $alatInputs[$rowNumber]['alat_5'] ?? null;
            
            // Cek apakah ada data untuk baris ini
            $hasData = !empty($nominalValue) || 
                       !empty($alat1) || 
                       !empty($alat2) || 
                       !empty($alat3) || 
                       !empty($alat4) || 
                       !empty($alat5);
            
            if ($hasData) {
                $detailData = [
                    'calibration_id' => $calibration->id,
                    'nominal_value' => $nominalValue,
                    'alat_1' => $alat1,
                    'alat_2' => $alat2,
                    'alat_3' => $alat3,
                    'alat_4' => $alat4,
                    'alat_5' => $alat5,
                ];
                
                DetailHeightGauge::create($detailData);
                $detailCount++;
                \Log::debug("✅ Detail updated for row {$rowNumber}: nominal = {$nominalValue}");
            }
        }
        
        \Log::info("✅ Updated {$detailCount} detail measurements for Height Gauge");

        // ==================================================================
        // 4. UPDATE CALIBRATION DENGAN DATA LAINNYA
        // ==================================================================
        $updateData = [];
        
        // Data dari form utama
        $fieldsToUpdate = [
            'nama_alat' => 'nama_alat_final',
            'merek' => 'merek',
            'kode_alat' => 'kode_alat',
            'type_alat' => 'type_alat',
            'no_seri' => 'no_seri',
            'kapasitas' => 'kapasitas',
            'resolusi' => 'resolusi',
            'nama_pemilik' => 'nama_pemilik',
            'tanggal_alat_masuk' => 'tanggal_alat_masuk',
            'tanggal_kalibrasi' => 'tanggal_kalibrasi',
            'jenis_pembacaan' => 'jenis_pembacaan',
            'tempat_kalibrasi' => 'tempat_kalibrasi',
            'lokasi_pt' => 'lokasi_pt',
            'kode_th' => 'kode_th',
            'fungsi_komponen' => 'fungsi_komponen',
            'keterangan_fungsi_komponen' => 'keterangan_fungsi_komponen',
            'suhu_awal' => 'suhu_awal',
            'suhu_tengah' => 'suhu_tengah',
            'suhu_akhir' => 'suhu_akhir',
            'rh_awal' => 'rh_awal',
            'rh_tengah' => 'rh_tengah',
            'rh_akhir' => 'rh_akhir',
            'calibrated_by' => 'calibrated_by',
            'verified_by' => 'verified_by',
        ];
        
        foreach ($fieldsToUpdate as $requestField => $dbField) {
            $value = $this->getRequestValue($request, $requestField, $tabId);
            if ($value !== null && $value !== '') {
                // Handle khusus untuk nama_alat (ambil dari final)
                if ($requestField == 'nama_alat') {
                    $value = $this->getRequestValue($request, 'nama_alat_final', $tabId);
                    if (empty($value)) {
                        $value = $this->getRequestValue($request, 'nama_alat', $tabId);
                    }
                }
                $updateData[$dbField] = $value;
                \Log::info("📝 Field {$dbField} updated:", ['value' => $value]);
            }
        }
        
        // Handle rentang ukur (default 0)
        if (!isset($updateData['rentang_ukur_min'])) {
            $updateData['rentang_ukur_min'] = '0';
        }
        if (!isset($updateData['rentang_ukur_max'])) {
            $updateData['rentang_ukur_max'] = '0';
        }
        
        if (!empty($updateData)) {
            $calibration->update($updateData);
            \Log::info('✅ Calibration updated with all form data');
        }

        // ==================================================================
        // 5. LOG HASIL AKHIR
        // ==================================================================
        $savedDetailCount = DetailHeightGauge::where('calibration_id', $calibration->id)->count();
        
        \Log::info('📋 UPDATE SUMMARY (Height Gauge):', [
            'calibration_id' => $calibration->id,
            'detail_records' => $savedDetailCount,
            'certificate_id' => $certificateId,
            'tab_id' => $tabId,
            'alat_standar' => $alatStandarString,
            'satuan_titik_ukur' => $satuanTitikUkur,
            'calibration_method' => $calibrationMethod,
            'total_nominal_points' => $detailCount
        ]);

        \Log::info('🎉 updateHeightGauge COMPLETED');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateHeightGauge:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'calibration_id' => $calibration->id ?? 'N/A',
            'tab_id' => $tabId ?? 'N/A',
            'trace' => $e->getTraceAsString()
        ]);
        
        throw new \Exception("Gagal mengupdate data Height Gauge: " . $e->getMessage());
    }
}

private function storeInsulation($request, $calibration, $certificateId, $tabId = null)
{
    try {
        \Log::info('🚀 START storeInsulation');

        if ($tabId === null) {
            $tabId = $request->input('tab_id', 1);
        }

        $activeParameters = $this->getRequestValue($request, 'active_parameters', $tabId);
        if (empty($activeParameters)) {
            $activeParameters = $request->input('active_parameters', []);
        }

        if (is_string($activeParameters)) {
            $activeParameters = json_decode($activeParameters, true) ?? [$activeParameters];
        }
        if (!is_array($activeParameters)) {
            $activeParameters = [];
        }

        $activeParameters = array_unique($activeParameters);

        \Log::info('📌 Active parameters for insulation:', [
            'parameters' => $activeParameters,
            'tab_id' => $tabId
        ]);

        // ==========================================
        // 1. SAVE HEAD INSULATION
        // ==========================================
        $standard = '';
        $calibrationMethod = '';
        $insulationType = '';
        
        // Ambil alat standar dari request
        $alatStandar = $request->input('alat_standar', []);
        if (is_array($alatStandar)) {
            $standard = implode(', ', $alatStandar);
        } else {
            $standard = $alatStandar;
        }
        
        // Jika kosong, coba dari alat_standar_text
        if (empty($standard)) {
            $standard = $request->input('alat_standar_text', '');
        }
        
        // ==========================================
        // DETERMINE INSULATION TYPE
        // ==========================================
        // Ambil insulation_type dari request
        $insulationType = $request->input('insulation_type', '');
        
        // Jika insulation_type kosong, coba deteksi dari input lain
        if (empty($insulationType)) {
            $metode2 = $request->input('metode_2', '');
            $metode1 = $request->input('metode_1', '');
            $metode = $request->input('metode', '');
            
            // Deteksi berdasarkan metode atau input lainnya
            $isClamp = !empty($metode2) 
                || str_contains(strtolower($metode), 'clamp') 
                || str_contains(strtolower($metode), '43 b')
                || str_contains(strtolower($insulationType), 'clamp');
            
            // Set insulation_type berdasarkan deteksi
            $insulationType = $isClamp ? 'clampmeter' : 'multimeter';
            
            \Log::info('🔍 Insulation type detected from inputs: ' . $insulationType);
        } else {
            \Log::info('📌 Insulation type from request: ' . $insulationType);
        }
        
        // ==========================================
        // DETERMINE CALIBRATION METHOD
        // ==========================================
        // Tentukan metode kalibrasi berdasarkan insulation_type
        $metode2 = $request->input('metode_2', '');
        $metode1 = $request->input('metode_1', '');
        $metode = $request->input('metode', '');
        
        $isClamp = strtolower($insulationType) === 'clampmeter' 
            || !empty($metode2) 
            || str_contains(strtolower($metode), 'clamp') 
            || str_contains(strtolower($metode), '43 b');

        $calibrationMethod = $isClamp ? 'PAS-IK1102-43 B (Clamp Meter)' : 'PAS-IK1102-43 A (Multimeter)';
        
        \Log::info('📌 Calibration Method: ' . $calibrationMethod);
        \Log::info('📌 Insulation Type: ' . $insulationType);

        // Cek apakah sudah ada head_insulation untuk calibration ini
        $headInsulation = HeadInsulation::where('calibration_id', $calibration->id)->first();
        
        if ($headInsulation) {
            // Update existing
            $headInsulation->update([
                'standard' => $standard,
                'calibrationMethod' => $calibrationMethod,
                'certificate_id' => $certificateId,
                'insulation_type' => $insulationType, // <-- Tambahkan ini
            ]);
            \Log::info('✅ Updated HeadInsulation for calibration_id: ' . $calibration->id . ' with insulation_type: ' . $insulationType);
        } else {
            // Create new dengan certificate_id dan insulation_type
            $headInsulation = HeadInsulation::create([
                'calibration_id' => $calibration->id,
                'certificate_id' => $certificateId,
                'standard' => $standard,
                'calibrationMethod' => $calibrationMethod,
                'insulation_type' => $insulationType, // <-- Tambahkan ini
            ]);
            \Log::info('✅ Created HeadInsulation for calibration_id: ' . $calibration->id . ' with insulation_type: ' . $insulationType);
        }

        // ==========================================
        // 2. SAVE DETAIL INSULATION
        // ==========================================
        $detailCount = 0;

        $insulationData = $request->input('insulation_data', []);
        if (empty($insulationData)) {
            $insulationData = $request->input("insulation_data_tab{$tabId}", []);
        }
        if (empty($insulationData)) {
            foreach ($request->all() as $key => $val) {
                if (str_contains($key, 'insulation_data')) {
                    $insulationData = $val;
                    break;
                }
            }
        }

        if (is_string($insulationData)) {
            $insulationData = json_decode($insulationData, true) ?? [];
        }
        if (!is_array($insulationData)) {
            $insulationData = [];
        }

        \Log::info('📊 Extracting insulation measurements:', [
            'has_data' => !empty($insulationData),
            'param_keys' => array_keys($insulationData)
        ]);

        // Hapus detail lama jika ada (untuk update)
        DetailInsulation::where('calibration_id', $calibration->id)->delete();

        foreach ($activeParameters as $param) {
            $rows = $insulationData[$param] ?? [];
            
            // Tentukan jumlah baris berdasarkan parameter dan jenis alat
            $numRows = 9; // Default untuk multimeter
            
            if ($param === 'ac_current' && $isClamp) {
                // Clamp Meter: 18 baris (9 A + 9 Hz selang-seling)
                $numRows = 18;
            } elseif ($param === 'ac_current' && !$isClamp) {
                // Multimeter: 9 baris (3 µA, 3 mA, 3 A)
                $numRows = 9;
            }
            
            for ($i = 0; $i < $numRows; $i++) {
                $row = $rows[$i] ?? [];
                
                // Ambil satuan dari hidden input
                $satuan = $row['satuan'] ?? null;
                
                // Gabungkan rentang dengan satuan jika ada
                $rentangValue = $row['rentang'] ?? null;
                if (!empty($rentangValue) && !empty($satuan)) {
                    $rentangFinal = $rentangValue . ' ' . $satuan;
                } elseif (!empty($satuan)) {
                    $rentangFinal = $satuan;
                } else {
                    $rentangFinal = $rentangValue;
                }
                
                // Tentukan jumlah sub-row (titik ukur) berdasarkan parameter
                if ($param === 'ac_voltage' || $param === 'dc_voltage') {
                    // Voltage: 4 titik ukur
                    $numSubRows = 4;
                } elseif ($param === 'ac_current') {
                    if ($isClamp) {
                        // Clamp Meter: A = 2 titik ukur, Hz = 1 titik ukur
                        $numSubRows = ($i % 2 === 0) ? 2 : 1;
                    } else {
                        // Multimeter: 3 titik ukur
                        $numSubRows = 3;
                    }
                } elseif ($param === 'dc_current' || $param === 'resistance') {
                    // DC Current & Resistance: 3 titik ukur
                    $numSubRows = 3;
                } else {
                    $numSubRows = 3;
                }
                
                for ($k = 1; $k <= $numSubRows; $k++) {
                    // Ambil nilai titik ukur dengan format baru
                    $titikUkurKey = 'titik_ukur_' . $k;
                    $titikUkur = $row[$titikUkurKey] ?? null;
                    
                    // Ambil frequency dengan format baru (jika ada)
                    $frequencyKey = 'frequency_' . $k;
                    $frequency = $row[$frequencyKey] ?? null;
                    
                    // Ambil coil dengan format baru (jika ada)
                    $coilKey = 'coil_' . $k;
                    $coil = $row[$coilKey] ?? null;
                    
                    // Ambil readAlat dengan format baru: readAlat_{titikUkur}_{pengukuranKe}
                    $readAlat1 = $row['readAlat_' . $k . '_1'] ?? null;
                    $readAlat2 = $row['readAlat_' . $k . '_2'] ?? null;
                    $readAlat3 = $row['readAlat_' . $k . '_3'] ?? null;
                    $readAlat4 = $row['readAlat_' . $k . '_4'] ?? null;
                    $readAlat5 = $row['readAlat_' . $k . '_5'] ?? null;
                    
                    // Tambahkan satuan ke titik_ukur jika ada
                    $titikUkurFinal = $titikUkur;
                    if (!empty($titikUkur) && !empty($satuan)) {
                        $titikUkurFinal = $titikUkur . ' ' . $satuan;
                    }
                    
                    // Tambahkan satuan ke frequency jika ada dan belum ada
                    $frequencyFinal = $frequency;
                    if (!empty($frequency) && !str_contains(strtolower($frequency), 'hz')) {
                        $frequencyFinal = $frequency . ' Hz';
                    }
                    
                    // Ambil resolusi alat
                    $resolusiAlat = $row['resolusi_alat_' . $k . '_1'] ?? $row['resolusi_alat'] ?? null;
                    
                    // Skip jika semua data kosong
                    if (empty($titikUkur) && empty($rentangValue) && 
                        empty($readAlat1) && empty($readAlat2) &&
                        empty($readAlat3) && empty($readAlat4) &&
                        empty($readAlat5)) {
                        continue;
                    }
                    
                    DetailInsulation::create([
                        'calibration_id' => $calibration->id,
                        'parameter_type' => $param,
                        'rentang'        => $rentangFinal,
                        'titik_ukur'     => $titikUkurFinal,
                        'readAlat_1'     => $readAlat1,
                        'readAlat_2'     => $readAlat2,
                        'readAlat_3'     => $readAlat3,
                        'readAlat_4'     => $readAlat4,
                        'readAlat_5'     => $readAlat5,
                        'resolusi_alat'  => $resolusiAlat,
                        'frequency'      => $frequencyFinal,
                        'coil'           => $coil,
                    ]);
                    $detailCount++;
                }
            }
        }
        
        \Log::info("✅ Saved {$detailCount} detail measurements for Insulation/Kelistrikan");
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR storeInsulation:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw new \Exception("Gagal menyimpan data Insulation: " . $e->getMessage());
    }
}


/**
 * Helper function untuk mendapatkan field value dari row
 * Mendukung berbagai format: titik_ukur_1, titik_ukur_1, atau langsung array
 */
private function getFieldValue($row, $field, $index)
{
    // Format 1: field_index (contoh: titik_ukur_1)
    $key1 = $field . '_' . $index;
    if (isset($row[$key1])) {
        return $row[$key1];
    }
    
    // Format 2: field_1 (contoh: titik_ukur1)
    $key2 = $field . $index;
    if (isset($row[$key2])) {
        return $row[$key2];
    }
    
    // Format 3: field[index] (contoh: titik_ukur[0])
    $key3 = $field . '[' . ($index - 1) . ']';
    if (isset($row[$key3])) {
        return $row[$key3];
    }
    
    // Format 4: field adalah array dengan index
    if (isset($row[$field]) && is_array($row[$field])) {
        $idx = $index - 1;
        if (isset($row[$field][$idx])) {
            return $row[$field][$idx];
        }
    }
    
    return null;
}

private function updateInsulation($request, $calibration, $newCertificateId = null)
{
    try {
        \Log::info('🚀 ===== START updateInsulation =====', [
            'calibration_id' => $calibration->id,
            'timestamp' => now()->toDateTimeString()
        ]);
        
        \Log::info('📋 Request data keys:', array_keys($request->all()));

        // ==========================================
        // 1. GET PARAMETERS FROM REQUEST OR EXISTING
        // ==========================================
        $activeParameters = [];
        
        // Cek dari insulation_data di request
        $insulationData = $request->input('insulation_data', []);
        if (empty($insulationData)) {
            $insulationData = $request->input("insulation_data_tab1", []);
        }
        if (empty($insulationData)) {
            foreach ($request->all() as $key => $val) {
                if (str_contains($key, 'insulation_data')) {
                    $insulationData = $val;
                    break;
                }
            }
        }

        if (is_string($insulationData)) {
            $insulationData = json_decode($insulationData, true) ?? [];
        }
        if (!is_array($insulationData)) {
            $insulationData = [];
        }

        // Ambil parameter dari insulation_data
        if (!empty($insulationData)) {
            $activeParameters = array_keys($insulationData);
        }
        
        // Filter dengan active_parameters dari request jika ada
        $requestActiveParams = $request->input('active_parameters');
        if (!empty($requestActiveParams)) {
            if (is_string($requestActiveParams)) {
                $requestActiveParams = json_decode($requestActiveParams, true) ?? [$requestActiveParams];
            }
            if (is_array($requestActiveParams)) {
                // Hanya simpan parameter yang dicentang
                $activeParameters = array_values(array_intersect($activeParameters, $requestActiveParams));
            }
        } else {
            // Jika request berasal dari form submit (ada namaAlat atau brandAlat) tapi active_parameters kosong,
            // artinya user meng-uncheck semua parameter.
            if ($request->has('namaAlat') || $request->has('brandAlat') || $request->has('nama_alat')) {
                $activeParameters = [];
            }
        }
        
        // Jika masih kosong, ambil dari existing details
        if (empty($activeParameters)) {
            $existingDetails = DetailInsulation::where('calibration_id', $calibration->id)->get();
            foreach ($existingDetails as $detail) {
                if (!in_array($detail->parameter_type, $activeParameters)) {
                    $activeParameters[] = $detail->parameter_type;
                }
            }
        }
        
        $activeParameters = array_unique($activeParameters);
        
        \Log::info('📌 Parameters for update:', [
            'parameters' => $activeParameters,
            'calibration_id' => $calibration->id
        ]);

        // ==========================================
        // 2. UPDATE / CREATE HEAD INSULATION
        // ==========================================
        $standard = '';
        $calibrationMethod = '';
        
        // Ambil alat standar dari request
        $alatStandar = $request->input('alat_standar', []);
        if (is_array($alatStandar)) {
            $standard = implode(', ', $alatStandar);
        } else {
            $standard = $alatStandar;
        }
        
        // Jika kosong, coba dari alat_standar_text
        if (empty($standard)) {
            $standard = $request->input('alat_standar_text', '');
        }
        
        // Jika masih kosong, ambil dari head yang sudah ada
        if (empty($standard)) {
            $existingHead = HeadInsulation::where('calibration_id', $calibration->id)->first();
            if ($existingHead) {
                $standard = $existingHead->standard;
            }
        }
        
        // Ambil metode kalibrasi
        // $calibrationMethod = $request->input('metode', '');
        // if (empty($calibrationMethod)) {
        //     $calibrationMethod = $request->input('metode_1', '');
        // }
        // if (empty($calibrationMethod)) {
        //     $calibrationMethod = $request->input('metode_2', '');
        // }
        
        // // Jika masih kosong, ambil dari head yang sudah ada
        // if (empty($calibrationMethod)) {
        //     $existingHead = HeadInsulation::where('calibration_id', $calibration->id)->first();
        //     if ($existingHead) {
        //         $calibrationMethod = $existingHead->calibrationMethod;
        //     }
        // }
        
         // Tentukan metode kalibrasi berdasarkan input (metode_1 untuk Multimeter, metode_2 untuk Clamp Meter)
        $metode2 = $request->input('metode_2', '');
        $metode1 = $request->input('metode_1', '');
        $metode = $request->input('metode', '');
        $insulationType = $request->input('insulation_type', '');

        $isClamp = !empty($metode2) 
            || str_contains(strtolower($metode), 'clamp') 
            || str_contains(strtolower($metode), '43 b')
            || str_contains(strtolower($insulationType), 'clamp');

        $calibrationMethod = $isClamp ? 'PAS-IK1102-43 B (Clamp Meter)' : 'PAS-IK1102-43 A (Multimeter)';



        // Cek apakah sudah ada head_insulation
        $headInsulation = HeadInsulation::where('calibration_id', $calibration->id)->first();
        
        $headData = [
            'standard' => $standard,
            'calibrationMethod' => $calibrationMethod,
        ];

        // Update certificate_id jika ada
        if ($newCertificateId) {
            $headData['certificate_id'] = $newCertificateId;
            \Log::info('🆔 Setting certificate_id untuk head: ' . $newCertificateId);
        } else {
            // Jika tidak ada certificate_id baru, pertahankan yang lama
            if ($headInsulation && $headInsulation->certificate_id) {
                $headData['certificate_id'] = $headInsulation->certificate_id;
            }
        }

        if ($headInsulation) {
            $headInsulation->update($headData);
            \Log::info('✅ HeadInsulation updated', [
                'id' => $headInsulation->id,
                'standard' => $standard,
                'certificate_id' => $headInsulation->certificate_id,
            ]);
        } else {
            $headData['calibration_id'] = $calibration->id;
            if (empty($headData['certificate_id'])) {
                $headData['certificate_id'] = $newCertificateId ?? $calibration->certificate_id ?? 'NEW-' . time();
            }
            
            $headInsulation = HeadInsulation::create($headData);
            \Log::info('➕ HeadInsulation created baru', [
                'id' => $headInsulation->id,
                'calibration_id' => $calibration->id,
                'certificate_id' => $headInsulation->certificate_id
            ]);
        }

        // ==========================================
        // 3. UPDATE DETAIL INSULATION
        // ==========================================
        \Log::info('🔄 Updating detail measurements...');
        
        // Hapus data lama terlebih dahulu
        $deletedCount = DetailInsulation::where('calibration_id', $calibration->id)->delete();
        \Log::info('🗑️ Data lama dihapus', ['deleted_count' => $deletedCount]);

        $detailCount = 0;

        \Log::info('📊 Extracting insulation measurements:', [
            'has_data' => !empty($insulationData),
            'param_keys' => array_keys($insulationData)
        ]);

        // // Cek apakah ini Clamp Meter
        // $isClamp = str_contains(strtolower($calibration->namaAlat), 'clamp');
        // $metode = $request->input('metode', '');
        // if (str_contains(strtolower($metode), 'clamp')) {
        //     $isClamp = true;
        // }

        foreach ($activeParameters as $param) {
            $rows = $insulationData[$param] ?? [];
            
            // Tentukan jumlah baris
            $numRows = 9; // Default untuk multimeter
            
            if ($param === 'ac_current' && $isClamp) {
                $numRows = 18;
            } elseif ($param === 'ac_current' && !$isClamp) {
                $numRows = 9;
            }
            
            for ($i = 0; $i < $numRows; $i++) {
                $row = $rows[$i] ?? [];
                
                // Ambil satuan dari hidden input atau dari data yang ada
                $satuan = $row['satuan'] ?? null;
                
                // Jika tidak ada satuan di hidden input, coba ekstrak dari rentang
                if (empty($satuan) && !empty($row['rentang'])) {
                    $rentangParts = explode(' ', trim($row['rentang']));
                    if (count($rentangParts) >= 2) {
                        $satuan = end($rentangParts);
                    }
                }
                
                // Gabungkan rentang dengan satuan
                $rentangValue = $row['rentang'] ?? null;
                if (!empty($rentangValue) && !empty($satuan) && !str_contains($rentangValue, $satuan)) {
                    $rentangFinal = $rentangValue . ' ' . $satuan;
                } elseif (!empty($rentangValue)) {
                    $rentangFinal = $rentangValue;
                } elseif (!empty($satuan)) {
                    $rentangFinal = $satuan;
                } else {
                    $rentangFinal = null;
                }
                
                // Tentukan jumlah sub-row (titik ukur)
                if ($param === 'ac_voltage' || $param === 'dc_voltage') {
                    $numSubRows = 4;
                } elseif ($param === 'ac_current') {
                    if ($isClamp) {
                        $numSubRows = ($i % 2 === 0) ? 2 : 1;
                    } else {
                        $numSubRows = 3;
                    }
                } elseif ($param === 'dc_current' || $param === 'resistance') {
                    $numSubRows = 3;
                } else {
                    $numSubRows = 3;
                }
                
                for ($k = 1; $k <= $numSubRows; $k++) {
                    // Ambil nilai titik ukur dengan format baru
                    $titikUkurKey = 'titik_ukur_' . $k;
                    $titikUkur = $row[$titikUkurKey] ?? null;
                    
                    // Ambil frequency dengan format baru
                    $frequencyKey = 'frequency_' . $k;
                    $frequency = $row[$frequencyKey] ?? null;
                    
                    // Ambil coil dengan format baru
                    $coilKey = 'coil_' . $k;
                    $coil = $row[$coilKey] ?? null;
                    
                    // Tambahkan satuan ke titik_ukur jika ada
                    $titikUkurFinal = $titikUkur;
                    if (!empty($titikUkur) && !empty($satuan) && !str_contains($titikUkur, $satuan)) {
                        $titikUkurFinal = $titikUkur . ' ' . $satuan;
                    }
                    
                    // Tambahkan satuan ke frequency jika ada dan belum ada
                    $frequencyFinal = $frequency;
                    if (!empty($frequency) && !str_contains(strtolower($frequency), 'hz')) {
                        $frequencyFinal = $frequency . ' Hz';
                    }
                    
                    // Ambil readAlat dengan format baru: readAlat_{titikUkur}_{pengukuranKe}
                    $readAlat1 = $row['readAlat_' . $k . '_1'] ?? null;
                    $readAlat2 = $row['readAlat_' . $k . '_2'] ?? null;
                    $readAlat3 = $row['readAlat_' . $k . '_3'] ?? null;
                    $readAlat4 = $row['readAlat_' . $k . '_4'] ?? null;
                    $readAlat5 = $row['readAlat_' . $k . '_5'] ?? null;
                    
                    // Ambil resolusi alat
                    $resolusiAlat = $row['resolusi_alat_' . $k . '_1'] ?? $row['resolusi_alat'] ?? null;
                    
                    // Skip jika semua data kosong
                    if (empty($titikUkur) && empty($rentangValue) && 
                        empty($readAlat1) && empty($readAlat2) && empty($readAlat3) && 
                        empty($readAlat4) && empty($readAlat5) && empty($resolusiAlat)) {
                        continue;
                    }
                    
                    // Log untuk debugging
                    \Log::debug('💾 Saving detail:', [
                        'param' => $param,
                        'row' => $i,
                        'sub' => $k,
                        'rentang' => $rentangFinal,
                        'titik_ukur' => $titikUkurFinal,
                        'satuan' => $satuan,
                        'readAlat1' => $readAlat1,
                        'readAlat2' => $readAlat2,
                        'readAlat3' => $readAlat3,
                        'readAlat4' => $readAlat4,
                        'readAlat5' => $readAlat5
                    ]);
                    
                    DetailInsulation::create([
                        'calibration_id' => $calibration->id,
                        'parameter_type' => $param,
                        'rentang'        => $rentangFinal,
                        'titik_ukur'     => $titikUkurFinal,
                        'readAlat_1'     => $readAlat1,
                        'readAlat_2'     => $readAlat2,
                        'readAlat_3'     => $readAlat3,
                        'readAlat_4'     => $readAlat4,
                        'readAlat_5'     => $readAlat5,
                        'resolusi_alat'  => $resolusiAlat,
                        'frequency'      => $frequencyFinal,
                        'coil'           => $coil,
                    ]);
                    $detailCount++;
                }
            }
        }

        \Log::info("✅ Saved {$detailCount} detail measurements");

        // ==========================================
        // 4. FINAL VERIFICATION
        // ==========================================
        $finalDetailCount = DetailInsulation::where('calibration_id', $calibration->id)->count();
        $finalHead = HeadInsulation::where('calibration_id', $calibration->id)->first();
        
        \Log::info('🔍 FINAL VERIFICATION:', [
            'calibration_id' => $calibration->id,
            'certificate_id_head' => $finalHead->certificate_id ?? 'TIDAK ADA',
            'head_id' => $headInsulation->id ?? 'TIDAK ADA',
            'detail_records' => $finalDetailCount,
            'standard' => $standard,
            'parameters_processed' => $activeParameters,
        ]);

        \Log::info('🎉 updateInsulation COMPLETED SUCCESSFULLY');
        return true;

    } catch (\Exception $e) {
        \Log::error('💥 ERROR updateInsulation:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $calibration->id ?? 'N/A',
        ]);
        
        throw new \Exception("Gagal mengupdate data Insulation: " . $e->getMessage());
    }
}

/**
 * Format bytes ke readable size
 */
private function formatBytes($bytes, $precision = 2)
{
    $units = ['B', 'KB', 'MB', 'GB', 'TB'];
    
    $bytes = max($bytes, 0);
    $pow = floor(($bytes ? log($bytes) : 0) / log(1024));
    $pow = min($pow, count($units) - 1);
    
    $bytes /= pow(1024, $pow);
    
    return round($bytes, $precision) . ' ' . $units[$pow];
}




