/**
 * Ambil alat standar dari request (support array dan text)
 */
private function getAlatStandarFromRequest($request)
{
    // Coba ambil dari array dulu
    $alatStandar = $request->alat_standar ?? [];
    
    if (!empty($alatStandar) && is_array($alatStandar)) {
        return implode(', ', $alatStandar);
    }
    
    // Jika array kosong, coba dari text
    if ($request->filled('alat_standar_text')) {
        return $request->alat_standar_text;
    }
    
    // Coba dari field lain
    if ($request->filled('alatStandar')) {
        return $request->alatStandar;
    } 
    
    return '';
}

/**
 * Simpan Head Thermohygrometer
 */
private function saveHeadThermohygrometer($calibrationId, $certificateId, $standard, $method)
{
    // Cek apakah head sudah ada (untuk update scenario)
    $headThermohygrometer = \App\Models\HeadThermohygrometer::where('calibration_id', $calibrationId)->first();
    
    if ($headThermohygrometer) {
        // Update head yang sudah ada
        $headThermohygrometer->update([
            'standard' => $standard,
            'calibrationMethod' => $method,
            'certificate_id' => $certificateId,
        ]);
        \Log::info('✅ Updated existing HeadThermohygrometer');
    } else {
        // Buat head baru
        \App\Models\HeadThermohygrometer::create([
            'calibration_id' => $calibrationId,
            'certificate_id' => $certificateId,
            'standard' => $standard,
            'calibrationMethod' => $method,
        ]);
        \Log::info('✅ Created new HeadThermohygrometer');
    }
}

/**
 * Simpan detail untuk type IN/OUT (7 baris)
 */
private function saveInOutDetails($request, $calibration)
{
    $detailCount = 0;
    \Log::info('Processing IN/OUT data (7 rows)...');
    
    for ($i = 0; $i < 7; $i++) {
        $tempData = $request->input("temp.{$i}", []);
        $humidityData = $request->input("humidity.{$i}", []);
        
        // Debug log
        \Log::debug("IN/OUT Row {$i}", [
            'temp' => $tempData,
            'humidity' => $humidityData
        ]);
        
        // Cek apakah ada data untuk baris ini
        $hasTempData = !empty(array_filter($tempData, function($value) {
            return $value !== null && $value !== '' && $value !== 'null';
        }));
        
        $hasHumidityData = !empty(array_filter($humidityData, function($value) {
            return $value !== null && $value !== '' && $value !== 'null';
        }));
        
        if ($hasTempData || $hasHumidityData) {
            try {
                \App\Models\DetailThermohygrometer::create([
                    'calibration_id' => $calibration->id,
                    
                    // Data Temperatur
                    'titikUkur_T' => $tempData['set_point'] ?? null,
                    'T_STD1' => $tempData['std_x1'] ?? null,
                    'T_STD2' => $tempData['std_x2'] ?? null,
                    'T_STD3' => $tempData['std_x3'] ?? null,
                    'T_IN1' => $tempData['in_x1'] ?? null,
                    'T_IN2' => $tempData['in_x2'] ?? null,
                    'T_IN3' => $tempData['in_x3'] ?? null,
                    'T_OUT1' => $tempData['out_x1'] ?? null,
                    'T_OUT2' => $tempData['out_x2'] ?? null,
                    'T_OUT3' => $tempData['out_x3'] ?? null,
                    
                    // Data Kelembaban
                    'titikUkur_RH' => $humidityData['set_point'] ?? null,
                    'RH_STD1' => $humidityData['std_x1'] ?? null,
                    'RH_STD2' => $humidityData['std_x2'] ?? null,
                    'RH_STD3' => $humidityData['std_x3'] ?? null,
                    'RH_ALAT1' => $humidityData['alat_x1'] ?? null,
                    'RH_ALAT2' => $humidityData['alat_x2'] ?? null,
                    'RH_ALAT3' => $humidityData['alat_x3'] ?? null,
                ]);
                
                $detailCount++;
                \Log::debug("✅ Saved IN/OUT row {$i}");
                
            } catch (\Exception $e) {
                \Log::error("❌ Failed to save IN/OUT row {$i}: " . $e->getMessage());
            }
        } else {
            \Log::debug("⏭️ Skipping IN/OUT row {$i} - no data");
        }
    }
    
    return $detailCount;
}

/**
 * Simpan detail untuk type SINGLE (10 baris)
 */
private function saveSingleDetails($request, $calibration)
{
    $detailCount = 0;
    \Log::info('Processing SINGLE data (10 rows)...');
    
    for ($i = 1; $i <= 10; $i++) {
        // Cek apakah ada data untuk baris ini
        $hasTempData = $request->filled("t_set{$i}") || 
                      $request->filled("t_std{$i}_1") ||
                      $request->filled("t_inst{$i}_1");
        
        $hasHumidityData = $request->filled("h_set{$i}") || 
                          $request->filled("h_std{$i}_1") ||
                          $request->filled("h_inst{$i}_1");
        
        if ($hasTempData || $hasHumidityData) {
            try {
                \App\Models\DetailThermohygrometer::create([
                    'calibration_id' => $calibration->id,
                    
                    // Data Temperatur
                    'titikUkur_T' => $this->formatNumericValue($request->input("t_set{$i}")),
                    'T_STD1' => $this->formatNumericValue($request->input("t_std{$i}_1")),
                    'T_STD2' => $this->formatNumericValue($request->input("t_std{$i}_2")),
                    'T_STD3' => $this->formatNumericValue($request->input("t_std{$i}_3")),
                    'T_IN1' => null,  // DIKOSONGKAN untuk type single
                    'T_IN2' => null,  // DIKOSONGKAN untuk type single
                    'T_IN3' => null,  // DIKOSONGKAN untuk type single
                    'T_OUT1' => null, // DIKOSONGKAN untuk type single
                    'T_OUT2' => null, // DIKOSONGKAN untuk type single
                    'T_OUT3' => null, // DIKOSONGKAN untuk type single
                    
                    // Data Kelembaban
                    'titikUkur_RH' => $this->formatNumericValue($request->input("h_set{$i}")),
                    'RH_STD1' => $this->formatNumericValue($request->input("h_std{$i}_1")),
                    'RH_STD2' => $this->formatNumericValue($request->input("h_std{$i}_2")),
                    'RH_STD3' => $this->formatNumericValue($request->input("h_std{$i}_3")),
                    'RH_ALAT1' => $this->formatNumericValue($request->input("h_inst{$i}_1")),
                    'RH_ALAT2' => $this->formatNumericValue($request->input("h_inst{$i}_2")),
                    'RH_ALAT3' => $this->formatNumericValue($request->input("h_inst{$i}_3")),
                ]);
                
                $detailCount++;
                \Log::debug("✅ Saved SINGLE row {$i} (T_IN/T_OUT fields nulled)");
                
            } catch (\Exception $e) {
                \Log::error("❌ Failed to save SINGLE row {$i}: " . $e->getMessage());
            }
        } else {
            \Log::debug("⏭️ Skipping SINGLE row {$i} - no data");
        }
    }
    
    return $detailCount;
}

/**
 * Simpan data tambahan ke calibration
 */
private function saveAdditionalCalibrationData($calibration, $request, $alatStandarString)
{
    $additionalData = [];
    
    if ($request->filled('calibrated_by')) {
        $additionalData['calibrated_by'] = $request->calibrated_by;
        \Log::info('📝 Nama dikalibrasi:', ['nama' => $request->calibrated_by]);
    }
    
    if ($request->filled('verified_by')) {
        $additionalData['verified_by'] = $request->verified_by;
        \Log::info('📝 Nama diperiksa:', ['nama' => $request->verified_by]);
    }
    
    if ($request->filled('uncertainty')) {
        $additionalData['uncertainty'] = $request->uncertainty;
        $additionalData['keterangan'] = $request->conclusion ?? '';
    }
    
    // Tanggal kalibrasi jika ada
    if ($request->filled('calibration_date')) {
        try {
            $additionalData['calibration_date'] = \Carbon\Carbon::parse($request->calibration_date);
        } catch (\Exception $e) {
            \Log::warning('⚠️ Invalid calibration date: ' . $e->getMessage());
        }
    }
    
    // Simpan alat standar ke calibration
    if (!empty($alatStandarString)) {
        $additionalData['alat_standar'] = $alatStandarString;
    }
    
    if ($request->filled('calibration_method')) {
        $additionalData['calibration_method'] = $request->calibration_method;
    }
    
    if (!empty($additionalData)) {
        $calibration->update($additionalData);
        \Log::info('✅ Additional data saved to calibration');
    }
}

/**
 * Log summary
 */
private function logStoreSummary($calibration, $type, $certificateId, $detailCount, $alatStandarString, $calibrationMethod)
{
    $savedDetailCount = \App\Models\DetailThermohygrometer::where('calibration_id', $calibration->id)->count();
    
    \Log::info('📋 STORE SUMMARY (Thermohygrometer):', [
        'calibration_id' => $calibration->id,
        'type' => $type,
        'detail_records' => $savedDetailCount,
        'certificate_id' => $certificateId,
        'alat_standar' => $alatStandarString,
        'calibration_method' => $calibrationMethod,
        'calibrated_by' => $calibration->calibrated_by ?? null,
        'verified_by' => $calibration->verified_by ?? null,
        'uncertainty' => $calibration->uncertainty ?? null,
    ]);
    
    // Validasi jika ada mismatch
    if ($detailCount !== $savedDetailCount) {
        \Log::warning("⚠️ Mismatch: Saved {$detailCount} records but {$savedDetailCount} in database");
    }
}

private function getFormattedNamaAlat($namaAlat = null, $calibration = null)
{
    $resolvedNamaAlat = is_string($namaAlat) ? trim($namaAlat) : '';

    // 1. Resolve jika bernilai MANUAL_INPUT atau kosong dari request
    if (empty($resolvedNamaAlat) || strtoupper($resolvedNamaAlat) === 'MANUAL_INPUT') {
        if (request()->has('nama_alat_manual') && !empty(request()->input('nama_alat_manual'))) {
            $resolvedNamaAlat = trim(request()->input('nama_alat_manual'));
        } elseif (request()->has('nama_alat_final') && !empty(request()->input('nama_alat_final'))) {
            $resolvedNamaAlat = trim(request()->input('nama_alat_final'));
        } elseif (request()->has('namaAlat') && !empty(request()->input('namaAlat'))) {
            $resolvedNamaAlat = trim(request()->input('namaAlat'));
        } elseif (request()->has('nama_alat') && !empty(request()->input('nama_alat'))) {
            $resolvedNamaAlat = trim(request()->input('nama_alat'));
        }
    }

    // 2. Jika masih kosong, coba ambil dari objek/array calibration
    if (empty($resolvedNamaAlat) || strtoupper($resolvedNamaAlat) === 'MANUAL_INPUT') {
        if ($calibration) {
            if (is_object($calibration)) {
                $resolvedNamaAlat = $calibration->namaAlat ?? $calibration->nama_alat ?? '';
            } elseif (is_array($calibration)) {
                $resolvedNamaAlat = $calibration['namaAlat'] ?? $calibration['nama_alat'] ?? '';
            }
        }
    }

    // 3. Fallback jika masih kosong
    if (empty($resolvedNamaAlat) || strtoupper($resolvedNamaAlat) === 'MANUAL_INPUT') {
        $resolvedNamaAlat = 'Alat';
    }

    // 4. Formatting: ganti underscore dengan spasi
    $formatted = str_replace('_', ' ', $resolvedNamaAlat);

    // Hapus karakter yang tidak valid (aman untuk certificate ID: alfanumerik, spasi, dash)
    $formatted = preg_replace('/[^\w\s\-]/', '', $formatted);
    $formatted = preg_replace('/\s+/', ' ', $formatted);

    // Ubah ke Title Case
    $formatted = ucwords(strtolower(trim($formatted)));

    return !empty($formatted) ? $formatted : 'Alat';
}

private function getFormattedFormType($namaAlat, $calibration = null)
{
    // Menggunakan NamaAlat saja (bukan form_type)
    return $this->getFormattedNamaAlat($namaAlat, $calibration);
}

