private function generateCertificateIdFromNamaAlat($namaAlat = null, $calibration = null)
{
    // 1. Jika objek Calibration diberikan dan memiliki ID, langsung kembalikan PURE calibration ID
    if ($namaAlat instanceof Calibration && !empty($namaAlat->id)) {
        return $namaAlat->id;
    }
    if (is_object($calibration) && !empty($calibration->id)) {
        return $calibration->id;
    }

    $baseId = null;

    if (is_string($calibration) && !empty($calibration)) {
        $baseId = $calibration;
    } elseif (is_string($namaAlat) && preg_match('/^PAS-\d+-K\d{2}/i', $namaAlat)) {
        $baseId = $namaAlat;
    } elseif (is_object($calibration) && !empty($calibration->id_alat)) {
        $baseId = $calibration->id_alat;
    }

    if (!$baseId) {
        $routeId = request()->route('id') ?? request()->route('calibration') ?? request()->input('calibration_id') ?? request()->input('id');
        if ($routeId) {
            $baseId = is_object($routeId) ? ($routeId->id ?? null) : $routeId;
        }
    }

    if (!$baseId) {
        try {
            $lastCalibration = Calibration::withTrashed()->where('id', 'LIKE', 'PAS-%')
                ->orderBy('id', 'desc')
                ->first();

            if ($lastCalibration) {
                $baseId = $lastCalibration->id;
            } else {
                $nomorUrutFormatted = str_pad(1, 6, '0', STR_PAD_LEFT);
                $currentYear = date('y');
                $baseId = "PAS-{$nomorUrutFormatted}-K{$currentYear}-1";
            }

        } catch (\Exception $e) {
            \Log::error('💥 Error generating certificate ID base:', [
                'error' => $e->getMessage()
            ]);

            $timestamp = substr(time(), -6);
            $formattedNumber = str_pad($timestamp, 6, '0', STR_PAD_LEFT);
            $currentYear = date('y');
            $baseId = "PAS-{$formattedNumber}-K{$currentYear}-1";
        }
    }

    // Bersihkan nama alat jika sebelumnya menempel di baseId (format lama: PAS-XXXXXX-KYY-Z-NamaAlat)
    if (preg_match('/^(PAS-\d+-K\d{2}(?:-\d+)?(?:-[A-Za-z]{2,4})?)/i', $baseId, $matches)) {
        $baseId = $matches[1];
    }
    
    if (preg_match('/^PAS-\d+-K\d{2}$/i', $baseId)) {
        $urutan = 1;
        if (is_object($calibration)) {
            $urutan = $calibration->urutan_kalibrasi_ke ?? 1;
        }
        $baseId = "{$baseId}-{$urutan}";
    }

    return $baseId;
}

private function generateCertificateId($namaAlat = null, $calibration = null)
{
    return $this->generateCertificateIdFromNamaAlat($namaAlat, $calibration);
}


