private function getAlatType($namaAlat = null, $formTypeDb = null)
{
    // ✅ 1. PRIORITAS: FORM TYPE DARI DATABASE
    if (!empty($formTypeDb)) {
        \Log::info("🎯 Form type dari database dipakai:", [
            'form_type_db' => $formTypeDb
        ]);
        return $formTypeDb;
    }

    // ✅ 2. SAFETY CHECK
    if (empty($namaAlat)) {
        return 'general';
    }

    $namaAlatLower = strtolower($namaAlat);

    // ✅ 3. MAPPING FULL (DARI PUNYA KAMU)
    $alatMapping = [
        // MICROMETER & CALIPER
        'inside micrometer' => 'inside_micrometer',
        'outside micrometer' => 'outside_micrometer',
        'depth micrometer' => 'depth_micrometer',
        'vernier caliper' => 'vernier_caliper',
        'depth caliper' => 'depth_caliper',
        'height gauge' => 'height_gauge',
        'caliper' => 'caliper',

        // INDICATOR
        'dial test indicator' => 'dial_test_indicator',
        'dial indicator' => 'dial_indicator',

        // THERMOMETER
        'thermometer infrared' => 'ir_thermometer',
        'thermometer' => 'thermometer',

        // TORQUE
        'torque wrench' => 'torque_wrench',
        'torque meter' => 'torque_meter',

        // THICKNESS
        'ultrasonic thickness gauge' => 'ultrasonic_thickness_gauge',
        'thickness gauge' => 'thickness_gauge',

        // PENGGARIS
        'penggaris' => 'penggaris',

        // ENCLOSURE
        'autoclave' => 'enclosure',
        'waterbath' => 'enclosure',
        'incubator' => 'enclosure',
        'furnace' => 'enclosure',
        'freezer' => 'enclosure',
        'oven' => 'enclosure',
        
        'clamp meter' => 'insulation',
        'clampmeter' => 'insulation',
        'multimeter' => 'insulation',


        // CHAMBER
        'climatic chamber' => 'chamber',
        'chamber' => 'chamber',

        // PRESSURE
        'differential pressure gauge' => 'differential_pressure_gauge',
        'pressure gauge' => 'pressure_gauge',

        // VOLUMETRIK
        'buret' => 'volumetrik',
        'gelas ukur' => 'volumetrik',
        'labu ukur' => 'volumetrik',
        'pipet volume' => 'volumetrik',
        'pipet ukur' => 'volumetrik',

        // LAINNYA
        'thermohygrometer' => 'thermohygrometer',
        'viscometer' => 'viscometer',
        'push pull' => 'push_pull',
        'tension gauge' => 'push_pull',
        'anak timbangan' => 'anak_timbangan',
        'timbangan and moisture' => 'timbangan_moisture',
        'timbangan moisture' => 'timbangan_moisture',
        'timbangan bias' => 'timbangan_bias',
        'timbangan' => 'timbangan',
        'gauge block' => 'gauge_block',
        'holetest' => 'holetest',
        'conductivity meter' => 'conductivity_meter',
        'coating thickness' => 'coating_thickness',
        'durometer' => 'durometer',
        'mikropipet' => 'mikropipet_dispenset',
        'dispenset' => 'mikropipet_dispenset',
        'taper gauge' => 'taper_gauge',
        'bore gauge' => 'bore_gauge',
        'feeler gauge' => 'feeler_gauge',
        'ph meter' => 'ph_meter',
        'tachometer' => 'tachometer',
        'pin gauge' => 'pin_gauge',
        'visco cup' => 'visco_cup',
        'plain limit gauge' => 'plain_limit_gauge',
        'thermo indicator' => 'thermo_indicator',
        'thermoindicator' => 'thermoindicator',
        'temperature transmitter' => 'temperature_transmitter',
        'humidity transmitter' => 'temp_humid_transmitter',
        'temperature' => 'temp_humid_transmitter',
        'plastic shim' => 'plastic_shim',
        'profil projector' => 'profil_projector',
        'microscope' => 'profil_projector',
        'surface roughness tester' => 'surface_roughness_tester',
        'thread gauge' => 'thread_gauge',
        'stopwatch' => 'stopwatch',
        'centrifuge' => 'centrifuge',
        'mesin uji tarik' => 'utm',
        'mesin uji tekan' => 'utm',
        'pressure transmitter' => 'pressure_transmitter',
        'diff pressure transmitter' => 'pressure_transmitter',
        'surface plate' => 'surface_plate',
        'meja rata' => 'surface_plate',
    ];

    // ✅ 4. SORT KEY PANJANG → PENDEK (BIAR GA SALAH MATCH)
    uksort($alatMapping, function ($a, $b) {
        return strlen($b) <=> strlen($a);
    });

    // ✅ 5. DETEKSI
    foreach ($alatMapping as $key => $type) {
        if (strpos($namaAlatLower, $key) !== false) {
            \Log::info("🔍 Form type detected:", [
                'namaAlat' => $namaAlatLower,
                'key' => $key,
                'type' => $type
            ]);
            return $type;
        }
    }

    // ✅ 6. DEFAULT
    return 'general';
}

    

private function updateInsideMicrometer($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateInsideMicrometer =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong atau MANUAL_INPUT):', [
                'certificate_id_lama' => $calibration->certificate_id,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        }
        
        // Update certificate_id di tabel calibration
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
            
            \Log::info('📝 UPDATE CERTIFICATE ID DI CALIBRATION:', [
                'certificate_id_baru' => $certificateIdBaru,
                'current_certificate_id' => $calibration->certificate_id
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Inside Micrometer - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM (DENGAN FIELD BARU PER FORM)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadInsideMicrometer::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // 🔥 AMBIL DATA DARI REQUEST (PER FORM)
            // Satuan Unit
            $satuanUnit = $request->input("satuan_unit_{$formIndex}", 
                          $request->input("satuan_unit", 'mm'));
            
            // 🔥 RENTANG UKUR MIN & MAX (PER FORM)
            $rentangUkurMin = $request->input("rentang_ukur_min_{$formIndex}", 
                             $request->input("rentang_ukur_min", '0'));
            $rentangUkurMax = $request->input("rentang_ukur_max_{$formIndex}", 
                             $request->input("rentang_ukur_max", ''));
            
            // 🔥 KAPASITAS & RESOLUSI (PER FORM)
            $kapasitas = $request->input("kapasitas_{$formIndex}", 
                        $request->input("kapasitas", ''));
            $resolusi = $request->input("resolusi_{$formIndex}", 
                      $request->input("resolusi", ''));
            
            $headData = [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
            ];
            
            // 🔥 AMBIL ALAT STANDAR UNTUK FORM INI (MASING-MASING FORM PUNYA SENDIRI)
            $alatStandar = [];
            
            // Coba ambil dari alat_standar_{formIndex}[]
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            
            // Jika masih kosong dan ini form 1, coba dari alat_standar biasa (backward compatibility)
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
            }
            
            // Pastikan dalam bentuk array
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            // Filter nilai kosong
            $alatStandar = array_filter($alatStandar);
            
            // Simpan ke database
            $headData['standard'] = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            \Log::info("📝 Head data untuk form {$formIndex}:", [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'alat_standar_raw' => $alatStandar,
                'standard_string' => $headData['standard']
            ]);
            
            // 🔥 UPDATE CERTIFICATE ID UNTUK SEMUA HEAD (FORM 1-4)
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'satuan_unit' => $head->satuan_unit,
                    'rentang_ukur_min' => $head->rentang_ukur_min,
                    'rentang_ukur_max' => $head->rentang_ukur_max,
                    'kapasitas' => $head->kapasitas,
                    'resolusi' => $head->resolusi,
                    'standard' => $head->standard,
                    'certificate_id' => $head->certificate_id ?? 'not_set'
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['calibrationMethod'] = 'PAS-IK1102-01 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)';
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                $head = HeadInsideMicrometer::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadInsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE DETAIL MEASUREMENTS
        // ==================================================================
        DetailInsideMicrometer::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Coba ambil data dengan berbagai format (dengan prefix form index)
            $titikUkurArray = $request->input("titikUkur_{$formIndex}", []);
            $ulangan01Array = $request->input("ulangan01_{$formIndex}", []);
            $ulangan02Array = $request->input("ulangan02_{$formIndex}", []);
            $ulangan03Array = $request->input("ulangan03_{$formIndex}", []);
            $ulangan04Array = $request->input("ulangan04_{$formIndex}", []);
            $ulangan05Array = $request->input("ulangan05_{$formIndex}", []);
            
            // Jika tidak ada data dengan format per form, coba ambil dari format array biasa
            if (empty($titikUkurArray)) {
                $titikUkurArray = $request->input("titikUkur", []);
                $ulangan01Array = $request->input("ulangan01", []);
                $ulangan02Array = $request->input("ulangan02", []);
                $ulangan03Array = $request->input("ulangan03", []);
                $ulangan04Array = $request->input("ulangan04", []);
                $ulangan05Array = $request->input("ulangan05", []);
                \Log::info("Using fallback array format for form {$formIndex}");
            }
            
            for ($i = 0; $i < 14; $i++) {
                $titikUkur = $titikUkurArray[$i] ?? '';
                $ulangan01 = $ulangan01Array[$i] ?? '';
                $ulangan02 = $ulangan02Array[$i] ?? '';
                $ulangan03 = $ulangan03Array[$i] ?? '';
                $ulangan04 = $ulangan04Array[$i] ?? '';
                $ulangan05 = $ulangan05Array[$i] ?? '';
                
                $hasData = !empty(trim($titikUkur)) || 
                          !empty(trim($ulangan01)) || 
                          !empty(trim($ulangan02)) || 
                          !empty(trim($ulangan03)) || 
                          !empty(trim($ulangan04)) || 
                          !empty(trim($ulangan05));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'ulangan01' => !empty($ulangan01) ? str_replace(',', '.', $ulangan01) : null,
                        'ulangan02' => !empty($ulangan02) ? str_replace(',', '.', $ulangan02) : null,
                        'ulangan03' => !empty($ulangan03) ? str_replace(',', '.', $ulangan03) : null,
                        'ulangan04' => !empty($ulangan04) ? str_replace(',', '.', $ulangan04) : null,
                        'ulangan05' => !empty($ulangan05) ? str_replace(',', '.', $ulangan05) : null,
                    ];
                    
                    DetailInsideMicrometer::create($detailData);
                    $totalDetailCount++;
                }
            }
        }
        
        \Log::info("✅ Saved {$totalDetailCount} detail measurements");
        
        // ==================================================================
        // 3. UPDATE FIELD LAINNYA DI CALIBRATION (HANYA DATA YANG TIDAK PER FORM)
        // ==================================================================
        $updateData = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->brandAlat ?? $calibration->brandAlat,
            'kodeAlat' => $request->kodeAlat ?? $calibration->kodeAlat,
            'typeAlat' => $request->typeAlat ?? $calibration->typeAlat,
            'NoSeri' => $request->NoSeri ?? $calibration->NoSeri,
            'pemilikAlat' => $request->pemilikAlat ?? $calibration->pemilikAlat,
            'tanggalMasuk' => $request->tanggalMasuk ?? $calibration->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi ?? $calibration->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $calibration->tempatKalibrasi,
            'jenisPembacaan' => $request->jenisPembacaan ?? $calibration->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT ?? $calibration->lokasiPT,
            'kode_th' => $request->kode_th ?? $calibration->kode_th,
            'kondisiAlat' => $request->kondisiAlat ?? $calibration->kondisiAlat,
            'keterangan' => $request->keterangan ?? $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1 ?? $calibration->RT_condition1,
            'RT_condition2' => $request->RT_condition2 ?? $calibration->RT_condition2,
            'RT_condition3' => $request->RT_condition3 ?? $calibration->RT_condition3,
            'RH_condition1' => $request->RH_condition1 ?? $calibration->RH_condition1,
            'RH_condition2' => $request->RH_condition2 ?? $calibration->RH_condition2,
            'RH_condition3' => $request->RH_condition3 ?? $calibration->RH_condition3,
            'calibratedBy' => $request->calibratedBy ?? $calibration->calibratedBy,
            'verifiedBy' => $request->verifiedBy ?? $calibration->verifiedBy,
            'jumlah_form' => $jumlahForm,
        ];
        
        // Hapus field yang sudah dipindahkan ke Head (tidak perlu disimpan di calibration)
        unset($updateData['rangeMin']);
        unset($updateData['rangeMax']);
        unset($updateData['kapasitas']);
        unset($updateData['resolusi']);
        
        // Hanya update jika ada perubahan nilai
        $calibration->update($updateData);
        
        // Refresh untuk memastikan data terbaru
        $calibration->refresh();
        
        \Log::info('🎉 updateInsideMicrometer completed successfully', [
            'calibration_id' => $calibration->id,
            'details_created' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateInsideMicrometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

 private function updateOutsideMicrometer($request, $calibration, $newCertificateId = null)
{
    \Log::info('🚀 ===== START updateOutsideMicrometer =====', [
        'calibration_id' => $calibration->id,
        'timestamp' => now()->toDateTimeString()
    ]);
    
    try {
        // ==================================================================
        // 0. CEK PERUBAHAN NAMA ALAT UNTUK UPDATE CERTIFICATE ID
        // ==================================================================
        $certificateIdBaru = $newCertificateId;
        $certificateIdUpdated = false;
        
        // Ambil nama alat dari request
        $namaAlatDariRequest = $request->namaAlat ?? $request->nama_alat ?? $calibration->namaAlat;
        
        \Log::info('🔍 CEK NAMA ALAT:', [
            'namaAlat_dari_request' => $namaAlatDariRequest,
            'namaAlat_di_calibration' => $calibration->namaAlat,
            'certificate_id_lama_di_calibration' => $calibration->certificate_id
        ]);
        
        // Cek apakah nama alat berubah
        if ($namaAlatDariRequest != $calibration->namaAlat && !empty($namaAlatDariRequest)) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan diupdate (nama alat berubah):', [
                'old_nama' => $calibration->namaAlat,
                'new_nama' => $namaAlatDariRequest,
                'new_certificate_id' => $certificateIdBaru
            ]);
        } elseif (empty($calibration->certificate_id) || strpos($calibration->certificate_id ?? '', 'MANUAL_INPUT') !== false) {
            $certificateIdBaru = $this->generateCertificateIdFromNamaAlat($namaAlatDariRequest, $calibration);
            $certificateIdUpdated = true;
            
            \Log::info('🆔 Certificate ID akan digenerate (kosong atau MANUAL_INPUT):', [
                'certificate_id_lama' => $calibration->certificate_id,
                'certificate_id_baru' => $certificateIdBaru
            ]);
        }
        
        // Update certificate_id di tabel calibration
        if ($certificateIdUpdated && !empty($certificateIdBaru)) {
            $calibration->update(['certificate_id' => $certificateIdBaru]);
            $calibration->refresh();
            
            \Log::info('📝 UPDATE CERTIFICATE ID DI CALIBRATION:', [
                'certificate_id_baru' => $certificateIdBaru,
                'current_certificate_id' => $calibration->certificate_id
            ]);
        }
        
        // Ambil jumlah form dari request
        $jumlahForm = (int) ($request->jumlah_form ?? $calibration->jumlah_form ?? 1);
        $jumlahForm = max(1, $jumlahForm);
        
        \Log::info('📊 UPDATE Outside Micrometer - Multiple Form', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $jumlahForm,
        ]);
        
        // ==================================================================
        // 1. UPDATE HEAD UNTUK SETIAP FORM (DENGAN FIELD BARU PER FORM)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $head = HeadOutsideMicrometer::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // 🔥 AMBIL DATA DARI REQUEST (PER FORM)
            // Satuan Unit
            $satuanUnit = $request->input("satuan_unit_{$formIndex}", 
                          $request->input("satuan_unit", 'mm'));
            
            // 🔥 RENTANG UKUR MIN & MAX (PER FORM)
            $rentangUkurMin = $request->input("rentang_ukur_min_{$formIndex}", 
                             $request->input("rentang_ukur_min", '0'));
            $rentangUkurMax = $request->input("rentang_ukur_max_{$formIndex}", 
                             $request->input("rentang_ukur_max", ''));
            
            // 🔥 KAPASITAS & RESOLUSI (PER FORM)
            $kapasitas = $request->input("kapasitas_{$formIndex}", 
                        $request->input("kapasitas", ''));
            $resolusi = $request->input("resolusi_{$formIndex}", 
                      $request->input("resolusi", ''));
            
            // 🔥 AMBIL ALAT STANDAR UNTUK FORM INI (MASING-MASING FORM PUNYA SENDIRI)
            $alatStandar = [];
            
            // Coba ambil dari alat_standar_{formIndex}[]
            $alatStandar = $request->input("alat_standar_{$formIndex}", []);
            
            // Jika masih kosong dan ini form 1, coba dari alat_standar biasa (backward compatibility)
            if (empty($alatStandar) && $formIndex == 1) {
                $alatStandar = $request->input('alat_standar', []);
            }
            
            // Pastikan dalam bentuk array
            if (!is_array($alatStandar)) {
                $alatStandar = [$alatStandar];
            }
            
            // Filter nilai kosong
            $alatStandar = array_filter($alatStandar);
            
            // Simpan ke database
            $standardValue = !empty($alatStandar) ? implode(', ', $alatStandar) : '';
            
            $headData = [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
                'calibrationMethod' => 'PAS-IK1102-02 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)',
            ];
            
            \Log::info("📝 Head data untuk form {$formIndex}:", [
                'satuan_unit' => $satuanUnit,
                'rentang_ukur_min' => $rentangUkurMin,
                'rentang_ukur_max' => $rentangUkurMax,
                'kapasitas' => $kapasitas,
                'resolusi' => $resolusi,
                'standard' => $standardValue,
            ]);
            
            // 🔥 UPDATE CERTIFICATE ID UNTUK SEMUA HEAD
            if ($certificateIdUpdated && !empty($certificateIdBaru)) {
                $headData['certificate_id'] = $certificateIdBaru;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex}: {$certificateIdBaru}");
            } elseif ($newCertificateId && !$certificateIdUpdated) {
                $headData['certificate_id'] = $newCertificateId;
                \Log::info("📝 Setting certificate_id untuk head form {$formIndex} dari parameter: {$newCertificateId}");
            }
            
            if ($head) {
                $head->update($headData);
                \Log::info("✅ Head updated for form {$formIndex}", [
                    'head_id' => $head->id,
                    'satuan_unit' => $head->satuan_unit,
                    'rentang_ukur_min' => $head->rentang_ukur_min,
                    'rentang_ukur_max' => $head->rentang_ukur_max,
                    'kapasitas' => $head->kapasitas,
                    'resolusi' => $head->resolusi,
                    'standard' => $head->standard,
                    'certificate_id' => $head->certificate_id ?? 'not_set'
                ]);
            } else {
                $headData['calibration_id'] = $calibration->id;
                $headData['form_index'] = $formIndex;
                $headData['certificate_id'] = $headData['certificate_id'] ?? $certificateIdBaru ?? $calibration->certificate_id ?? 'NEW-' . time();
                $head = HeadOutsideMicrometer::create($headData);
                \Log::info("➕ New head created for form {$formIndex}");
            }
        }
        
        // Hapus head untuk form yang tidak digunakan
        HeadOutsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 2. UPDATE ADD OUTSIDE MICROMETER (UJI KERATAAN) PER FORM
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            $add = AddOutsideMicrometer::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // Ambil data add per form dengan suffix _formIndex
            $addData = [
                'ukuranAnvil1' => $request->input("ukuranAnvil1_{$formIndex}"),
                'jumlahAnvil1' => $request->input("jumlahAnvil1_{$formIndex}"),
                'ukuranAnvil2' => $request->input("ukuranAnvil2_{$formIndex}"),
                'jumlahAnvil2' => $request->input("jumlahAnvil2_{$formIndex}"),
                'ukuranSpindle1' => $request->input("ukuranSpindle1_{$formIndex}"),
                'jumlahSpindle1' => $request->input("jumlahSpindle1_{$formIndex}"),
                'ukuranSpindle2' => $request->input("ukuranSpindle2_{$formIndex}"),
                'jumlahSpindle2' => $request->input("jumlahSpindle2_{$formIndex}"),
            ];
            
            \Log::info("📝 Add data untuk form {$formIndex}:", $addData);
            
            if ($add) {
                $add->update($addData);
                \Log::info("✅ Add data updated for form {$formIndex}", ['add_id' => $add->id]);
            } else {
                $addData['calibration_id'] = $calibration->id;
                $addData['form_index'] = $formIndex;
                AddOutsideMicrometer::create($addData);
                \Log::info("➕ New add data created for form {$formIndex}");
            }
        }
        
        // Hapus add data untuk form yang tidak digunakan
        AddOutsideMicrometer::where('calibration_id', $calibration->id)
            ->where('form_index', '>', $jumlahForm)
            ->delete();
        
        // ==================================================================
        // 3. UPDATE DETAIL MEASUREMENTS (UJI SKALA NOMINAL) PER FORM
        // ==================================================================
        DetailOutsideMicrometer::where('calibration_id', $calibration->id)->delete();
        
        $totalDetailCount = 0;
        
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📊 Processing details for form {$formIndex}");
            
            // Coba ambil data dengan berbagai format (dengan prefix form index)
            $titikUkurArray = $request->input("titikUkur_{$formIndex}", []);
            $ulangan01Array = $request->input("ulangan01_{$formIndex}", []);
            $ulangan02Array = $request->input("ulangan02_{$formIndex}", []);
            $ulangan03Array = $request->input("ulangan03_{$formIndex}", []);
            $ulangan04Array = $request->input("ulangan04_{$formIndex}", []);
            $ulangan05Array = $request->input("ulangan05_{$formIndex}", []);
            
            // Jika tidak ada data dengan format per form, coba ambil dari format array biasa
            if (empty($titikUkurArray)) {
                $titikUkurArray = $request->input("titikUkur", []);
                $ulangan01Array = $request->input("ulangan01", []);
                $ulangan02Array = $request->input("ulangan02", []);
                $ulangan03Array = $request->input("ulangan03", []);
                $ulangan04Array = $request->input("ulangan04", []);
                $ulangan05Array = $request->input("ulangan05", []);
                \Log::info("Using fallback array format for form {$formIndex}");
            }
            
            for ($i = 0; $i < 14; $i++) {
                $titikUkur = $titikUkurArray[$i] ?? '';
                $ulangan01 = $ulangan01Array[$i] ?? '';
                $ulangan02 = $ulangan02Array[$i] ?? '';
                $ulangan03 = $ulangan03Array[$i] ?? '';
                $ulangan04 = $ulangan04Array[$i] ?? '';
                $ulangan05 = $ulangan05Array[$i] ?? '';
                
                $hasData = !empty(trim($titikUkur)) || 
                          !empty(trim($ulangan01)) || 
                          !empty(trim($ulangan02)) || 
                          !empty(trim($ulangan03)) || 
                          !empty(trim($ulangan04)) || 
                          !empty(trim($ulangan05));
                
                if ($hasData) {
                    $detailData = [
                        'calibration_id' => $calibration->id,
                        'form_index' => $formIndex,
                        'titikUkur' => $titikUkur,
                        'ulangan01' => !empty($ulangan01) ? str_replace(',', '.', $ulangan01) : null,
                        'ulangan02' => !empty($ulangan02) ? str_replace(',', '.', $ulangan02) : null,
                        'ulangan03' => !empty($ulangan03) ? str_replace(',', '.', $ulangan03) : null,
                        'ulangan04' => !empty($ulangan04) ? str_replace(',', '.', $ulangan04) : null,
                        'ulangan05' => !empty($ulangan05) ? str_replace(',', '.', $ulangan05) : null,
                    ];
                    
                    DetailOutsideMicrometer::create($detailData);
                    $totalDetailCount++;
                }
            }
        }
        
        \Log::info("✅ Saved {$totalDetailCount} detail measurements for Outside Micrometer");
        
        // ==================================================================
        // 4. UPDATE FIELD LAINNYA DI CALIBRATION
        // ⚠️ JANGAN UPDATE RANGE MIN/MAX, KAPASITAS, RESOLUSI!
        // ==================================================================
        $updateData = [
            'namaAlat' => $namaAlatDariRequest,
            'brandAlat' => $request->brandAlat ?? $calibration->brandAlat,
            'kodeAlat' => $request->kodeAlat ?? $calibration->kodeAlat,
            'typeAlat' => $request->typeAlat ?? $calibration->typeAlat,
            'NoSeri' => $request->NoSeri ?? $calibration->NoSeri,
            'pemilikAlat' => $request->pemilikAlat ?? $calibration->pemilikAlat,
            'tanggalMasuk' => $request->tanggalMasuk ?? $calibration->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi ?? $calibration->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $calibration->tempatKalibrasi,
            'jenisPembacaan' => $request->jenisPembacaan ?? $calibration->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT ?? $calibration->lokasiPT,
            'kode_th' => $request->kode_th ?? $calibration->kode_th,
            'kondisiAlat' => $request->kondisiAlat ?? $calibration->kondisiAlat,
            'keterangan' => $request->keterangan ?? $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1 ?? $calibration->RT_condition1,
            'RT_condition2' => $request->RT_condition2 ?? $calibration->RT_condition2,
            'RT_condition3' => $request->RT_condition3 ?? $calibration->RT_condition3,
            'RH_condition1' => $request->RH_condition1 ?? $calibration->RH_condition1,
            'RH_condition2' => $request->RH_condition2 ?? $calibration->RH_condition2,
            'RH_condition3' => $request->RH_condition3 ?? $calibration->RH_condition3,
            'calibratedBy' => $request->calibratedBy ?? $calibration->calibratedBy,
            'verifiedBy' => $request->verifiedBy ?? $calibration->verifiedBy,
            'jumlah_form' => $jumlahForm,
        ];
        
        // ⚠️ HAPUS FIELD YANG SUDAH DIPINDAHKAN KE HEAD
        unset($updateData['rangeMin']);
        unset($updateData['rangeMax']);
        unset($updateData['kapasitas']);
        unset($updateData['resolusi']);
        
        $calibration->update($updateData);
        
        // Refresh untuk memastikan data terbaru
        $calibration->refresh();
        
        // FINAL VERIFICATION
        $allHeads = HeadOutsideMicrometer::where('calibration_id', $calibration->id)->get();
        $allAdd = AddOutsideMicrometer::where('calibration_id', $calibration->id)->get();
        $allDetails = DetailOutsideMicrometer::where('calibration_id', $calibration->id)->get();
        
        \Log::info('🎯 FINAL SUMMARY AFTER UPDATE:', [
            'total_heads' => $allHeads->count(),
            'heads_by_form' => $allHeads->groupBy('form_index')->map->count(),
            'total_add' => $allAdd->count(),
            'add_by_form' => $allAdd->groupBy('form_index')->map->count(),
            'total_details' => $allDetails->count(),
            'details_by_form' => $allDetails->groupBy('form_index')->map->count(),
            'jumlah_form' => $jumlahForm,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        \Log::info('🎉 updateOutsideMicrometer completed successfully', [
            'calibration_id' => $calibration->id,
            'details_created' => $totalDetailCount,
            'jumlah_form' => $jumlahForm,
            'certificate_id_updated' => $certificateIdUpdated,
            'certificate_id_final' => $certificateIdBaru ?? $calibration->certificate_id
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 updateOutsideMicrometer FAILED:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

   public function index(Request $request)
{
    canOrFail('super admin,teknisi,approver,checker');
    $perPageInput = $request->get('perPage', 5); // Default 5 data per halaman
    $perPage = $perPageInput === 'all' ? 1000000 : $perPageInput;
    
    // Buat query builder
    $query = Calibration::with([
        'headInsideMicrometer', 
        'detailInsideMicrometers',
        'headOutsideMicrometer',
        'detailOutsideMicrometers',
        'addOutsideMicrometer',
        'detailDepthMicrometers',
        'headDepthMicrometer',
        'headThermometer',
        'detailThermometers',
        'headDialIndicator',
        'detailDialIndicators',
        'AddDialIndicator',
        'headDialTestIndicator',
        'detailDialTestIndicators',
        'AddDialTestIndicator',
        'headDepthCaliper',
        'detailDepthCalipers',
        'headCaliper',
        'detailCalipers',
        'addCaliper',
        'headTorqueWrench',
        'detailTorqueWrenchs',
        'addTorqueWrench',
        'headTorqueMeter',
        'detailTorqueMeters',
        'addTorqueMeter',
        'headThicknessGauge',
        'detailThicknessGauges',
        'headPenggaris',
        'detailPenggaris',
        'headEnclosure',
        'detailEnclosures',
        'addEnclosure',
        'headChamber',
        'detailChambers',
        'addChamber',
        'headPressureGauge',
        'detailPressureGauges',
        'addPressureGauge',
        'headDifferentialPressureGauge',
        'detailDifferentialPressureGauges',
        'addDifferentialPressureGauge',
        'headVolumetrik',
        'detailVolumetriks',
        'addVolumetrik',
        'headPushPull',
        'detailPushPulls',
        'addPushPull',
        'headAbrationTester',
        'detailAbrationTesters',
    ]);
    
    // Filter berdasarkan status dari request (hanya berlaku jika user bukan role terbatas)
    $requestedStatus = $request->input('status');
    if (!empty($requestedStatus)) {
        if (!in_array(auth()->user()->role, ['teknisi', 'checker', 'approver'])) {
            $query->where('status', $requestedStatus);
        }
    }

    // FILTER BERDASARKAN ROLE
    $user = auth()->user();
    
    // Jika role adalah teknisi, filter berdasarkan calibratedBy dan HANYA status draft
    if ($user->role === 'teknisi') {
        $namaTeknisi = $user->nama ?? $user->name;
        
        $query->where('calibratedBy', $namaTeknisi)
              ->where('status', 'draft');
        
        \Log::info("Teknisi login: {$namaTeknisi} - Menampilkan data kalibrasi draft miliknya");
    }
    
    
     // JIKA ROLE ADALAH CHECKER - MELIHAT STATUS waiting_verification DAN rejected
    if ($user->role === 'checker') {
        if (!empty($requestedStatus) && in_array($requestedStatus, ['waiting_verification', 'rejected'])) {
            $query->where('status', $requestedStatus);
        } else {
            $query->whereIn('status', ['waiting_verification', 'rejected']);
        }
    }
    
    // JIKA ROLE ADALAH APPROVER - MELIHAT STATUS verified DAN approved
    if ($user->role === 'approver') {
        if (!empty($requestedStatus) && in_array($requestedStatus, ['verified', 'approved'])) {
            $query->where('status', $requestedStatus);
        } else {
            $query->whereIn('status', ['verified', 'approved']);
        }
    }
    
    // Filter berdasarkan pencarian (jika ada)
    if ($request->has('search') && !empty($request->search)) {
        $search = $request->search;
        $query->where(function($q) use ($search) {
            $q->where('namaAlat', 'like', '%' . $search . '%')
              ->orWhere('NoSeri', 'like', '%' . $search . '%')
              ->orWhere('brandAlat', 'like', '%' . $search . '%')
              ->orWhere('pemilikAlat', 'like', '%' . $search . '%');
        });
    }
    
    // Filter berdasarkan tanggal (jika ada)
    if ($request->has('date_from') && !empty($request->date_from)) {
        $query->whereDate('tanggalKalibrasi', '>=', $request->date_from);
    }
    
    if ($request->has('date_to') && !empty($request->date_to)) {
        $query->whereDate('tanggalKalibrasi', '<=', $request->date_to);
    }
    
      // 🔥 URUTKAN BERDASARKAN updated_at TERBARU, lalu created_at TERBARU
    // Data yang baru diedit akan muncul di atas, jika sama maka berdasarkan created_at
    $query->orderBy('updated_at', 'desc')
          ->orderBy('created_at', 'desc');
          
    // Urutkan dan paginasi
    $calibrations = $query->orderBy('created_at', 'desc')
        ->paginate($perPage)
        ->withQueryString(); // Menjaga parameter query string
    
    return view('calibrations.index', compact('calibrations'));
}

 /**
     * Export kalibrasi ke PDF per row
     */
    public function exportPdf($id, Request $request)
    {
        try {
            $calibration = Calibration::findOrFail($id);
            $formType = $this->getAlatType($calibration->namaAlat);
            
            // Generate relation names
            $headModelName = 'head' . str_replace(' ', '', ucwords(str_replace('_', ' ', $formType)));
            $detailModelName = 'detail' . str_replace(' ', '', ucwords(str_replace('_', ' ', $formType))) . 's';
            $addModelName = 'add' . str_replace(' ', '', ucwords(str_replace('_', ' ', $formType)));
            
            $relations = [];
            if (method_exists($calibration, $headModelName)) $relations[] = $headModelName;
            if (method_exists($calibration, $detailModelName)) {
                $relations[$detailModelName] = function($query) { $query->orderBy('id', 'asc'); };
            }
            if (method_exists($calibration, $addModelName)) {
                $relations[$addModelName] = function($query) { $query->orderBy('id', 'asc'); };
            }
            
            $calibration->load($relations);
            
            // Load subform relations if any
            $savedSubforms = self::getSavedSubforms($calibration->id, $formType);
            foreach ($savedSubforms as $subType) {
                $subHead = 'head' . str_replace(' ', '', ucwords(str_replace('_', ' ', $subType)));
                $subDetail = 'detail' . str_replace(' ', '', ucwords(str_replace('_', ' ', $subType))) . 's';
                $subAdd = 'add' . str_replace(' ', '', ucwords(str_replace('_', ' ', $subType)));
                $subRelations = [];
                if (method_exists($calibration, $subHead)) $subRelations[] = $subHead;
                if (method_exists($calibration, $subDetail)) {
                    $subRelations[$subDetail] = function($query) { $query->orderBy('id', 'asc'); };
                }
                if (method_exists($calibration, $subAdd)) {
                    $subRelations[$subAdd] = function($query) { $query->orderBy('id', 'asc'); };
                }
                $calibration->load($subRelations);
            }

            $mode = 'view';
            $viewName = 'formhtml.' . $formType . '_view';
            
            if ($formType == 'insulation') {
                if (str_contains(strtolower($calibration->namaAlat), 'clamp')) {
                    $viewName = 'formhtml.clampmeter_view';
                } else {
                    $viewName = 'formhtml.multimeter_view';
                }
            }

            if (!view()->exists($viewName)) {
                return back()->with('error', 'Template PDF untuk alat ini belum tersedia.');
            }

           
            // Render view to HTML
            $html = view($viewName, compact('calibration', 'formType', 'mode'))->render();
            // Remove Font Awesome to prevent DomPDF stream error
            $html = preg_replace('/<link[^>]*font-awesome[^>]*>/i', '', $html);

            // Ganti unicode checkbox dengan teks ASCII agar dirender sempurna oleh DomPDF
            // Menggunakan font DejaVu Sans yang mensupport karakter unicode checkmark (✓)
            $checkMark = '<strong style="font-family: \'DejaVu Sans\', sans-serif;">[&#10003;]</strong>';
            $uncheckMark = '[ &nbsp; ]';

            // Hanya replace karakter centang (✓, ☑, ✅) dan kotak kosong (□, ☐, ⬜)
            $html = str_replace(['☑', '✅', '✓', '✔'], $checkMark, $html);
            $html = str_replace(['☐', '⬜', '□'], $uncheckMark, $html);

            // Ganti logo cetak ke pgp_pas_basic.png
            $html = str_replace('/logo/logo_pas_basic.png', '/logo/pgp_pas_basic.png', $html);

            // Ganti radio/checkbox checked dengan checkmark
            $html = preg_replace('/<input(?=[^>]*checked)(?=[^>]*type=[\'"](?:radio|checkbox)[\'"])[^>]*>/i', ' ' . $checkMark . ' ', $html);
            // Ganti radio/checkbox unchecked dengan kotak kosong
            $html = preg_replace('/<input[^>]*type=[\'"](?:radio|checkbox)[\'"][^>]*>/i', ' ' . $uncheckMark . ' ', $html);

            // Inject custom CSS to make it look like a printed document and hide UI elements
            $css = '
            <style>
                @page { margin: 10px 15px; }
                body { font-family: sans-serif; font-size: 8.5px; line-height: 1.0; background: #fff !important; color: #000 !important; }
                /* Sembunyikan elemen UI yang tidak perlu */
                button, .btn, a, i, .fa, .fas, .far, .badge, .d-none, .d-sm-inline-block, .action-btn, #btnSimpanSemua, .central-action-row { display: none !important; }
                /* Hilangkan border pada input agar terlihat seperti teks biasa */
                input, select, textarea, .form-control, .kalibrasi-input, .kondisi-input { 
                    border: none !important; 
                    background: transparent !important; 
                    box-shadow: none !important; 
                    padding: 0 !important; 
                    margin: 0 !important; 
                    color: #000 !important; 
                    width: 100% !important;
                    height: auto !important;
                    text-overflow: clip !important;
                    font-size: 8px !important;
                }
                /* Rapihkan tabel */
                table { width: 100% !important; border-collapse: collapse !important; table-layout: fixed !important; margin-bottom: 2px !important; }
                table, th, td { border: 1px solid #000 !important; padding: 1px 2px !important; color: #000 !important; vertical-align: middle; word-wrap: break-word; font-size: 8px !important; }
                th { background-color: #e9ecef !important; font-weight: bold; text-align: center; }
                /* Sembunyikan thead yang tidak memiliki konten / duplikat */
                thead th { border-bottom: 1px solid #000 !important; }
                /* Hapus styling box/card */
                .card, .card-header, .card-body, .container, .container-fluid, .row { 
                    border: none !important; padding: 0 !important; margin: 0 !important; box-shadow: none !important; width: 100% !important;
                }
                /* Grid fallback untuk DomPDF */
                .col-12, .col-md-12, .col-md-8, .col-md-6, .col-6, .col-sm-6, .col-md-4, .col-md-3, .col-md-2 { 
                    display: inline-block; vertical-align: top; margin: 0; padding: 0 1px;
                }
                .col-12, .col-md-12 { width: 100%; }
                .col-md-8 { width: 66%; }
                .col-md-6, .col-6, .col-sm-6 { width: 49%; }
                .col-md-4 { width: 32%; }
                .col-md-3 { width: 24%; }
                .col-md-2 { width: 16%; }
                
                /* Fix label margin */
                .form-check-label, label { margin: 0 !important; padding: 0 !important; font-weight: bold; }
                .form-check-inline { display: inline-block; margin-right: 6px; }
                .form-check { display: inline-block; margin-right: 6px; }
                h1, h2, h3, h4, h5, h6 { font-size: 9px !important; font-weight: bold !important; margin: 1px 0 !important; text-align: center; }
                .text-center { text-align: center !important; }
                .fw-bold { font-weight: bold !important; }
                .data-kalibrasi-header { background: #e9ecef; border: 1px solid #000; padding: 2px; text-align: center; font-weight: bold; margin-bottom: 2px; font-size: 9px !important; }
                .kalibrasi-section-header { font-weight: bold; border-bottom: 1px solid #000; margin-bottom: 2px; padding-bottom: 1px; text-align: center; font-size: 9px !important; }
            </style>';

            // Insert CSS into head
            if (strpos($html, '</head>') !== false) {
                $html = str_replace('</head>', $css . '</head>', $html);
            } else {
                $html = $css . $html;
            }

            $pdf = \Barryvdh\DomPDF\Facade\Pdf::loadHTML($html);
            $certificateId = 'Kalibrasi';
            if ($calibration->$headModelName && isset($calibration->$headModelName->certificate_id)) {
                $certificateId = $calibration->$headModelName->certificate_id;
            } else {
                $certificateId = $calibration->certificate_id ?? $certificateId;
            }

            $fileName = $certificateId . '_' . str_replace(' ', '_', $calibration->namaAlat) . '.pdf';
            $fileName = preg_replace('/[^A-Za-z0-9_\-\.]/', '_', $fileName);

            return $pdf->download($fileName);

        } catch (\Exception $e) {
            \Log::error('Error generate PDF: ' . $e->getMessage());
            return back()->with('error', 'Gagal menghasilkan PDF: ' . $e->getMessage());
        }
    }

    
