    public function edit($id)
    {
        $calibration = Calibration::with([
            'headInsideMicrometer', 
            'detailInsideMicrometers',
            'headOutsideMicrometer',
            'detailOutsideMicrometers',
            'addOutsideMicrometer',
            'detailDepthMicrometers',
            'headDepthMicrometer',
            'headThermometer',
            'detailThermometers',
            'headDialIndicator',
            'detailDialIndicators',
            'AddDialIndicator',
            'headDialTestIndicator',
            'detailDialTestIndicators',
            'AddDialTestIndicator',
            'headDepthCaliper',
            'detailDepthCalipers',
            'headCaliper',
            'detailCalipers',
            'addCaliper',
            'headTorqueWrench',
            'detailTorqueWrenchs',
            'addTorqueWrench',
            'headTorqueMeter',
            'detailTorqueMeters',
            'addTorqueMeter',
            'headThicknessGauge',
            'detailThicknessGauges',
            'headPenggaris',
            'detailPenggaris',
            'headEnclosure',
            'detailEnclosures',
            'addEnclosure',
            'headChamber',
            'detailChambers',
            'addChamber',
            'headPressureGauge',
            'detailPressureGauges',
            'addPressureGauge',
            'headDifferentialPressureGauge',
            'detailDifferentialPressureGauges',
            'addDifferentialPressureGauge',
            'headVolumetrik',
            'detailVolumetriks',
            'addVolumetrik',
            'headPushPull',
            'detailPushPulls',
            'addPushPull',
            'headBoreGauge',
            'detailBoreGauges',
            'addBoreGauge',
            'headAbrationTester',
            'detailAbrationTesters',
        ])->findOrFail($id);
            
        return view('calibrations.edit', compact('calibration'));
    }

