public function update(Request $request, $id)
{
    \Log::info('🎯 ===== UPDATE METHOD CALLED =====', [
        'calibration_id' => $id,
        'user' => auth()->user()->nama ?? 'unknown',
        'timestamp' => now()->toDateTimeString(),
        'ip' => request()->ip()
    ]);
    
    \Log::info('📦 REQUEST DATA SAMPLE:', [
        'namaAlat' => $request->namaAlat ?? 'not_set',
        'nama_alat_select' => $request->nama_alat_select ?? 'not_set',
        'nama_alat_manual' => $request->nama_alat_manual ?? 'not_set',
        'brandAlat' => $request->brandAlat ?? 'not_set',
        'NoSeri' => $request->NoSeri ?? 'not_set',
        'calibratedBy' => $request->calibratedBy ?? 'not_set',
        'alat_standar_count' => is_array($request->alat_standar) ? count($request->alat_standar) : 0,
        'titikUkur_count' => is_array($request->titikUkur) ? count($request->titikUkur) : 0,
        'has_files' => $request->hasFile('files') ? 'yes' : 'no'
    ]);
    
    \Log::info('📋 FORM TYPE FROM REQUEST:', [
        'form_type' => $request->form_type ?? 'not_set',
        'form_type_exists' => $request->has('form_type'),
        'form_type_value' => $request->input('form_type')
    ]);
    
    \Log::debug('🔍 FULL REQUEST DATA DUMP:', $request->all());
    
    \Log::info('🔥 RAW NAMA ALAT:', ['value' => $request->input('namaAlat')]);
    
    try {
        $calibration = Calibration::findOrFail($id);
        
        \Log::info('🔍 CALIBRATION FOUND:', [
            'id' => $calibration->id,
            'id_alat' => $calibration->id_alat,
            'current_namaAlat' => $calibration->namaAlat,
            'current_form_type' => $calibration->form_type,
            'current_certificate_id' => $calibration->certificate_id,
            'current_status' => $calibration->status,
            'created_at' => $calibration->created_at
        ]);
        
        // ==================================================================
        // 1. PASTIKAN ID_ALAT TIDAK BERUBAH
        // ==================================================================
        \Log::info('🔒 ID dan id_alat tetap:', [
            'id' => $calibration->id,
            'id_alat' => $calibration->id_alat
        ]);
        
        // ==================================================================
        // 2. TENTUKAN NAMA ALAT YANG BARU DARI BERBAGAI SUMBER
        // ==================================================================
        $namaAlatBaru = $calibration->namaAlat;
        
        // Priority 1: Hidden input namaAlat (sudah diproses JavaScript)
        if ($request->has('namaAlat') && !empty($request->namaAlat)) {
            $namaAlatBaru = $request->namaAlat;
            \Log::info('📝 Nama alat dari hidden input:', ['nama' => $namaAlatBaru]);
        }
        // Priority 2: Input manual
        elseif ($request->has('nama_alat_manual') && !empty($request->nama_alat_manual)) {
            $namaAlatBaru = $request->nama_alat_manual;
            \Log::info('📝 Nama alat dari input manual:', ['nama' => $namaAlatBaru]);
        }
        // Priority 3: Dropdown (bukan MANUAL_INPUT)
        elseif ($request->filled('nama_alat_select') && $request->nama_alat_select !== 'MANUAL_INPUT') {
            $namaAlatBaru = $request->nama_alat_select;
            \Log::info('📝 Nama alat dari dropdown:', ['nama' => $namaAlatBaru]);
        }
        
        // ==================================================================
        // 3. TENTUKAN FORM TYPE YANG AKAN DIGUNAKAN
        // ==================================================================
        $formTypeFromRequest = $request->form_type;
        $formTypeFromDatabase = $calibration->form_type;
        
        \Log::info('📊 FORM TYPE SOURCES:', [
            'from_request' => $formTypeFromRequest,
            'from_database' => $formTypeFromDatabase,
            'nama_alat' => $namaAlatBaru
        ]);
        
       // ==================================================================
        // 4. PERBARUI/SINKRONKAN CERTIFICATE ID UNTUK UPDATE DATA
        // ==================================================================
        $certificateId = $this->generateCertificateIdFromNamaAlat($namaAlatBaru, $calibration);
        $certificateUpdated = true;
        
        \Log::info('🆔 Certificate ID disinkronkan saat update:', [
            'nama_alat' => $namaAlatBaru,
            'old_certificate_id' => $calibration->certificate_id,
            'new_certificate_id' => $certificateId
        ]);
        
        
        // ==================================================================
        // 5. VALIDASI REQUEST DATA
        // ==================================================================
        $validated = $request->validate([
            'namaAlat' => 'nullable',
            'brandAlat' => 'nullable',
            'kodeAlat' => 'nullable',
            'typeAlat' => 'nullable',
            'NoSeri' => 'nullable',
            'kapasitas' => 'nullable',
            'resolusi' => 'nullable',
            'rangeMin' => 'nullable',
            'rangeMax' => 'nullable',
            'pemilikAlat' => 'nullable',
            'tanggalMasuk' => 'nullable|date',
            'tanggalKalibrasi' => 'nullable|date',
            'jenisPembacaan' => 'nullable',
            'tempatKalibrasi' => 'nullable',
            'lokasiPT' => 'nullable',
            'kondisiAlat' => 'nullable',
            'keterangan' => 'nullable',
            'RT_condition1' => 'nullable',
            'RT_condition2' => 'nullable',
            'RT_condition3' => 'nullable',
            'RH_condition1' => 'nullable',
            'RH_condition2' => 'nullable',
            'RH_condition3' => 'nullable',
            'alat_standar' => 'nullable|array',
            'alat_standar.*' => 'string',
            'calibratedBy' => 'nullable',
            'verifiedBy' => 'nullable',
            'kode_th' => 'nullable',
        ]);
        
        \Log::info('✅ VALIDATION PASSED FOR UPDATE');
        
        // Log alat standar yang dipilih
        $alatStandar = $request->alat_standar ?? [];
        \Log::info('🔧 ALAT STANDAR SELECTED:', [
            'count' => count($alatStandar),
            'items' => $alatStandar,
            'string' => implode(', ', $alatStandar)
        ]);
        
        // ==================================================================
        // 6. UPDATE DATA DASAR CALIBRATION
        // ==================================================================
        $calibrationData = [
            'namaAlat' => $namaAlatBaru,
            'brandAlat' => $request->brandAlat,
            'kodeAlat' => $request->kodeAlat,
            'typeAlat' => $request->typeAlat,
            'NoSeri' => $request->NoSeri,
            'kapasitas' => $request->kapasitas,
            'resolusi' => $request->resolusi,
            'rangeMin' => $request->rangeMin,
            'rangeMax' => $request->rangeMax,
            'pemilikAlat' => $request->pemilikAlat,
             'no_po' => $request->has('no_po') ? $request->no_po : ($calibration->no_po ?? null),
            'tanggalMasuk' => $request->tanggalMasuk,
            'tanggalKalibrasi' => $request->tanggalKalibrasi,
            'tempatKalibrasi' => $request->tempatKalibrasi ?? $request->tempatKalibrasi_1 ?? $request->tempat_kalibrasi_1 ?? $request->tempat_kalibrasi ?? $calibration->tempatKalibrasi ?? 'lab.PT PAS',
            'kondisiAlat' => $request->kondisiAlat ?? $request->kondisiAlat_1 ?? $request->kondisi_alat_1 ?? $calibration->kondisiAlat ?? 'ok',
            'keterangan' => $request->keterangan ?? $request->keterangan_fungsi_komponen_1 ?? $calibration->keterangan,
            'RT_condition1' => $request->RT_condition1,
            'RT_condition2' => $request->RT_condition2,
            'RT_condition3' => $request->RT_condition3,
            'RH_condition1' => $request->RH_condition1,
            'RH_condition2' => $request->RH_condition2,
            'RH_condition3' => $request->RH_condition3,
            'calibratedBy' => $request->calibratedBy,
            'verifiedBy' => $request->verifiedBy,
            'jenisPembacaan' => $request->jenisPembacaan,
            'lokasiPT' => $request->lokasiPT,
            'kode_th' => $request->kode_th,
        ];
        
        // Tambahkan certificate_id jika berubah
        if ($certificateUpdated && !empty($certificateId)) {
            $calibrationData['certificate_id'] = $certificateId;
        }
        
        \Log::info('📝 UPDATING CALIBRATION BASIC DATA:', [
            'nama_alat_lama' => $calibration->namaAlat,
            'nama_alat_baru' => $namaAlatBaru,
            'certificate_updated' => $certificateUpdated ? 'Yes' : 'No',
            'certificate_id' => $certificateId,
            'data_sample' => [
                'NoSeri' => $request->NoSeri,
                'tanggalKalibrasi' => $request->tanggalKalibrasi,
                'calibratedBy' => $request->calibratedBy
            ]
        ]);
        // ==================================================================
        // 🔥 CAPTURE SUBFORM IDENTITIES IN EDIT MODE
        // ==================================================================
        if ($request->form_type && $request->form_type !== $calibration->form_type) {
            if ($request->input('use_custom_identity') == '1' || $request->input("subform_identities_enabled") == '1' || true) { // Always capture if it's subform
                $existingIdentities = json_decode($calibration->subform_identities, true) ?? [];
                $subType = $request->form_type;
                
                $subIdData = [];
                $identityFields = [
                    'nama_alat', 'nama_alat_final', 'merek', 'kode_alat', 'type_alat', 'no_seri', 
                    'kapasitas', 'resolusi', 'rentang_ukur_max', 'rentang_ukur_min', 'rangeMax', 'rangeMin',
                    'nama_pemilik', 'no_po', 'tanggal_alat_masuk', 'tanggal_kalibrasi', 
                    'jenis_pembacaan', 'tempat_kalibrasi', 'lokasi_pt', 'kode_th', 
                    'fungsi_komponen', 'keterangan_fungsi_komponen', 
                    'suhu_awal', 'suhu_tengah', 'suhu_akhir', 
                    'rh_awal', 'rh_tengah', 'rh_akhir', 
                    'calibrated_by', 'verified_by'
                ];
                
                $requestData = $request->all();
                foreach ($identityFields as $field) {
                    if (array_key_exists($field, $requestData)) {
                        $subIdData[$field] = $requestData[$field];
                    }
                }
                if (!empty($subIdData)) {
                    $existingIdentities[$subType] = $subIdData;
                    $calibration->update(['subform_identities' => json_encode($existingIdentities)]);
                    \Log::info("📝 Extracted subform identities for {$subType} (UPDATE MODE):", $subIdData);
                }
            } elseif ($request->input('use_custom_identity') == '0') {
                $existingIdentities = json_decode($calibration->subform_identities, true) ?? [];
                if (isset($existingIdentities[$request->form_type])) {
                    unset($existingIdentities[$request->form_type]);
                    $calibration->update(['subform_identities' => json_encode($existingIdentities)]);
                }
            }
            \Log::info('Skipping basic data update because request is for a subform', ['form_type' => $request->form_type]);
        } else {
            // UPDATE CALIBRATION (Only for main form)
            $updateResult = $calibration->update($calibrationData);
            
            // Refresh untuk memastikan data terbaru
            $calibration->refresh();
            
            \Log::info('✅ CALIBRATION BASIC DATA UPDATED', [
                'rows_affected' => $updateResult ? 1 : 0,
                'new_namaAlat' => $calibration->namaAlat,
                'new_certificate_id' => $calibration->certificate_id,
                'new_status' => $calibration->status,
                'id_alat_tetap' => $calibration->id_alat
            ]);
        }

        // ==================================================================
        // 7. TENTUKAN FORM TYPE FINAL
        // ==================================================================
        $formType = $this->getAlatType(
            $namaAlatBaru,
            $formTypeFromRequest ?? $formTypeFromDatabase
        );
        
        \Log::info('🔧 FORM TYPE DETECTED:', [
            'namaAlat_baru' => $namaAlatBaru,
            'detected_type' => $formType,
            'from_request' => $formTypeFromRequest,
            'from_database' => $formTypeFromDatabase,
            'detection_method' => 'getAlatType'
        ]);
        
        // Update form_type di database jika berbeda
        if ($calibration->form_type !== $formType) {
            $calibration->update(['form_type' => $formType]);
            \Log::info('🔄 Form type diupdate di database:', [
                'old' => $calibration->getOriginal('form_type'),
                'new' => $formType
            ]);
        }

             // ==================================================================
            // 8. PANGGIL METODE UPDATE SPESIFIK
            // ==================================================================
            switch($formType) {
                case 'inside_micrometer':
                    \Log::info('🎯 CALLING updateInsideMicrometer');
                    $this->updateInsideMicrometer($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'outside_micrometer':
                    \Log::info('🎯 CALLING updateOutsideMicrometer');
                    $this->updateOutsideMicrometer($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'depth_micrometer':
                    \Log::info('🎯 CALLING updateDepthMicrometer');
                    $this->updateDepthMicrometer($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'thermometer':
                    \Log::info('🎯 CALLING updateThermometer');
                    $this->updateThermometer($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'dial_indicator':
                    \Log::info('🎯 CALLING updateDialIndicator');
                    $this->updateDialIndicator($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'dial_test_indicator':
                    \Log::info('🎯 CALLING updateDialTestIndicator');
                    $this->updateDialTestIndicator($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'depth_caliper':
                    \Log::info('🎯 CALLING updateDepthCaliper');
                    $this->updateDepthCaliper($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'caliper':
                    \Log::info('🎯 CALLING updateCaliper');
                    $this->updateCaliper($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'torque_wrench':
                    \Log::info('🎯 CALLING updateTorqueWrench');
                    $this->updateTorqueWrench($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'torque_meter':
                    \Log::info('🎯 CALLING updateTorqueMeter');
                    $this->updateTorqueMeter($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'thickness_gauge':
                    \Log::info('🎯 CALLING updateThicknessGauge');
                    $this->updateThicknessGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'penggaris':
                    \Log::info('🎯 CALLING updatePenggaris');
                    $this->updatePenggaris($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'enclosure':
                    \Log::info('🎯 CALLING updateEnclosure');
                    $this->updateEnclosure($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'chamber':
                    \Log::info('🎯 CALLING updateClimaticChamber');
                    $this->updateClimaticChamber($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'pressure_gauge':
                    \Log::info('🎯 CALLING updatePressureGauge');
                    $this->updatePressureGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'differential_pressure_gauge':
                    \Log::info('🎯 CALLING updateDifferentialPressureGauge');
                    $this->updateDifferentialPressureGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'thermohygrometer':
                    \Log::info('🎯 CALLING updateThermohygrometer');
                    $this->updateThermohygrometer($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'volumetrik':
                    \Log::info('🎯 CALLING updateVolumetrik');
                    $this->updateVolumetrik($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                case 'viscometer':
                    \Log::info('🎯 CALLING updateViscometer');
                    $this->updateViscometer($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'push_pull':
                    \Log::info('🎯 CALLING updatePushPull');
                    $this->updatePushPull($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                        
                case 'timbangan':
                    \Log::info('🎯 CALLING updateTimbangan');
                    $this->updateTimbangan($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'timbangan_moisture':
                    \Log::info('🎯 CALLING updateTimbanganMoisture');
                    $this->updateTimbanganMoisture($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'timbangan_bias':
                    \Log::info('🎯 CALLING updateTimbanganBias');
                    $this->updateTimbanganBias($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'gauge_block':
                    \Log::info('🎯 CALLING updateGaugeBlock');
                    $this->updateGaugeBlock($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'holetest':
                    \Log::info('🎯 CALLING updateHoletest');
                    $this->updateHoletest($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'conductivity_meter':
                    \Log::info('🎯 CALLING updateConductivityMeter');
