                case 'pin_gauge':
                    \Log::info('🎯 CALLING updatePinGauge');
                    $this->updatePinGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'profil_projector':
                    \Log::info('🎯 CALLING updateProfilProjector');
                    $this->updateProfilProjector($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'thread_gauge':
                    \Log::info('🎯 CALLING updateThreadGauge');
                    $this->updateThreadGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'pressure_transmitter':
                    \Log::info('🎯 CALLING updatePressureTransmitter');
                    $this->updatePressureTransmitter($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'ultrasonic_thickness_gauge':
                    \Log::info('🎯 CALLING updateUltrasonicThicknessGauge');
                    $this->updateUltrasonicThicknessGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'temperature_transmitter':
                    \Log::info('🎯 CALLING updateTempTransmitter');
                    $this->updateTempTransmitter($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'anak_timbangan':
                    \Log::info('🎯 CALLING updateAnakTimbangan');
                    $this->updateAnakTimbangan($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                           
                case 'utm':
                    \Log::info('🎯 CALLING updateUtm');
                    $this->updateUtm($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'thermoindicator':
                    \Log::info('🎯 CALLING updateThermoIndicator');
                    $this->updateThermoIndicator($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;   
                    
                case 'abration_tester':
                    \Log::info('🎯 CALLING updateAbrationTester');
                    $this->updateAbrationTester($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'height_gauge':
                    \Log::info('🎯 CALLING updateHeightGauge');
                    $this->updateHeightGauge($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                    
                case 'insulation':
                    \Log::info('🎯 CALLING updateInsulation');
                    $this->updateInsulation($request, $calibration, $certificateUpdated ? $certificateId : null);
                    break;
                     
                     
                default:
                    \Log::warning('⚠️ UNKNOWN FORM TYPE:', [
                        'formType' => $formType,
                        'namaAlat' => $namaAlatBaru
                    ]);
                    break;
            }

            // ==================================================================
            // UPDATE FORM TAMBAHAN (SUBFORMS)
            // ==================================================================
            // 🔥 FIX: Hanya kelola subform JIKA request benar-benar mengirim 'additional_forms'
            // Ini mencegah data subform existing terhapus saat user update form utama saja
            $hasAdditionalFormsInput = $request->has('additional_forms');
            
            if (!$hasAdditionalFormsInput) {
                \Log::info('ℹ️ [SKIP SUBFORM MANAGEMENT] additional_forms tidak dikirim di request. Subform existing dipertahankan.', [
                    'calibration_id' => $calibration->id,
                    'existing_subforms' => self::getSavedSubforms($calibration->id, $calibration->form_type)
                ]);
            } else {
                $submittedSubforms = $request->input('additional_forms', []);
                if (!is_array($submittedSubforms)) {
                    $submittedSubforms = !empty($submittedSubforms) ? [$submittedSubforms] : [];
                }
                
                $savedSubforms = self::getSavedSubforms($calibration->id, $calibration->form_type);
                
                \Log::info('🔄 [SUBFORM MANAGEMENT] Processing subforms', [
                    'calibration_id' => $calibration->id,
                    'submitted' => $submittedSubforms,
                    'saved' => $savedSubforms,
                ]);
                
                // Hapus subform yang tidak ada di request (user memang menghapus subform ini)
                foreach ($savedSubforms as $savedType) {
                    if (!in_array($savedType, $submittedSubforms)) {
                        \Log::info("🗑️ Removing subform (user action): {$savedType} for calibration ID: {$calibration->id}");
                        self::deleteSubformData($calibration->id, $savedType);
                    }
                }
                
                \App\Models\Calibration::$preventUpdating = true;
                try {
                    foreach ($submittedSubforms as $subFormType) {
                        if (empty($subFormType) || $subFormType === $calibration->form_type) {
                            continue;
                        }
                        
                        $registry = self::$formRegistry[$subFormType] ?? null;
                        if (!$registry) {
                            \Log::warning("⚠️ Subform type tidak terdaftar: {$subFormType}");
                            continue;
                        }
                        
                        $hasRecord = in_array($subFormType, $savedSubforms);
                        
                        if ($hasRecord) {
                            $updateMethod = $registry['update_method'] ?? null;
                            if ($updateMethod && method_exists($this, $updateMethod)) {
                                \Log::info("🔄 Updating existing subform: {$subFormType}");
                                try {
                                    $this->$updateMethod($request, $calibration, $certificateUpdated ? $certificateId : null);
                                } catch (\Exception $e) {
                                    \Log::error("❌ Error updating subform {$subFormType}: " . $e->getMessage());
                                }
                            }
                        } else {
                            $storeMethod = $registry['store_method'] ?? null;
                            if ($storeMethod && method_exists($this, $storeMethod)) {
                                \Log::info("🆕 Storing new subform: {$subFormType}");
                                $subCertificateId = $this->generateCertificateIdFromNamaAlat(
                                    ucwords(str_replace('_', ' ', $subFormType)), 
                                    $calibration
                                );
                                try {
                                    $this->$storeMethod($request, $calibration, $subCertificateId);
                                    
                                    // 🔥 Update additional_forms di DB setelah store berhasil
                                    $existingForms = $calibration->additional_forms ?? [];
                                    if (is_string($existingForms)) {
                                        $existingForms = json_decode($existingForms, true) ?? [];
                                    }
                                    if (!is_array($existingForms)) {
                                        $existingForms = [];
                                    }
                                    if (!in_array($subFormType, $existingForms)) {
                                        $existingForms[] = $subFormType;
                                        \DB::table('calibrations')
                                            ->where('id', $calibration->id)
                                            ->update(['additional_forms' => json_encode($existingForms)]);
                                    }
                                } catch (\Exception $e) {
                                    \Log::error("❌ Error storing new subform {$subFormType}: " . $e->getMessage());
                                }
                            }
                        }
                    }
                } finally {
                    \App\Models\Calibration::$preventUpdating = false;
                }
            }

        // Refresh lagi setelah update spesifik
        $calibration->refresh();
        
        \Log::info('✅ UPDATE COMPLETED SUCCESSFULLY', [
            'calibration_id' => $id,
            'id_alat' => $calibration->id_alat,
            'nama_alat_sebelum' => $calibration->getOriginal('namaAlat'),
            'nama_alat_sesudah' => $calibration->namaAlat,
            'form_type_final' => $formType,
            'certificate_updated' => $certificateUpdated ? 'Yes' : 'No',
            'certificate_id_final' => $calibration->certificate_id,
            'execution_time' => microtime(true) - LARAVEL_START,
            'memory_usage' => round(memory_get_peak_usage() / 1024 / 1024, 2) . ' MB'
        ]);

        // Log Aktivitas
        LogHelper::log('update', "Mengupdate data kalibrasi: {$calibration->namaAlat} ({$calibration->NoSeri}) - ID: {$calibration->id}", $calibration);
        
          if ($request->ajax() || $request->wantsJson() || $request->input('is_ajax') === 'true' || $request->has('is_ajax')) {
            session()->flash('success', 'Data berhasil disimpan');
            return response()->json([
                'success' => true,
                'message' => 'Data berhasil disimpan',
                'redirect' => route('calibrations.index')
            ]);
        }
        
      // Redirect ke halaman index dengan pesan sukses
    return redirect()->route('calibrations.index')->with('success', 'Data berhasil disimpan');

    } catch (\Illuminate\Validation\ValidationException $e) {
        \Log::error('❌ VALIDATION ERROR:', [
            'errors' => $e->errors(),
            'input' => $request->except(['password', '_token'])
        ]);
        
        return redirect()->back()
            ->withErrors($e->errors())
            ->withInput();
            
    } catch (\Exception $e) {
        \Log::error('💥 UPDATE METHOD ERROR:', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'calibration_id' => $id ?? 'unknown'
        ]);
        
        return redirect()->back()
            ->with('error', 'Terjadi kesalahan: ' . $e->getMessage())
            ->withInput();
    }
}

   /**
 * Remove the specified calibration from storage.
 */
public function destroy($id)
{
    try {
        $calibration = Calibration::findOrFail($id);
        
        \Log::info('🗑️ START DELETE CALIBRATION', [
            'calibration_id' => $calibration->id,
            'nama_alat' => $calibration->namaAlat,
            'no_seri' => $calibration->NoSeri
        ]);

        // ==================================================================
        // 1. LOG PENGHAPUSAN DATA
        // ==================================================================
        \App\Helpers\LogHelper::log('delete', "Menghapus data kalibrasi: {$calibration->namaAlat} ({$calibration->NoSeri}) - ID: {$calibration->id}", $calibration);
        
        // ==================================================================
        // 2. HAPUS DATA FORM UTAMA DAN SUBFORM (BESERTA FILE FISIK)
        // ==================================================================
        if (!empty($calibration->form_type)) {
            self::deleteSubformData($calibration->id, $calibration->form_type);
        }
        
        if (!empty($calibration->additional_forms) && is_array($calibration->additional_forms)) {
            foreach ($calibration->additional_forms as $subformType) {
                self::deleteSubformData($calibration->id, $subformType);
            }
        }
        
        // ==================================================================
        // 3. HAPUS RECORD CALIBRATION DARI DATABASE
        // ==================================================================
        $calibration->delete();
        
        \Log::info('✅ CALIBRATION DELETED SUCCESSFULLY', [
            'calibration_id' => $calibration->id
        ]);

        return redirect()->route('calibrations.index')
            ->with('success', 'Data kalibrasi beserta file gambar/attachment berhasil dihapus!');

    } catch (\Exception $e) {
        \Log::error('💥 ERROR DELETING CALIBRATION:', [
            'calibration_id' => $id ?? 'unknown',
            'error' => $e->getMessage(),
            'trace' => $e->getTraceAsString()
        ]);
        
        return redirect()->route('calibrations.index')
            ->with('error', 'Gagal menghapus data: ' . $e->getMessage());
    }
}


/**
 * Hapus file attachment dari folder public
 */
private function deleteAttachmentFiles($calibration)
{
    try {
        // Cek apakah ada attachment di head_gauge_block
        $headGaugeBlock = HeadGaugeBlock::where('calibration_id', $calibration->id)->first();
        
        if ($headGaugeBlock && $headGaugeBlock->attachment) {
            // Decode JSON attachments
            $attachments = [];
            if (is_string($headGaugeBlock->attachment)) {
                $attachments = json_decode($headGaugeBlock->attachment, true);
            } elseif (is_array($headGaugeBlock->attachment)) {
                $attachments = $headGaugeBlock->attachment;
            }
            
            if (!empty($attachments) && is_array($attachments)) {
                foreach ($attachments as $attachment) {
                    // Path lengkap ke file di public
                    $filePath = public_path($attachment);
                    
                    if (file_exists($filePath)) {
                        @unlink($filePath);
                        \Log::info('🗑️ Attachment file dihapus:', [
                            'file' => $attachment,
                            'calibration_id' => $calibration->id
                        ]);
                    } else {
                        \Log::info('ℹ️ Attachment file tidak ditemukan:', [
                            'file' => $attachment,
                            'calibration_id' => $calibration->id
                        ]);
                    }
                }
            }
        }
        
        // Hapus folder attachment jika kosong
        $folderPath = public_path('uploads/gauge-block/' . $calibration->id);
        if (is_dir($folderPath)) {
            // Cek apakah folder kosong
            $files = glob($folderPath . '/*');
            if (empty($files)) {
                @rmdir($folderPath);
                \Log::info('🗑️ Folder attachment dihapus (kosong):', [
                    'folder' => 'uploads/gauge-block/' . $calibration->id
                ]);
            }
        }
        
    } catch (\Exception $e) {
        \Log::error('❌ Error deleting attachment files:', [
            'calibration_id' => $calibration->id,
            'error' => $e->getMessage()
        ]);
    }
}

