public function downloadExcelTemplate($id)
{
    try {
        \Log::info('🟢 ===== START EXCEL DOWNLOAD WITH TEMPLATE =====');

        $calibration = Calibration::with([
            'headInsideMicrometer',
            'detailInsideMicrometers',
            'headOutsideMicrometer',
            'detailOutsideMicrometers',
            'addOutsideMicrometer',
            'headDepthMicrometer',
            'detailDepthMicrometers',
            'headThermometer',
            'detailThermometers',
            'headDialIndicator',
            'detailDialIndicators',
            'headDialTestIndicator',
            'detailDialTestIndicators',
            'headThicknessGauge',
            'detailThicknessGauges',
            'headCaliper',
            'detailCalipers',
            'addCaliper',
            'headPenggaris',
            'detailPenggaris',
            'headTorqueWrench',
            'detailTorqueWrenchs',
            'addTorqueWrench',
            'headTorqueMeter',
            'detailTorqueMeters',
            'addTorqueMeter',
            'headPressureGauge',
            'detailPressureGauges',
            'addPressureGauge',
            'headDifferentialPressureGauge',
            'detailDifferentialPressureGauges',
            'addDifferentialPressureGauge',
            'headPressureTransmitter',
            'detailPressureTransmitters',
            'addPressureTransmitter',
            'headVolumetrik',
            'detailVolumetriks',
            'addVolumetrik',
            'headThermohygrometer',
            'detailThermohygrometers',
            'headViscometer',
            'detailViscometers',
            'headPushPull',
            'detailPushPulls',
            'addPushPull',
            'headEnclosure',
            'detailEnclosures',
            'headTimbangan',
            'detailTimbangans',
            'addTimbangan',
            'headTimbanganMoisture',
            'detailTimbanganMoistures',
            'addTimbanganMoisture',
            'headTimbanganBias',
            'detailTimbanganBiass',
            'addTimbanganBias',
            'headHoleTest',
            'detailHoleTests',
            'headConductivityMeter',
            'detailConductivityMeters',
            'headMikropipetDispenset',
            'detailMikropipetDispensets',
            'headCoatingThickness',
            'detailCoatingThicknesses',
            'headTaperGauge',
            'detailTaperGauges',
            'headProfilProjector',
            'detailProfilProjectors',
            'headUltrasonicThicknessGauge',
            'detailUltrasonicThicknessGauges',
            'headHeightGauge',
            'detailHeightGauges',
            'headTempHumidTransmitter',
            'detail_T_TempHumidTransmitters',
            'detail_RH_TempHumidTransmitters',
            'headIrThermometer',
            'detailIrThermometers',
            'headTempTransmitter',
            'detailTempTransmitters',
            'headViscoCup',
            'detailViscoCups',
            'addViscoCup',
            'headPhMeter',
            'detailPhMeters',
            'headDurometer',
            'detailDurometers',
            'addDurometer',
            'headCentrifuge',
            'detailCentrifuges',
            'headThermoindicator',
            'detailThermoindicators',
            'addThermoindicator',
            'headUtm',
            'detailUtms',
            // ==============================================================
            // MULTIMETER & CLAMPMETER (insulation)
            // ==============================================================
            'headInsulation',
            'detailInsulations',
            'headTachometer',
            'detailTachometers',
            'headAnakTimbangan',
            'detailAnakTimbangans',
            'headPinGauge',
            'detailPinGauges',
            'headStopwatch',
            'detailStopwatches',
            'headThreadGauge',
            'detailThreadGauges',
            'headPlainLimitGauge',
            'detailPlainLimitGauges',
            'headChamber',
            'detailChambers',
            'addChamber',
            'headSurfaceRoughnessTester',
            'detailSurfaceRoughnessTesters',
            'headBoreGauge',
            'detailBoreGauges',
            'addBoreGauge',
            'headSurfacePlate',
            'detailSurfacePlates',
        ])->findOrFail($id);

        \Log::info('🔧 Instrument: ' . $calibration->namaAlat);
        \Log::info('📋 Form Type: ' . $calibration->form_type);

        // ==============================================================
        // AMBIL DATA USER YANG SEDANG LOGIN
        // ==============================================================
        $user = auth()->user();
        $userName = $user->nama ?? $user->username ?? 'System';
        $userId = $user->id ?? null;

        // ==============================================================
        // UPDATE VERIFIEDBY DENGAN NAMA USER DAN TANGGAL SEKARANG
        // ==============================================================
        if ($userId) {
            $calibration->verifiedBy = $userName;
            $calibration->verified = now();
            $calibration->save();
            
            \Log::info('✅ verifiedBy updated to: ' . $userName . ' (ID: ' . $userId . ')');
            \Log::info('✅ verified updated to: ' . now());
        } else {
            \Log::warning('⚠️ User not authenticated, verifiedBy and verified not updated');
        }

        // ==============================================================
        // LOG DOWNLOAD ACTIVITY
        // ==============================================================
        LogHelper::log('download_template', "{$userName} (ID: {$userId}) mendownload template Excel untuk data kalibrasi: {$calibration->namaAlat} ({$calibration->NoSeri})", $calibration);

        // 🔥 OPTIMASI: Naikkan memory limit dan execution time untuk file besar
        ini_set('memory_limit', '512M');
        ini_set('max_execution_time', '300');
        
        // Generate nama template dan function dari form_type
        $formType = $calibration->form_type;
        
        // ==============================================================
        // PENENTUAN TEMPLATE FILE UNTUK MULTIMETER & CLAMPMETER
        // ==============================================================
        $templateFile = '';
        $fillFunction = '';
         $useAutoclaveTemplate = false;
        $useBoreGaugeDialTemplate = false;
        
        // Cek apakah ini Multimeter atau Clampmeter (form_type = insulation)
        if ($formType === 'insulation') {
            // Ambil dari headInsulation untuk menentukan jenis alat
            $headInsulation = \App\Models\HeadInsulation::where('calibration_id', $calibration->id)->first();
            
            // Cek insulation_type dari head
            $insulationType = $headInsulation->insulation_type ?? '';
            
            \Log::info('📄 Insulation Type: ' . $insulationType);
            
            // Logika penentuan template berdasarkan insulation_type
            if (strtolower($insulationType) === 'clampmeter') {
                // Clampmeter
                $templateFile = 'template_clampmeter.xlsm';
                $fillFunction = 'fillClampmeterExcel';  // <- PERBAIKAN: gunakan fillClampmeterExcel
                \Log::info('📄 Detected Clampmeter from insulation_type');
            } else {
                // Default Multimeter (jika insulation_type kosong atau 'multimeter')
                $templateFile = 'template_multimeter.xlsm';
                $fillFunction = 'fillMultimeterExcel';
                \Log::info('📄 Detected Multimeter from insulation_type');
            }
            
            \Log::info('📄 Using template: ' . $templateFile);
            \Log::info('🔧 Using function: ' . $fillFunction);
            
        } else {
            // ==============================================================
            // FORM TYPE LAINNYA (SELAIN insulation)
            // ==============================================================
            
            // Konversi ke studly case untuk nama function
            $studlyName = str_replace('_', '', ucwords($formType, '_'));
            $templateFile = 'template_' . $formType . '.xlsm';
            $fillFunction = 'fill' . $studlyName . 'Excel';

            // ==============================================================
            // MODIFIKASI KHUSUS: ENCLOSURE & PRESSURE GAUGE -> AUTOCLAVE
            // Jika form_type = enclosure atau pressure_gauge DAN
            // kolom additional_forms berisi data, maka gunakan template autoclave
            // ==============================================================
            $useAutoclaveTemplate = false;
            
            if (in_array($formType, ['enclosure', 'pressure_gauge'])) {
                $additionalForms = $calibration->additional_forms ?? null;
                
                // Cek apakah additional_forms ada isinya (tidak null, tidak kosong, tidak '[]')
                if (!empty($additionalForms) && $additionalForms !== '[]' && $additionalForms !== 'null') {
                    // Kalau isinya JSON, decode dulu untuk memastikan ada data
                    if (is_string($additionalForms)) {
                        $decoded = json_decode($additionalForms, true);
                        if (is_array($decoded) && count($decoded) > 0) {
                            $useAutoclaveTemplate = true;
                        } elseif (!is_array($decoded) && trim($additionalForms) !== '') {
                            // Kalau bukan JSON tapi isinya string biasa, tetap anggap ada data
                            $useAutoclaveTemplate = true;
                        }
                    } elseif (is_array($additionalForms) && count($additionalForms) > 0) {
                        $useAutoclaveTemplate = true;
                    }
                }
                
                if ($useAutoclaveTemplate) {
                    $templateFile = 'template_autoclave.xlsm';
                    $fillFunction = 'fillAutoclaveExcel';
                    \Log::info('📄 Detected additional_forms data, using AUTOCLAVE template');
                    \Log::info('📄 additional_forms: ' . (is_string($additionalForms) ? $additionalForms : json_encode($additionalForms)));
                } else {
                    \Log::info('📄 No additional_forms data, using normal template: ' . $templateFile);
                }
            }
            
             // ==============================================================
            // MODIFIKASI KHUSUS: BORE GAUGE & DIAL INDICATOR -> BORE_GAUGE_DIAL
            // Jika form_type = bore_gauge ATAU dial_indicator DAN
            // kolom additional_forms berisi data, maka gunakan template gabungan
            // ==============================================================
            $useBoreGaugeDialTemplate = false;
            
            if (in_array($formType, ['bore_gauge', 'dial_indicator'])) {
                $additionalForms = $calibration->additional_forms ?? null;
                
                // Cek apakah additional_forms ada isinya (tidak null, tidak kosong, tidak '[]')
                if (!empty($additionalForms) && $additionalForms !== '[]' && $additionalForms !== 'null') {
                    // Kalau isinya JSON, decode dulu untuk memastikan ada data
                    if (is_string($additionalForms)) {
                        $decoded = json_decode($additionalForms, true);
                        if (is_array($decoded) && count($decoded) > 0) {
                            $useBoreGaugeDialTemplate = true;
                        } elseif (!is_array($decoded) && trim($additionalForms) !== '') {
                            // Kalau bukan JSON tapi isinya string biasa, tetap anggap ada data
                            $useBoreGaugeDialTemplate = true;
                        }
                    } elseif (is_array($additionalForms) && count($additionalForms) > 0) {
                        $useBoreGaugeDialTemplate = true;
                    }
                }
                
                if ($useBoreGaugeDialTemplate) {
                    $templateFile = 'template_bore_gauge_dial.xlsm';
                    $fillFunction = 'fillBoreGaugeDialExcel';
                    \Log::info('📄 Detected additional_forms data, using BORE GAUGE DIAL template');
                    \Log::info('📄 additional_forms: ' . (is_string($additionalForms) ? $additionalForms : json_encode($additionalForms)));
                } else {
                    \Log::info('📄 No additional_forms data, using normal template: ' . $templateFile);
                }
            }

            // Modifikasi untuk Pressure Gauge dengan alat standar P.006
            // (hanya berlaku kalau BUKAN template autoclave)
            if ($formType === 'pressure_gauge' 
                && !$useAutoclaveTemplate 
                && $calibration->headPressureGauge) {
                if (strpos($calibration->headPressureGauge->standard, 'P.006') !== false) {
                    $templateFile = 'template_pressure_gauge_P.006.xlsm';
                }
            }
            
            // ==============================================================
            // MODIFIKASI KHUSUS: TIMBANGAN -> template_timbangan (1).xlsm
            // ==============================================================
            if ($formType === 'timbangan') {
                $templateFile = 'template_timbangan (1).xlsm';
                $fillFunction = 'fillTimbanganExcel';
                \Log::info('📄 Detected Timbangan, using template: template_timbangan (1).xlsm');
            }
            
             if ($formType === 'anak_timbangan') {
                $templateFile = 'template_anak_timbangan (1).xlsm';
                $fillFunction = 'fillAnakTimbanganExcel';
                \Log::info('📄 Detected Anak Timbangan, using template: template_Anak_timbangan (1).xlsm');
            }

            // Modifikasi untuk Differential Pressure Gauge dengan alat standar P.006 atau P.005
            if ($formType === 'differential_pressure_gauge' && $calibration->headDifferentialPressureGauge) {
                $standard = $calibration->headDifferentialPressureGauge->standard;
                
                if (strpos($standard, 'P.006') !== false || strpos($standard, 'P.005') !== false) {
                    $templateFile = 'template_differential_pressure_gauge_P.006.xlsm';
                }
            }
        }
        // ==============================================================
        // MULTI-FORM DOWNLOAD (ZIP)
        // Untuk data yang memiliki additional_forms selain kasus khusus
        // autoclave (enclosure/pressure_gauge) dan bore_gauge_dial (bore_gauge/dial_indicator).
        // Setiap form type di-generate sebagai file Excel terpisah, lalu
        // dibungkus menjadi 1 file ZIP untuk didownload.
        // ==============================================================
        $parsedAdditionalForms = [];
        $rawAdditional = $calibration->additional_forms ?? null;
        if (!empty($rawAdditional) && $rawAdditional !== '[]' && $rawAdditional !== 'null') {
            if (is_string($rawAdditional)) {
                $decoded = json_decode($rawAdditional, true);
                if (is_array($decoded)) {
                    $parsedAdditionalForms = $decoded;
                } elseif (trim($rawAdditional) !== '') {
                    $parsedAdditionalForms = [trim($rawAdditional)];
                }
            } elseif (is_array($rawAdditional)) {
                $parsedAdditionalForms = $rawAdditional;
            }
        }

        $cleanAdditionalForms = array_values(array_filter(array_unique($parsedAdditionalForms), function($f) use ($formType) {
            return !empty($f) && $f !== $formType;
        }));

        if (!$useAutoclaveTemplate && !$useBoreGaugeDialTemplate && count($cleanAdditionalForms) > 0) {
            $allForms = array_merge([$formType], $cleanAdditionalForms);
            \Log::info('📦 Multi-form detected (non-autoclave & non-bore_gauge_dial): ' . json_encode($allForms));

           // Format nama file ZIP sama seperti yang sudah ada (Foto 2): 000384 - Nama PT - Nama Alat.zip
            $baseFileName = pathinfo($this->generateFileName($calibration), PATHINFO_FILENAME);
            $zipFileName  = $baseFileName . '.zip';
            $safeTempZip  = preg_replace('/[^A-Za-z0-9_\-\. ]/', '_', $zipFileName);
            $zipTempPath  = storage_path('app/temp/' . uniqid('zip_') . '_' . $safeTempZip);

            if (!is_dir(dirname($zipTempPath))) {
                mkdir(dirname($zipTempPath), 0755, true);
            }

            $zip = new \ZipArchive();
            if ($zip->open($zipTempPath, \ZipArchive::CREATE | \ZipArchive::OVERWRITE) !== true) {
                throw new \Exception('Gagal membuat file ZIP untuk multi-template');
            }

            $tempFilesToClean = [];

            foreach ($allForms as $subType) {
                $subTemplate = 'template_' . $subType . '.xlsm';
                $subStudly   = str_replace('_', '', ucwords($subType, '_'));
                $subFiller   = 'fill' . $subStudly . 'Excel';

                if ($subType === 'insulation') {
                    $headIns = \App\Models\HeadInsulation::where('calibration_id', $calibration->id)->first();
                    $insType = $headIns->insulation_type ?? '';
                    if (strtolower($insType) === 'clampmeter') {
                        $subTemplate = 'template_clampmeter.xlsm';
                        $subFiller   = 'fillClampmeterExcel';
                    } else {
                        $subTemplate = 'template_multimeter.xlsm';
                        $subFiller   = 'fillMultimeterExcel';
                    }
                } elseif ($subType === 'timbangan') {
                    $subTemplate = 'template_timbangan (1).xlsm';
                    $subFiller   = 'fillTimbanganExcel';
                } elseif ($subType === 'pressure_gauge' && $calibration->headPressureGauge) {
                    if (strpos($calibration->headPressureGauge->standard, 'P.006') !== false) {
                        $subTemplate = 'template_pressure_gauge_P.006.xlsm';
                    }
                } elseif ($subType === 'differential_pressure_gauge' && $calibration->headDifferentialPressureGauge) {
                    $standard = $calibration->headDifferentialPressureGauge->standard;
                    if (strpos($standard, 'P.006') !== false || strpos($standard, 'P.005') !== false) {
                        $subTemplate = 'template_differential_pressure_gauge_P.006.xlsm';
                    }
                }

                $subTplPath = public_path('excel_files/' . $subTemplate);
                if (!file_exists($subTplPath)) {
                    \Log::warning("⚠️ Template tidak ditemukan untuk subform {$subType}: {$subTemplate}");
                    continue;
                }
                if (!method_exists($this, $subFiller)) {
                    \Log::warning("⚠️ Filler function tidak ditemukan untuk subform {$subType}: {$subFiller}");
                    continue;
                }

                 // Format nama file di dalam ZIP sama seperti yang sudah ada (Foto 2): 000384 - Nama PT - Nama Alat.xlsm
                $entryNameInZip  = $this->generateFileName($calibration, $subType);
                $safeTempEntry   = preg_replace('/[^A-Za-z0-9_\-\. ]/', '_', $entryNameInZip);
                $subTempFileName = uniqid('cal_') . '_' . $safeTempEntry;
                $subTempPath     = storage_path('app/temp/' . $subTempFileName);

                if (!copy($subTplPath, $subTempPath)) {
                    \Log::warning("⚠️ Gagal menyalin template {$subTemplate}");
                    continue;
                }

                $this->{$subFiller}($subTempPath, $calibration);
                $this->removeAtSignFromAggregateFormulas($subTempPath);

                
                $zip->addFile($subTempPath, $entryNameInZip);
                $tempFilesToClean[] = $subTempPath;
            }

            $zip->close();

            foreach ($tempFilesToClean as $f) {
                if (file_exists($f)) {
                    @unlink($f);
                }
            }

            \Log::info("✅ Multi-form ZIP berhasil dibuat: {$zipFileName}");

            if (ob_get_level()) {
                ob_end_clean();
            }

            return response()->download($zipTempPath, $zipFileName, [
                'Content-Type'        => 'application/zip',
                'Content-Disposition' => 'attachment; filename="' . $zipFileName . '"',
                'Cache-Control'       => 'no-cache, must-revalidate',
            ])->deleteFileAfterSend(true);
        }

        \Log::info('📄 Generated template: ' . $templateFile);
        \Log::info('🔧 Generated function: ' . $fillFunction);

        $templatePath = public_path('excel_files/' . $templateFile);

        if (!file_exists($templatePath)) {
            throw new \Exception('File template tidak ditemukan: ' . $templateFile);
        }

        if (!method_exists($this, $fillFunction)) {
            throw new \Exception('Function filler tidak ditemukan: ' . $fillFunction);
        }

        // Generate nama file dengan timestamp unik
        $fileName = $this->generateFileName($calibration);
        $tempPath = storage_path('app/temp/' . $fileName);

        if (!is_dir(dirname($tempPath))) {
            mkdir(dirname($tempPath), 0755, true);
        }

        // Copy file
        if (!copy($templatePath, $tempPath)) {
            throw new \Exception('Gagal menyalin template Excel');
        }

        \Log::info('✅ Template copied to: ' . $tempPath);
        \Log::info('📦 Template size: ' . number_format(filesize($tempPath) / 1024 / 1024, 2) . ' MB');

        // Panggil fungsi berdasarkan form_type
        $this->{$fillFunction}($tempPath, $calibration);

        \Log::info('✅ Data berhasil diisi ke Excel');
        
        // 🔧 Fix: Hapus @ dari rumus AGGREGATE di semua sheet
        $this->removeAtSignFromAggregateFormulas($tempPath);
        
        \Log::info('📦 Result file size: ' . number_format(filesize($tempPath) / 1024 / 1024, 2) . ' MB');

        // Bersihkan buffer sebelum download
        if (ob_get_level()) {
            ob_end_clean();
        }
        
        // Download file
        return response()->download($tempPath, $fileName, [
            'Content-Type' => 'application/vnd.ms-excel.sheet.macroEnabled.12',
            'Content-Disposition' => 'attachment; filename="' . $fileName . '"',
            'Cache-Control' => 'no-cache, must-revalidate',
        ])->deleteFileAfterSend(true);

    } catch (\Exception $e) {
        \Log::error('💥 ERROR DOWNLOAD EXCEL: ' . $e->getMessage());
        \Log::error('📚 File: ' . $e->getFile() . ' Line: ' . $e->getLine());
        
        if (ob_get_length()) {
        }
        
        return back()->with('error', 'Gagal download template: ' . $e->getMessage());
    }
}

/**
 * Download Excel template untuk satu form type tertentu.
 * Digunakan oleh JS untuk trigger multi-download saat ada additional_forms.
 */
public function downloadExcelTemplateByType($id, string $formType)
{
    try {
        \Log::info("📥 downloadExcelTemplateByType: id={$id}, formType={$formType}");

        $calibration = Calibration::with([
            'headInsideMicrometer', 'detailInsideMicrometers',
            'headOutsideMicrometer', 'detailOutsideMicrometers', 'addOutsideMicrometer',
            'headDepthMicrometer', 'detailDepthMicrometers',
            'headThermometer', 'detailThermometers',
            'headDialIndicator', 'detailDialIndicators',
            'headDialTestIndicator', 'detailDialTestIndicators',
            'headThicknessGauge', 'detailThicknessGauges',
            'headCaliper', 'detailCalipers', 'addCaliper',
            'headPenggaris', 'detailPenggaris',
            'headTorqueWrench', 'detailTorqueWrenchs', 'addTorqueWrench',
            'headTorqueMeter', 'detailTorqueMeters', 'addTorqueMeter',
            'headPressureGauge', 'detailPressureGauges', 'addPressureGauge',
            'headDifferentialPressureGauge', 'detailDifferentialPressureGauges', 'addDifferentialPressureGauge',
            'headPressureTransmitter', 'detailPressureTransmitters', 'addPressureTransmitter',
            'headVolumetrik', 'detailVolumetriks', 'addVolumetrik',
            'headThermohygrometer', 'detailThermohygrometers',
            'headViscometer', 'detailViscometers',
            'headPushPull', 'detailPushPulls', 'addPushPull',
            'headEnclosure', 'detailEnclosures',
            'headTimbangan', 'detailTimbangans', 'addTimbangan',
            'headTimbanganMoisture', 'detailTimbanganMoistures', 'addTimbanganMoisture',
            'headTimbanganBias', 'detailTimbanganBiass', 'addTimbanganBias',
            'headHoleTest', 'detailHoleTests',
            'headConductivityMeter', 'detailConductivityMeters',
            'headMikropipetDispenset', 'detailMikropipetDispensets',
            'headCoatingThickness', 'detailCoatingThicknesses',
            'headTaperGauge', 'detailTaperGauges',
            'headProfilProjector', 'detailProfilProjectors',
            'headUltrasonicThicknessGauge', 'detailUltrasonicThicknessGauges',
            'headHeightGauge', 'detailHeightGauges',
            'headTempHumidTransmitter', 'detail_T_TempHumidTransmitters', 'detail_RH_TempHumidTransmitters',
            'headIrThermometer', 'detailIrThermometers',
            'headTempTransmitter', 'detailTempTransmitters',
            'headViscoCup', 'detailViscoCups', 'addViscoCup',
            'headPhMeter', 'detailPhMeters',
            'headDurometer', 'detailDurometers', 'addDurometer',
            'headCentrifuge', 'detailCentrifuges',
            'headThermoindicator', 'detailThermoindicators', 'addThermoindicator',
            'headUtm', 'detailUtms',
            'headInsulation', 'detailInsulations',
            'headTachometer', 'detailTachometers',
            'headAnakTimbangan', 'detailAnakTimbangans',
            'headPinGauge', 'detailPinGauges',
            'headStopwatch', 'detailStopwatches',
            'headThreadGauge', 'detailThreadGauges',
            'headPlainLimitGauge', 'detailPlainLimitGauges',
            'headChamber', 'detailChambers', 'addChamber',
            'headSurfaceRoughnessTester', 'detailSurfaceRoughnessTesters',
            'headBoreGauge', 'detailBoreGauges', 'addBoreGauge',
            'headSurfacePlate', 'detailSurfacePlates',
        ])->findOrFail($id);

        ini_set('memory_limit', '512M');
        ini_set('max_execution_time', '300');

        // Resolve template & fill function
        $templateFile = '';
        $fillFunction  = '';

        if ($formType === 'insulation') {
            $headInsulation = \App\Models\HeadInsulation::where('calibration_id', $calibration->id)->first();
            $insulationType = $headInsulation->insulation_type ?? '';
            if (strtolower($insulationType) === 'clampmeter') {
                $templateFile = 'template_clampmeter.xlsm';
                $fillFunction  = 'fillClampmeterExcel';
            } else {
                $templateFile = 'template_multimeter.xlsm';
                $fillFunction  = 'fillMultimeterExcel';
            }
        } else {
            $studlyName   = str_replace('_', '', ucwords($formType, '_'));
            $templateFile = 'template_' . $formType . '.xlsm';
            $fillFunction  = 'fill' . $studlyName . 'Excel';

            if ($formType === 'timbangan') {
                $templateFile = 'template_timbangan (1).xlsm';
                $fillFunction  = 'fillTimbanganExcel';
            }
            if ($formType === 'pressure_gauge' && $calibration->headPressureGauge) {
                if (strpos($calibration->headPressureGauge->standard, 'P.006') !== false) {
                    $templateFile = 'template_pressure_gauge_P.006.xlsm';
                }
            }
            if ($formType === 'differential_pressure_gauge' && $calibration->headDifferentialPressureGauge) {
                $standard = $calibration->headDifferentialPressureGauge->standard;
                if (strpos($standard, 'P.006') !== false || strpos($standard, 'P.005') !== false) {
                    $templateFile = 'template_differential_pressure_gauge_P.006.xlsm';
                }
            }
        }

        \Log::info("📄 Template: {$templateFile} | Function: {$fillFunction}");

        $templatePath = public_path('excel_files/' . $templateFile);
        if (!file_exists($templatePath)) {
            throw new \Exception("File template tidak ditemukan: {$templateFile}");
        }
        if (!method_exists($this, $fillFunction)) {
            throw new \Exception("Function filler tidak ditemukan: {$fillFunction}");
        }

        // Nama file output
          // Nama file output sesuai format baku (Foto 2): 000384 - Nama PT - Nama Alat.xlsm
        $fileName = $this->generateFileName($calibration, $formType);
        $safeTempFile = preg_replace('/[^A-Za-z0-9_\-\. ]/', '_', $fileName);
        $tempPath = storage_path('app/temp/' . uniqid('cal_') . '_' . $safeTempFile);

        if (!is_dir(dirname($tempPath))) {
            mkdir(dirname($tempPath), 0755, true);
        }
        if (!copy($templatePath, $tempPath)) {
            throw new \Exception('Gagal menyalin template Excel');
        }

        $this->{$fillFunction}($tempPath, $calibration);
        $this->removeAtSignFromAggregateFormulas($tempPath);

        \Log::info("✅ downloadExcelTemplateByType selesai: {$fileName}");

        if (ob_get_level()) ob_end_clean();

        return response()->download($tempPath, $fileName, [
            'Content-Type'        => 'application/vnd.ms-excel.sheet.macroEnabled.12',
            'Content-Disposition' => 'attachment; filename="' . $fileName . '"',
            'Cache-Control'       => 'no-cache, must-revalidate',
        ])->deleteFileAfterSend(true);

    } catch (\Exception $e) {
        \Log::error('💥 ERROR downloadExcelTemplateByType: ' . $e->getMessage());
        return back()->with('error', 'Gagal download: ' . $e->getMessage());
    }
}
private function removeAtSignFromAggregateFormulas(string $filePath): void
{
    try {
        \Log::info('🔧 Fixing AGGREGATE formulas via ZipArchive...');

        $zip = new \ZipArchive();
        if ($zip->open($filePath) !== true) {
            \Log::warning('⚠️ Tidak bisa buka file sebagai ZIP');
            return;
        }

        $fixedSheets   = 0;
        $fixedCells    = 0;
        $filesToUpdate = [];

        for ($i = 0; $i < $zip->numFiles; $i++) {
            $name = $zip->getNameIndex($i);

            if (!preg_match('#^xl/worksheets/sheet\d+\.xml$#', $name)) {
                continue;
            }

            $content = $zip->getFromIndex($i);
            if ($content === false) continue;

            $original = $content;

           $newContent = preg_replace_callback(
                '/<f([^>]*)>(.*?)<\/f>/s',
                function ($matches) use (&$fixedCells, $name) {  // ← tambah $name di sini
                    $attr    = $matches[1];
                    $formula = $matches[2];
            
                    $isChanged = false;
                    $fixed = $formula;

                    if (stripos($fixed, 'AGGREGATE') !== false && stripos($fixed, '_xlfn.AGGREGATE') === false) {
                        $fixed = preg_replace('/\bAGGREGATE\b/i', '_xlfn.AGGREGATE', $fixed);
                        $isChanged = true;
                    }

                    if ($isChanged) {
                        $fixedCells++;
                        \Log::info("  ✅ [{$name}] Fixed: {$formula} → {$fixed}");
                        return "<f{$attr}>{$fixed}</f>";
                    }
            
                    return $matches[0];
                },
                $content
            
            );

            if ($newContent !== $original) {
                $filesToUpdate[$name] = $newContent;
                $fixedSheets++;
            }
        }

        $zip->close();

        if (!empty($filesToUpdate)) {
            $zip2 = new \ZipArchive();
            if ($zip2->open($filePath) === true) {
                foreach ($filesToUpdate as $sheetName => $content) {
                    $zip2->addFromString($sheetName, $content);
                }
                $zip2->close();
                \Log::info("✅ Fixed {$fixedCells} AGGREGATE formula(s) di {$fixedSheets} sheet(s)");
            }
        } else {
            \Log::info('ℹ️ Tidak ada AGGREGATE formula ditemukan');
        }

    } catch (\Exception $e) {
        \Log::warning('⚠️ removeAtSignFromAggregateFormulas failed: ' . $e->getMessage());
    }
}
       public function fillInsideMicrometerExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Inside Micrometer', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $calibration->jumlah_form ?? 1
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }
        
        // Ambil jumlah form
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);
        
        // Ambil data dengan query langsung ke model
        $allHeads = \App\Models\HeadInsideMicrometer::where('calibration_id', $calibration->id)->get();
        $allDetails = \App\Models\DetailInsideMicrometer::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // Kelompokkan data per form index
        $headsByForm = [];
        foreach ($allHeads as $head) {
            if ($head && isset($head->form_index)) {
                $headsByForm[$head->form_index] = $head;
            }
        }
        
        $detailsByForm = [];
        foreach ($allDetails as $detail) {
            if ($detail && isset($detail->form_index)) {
                if (!isset($detailsByForm[$detail->form_index])) {
                    $detailsByForm[$detail->form_index] = collect();
                }
                $detailsByForm[$detail->form_index]->push($detail);
            }
        }
        
        \Log::info('📊 Data grouped by form', [
            'heads_found' => array_keys($headsByForm),
            'details_found' => array_keys($detailsByForm),
            'jumlah_form_dari_calibration' => $jumlahForm
        ]);
        
        // ==================================================================
        // LOOPING UNTUK SETIAP FORM INDEX (1 sampai jumlahForm)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Tentukan nama sheet
            $sheetName = ($formIndex == 1) ? 'ACTION' : "ACTION ({$formIndex})";
            
            // Coba ambil sheet, jika tidak ada maka buat
            $sheet = $spreadsheet->getSheetByName($sheetName);
            
            if (!$sheet) {
                // Jika sheet tidak ada, clone dari sheet ACTION
                $sourceSheet = $spreadsheet->getSheetByName('ACTION');
                if ($sourceSheet) {
                    $newSheet = clone $sourceSheet;
                    $newSheet->setTitle($sheetName);
                    $spreadsheet->addSheet($newSheet);
                    $sheet = $newSheet;
                    \Log::info("Created new sheet: {$sheetName}");
                } else {
                    throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Inside Micrometer");
                }
            }
            
            // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            
            // Ambil head untuk form ini
            $head = $headsByForm[$formIndex] ?? null;
            
            // Ambil details untuk form ini
            $formDetails = $detailsByForm[$formIndex] ?? collect();
            
            \Log::info("📝 Processing form index {$formIndex}", [
                'sheet_name' => $sheetName,
                'has_head' => !is_null($head),
                'details_count' => $formDetails->count()
            ]);
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (HANYA UNTUK FORM 1)
            // ==============================================================
            if ($formIndex == 1) {
                $sheet->setCellValue('B1',  $calibration->id ?? '');
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
                $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
                $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
                $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
                $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
                $sheet->setCellValue('B18', $calibration->keterangan ?? '');
                $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
                
                $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
                $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
                
                $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
                $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
                $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
                $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
                $sheet->setCellValue('B19', $calibration->kode_th ?? '');
                
                // Suhu & RH
                $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
                $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
                $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
                $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
                $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
                $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
                
                // Calibrated & Verified by
                $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
            } else {
                // Untuk form 2,3,4,5 - hanya isi certificate ID dan data spesifik form
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
                
                \Log::info("Form {$formIndex}: Filled certificate ID and basic info");
            }
            
            // ==============================================================
            // HEAD DATA KHUSUS INSIDE MICROMETER PER FORM
            // Data ini diambil dari HeadInsideMicrometer (per form)
            // ==============================================================
            if ($head) {
                // === DATA DARI HEAD INSIDE MICROMETER ===
                // Range Min & Max (dari head, bukan dari calibration)
                $sheet->setCellValue('B7',  $head->rentang_ukur_min ?? '0');
                $sheet->setCellValue('B8',  $head->rentang_ukur_max ?? '');
                
                // Kapasitas & Resolusi (dari head, bukan dari calibration)
                $sheet->setCellValue('B9',  $head->kapasitas ?? '');
                $sheet->setCellValue('B10', $head->resolusi ?? '');
                
                // Alat Standar & Metode Kalibrasi
                $sheet->setCellValue('B43', $head->standard ?? '');
                $sheet->setCellValue('B44', $head->calibrationMethod ?? 'PAS-IK1102-01 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)');
                
                // Satuan Unit
                $satuanUnit = $head->satuan_unit ?? 'mm';
                $sheet->setCellValue('B24', $satuanUnit);
                
                \Log::info("Form {$formIndex}: Head data filled from HeadInsideMicrometer", [
                    'rentang_ukur_min' => $head->rentang_ukur_min,
                    'rentang_ukur_max' => $head->rentang_ukur_max,
                    'kapasitas' => $head->kapasitas,
                    'resolusi' => $head->resolusi,
                    'standard' => $head->standard,
                    'satuan_unit' => $satuanUnit
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No head data found, using defaults");
                
                // Set default values jika head tidak ditemukan
                $sheet->setCellValue('B7',  '0');
                $sheet->setCellValue('B8',  '');
                $sheet->setCellValue('B9',  '');
                $sheet->setCellValue('B10', '');
                $sheet->setCellValue('B43', '');
                $sheet->setCellValue('B44', 'PAS-IK1102-01 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)');
                $sheet->setCellValue('B24', 'mm');
            }
            
            // ==============================================================
            // DETAIL DATA (baris mulai 27) PER FORM
            // ==============================================================
            if ($formDetails && $formDetails->count() > 0) {
                $sortedDetails = $formDetails->sortBy('id');
                $row = 27;
                foreach ($sortedDetails as $index => $detail) {
                    if ($index >= 20) break;
                    
                    $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                    $sheet->setCellValue('B' . $row, $detail->ulangan01 ?? '');
                    $sheet->setCellValue('C' . $row, $detail->ulangan02 ?? '');
                    $sheet->setCellValue('D' . $row, $detail->ulangan03 ?? '');
                    $sheet->setCellValue('E' . $row, $detail->ulangan04 ?? '');
                    $sheet->setCellValue('F' . $row, $detail->ulangan05 ?? '');
                    
                    $row++;
                }
                \Log::info("Form {$formIndex}: Filled {$formDetails->count()} detail rows");
            } else {
                \Log::warning("Form {$formIndex}: No detail data found");
            }
        }
        
        // ==================================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==================================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Inside Micrometer berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms' => $jumlahForm,
            'sheets_processed' => $jumlahForm,
            'filled_by' => $userName
        ]); 
        
    } catch (Exception $e) {
        \Log::error('Error fillInsideMicrometerExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

