public function fillCaliperExcel($filePath, $calibration)
{
    try {
        \Log::info('🚀 START fillCaliperExcel - Step 1', [
            'calibration_id' => $calibration->id,
            'filePath' => $filePath
        ]);

        // 🔥 OPTIMASI: Naikkan memory untuk proses ini
        ini_set('memory_limit', '512M');
        ini_set('max_execution_time', '300');

        // Cek file exists
        if (!file_exists($filePath)) {
            throw new \Exception("File tidak ditemukan: {$filePath}");
        }
        \Log::info('✅ Step 1: File exists');

        \Log::info('📂 Step 2: Loading spreadsheet...');
        
        // Load spreadsheet
        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
            // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }


        \Log::info('✅ Step 2: Spreadsheet loaded');

        // Ambil jumlah form
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);
        \Log::info('✅ Step 3: Jumlah form: ' . $jumlahForm);
        
        // Ambil data dari database (sudah dalam format JSON array)
        \Log::info('📊 Step 4: Fetching HeadCaliper data...');
        $allHeads = \App\Models\HeadCaliper::where('calibration_id', $calibration->id)->get();
        \Log::info('✅ HeadCaliper count: ' . $allHeads->count());
        
        \Log::info('📊 Step 5: Fetching DetailCaliper data...');
        $allDetails = \App\Models\DetailCaliper::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        \Log::info('✅ DetailCaliper count: ' . $allDetails->count());
        
        \Log::info('📊 Step 6: Fetching AddCaliper data...');
        $allAdds = \App\Models\AddCaliper::where('calibration_id', $calibration->id)->get();
        \Log::info('✅ AddCaliper count: ' . $allAdds->count());
        
        // Kelompokkan data per form index
        $headsByForm = [];
        foreach ($allHeads as $head) {
            if ($head && isset($head->form_index)) {
                $headsByForm[$head->form_index] = $head;
            }
        }
        
        // 🔥 MODIFIKASI: Kelompokkan detail data per form index
        // Data sudah dalam bentuk object, bukan JSON array lagi
        $detailsByForm = [];
        foreach ($allDetails as $detail) {
            if ($detail && isset($detail->form_index)) {
                if (!isset($detailsByForm[$detail->form_index])) {
                    $detailsByForm[$detail->form_index] = collect();
                }
                $detailsByForm[$detail->form_index]->push($detail);
            }
        }
        
        $addsByForm = [];
        foreach ($allAdds as $add) {
            if ($add && isset($add->form_index)) {
                $addsByForm[$add->form_index] = $add;
            }
        }
        
        \Log::info('📊 Step 7: Data grouped by form', [
            'heads_found' => array_keys($headsByForm),
            'details_found' => array_keys($detailsByForm),
            'adds_found' => array_keys($addsByForm),
        ]);
        
        // ==================================================================
        // LOOPING UNTUK SETIAP FORM INDEX
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            \Log::info("📝 Step 8: Processing form index {$formIndex}");
            
            $sheetName = ($formIndex == 1) ? 'ACTION' : "ACTION ({$formIndex})";
            \Log::info("📝 Sheet name: {$sheetName}");
            
            $sheet = $spreadsheet->getSheetByName($sheetName);
            
            if (!$sheet) {
                $sourceSheet = $spreadsheet->getSheetByName('ACTION');
                if ($sourceSheet) {
                    $newSheet = clone $sourceSheet;
                    $newSheet->setTitle($sheetName);
                    $spreadsheet->addSheet($newSheet);
                    $sheet = $newSheet;
                    \Log::info("Created new sheet: {$sheetName}");
                } else {
                    throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Caliper");
                }
            }
            
            $head = $headsByForm[$formIndex] ?? null;
            
            // 🔥 MODIFIKASI: Detail data sudah dalam bentuk collection of objects
            $formDetails = $detailsByForm[$formIndex] ?? collect();
            $addData = $addsByForm[$formIndex] ?? null;
            
            \Log::info("📝 Form {$formIndex}: head=" . ($head ? 'yes' : 'no') . ", details=" . $formDetails->count() . ", add=" . ($addData ? 'yes' : 'no'));
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (HANYA UNTUK FORM 1)
            // ==============================================================
            if ($formIndex == 1) {
                \Log::info("📝 Step 9: Filling general data for form 1");
                $sheet->setCellValue('B1',  $calibration->id ?? '');
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
                $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
                $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
                $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
                $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
                $sheet->setCellValue('B18', $calibration->keterangan ?? '');
                $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
                $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
                $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
                $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
                $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
                $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
                $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
                $sheet->setCellValue('B19', $calibration->kode_th ?? '');
                $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
                $sheet->setCellValue('B10', $calibration->resolusi ?? '');
                $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
                $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
                $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
                $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
                $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
                $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
                $sheet->setCellValue('B80', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B81', $calibration->verifiedBy ?? '');
                \Log::info("✅ Step 9: General data filled");
            } else {
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
            }
            
            // ==============================================================
            // HEAD DATA CALIPER
            // ==============================================================
            if ($head) {
                \Log::info("📝 Step 10: Filling head data");
                $sheet->setCellValue('B78', $head->standard ?? '');
                $sheet->setCellValue('B79', $head->calibrationMethod ?? 'PAS-IK1102-01 (JIS B 7502:2016 (JMA/JSA); SNSU PK.P-01:2020)');
                $sheet->setCellValue('A35', $head->satuan_unit_outside ?? 'mm');
                $sheet->setCellValue('A50', $head->satuan_unit_inside ?? 'mm');
                $sheet->setCellValue('A65', $head->satuan_unit_depth ?? 'mm');
                \Log::info("✅ Step 10: Head data filled");
            }
            
            // ==============================================================
            // ADD CALIPER DATA
            // ==============================================================
            if ($addData) {
                \Log::info("📝 Step 11: Filling add data");
                $sheet->setCellValue('A27', $addData->titikUkurKesajajaran ?? '');
                $sheet->setCellValue('B27', $addData->kesejajaranAwal ?? '');
                $sheet->setCellValue('C27', $addData->kesejajaranTengah ?? '');
                $sheet->setCellValue('D27', $addData->kesejajaranAkhir ?? '');
                $sheet->setCellValue('A31', $addData->pengukuranDalamPisauBersilang ?? '');
                $sheet->setCellValue('B31', $addData->pembacaan1 ?? '');
                $sheet->setCellValue('C31', $addData->pembacaan2 ?? '');
                $sheet->setCellValue('D31', $addData->pembacaan3 ?? '');
                \Log::info("✅ Step 11: Add data filled");
            }
            
                        // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            // ==============================================================
            // 🔥 DETAIL DATA (MODIFIKASI UNTUK JSON ARRAY DARI DATABASE)
            // Data dari database sudah dalam bentuk object, bukan JSON array
            // ==============================================================
            if ($formDetails && $formDetails->count() > 0) {
                \Log::info("📝 Step 12: Filling detail data from database objects, count: " . $formDetails->count());
                
                // Urutkan detail berdasarkan ID
                $sortedDetails = $formDetails->sortBy('id');
                
                // Pisahkan data berdasarkan jenis pengukuran
                $outsideData = [];
                $insideData = [];
                $depthData = [];
                
                foreach ($sortedDetails as $detail) {
                    // Data Outside (yang memiliki nilai outside01)
                    if ($detail->outside01 !== null || $detail->outside02 !== null || 
                        $detail->outside03 !== null || $detail->outside04 !== null || 
                        $detail->outside05 !== null) {
                        $outsideData[] = $detail;
                    }
                    
                    // Data Inside (yang memiliki nilai inside01)
                    if ($detail->inside01 !== null || $detail->inside02 !== null || 
                        $detail->inside03 !== null || $detail->inside04 !== null || 
                        $detail->inside05 !== null) {
                        $insideData[] = $detail;
                    }
                    
                    // Data Depth (yang memiliki nilai depth01)
                    if ($detail->depth01 !== null || $detail->depth02 !== null || 
                        $detail->depth03 !== null || $detail->depth04 !== null || 
                        $detail->depth05 !== null) {
                        $depthData[] = $detail;
                    }
                }
                
                \Log::info("📊 Detail breakdown for form {$formIndex}:", [
                    'outside' => count($outsideData),
                    'inside' => count($insideData),
                    'depth' => count($depthData)
                ]);
                
                // ==========================================================
                // FILL DATA OUTSIDE (mulai baris 36)
                // ==========================================================
                $rowOutside = 36;
                foreach ($outsideData as $index => $detail) {
                    if ($index >= 11) break; // Maksimal 11 baris
                    
                    $sheet->setCellValue('A' . $rowOutside, $detail->titikUkur ?? '');
                    $sheet->setCellValue('B' . $rowOutside, $detail->outside01 ?? '');
                    $sheet->setCellValue('C' . $rowOutside, $detail->outside02 ?? '');
                    $sheet->setCellValue('D' . $rowOutside, $detail->outside03 ?? '');
                    $sheet->setCellValue('E' . $rowOutside, $detail->outside04 ?? '');
                    $sheet->setCellValue('F' . $rowOutside, $detail->outside05 ?? '');
                    $rowOutside++;
                }
                
                // ==========================================================
                // FILL DATA INSIDE (mulai baris 51)
                // ==========================================================
                $rowInside = 51;
                foreach ($insideData as $index => $detail) {
                    if ($index >= 11) break; // Maksimal 11 baris
                    
                    $sheet->setCellValue('A' . $rowInside, $detail->titikUkur ?? '');
                    $sheet->setCellValue('B' . $rowInside, $detail->inside01 ?? '');
                    $sheet->setCellValue('C' . $rowInside, $detail->inside02 ?? '');
                    $sheet->setCellValue('D' . $rowInside, $detail->inside03 ?? '');
                    $sheet->setCellValue('E' . $rowInside, $detail->inside04 ?? '');
                    $sheet->setCellValue('F' . $rowInside, $detail->inside05 ?? '');
                    $rowInside++;
                }
                
                // ==========================================================
                // FILL DATA DEPTH (mulai baris 66) dengan kode standar
                // ==========================================================
                $rowDepth = 66;
                foreach ($depthData as $index => $detail) {
                    if ($index >= 11) break; // Maksimal 11 baris
                    
                    $sheet->setCellValue('A' . $rowDepth, $detail->titikUkur ?? '');
                    $sheet->setCellValue('D' . $rowDepth, $detail->depth01 ?? '');
                    $sheet->setCellValue('E' . $rowDepth, $detail->depth02 ?? '');
                    $sheet->setCellValue('F' . $rowDepth, $detail->depth03 ?? '');
                    $sheet->setCellValue('G' . $rowDepth, $detail->depth04 ?? '');
                    $sheet->setCellValue('H' . $rowDepth, $detail->depth05 ?? '');
                    $sheet->setCellValue('B' . $rowDepth, $detail->kodeStandarKiri ?? '');
                    $sheet->setCellValue('C' . $rowDepth, $detail->kodeStandarKanan ?? '');
                    $rowDepth++;
                }
                
                \Log::info("✅ Step 12: Detail data filled", [
                    'outside_rows' => count($outsideData),
                    'inside_rows' => count($insideData),
                    'depth_rows' => count($depthData)
                ]);
            } else {
                \Log::info("📝 Step 12: No detail data for form {$formIndex}");
            }
        }
        
        // ==================================================================
        // SAVE SPREADSHEET
        // ==================================================================
        \Log::info("💾 Step 13: Saving spreadsheet...");
        
        // Gunakan writer dengan preCalculateFormulas = false untuk mempercepat
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        // Bersihkan object untuk free memory
        $spreadsheet->disconnectWorksheets();
        unset($spreadsheet);
        unset($writer);
        
        \Log::info("✅ Step 13: Spreadsheet saved successfully");
        \Log::info('🎉 SUKSES! Data Caliper berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms' => $jumlahForm,
        ]);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('💥 ERROR fillCaliperExcel: ' . $e->getMessage());
        \Log::error('📚 File: ' . $e->getFile() . ' Line: ' . $e->getLine());
        \Log::error('📚 Trace: ' . $e->getTraceAsString());
        throw $e;
    }
}

public function fillPenggarisExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Penggaris', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
           // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }


        // Ambil data dengan query langsung ke model
        $head = \App\Models\HeadPenggaris::where('calibration_id', $calibration->id)->first();
        $details = \App\Models\DetailPenggaris::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        \Log::info('📊 Data retrieved', [
            'has_head' => !is_null($head),
            'details_count' => $details->count()
        ]);
        
        // ==============================================================
        // AMBIL SHEET ACTION
        // ==============================================================
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Penggaris");
        }
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
        $sheet->setCellValue('B10', $calibration->resolusi ?? '');

        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // ==============================================================
        // HEAD DATA KHUSUS PENGGARIS
        // ==============================================================
        if ($head) {
            // Satuan Unit
            $satuanUnit = $head->satuan_unit ?? ' ';
            $sheet->setCellValue('B24', $satuanUnit);
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B45', $head->standard ?? '');
            $sheet->setCellValue('B46', $head->calibrationMethod ?? '');
            
            // Calibrated by & Verified by
            $sheet->setCellValue('B47', $head->calibratedBy ?? $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B48', $head->verifiedBy ?? $calibration->verifiedBy ?? '');
            
            \Log::info("Head data filled from HeadPenggaris");
        } else {
            \Log::warning("No head data found, using defaults");
            
            // Set default values jika head tidak ditemukan
            $sheet->setCellValue('B24', 'mm');
            $sheet->setCellValue('B69', '');
            $sheet->setCellValue('B70', '');
            $sheet->setCellValue('B71', $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B72', $calibration->verifiedBy ?? '');
        }
        
                    // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
        // ==============================================================
        // DETAIL DATA (titikUkur dengan 5 kali ulangan)
        // Data akan diisi mulai dari baris 28 sampai seterusnya
        // Format: 
        // Kolom A = Titik Ukur
        // Kolom B = Ulangan 1
        // Kolom C = Ulangan 2  
        // Kolom D = Ulangan 3
        // Kolom E = Ulangan 4
        // Kolom F = Ulangan 5
        // ==============================================================
        if ($details && $details->count() > 0) {
            $sortedDetails = $details->sortBy('id');
            $row = 27;
            $maxRow = 43; // Batas maksimal baris sesuai template
            
            foreach ($sortedDetails as $detail) {
                if ($row > $maxRow) break;
                
                // Titik Ukur di kolom A
                $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                
                // 5 kali ulangan di kolom B, C, D, E, F
                $sheet->setCellValue('B' . $row, $detail->ulangan01 ?? '');
                $sheet->setCellValue('C' . $row, $detail->ulangan02 ?? '');
                $sheet->setCellValue('D' . $row, $detail->ulangan03 ?? '');
                $sheet->setCellValue('E' . $row, $detail->ulangan04 ?? '');
                $sheet->setCellValue('F' . $row, $detail->ulangan05 ?? '');
                
                $row++;
            }
            
            \Log::info("Filled {$details->count()} detail rows for Penggaris");
        } else {
            \Log::warning("No detail data found for Penggaris");
        }
        
        // ==============================================================
        // CATATAN: Penggaris tidak memiliki data Repeatability (AddData)
        // seperti pada Dial Indicator, jadi hanya sampai detail saja
        // ==============================================================
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Penggaris berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillPenggarisExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillTorqueWrenchExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Torque Wrench', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
                // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }
        
        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Torque Wrench");
        }
        
        // Ambil data HeadTorqueWrench
        $head = \App\Models\HeadTorqueWrench::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailTorqueWrench
        $details = \App\Models\DetailTorqueWrench::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();
        
        // Ambil data AddTorqueWrench untuk repeatability
        $addTorqueWrench = \App\Models\AddTorqueWrench::where('calibration_id', $calibration->id)->first();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1', $calibration->id ?? '');
        $sheet->setCellValue('E1', $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2', $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3', $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5', $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6', $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4', $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B55', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B56', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA TORQUE WRENCH (sesuai model HeadTorqueWrench)
        // ==============================================================
        if ($head) {
            // Range Min (B7) dan Range Max (B8) dari calibration
            $sheet->setCellValue('B7', $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8', $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Satuan Ukur Alat (B24) - dari head satuan_setting_alat
            $sheet->setCellValue('A28', $head->satuan_setting_alat ?? '');
            
            // Satuan Ukur Standar (A28) - dari head satuan_cw
            $sheet->setCellValue('F27', $head->satuan_cw ?? 'N.m');
            $sheet->setCellValue('J27', $head->satuan_ccw ?? 'N.m');
            
            // Standard (B45) dan Calibration Method (B46)
            $sheet->setCellValue('B53', $head->standard ?? '');
            $sheet->setCellValue('B54', $head->calibrationMethod ?? '');
            
            // // Alat Standar (B53) - dari head standard
            // $sheet->setCellValue('B53', $head->standard ?? '');
            
            \Log::info('Head Torque Wrench data filled', [
                'satuan_setting_alat' => $head->satuan_setting_alat,
                'satuan_cw' => $head->satuan_cw,
                'satuan_ccw' => $head->satuan_ccw,
                'standard' => $head->standard,
                'calibrationMethod' => $head->calibrationMethod
            ]);
        } else {
            $sheet->setCellValue('B7', '0');
            $sheet->setCellValue('B8', '');
            $sheet->setCellValue('B9', '');
            $sheet->setCellValue('B10', '');
            $sheet->setCellValue('B24', 'N.m');
            $sheet->setCellValue('A28', 'N.m');
            $sheet->setCellValue('B45', '');
            $sheet->setCellValue('B46', '');
            $sheet->setCellValue('B53', '');
        }
        
          // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
        
        // ==============================================================
        // DATA KALIBRASI TORQUE WRENCH (sesuai model DetailTorqueWrench)
        // Struktur: titikUkur, cw1, cw2, cw3, ccw1, ccw2, ccw3
        // ==============================================================
        if ($details && $details->count() > 0) {
            // Clockwise data (baris 29-42) untuk CW
            $cwRow = 29;
            // Counter Clockwise data (baris 45-58) untuk CCW
            $ccwRow = 29;
            
            foreach ($details as $detail) {
                // Isi data Clockwise ke kolom C, D, E (standar1, standar2, koreksi)
                if ($cwRow <= 40) {
                    $sheet->setCellValue('A' . $cwRow, $detail->titikUkur ?? '');     // Titik Ukur
                    $sheet->setCellValue('C' . $cwRow, $detail->cw1 ?? '');           // Standar 1
                    $sheet->setCellValue('D' . $cwRow, $detail->cw2 ?? '');           // Standar 2
                    $sheet->setCellValue('E' . $cwRow, $detail->cw3 ?? '');           // Koreksi
                    $cwRow++;
                }
                
                // Isi data Counter Clockwise ke kolom C, D, E
                if ($ccwRow <= 40) {
                    $sheet->setCellValue('G' . $ccwRow, $detail->ccw1 ?? '');          // Standar 1
                    $sheet->setCellValue('H' . $ccwRow, $detail->ccw2 ?? '');          // Standar 2
                    $sheet->setCellValue('I' . $ccwRow, $detail->ccw3 ?? '');          // Koreksi
                    $ccwRow++;
                }
            }
            \Log::info("Filled {$details->count()} detail rows");
        } else {
            // Isi default kosong untuk 14 baris CW dan 14 baris CCW
            for ($row = 29; $row <= 42; $row++) {
                $sheet->setCellValue('A' . $row, '');
                $sheet->setCellValue('B' . $row, '');
                $sheet->setCellValue('C' . $row, '');
                $sheet->setCellValue('D' . $row, '');
                $sheet->setCellValue('E' . $row, '');
                $sheet->setCellValue('F' . $row, '');
            }
            for ($row = 29; $row <= 42; $row++) {
                $sheet->setCellValue('A' . $row, '');
                $sheet->setCellValue('B' . $row, '');
                $sheet->setCellValue('C' . $row, '');
                $sheet->setCellValue('D' . $row, '');
                $sheet->setCellValue('E' . $row, '');
                $sheet->setCellValue('F' . $row, '');
            }
        }
        
        // ==============================================================
        // DATA REPEATABILITY (sesuai model AddTorqueWrench)
        // Struktur: repCw01 - repCw10 dan repCcw01 - repCcw10
        // ==============================================================
        if ($addTorqueWrench) {
            // Repeatability Clockwise baris 43
            // $sheet->setCellValue('A43', 'Repeatability CW');
            $sheet->setCellValue('A43', $addTorqueWrench->repCw01 ?? '');
            $sheet->setCellValue('B43', $addTorqueWrench->repCw02 ?? '');
            $sheet->setCellValue('C43', $addTorqueWrench->repCw03 ?? '');
            $sheet->setCellValue('D43', $addTorqueWrench->repCw04 ?? '');
            $sheet->setCellValue('E43', $addTorqueWrench->repCw05 ?? '');
            $sheet->setCellValue('A44', $addTorqueWrench->repCw06 ?? '');
            $sheet->setCellValue('B44', $addTorqueWrench->repCw07 ?? '');
            $sheet->setCellValue('C44', $addTorqueWrench->repCw08 ?? '');
            $sheet->setCellValue('D44', $addTorqueWrench->repCw09 ?? '');
            $sheet->setCellValue('E44', $addTorqueWrench->repCw10 ?? '');
            
          
            
            // Repeatability Counter Clockwise baris 59
           
            $sheet->setCellValue('A49', $addTorqueWrench->repCcw01 ?? '');
            $sheet->setCellValue('B49', $addTorqueWrench->repCcw02 ?? '');
            $sheet->setCellValue('C49', $addTorqueWrench->repCcw03 ?? '');
            $sheet->setCellValue('D49', $addTorqueWrench->repCcw04 ?? '');
            $sheet->setCellValue('E49', $addTorqueWrench->repCcw05 ?? '');
            $sheet->setCellValue('A50', $addTorqueWrench->repCcw06 ?? '');
            $sheet->setCellValue('B50', $addTorqueWrench->repCcw07 ?? '');
            $sheet->setCellValue('C50', $addTorqueWrench->repCcw08 ?? '');
            $sheet->setCellValue('D50', $addTorqueWrench->repCcw09 ?? '');
            $sheet->setCellValue('E50', $addTorqueWrench->repCcw10 ?? '');
            
            
            \Log::info('AddTorqueWrench repeatability data filled', [
                'repCw01' => $addTorqueWrench->repCw01,
                'repCcw01' => $addTorqueWrench->repCcw01
            ]);
        }
        
        // ==============================================================
        // SIMPAN FILE
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Torque Wrench berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'details_count' => $details->count(),
            'has_repeatability' => $addTorqueWrench ? true : false
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillTorqueWrenchExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillTorqueMeterExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Torque Wrench', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
          // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }


        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Torque Wrench");
        }
        
        // Ambil data HeadTorqueWrench
        $head = \App\Models\HeadTorqueMeter::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailTorqueWrench
        $details = \App\Models\DetailTorqueMeter::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();
        
        // Ambil data AddTorqueWrench untuk repeatability
        $addTorqueWrench = \App\Models\AddTorqueMeter::where('calibration_id', $calibration->id)->first();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1', $calibration->id ?? '');
        $sheet->setCellValue('E1', $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2', $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3', $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5', $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6', $calibration->NoSeri ?? '');
