            }
            
        // ==============================================================
        // DATA KALIBRASI TORQUE WRENCH (sesuai model DetailTorqueWrench)
        // Struktur: titikUkur, cw1, cw2, cw3, ccw1, ccw2, ccw3
        // ==============================================================
        if ($details && $details->count() > 0) {
            // Clockwise data (baris 29-42) untuk CW
            $cwRow = 31;
            // Counter Clockwise data (baris 45-58) untuk CCW
            $ccwRow = 31;
            
