public function fillPressureTransmitterExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Pressure Transmitter', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);

        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Pressure Transmitter");
        }

        // Ambil data Head
        $head = \App\Models\HeadPressureTransmitter::where('calibration_id', $calibration->id)->first();

        // Ambil detail
        $details = \App\Models\DetailPressureTransmitter::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();

        // Ambil data Add (repeatability)
        $add = \App\Models\AddPressureTransmitter::where('calibration_id', $calibration->id)->first();

        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');

        $sheet->setCellValue('B12', $calibration->tanggalMasuk
            ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi
            ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');

        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');

        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');

        // Calibrated & Verified by
        $sheet->setCellValue('B58', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B59', $calibration->verifiedBy ?? '');

        // ==============================================================
        // HEAD DATA
        // ==============================================================
        if ($head) {
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');

            $sheet->setCellValue('B56', $head->standard ?? '');
            $sheet->setCellValue('B57', $head->calibrationMethod ?? '');

            // satuan
            $sheet->setCellValue('A26', $head->satuan_set_point ?? ' ');
            $sheet->setCellValue('B26', $head->satuan_p_naik ?? ' ');
            $sheet->setCellValue('D26', $head->satuan_p_turun ?? ' ');
            $sheet->setCellValue('C26', $head->satuan_so_naik ?? ' ');
            $sheet->setCellValue('E26', $head->satuan_so_turun ?? ' ');

            \Log::info('Head Pressure Transmitter filled', [
                'standard' => $head->standard,
                'calibrationMethod' => $head->calibrationMethod,
            ]);
        } else {
            $sheet->setCellValue('B7', ' ');
        }

        // Isi cell K1 dengan nama user
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }

        // ==============================================================
        // DETAIL DATA (setPoint, readP_UP, readS_UP, readP_DOWN, readS_DOWN)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 28;
            foreach ($details as $detail) {
                if ($row > 48) break; // max 20 baris

                $sheet->setCellValue('A' . $row, $detail->setPoint ?? '');
                $sheet->setCellValue('B' . $row, $detail->readP_UP ?? '');
                $sheet->setCellValue('C' . $row, $detail->readS_UP ?? '');
                $sheet->setCellValue('D' . $row, $detail->readP_DOWN ?? '');
                $sheet->setCellValue('E' . $row, $detail->readS_DOWN ?? '');

                $row++;
            }
            \Log::info("Filled {$details->count()} detail rows Pressure Transmitter");
        }

                // ==============================================================
        // REPEATABILITY (add)
        // Sesuai layout template: 5 ulangan menyamping di Row 50 & 53
        // ==============================================================
        if ($add) {
            // --- Repeatability 1 (Pressure) di Row 50 ---
            $sheet->setCellValue('B50', $add->repeatibility_P ?? '');
            $sheet->setCellValue('C50', $add->satuan_P ?? '');
            $sheet->setCellValue('A51', $add->repP01 ?? '');
            $sheet->setCellValue('B51', $add->repP02 ?? '');
            $sheet->setCellValue('C51', $add->repP03 ?? '');
            $sheet->setCellValue('D51', $add->repP04 ?? '');
            $sheet->setCellValue('E51', $add->repP05 ?? '');

            // --- Repeatability 2 (Signal Output) di Row 53 ---
            $sheet->setCellValue('B53', $add->repeatibility_SO ?? '');
            $sheet->setCellValue('C53', $add->satuan_SO ?? '');
            $sheet->setCellValue('A54', $add->repSO01 ?? '');
            $sheet->setCellValue('B54', $add->repSO02 ?? '');
            $sheet->setCellValue('C54', $add->repSO03 ?? '');
            $sheet->setCellValue('D54', $add->repSO04 ?? '');
            $sheet->setCellValue('E54', $add->repSO05 ?? '');

            \Log::info('Add Pressure Transmitter repeatability filled', [
                'satuan_P'         => $add->satuan_P,
                'repeatibility_P'  => $add->repeatibility_P,
                'satuan_SO'        => $add->satuan_SO,
                'repeatibility_SO' => $add->repeatibility_SO,
                'repP01'           => $add->repP01,
                'repSO01'          => $add->repSO01,
            ]);
        }

        // ==============================================================
        // SIMPAN FILE
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();

        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);

        \Log::info('SUKSES! Data Pressure Transmitter berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);

    } catch (\Throwable $e) {
        \Log::error('Error fillPressureTransmitterExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace'          => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

