public function fillVolumetrikExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Volumetrik', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Volumetrik");
        }
        
        // Ambil data HeadVolumetrik (hanya 1 form)
        $head = \App\Models\HeadVolumetrik::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailVolumetrik
        $details = \App\Models\DetailVolumetrik::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
           
        // Ambil data AddVolumetrik untuk data tambahan
        $add = \App\Models\AddVolumetrik::where('calibration_id', $calibration->id)->first();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B61', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B62', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA VOLUMETRIK
        // ==============================================================
        if ($head) {
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            $sheet->setCellValue('B59', $head->standard ?? '');
            $sheet->setCellValue('B60', $head->calibrationMethod ?? '');
            $sheet->setCellValue('A26', $head->satuan_alatUkur ?? ' ');
            $sheet->setCellValue('A46', $head->satuan_rep ?? ' ');
            
        } else {
            $sheet->setCellValue('B7', ' ');
            $sheet->setCellValue('B24', '  ');
        }
        
        // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // DETAIL DATA VOLUMETRIK (baris mulai 27)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 27;
            foreach ($details as $detail) {
                if ($row > 48) break; // Max 20 baris
                
                // Setiap 1 titik ukur memiliki 3 data pengukuran
                // Data disusun per kolom (B, C, D, E) dengan 3 pengukuran per kolom
                
                $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                
                // Massa Kosong (3 data) - Kolom B
                $sheet->setCellValue('B' . $row, $detail->masssaKosong01 ?? '');
                $sheet->setCellValue('B' . ($row + 1), $detail->masssaKosong02 ?? '');
                $sheet->setCellValue('B' . ($row + 2), $detail->masssaKosong03 ?? '');
                
                // Massa Isi (3 data) - Kolom C
                $sheet->setCellValue('C' . $row, $detail->massaIsi01 ?? '');
                $sheet->setCellValue('C' . ($row + 1), $detail->massaIsi02 ?? '');
                $sheet->setCellValue('C' . ($row + 2), $detail->massaIsi03 ?? '');
                
                // T air suling (3 data) - Kolom D
                $sheet->setCellValue('D' . $row, $detail->T_airSuling01 ?? '');
                $sheet->setCellValue('D' . ($row + 1), $detail->T_airSuling02 ?? '');
                $sheet->setCellValue('D' . ($row + 2), $detail->T_airSuling03 ?? '');
                
                // P Udara (3 data) - Kolom E
                $sheet->setCellValue('E' . $row, $detail->P_Udara01 ?? '');
                $sheet->setCellValue('E' . ($row + 1), $detail->P_Udara02 ?? '');
                $sheet->setCellValue('E' . ($row + 2), $detail->P_Udara03 ?? '');
                
                $row += 3; // Lompat 3 baris untuk titik ukur berikutnya
            }
            \Log::info("Filled {$details->count()} detail rows");
        }
        
        // ==============================================================
        // ADD DATA VOLUMETRIK (data tambahan / repeatability)
        // ==============================================================
        if ($add) {
            // Ambil semua data AddVolumetrik
            $addData = \App\Models\AddVolumetrik::where('calibration_id', $calibration->id)
                        ->orderBy('id', 'asc')
                        ->get();
            
            if ($addData && $addData->count() > 0) {
                $row = 47; // Mulai dari baris 47
                
                // Ambil titik ukur dari data pertama
                $titikUkur = $addData->first()->titikUkur ?? '';
                
                // Isi titik ukur di cell A47 (hanya 1 kali)
                $sheet->setCellValue('A47', $titikUkur);
                
                // Looping untuk mengisi data di kolom B, C, D, E
                foreach ($addData as $index => $addItem) {
                    $currentRow = $row + $index;
                    if ($currentRow > 58) break; // Maksimal 20 baris (47-66)
                    
                    // Massa Kosong di kolom B
                    $sheet->setCellValue('B' . $currentRow, $addItem->massaKosong ?? '');
                    
                    // Massa Isi di kolom C
                    $sheet->setCellValue('C' . $currentRow, $addItem->massaIsi ?? '');
                    
                    // T air suling di kolom D
                    $sheet->setCellValue('D' . $currentRow, $addItem->T_airSuling ?? '');
                    
                    // P Udara di kolom E
                    $sheet->setCellValue('E' . $currentRow, $addItem->P_Udara ?? '');
                }
                
                \Log::info('Add data filled', [
                    'titikUkur' => $titikUkur,
                    'total_data' => $addData->count(),
                    'rows' => ($row + $addData->count() - 1)
                ]);
            }
        }
        
        // ==============================================================
        // SIMPAN FILE
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Volumetrik berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillVolumetrikExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

