        $details = \App\Models\DetailThermohygrometer::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        \Log::info('📊 Data retrieved', [
            'has_head' => !is_null($head),
            'details_count' => $details->count()
        ]);
        
        // ==============================================================
        // AMBIL SHEET ACTION
        // ==============================================================
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Thermohygrometer");
        }
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1', $calibration->id ?? '');
        $sheet->setCellValue('E1', $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2', $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3', $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5', $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6', $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4', $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Kapasitas dan Resolusi dari head
        $sheet->setCellValue('B9', $head->kapasitas_c ?? $calibration->kapasitas ?? '');
        $sheet->setCellValue('B10', $head->resolusi_c ?? $calibration->resolusi ?? '');

        // Suhu & RH Conditions dari calibration
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // ==============================================================
        // HEAD DATA KHUSUS THERMOHYGROMETER
        // ==============================================================
        if ($head) {
            // Rentang Ukur Suhu (°C)
            $sheet->setCellValue('B7', $head->rentang_ukur_min_c ?? '');
            $sheet->setCellValue('B8', $head->rentang_ukur_max_c ?? '');
            
            // Rentang Ukur RH (%)
            $sheet->setCellValue('D7', $head->rentang_ukur_min_rh ?? '');
            $sheet->setCellValue('D8', $head->rentang_ukur_max_rh ?? '');
            
            // Kapasitas dan Resolusi
            $sheet->setCellValue('B9', $head->kapasitas_c ?? '');
            $sheet->setCellValue('D9', $head->kapasitas_rh ?? '');
            $sheet->setCellValue('B10', $head->resolusi_c ?? '');
            $sheet->setCellValue('D10', $head->resolusi_rh ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B51', $head->standard ?? '');
            $sheet->setCellValue('B52', $head->calibrationMethod ?? '');
            
            // Calibrated by & Verified by
            $sheet->setCellValue('B53', $head->calibratedBy ?? $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B54', $head->verifiedBy ?? $calibration->verifiedBy ?? '');
            
            \Log::info("Head data filled from HeadThermohygrometer", [
                'rentang_suhu' => $head->rentang_ukur_min_c . ' - ' . $head->rentang_ukur_max_c,
                'rentang_rh' => $head->rentang_ukur_min_rh . ' - ' . $head->rentang_ukur_max_rh
            ]);
        } else {
            \Log::warning("No head data found, using defaults");
            
            // Set default values jika head tidak ditemukan
            $sheet->setCellValue('B24', '');
            $sheet->setCellValue('C24', '');
            $sheet->setCellValue('B25', '');
            $sheet->setCellValue('C25', '');
            $sheet->setCellValue('B26', '');
            $sheet->setCellValue('C26', '');
            $sheet->setCellValue('B27', '');
            $sheet->setCellValue('C27', '');
            $sheet->setCellValue('B45', '');
            $sheet->setCellValue('B46', '');
            $sheet->setCellValue('B47', $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B48', $calibration->verifiedBy ?? '');
        }
        
        // Isi cell K1 dengan nama user yang login
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // DETAIL DATA SUHU (Titik Ukur Suhu)
        // Data akan diisi mulai dari baris 29 sampai seterusnya
        // Format untuk Suhu:
        // Kolom A = Titik Ukur Suhu
        // Kolom B = T_STD1 (Standar 1)
        // Kolom C = T_STD2 (Standar 2)
        // Kolom D = T_STD3 (Standar 3)
        // Kolom E = T_IN1 (In 1)
        // Kolom F = T_IN2 (In 2)
        // Kolom G = T_IN3 (In 3)
        // Kolom H = T_OUT1 (Out 1)
        // Kolom I = T_OUT2 (Out 2)
        // Kolom J = T_OUT3 (Out 3)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $sortedDetails = $details->sortBy('id');
            
            // ==============================================================
            // ISI DATA SUHU (Mulai baris 29)
            // ==============================================================
            $rowSuhu = 27;
            $maxRowSuhu = 36; // Batas maksimal baris untuk suhu
            
            foreach ($sortedDetails as $detail) {
                if ($rowSuhu > $maxRowSuhu) break;
                
                // Titik Ukur Suhu di kolom A
                $sheet->setCellValue('A' . $rowSuhu, $detail->titikUkur_T ?? '');
                
                // T_STD (Standar) - Kolom B, C, D
                $sheet->setCellValue('B' . $rowSuhu, $detail->T_STD1 ?? '');
                $sheet->setCellValue('C' . $rowSuhu, $detail->T_STD2 ?? '');
                $sheet->setCellValue('D' . $rowSuhu, $detail->T_STD3 ?? '');
                
                // T_IN - Kolom E, F, G
                $sheet->setCellValue('E' . $rowSuhu, $detail->T_IN1 ?? '');
                $sheet->setCellValue('F' . $rowSuhu, $detail->T_IN2 ?? '');
                $sheet->setCellValue('G' . $rowSuhu, $detail->T_IN3 ?? '');
                
                // T_OUT - Kolom H, I, J
                $sheet->setCellValue('H' . $rowSuhu, $detail->T_OUT1 ?? '');
                $sheet->setCellValue('I' . $rowSuhu, $detail->T_OUT2 ?? '');
                $sheet->setCellValue('J' . $rowSuhu, $detail->T_OUT3 ?? '');
                
                $rowSuhu++;
            }
            
            \Log::info("Filled temperature data for {$details->count()} detail rows");
            
            // ==============================================================
            // ISI DATA RH (Mulai baris 38)
            // ==============================================================
            $rowRH = 40;
            $maxRowRH = 49; // Batas maksimal baris untuk RH
            
            foreach ($sortedDetails as $detail) {
                if ($rowRH > $maxRowRH) break;
                
                // Titik Ukur RH di kolom A
                $sheet->setCellValue('A' . $rowRH, $detail->titikUkur_RH ?? '');
                
                // RH_STD (Standar) - Kolom B, C, D
                $sheet->setCellValue('B' . $rowRH, $detail->RH_STD1 ?? '');
                $sheet->setCellValue('C' . $rowRH, $detail->RH_STD2 ?? '');
                $sheet->setCellValue('D' . $rowRH, $detail->RH_STD3 ?? '');
                
                // RH_ALAT (Alat) - Kolom E, F, G
                $sheet->setCellValue('E' . $rowRH, $detail->RH_ALAT1 ?? '');
                $sheet->setCellValue('F' . $rowRH, $detail->RH_ALAT2 ?? '');
                $sheet->setCellValue('G' . $rowRH, $detail->RH_ALAT3 ?? '');
                
                $rowRH++;
            }
            
            \Log::info("Filled RH data for {$details->count()} detail rows");
            
        } else {
            \Log::warning("No detail data found for Thermohygrometer");
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Thermohygrometer berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillThermohygrometerExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

