                // Kolom G = resolution (Resolusi)
                $sheet->setCellValue('I' . $rowData, $detail->resolution ?? '');
                
                // Kolom H = T_awal (Suhu Awal)
                $sheet->setCellValue('J' . $rowData, $detail->T_awal ?? '');
                
                // Kolom I = T_akhir (Suhu Akhir)
                $sheet->setCellValue('K' . $rowData, $detail->T_akhir ?? '');
                
                // Kolom J = spindle (Spindle)
                $sheet->setCellValue('B' . $rowData, $detail->spindle ?? '');
                
                // Kolom K = RPM (RPM)
                $sheet->setCellValue('C' . $rowData, $detail->RPM ?? '');
                
                $rowData++;
            }
            
            \Log::info("Filled main data for {$details->count()} detail rows");
            
        } else {
            \Log::warning("No detail data found for Viscometer");
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
