        $sheet->setCellValue('B3', $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5', $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6', $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4', $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B49', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B50', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA PUSH PULL
        // ==============================================================
        if ($head) {
            $sheet->setCellValue('B7', $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8', $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            $sheet->setCellValue('H25', $head->satuan_tekan ?? '');
            $sheet->setCellValue('E25', $head->satuan_tarik ?? '');
            $sheet->setCellValue('A26', $head->satuan_titik_ukur ?? '');
            $sheet->setCellValue('B47', $head->standard ?? '');
            $sheet->setCellValue('B48', $head->calibrationMethod ?? '');
            
          
            
            \Log::info('Head Push Pull data filled', [
                'rangeMin' => $head->rangeMin,
                'rangeMax' => $head->rangeMax,
                'satuan' => $head->satuan
            ]);
        } else {
            $sheet->setCellValue('B7', '0');
            $sheet->setCellValue('B8', '');
            $sheet->setCellValue('B9', '');
            $sheet->setCellValue('B10', '');
            $sheet->setCellValue('H25', '');
            $sheet->setCellValue('B51', '');
            $sheet->setCellValue('B52', '');
            $sheet->setCellValue('B53', '');
            $sheet->setCellValue('B54', '');
        }
        
        // Isi cell K1 dengan nama user yang login
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // DATA KALIBRASI PUSH PULL (TARIK)
        // Struktur: titikUkur, STD, ulanganTarik01, ulanganTarik02, ulanganTarik03
        // ==============================================================
        if ($details && $details->count() > 0) {
            $rowData = 27;
            $maxRow = 36;
            
            foreach ($details as $detail) {
                if ($rowData > $maxRow) break;
                
                // Kolom A = titikUkur
                $sheet->setCellValue('A' . $rowData, $detail->titikUkur ?? '');
                
                // Kolom B = STD
                $sheet->setCellValue('B' . $rowData, $detail->STD ?? '');
                
                // Kolom C = ulanganTarik01
                $sheet->setCellValue('C' . $rowData, $detail->ulanganTarik01 ?? '');
                
                // Kolom D = ulanganTarik02
                $sheet->setCellValue('D' . $rowData, $detail->ulanganTarik02 ?? '');
                
                // Kolom E = ulanganTarik03
                $sheet->setCellValue('E' . $rowData, $detail->ulanganTarik03 ?? '');
                
                // Kolom F = ulanganTekan01
                $sheet->setCellValue('F' . $rowData, $detail->ulanganTekan01 ?? '');
                
                // Kolom G = ulanganTekan02
                $sheet->setCellValue('G' . $rowData, $detail->ulanganTekan02 ?? '');
                
                // Kolom H = ulanganTekan03
                $sheet->setCellValue('H' . $rowData, $detail->ulanganTekan03 ?? '');
                
                $rowData++;
            }
            
            \Log::info("Filled {$details->count()} detail rows for Push Pull");
        } else {
            // Isi default kosong untuk 10 baris
            for ($row = 27; $row <= 36; $row++) {
                $sheet->setCellValue('A' . $row, '');
                $sheet->setCellValue('B' . $row, '');
                $sheet->setCellValue('C' . $row, '');
                $sheet->setCellValue('D' . $row, '');
                $sheet->setCellValue('E' . $row, '');
                $sheet->setCellValue('F' . $row, '');
                $sheet->setCellValue('G' . $row, '');
                $sheet->setCellValue('H' . $row, '');
            }
        }
        
        // ==============================================================
        // DATA REPEATABILITY PUSH PULL (sesuai model AddPushPull)
        // Struktur: repeatabilityTarik01-10 dan repeatabilityTekan01-10
        // ==============================================================
        if ($addPushPull) {
            // Repeatability TARIK (baris 47-48)
            $sheet->setCellValue('A40', $addPushPull->repeatabilityTarik01 ?? '');
            $sheet->setCellValue('B40', $addPushPull->repeatabilityTarik02 ?? '');
            $sheet->setCellValue('C40', $addPushPull->repeatabilityTarik03 ?? '');
            $sheet->setCellValue('D40', $addPushPull->repeatabilityTarik04 ?? '');
            $sheet->setCellValue('E40', $addPushPull->repeatabilityTarik05 ?? '');
            $sheet->setCellValue('A41', $addPushPull->repeatabilityTarik06 ?? '');
            $sheet->setCellValue('B41', $addPushPull->repeatabilityTarik07 ?? '');
            $sheet->setCellValue('C41', $addPushPull->repeatabilityTarik08 ?? '');
            $sheet->setCellValue('D41', $addPushPull->repeatabilityTarik09 ?? '');
            $sheet->setCellValue('E41', $addPushPull->repeatabilityTarik10 ?? '');
            
            // Repeatability TEKAN (baris 51-52)
            $sheet->setCellValue('A44', $addPushPull->repeatabilityTekan01 ?? '');
            $sheet->setCellValue('B44', $addPushPull->repeatabilityTekan02 ?? '');
            $sheet->setCellValue('C44', $addPushPull->repeatabilityTekan03 ?? '');
            $sheet->setCellValue('D44', $addPushPull->repeatabilityTekan04 ?? '');
            $sheet->setCellValue('E44', $addPushPull->repeatabilityTekan05 ?? '');
            $sheet->setCellValue('A45', $addPushPull->repeatabilityTekan06 ?? '');
            $sheet->setCellValue('B45', $addPushPull->repeatabilityTekan07 ?? '');
            $sheet->setCellValue('C45', $addPushPull->repeatabilityTekan08 ?? '');
            $sheet->setCellValue('D45', $addPushPull->repeatabilityTekan09 ?? '');
            $sheet->setCellValue('E45', $addPushPull->repeatabilityTekan10 ?? '');
            
            \Log::info('AddPushPull repeatability data filled', [
                'repeatabilityTarik01' => $addPushPull->repeatabilityTarik01,
                'repeatabilityTekan01' => $addPushPull->repeatabilityTekan01
            ]);
        }
        
        // ==============================================================
        // SIMPAN FILE
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Push Pull berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'details_count' => $details->count(),
            'has_repeatability' => $addPushPull ? true : false
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillPushPullExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillTimbanganExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Timbangan', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $calibration->jumlah_form ?? 1
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil jumlah form
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);
        
        // Ambil data dengan query langsung ke model
        $allHeads = \App\Models\HeadTimbangan::where('calibration_id', $calibration->id)->get();
        $allDetails = \App\Models\DetailTimbangan::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        $allAdds = \App\Models\AddTimbangan::where('calibration_id', $calibration->id)->get();
        
        // Kelompokkan data per form index
        $headsByForm = [];
        foreach ($allHeads as $head) {
            if ($head && isset($head->form_index)) {
                $headsByForm[$head->form_index] = $head;
            }
        }
        
        $detailsByForm = [];
        foreach ($allDetails as $detail) {
            if ($detail && isset($detail->form_index)) {
                if (!isset($detailsByForm[$detail->form_index])) {
                    $detailsByForm[$detail->form_index] = collect();
                }
                $detailsByForm[$detail->form_index]->push($detail);
            }
        }
        
        $addsByForm = [];
        foreach ($allAdds as $add) {
            if ($add && isset($add->form_index)) {
                $addsByForm[$add->form_index] = $add;
            }
        }
        
        \Log::info('📊 Data grouped by form', [
            'heads_found' => array_keys($headsByForm),
            'details_found' => array_keys($detailsByForm),
            'adds_found' => array_keys($addsByForm),
            'jumlah_form_dari_calibration' => $jumlahForm
        ]);
        
        // ==================================================================
        // LOOPING UNTUK SETIAP FORM INDEX (1 sampai jumlahForm)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Tentukan nama sheet ACTION
            $sheetName = ($formIndex == 1) ? 'ACTION' : "ACTION ({$formIndex})";
            
            // Coba ambil sheet, jika tidak ada maka buat
            $sheet = $spreadsheet->getSheetByName($sheetName);
            
            if (!$sheet) {
                // Jika sheet tidak ada, clone dari sheet ACTION
                $sourceSheet = $spreadsheet->getSheetByName('ACTION');
                if ($sourceSheet) {
                    $newSheet = clone $sourceSheet;
                    $newSheet->setTitle($sheetName);
                    $spreadsheet->addSheet($newSheet);
                    $sheet = $newSheet;
                    \Log::info("Created new sheet: {$sheetName}");
                } else {
                    throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Timbangan");
                }
            }
            
            // Isi cell K1 dengan nama user yang login (untuk semua sheet ACTION)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            
            // Ambil head untuk form ini
            $head = $headsByForm[$formIndex] ?? null;
            
            // Ambil details untuk form ini
            $formDetails = $detailsByForm[$formIndex] ?? collect();
            
            // Ambil add untuk form ini
            $add = $addsByForm[$formIndex] ?? null;
            
            \Log::info("📝 Processing form index {$formIndex}", [
                'sheet_name' => $sheetName,
                'has_head' => !is_null($head),
                'details_count' => $formDetails->count(),
                'has_add' => !is_null($add)
            ]);
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (HANYA UNTUK FORM 1)
            // ==============================================================
            if ($formIndex == 1) {
                $sheet->setCellValue('B1', $calibration->id ?? '');
                $sheet->setCellValue('E1', $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B2', $calibration->namaAlat ?? '');
                $sheet->setCellValue('B3', $calibration->brandAlat ?? '');
                $sheet->setCellValue('B5', $calibration->typeAlat ?? '');
                $sheet->setCellValue('B6', $calibration->NoSeri ?? '');
                $sheet->setCellValue('B4', $calibration->kodeAlat ?? '');
                $sheet->setCellValue('B18', $calibration->keterangan ?? '');
                $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
                
                // Jenis Alat Ukur (cell E2)
                $sheet->setCellValue('E2', $calibration->form_type ?? '');
                
                // Tanggal
                $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
                $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
                
                $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
                $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
                $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
                $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
                $sheet->setCellValue('B19', $calibration->kode_th ?? '');
                
                // Suhu & RH
                $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
                $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
                $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
                $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
                $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
                $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
                
                // Calibrated & Verified by
                $sheet->setCellValue('B71', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B72', $calibration->verifiedBy ?? '');
            }
            
            // ==============================================================
            // HEAD DATA KHUSUS TIMBANGAN PER FORM
            // ==============================================================
            if ($head) {
                // Range Min & Max
                $sheet->setCellValue('B7', $calibration->rangeMax ?? '');
                $sheet->setCellValue('B8', $calibration->rangeMin ?? '');
                
                // Kapasitas & Resolusi
                $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
                $sheet->setCellValue('B10', $calibration->resolusi ?? '');
                
                $sheet->setCellValue('A44', $head->note ?? '');
                $sheet->setCellValue('B27', $head->setengah_kapasitas ?? '');
                $sheet->setCellValue('B28', $head->kapasitas_max ?? '');
                
                // Alat Standar & Metode Kalibrasi
                $sheet->setCellValue('B69', $head->standard ?? '');
                $sheet->setCellValue('B70', $head->calibrationMethod ?? '');
                
                \Log::info("Form {$formIndex}: Head data filled from HeadTimbangan", [
                    'range_max' => $calibration->rangeMax ?? 'not set',
                    'range_min' => $calibration->rangeMin ?? 'not set',
                    'kapasitas' => $calibration->kapasitas ?? 'not set',
                    'resolusi' => $calibration->resolusi ?? 'not set',
                    'standard' => $head->standard ?? 'not set',
                    'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No head data found, using empty values");
                
                $sheet->setCellValue('B7', '');
                $sheet->setCellValue('B8', '');
                $sheet->setCellValue('B9', '');
                $sheet->setCellValue('B10', '');
                $sheet->setCellValue('B27', '');
                $sheet->setCellValue('B28', '');
            }
            
            // ==============================================================
            // DETAIL DATA TIMBANGAN PER FORM (SHEET ACTION)
            // ==============================================================
            if ($formDetails && $formDetails->count() > 0) {
                $sortedDetails = $formDetails->sortBy('id');
                $row = 52;
                
                foreach ($sortedDetails as $index => $detail) {
                    if ($index >= 13) break;
                    
                    $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                    $sheet->setCellValue('B' . $row, $detail->Lz1 ?? '');
                    $sheet->setCellValue('C' . $row, $detail->Lm1 ?? '');
                    $sheet->setCellValue('E' . $row, $detail->Rz1 ?? '');
                    $sheet->setCellValue('D' . $row, $detail->Rm1 ?? '');
                    $sheet->setCellValue('F' . $row, $detail->STD ?? '');
                    
                    $row++;
                }
                
                \Log::info("Form {$formIndex}: Filled {$formDetails->count()} detail rows");
            } else {
                \Log::warning("Form {$formIndex}: No detail data found");
            }
            
            // ==============================================================
            // DATA ADD TIMBANGAN (SHEET ACTION)
            // ==============================================================
            if ($add) {
                // HalfMax Z1
                $sheet->setCellValue('A32', $add->HalfMax_z1_01 ?? '');
                $sheet->setCellValue('A33', $add->HalfMax_z1_02 ?? '');
                $sheet->setCellValue('A34', $add->HalfMax_z1_03 ?? '');
                $sheet->setCellValue('A35', $add->HalfMax_z1_04 ?? '');
                $sheet->setCellValue('A36', $add->HalfMax_z1_05 ?? '');
                $sheet->setCellValue('A37', $add->HalfMax_z1_06 ?? '');
                $sheet->setCellValue('A38', $add->HalfMax_z1_07 ?? '');
                $sheet->setCellValue('A39', $add->HalfMax_z1_08 ?? '');
                $sheet->setCellValue('A40', $add->HalfMax_z1_09 ?? '');
                $sheet->setCellValue('A41', $add->HalfMax_z1_10 ?? '');
                
                // HalfMax M1
                $sheet->setCellValue('B32', $add->HalfMax_m1_01 ?? '');
                $sheet->setCellValue('B33', $add->HalfMax_m1_02 ?? '');
                $sheet->setCellValue('B34', $add->HalfMax_m1_03 ?? '');
                $sheet->setCellValue('B35', $add->HalfMax_m1_04 ?? '');
                $sheet->setCellValue('B36', $add->HalfMax_m1_05 ?? '');
                $sheet->setCellValue('B37', $add->HalfMax_m1_06 ?? '');
                $sheet->setCellValue('B38', $add->HalfMax_m1_07 ?? '');
                $sheet->setCellValue('B39', $add->HalfMax_m1_08 ?? '');
                $sheet->setCellValue('B40', $add->HalfMax_m1_09 ?? '');
                $sheet->setCellValue('B41', $add->HalfMax_m1_10 ?? '');
                
                // FullMax Z1
                $sheet->setCellValue('C32', $add->FullMax_z1_01 ?? '');
                $sheet->setCellValue('C33', $add->FullMax_z1_02 ?? '');
                $sheet->setCellValue('C34', $add->FullMax_z1_03 ?? '');
                $sheet->setCellValue('C35', $add->FullMax_z1_04 ?? '');
                $sheet->setCellValue('C36', $add->FullMax_z1_05 ?? '');
                $sheet->setCellValue('C37', $add->FullMax_z1_06 ?? '');
                $sheet->setCellValue('C38', $add->FullMax_z1_07 ?? '');
                $sheet->setCellValue('C39', $add->FullMax_z1_08 ?? '');
                $sheet->setCellValue('C40', $add->FullMax_z1_09 ?? '');
                $sheet->setCellValue('C41', $add->FullMax_z1_10 ?? '');
                
                // FullMax M1
                $sheet->setCellValue('D32', $add->FullMax_m1_01 ?? '');
                $sheet->setCellValue('D33', $add->FullMax_m1_02 ?? '');
                $sheet->setCellValue('D34', $add->FullMax_m1_03 ?? '');
                $sheet->setCellValue('D35', $add->FullMax_m1_04 ?? '');
                $sheet->setCellValue('D36', $add->FullMax_m1_05 ?? '');
                $sheet->setCellValue('D37', $add->FullMax_m1_06 ?? '');
                $sheet->setCellValue('D38', $add->FullMax_m1_07 ?? '');
                $sheet->setCellValue('D39', $add->FullMax_m1_08 ?? '');
                $sheet->setCellValue('D40', $add->FullMax_m1_09 ?? '');
                $sheet->setCellValue('D41', $add->FullMax_m1_10 ?? '');
                
                // Off Center Loading
                $sheet->setCellValue('B64', $add->bebanOffCenter ?? '');
                $sheet->setCellValue('B67', $add->offCenterMiddle ?? '');
                $sheet->setCellValue('C67', $add->offCenterFront ?? '');
                $sheet->setCellValue('D67', $add->offCenterBack ?? '');
                $sheet->setCellValue('E67', $add->offCenterRight ?? '');
                $sheet->setCellValue('F67', $add->offCenterLeft ?? '');
                
                \Log::info("Form {$formIndex}: AddTimbangan data filled");
            }
        }
        
        // ==================================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==================================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Timbangan berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms' => $jumlahForm,
            'sheets_processed' => $jumlahForm
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillTimbanganExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillTimbanganMoistureExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Timbangan Moisture', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil data dari model (hanya 1 form, tanpa form_index)
        $head = \App\Models\HeadTimbanganMoisture::where('calibration_id', $calibration->id)->first();
        $details = \App\Models\DetailTimbanganMoisture::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        $add = \App\Models\AddTimbanganMoisture::where('calibration_id', $calibration->id)->first();
        
        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Timbangan Moisture");
        }
        
        // Isi cell K1 dengan nama user yang login
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        \Log::info('📝 Processing Timbangan Moisture', [
            'has_head' => !is_null($head),
            'details_count' => $details ? $details->count() : 0,
            'has_add' => !is_null($add)
        ]);
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1', $calibration->id ?? '');
        $sheet->setCellValue('E1', $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2', $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3', $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5', $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6', $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4', $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B71', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B72', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA TIMBANGAN MOISTURE
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7', $calibration->rangeMax ?? '');
            $sheet->setCellValue('B8', $calibration->rangeMin ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            $sheet->setCellValue('A44', $head->note ?? '');
            $sheet->setCellValue('B27', $head->setengah_kapasitas ?? '');
            $sheet->setCellValue('B28', $head->kapasitas_max ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B69', $head->standard ?? '');
            $sheet->setCellValue('B70', $head->calibrationMethod ?? '');
            
            \Log::info('Head data filled from HeadTimbanganMoisture', [
                'range_max' => $calibration->rangeMax ?? 'not set',
                'range_min' => $calibration->rangeMin ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA TIMBANGAN MOISTURE (SHEET ACTION)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $sortedDetails = $details->sortBy('id');
            
            // ==============================================================
            // 1. DATA TITIK UKUR (ROW 52-64)
            // ==============================================================
            $row = 52;
            foreach ($sortedDetails as $index => $detail) {
                if ($index >= 13) break;
                
                $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                $sheet->setCellValue('B' . $row, $detail->Lz1 ?? '');
                $sheet->setCellValue('C' . $row, $detail->Lm1 ?? '');
                $sheet->setCellValue('E' . $row, $detail->Rz1 ?? '');
                $sheet->setCellValue('D' . $row, $detail->Rm1 ?? '');
                $sheet->setCellValue('F' . $row, $detail->STD ?? '');
                
                $row++;
            }
            
            // ==============================================================
            // 2. DATA MOISTURE KHUSUS (SETTING SUHU, PEMBACAAN ALAT & STANDAR)
            //    Setiap row di detail mewakili 1 setting suhu
            //    Field yang sama: Tsetting, ReadAlat01-03, ReadSTD01-03
            // ==============================================================
            
            // Ambil 3 row pertama untuk moisture (atau sesuai jumlah yang ada)
            $moistureRows = $sortedDetails->take(3);
            $moistureIndex = 0;
            
