public function fillUltrasonicThicknessGaugeExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Ultrasonic Thickness Gauge', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $calibration->jumlah_form ?? 1
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil jumlah form
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);
        
        // 🔥 Ambil data dengan query langsung ke model
        $allHeads = \App\Models\HeadUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->get();
        $allDetails = \App\Models\DetailUltrasonicThicknessGauge::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // Kelompokkan data per form index
        $headsByForm = [];
        foreach ($allHeads as $head) {
            if ($head && isset($head->form_index)) {
                $headsByForm[$head->form_index] = $head;
            }
        }
        
        $detailsByForm = [];
        foreach ($allDetails as $detail) {
            if ($detail && isset($detail->form_index)) {
                if (!isset($detailsByForm[$detail->form_index])) {
                    $detailsByForm[$detail->form_index] = collect();
                }
                $detailsByForm[$detail->form_index]->push($detail);
            }
        }
        
        \Log::info('📊 Data grouped by form for Ultrasonic Thickness Gauge', [
            'heads_found' => array_keys($headsByForm),
            'details_found' => array_keys($detailsByForm),
            'jumlah_form_dari_calibration' => $jumlahForm
        ]);
        
        // ==================================================================
        // LOOPING UNTUK SETIAP FORM INDEX (1 sampai jumlahForm)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Tentukan nama sheet
            $sheetName = ($formIndex == 1) ? 'ACTION' : "ACTION ({$formIndex})";
            
            // Coba ambil sheet, jika tidak ada maka buat
            $sheet = $spreadsheet->getSheetByName($sheetName);
            
            if (!$sheet) {
                // Jika sheet tidak ada, clone dari sheet ACTION
                $sourceSheet = $spreadsheet->getSheetByName('ACTION');
                if ($sourceSheet) {
                    $newSheet = clone $sourceSheet;
                    $newSheet->setTitle($sheetName);
                    $spreadsheet->addSheet($newSheet);
                    $sheet = $newSheet;
                    \Log::info("Created new sheet: {$sheetName}");
                } else {
                    throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Ultrasonic Thickness Gauge");
                }
            }
            
            // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            
            // Ambil head untuk form ini
            $head = $headsByForm[$formIndex] ?? null;
            // Ambil details untuk form ini
            $formDetails = $detailsByForm[$formIndex] ?? collect();
            
            \Log::info("📝 Processing form index {$formIndex}", [
                'sheet_name' => $sheetName,
                'has_head' => !is_null($head),
                'details_count' => $formDetails->count()
            ]);
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (HANYA UNTUK FORM 1)
            // ==============================================================
            if ($formIndex == 1) {
                $sheet->setCellValue('B1',  $calibration->id ?? '');
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
                $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
                $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
                $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
                $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
                // $sheet->setCellValue('B18', $calibration->keterangan ?? '');
                $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
                $sheet->setCellValue('B9', $calibration->kapasitas ?? '');
                $sheet->setCellValue('B10', $calibration->resolusi ?? '');
                $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
                $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
                
                $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
                $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
                $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
                $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
                $sheet->setCellValue('B19', $calibration->kode_th ?? '');
                
                // Suhu & RH
                $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
                $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
                $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
                $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
                $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
                $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
                
                // Calibrated & Verified by
                $sheet->setCellValue('B46', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B47', $calibration->verifiedBy ?? '');
            } else {
                // Untuk form 2,3,4,5 - hanya isi certificate ID dan data spesifik form
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
                
                \Log::info("Form {$formIndex}: Filled certificate ID and basic info");
            }
            
            // ==============================================================
            // 🔥 HEAD DATA KHUSUS ULTRASONIC THICKNESS GAUGE PER FORM
            // Data Standard, Calibration Method, Satuan Unit diambil dari 
            // HeadUltrasonicThicknessGauge (per form)
            // ==============================================================
            if ($head) {
                // Data dari HeadUltrasonicThicknessGauge
                $sheet->setCellValue('B44', $head->standard ?? '');
                $sheet->setCellValue('B45', $head->calibrationMethod ?? '');
                
                // Satuan Unit
                $satuanUnit = $head->satuan_unit ?? 'mm';
                $sheet->setCellValue('B27', $satuanUnit);
                
                // Keterangan Fungsi Komponen (jika ada kolomnya di Excel)
                if ($head->keterangan_fungsi_komponen) {
                    $sheet->setCellValue('B18', $head->keterangan_fungsi_komponen ?? '');
                }
                
                \Log::info("Form {$formIndex}: Head data filled from HeadUltrasonicThicknessGauge", [
                    'standard' => $head->standard,
                    'calibrationMethod' => $head->calibrationMethod,
                    'satuan_unit' => $satuanUnit,
                    'keterangan_fungsi_komponen' => $head->keterangan_fungsi_komponen
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No head data found, using defaults");
                
                // Set default values jika head tidak ditemukan
                $sheet->setCellValue('B43', '');
                $sheet->setCellValue('B44', '');
                $sheet->setCellValue('B24', '');
                $sheet->setCellValue('B47', '');
            }
            
            // ==============================================================
            // DETAIL DATA (baris mulai 27) PER FORM
            // Data: Nominal STD dan Ulangan 1-5
            // ==============================================================
            if ($formDetails && $formDetails->count() > 0) {
                $sortedDetails = $formDetails->sortBy('id');
                $row = 28;
                foreach ($sortedDetails as $index => $detail) {
                    if ($index >= 20) break;
                    
                    // Sesuai dengan kolom di DetailUltrasonicThicknessGauge
                    $sheet->setCellValue('A' . $row, $detail->nominalSTD ?? '');
                    $sheet->setCellValue('B' . $row, $detail->ulangan01 ?? '');
                    $sheet->setCellValue('C' . $row, $detail->ulangan02 ?? '');
                    $sheet->setCellValue('D' . $row, $detail->ulangan03 ?? '');
                    $sheet->setCellValue('E' . $row, $detail->ulangan04 ?? '');
                    $sheet->setCellValue('F' . $row, $detail->ulangan05 ?? '');
                    
                    $row++;
                }
                \Log::info("Form {$formIndex}: Filled {$formDetails->count()} detail rows");
            } else {
                \Log::warning("Form {$formIndex}: No detail data found");
            }
        }
        
        // ==================================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==================================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Ultrasonic Thickness Gauge berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms' => $jumlahForm,
            'sheets_processed' => $jumlahForm
        ]);
        
    } catch (\Exception $e) {
        \Log::error('Error fillUltrasonicThicknessGauge: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
public function fillHeightGaugeExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Height Gauge', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Height Gauge");
        }
        
        // Isi cell K1 dengan nama user yang login
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // 🔥 Ambil data dari database
        $head = \App\Models\HeadHeightGauge::where('calibration_id', $calibration->id)->first();
        $details = \App\Models\DetailHeightGauge::where('calibration_id', $calibration->id)
                    ->orderBy('id', 'asc')
                    ->get();
        
        \Log::info('📊 Data Height Gauge', [
            'has_head' => !is_null($head),
            'details_count' => $details->count()
        ]);
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // 🔥 DATA DARI CALIBRATION 
        // Kapasitas, Resolusi, dan Rentang Ukur (Min/Max)
        // ==============================================================
        // Kapasitas & Resolusi dari tabel calibration
        $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
        $sheet->setCellValue('B10', $calibration->resolusi ?? '');
        
        // Rentang Ukur Min & Max dari tabel calibration (rangeMin & rangeMax)
        $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
        $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
        
        // Satuan Unit (dari head jika ada, atau default)
        $satuanUnit = $head->satuan_titik_ukur ?? $calibration->satuan_unit ?? 'mm';
        $sheet->setCellValue('B24', $satuanUnit);
        
        \Log::info('Data dari CALIBRATION', [
            'kapasitas' => $calibration->kapasitas,
            'resolusi' => $calibration->resolusi,
            'rangeMin' => $calibration->rangeMin,
            'rangeMax' => $calibration->rangeMax,
            'satuan_unit' => $satuanUnit
        ]);
        
        // ==============================================================
        // HEAD DATA DARI HeadHeightGauge
        // Standard & Metode Kalibrasi
        // ==============================================================
        if ($head) {
            // Alat Standar & Metode Kalibrasi dari head
            $sheet->setCellValue('B43', $head->standard ?? '');
            $sheet->setCellValue('B44', $head->calibrationMethod ?? '');
            
            \Log::info('Head data filled from HeadHeightGauge', [
                'standard' => $head->standard,
                'calibrationMethod' => $head->calibrationMethod,
                'satuan_titik_ukur' => $head->satuan_titik_ukur
            ]);
        } else {
            \Log::warning('No head data found, using defaults');
            $sheet->setCellValue('B43', '');
            $sheet->setCellValue('B44', '');
        }
        
        // ==============================================================
        // DETAIL DATA (baris mulai 27)
        // Sesuai dengan model DetailHeightGauge:
        // nominal_value, alat_1, alat_2, alat_3, alat_4, alat_5
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 27;
            foreach ($details as $index => $detail) {
                if ($index >= 20) break; // Maksimal 20 baris data
                
                // Sesuai dengan model DetailHeightGauge
                $sheet->setCellValue('A' . $row, $detail->nominal_value ?? '');
                $sheet->setCellValue('B' . $row, $detail->alat_1 ?? '');
                $sheet->setCellValue('C' . $row, $detail->alat_2 ?? '');
                $sheet->setCellValue('D' . $row, $detail->alat_3 ?? '');
                $sheet->setCellValue('E' . $row, $detail->alat_4 ?? '');
                $sheet->setCellValue('F' . $row, $detail->alat_5 ?? '');
                
                $row++;
            }
            \Log::info("Filled {$details->count()} detail rows");
        } else {
            \Log::warning('No detail data found');
        }
        
        // ==================================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==================================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Height Gauge berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (\Exception $e) {
        \Log::error('Error fillHeightGaugeExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillTempHumidTransmitterExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Temperature Humidity Transmitter', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Temperature Humidity Transmitter");
        }
        
        // Ambil data HeadTempHumidTransmitter
        $head = \App\Models\HeadTempHumidTransmitter::where('calibration_id', $calibration->id)->first();
        
        // Ambil data Detail_T_TempHumidTransmitter (Celcius)
        $detailC = \App\Models\Detail_T_TempHumidTransmitter::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // Ambil data Detail_RH_TempHumidTransmitter (RH%)
        $detailRH = \App\Models\Detail_RH_TempHumidTransmitter::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B49', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B50', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA TEMPERATURE HUMIDITY TRANSMITTER
        // ==============================================================
        if ($head) {
            // Kapasitas & Resolusi untuk Celcius
            $sheet->setCellValue('B54', $head->kapasitas_min_c ?? '0');
            $sheet->setCellValue('B55', $head->kapasitas_max_c ?? '');
            $sheet->setCellValue('B56', $head->resolusi_c ?? '');
            
            // Kapasitas & Resolusi untuk RH%
            $sheet->setCellValue('B57', $head->kapasitas_min_rh ?? '0');
            $sheet->setCellValue('B58', $head->kapasitas_max_rh ?? '');
            $sheet->setCellValue('B59', $head->resolusi_rh ?? '');
            
            // Kapasitas & Resolusi untuk mA
            $sheet->setCellValue('B60', $head->kapasitas_min_ma ?? '0');
            $sheet->setCellValue('B61', $head->kapasitas_max_ma ?? '');
            $sheet->setCellValue('B62', $head->resolusi_ma ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B47', $head->standard ?? '');
            $sheet->setCellValue('B48', $head->calibrationMethod ?? '');
            $sheet->setCellValue('B51', $head->tertelusur ?? '');
            
            \Log::info('Head data filled from HeadTempHumidTransmitter', [
                'kapasitas_min_c' => $head->kapasitas_min_c ?? 'not set',
                'kapasitas_max_c' => $head->kapasitas_max_c ?? 'not set',
                'resolusi_c' => $head->resolusi_c ?? 'not set',
                'kapasitas_min_rh' => $head->kapasitas_min_rh ?? 'not set',
                'kapasitas_max_rh' => $head->kapasitas_max_rh ?? 'not set',
                'resolusi_rh' => $head->resolusi_rh ?? 'not set',
                'kapasitas_min_ma' => $head->kapasitas_min_ma ?? 'not set',
                'kapasitas_max_ma' => $head->kapasitas_max_ma ?? 'not set',
                'resolusi_ma' => $head->resolusi_ma ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'tertelusur' => $head->tertelusur ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA C (CELCIUS) - Detail_T_TempHumidTransmitter
        // Kolom: T_setting, T_STD1, T_STD2, T_STD3, T_OSmA1, T_OSmA2, T_OSmA3
        // Sheet ACTION: A27-A34 (Titik Ukur), B27-D27 (T_STD1-3), E27-G27 (T_OSmA1-3)
        // ==============================================================
        if ($detailC && $detailC->count() > 0) {
            $row = 27;
            $detailIndex = 0;
            
            foreach ($detailC as $detail) {
                if ($row > 34) break; // Max 8 baris (A27-A34)
                
                // Titik Ukur -> A27-A34 (menggunakan T_setting)
                $sheet->setCellValue('A' . $row, $detail->T_setting ?? '');
                
                // Perulangan Celcius (3 data) -> B27-D27 (T_STD1, T_STD2, T_STD3)
                $sheet->setCellValue('B' . $row, $detail->T_STD1 ?? '');
                $sheet->setCellValue('C' . $row, $detail->T_STD2 ?? '');
                $sheet->setCellValue('D' . $row, $detail->T_STD3 ?? '');
                
                // Perulangan mA (3 data) -> E27-G27 (T_OSmA1, T_OSmA2, T_OSmA3)
                $sheet->setCellValue('E' . $row, $detail->T_OSmA1 ?? '');
                $sheet->setCellValue('F' . $row, $detail->T_OSmA2 ?? '');
                $sheet->setCellValue('G' . $row, $detail->T_OSmA3 ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows for Celcius (Detail_T_TempHumidTransmitter)");
        }
        
        // ==============================================================
        // DETAIL DATA RH% - Detail_RH_TempHumidTransmitter
        // Kolom: RH_setting, RH_STD1, RH_STD2, RH_STD3, RH_OSmA1, RH_OSmA2, RH_OSmA3
        // Sheet ACTION: A38-A45 (Titik Ukur), B38-D38 (RH_STD1-3), E38-G38 (RH_OSmA1-3)
        // ==============================================================
        if ($detailRH && $detailRH->count() > 0) {
            $row = 38;
            $detailIndex = 0;
            
            foreach ($detailRH as $detail) {
                if ($row > 45) break; // Max 8 baris (A38-A45)
                
                // Titik Ukur -> A38-A45 (menggunakan RH_setting)
                $sheet->setCellValue('A' . $row, $detail->RH_setting ?? '');
                
                // Perulangan RH (3 data) -> B38-D38 (RH_STD1, RH_STD2, RH_STD3)
                $sheet->setCellValue('B' . $row, $detail->RH_STD1 ?? '');
                $sheet->setCellValue('C' . $row, $detail->RH_STD2 ?? '');
                $sheet->setCellValue('D' . $row, $detail->RH_STD3 ?? '');
                
                // Perulangan mA (3 data) -> E38-G38 (RH_OSmA1, RH_OSmA2, RH_OSmA3)
                $sheet->setCellValue('E' . $row, $detail->RH_OSmA1 ?? '');
                $sheet->setCellValue('F' . $row, $detail->RH_OSmA2 ?? '');
                $sheet->setCellValue('G' . $row, $detail->RH_OSmA3 ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows for RH% (Detail_RH_TempHumidTransmitter)");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
