        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B59', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B60', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA TEMPERATURE TRANSMITTER
        // ==============================================================
        if ($head) {
            // Kapasitas & Resolusi untuk Celcius
            $sheet->setCellValue('B65', $head->kapasitas_min_c ?? '0');
            $sheet->setCellValue('B66', $head->kapasitas_max_c ?? '');
            $sheet->setCellValue('B67', $head->resolusi_c ?? '');
            
            // Kapasitas & Resolusi untuk mA
            $sheet->setCellValue('B68', $head->kapasitas_min_ma ?? '0');
            $sheet->setCellValue('B69', $head->kapasitas_max_ma ?? '');
            $sheet->setCellValue('B70', $head->resolusi_ma ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B57', $head->standard ?? '');
            $sheet->setCellValue('B58', $head->calibrationMethod ?? '');
          
            
            // Satuan (jika ada di head)
            $sheet->setCellValue('E26', $head->satuan_suhu_kiri ?? '');
        
            $sheet->setCellValue('F26', $head->satuan_std_kiri ?? '');
     
            $sheet->setCellValue('G26', $head->satuan_indicator_kiri ?? '');
           
            
            // Media & Indicator
            $sheet->setCellValue('B61', $head->media ?? '');
            $sheet->setCellValue('B62', $head->indicator ?? '');
            
            \Log::info('Head data filled from HeadTempTransmitter', [
                'kapasitas_min_c' => $head->kapasitas_min_c ?? 'not set',
                'kapasitas_max_c' => $head->kapasitas_max_c ?? 'not set',
                'resolusi_c' => $head->resolusi_c ?? 'not set',
                'kapasitas_min_ma' => $head->kapasitas_min_ma ?? 'not set',
                'kapasitas_max_ma' => $head->kapasitas_max_ma ?? 'not set',
                'resolusi_ma' => $head->resolusi_ma ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'tertelusur' => $head->tertelusur ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA - DetailTempTransmitter
        // Data di sheet ACTION: 
        // A26 untuk T_setting, B26-B28 untuk T_STD1-3, C26-C28 untuk T_Indicator1-3
        // A29 untuk T_setting, B29-B31 untuk T_STD1-3, C29-C31 untuk T_Indicator1-3
        // Sampai A53 (total 28 data point)
        // 
        // Data di sheet INPUT DATA:
        // A53 untuk T_setting, C53-C55 untuk T_STD1-3, E53-E55 untuk T_Indicator1-3
        // A56 untuk T_setting, C56-C58 untuk T_STD1-3, E56-E58 untuk T_Indicator1-3
        // Sampai baris 80
        // ==============================================================
       if ($details && $details->count() > 0) {
            $row = 26; // Mulai dari A26
            $detailIndex = 0;
            $maxDataPoints = 28; // Maksimal 28 data point (A26 sampai A53)
            
            foreach ($details as $detail) {
                // Batas maksimal 28 data point (A26 sampai A53)
                if ($detailIndex >= $maxDataPoints) {
                    \Log::warning('Data detail melebihi 28 data point, data ke-' . ($detailIndex + 1) . ' diabaikan', [
                        'calibration_id' => $calibration->id
                    ]);
                    break;
                }
                
                // T_setting -> A26, A29, A32, A35, A38, A41, A44, A47, A50, A53, ...
                $sheet->setCellValue('A' . $row, $detail->T_setting ?? '');
                
                // T_STD (3 nilai) -> B26-B28, B29-B31, B32-B34, dst.
                $sheet->setCellValue('B' . $row, $detail->T_STD1 ?? '');
                $sheet->setCellValue('B' . ($row + 1), $detail->T_STD2 ?? '');
                $sheet->setCellValue('B' . ($row + 2), $detail->T_STD3 ?? '');
                
                // T_Indicator (3 nilai) -> C26-C28, C29-C31, C32-C34, dst.
                $sheet->setCellValue('C' . $row, $detail->T_Indicator1 ?? '');
                $sheet->setCellValue('C' . ($row + 1), $detail->T_Indicator2 ?? '');
                $sheet->setCellValue('C' . ($row + 2), $detail->T_Indicator3 ?? '');
                
                // Increment untuk data berikutnya (loncat 3 baris)
                $row += 3;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows for Temperature Transmitter", [
                'total_data' => $details->count(),
                'max_data_used' => $detailIndex,
                'last_row' => $row - 3
            ]);
        } else {
            \Log::warning('Tidak ada data detail untuk Temperature Transmitter', [
                'calibration_id' => $calibration->id
            ]);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Temperature Transmitter berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'detail_count' => $details->count()
        ]);
        
        return true;
        
    } catch (Exception $e) {
        \Log::error('Error fillTempTransmitter: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

