                // Ulangan5 -> F31-F33
                $sheet->setCellValue('F' . $row, $detail->ulangan5 ?? '');
                
                // Suhu CRM -> G31-G33
                $sheet->setCellValue('G' . $row, $detail->suhuCRM ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Visco Cup)");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Visco Cup berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillViscoCupExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillPhMeterExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk pH Meter', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template pH Meter");
        }
        
        // Ambil data HeadPhMeter (hanya 1 form)
        $head = \App\Models\HeadPhMeter::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailPhMeter
        $details = \App\Models\DetailPhMeter::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? 'pH Meter');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B35', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B36', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA pH METER
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Unit pH - Dari calibration atau default
            $sheet->setCellValue('A26', $calibration->satuan_unit ?? 'pH');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B33', $head->standard ?? '');
            $sheet->setCellValue('B34', $head->calibrationMethod ?? '');
            
            \Log::info('Head data filled from HeadPhMeter', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA pH METER
        // Format sheet ACTION berdasarkan model DetailPhMeter:
        // Baris A27-A31: nilaiBuffer (Nilai Buffer pH Standard)
        // Baris B27-B31: rep01 (Pembacaan 1)
        // Baris C27-C31: rep02 (Pembacaan 2)
        // Baris D27-D31: rep03 (Pembacaan 3)
        // Baris E27-E31: rep04 (Pembacaan 4)
        // Baris F27-F31: rep05 (Pembacaan 5)
        // Baris G27-G31: Resolusi (Diisi per baris sesuai data)
        // Baris H27-H31: TBuffer (Suhu Buffer - Diisi per baris sesuai data)
        // ==============================================================
        
        // KOSONGKAN SEMUA CELL TERLEBIH DAHULU (27-31)
        for ($row = 27; $row <= 31; $row++) {
            $sheet->setCellValue('A' . $row, '');
            $sheet->setCellValue('B' . $row, '');
            $sheet->setCellValue('C' . $row, '');
            $sheet->setCellValue('D' . $row, '');
            $sheet->setCellValue('E' . $row, '');
            $sheet->setCellValue('F' . $row, '');
            $sheet->setCellValue('G' . $row, '');
            $sheet->setCellValue('H' . $row, '');
        }
        
        // Proses detail data sesuai jumlah yang ada
        if ($details && $details->count() > 0) {
            $row = 27;
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 31) break; // Max 5 baris (A27-A31)
                
                // nilaiBuffer (Nilai Buffer) -> A27-A31
                $sheet->setCellValue('A' . $row, $detail->nilaiBuffer ?? '');
                
                // rep01 (Pembacaan 1) -> B27-B31
                $sheet->setCellValue('B' . $row, $detail->rep01 ?? '');
                
                // rep02 (Pembacaan 2) -> C27-C31
                $sheet->setCellValue('C' . $row, $detail->rep02 ?? '');
                
                // rep03 (Pembacaan 3) -> D27-D31
                $sheet->setCellValue('D' . $row, $detail->rep03 ?? '');
                
                // rep04 (Pembacaan 4) -> E27-E31
                $sheet->setCellValue('E' . $row, $detail->rep04 ?? '');
                
                // rep05 (Pembacaan 5) -> F27-F31
                $sheet->setCellValue('F' . $row, $detail->rep05 ?? '');
                
                // Resolusi -> G27-G31 (sesuai data masing-masing)
                $sheet->setCellValue('G' . $row, $detail->Resolusi ?? '');
                
                // TBuffer (Suhu Buffer) -> H27-H31 (sesuai data masing-masing)
                $sheet->setCellValue('H' . $row, $detail->Tbuffer ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (pH Meter)", [
                'fields' => ['nilaiBuffer', 'rep01', 'rep02', 'rep03', 'rep04', 'rep05', 'Resolusi', 'TBuffer'],
                'total_data' => $detailIndex,
                'rows_used' => ($row - 1) // Baris terakhir yang terisi
            ]);
        } else {
            \Log::warning('Tidak ada detail data untuk pH Meter', [
                'calibration_id' => $calibration->id
            ]);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data pH Meter berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_details' => $details->count()
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillPhMeterExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}


       public function fillEnclosureExcel($filePath, $calibration)
    {
        $tempImagePath = null; // Menyimpan path file temporary jika didownload dari URL
        try {
            \Log::info('Mengisi data Excel untuk Enclosure Calibration', [
                'calibration_id' => $calibration->id
            ]);
            // Load file Excel template
            $spreadsheet = IOFactory::load($filePath);
            
            // 1. AMBIL NAMA USER DARI SESSION / AUTH LOGIN
            $userName = '';
            if (auth()->check()) {
                $userName = auth()->user()->nama;
            } elseif (session()->has('user_name')) {
                $userName = session('user_name');
            } elseif (session()->has('nama_user')) {
                $userName = session('nama_user');
            }
            
            // 2. AMBIL SHEET 'ACTION'
            $sheet = $spreadsheet->getSheetByName('ACTION');
            if (!$sheet) {
                throw new Exception("Sheet 'ACTION' tidak ditemukan di template Enclosure");
            }
            
            // 3. AMBIL DATA DARI MODEL RELATION (Diurutkan berdasarkan repetition_number)
            $head    = HeadEnclosure::where('calibration_id', $calibration->id)->first();
            $adds    = AddEnclosure::where('calibration_id', $calibration->id)
                        ->orderBy('repetition_number', 'asc')
                        ->orderBy('id', 'asc')
                        ->get();
            $details = DetailEnclosure::where('calibration_id', $calibration->id)
                        ->orderBy('repetition_number', 'asc')
                        ->orderBy('interval_number', 'asc')
                        ->get();
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (SHEET ACTION)
            // ==============================================================
            $sheet->setCellValue('B1',  $calibration->id ?? '');
            $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
            $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
            $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
            $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
            $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
            $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
            $sheet->setCellValue('B18', $calibration->keterangan ?? '');
            $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
            
            // Jenis Alat Ukur (cell E2)
            $sheet->setCellValue('E2', $calibration->form_type ?? '');
            
            // Tanggal Masuk & Tanggal Kalibrasi
            $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
            $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
            
            $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
            $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
            $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
            $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
            $sheet->setCellValue('B19', $calibration->kode_th ?? '');
            
            // Suhu (RT) & Kelembaban (RH)
            $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
            $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
            $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
            $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
            $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
            $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
            
            // Range, Kapasitas & Resolusi
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Calibrated & Verified by
            $sheet->setCellValue('B82', $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B83', $calibration->verifiedBy ?? '');
            
            // ==============================================================
            // HEAD DATA ENCLOSURE (STANDARD, METHOD, & GAMBAR CELL A26)
            // ==============================================================
            if ($head) {
                $sheet->setCellValue('B80', $head->standard ?? ''); // Digunakan untuk pembacaan makro VBA
                $sheet->setCellValue('B81', $head->calibrationMethod ?? '');
                
                // ----------------------------------------------------------
                // AMBIL & TEMPELKAN GAMBAR KE SHEET ACTION CELL A26
                // ----------------------------------------------------------
                if (!empty($head->keterangan_gambar)) {
                    $relativeUrl = trim($head->keterangan_gambar);
                    
                    // Tulis string path gambar ke Cell A26 sebagai teks dasar
                    $sheet->setCellValue('A26', $relativeUrl);
                    
                    $imagePath = null;
                    
                    // Penelusuran lokasi file gambar di server
                    if (file_exists(public_path($relativeUrl))) {
                        $imagePath = public_path($relativeUrl);
                    } 
                    elseif (file_exists(storage_path('app/public/' . $relativeUrl))) {
                        $imagePath = storage_path('app/public/' . $relativeUrl);
                    } 
                    elseif (file_exists(storage_path('app/' . $relativeUrl))) {
                        $imagePath = storage_path('app/' . $relativeUrl);
                    } 
                    elseif (filter_var($relativeUrl, FILTER_VALIDATE_URL) || preg_match('/^https?:\/\//i', $relativeUrl)) {
                        $imageContent = @file_get_contents($relativeUrl);
                        if ($imageContent !== false) {
                            $ext = pathinfo(parse_url($relativeUrl, PHP_URL_PATH), PATHINFO_EXTENSION) ?: 'png';
                            $tempImagePath = sys_get_temp_dir() . '/enc_img_' . uniqid() . '.' . $ext;
                            file_put_contents($tempImagePath, $imageContent);
                            $imagePath = $tempImagePath;
                        }
                    }
                    else {
                        $fullUrl = url($relativeUrl);
                        $imageContent = @file_get_contents($fullUrl);
                        if ($imageContent !== false) {
                            $ext = pathinfo($relativeUrl, PATHINFO_EXTENSION) ?: 'png';
                            $tempImagePath = sys_get_temp_dir() . '/enc_img_' . uniqid() . '.' . $ext;
                            file_put_contents($tempImagePath, $imageContent);
                            $imagePath = $tempImagePath;
                        }
                    }
                    
                    // Sisipkan objek gambar ke Sheet ACTION Cell A26
                    if ($imagePath && file_exists($imagePath)) {
                        $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
                        $drawing->setName('Gambar Teknisi Enclosure');
                        $drawing->setDescription('Gambar Enclosure Cell A26');
                        $drawing->setPath($imagePath);
                        $drawing->setCoordinates('A26');
                        $drawing->setHeight(140);
                        $drawing->setWorksheet($sheet);
                        
                        \Log::info('SUKSES! Menyisipkan objek gambar ke cell ACTION!A26', [
                            'resolved_path' => $imagePath
                        ]);
                    } else {
                        Log::warning('Gambar dari keterangan_gambar tidak dapat ditemukan di server', [
                            'input_path' => $relativeUrl
                        ]);
                    }
                }
            }
            
            // ==============================================================
            // DATA ADD ENCLOSURE (TSETTING PER REPETITION) - SUDAH FIX
            // ==============================================================
            // Repetition 1 = B32, Repetition 2 = B44, Repetition 3 = B56, Repetition 4 = B68
            $tsettingCells = [
                1 => 'B32',
                2 => 'B44',
                3 => 'B56',
                4 => 'B68'
            ];
            
            foreach ($adds as $index => $add) {
                // Mengambil nomor repetition dari kolom repetition_number database
                $rep = $add->repetition_number ?? $add->repetition ?? ($index + 1);
                
                // Ambil nilai Tsetting
                $tSettingValue = $add->Tsetting ?? $add->tsetting ?? '';
                
                // Masukkan nilai Tsetting ke cell Excel sesuai nomor repetition-nya
                if (isset($tsettingCells[$rep])) {
                    $sheet->setCellValue($tsettingCells[$rep], $tSettingValue);
                }
            }
            
            // ==============================================================
            // KELOMPOKKAN DETAIL ENCLOSURE BERDASARKAN REPETITION & INTERVAL
            // ==============================================================
            $detailsByRepetition = [];
            foreach ($details as $detail) {
                $rep = $detail->repetition_number ?? $detail->repetition ?? 1;
                $interval = $detail->interval_number ?? $detail->interval ?? 1;
                $detailsByRepetition[$rep][$interval] = $detail;
            }
            
            // ==============================================================
            // DATA INTERVAL WAKTU PER REPETITION (KOLOM A)
            // ==============================================================
            $intervalCells = [
                1 => ['start' => 35, 'end' => 42],
                2 => ['start' => 47, 'end' => 54],
                3 => ['start' => 59, 'end' => 66],
                4 => ['start' => 71, 'end' => 78]
            ];
            
            foreach ($intervalCells as $rep => $range) {
                if (isset($detailsByRepetition[$rep])) {
                    $row = $range['start'];
                    $endRow = $range['end'];
                    
                    ksort($detailsByRepetition[$rep]);
                    
                    foreach ($detailsByRepetition[$rep] as $interval => $detail) {
                        if ($row <= $endRow) {
                            $sheet->setCellValue('A' . $row, $detail->interval_number ?? '');
                            $row++;
                        }
                    }
                }
            }
            
            // ==============================================================
            // DETAIL DATA ENCLOSURE (READ ALAT & SENSOR 1 s/d SENSOR 9)
            // ==============================================================
            $dataRows = [
                1 => ['start' => 35, 'end' => 42],
                2 => ['start' => 47, 'end' => 54],
                3 => ['start' => 59, 'end' => 66],
                4 => ['start' => 71, 'end' => 78]
            ];
            
            foreach ($dataRows as $rep => $range) {
                if (isset($detailsByRepetition[$rep])) {
                    $row = $range['start'];
                    $endRow = $range['end'];
                    
                    ksort($detailsByRepetition[$rep]);
                    
                    foreach ($detailsByRepetition[$rep] as $interval => $detail) {
                        if ($row <= $endRow) {
                            // Kolom B = Read Alat
                            $sheet->setCellValue('B' . $row, $detail->readAlat ?? '');
                            
                            // Kolom C s/d K = Read Sensor 1 s/d Sensor 9
                            $sheet->setCellValue('C' . $row, $detail->readSensor1 ?? '');
                            $sheet->setCellValue('D' . $row, $detail->readSensor2 ?? '');
                            $sheet->setCellValue('E' . $row, $detail->readSensor3 ?? '');
                            $sheet->setCellValue('F' . $row, $detail->readSensor4 ?? '');
                            $sheet->setCellValue('G' . $row, $detail->readSensor5 ?? '');
                            $sheet->setCellValue('H' . $row, $detail->readSensor6 ?? '');
                            $sheet->setCellValue('I' . $row, $detail->readSensor7 ?? '');
                            $sheet->setCellValue('J' . $row, $detail->readSensor8 ?? '');
                            $sheet->setCellValue('K' . $row, $detail->readSensor9 ?? '');
                            
                            $row++;
                        }
                    }
                }
            }
            
            \Log::info("Filled {$details->count()} DetailEnclosure rows into Excel");
            
            // ==============================================================
            // ISI CELL K1 DENGAN NAMA USER
            // ==============================================================
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            
            // ==============================================================
            // OPTIMASI DAN SIMPAN FILE EXCEL
            // ==============================================================
            $spreadsheet->setActiveSheetIndex(0);
            $spreadsheet->garbageCollect();
            
            $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
            $calculationEngine->setCalculationCacheEnabled(false);
            $calculationEngine->clearCalculationCache();
            
            $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
            $writer->setPreCalculateFormulas(false);
            $writer->save($filePath);
            
            // Hapus file gambar temporary jika ada
            if ($tempImagePath && file_exists($tempImagePath)) {
                @unlink($tempImagePath);
            }
            
            \Log::info('SUKSES! Data Enclosure dan Gambar A26 berhasil diisi ke Excel', [
                'calibration_id' => $calibration->id
            ]);
            
        } catch (\Exception $e) {
            // Hapus temp file jika terjadi error saat proses
            if ($tempImagePath && file_exists($tempImagePath)) {
                @unlink($tempImagePath);
            }
            
            \Log::error('Error fillEnclosureExcel: ' . $e->getMessage(), [
                'calibration_id' => $calibration->id ?? null,
                'trace' => $e->getTraceAsString()
            ]);
            
            throw $e;
        }
    }

public function fillAutoclaveExcel($filePath, $calibration)
{
    $tempImagePath = null; // Menyimpan path file temporary jika didownload dari URL
    
    try {
        \Log::info('Mengisi data Excel untuk Autoclave (Enclosure + Pressure Gauge)', [
            'calibration_id' => $calibration->id
        ]);
        
        // Load file Excel template autoclave
        $spreadsheet = IOFactory::load($filePath);
        
        // ==============================================================
        // 1. AMBIL NAMA USER DARI SESSION / AUTH LOGIN
        // ==============================================================
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }
        
        // ==============================================================
        // 2. AMBIL SHEET 'ACTION'
        // ==============================================================
        $sheet = $spreadsheet->getSheetByName('ACTION');
        if (!$sheet) {
            throw new Exception("Sheet 'ACTION' tidak ditemukan di template Autoclave");
        }
        
        // ==============================================================
        // 3. PARSE additional_forms & subform_identities
        // (handle kasus string JSON atau sudah array dari cast)
        // ==============================================================
        $rawAdditionalForms = $calibration->additional_forms ?? [];
        if (is_string($rawAdditionalForms)) {
            $additionalForms = json_decode($rawAdditionalForms, true) ?: [];
        } elseif (is_array($rawAdditionalForms)) {
            $additionalForms = $rawAdditionalForms;
        } else {
            $additionalForms = [];
        }
        
        $rawSubformIdentities = $calibration->subform_identities ?? [];
        if (is_string($rawSubformIdentities)) {
            $subformIdentities = json_decode($rawSubformIdentities, true) ?: [];
        } elseif (is_array($rawSubformIdentities)) {
            $subformIdentities = $rawSubformIdentities;
        } else {
            $subformIdentities = [];
        }
        
        \Log::info('🔍 Autoclave subform detection', [
            'additional_forms' => $additionalForms,
            'subform_keys' => array_keys($subformIdentities),
        ]);
        
        // ==============================================================
        // 4. AMBIL DATA MODEL RELATION (PISAH, DIISI SEMUA)
        // ==============================================================
        
        // --- Data Enclosure ---
        $headEnclosure    = HeadEnclosure::where('calibration_id', $calibration->id)->first();
        $addsEnclosure    = AddEnclosure::where('calibration_id', $calibration->id)
                                ->orderBy('repetition_number', 'asc')
                                ->orderBy('id', 'asc')
                                ->get();
        $detailsEnclosure = DetailEnclosure::where('calibration_id', $calibration->id)
                                ->orderBy('repetition_number', 'asc')
                                ->orderBy('interval_number', 'asc')
                                ->get();
        
        // --- Data Pressure Gauge ---
        $headPressureGauge    = \App\Models\HeadPressureGauge::where('calibration_id', $calibration->id)->first();
        $detailsPressureGauge = \App\Models\DetailPressureGauge::where('calibration_id', $calibration->id)
                                    ->orderBy('id', 'asc')
                                    ->get();
        $addPressureGauge     = \App\Models\AddPressureGauge::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📦 Autoclave data counts', [
            'headEnclosure' => $headEnclosure ? 'ADA' : 'KOSONG',
            'addsEnclosure' => $addsEnclosure->count(),
            'detailsEnclosure' => $detailsEnclosure->count(),
            'headPressureGauge' => $headPressureGauge ? 'ADA' : 'KOSONG',
            'detailsPressureGauge' => $detailsPressureGauge->count(),
            'addPressureGauge' => $addPressureGauge ? 'ADA' : 'KOSONG',
        ]);
        
        // ==============================================================
        // 5. DATA UTAMA DARI TABEL CALIBRATIONS (CELL B - SELALU)
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $headEnclosure->certificate_id 
                                        ?? $headPressureGauge->certificate_id 
                                        ?? $calibration->certificate_id 
                                        ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
        $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
        $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
        $sheet->setCellValue('B10', $calibration->resolusi ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B12', $calibration->tanggalMasuk 
                                        ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) 
                                        : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi 
                                        ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) 
                                        : '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH dari calibrations
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Jenis Alat Ukur
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // ==============================================================
        // 6. DATA SUBFORM DARI subform_identities (CELL C - SELALU)
        // ==============================================================
        // Apapun subform-nya (pressure_gauge atau enclosure), data subform
        // selalu ditaruh di kolom C
        $subformData = null;
        $subformKey  = '';
        
        if (isset($subformIdentities['pressure_gauge'])) {
            $subformData = $subformIdentities['pressure_gauge'];
            $subformKey  = 'pressure_gauge';
        } elseif (isset($subformIdentities['enclosure'])) {
            $subformData = $subformIdentities['enclosure'];
            $subformKey  = 'enclosure';
        }
        
        if ($subformData) {
            // Data identitas subform → kolom C
            $sheet->setCellValue('C2',  $subformData['nama_alat'] ?? '');
            $sheet->setCellValue('C3',  $subformData['merek'] ?? '');
            $sheet->setCellValue('C4',  $subformData['kode_alat'] ?? '');
            $sheet->setCellValue('C5',  $subformData['type_alat'] ?? '');
            $sheet->setCellValue('C6',  $subformData['no_seri'] ?? '');
            $sheet->setCellValue('C7',  $subformData['rentang_ukur_min'] ?? '0');
            $sheet->setCellValue('C8',  $subformData['rentang_ukur_max'] ?? '');
            $sheet->setCellValue('C9',  $subformData['kapasitas'] ?? '');
            $sheet->setCellValue('C10', $subformData['resolusi'] ?? '');
            $sheet->setCellValue('C11', $subformData['nama_pemilik'] ?? '');
            $sheet->setCellValue('C12', !empty($subformData['tanggal_alat_masuk']) 
                                            ? date('d-m-Y', strtotime($subformData['tanggal_alat_masuk'])) 
                                            : '');
            $sheet->setCellValue('C13', !empty($subformData['tanggal_kalibrasi']) 
                                            ? date('d-m-Y', strtotime($subformData['tanggal_kalibrasi'])) 
                                            : '');
            $sheet->setCellValue('C14', $subformData['jenis_pembacaan'] ?? '');
            $sheet->setCellValue('C15', $subformData['tempat_kalibrasi'] ?? '');
            $sheet->setCellValue('C16', $subformData['lokasi_pt'] ?? $subformData['lokasiPT'] ?? '');
            $sheet->setCellValue('C17', $subformData['kondisi_alat'] ?? '');
            $sheet->setCellValue('C18', $subformData['keterangan'] ?? '');
            $sheet->setCellValue('C19', $subformData['kode_th'] ?? '');
            
            // Suhu & RH dari subform → kolom C, D, E
            $sheet->setCellValue('E22', $subformData['suhu_awal'] ?? '');
            $sheet->setCellValue('F22', $subformData['suhu_tengah'] ?? '');
            $sheet->setCellValue('G22', $subformData['suhu_akhir'] ?? '');
            $sheet->setCellValue('E23', $subformData['rh_awal'] ?? '');
            $sheet->setCellValue('F23', $subformData['rh_tengah'] ?? '');
            $sheet->setCellValue('G23', $subformData['rh_akhir'] ?? '');
            
            \Log::info('✅ Data subform diisi ke kolom C', [
                'subform_key' => $subformKey
            ]);
        } else {
            \Log::warning('⚠️ Subform data tidak ditemukan di subform_identities', [
                'additional_forms' => $additionalForms,
                'available_keys' => array_keys($subformIdentities)
            ]);
        }
        
        // ==============================================================
        // 7. HEAD DATA & DETAIL - ENCLOSURE (SELALU DIISI)
        // ==============================================================
        if ($headEnclosure) {
            
            // --- Alat Standar, Method, Calibrated/Verified by ---
            $sheet->setCellValue('B108', $headEnclosure->standard ?? '');
            $sheet->setCellValue('B109', $headEnclosure->calibrationMethod ?? '');
            $sheet->setCellValue('B80',  $headEnclosure->standard ?? ''); // untuk makro VBA
            $sheet->setCellValue('B81',  $headEnclosure->calibrationMethod ?? '');
            $sheet->setCellValue('B110',  $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B111',  $calibration->verifiedBy ?? '');
            
            // ----------------------------------------------------------
            // AMBIL & TEMPELKAN GAMBAR KE SHEET ACTION CELL A26
            // ----------------------------------------------------------
            if (!empty($headEnclosure->keterangan_gambar)) {
                $relativeUrl = trim($headEnclosure->keterangan_gambar);
                
                $sheet->setCellValue('A26', $relativeUrl);
                
                $imagePath = null;
                
                if (file_exists(public_path($relativeUrl))) {
                    $imagePath = public_path($relativeUrl);
                } 
                elseif (file_exists(storage_path('app/public/' . $relativeUrl))) {
                    $imagePath = storage_path('app/public/' . $relativeUrl);
                } 
                elseif (file_exists(storage_path('app/' . $relativeUrl))) {
                    $imagePath = storage_path('app/' . $relativeUrl);
                } 
                elseif (filter_var($relativeUrl, FILTER_VALIDATE_URL) || preg_match('/^https?:\/\//i', $relativeUrl)) {
                    $imageContent = @file_get_contents($relativeUrl);
                    if ($imageContent !== false) {
                        $ext = pathinfo(parse_url($relativeUrl, PHP_URL_PATH), PATHINFO_EXTENSION) ?: 'png';
                        $tempImagePath = sys_get_temp_dir() . '/autoclave_img_' . uniqid() . '.' . $ext;
                        file_put_contents($tempImagePath, $imageContent);
                        $imagePath = $tempImagePath;
                    }
                }
                else {
                    $fullUrl = url($relativeUrl);
                    $imageContent = @file_get_contents($fullUrl);
                    if ($imageContent !== false) {
                        $ext = pathinfo($relativeUrl, PATHINFO_EXTENSION) ?: 'png';
                        $tempImagePath = sys_get_temp_dir() . '/autoclave_img_' . uniqid() . '.' . $ext;
                        file_put_contents($tempImagePath, $imageContent);
                        $imagePath = $tempImagePath;
                    }
                }
                
                if ($imagePath && file_exists($imagePath)) {
                    $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
                    $drawing->setName('Gambar Teknisi Autoclave');
                    $drawing->setDescription('Gambar Autoclave Cell A26');
                    $drawing->setPath($imagePath);
                    $drawing->setCoordinates('A26');
                    $drawing->setHeight(140);
                    $drawing->setWorksheet($sheet);
                    
                    \Log::info('SUKSES! Menyisipkan objek gambar ke cell ACTION!A26 (Autoclave)');
                } else {
                    \Log::warning('Gambar dari keterangan_gambar tidak dapat ditemukan di server (Autoclave)', [
                        'input_path' => $relativeUrl
                    ]);
                }
            }
            
            // ----------------------------------------------------------
            // DATA ADD ENCLOSURE (TSETTING PER REPETITION)
            // ----------------------------------------------------------
            $tsettingCells = [
                1 => 'B32',
                2 => 'B44',
                3 => 'B56',
                4 => 'B68'
            ];
            
            foreach ($addsEnclosure as $index => $add) {
                $rep = $add->repetition_number ?? $add->repetition ?? ($index + 1);
                $tSettingValue = $add->Tsetting ?? $add->tsetting ?? '';
                
                if (isset($tsettingCells[$rep])) {
                    $sheet->setCellValue($tsettingCells[$rep], $tSettingValue);
                }
            }
            
            // ----------------------------------------------------------
            // KELOMPOKKAN DETAIL ENCLOSURE
            // ----------------------------------------------------------
            $detailsByRepetition = [];
            foreach ($detailsEnclosure as $detail) {
                $rep = $detail->repetition_number ?? $detail->repetition ?? 1;
                $interval = $detail->interval_number ?? $detail->interval ?? 1;
                $detailsByRepetition[$rep][$interval] = $detail;
            }
            
            // ----------------------------------------------------------
            // DATA INTERVAL WAKTU PER REPETITION (KOLOM A)
            // ----------------------------------------------------------
            $intervalCells = [
                1 => ['start' => 35, 'end' => 42],
                2 => ['start' => 47, 'end' => 54],
                3 => ['start' => 59, 'end' => 66],
                4 => ['start' => 71, 'end' => 78]
            ];
            
            foreach ($intervalCells as $rep => $range) {
                if (isset($detailsByRepetition[$rep])) {
                    $row = $range['start'];
                    $endRow = $range['end'];
                    ksort($detailsByRepetition[$rep]);
                    
                    foreach ($detailsByRepetition[$rep] as $interval => $detail) {
                        if ($row <= $endRow) {
                            $sheet->setCellValue('A' . $row, $detail->interval_number ?? '');
                            $row++;
                        }
                    }
                }
            }
            
            // ----------------------------------------------------------
            // DETAIL DATA ENCLOSURE (READ ALAT & SENSOR 1-9)
            // ----------------------------------------------------------
            $dataRows = [
                1 => ['start' => 35, 'end' => 42],
                2 => ['start' => 47, 'end' => 54],
                3 => ['start' => 59, 'end' => 66],
                4 => ['start' => 71, 'end' => 78]
            ];
            
            foreach ($dataRows as $rep => $range) {
                if (isset($detailsByRepetition[$rep])) {
                    $row = $range['start'];
                    $endRow = $range['end'];
                    ksort($detailsByRepetition[$rep]);
                    
                    foreach ($detailsByRepetition[$rep] as $interval => $detail) {
                        if ($row <= $endRow) {
                            $sheet->setCellValue('B' . $row, $detail->readAlat ?? '');
                            $sheet->setCellValue('C' . $row, $detail->readSensor1 ?? '');
                            $sheet->setCellValue('D' . $row, $detail->readSensor2 ?? '');
                            $sheet->setCellValue('E' . $row, $detail->readSensor3 ?? '');
                            $sheet->setCellValue('F' . $row, $detail->readSensor4 ?? '');
                            $sheet->setCellValue('G' . $row, $detail->readSensor5 ?? '');
                            $sheet->setCellValue('H' . $row, $detail->readSensor6 ?? '');
                            $sheet->setCellValue('I' . $row, $detail->readSensor7 ?? '');
                            $sheet->setCellValue('J' . $row, $detail->readSensor8 ?? '');
                            $sheet->setCellValue('K' . $row, $detail->readSensor9 ?? '');
                            $row++;
                        }
                    }
                }
            }
            
            \Log::info("Filled {$detailsEnclosure->count()} DetailEnclosure rows into Excel (Autoclave)");
        }
        
        // ==============================================================
        // 8. HEAD DATA & DETAIL - PRESSURE GAUGE (SELALU DIISI)
        // ==============================================================
        if ($headPressureGauge) {
            
            // --- Alat Standar, Method, Calibrated/Verified by ---
            $sheet->setCellValue('C108', $headPressureGauge->standard ?? '');
            $sheet->setCellValue('C109', $headPressureGauge->calibrationMethod ?? '');
            $sheet->setCellValue('C82',  $calibration->calibratedBy ?? '');
            $sheet->setCellValue('C83',  $calibration->verifiedBy ?? '');
            
            // Satuan alat kiri & std kiri
            $sheet->setCellValue('A81', $headPressureGauge->satuan_alat_kiri ?? ' ');
            $sheet->setCellValue('B81', $headPressureGauge->satuan_std_kiri ?? ' ');
            
            // ----------------------------------------------------------
            // DETAIL PRESSURE GAUGE - MULAI ROW 83
            // ----------------------------------------------------------
            if ($detailsPressureGauge && $detailsPressureGauge->count() > 0) {
                $row = 83;
                foreach ($detailsPressureGauge as $detail) {
                    if ($row > 102) break; // Max 20 baris (83 s/d 102)
                    
                    $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                    $sheet->setCellValue('B' . $row, $detail->STDNaik ?? '');
                    $sheet->setCellValue('C' . $row, $detail->STDTurun ?? '');
                    $row++;
                }
                \Log::info("Filled {$detailsPressureGauge->count()} DetailPressureGauge rows into Excel (Autoclave)");
            }
            
            // ----------------------------------------------------------
            // ADD PRESSURE GAUGE (REPEATABILITY) - SETELAH DETAIL PG
            // ----------------------------------------------------------
            if ($addPressureGauge) {
                $sheet->setCellValue('B104', $addPressureGauge->repeatability ?? '');
                $sheet->setCellValue('C104', $addPressureGauge->repeatabilitySTD ?? '');
                
                $sheet->setCellValue('A105', $addPressureGauge->ulangan01 ?? '');
                $sheet->setCellValue('B105', $addPressureGauge->ulangan02 ?? '');
                $sheet->setCellValue('C105', $addPressureGauge->ulangan03 ?? '');
                $sheet->setCellValue('D105', $addPressureGauge->ulangan04 ?? '');
                $sheet->setCellValue('E105', $addPressureGauge->ulangan05 ?? '');
                
                \Log::info('Add Pressure Gauge repeatability data filled (Autoclave)', [
                    'ulangan01' => $addPressureGauge->ulangan01,
                    'ulangan02' => $addPressureGauge->ulangan02,
                    'ulangan03' => $addPressureGauge->ulangan03,
                    'ulangan04' => $addPressureGauge->ulangan04,
                    'ulangan05' => $addPressureGauge->ulangan05,
                ]);
            }
        }
        
        // ==============================================================
        // 9. ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // 10. SIMPAN FILE EXCEL
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        // Hapus file gambar temporary jika ada
        if ($tempImagePath && file_exists($tempImagePath)) {
            @unlink($tempImagePath);
        }
        
        \Log::info('SUKSES! Data Autoclave berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'enclosure_filled' => $headEnclosure ? 'yes' : 'no',
            'pressure_gauge_filled' => $headPressureGauge ? 'yes' : 'no',
        ]);
        
    } catch (\Exception $e) {
        if ($tempImagePath && file_exists($tempImagePath)) {
            @unlink($tempImagePath);
        }
        
        \Log::error('Error fillAutoclaveExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        
        throw $e;
    }
}

public function fillDurometerExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Durometer', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Durometer");
        }
        
        // Ambil data HeadDurometer
        $head = \App\Models\HeadDurometer::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailDurometer
        $details = \App\Models\DetailDurometer::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // Ambil data AddDurometer (repeatability)
        $addData = \App\Models\AddDurometer::where('calibration_id', $calibration->id)->first();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? 'Durometer');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA DUROMETER
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B43', $head->standard ?? '');
            $sheet->setCellValue('B44', $head->calibrationMethod ?? '');
            
            // Satuan/Unit (A27 di ACTION)
            $sheet->setCellValue('D25', $head->satuan?? '');
            
           
            
            \Log::info('Head data filled from HeadDurometer', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'durometer_type' => $head->durometer_type ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // REPEATABILITY DATA (dari AddDurometer)
        // Sheet ACTION: A40-E41
        // ==============================================================
        if ($addData) {
            // Baris 1: A40-E40 (rep01 - rep05)
            $sheet->setCellValue('A40', $addData->rep01 ?? '');
            $sheet->setCellValue('B40', $addData->rep02 ?? '');
            $sheet->setCellValue('C40', $addData->rep03 ?? '');
            $sheet->setCellValue('D40', $addData->rep04 ?? '');
            $sheet->setCellValue('E40', $addData->rep05 ?? '');
            
            // Baris 2: A41-E41 (rep06 - rep10)
            $sheet->setCellValue('A41', $addData->rep06 ?? '');
            $sheet->setCellValue('B41', $addData->rep07 ?? '');
            $sheet->setCellValue('C41', $addData->rep08 ?? '');
            $sheet->setCellValue('D41', $addData->rep09 ?? '');
            $sheet->setCellValue('E41', $addData->rep10 ?? '');
            
            \Log::info('Repeatability data filled from AddDurometer', [
                'rep01' => $addData->rep01 ?? 'not set',
                'rep06' => $addData->rep06 ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA DUROMETER (dari DetailDurometer)
        // Kolom: setPointSkala, x1, x2, x3
        // Sheet ACTION: A27-D37
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 27;
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 37) break; // Max 11 baris (A27-D37)
                
                // Set Point Skala -> A27-A37
                $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                
                // X1 -> B27-B37
                $sheet->setCellValue('B' . $row, $detail->x1 ?? '');
                
                // X2 -> C27-C37
                $sheet->setCellValue('C' . $row, $detail->x2 ?? '');
                
                // X3 -> D27-D37
                $sheet->setCellValue('D' . $row, $detail->x3 ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Durometer)");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Durometer berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillDurometer: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillCentrifugeExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Centrifuge', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Centrifuge");
        }
        
        // Ambil data HeadCentrifuge (hanya 1 form)
        $head = \App\Models\HeadCentrifuge::where('calibration_id', $calibration->id)->first();
        
        // DEBUG: Log data head
        \Log::info('🔍 HEAD CENTRIFUGE DATA', [
            'calibration_id' => $calibration->id,
            'head_exists' => $head ? 'YES' : 'NO',
            'head_data' => $head ? $head->toArray() : 'null'
        ]);
        
        // Ambil data DetailCentrifuge
        $details = \App\Models\DetailCentrifuge::where('calibration_id', $calibration->id)
            ->orderBy('form_index', 'asc')
            ->orderBy('id', 'asc')
            ->get();
        
        // DEBUG: Log data details
        \Log::info('🔍 DETAIL CENTRIFUGE DATA', [
            'calibration_id' => $calibration->id,
            'details_count' => $details->count(),
            'details_data' => $details->toArray()
        ]);
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B19', $calibration->keterangan ?? '');
        $sheet->setCellValue('B18', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // ==============================================================
        // HEAD DATA CENTRIFUGE
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // ==============================================================
            // ALAT STANDAR & METODE KALIBRASI
            // B40 = Alat Standar (prioritaskan alat_standar_id, lalu standard)
            // B41 = Metode Kalibrasi
            // ==============================================================
            
            // Prioritaskan alat_standar_id, jika kosong gunakan standard
            $alatStandarValue = !empty($head->alat_standar_id) 
                ? $head->alat_standar_id 
                : ($head->standard ?? '');
            
            $methodValue = $head->calibrationMethod ?? '';
            
            \Log::info('📝 WRITING TO EXCEL - Centrifuge', [
                'B40_alat_standar' => $alatStandarValue,
                'B41_calibrationMethod' => $methodValue,
                'alat_standar_id' => $head->alat_standar_id ?? 'NULL',
                'standard' => $head->standard ?? 'NULL'
            ]);
            
            // Tulis ke Excel
            $sheet->setCellValue('B40', $alatStandarValue);
            $sheet->setCellValue('B41', $methodValue);
            
            // ==============================================================
            // DATA HEADER ROW 27 - CENTRIFUGE
            // A27 = Satuan Unit / Nominal
            // B27-F27 = Standar 1-5
            // G27 = Resolusi Alat
            // ==============================================================
            $sheet->setCellValue('A27', $head->satuan_unit ?? '');
            $sheet->setCellValue('B27', $head->standar1 ?? '');
            $sheet->setCellValue('C27', $head->standar2 ?? '');
            $sheet->setCellValue('D27', $head->standar3 ?? '');
            $sheet->setCellValue('E27', $head->standar4 ?? '');
            $sheet->setCellValue('F27', $head->standar5 ?? '');
            $sheet->setCellValue('G27', $head->resolusi_alat ?? '');
            
            \Log::info('Head data filled from HeadCentrifuge', [
                'calibration_id' => $calibration->id,
                'B40_alat_standar' => $alatStandarValue,
                'B41_calibrationMethod' => $methodValue,
                'A27_satuan_unit' => $head->satuan_unit ?? 'not set',
            ]);
        } else {
            \Log::warning('⚠️ HeadCentrifuge data NOT FOUND for calibration_id: ' . $calibration->id);
        }
        
        // ==============================================================
        // DETAIL DATA CENTRIFUGE - MULAI DARI ROW 28
        // Mapping kolom DetailCentrifuge ke sheet ACTION:
        //   - nominalRPM -> A28-A38 (Titik Ukur / Nominal)
        //   - STD1       -> B28-B38 (Standar 1)
        //   - STD2       -> C28-C38 (Standar 2)
        //   - STD3       -> D28-D38 (Standar 3)
        //   - STD4       -> E28-E38 (Standar 4)
        //   - STD5       -> F28-F38 (Standar 5)
        //   - resolusi   -> G28-G38 (Resolusi Alat)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 27;  // ✅ MULAI DARI 28BUKAN 27
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 38) break; // Max 11 baris (A28-A38)
                
                \Log::info('📝 DETAIL ROW ' . $row, [
                    'nominalRPM' => $detail->nominalRPM ?? 'empty',
                    'STD1' => $detail->STD1 ?? 'empty',
                    'STD2' => $detail->STD2 ?? 'empty',
                    'STD3' => $detail->STD3 ?? 'empty',
                    'STD4' => $detail->STD4 ?? 'empty',
                    'STD5' => $detail->STD5 ?? 'empty',
                    'resolusi' => $detail->resolusi ?? 'empty'
                ]);
                
                // A28-A38 = nominalRPM
                $sheet->setCellValue('A' . $row, $detail->nominalRPM ?? '');
                
                // B28-B38 = STD1
                $sheet->setCellValue('B' . $row, $detail->STD1 ?? '');
                
                // C28-C38 = STD2
                $sheet->setCellValue('C' . $row, $detail->STD2 ?? '');
                
                // D28-D38 = STD3
                $sheet->setCellValue('D' . $row, $detail->STD3 ?? '');
                
                // E28-E38 = STD4
                $sheet->setCellValue('E' . $row, $detail->STD4 ?? '');
                
                // F28-F38 = STD5
                $sheet->setCellValue('F' . $row, $detail->STD5 ?? '');
                
                // G28-G38 = resolusi
                $sheet->setCellValue('G' . $row, $detail->resolusi ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Centrifuge)");
        } else {
            \Log::warning('⚠️ No DetailCentrifuge data found for calibration_id: ' . $calibration->id);
        }
        
        // ==============================================================
        // CALIBRATED & VERIFIED BY
        // B42 = Calibrated By
        // B43 = Verified By
        // ==============================================================
        $sheet->setCellValue('B42', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B43', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Centrifuge berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillCentrifugeExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillThermoindicatorExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Thermoindicator', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $calibration->jumlah_form ?? 1
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil jumlah form
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);
        
        // 🔥 Ambil data dengan query langsung ke model
        $allHeads = \App\Models\HeadThermoIndicator::where('calibration_id', $calibration->id)->get();
        $allDetails = \App\Models\DetailThermoIndicator::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        $allAdds = \App\Models\AddThermoIndicator::where('calibration_id', $calibration->id)->get();
        
        // Kelompokkan data per form index
        $headsByForm = [];
        foreach ($allHeads as $head) {
            if ($head && isset($head->form_index)) {
                $headsByForm[$head->form_index] = $head;
            }
        }
        
        $detailsByForm = [];
        foreach ($allDetails as $detail) {
            if ($detail && isset($detail->form_index)) {
                if (!isset($detailsByForm[$detail->form_index])) {
                    $detailsByForm[$detail->form_index] = collect();
                }
                $detailsByForm[$detail->form_index]->push($detail);
            }
        }
        
        // Kelompokkan data Add (Wire Type) per form index
        $addsByForm = [];
        foreach ($allAdds as $add) {
            if ($add && isset($add->form_index)) {
                $addsByForm[$add->form_index] = $add;
            }
        }
        
        \Log::info('📊 Data grouped by form for Thermoindicator', [
            'heads_found' => array_keys($headsByForm),
            'details_found' => array_keys($detailsByForm),
            'adds_found' => array_keys($addsByForm),
            'jumlah_form_dari_calibration' => $jumlahForm
        ]);
        
        // ==================================================================
        // LOOPING UNTUK SETIAP FORM INDEX (1 sampai jumlahForm)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Tentukan nama sheet
            $sheetName = ($formIndex == 1) ? 'ACTION' : "ACTION ({$formIndex})";
            
            // Coba ambil sheet, jika tidak ada maka buat
            $sheet = $spreadsheet->getSheetByName($sheetName);
            
            if (!$sheet) {
                // Jika sheet tidak ada, clone dari sheet ACTION
                $sourceSheet = $spreadsheet->getSheetByName('ACTION');
                if ($sourceSheet) {
                    $newSheet = clone $sourceSheet;
                    $newSheet->setTitle($sheetName);
                    $spreadsheet->addSheet($newSheet);
                    $sheet = $newSheet;
                    \Log::info("Created new sheet: {$sheetName}");
                } else {
                    throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Thermoindicator");
                }
            }
            
            // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            
            // Ambil head untuk form ini
            $head = $headsByForm[$formIndex] ?? null;
            // Ambil add (Wire Type) untuk form ini
            $add = $addsByForm[$formIndex] ?? null;
            // Ambil details untuk form ini
            $formDetails = $detailsByForm[$formIndex] ?? collect();
            
            \Log::info("📝 Processing form index {$formIndex}", [
                'sheet_name' => $sheetName,
                'has_head' => !is_null($head),
                'has_add' => !is_null($add),
                'details_count' => $formDetails->count()
            ]);
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (HANYA UNTUK FORM 1)
            // ==============================================================
            if ($formIndex == 1) {
                $sheet->setCellValue('B1',  $calibration->id ?? '');
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
                $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
                $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
                $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
                $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
                // $sheet->setCellValue('B18', $calibration->keterangan ?? '');
                $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
                
                $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
                $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
                
                $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
                $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
                $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
                $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
                $sheet->setCellValue('B19', $calibration->kode_th ?? '');
                
                // Suhu & RH
                $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
                $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
                $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
                $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
                $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
                $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
                
                // Calibrated & Verified by
                $sheet->setCellValue('B56', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B57', $calibration->verifiedBy ?? '');
            } else {
                // Untuk form 2,3,4,5 - hanya isi certificate ID dan data spesifik form
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B56', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B57', $calibration->verifiedBy ?? '');
                
                \Log::info("Form {$formIndex}: Filled certificate ID and basic info");
            }
            
            // ==============================================================
            // HEAD DATA KHUSUS THERMOINDICATOR PER FORM
            // ==============================================================
            if ($head) {
                // Range Min & Max (dari head)
                $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
                $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
                
                // Kapasitas & Resolusi
                $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
                $sheet->setCellValue('B10', $calibration->resolusi ?? '');
                
                // Alat Standar & Metode Kalibrasi
                // $sheet->setCellValue('B43', $head->standard ?? '');
                $sheet->setCellValue('B55', $head->calibrationMethod ?? '');
                
                // Satuan STD & Satuan UUT
                $sheet->setCellValue('A28', $head->satuan_std ?? '');
                $sheet->setCellValue('B28', $head->satuan_uut ?? '');
                
                // Keterangan Fungsi Komponen
                $sheet->setCellValue('B18', $head->keterangan_fungsi_komponen ?? '');
                
                // ==============================================================
                // DATA ALAT STANDAR (B25) - UNTUK THERMOINDICATOR
                // ==============================================================
                // B25 di sheet ACTION berisi jenis alat standar (TYPE J, TYPE K, RTD (PT100))
                // Data ini akan diproses di VBA untuk dicocokkan dengan Y18-Y20
                // Kita isi dari field standard atau wireType
                $standardValue = $head->standard ?? '';
                $sheet->setCellValue('B54', $standardValue);
                
                \Log::info("Form {$formIndex}: Head data filled from HeadThermoIndicator", [
                    'standard' => $head->standard,
                    'calibrationMethod' => $head->calibrationMethod,
                    'satuan_std' => $head->satuan_std,
                    'satuan_uut' => $head->satuan_uut,
                    'keterangan_fungsi_komponen' => $head->keterangan_fungsi_komponen,
                    'B25_standard' => $standardValue
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No head data found, using defaults");
                
                // Set default values jika head tidak ditemukan
                $sheet->setCellValue('B7',  '0');
                $sheet->setCellValue('B8',  '');
                $sheet->setCellValue('B9',  '');
                $sheet->setCellValue('B10', '');
                $sheet->setCellValue('B43', '');
                $sheet->setCellValue('B44', '');
                $sheet->setCellValue('B24', '');
                $sheet->setCellValue('B25', '');
                $sheet->setCellValue('B26', '');
            }
            
            // ==============================================================
            // DATA ADD (WIRE TYPE) UNTUK REPEATABILITY
            // Data ini dari model AddThermoIndicator
            // ==============================================================
            if ($add) {
                // Wire Type Data (baris 52)
                // A52 = Wire Type, B52-E52 = Repeatability 1-5
                $sheet->setCellValue('B25', $add->wireType ?? '');
                $sheet->setCellValue('A52', $add->rep01 ?? '');
                $sheet->setCellValue('B52', $add->rep02 ?? '');
                $sheet->setCellValue('C52', $add->rep03 ?? '');
                $sheet->setCellValue('D52', $add->rep04 ?? '');
                $sheet->setCellValue('E52', $add->rep05 ?? '');
                
                \Log::info("Form {$formIndex}: Add (Wire Type) data filled", [
                    'wireType' => $add->wireType,
                    'rep01' => $add->rep01,
                    'rep02' => $add->rep02,
                    'rep03' => $add->rep03,
                    'rep04' => $add->rep04,
                    'rep05' => $add->rep05,
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No add (Wire Type) data found");
                // Kosongkan data Wire Type
                $sheet->setCellValue('A52', '');
                $sheet->setCellValue('B52', '');
                $sheet->setCellValue('C52', '');
                $sheet->setCellValue('D52', '');
                $sheet->setCellValue('E52', '');
                $sheet->setCellValue('F52', '');
            }
            
            // ==============================================================
            // DETAIL DATA THERMOINDICATOR (baris mulai 30-49)
            // Mapping:
            //   - PenunjukanSTD -> A30-A49
            //   - UUTnaik       -> B30-B49
            //   - UUTturun      -> C30-C49
            // ==============================================================
            if ($formDetails && $formDetails->count() > 0) {
                $sortedDetails = $formDetails->sortBy('id');
                $row = 30;
                foreach ($sortedDetails as $index => $detail) {
                    if ($index >= 20) break; // Max 20 baris (30-49)
                    
                    // PenunjukanSTD -> A30-A49
                    $sheet->setCellValue('A' . $row, $detail->PenunjukanSTD ?? '');
                    
                    // UUTnaik -> B30-B49
                    $sheet->setCellValue('B' . $row, $detail->UUTnaik ?? '');
                    
                    // UUTturun -> C30-C49
                    $sheet->setCellValue('C' . $row, $detail->UUTturun ?? '');
                    
                    $row++;
                }
                \Log::info("Form {$formIndex}: Filled {$formDetails->count()} detail rows (Thermoindicator)");
            } else {
                \Log::warning("Form {$formIndex}: No detail data found");
            }
        }
        
        // ==================================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==================================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Thermoindicator berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms' => $jumlahForm,
            'sheets_processed' => $jumlahForm
        ]);
        
    } catch (\Exception $e) {
        \Log::error('Error fillThermoindicatorExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillUtmExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk UTM', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template UTM");
        }
        
        // Ambil data HeadUtm (hanya 1 form)
        $head = \App\Models\HeadUtm::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailUtm
        $details = \App\Models\DetailUtm::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B56', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B57', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA UTM
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B54', $head->standard ?? '');
            $sheet->setCellValue('B55', $head->calibrationMethod ?? '');
            
            // Satuan untuk TEKAN (Pressure)
            // A27: satuan_titik_ukur_tekan
            $sheet->setCellValue('A26', $head->satuan_titik_ukur_tekan ?? '');
            
            // B27: satuan_read_tekan_std
            $sheet->setCellValue('D25', $head->satuan_read_tekan_std ?? '');
            
            // C27: satuan_read_tekan_uut (kosongkan atau isi sesuai)
            $sheet->setCellValue('G25', $head->satuan_read_tekan_uut ?? '');
            
            // D27: satuan_titik_ukur_tarik
            $sheet->setCellValue('A40', $head->satuan_titik_ukur_tarik ?? '');
            
            // E27: satuan_read_tarik_std
            $sheet->setCellValue('D39', $head->satuan_read_tarik_std ?? '');
            
            // F27: satuan_read_tarik_uut (kosongkan atau isi sesuai)
            $sheet->setCellValue('G39', $head->satuan_read_tarik_uut ?? '');
            
            \Log::info('Head data filled from HeadUtm', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'satuan_titik_ukur_tekan' => $head->satuan_titik_ukur_tekan ?? 'not set',
                'satuan_read_tekan_std' => $head->satuan_read_tekan_std ?? 'not set',
                'satuan_titik_ukur_tarik' => $head->satuan_titik_ukur_tarik ?? 'not set',
                'satuan_read_tarik_std' => $head->satuan_read_tarik_std ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA UTM
        // Untuk bagian TEKAN (Pressure):
        //   - Titik Ukur: A28-A37
        //   - Pembacaan Standar 1: B28-B37 (readTekanSTD1)
        //   - Pembacaan Standar 2: C28-C37 (readTekanSTD2)
        //   - Pembacaan Standar 3: D28-D37 (readTekanSTD3)
        //   - Pembacaan UUT 1: E28-E37 (readTekanUUT1)
        //   - Pembacaan UUT 2: F28-F37 (readTekanUUT2)
        //   - Pembacaan UUT 3: G28-G37 (readTekanUUT3)
        // 
        // Untuk bagian TARIK (Tension):
        //   - Titik Ukur: A42-A51
        //   - Pembacaan Standar 1: B42-B51 (readTarikSTD1)
        //   - Pembacaan Standar 2: C42-C51 (readTarikSTD2)
        //   - Pembacaan Standar 3: D42-D51 (readTarikSTD3)
        //   - Pembacaan UUT 1: E42-E51 (readTarikUUT1)
        //   - Pembacaan UUT 2: F42-F51 (readTarikUUT2)
        //   - Pembacaan UUT 3: G42-G51 (readTarikUUT3)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $rowTekan = 28;
            $rowTarik = 42;
            $detailIndex = 0;
            $tekanCount = 0;
            $tarikCount = 0;
            
            foreach ($details as $detail) {
                // ===== DATA TEKAN =====
                // Cek apakah data tekan ada (cek readTekanSTD1 tidak null)
                if (!is_null($detail->readTekanSTD1) || !is_null($detail->titikUkur)) {
                    if ($rowTekan <= 37) {
                        // Titik Ukur TEKAN -> A28-A37
                        $sheet->setCellValue('A' . $rowTekan, $detail->titikUkur ?? '');
                        
                        // Pembacaan Standar TEKAN 1 -> B28-B37
                        $sheet->setCellValue('B' . $rowTekan, $detail->readTekanSTD1 ?? '');
                        
                        // Pembacaan Standar TEKAN 2 -> C28-C37
                        $sheet->setCellValue('C' . $rowTekan, $detail->readTekanSTD2 ?? '');
                        
                        // Pembacaan Standar TEKAN 3 -> D28-D37
                        $sheet->setCellValue('D' . $rowTekan, $detail->readTekanSTD3 ?? '');
                        
                        // Pembacaan UUT TEKAN 1 -> E28-E37
                        $sheet->setCellValue('E' . $rowTekan, $detail->readTekanUUT1 ?? '');
                        
                        // Pembacaan UUT TEKAN 2 -> F28-F37
                        $sheet->setCellValue('F' . $rowTekan, $detail->readTekanUUT2 ?? '');
                        
                        // Pembacaan UUT TEKAN 3 -> G28-G37
                        $sheet->setCellValue('G' . $rowTekan, $detail->readTekanUUT3 ?? '');
                        
                        $rowTekan++;
                        $tekanCount++;
                    } else {
                        \Log::warning('Row tekan melebihi batas (A37), data tambahan diabaikan');
                    }
                }
                
                // ===== DATA TARIK =====
                // Cek apakah data tarik ada (cek readTarikSTD1 tidak null)
                if (!is_null($detail->readTarikSTD1) || !is_null($detail->titikUkur)) {
                    if ($rowTarik <= 51) {
                        // Titik Ukur TARIK -> A42-A51
                        $sheet->setCellValue('A' . $rowTarik, $detail->titikUkur ?? '');
                        
                        // Pembacaan Standar TARIK 1 -> B42-B51
                        $sheet->setCellValue('B' . $rowTarik, $detail->readTarikSTD1 ?? '');
                        
                        // Pembacaan Standar TARIK 2 -> C42-C51
                        $sheet->setCellValue('C' . $rowTarik, $detail->readTarikSTD2 ?? '');
                        
                        // Pembacaan Standar TARIK 3 -> D42-D51
                        $sheet->setCellValue('D' . $rowTarik, $detail->readTarikSTD3 ?? '');
                        
                        // Pembacaan UUT TARIK 1 -> E42-E51
                        $sheet->setCellValue('E' . $rowTarik, $detail->readTarikUUT1 ?? '');
                        
                        // Pembacaan UUT TARIK 2 -> F42-F51
                        $sheet->setCellValue('F' . $rowTarik, $detail->readTarikUUT2 ?? '');
                        
                        // Pembacaan UUT TARIK 3 -> G42-G51
                        $sheet->setCellValue('G' . $rowTarik, $detail->readTarikUUT3 ?? '');
                        
                        $rowTarik++;
                        $tarikCount++;
                    } else {
                        \Log::warning('Row tarik melebihi batas (A51), data tambahan diabaikan');
                    }
                }
                
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (UTM)", [
                'tekan_rows' => $tekanCount,
                'tarik_rows' => $tarikCount,
                'row_tekan_terakhir' => $rowTekan - 1,
                'row_tarik_terakhir' => $rowTarik - 1
            ]);
        } else {
            \Log::info('Tidak ada detail data UTM untuk calibration_id: ' . $calibration->id);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data UTM berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillUtmExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillMultimeterExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Multimeter', [
            'calibration_id' => $calibration->id,
            'form_type' => $calibration->form_type
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Multimeter");
        }
        
        // Ambil data HeadInsulation
        $head = \App\Models\HeadInsulation::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailInsulation - semua data sesuai urutan
        $details = \App\Models\DetailInsulation::where('calibration_id', $calibration->id)
            ->orderBy('parameter_type', 'asc')
            ->orderBy('id', 'asc')
            ->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B141', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B142', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA MULTIMETER/CLAMPMETER
        // ==============================================================
        if ($head) {
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            $sheet->setCellValue('B139', $head->standard ?? '');
            $sheet->setCellValue('B140', $head->calibrationMethod ?? '');
            
            \Log::info('Head data filled from HeadInsulation', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA - LANGSUNG TULIS SESUAI URUTAN DI DATABASE
        // ==============================================================
        if ($details && $details->count() > 0) {
            // Inisialisasi row untuk setiap parameter
            $rowAcVoltage = 28;
            $rowDcVoltage = 28;
            $rowAcCurrent = 69;
            $rowDcCurrent = 69;
            $rowResistance = 110;
            
            $totalRows = 0;
            
            foreach ($details as $detail) {
                $paramType = $detail->parameter_type ?? '';
                $rentang = $detail->rentang ?? '';
                $titikUkur = $detail->titik_ukur ?? '';
                $freq = $detail->frequency ?? '';
                $resolusi = $detail->resolusi_alat ?? '';
                
                // ==========================================================
                // AC VOLTAGE - Row 28-63 (max 36 baris / 9 rentang x 4 baris)
                // ==========================================================
                if ($paramType === 'ac_voltage' && $rowAcVoltage <= 63) {
                    $sheet->setCellValue('A' . $rowAcVoltage, $rentang);
                    $sheet->setCellValue('B' . $rowAcVoltage, $titikUkur);
                    $sheet->setCellValue('C' . $rowAcVoltage, $freq);
                    $sheet->setCellValue('D' . $rowAcVoltage, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('E' . $rowAcVoltage, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('F' . $rowAcVoltage, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('G' . $rowAcVoltage, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('H' . $rowAcVoltage, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('I' . $rowAcVoltage, $resolusi);
                    $rowAcVoltage++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // DC VOLTAGE - Row 28-63 (max 36 baris / 9 rentang x 4 baris)
                // ==========================================================
                if ($paramType === 'dc_voltage' && $rowDcVoltage <= 63) {
                    $sheet->setCellValue('K' . $rowDcVoltage, $rentang);
                    $sheet->setCellValue('L' . $rowDcVoltage, $titikUkur);
                    $sheet->setCellValue('M' . $rowDcVoltage, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('N' . $rowDcVoltage, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('O' . $rowDcVoltage, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('P' . $rowDcVoltage, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('Q' . $rowDcVoltage, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('R' . $rowDcVoltage, $resolusi);
                    $rowDcVoltage++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // AC CURRENT - Row 69-95 (max 27 baris / 9 rentang x 3 baris)
                // ==========================================================
                if ($paramType === 'ac_current' && $rowAcCurrent <= 95) {
                    $sheet->setCellValue('A' . $rowAcCurrent, $rentang);
                    $sheet->setCellValue('B' . $rowAcCurrent, $titikUkur);
                    $sheet->setCellValue('C' . $rowAcCurrent, $freq);
                    $sheet->setCellValue('D' . $rowAcCurrent, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('E' . $rowAcCurrent, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('F' . $rowAcCurrent, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('G' . $rowAcCurrent, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('H' . $rowAcCurrent, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('I' . $rowAcCurrent, $resolusi);
                    $rowAcCurrent++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // DC CURRENT - Row 69-95 (max 27 baris / 9 rentang x 3 baris)
                // ==========================================================
                if ($paramType === 'dc_current' && $rowDcCurrent <= 95) {
                    $sheet->setCellValue('K' . $rowDcCurrent, $rentang);
                    $sheet->setCellValue('L' . $rowDcCurrent, $titikUkur);
                    $sheet->setCellValue('M' . $rowDcCurrent, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('N' . $rowDcCurrent, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('O' . $rowDcCurrent, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('P' . $rowDcCurrent, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('Q' . $rowDcCurrent, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('R' . $rowDcCurrent, $resolusi);
                    $rowDcCurrent++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // RESISTANCE - Row 110-136 (max 27 baris / 9 rentang x 3 baris)
                // ==========================================================
                if ($paramType === 'resistance' && $rowResistance <= 136) {
                    $sheet->setCellValue('A' . $rowResistance, $rentang);
                    $sheet->setCellValue('B' . $rowResistance, $titikUkur);
                    $sheet->setCellValue('C' . $rowResistance, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('D' . $rowResistance, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('E' . $rowResistance, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('F' . $rowResistance, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('G' . $rowResistance, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('H' . $rowResistance, $resolusi);
                    $rowResistance++;
                    $totalRows++;
                    continue;
                }
            }
            
            \Log::info("Total detail rows processed: {$totalRows}");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Multimeter/Clampmeter berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'form_type' => $calibration->form_type
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillMultimeterExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

