        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B141', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B142', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA CLAMPMETER
        // ==============================================================
        if ($head) {
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            $sheet->setCellValue('B139', $head->standard ?? '');
            $sheet->setCellValue('B140', $head->calibrationMethod ?? '');
            
            \Log::info('Head data filled from HeadInsulation', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA - LANGSUNG TULIS SESUAI URUTAN DI DATABASE
        // ==============================================================
        if ($details && $details->count() > 0) {
            // Inisialisasi row untuk setiap parameter
            $rowAcVoltage = 28;
            $rowDcVoltage = 28;
            $rowAcCurrent = 69;
            $rowDcCurrent = 69;
            $rowResistance = 110;
            
            $totalRows = 0;
            
            foreach ($details as $detail) {
                $paramType = $detail->parameter_type ?? '';
                $rentang = $detail->rentang ?? '';
                $titikUkur = $detail->titik_ukur ?? '';
                $freq = $detail->frequency ?? '';
                $resolusi = $detail->resolusi_alat ?? '';
                $coil = $detail->coil ?? '';
                
                // ==========================================================
                // AC VOLTAGE - Row 28-63 (4 data per rentang)
                // ==========================================================
                if ($paramType === 'ac_voltage' && $rowAcVoltage <= 63) {
                    $sheet->setCellValue('A' . $rowAcVoltage, $rentang);
                    $sheet->setCellValue('B' . $rowAcVoltage, $titikUkur);
                    $sheet->setCellValue('C' . $rowAcVoltage, $freq);
                    $sheet->setCellValue('D' . $rowAcVoltage, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('E' . $rowAcVoltage, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('F' . $rowAcVoltage, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('G' . $rowAcVoltage, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('H' . $rowAcVoltage, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('I' . $rowAcVoltage, $resolusi);
                    
                    $rowAcVoltage++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // DC VOLTAGE - Row 28-63 (4 data per rentang)
                // ==========================================================
                if ($paramType === 'dc_voltage' && $rowDcVoltage <= 63) {
                    $sheet->setCellValue('K' . $rowDcVoltage, $rentang);
                    $sheet->setCellValue('L' . $rowDcVoltage, $titikUkur);
                    $sheet->setCellValue('M' . $rowDcVoltage, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('N' . $rowDcVoltage, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('O' . $rowDcVoltage, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('P' . $rowDcVoltage, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('Q' . $rowDcVoltage, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('R' . $rowDcVoltage, $resolusi);
                    
                    $rowDcVoltage++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // AC CURRENT - Row 69-95 (3 data per rentang)
                // Clampmeter: Column A = Rentang, B = Standar, C = Coil (dari detail)
                // D-H = UUT, I = Resolusi
                // ==========================================================
                if ($paramType === 'ac_current' && $rowAcCurrent <= 95) {
                    // Coil dari data detail
                    $coilValue = $detail->coil ?? '';
                    
                    $sheet->setCellValue('A' . $rowAcCurrent, $rentang);
                    $sheet->setCellValue('B' . $rowAcCurrent, $titikUkur);
                    $sheet->setCellValue('C' . $rowAcCurrent, $coilValue);  // Coil dari detail
                    $sheet->setCellValue('D' . $rowAcCurrent, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('E' . $rowAcCurrent, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('F' . $rowAcCurrent, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('G' . $rowAcCurrent, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('H' . $rowAcCurrent, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('I' . $rowAcCurrent, $resolusi);
                    
                    $rowAcCurrent++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // DC CURRENT - Row 69-95 (3 data per rentang)
                // Clampmeter: Column K = Rentang, L = Standar, M = Coil (dari detail)
                // N-R = UUT, S = Resolusi
                // ==========================================================
                if ($paramType === 'dc_current' && $rowDcCurrent <= 95) {
                    // Coil dari data detail
                    $coilValue = $detail->coil ?? '';
                    
                    $sheet->setCellValue('K' . $rowDcCurrent, $rentang);
                    $sheet->setCellValue('L' . $rowDcCurrent, $titikUkur);
                    $sheet->setCellValue('M' . $rowDcCurrent, $coilValue);  // Coil dari detail
                    $sheet->setCellValue('N' . $rowDcCurrent, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('O' . $rowDcCurrent, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('P' . $rowDcCurrent, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('Q' . $rowDcCurrent, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('R' . $rowDcCurrent, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('S' . $rowDcCurrent, $resolusi);
                    
                    $rowDcCurrent++;
                    $totalRows++;
                    continue;
                }
                
                // ==========================================================
                // RESISTANCE - Row 110-136 (3 data per rentang)
                // ==========================================================
                if ($paramType === 'resistance' && $rowResistance <= 136) {
                    $sheet->setCellValue('A' . $rowResistance, $rentang);
                    $sheet->setCellValue('B' . $rowResistance, $titikUkur);
                    $sheet->setCellValue('C' . $rowResistance, $detail->readAlat_1 ?? '');
                    $sheet->setCellValue('D' . $rowResistance, $detail->readAlat_2 ?? '');
                    $sheet->setCellValue('E' . $rowResistance, $detail->readAlat_3 ?? '');
                    $sheet->setCellValue('F' . $rowResistance, $detail->readAlat_4 ?? '');
                    $sheet->setCellValue('G' . $rowResistance, $detail->readAlat_5 ?? '');
                    $sheet->setCellValue('H' . $rowResistance, $resolusi);
                    
                    $rowResistance++;
                    $totalRows++;
                    continue;
                }
            }
            
            \Log::info("Total detail rows processed: {$totalRows}");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Clampmeter berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'form_type' => $calibration->form_type
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillClampmeterExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillTachometerExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Tachometer', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Tachometer");
        }
        
        // Ambil data HeadTachometer (hanya 1 form)
        $head = \App\Models\HeadTachometer::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailTachometer
        $details = \App\Models\DetailTachometer::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B44', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B45', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA TACHOMETER
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B42', $head->standard ?? '');
            $sheet->setCellValue('B43', $head->calibrationMethod ?? '');
            $sheet->setCellValue('A28', $head->satuan_unit ?? '');
            
            \Log::info('Head data filled from HeadTachometer', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'satuan_unit' => $head->satuan_unit ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA TACHOMETER
        // Kolom dari model DetailTachometer:
        // - nilaiStandard (A29-A40)
        // - rep01 (B29-B40)
        // - rep02 (C29-C40)
        // - rep03 (D29-D40)
        // - rep04 (E29-E40)
        // - rep05 (F29-F40)
        // - resolusiAlat (G29-G40)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 29;
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 40) break; // Max 12 baris (A29-A40)
                
                // nilaiStandard -> A29-A40
                $sheet->setCellValue('A' . $row, $detail->nilaiStandard ?? '');
                
                // rep01 -> B29-B40
                $sheet->setCellValue('B' . $row, $detail->rep01 ?? '');
                
                // rep02 -> C29-C40
                $sheet->setCellValue('C' . $row, $detail->rep02 ?? '');
                
                // rep03 -> D29-D40
                $sheet->setCellValue('D' . $row, $detail->rep03 ?? '');
                
                // rep04 -> E29-E40
                $sheet->setCellValue('E' . $row, $detail->rep04 ?? '');
                
                // rep05 -> F29-F40
                $sheet->setCellValue('F' . $row, $detail->rep05 ?? '');
                
                // resolusiAlat -> G29-G40
                $sheet->setCellValue('G' . $row, $detail->resolusiAlat ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Tachometer)");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Tachometer berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillTachometerExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillAnakTimbanganExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Anak Timbangan (Multi Form)', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // ==============================================================
        // AMBIL NAMA USER DARI SESSION LOGIN
        // ==============================================================
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }
        
        // ==============================================================
        // DAPATKAN SEMUA form_index YANG ADA UNTUK CALIBRATION INI
        // ==============================================================
        $formIndexes = \App\Models\HeadAnakTimbangan::where('calibration_id', $calibration->id)
            ->orderBy('form_index', 'asc')
            ->pluck('form_index')
            ->unique()
            ->toArray();
        
        // Jika tidak ada data Head, fallback ke form_index 1
        if (empty($formIndexes)) {
            $formIndexes = [1];
            \Log::warning('Tidak ada HeadAnakTimbangan ditemukan, fallback ke form_index 1', [
                'calibration_id' => $calibration->id
            ]);
        }
        
        \Log::info('Form indexes yang akan diproses:', [
            'calibration_id' => $calibration->id,
            'form_indexes' => $formIndexes
        ]);
        
        // ==============================================================
        // LOOP UNTUK SETIAP FORM INDEX
        // ==============================================================
        foreach ($formIndexes as $formIndex) {
            
            // ==========================================================
            // TENTUKAN NAMA SHEET BERDASARKAN form_index
            // ==========================================================
            if ($formIndex == 1) {
                $sheetName = 'ACTION';
            } else {
                $sheetName = 'ACTION (' . $formIndex . ')';
            }
            
            $sheet = $spreadsheet->getSheetByName($sheetName);
            
            if (!$sheet) {
                \Log::warning("Sheet '{$sheetName}' tidak ditemukan, skip form_index {$formIndex}");
                continue;
            }
            
            \Log::info("Memproses form_index {$formIndex} pada sheet '{$sheetName}'");
            
            // ==========================================================
            // AMBIL DATA HEAD UNTUK FORM INI
            // ==========================================================
            $head = \App\Models\HeadAnakTimbangan::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->first();
            
            // ==========================================================
            // AMBIL DATA DETAIL UNTUK FORM INI
            // ==========================================================
            $details = \App\Models\DetailAnakTimbangan::where('calibration_id', $calibration->id)
                ->where('form_index', $formIndex)
                ->orderBy('id', 'asc')
                ->get();
            
            // ==========================================================
            // DATA UMUM DARI TABEL CALIBRATION
            // ==========================================================
            $sheet->setCellValue('B1',  $calibration->id ?? '');
            $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
            $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
            $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
            $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
            $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
            $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
            $sheet->setCellValue('B18', $calibration->keterangan ?? '');
            $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
            
            // Jenis Alat Ukur (cell E2)
            $sheet->setCellValue('E2', $calibration->form_type ?? '');
            
            // Tanggal
            $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
            $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
            
            $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
            $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
            $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
            $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
            $sheet->setCellValue('B19', $calibration->kode_th ?? '');
            
            // Suhu & RH
            $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
            $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
            $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
            $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
            $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
            $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
            
            // Calibrated & Verified by
            $sheet->setCellValue('B51', $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B52', $calibration->verifiedBy ?? '');
            
            // ==========================================================
            // HEAD DATA ANAK TIMBANGAN
            // ==========================================================
            if ($head) {
                // Range Min & Max
                $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
                $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
                
                // Kapasitas & Resolusi
                $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
                $sheet->setCellValue('B10', $calibration->resolusi ?? '');
                
                // Metode Kalibrasi
                $sheet->setCellValue('B50', $head->calibrationMethod ?? '');
                
                // Satuan Unit 01 dan 02
                $sheet->setCellValue('B27', $head->satuan_unit01 ?? '');
                $sheet->setCellValue('C27', $head->satuan_unit02 ?? '');
                
                // Alat Standar untuk Anak Timbangan (cell B49)
                $sheet->setCellValue('B49', $head->standard ?? '');
                
                \Log::info("Head data filled for form_index {$formIndex}", [
                    'range_min' => $calibration->rangeMin ?? 'not set',
                    'range_max' => $calibration->rangeMax ?? 'not set',
                    'kapasitas' => $calibration->kapasitas ?? 'not set',
                    'resolusi' => $calibration->resolusi ?? 'not set',
                    'standard' => $head->standard ?? 'not set',
                    'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                    'satuan_unit01' => $head->satuan_unit01 ?? 'not set',
                    'satuan_unit02' => $head->satuan_unit02 ?? 'not set',
                ]);
            }
            
            // ==========================================================
            // DETAIL DATA ANAK TIMBANGAN
            // 
            // Struktur Excel (Sheet ACTION / ACTION (n)):
            // - Setiap NOMINAL memakai 4 row berurutan
            // - Kolom A: nominalAlat (hanya di row pertama setiap grup)
            // - Kolom B: ULSTD, ULUUT, LLUUT, LLSTD (4 row berurutan)
            // - Kolom C: URSTD, URUUT, LRUUT, LRSTD (4 row berurutan)
            // - Kolom D: ATSTD (hanya di row pertama setiap grup)
            //
            // Contoh untuk Nominal ke-1:
            //   A28 = nominalAlat,  B28 = ULSTD,  C28 = URSTD,  D28 = ATSTD
            //                       B29 = ULUUT,  C29 = URUUT
            //                       B30 = LLUUT,  C30 = LRUUT
            //                       B31 = LLSTD,  C31 = LRSTD
            //
            // Untuk Nominal ke-2 (mulai row 32):
            //   A32 = nominalAlat,  B32 = ULSTD,  C32 = URSTD,  D32 = ATSTD
            //   ... dst sampai row 44
            // ==========================================================
            if ($details && $details->count() > 0) {
                $row = 28; // Mulai dari row 28
                $nominalCount = 0;
                $maxRow = 44; // Batas maksimal row
                
                foreach ($details as $detail) {
                    // Cek apakah masih dalam batas row
                    if ($row > $maxRow) {
                        \Log::warning("Detail Anak Timbangan form_index {$formIndex} melebihi batas row {$maxRow}, sisa data tidak diisi");
                        break;
                    }
                    
                    // ==================================================
                    // ROW PERTAMA DARI GRUP (Kolom A, B, C, D)
                    // ==================================================
                    
                    // Kolom A: Nominal Alat (hanya di row pertama)
                    $sheet->setCellValue('A' . $row, $detail->nominalAlat ?? '');
                    
                    // Kolom B: ULSTD (row pertama)
                    $sheet->setCellValue('B' . $row, $detail->ULSTD ?? '');
                    
                    // Kolom C: URSTD (row pertama)
                    $sheet->setCellValue('C' . $row, $detail->URSTD ?? '');
                    
                    // Kolom D: ATSTD (hanya di row pertama)
                    $sheet->setCellValue('D' . $row, $detail->ATSTD ?? '');
                    
                    // ==================================================
                    // ROW KEDUA (Kolom B, C)
                    // ==================================================
                    
                    // Kolom B: ULUUT (row kedua)
                    $sheet->setCellValue('B' . ($row + 1), $detail->ULUUT ?? '');
                    
                    // Kolom C: URUUT (row kedua)
                    $sheet->setCellValue('C' . ($row + 1), $detail->URUUT ?? '');
                    
                    // ==================================================
                    // ROW KETIGA (Kolom B, C)
                    // ==================================================
                    
                    // Kolom B: LLUUT (row ketiga)
                    $sheet->setCellValue('B' . ($row + 2), $detail->LLUUT ?? '');
                    
                    // Kolom C: LRUUT (row ketiga)
                    $sheet->setCellValue('C' . ($row + 2), $detail->LRUUT ?? '');
                    
                    // ==================================================
                    // ROW KEEMPAT (Kolom B, C)
                    // ==================================================
                    
                    // Kolom B: LLSTD (row keempat)
                    $sheet->setCellValue('B' . ($row + 3), $detail->LLSTD ?? '');
                    
                    // Kolom C: LRSTD (row keempat)
                    $sheet->setCellValue('C' . ($row + 3), $detail->LRSTD ?? '');
                    
                    // Pindah ke grup nominal berikutnya (geser 4 row)
                    $row += 4;
                    $nominalCount++;
                }
                
                \Log::info("Filled {$nominalCount} nominal groups for form_index {$formIndex}", [
                    'total_rows_used' => ($nominalCount * 4),
                    'start_row' => 28,
                    'last_row' => $row - 1,
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex,
                    'sheet_name' => $sheetName
                ]);
            } else {
                \Log::warning("Tidak ada detail Anak Timbangan untuk form_index {$formIndex}", [
                    'calibration_id' => $calibration->id,
                    'form_index' => $formIndex
                ]);
            }
            
            // ==========================================================
            // ISI CELL K1 DENGAN NAMA USER (setiap sheet ACTION)
            // ==========================================================
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
            
        } // END foreach formIndexes
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Anak Timbangan berhasil diisi ke Excel (Multi Form)', [
            'calibration_id' => $calibration->id,
            'total_forms_processed' => count($formIndexes),
            'form_indexes' => $formIndexes
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillAnakTimbanganExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillPinGaugeExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Pin Gauge', [
            'calibration_id' => $calibration->id,
            'jumlah_form' => $calibration->jumlah_form ?? 1
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil jumlah form
        $jumlahForm = $calibration->jumlah_form ?? 1;
        $jumlahForm = max(1, $jumlahForm);

        // 🔥 Ambil data dengan query langsung ke model
        $allHeads = \App\Models\HeadPinGauge::where('calibration_id', $calibration->id)->get();
        $allDetails = \App\Models\DetailPinGauge::where('calibration_id', $calibration->id)->orderBy('id', 'asc')->get();

        // Kelompokkan data per form index
        $headsByForm = [];
        foreach ($allHeads as $head) {
            if ($head && isset($head->form_index)) {
                $headsByForm[$head->form_index] = $head;
            }
        }

        $detailsByForm = [];
        foreach ($allDetails as $detail) {
            if ($detail && isset($detail->form_index)) {
                if (!isset($detailsByForm[$detail->form_index])) {
                    $detailsByForm[$detail->form_index] = collect();
                }
                $detailsByForm[$detail->form_index]->push($detail);
            }
        }

        \Log::info('📊 Data grouped by form for Pin Gauge', [
            'heads_found' => array_keys($headsByForm),
            'details_found' => array_keys($detailsByForm),
            'jumlah_form_dari_calibration' => $jumlahForm
        ]);

        // ==================================================================
        // LOOPING UNTUK SETIAP FORM INDEX (1 sampai jumlahForm)
        // ==================================================================
        for ($formIndex = 1; $formIndex <= $jumlahForm; $formIndex++) {
            // Tentukan nama sheet
            $sheetName = ($formIndex == 1) ? 'ACTION' : "ACTION ({$formIndex})";

            // Coba ambil sheet, jika tidak ada maka buat
            $sheet = $spreadsheet->getSheetByName($sheetName);

            if (!$sheet) {
                // Jika sheet tidak ada, clone dari sheet ACTION
                $sourceSheet = $spreadsheet->getSheetByName('ACTION');
                if ($sourceSheet) {
                    $newSheet = clone $sourceSheet;
                    $newSheet->setTitle($sheetName);
                    $spreadsheet->addSheet($newSheet);
                    $sheet = $newSheet;
                    \Log::info("Created new sheet: {$sheetName}");
                } else {
                    throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Pin Gauge");
                }
            }

            // Isi cell K1 dengan nama user yang login (untuk semua form/sheet)
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }

            // Ambil head & detail untuk form ini
            $head = $headsByForm[$formIndex] ?? null;
            $formDetails = $detailsByForm[$formIndex] ?? collect();

            \Log::info("📝 Processing form index {$formIndex}", [
                'sheet_name' => $sheetName,
                'has_head' => !is_null($head),
                'details_count' => $formDetails->count()
            ]);

            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (HANYA UNTUK FORM 1)
            // ==============================================================
            if ($formIndex == 1) {
                $sheet->setCellValue('B1',  $calibration->id ?? '');
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
                $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
                $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
                $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
                $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
                $sheet->setCellValue('B18', $calibration->keterangan ?? '');
                $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');

                // Jenis Alat Ukur (cell E2)
                $sheet->setCellValue('E2', $calibration->form_type ?? '');

                // Tanggal
                $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
                $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');

                $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
                $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
                $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
                $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
                $sheet->setCellValue('B19', $calibration->kode_th ?? '');

                // Suhu & RH
                $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
                $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
                $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
                $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
                $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
                $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');

                // Calibrated & Verified by
                $sheet->setCellValue('B75', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B76', $calibration->verifiedBy ?? '');
            } else {
                // Untuk form 2,3,4,5 - hanya isi certificate ID dan data spesifik form
                $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
                $sheet->setCellValue('B75', $calibration->calibratedBy ?? '');
                $sheet->setCellValue('B76', $calibration->verifiedBy ?? '');

                \Log::info("Form {$formIndex}: Filled certificate ID and basic info");
            }

            // ==============================================================
            // HEAD DATA PIN GAUGE PER FORM
            // ==============================================================
            if ($head) {
                // Range Min & Max — langsung dari database, tanpa default '0'
                $sheet->setCellValue('B7',  $calibration->rangeMin ?? '');
                $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');

                // Kapasitas & Resolusi
                $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
                $sheet->setCellValue('B10', $calibration->resolusi ?? '');

                // Alat Standar & Metode Kalibrasi
                $sheet->setCellValue('B73', $head->standard ?? '');
                $sheet->setCellValue('B74', $head->calibrationMethod ?? '');

                \Log::info("Form {$formIndex}: Head data filled from HeadPinGauge", [
                    'head_id' => $head->id,
                    'standard' => $head->standard,
                    'calibrationMethod' => $head->calibrationMethod,
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No head data found");

                // Kosongkan saja — tanpa default value
                $sheet->setCellValue('B7',  '');
                $sheet->setCellValue('B8',  '');
                $sheet->setCellValue('B9',  '');
                $sheet->setCellValue('B10', '');
                $sheet->setCellValue('B73', '');
                $sheet->setCellValue('B74', '');
            }

            // ==============================================================
            // DETAIL DATA PIN GAUGE PER FORM
            // Struktur:
            //   - Baris ganjil (28, 30, 32, ...): Nominal + Ulangan 1,2,3
            //   - Baris genap (29, 31, 33, ...): Ulangan 4,5,6
            // ==============================================================
            if ($formDetails && $formDetails->count() > 0) {
                $sortedDetails = $formDetails->sortBy('id');
                $startRow = 28;
                $maxRow = 71;
                $detailIndex = 0;

                foreach ($sortedDetails as $detail) {
                    $rowNominal = $startRow + ($detailIndex * 2);
                    $rowUlangan = $rowNominal + 1;

                    // Safety check: jangan melebihi batas row
                    if ($rowNominal > $maxRow) break;

                    // BARIS GANJIL: Nominal + Ulangan 1,2,3
                    $sheet->setCellValue('B' . $rowNominal, $detail->titikUkur ?? '');
                    $sheet->setCellValue('C' . $rowNominal, $detail->ulangan1 ?? '');
                    $sheet->setCellValue('D' . $rowNominal, $detail->ulangan2 ?? '');
                    $sheet->setCellValue('E' . $rowNominal, $detail->ulangan3 ?? '');

                    // BARIS GENAP: Ulangan 4,5,6
                    if ($rowUlangan <= $maxRow) {
                        $sheet->setCellValue('C' . $rowUlangan, $detail->ulangan4 ?? '');
                        $sheet->setCellValue('D' . $rowUlangan, $detail->ulangan5 ?? '');
                        $sheet->setCellValue('E' . $rowUlangan, $detail->ulangan6 ?? '');
                    }

                    $detailIndex++;
                }

                \Log::info("Form {$formIndex}: Filled {$detailIndex} detail rows (Pin Gauge)", [
                    'start_row' => $startRow,
                    'end_row' => $startRow + ($detailIndex * 2) - 1,
                    'total_details' => $formDetails->count()
                ]);
            } else {
                \Log::warning("Form {$formIndex}: No detail data found");
            }
        }

        // ==================================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==================================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();

        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();

        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);

        \Log::info('SUKSES! Data Pin Gauge berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms' => $jumlahForm,
            'sheets_processed' => $jumlahForm
        ]);

    } catch (\Exception $e) {
        \Log::error('Error fillPinGaugeExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillStopwatchExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Stopwatch', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Stopwatch");
        }
        
        // Ambil data Head Stopwatch
        $head = \App\Models\HeadStopwatch::where('calibration_id', $calibration->id)->first();
        
        // Ambil data Detail Stopwatch (STD & UUT)
        $details = \App\Models\DetailStopwatch::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B51', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B52', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA STOPWATCH
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B49', $head->standard ?? '');
            $sheet->setCellValue('B50', $head->calibrationMethod ?? '');
            
            // Satuan Titik Ukur
            $sheet->setCellValue('A24', $head->satuan_titik_ukur ?? '');
            
          
            
            \Log::info('Head data filled from HeadStopwatch', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'satuan_titik_ukur' => $head->satuan_titik_ukur ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA STOPWATCH (STD & UUT)
        // Struktur di sheet ACTION:
        //   - Titik Ukur: A28 sampai A46 (19 baris)
        //   - STD: row 28, kolom C-Q (5 perulangan x 3 kolom = m, s, ms)
        //   - UUT: row 29, kolom C-Q (5 perulangan x 3 kolom = m, s, ms)
        //
        // Struktur data di database (DetailStopwatch):
        //   Setiap record = 1 titik ukur dengan:
        //   - titikUkur
        //   - STDm1, STDs1, STDms1, STDm2, STDs2, STDms2, ... STDm5, STDs5, STDms5
        //   - UUTm1, UUTs1, UUTms1, UUTm2, UUTs2, UUTms2, ... UUTm5, UUTs5, UUTms5
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 28;
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 46) break; // Max 19 baris (A28-A46)
                
                // ==========================================================
                // TITIK UKUR -> A28-A46
                // ==========================================================
                $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                
                // ==========================================================
                // DATA STD (row 28) -> kolom C, D, E / F, G, H / dst
                // ==========================================================
                // Perulangan 1: C, D, E
                $sheet->setCellValue('C' . $row, $detail->STDm1 ?? '');
                $sheet->setCellValue('D' . $row, $detail->STDs1 ?? '');
                $sheet->setCellValue('E' . $row, $detail->STDms1 ?? '');
                
                // Perulangan 2: F, G, H
                $sheet->setCellValue('F' . $row, $detail->STDm2 ?? '');
                $sheet->setCellValue('G' . $row, $detail->STDs2 ?? '');
                $sheet->setCellValue('H' . $row, $detail->STDms2 ?? '');
                
                // Perulangan 3: I, J, K
                $sheet->setCellValue('I' . $row, $detail->STDm3 ?? '');
                $sheet->setCellValue('J' . $row, $detail->STDs3 ?? '');
                $sheet->setCellValue('K' . $row, $detail->STDms3 ?? '');
                
                // Perulangan 4: L, M, N
                $sheet->setCellValue('L' . $row, $detail->STDm4 ?? '');
                $sheet->setCellValue('M' . $row, $detail->STDs4 ?? '');
                $sheet->setCellValue('N' . $row, $detail->STDms4 ?? '');
                
                // Perulangan 5: O, P, Q
                $sheet->setCellValue('O' . $row, $detail->STDm5 ?? '');
                $sheet->setCellValue('P' . $row, $detail->STDs5 ?? '');
                $sheet->setCellValue('Q' . $row, $detail->STDms5 ?? '');
                
                // ==========================================================
                // DATA UUT (row 29) -> kolom C, D, E / F, G, H / dst
                // ==========================================================
                $uutRow = $row + 1;
                
                // Perulangan 1: C, D, E
                $sheet->setCellValue('C' . $uutRow, $detail->UUTm1 ?? '');
                $sheet->setCellValue('D' . $uutRow, $detail->UUTs1 ?? '');
                $sheet->setCellValue('E' . $uutRow, $detail->UUTms1 ?? '');
                
                // Perulangan 2: F, G, H
                $sheet->setCellValue('F' . $uutRow, $detail->UUTm2 ?? '');
                $sheet->setCellValue('G' . $uutRow, $detail->UUTs2 ?? '');
                $sheet->setCellValue('H' . $uutRow, $detail->UUTms2 ?? '');
                
                // Perulangan 3: I, J, K
                $sheet->setCellValue('I' . $uutRow, $detail->UUTm3 ?? '');
                $sheet->setCellValue('J' . $uutRow, $detail->UUTs3 ?? '');
                $sheet->setCellValue('K' . $uutRow, $detail->UUTms3 ?? '');
                
                // Perulangan 4: L, M, N
                $sheet->setCellValue('L' . $uutRow, $detail->UUTm4 ?? '');
                $sheet->setCellValue('M' . $uutRow, $detail->UUTs4 ?? '');
                $sheet->setCellValue('N' . $uutRow, $detail->UUTms4 ?? '');
                
                // Perulangan 5: O, P, Q
                $sheet->setCellValue('O' . $uutRow, $detail->UUTm5 ?? '');
                $sheet->setCellValue('P' . $uutRow, $detail->UUTs5 ?? '');
                $sheet->setCellValue('Q' . $uutRow, $detail->UUTms5 ?? '');
                
                $row += 2; // Lewati 2 baris (STD dan UUT)
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Stopwatch)", [
                'total_details' => $details->count()
            ]);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Stopwatch berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillStopwatchExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillThreadGaugeExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Thread Gauge', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Thread Gauge");
        }
        
        // Ambil data Head Thread Gauge
        $head = \App\Models\HeadThreadGauge::where('calibration_id', $calibration->id)->first();
        
        // Ambil data Detail Thread Gauge
        $details = \App\Models\DetailThreadGauge::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('C5',  $head->jenis_thread ?? '');  // Jenis Thread
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
        $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
        // Kapasitas & Resolusi
        $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
         $sheet->setCellValue('B10',  $calibration->resolusi ?? '');
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        $sheet->setCellValue('B45', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B46', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA THREAD GAUGE
        // ==============================================================
        if ($head) {
            // Standard & Calibration Method
            $sheet->setCellValue('B43', $head->standard ?? '');
            $sheet->setCellValue('B44', $head->calibrationMethod ?? '');
            
            // Catatan -> B41 (override dengan catatan head jika ada)
            $sheet->setCellValue('B41', $head->catatan ?? '');
            
            \Log::info('Head data filled from HeadThreadGauge', [
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'catatan' => $head->catatan ?? 'not set',
                'jenis_thread' => $head->jenis_thread ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA THREAD GAUGE
        // Ambil dari detail pertama (karena data Thread Gauge bersifat single)
        //
        // Mapping:
        // - sensor -> B25
        // - kodeGO -> C27
        // - satuan_go -> A29
        // - GOatasX1 -> C30
        // - GOatasY1 -> D30
        // - GObawahX1 -> C31
        // - GObawahY1 -> D31
        // - kodeNOTGO -> C33
        // - satuan_not_go -> A35
        // - NOTGOatasX1 -> C36
        // - NOTGOatasY1 -> D36
        // - NOTGObawahX1 -> C37
        // - NOTGObawahY1 -> D37
        // - ukuranPitch -> B39
        // - sudutUlir -> B40
        // ==============================================================
        if ($details && $details->count() > 0) {
            $detail = $details->first();
            
            // ==========================================================
            // SENSOR & KODE GO SIDE
            // ==========================================================
            $sheet->setCellValue('B25', $detail->sensor ?? '');
            $sheet->setCellValue('C27', $detail->kodeGO ?? '');
            $sheet->setCellValue('A29', $detail->satuan_go ?? '');
            
            // ==========================================================
            // DATA GO (atas & bawah)
            // ==========================================================
            $sheet->setCellValue('C30', $detail->GOatasX1 ?? '');
            $sheet->setCellValue('D30', $detail->GOatasY1 ?? '');
            $sheet->setCellValue('C31', $detail->GObawahX1 ?? '');
            $sheet->setCellValue('D31', $detail->GObawahY1 ?? '');
            
            // ==========================================================
            // KODE NOT GO SIDE
            // ==========================================================
            $sheet->setCellValue('C33', $detail->kodeNOTGO ?? '');
            $sheet->setCellValue('A35', $detail->satuan_not_go ?? '');
            
            // ==========================================================
            // DATA NOT GO (atas & bawah)
            // ==========================================================
            $sheet->setCellValue('C36', $detail->NOTGOatasX1 ?? '');
            $sheet->setCellValue('D36', $detail->NOTGOatasY1 ?? '');
            $sheet->setCellValue('C37', $detail->NOTGObawahX1 ?? '');
            $sheet->setCellValue('D37', $detail->NOTGObawahY1 ?? '');
            
            // ==========================================================
            // UKURAN PITCH & SUDUT ULIR
            // ==========================================================
            $sheet->setCellValue('B39', $detail->ukuranPitch ?? '');
            $sheet->setCellValue('B40', $detail->sudutUlir ?? '');
            $sheet->setCellValue('C39', $detail->satuan_pitch ?? '');
            
            \Log::info('Detail data filled from DetailThreadGauge', [
                'sensor' => $detail->sensor ?? 'not set',
                'kodeGO' => $detail->kodeGO ?? 'not set',
                'kodeNOTGO' => $detail->kodeNOTGO ?? 'not set',
                'ukuranPitch' => $detail->ukuranPitch ?? 'not set',
                'sudutUlir' => $detail->sudutUlir ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Thread Gauge berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillThreadGaugeExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

