public function fillChamberExcel($filePath, $calibration)
{
    $tempImagePath = null; // Menyimpan path file temporary jika didownload dari URL
    try {
        \Log::info('Mengisi data Excel untuk Chamber Calibration', [
            'calibration_id' => $calibration->id
        ]);
        // Load file Excel template
        $spreadsheet = IOFactory::load($filePath);
        
        // 1. AMBIL NAMA USER DARI SESSION / AUTH LOGIN
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }
        
        // 2. AMBIL DATA DARI MODEL RELATION (Diurutkan berdasarkan form_index & repetition_number)
        $head    = HeadChamber::where('calibration_id', $calibration->id)->first();
        $adds    = AddChamber::where('calibration_id', $calibration->id)
                    ->orderBy('form_index', 'asc')
                    ->orderBy('repetition_number', 'asc')
                    ->orderBy('id', 'asc')
                    ->get();
        $details = DetailChamber::where('calibration_id', $calibration->id)
                    ->orderBy('form_index', 'asc')
                    ->orderBy('repetition_number', 'asc')
                    ->orderBy('interval_number', 'asc')
                    ->get();
        
        // ==============================================================
        // 3. KELOMPOKKAN DATA BERDASARKAN form_index
        // ==============================================================
        $addsByForm = [];
        foreach ($adds as $add) {
            $formIdx = $add->form_index ?? 1;
            $rep     = $add->repetition_number ?? 1;
            $addsByForm[$formIdx][$rep] = $add;
        }
        
        $detailsByForm = [];
        foreach ($details as $detail) {
            $formIdx  = $detail->form_index ?? 1;
            $rep      = $detail->repetition_number ?? 1;
            $interval = $detail->interval_number ?? 1;
            $detailsByForm[$formIdx][$rep][$interval] = $detail;
        }
        
        // ==============================================================
        // 4. TENTUKAN JUMLAH FORM (= JUMLAH SHEET ACTION)
        // ==============================================================
        $allFormIndexes = array_unique(array_merge(
            array_keys($addsByForm),
            array_keys($detailsByForm)
        ));
        $maxFormIndex = !empty($allFormIndexes) ? max($allFormIndexes) : 1;
        
        // ==============================================================
        // 5. LOOP UNTUK SETIAP FORM (= SETIAP SHEET ACTION)
        // ==============================================================
        for ($formIndex = 1; $formIndex <= $maxFormIndex; $formIndex++) {
            
            // ----------------------------------------------------------
            // TENTUKAN NAMA SHEET ACTION
            // ----------------------------------------------------------
            if ($formIndex === 1) {
                $actionSheetName = 'ACTION';
            } else {
                $actionSheetName = 'ACTION (' . $formIndex . ')';
            }
            
            // ----------------------------------------------------------
            // AMBIL SHEET ACTION (formIndex 1) ATAU BUAT BARU (formIndex > 1)
            // ----------------------------------------------------------
            if ($formIndex === 1) {
                $sheet = $spreadsheet->getSheetByName('ACTION');
                if (!$sheet) {
                    throw new Exception("Sheet 'ACTION' tidak ditemukan di template Chamber");
                }
            } else {
                // Cek apakah sheet sudah ada
                $existingSheet = $spreadsheet->getSheetByName($actionSheetName);
                if ($existingSheet) {
                    $sheet = $existingSheet;
                } else {
                    // Clone sheet ACTION sebagai base
                    $baseSheet = $spreadsheet->getSheetByName('ACTION');
                    $newSheet = clone $baseSheet;
                    $newSheet->setTitle($actionSheetName);
                    $spreadsheet->addSheet($newSheet);
                    
                    $sheet = $spreadsheet->getSheetByName($actionSheetName);
                }
            }
            
            // ==============================================================
            // DATA UMUM DARI TABEL CALIBRATION (SHEET ACTION)
            // ==============================================================
            $sheet->setCellValue('B1',  $calibration->id ?? '');
            $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
            $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
            $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
            $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
            $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
            $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
            $sheet->setCellValue('B18', $calibration->keterangan ?? '');
            $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
            
            // Jenis Alat Ukur (cell E2)
            $sheet->setCellValue('E2', $calibration->form_type ?? '');
            
            // Tanggal Masuk & Tanggal Kalibrasi
            $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
            $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
            
            $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
            $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
            $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
            $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
            $sheet->setCellValue('B19', $calibration->kode_th ?? '');
            
            // Suhu (RT) & Kelembaban (RH)
            $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
            $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
            $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
            $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
            $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
            $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
            
            // Range
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi dari HeadChamber
            $sheet->setCellValue('B9',  $head->kapasitas_c ?? '');   // kapasitas C
            $sheet->setCellValue('B10', $head->resolusi_c ?? '');    // resolusi C
            $sheet->setCellValue('C9',  $head->kapasitas_rh ?? '');  // kapasitas %
            $sheet->setCellValue('C10', $head->resolusi_rh ?? '');   // resolusi %
            
            // Calibrated & Verified by
            $sheet->setCellValue('B70', $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B71', $calibration->verifiedBy ?? '');
            
            // ==============================================================
            // HEAD DATA CHAMBER (STANDARD, METHOD, & GAMBAR CELL A26)
            // ==============================================================
            if ($head) {
                $sheet->setCellValue('B68', $head->standard ?? ''); // Digunakan untuk pembacaan makro VBA
                $sheet->setCellValue('B69', $head->calibrationMethod ?? '');
                
                // ----------------------------------------------------------
                // AMBIL & TEMPELKAN GAMBAR KE SHEET ACTION CELL A26
                // ----------------------------------------------------------
                if (!empty($head->keterangan_gambar)) {
                    $relativeUrl = trim($head->keterangan_gambar);
                    
                    // Tulis string path gambar ke Cell A26 sebagai teks dasar
                    $sheet->setCellValue('A26', $relativeUrl);
                    
                    $imagePath = null;
                    
                    // Penelusuran lokasi file gambar di server
                    if (file_exists(public_path($relativeUrl))) {
                        $imagePath = public_path($relativeUrl);
                    } 
                    elseif (file_exists(storage_path('app/public/' . $relativeUrl))) {
                        $imagePath = storage_path('app/public/' . $relativeUrl);
                    } 
                    elseif (file_exists(storage_path('app/' . $relativeUrl))) {
                        $imagePath = storage_path('app/' . $relativeUrl);
                    } 
                    elseif (filter_var($relativeUrl, FILTER_VALIDATE_URL) || preg_match('/^https?:\/\//i', $relativeUrl)) {
                        $imageContent = @file_get_contents($relativeUrl);
                        if ($imageContent !== false) {
                            $ext = pathinfo(parse_url($relativeUrl, PHP_URL_PATH), PATHINFO_EXTENSION) ?: 'png';
                            $tempImagePath = sys_get_temp_dir() . '/chamber_img_' . uniqid() . '.' . $ext;
                            file_put_contents($tempImagePath, $imageContent);
                            $imagePath = $tempImagePath;
                        }
                    }
                    else {
                        $fullUrl = url($relativeUrl);
                        $imageContent = @file_get_contents($fullUrl);
                        if ($imageContent !== false) {
                            $ext = pathinfo($relativeUrl, PATHINFO_EXTENSION) ?: 'png';
                            $tempImagePath = sys_get_temp_dir() . '/chamber_img_' . uniqid() . '.' . $ext;
                            file_put_contents($tempImagePath, $imageContent);
                            $imagePath = $tempImagePath;
                        }
                    }
                    
                    // Sisipkan objek gambar ke Sheet ACTION Cell A26
                    if ($imagePath && file_exists($imagePath)) {
                        $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
                        $drawing->setName('Gambar Teknisi Chamber');
                        $drawing->setDescription('Gambar Chamber Cell A26');
                        $drawing->setPath($imagePath);
                        $drawing->setCoordinates('A26');
                        $drawing->setHeight(140);
                        $drawing->setWorksheet($sheet);
                        
                        \Log::info('SUKSES! Menyisipkan objek gambar ke cell ACTION!A26', [
                            'sheet' => $actionSheetName,
                            'resolved_path' => $imagePath
                        ]);
                    } else {
                        Log::warning('Gambar dari keterangan_gambar tidak dapat ditemukan di server', [
                            'input_path' => $relativeUrl
                        ]);
                    }
                }
            }
            
            // ==============================================================
            // DATA ADD CHAMBER (TSETTING PER REPETITION)
            // ==============================================================
            // Repetition 1 = B32, Repetition 2 = B44, Repetition 3 = B56, Repetition 4 = B68
            $tsettingCells = [
                1 => 'B32',
                2 => 'B44',
                3 => 'B56',
                4 => 'B68'
            ];
            
            $repetitionsForForm = $addsByForm[$formIndex] ?? [];
            
            foreach ($repetitionsForForm as $rep => $add) {
                // Ambil nilai Tsetting
                $tSettingValue = $add->Tsetting ?? '';
                
                // Masukkan nilai Tsetting ke cell Excel sesuai nomor repetition-nya
                if (isset($tsettingCells[$rep])) {
                    $sheet->setCellValue($tsettingCells[$rep], $tSettingValue);
                }
            }
            
            // ==============================================================
            // DATA INTERVAL WAKTU PER REPETITION (KOLOM A)
            // ==============================================================
            $intervalCells = [
                1 => ['start' => 35, 'end' => 42],
                2 => ['start' => 47, 'end' => 54],
                3 => ['start' => 59, 'end' => 66],
                4 => ['start' => 71, 'end' => 78]
            ];
            
            foreach ($intervalCells as $rep => $range) {
                if (isset($detailsByForm[$formIndex][$rep])) {
                    $row = $range['start'];
                    $endRow = $range['end'];
                    
                    ksort($detailsByForm[$formIndex][$rep]);
                    
                    foreach ($detailsByForm[$formIndex][$rep] as $interval => $detail) {
                        if ($row <= $endRow) {
                            $sheet->setCellValue('A' . $row, $detail->interval_number ?? '');
                            $row++;
                        }
                    }
                }
            }
            
            // ==============================================================
            // DETAIL DATA CHAMBER (READ ALAT, RH ALAT, & SENSOR 1 s/d SENSOR 9, RH ULANGAN)
            // ==============================================================
            $dataRows = [
                1 => ['start' => 35, 'end' => 42],
                2 => ['start' => 47, 'end' => 54],
                3 => ['start' => 59, 'end' => 66],
                4 => ['start' => 71, 'end' => 78]
            ];
            
            foreach ($dataRows as $rep => $range) {
                if (isset($detailsByForm[$formIndex][$rep])) {
                    $row = $range['start'];
                    $endRow = $range['end'];
                    
                    ksort($detailsByForm[$formIndex][$rep]);
                    
                    foreach ($detailsByForm[$formIndex][$rep] as $interval => $detail) {
                        if ($row <= $endRow) {
                            // Kolom B = Read Alat (Suhu Alat Standar)
                            $sheet->setCellValue('B' . $row, $detail->readAlat ?? '');
                            
                            // Kolom C = RH Alat (Humidity Alat Standar)
                            $sheet->setCellValue('C' . $row, $detail->RHAlat ?? '');
                            
                            // Kolom D s/d L = Ulangan01 s/d Ulangan09 (Sensor 1-9)
                            $sheet->setCellValue('D' . $row, $detail->ulangan01 ?? '');
                            $sheet->setCellValue('E' . $row, $detail->ulangan02 ?? '');
                            $sheet->setCellValue('F' . $row, $detail->ulangan03 ?? '');
                            $sheet->setCellValue('G' . $row, $detail->ulangan04 ?? '');
                            $sheet->setCellValue('H' . $row, $detail->ulangan05 ?? '');
                            $sheet->setCellValue('I' . $row, $detail->ulangan06 ?? '');
                            $sheet->setCellValue('J' . $row, $detail->ulangan07 ?? '');
                            $sheet->setCellValue('K' . $row, $detail->ulangan08 ?? '');
                            $sheet->setCellValue('L' . $row, $detail->ulangan09 ?? '');
                            
                            // Kolom M = RH Ulangan
                            $sheet->setCellValue('M' . $row, $detail->RHulangan ?? '');
                            
                            $row++;
                        }
                    }
                }
            }
            
            \Log::info("Form {$formIndex}: Filled DetailChamber rows into sheet {$actionSheetName}");
            
            // ==============================================================
            // ISI CELL K1 DENGAN NAMA USER
            // ==============================================================
            if (!empty($userName)) {
                $sheet->setCellValue('K1', $userName);
            }
        }
        
        // ==============================================================
        // OPTIMASI DAN SIMPAN FILE EXCEL
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        // Hapus file gambar temporary jika ada
        if ($tempImagePath && file_exists($tempImagePath)) {
            @unlink($tempImagePath);
        }
        
        \Log::info('SUKSES! Data Chamber dan Gambar A26 berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'total_forms'    => $maxFormIndex
        ]);
        
    } catch (\Exception $e) {
        // Hapus temp file jika terjadi error saat proses
        if ($tempImagePath && file_exists($tempImagePath)) {
            @unlink($tempImagePath);
        }
        
        \Log::error('Error fillChamberExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        
        throw $e;
    }
}

public function fillSurfaceRoughnessTesterExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk Surface Roughness Tester', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // Ambil nama user dari session login
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        // Ambil sheet ACTION
        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Surface Roughness Tester");
        }
        
        // Ambil data HeadSurfaceRoughnessTester (hanya 1 form)
        $head = \App\Models\HeadSurfaceRoughnessTester::where('calibration_id', $calibration->id)->first();
        
        // Ambil data DetailSurfaceRoughnessTester
        $details = \App\Models\DetailSurfaceRoughnessTester::where('calibration_id', $calibration->id)
                    ->orderBy('id', 'asc')
                    ->get();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur (cell E2)
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B40', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B41', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA SURFACE ROUGHNESS TESTER
        // ==============================================================
        if ($head) {
            // Range Min & Max
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Alat Standar & Metode Kalibrasi
            $sheet->setCellValue('B38', $head->standard ?? '');
            $sheet->setCellValue('B39', $head->calibrationMethod ?? '');
            
            // Satuan Unit (header tabel di ACTION)
            $sheet->setCellValue('A26', $head->satuan_unit ?? '');
            
            // Satuan Penunjukan Alat (header kolom penunjukan alat)
            // Misal di B27, C27, D27 (header per kolom)
            $sheet->setCellValue('E25', $head->satuan_penunjukan_alat ?? '');
            
            // Satuan Cut Off (header kolom cut off)
            // Misal di G27 (kolom cut off)
            $sheet->setCellValue('F26', $head->satuan_cut_off ?? '');
            
            \Log::info('Head data filled from HeadSurfaceRoughnessTester', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'satuan_unit' => $head->satuan_unit ?? 'not set',
                'satuan_penunjukan_alat' => $head->satuan_penunjukan_alat ?? 'not set',
                'satuan_cut_off' => $head->satuan_cut_off ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA SURFACE ROUGHNESS TESTER
        // ==============================================================
        // Struktur kolom di DetailSurfaceRoughnessTester:
        //   - nominalSTD       → A28:A38 (Nominal Standar)
        //   - parameter        → (opsional, kalau ada kolom khusus)
        //   - ukurAlat1        → B28:B38 (Penunjukan Alat 1)
        //   - ukurAlat2        → C28:C38 (Penunjukan Alat 2)
        //   - ukurAlat3        → D28:D38 (Penunjukan Alat 3)
        //   - CutOff           → G28:G38 (Cut Off)
        //
        // Sheet ACTION:
        //   - A28:A38 = Nominal Standar
        //   - B28:B38 = Penunjukan Alat 1
        //   - C28:C38 = Penunjukan Alat 2
        //   - D28:D38 = Penunjukan Alat 3
        //   - G28:G38 = Cut Off
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 27;
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 36) break; // Max 11 baris (A28-A38)
                
                // Nominal Standar -> A27-A38
                $sheet->setCellValue('A' . $row, $detail->nominalSTD ?? '');
                
                // Penunjukan Alat 1 -> B28-B38
                $sheet->setCellValue('B' . $row, $detail->parameter ?? '');
                
                // Penunjukan Alat 1 -> B28-B38
                $sheet->setCellValue('C' . $row, $detail->ukurAlat1 ?? '');
                
                // Penunjukan Alat 2 -> C28-C38
                $sheet->setCellValue('D' . $row, $detail->ukurAlat2 ?? '');
                
                // Penunjukan Alat 3 -> D28-D38
                $sheet->setCellValue('E' . $row, $detail->ukurAlat3 ?? '');
                
                // Cut Off -> G28-G38
                $sheet->setCellValue('F' . $row, $detail->CutOff ?? '');
                
                // Note: field 'parameter' dari model — kalau memang ada kolom khusus,
                // bisa ditambahkan di sini. Untuk sementara tidak ditaruh di ACTION.
                // $sheet->setCellValue('H' . $row, $detail->parameter ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Surface Roughness Tester)");
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Surface Roughness Tester berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillSurfaceRoughnessTesterExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

