        $details = \App\Models\DetailBoreGauge::where('calibration_id', $calibration->id)
            ->orderBy('id', 'asc')
            ->get();
        
        $additional = \App\Models\AddBoreGauge::where('calibration_id', $calibration->id)->first();
        
        // ==============================================================
        // DATA UMUM DARI TABEL CALIBRATION
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        // Jenis Alat Ukur
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // Tanggal
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Calibrated & Verified by
        $sheet->setCellValue('B75', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B76', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA BORE GAUGE
        // Model: HeadBoreGauge
        // Fillable: standard, calibrationMethod, satuan_unit_bawah, satuan_unit_atas
        // ==============================================================
        if ($head) {
            // Range Min & Max dari calibration
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            
            // Kapasitas & Resolusi dari calibration
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            // Alat Standar & Metode Kalibrasi dari HeadBoreGauge
            $sheet->setCellValue('B73', $head->standard ?? '');
            $sheet->setCellValue('B74', $head->calibrationMethod ?? '');
            
            // Satuan Unit
            $sheet->setCellValue('A27', $head->satuan_unit_bawah ?? '');
            // $sheet->setCellValue('B27', $head->satuan_unit_atas ?? '');
            
            \Log::info('Head data filled from HeadBoreGauge', [
                'range_min' => $calibration->rangeMin ?? 'not set',
                'range_max' => $calibration->rangeMax ?? 'not set',
                'kapasitas' => $calibration->kapasitas ?? 'not set',
                'resolusi' => $calibration->resolusi ?? 'not set',
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'satuan_unit_bawah' => $head->satuan_unit_bawah ?? 'not set',
       
            ]);
        }
        
        // ==============================================================
        // DETAIL DATA BORE GAUGE
        // Model: DetailBoreGauge
        // Fillable: penunjukAlat, std_naik, std_turun
        //
        // Sheet ACTION:
        //   A28:A67 = Titik Ukur (penunjukAlat)
        //   B28:B67 = Pembacaan Naik (std_naik)
        //   C28:C67 = Pembacaan Turun (std_turun)
        // ==============================================================
        if ($details && $details->count() > 0) {
            $row = 28;
            $detailIndex = 0;
            
            foreach ($details as $detail) {
                if ($row > 67) break; // Max 40 baris (A28-A67)
                
                // Titik Ukur / Penunjuk Alat -> A28-A67
                $sheet->setCellValue('A' . $row, $detail->penunjukAlat ?? '');
                
                // Pembacaan Naik -> B28-B67
                $sheet->setCellValue('B' . $row, $detail->std_naik ?? '');
                
                // Pembacaan Turun -> C28-C67
                $sheet->setCellValue('C' . $row, $detail->std_turun ?? '');
                
                $row++;
                $detailIndex++;
            }
            
            \Log::info("Filled {$detailIndex} detail rows (Bore Gauge)", [
                'first_row' => 28,
                'last_row' => $row - 1,
            ]);
        }
        
        // ==============================================================
        // DATA TAMBAHAN / REPEATABILITY
        // Model: AddBoreGauge
        // Fillable: repeatability, rep01 - rep10
        //
        // Sheet ACTION:
        //   B69     = Repeatability
        //   A70:E70 = Perulangan 1-5
        //   A71:E71 = Perulangan 6-10
        // ==============================================================
        if ($additional) {
            // Nilai Repeatability -> B69
            $sheet->setCellValue('B69', $additional->repeatability ?? '');
            
            // Perulangan 1-5 -> A70:E70
            $sheet->setCellValue('A70', $additional->rep01 ?? '');
            $sheet->setCellValue('B70', $additional->rep02 ?? '');
            $sheet->setCellValue('C70', $additional->rep03 ?? '');
            $sheet->setCellValue('D70', $additional->rep04 ?? '');
            $sheet->setCellValue('E70', $additional->rep05 ?? '');
            
            // Perulangan 6-10 -> A71:E71
            $sheet->setCellValue('A71', $additional->rep06 ?? '');
            $sheet->setCellValue('B71', $additional->rep07 ?? '');
            $sheet->setCellValue('C71', $additional->rep08 ?? '');
            $sheet->setCellValue('D71', $additional->rep09 ?? '');
            $sheet->setCellValue('E71', $additional->rep10 ?? '');
            
            \Log::info('Repeatability data filled from AddBoreGauge', [
                'repeatability' => $additional->repeatability ?? 'not set',
                'rep01' => $additional->rep01 ?? 'not set',
                'rep05' => $additional->rep05 ?? 'not set',
                'rep06' => $additional->rep06 ?? 'not set',
                'rep10' => $additional->rep10 ?? 'not set',
            ]);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Bore Gauge berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        \Log::error('Error fillBoreGaugeExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}

public function fillBoreGaugeDialExcel($filePath, $calibration)
{
    try {
        \Log::info('Mengisi data Excel untuk BORE GAUGE + DIAL INDICATOR', [
            'calibration_id' => $calibration->id
        ]);
        
        // Load file Excel template bore gauge + dial
        $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);
        
        // ==============================================================
        // 1. AMBIL NAMA USER DARI SESSION / AUTH LOGIN
        // ==============================================================
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }
        
        // ==============================================================
        // 2. AMBIL SHEET 'ACTION'
        // ==============================================================
        $sheet = $spreadsheet->getSheetByName('ACTION');
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Bore Gauge + Dial Indicator");
        }
        
        // ==============================================================
        // 3. PARSE additional_forms & subform_identities
        // ==============================================================
        $rawAdditionalForms = $calibration->additional_forms ?? [];
        if (is_string($rawAdditionalForms)) {
            $additionalForms = json_decode($rawAdditionalForms, true) ?: [];
        } elseif (is_array($rawAdditionalForms)) {
            $additionalForms = $rawAdditionalForms;
        } else {
            $additionalForms = [];
        }
        
        $rawSubformIdentities = $calibration->subform_identities ?? [];
        if (is_string($rawSubformIdentities)) {
            $subformIdentities = json_decode($rawSubformIdentities, true) ?: [];
        } elseif (is_array($rawSubformIdentities)) {
            $subformIdentities = $rawSubformIdentities;
        } else {
            $subformIdentities = [];
        }
        
        \Log::info('🔍 Bore Gauge + Dial subform detection', [
            'additional_forms' => $additionalForms,
            'subform_keys' => array_keys($subformIdentities),
        ]);
        
        // ==============================================================
        // 4. AMBIL DATA MODEL RELATION (PISAH, DIISI SEMUA)
        // ==============================================================
        
        // --- Data Bore Gauge (alat utama) ---
        $headBore       = \App\Models\HeadBoreGauge::where('calibration_id', $calibration->id)->first();
        $detailsBore    = \App\Models\DetailBoreGauge::where('calibration_id', $calibration->id)
                                ->orderBy('id', 'asc')
                                ->get();
        $addBore        = \App\Models\AddBoreGauge::where('calibration_id', $calibration->id)->first();
        
        // --- Data Dial Indicator (subform) ---
        $headDial       = \App\Models\HeadDialIndicator::where('calibration_id', $calibration->id)->first();
        $detailsDial    = \App\Models\DetailDialIndicator::where('calibration_id', $calibration->id)
                                ->orderBy('id', 'asc')
                                ->get();
        $addDial        = \App\Models\AddDialIndicator::where('calibration_id', $calibration->id)->first();
        
        \Log::info('📦 Bore Gauge + Dial data counts', [
            'headBore'      => $headBore ? 'ADA' : 'KOSONG',
            'detailsBore'   => $detailsBore->count(),
            'addBore'       => $addBore ? 'ADA' : 'KOSONG',
            'headDial'      => $headDial ? 'ADA' : 'KOSONG',
            'detailsDial'   => $detailsDial->count(),
            'addDial'       => $addDial ? 'ADA' : 'KOSONG',
        ]);
        
        // ==============================================================
        // 5. DATA UTAMA DARI TABEL CALIBRATIONS (CELL B - SELALU)
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $headBore->certificate_id 
                                        ?? $headDial->certificate_id 
                                        ?? $calibration->certificate_id 
                                        ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
        $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
        $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
        $sheet->setCellValue('B10', $calibration->resolusi ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B12', $calibration->tanggalMasuk 
                                        ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) 
                                        : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi 
                                        ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) 
                                        : '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        // Suhu & RH dari calibrations
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        // Jenis Alat Ukur
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        // ==============================================================
        // 6. DATA SUBFORM DARI subform_identities (CELL C - SELALU)
        // ==============================================================
        $subformData = null;
        $subformKey  = '';
        
        if (isset($subformIdentities['dial_indicator'])) {
            $subformData = $subformIdentities['dial_indicator'];
            $subformKey  = 'dial_indicator';
        } elseif (isset($subformIdentities['bore_gauge'])) {
            $subformData = $subformIdentities['bore_gauge'];
            $subformKey  = 'bore_gauge';
        }
        
        if ($subformData) {
            // Data identitas subform → kolom C
            $sheet->setCellValue('C2',  $subformData['nama_alat'] ?? '');
            $sheet->setCellValue('C3',  $subformData['merek'] ?? '');
            $sheet->setCellValue('C4',  $subformData['kode_alat'] ?? '');
            $sheet->setCellValue('C5',  $subformData['type_alat'] ?? '');
            $sheet->setCellValue('C6',  $subformData['no_seri'] ?? '');
            $sheet->setCellValue('C7',  $subformData['rentang_ukur_min'] ?? '0');
            $sheet->setCellValue('C8',  $subformData['rentang_ukur_max'] ?? '');
            $sheet->setCellValue('C9',  $subformData['kapasitas'] ?? '');
            $sheet->setCellValue('C10', $subformData['resolusi'] ?? '');
            $sheet->setCellValue('C11', $subformData['nama_pemilik'] ?? '');
            $sheet->setCellValue('C12', !empty($subformData['tanggal_alat_masuk']) 
                                            ? date('d-m-Y', strtotime($subformData['tanggal_alat_masuk'])) 
                                            : '');
            $sheet->setCellValue('C13', !empty($subformData['tanggal_kalibrasi']) 
                                            ? date('d-m-Y', strtotime($subformData['tanggal_kalibrasi'])) 
                                            : '');
            $sheet->setCellValue('C14', $subformData['jenis_pembacaan'] ?? '');
            $sheet->setCellValue('C15', $subformData['tempat_kalibrasi'] ?? '');
            $sheet->setCellValue('C16', $subformData['lokasi_pt'] ?? $subformData['lokasiPT'] ?? '');
            $sheet->setCellValue('C17', $subformData['kondisi_alat'] ?? '');
            $sheet->setCellValue('C18', $subformData['keterangan'] ?? '');
            $sheet->setCellValue('C19', $subformData['kode_th'] ?? '');
            
            // Suhu & RH dari subform → kolom E, F, G
            $sheet->setCellValue('E22', $subformData['suhu_awal'] ?? '');
            $sheet->setCellValue('F22', $subformData['suhu_tengah'] ?? '');
            $sheet->setCellValue('G22', $subformData['suhu_akhir'] ?? '');
            $sheet->setCellValue('E23', $subformData['rh_awal'] ?? '');
            $sheet->setCellValue('F23', $subformData['rh_tengah'] ?? '');
            $sheet->setCellValue('G23', $subformData['rh_akhir'] ?? '');
            
            \Log::info('✅ Data subform diisi ke kolom C', [
                'subform_key' => $subformKey
            ]);
        } else {
            \Log::warning('⚠️ Subform data tidak ditemukan di subform_identities', [
                'available_keys' => array_keys($subformIdentities)
            ]);
        }
        
        // ==============================================================
        // 7. HEAD DATA & DETAIL - BORE GAUGE (SELALU DIISI)
        // ==============================================================
        if ($headBore) {
            
            // --- Alat Standar, Method, Calibrated/Verified by ---
            $sheet->setCellValue('B122', $headBore->standard ?? '');
            $sheet->setCellValue('B123', $headBore->calibrationMethod ?? '');
            $sheet->setCellValue('B124', $calibration->calibratedBy ?? '');
            $sheet->setCellValue('B125', $calibration->verifiedBy ?? '');
            
            // Satuan unit Bore
            $sheet->setCellValue('A27', $headBore->satuan_unit_bawah ?? '');
            
            // ----------------------------------------------------------
            // DETAIL BORE GAUGE
            // Mapping: A28:C67 = Titik Ukur / Naik / Turun
            // ----------------------------------------------------------
            if ($detailsBore && $detailsBore->count() > 0) {
                $row = 28;
                $countBore = 0;
                
                foreach ($detailsBore as $detail) {
                    if ($row > 67) break; // Max 40 baris
                    
                    $sheet->setCellValue('A' . $row, $detail->penunjukAlat ?? '');
                    $sheet->setCellValue('B' . $row, $detail->std_naik ?? '');
                    $sheet->setCellValue('C' . $row, $detail->std_turun ?? '');
                    
                    $row++;
                    $countBore++;
                }
                
                \Log::info("Filled {$countBore} DetailBoreGauge rows (Bore Gauge Dial template)", [
                    'first_row' => 28,
                    'last_row'  => $row - 1,
                ]);
            }
            
            // ----------------------------------------------------------
            // REPEATABILITY BORE GAUGE
            // Mapping: B69, A70:E70, A71:E71
            // ----------------------------------------------------------
            if ($addBore) {
                $sheet->setCellValue('B69', $addBore->repeatability ?? '');
                
                // Perulangan 1-5 → A70:E70
                $sheet->setCellValue('A70', $addBore->rep01 ?? '');
                $sheet->setCellValue('B70', $addBore->rep02 ?? '');
                $sheet->setCellValue('C70', $addBore->rep03 ?? '');
                $sheet->setCellValue('D70', $addBore->rep04 ?? '');
                $sheet->setCellValue('E70', $addBore->rep05 ?? '');
                
                // Perulangan 6-10 → A71:E71
                $sheet->setCellValue('A71', $addBore->rep06 ?? '');
                $sheet->setCellValue('B71', $addBore->rep07 ?? '');
                $sheet->setCellValue('C71', $addBore->rep08 ?? '');
                $sheet->setCellValue('D71', $addBore->rep09 ?? '');
                $sheet->setCellValue('E71', $addBore->rep10 ?? '');
                
                \Log::info('Repeatability Bore Gauge filled');
            }
        }
        
        // ==============================================================
        // 8. HEAD DATA & DETAIL - DIAL INDICATOR (SELALU DIISI)
        // ==============================================================
        if ($headDial) {
            
            // --- Alat Standar, Method Dial ---
            // Cell C122 dibaca oleh sub Extract (PindahkanDataTest) sebagai alat standar dial
            $sheet->setCellValue('C122', $headDial->standard ?? '');
            $sheet->setCellValue('C123', $headDial->calibrationMethod ?? '');
            
            // Satuan unit Dial (kiri & kanan)
            $sheet->setCellValue('B73', $headDial->satuan_alat_kiri ?? '');
            $sheet->setCellValue('B74', $headDial->satuan_alat_kanan ?? '');
            
            // ----------------------------------------------------------
            // DETAIL DIAL INDICATOR
            // Mapping:
            //   A77:A115 = titikUkur
            //   B77:B115 = ulanganNaik
            //   C77:C115 = ulanganTurun
            // ----------------------------------------------------------
            if ($detailsDial && $detailsDial->count() > 0) {
                $row = 77;
                $countDial = 0;
                
                foreach ($detailsDial as $detail) {
                    if ($row > 115) break; // Max 39 baris
                    
                    $sheet->setCellValue('A' . $row, $detail->titikUkur ?? '');
                    $sheet->setCellValue('B' . $row, $detail->ulanganNaik ?? '');
                    $sheet->setCellValue('C' . $row, $detail->ulanganTurun ?? '');
                    
                    $row++;
                    $countDial++;
                }
                
                \Log::info("Filled {$countDial} DetailDialIndicator rows (Bore Gauge Dial template)", [
                    'first_row' => 77,
                    'last_row'  => $row - 1,
                ]);
            }
            
            // ----------------------------------------------------------
            // REPEATABILITY DIAL (dari AddDialIndicator)
            // Mapping:
            //   A119:E119 = ulangan01 - ulangan05
            //   A120:E120 = ulangan06 - ulangan10
            // ----------------------------------------------------------
            if ($addDial) {
                // Perulangan 1-5 → A119:E119
                $sheet->setCellValue('A119', $addDial->ulangan01 ?? '');
                $sheet->setCellValue('B119', $addDial->ulangan02 ?? '');
                $sheet->setCellValue('C119', $addDial->ulangan03 ?? '');
                $sheet->setCellValue('D119', $addDial->ulangan04 ?? '');
                $sheet->setCellValue('E119', $addDial->ulangan05 ?? '');
                
                // Perulangan 6-10 → A120:E120
                $sheet->setCellValue('A120', $addDial->ulangan06 ?? '');
                $sheet->setCellValue('B120', $addDial->ulangan07 ?? '');
                $sheet->setCellValue('C120', $addDial->ulangan08 ?? '');
                $sheet->setCellValue('D120', $addDial->ulangan09 ?? '');
                $sheet->setCellValue('E120', $addDial->ulangan10 ?? '');
                
                \Log::info('Repeatability Dial Indicator filled from AddDialIndicator', [
                    'repeatability' => $addDial->repeatability ?? 'not set',
                    'ulangan01'     => $addDial->ulangan01 ?? 'not set',
                    'ulangan05'     => $addDial->ulangan05 ?? 'not set',
                    'ulangan06'     => $addDial->ulangan06 ?? 'not set',
                    'ulangan10'     => $addDial->ulangan10 ?? 'not set',
                ]);
            }
        }
        
        // ==============================================================
        // 9. ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // 10. SIMPAN FILE EXCEL
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        \Log::info('SUKSES! Data Bore Gauge + Dial Indicator berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id,
            'bore_filled'    => $headBore ? 'yes' : 'no',
            'dial_filled'    => $headDial ? 'yes' : 'no',
        ]);
        
    } catch (\Exception $e) {
        \Log::error('Error fillBoreGaugeDialExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        
        throw $e;
    }
}

public function fillSurfacePlateExcel($filePath, $calibration)
{
    $tempImagePath = null;
    
    try {
        \Log::info('Mengisi data Excel untuk Surface Plate', [
            'calibration_id' => $calibration->id
        ]);

        $spreadsheet = IOFactory::load($filePath);
        
        $userName = '';
        if (auth()->check()) {
            $userName = auth()->user()->nama;
        } elseif (session()->has('user_name')) {
            $userName = session('user_name');
        } elseif (session()->has('nama_user')) {
            $userName = session('nama_user');
        }

        $sheet = $spreadsheet->getSheetByName('ACTION');
        
        if (!$sheet) {
            throw new \Exception("Sheet 'ACTION' tidak ditemukan di template Surface Plate");
        }
        
        // ==============================================================
        // AMBIL DATA
        // ==============================================================
        $head = \App\Models\HeadSurfacePlate::where('calibration_id', $calibration->id)->first();
        
        $detail = \App\Models\DetailSurfacePlate::where('calibration_id', $calibration->id)
                    ->orderBy('id', 'desc')
                    ->first();
        
        \Log::info('Data retrieved from DB:', [
            'head_found' => $head ? true : false,
            'detail_found' => $detail ? true : false,
        ]);
        
        // ==============================================================
        // DATA UMUM
        // ==============================================================
        $sheet->setCellValue('B1',  $calibration->id ?? '');
        $sheet->setCellValue('E1',  $head->certificate_id ?? $calibration->certificate_id ?? '');
        $sheet->setCellValue('B2',  $calibration->namaAlat ?? '');
        $sheet->setCellValue('B3',  $calibration->brandAlat ?? '');
        $sheet->setCellValue('B5',  $calibration->typeAlat ?? '');
        $sheet->setCellValue('B6',  $calibration->NoSeri ?? '');
        $sheet->setCellValue('B4',  $calibration->kodeAlat ?? '');
        $sheet->setCellValue('B18', $calibration->keterangan ?? '');
        $sheet->setCellValue('B17', $calibration->kondisiAlat ?? '');
        
        $sheet->setCellValue('E2', $calibration->form_type ?? '');
        
        $sheet->setCellValue('B12', $calibration->tanggalMasuk ? date('d-m-Y', strtotime($calibration->tanggalMasuk)) : '');
        $sheet->setCellValue('B13', $calibration->tanggalKalibrasi ? date('d-m-Y', strtotime($calibration->tanggalKalibrasi)) : '');
        
        $sheet->setCellValue('B15', $calibration->tempatKalibrasi ?? '');
        $sheet->setCellValue('B14', $calibration->jenisPembacaan ?? '');
        $sheet->setCellValue('B11', $calibration->pemilikAlat ?? '');
        $sheet->setCellValue('B16', $calibration->lokasiPT ?? '');
        $sheet->setCellValue('B19', $calibration->kode_th ?? '');
        
        $sheet->setCellValue('B22', $calibration->RT_condition1 ?? '');
        $sheet->setCellValue('C22', $calibration->RT_condition2 ?? '');
        $sheet->setCellValue('D22', $calibration->RT_condition3 ?? '');
        $sheet->setCellValue('B23', $calibration->RH_condition1 ?? '');
        $sheet->setCellValue('C23', $calibration->RH_condition2 ?? '');
        $sheet->setCellValue('D23', $calibration->RH_condition3 ?? '');
        
        $sheet->setCellValue('B86', $calibration->calibratedBy ?? '');
        $sheet->setCellValue('B87', $calibration->verifiedBy ?? '');
        
        // ==============================================================
        // HEAD DATA
        // ==============================================================
        if ($head) {
            $sheet->setCellValue('B7',  $calibration->rangeMin ?? '0');
            $sheet->setCellValue('B8',  $calibration->rangeMax ?? '');
            $sheet->setCellValue('B9',  $calibration->kapasitas ?? '');
            $sheet->setCellValue('B10', $calibration->resolusi ?? '');
            
            $sheet->setCellValue('B84', $head->standard ?? '');
            $sheet->setCellValue('B85', $head->calibrationMethod ?? '');
            
            \Log::info('Head data filled from HeadSurfacePlate', [
                'standard' => $head->standard ?? 'not set',
                'calibrationMethod' => $head->calibrationMethod ?? 'not set',
                'certificate_id' => $head->certificate_id ?? 'not set',
            ]);
            
            // ==========================================================
            // 🔥 INSERT GAMBAR KE CELL A26
            // ==========================================================
            if (!empty($head->keterangan)) {
                $relativeUrl = trim($head->keterangan);
                
                $sheet->setCellValue('A26', $relativeUrl);
                
                $imagePath = null;
                
                if (file_exists(public_path($relativeUrl))) {
                    $imagePath = public_path($relativeUrl);
                } 
                elseif (file_exists(storage_path('app/public/' . $relativeUrl))) {
                    $imagePath = storage_path('app/public/' . $relativeUrl);
                } 
                elseif (file_exists(storage_path('app/' . $relativeUrl))) {
                    $imagePath = storage_path('app/' . $relativeUrl);
                } 
                elseif (filter_var($relativeUrl, FILTER_VALIDATE_URL) || preg_match('/^https?:\/\//i', $relativeUrl)) {
                    $imageContent = @file_get_contents($relativeUrl);
                    if ($imageContent !== false) {
                        $ext = pathinfo(parse_url($relativeUrl, PHP_URL_PATH), PATHINFO_EXTENSION) ?: 'png';
                        $tempImagePath = sys_get_temp_dir() . '/sp_img_' . uniqid() . '.' . $ext;
                        file_put_contents($tempImagePath, $imageContent);
                        $imagePath = $tempImagePath;
                    }
                }
                else {
                    $fullUrl = url($relativeUrl);
                    $imageContent = @file_get_contents($fullUrl);
                    if ($imageContent !== false) {
                        $ext = pathinfo($relativeUrl, PATHINFO_EXTENSION) ?: 'png';
                        $tempImagePath = sys_get_temp_dir() . '/sp_img_' . uniqid() . '.' . $ext;
                        file_put_contents($tempImagePath, $imageContent);
                        $imagePath = $tempImagePath;
                    }
                }
                
                if ($imagePath && file_exists($imagePath)) {
                    $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
                    $drawing->setName('Gambar Visualisasi Surface Plate');
                    $drawing->setDescription('Gambar Surface Plate Cell A26');
                    $drawing->setPath($imagePath);
                    $drawing->setCoordinates('A26');
                    $drawing->setHeight(140);
                    $drawing->setWorksheet($sheet);
                    
                    \Log::info('SUKSES! Menyisipkan objek gambar ke cell ACTION!A26', [
                        'resolved_path' => $imagePath
                    ]);
                } else {
                    \Log::warning('Gambar dari head->keterangan tidak dapat ditemukan di server', [
                        'input_path' => $relativeUrl
                    ]);
                }
            }
        }
        
        // ==============================================================
        // DETAIL DATA
        // ==============================================================
        if ($detail) {
            
            // ----------------------------------------------------------
            // 1. SETTING SUHU — 13 baris × 10 kolom
            //    Sheet ACTION: B33:K45
            //    🔥 FIX: pakai Coordinate::stringFromColumnIndex()
            // ----------------------------------------------------------
            for ($row = 1; $row <= 13; $row++) {
                for ($col = 1; $col <= 10; $col++) {
                    $fieldName = "a{$row}_{$col}";
                    $value = $detail->$fieldName ?? '';
                    
                    $excelRow = 33 + ($row - 1);   // 33..45
                    $excelCol = 2 + ($col - 1);    // 2=B, 3=C, ..., 11=K
                    
                    // 🔥 Convert index ke huruf kolom
                    $colLetter = Coordinate::stringFromColumnIndex($excelCol);
                    
                    $sheet->setCellValue($colLetter . $excelRow, $value);
                }
            }
            
            \Log::info('Setting Suhu filled: 13x10 (B33:K45)');
            
            // ----------------------------------------------------------
            // 2. REPEATABILITY — GROUP A s/d L
            // ----------------------------------------------------------
            $groups = [
                0  => ['a', 1],
                1  => ['b', 2],
                2  => ['c', 3],
                3  => ['d', 4],
                4  => ['e', 5],
                5  => ['f', 6],
                6  => ['g', 7],
                7  => ['h', 8],
                8  => ['i', 9],
                9  => ['j', 10],
                10 => ['k', 11],
                11 => ['l', 12],
            ];
            
            foreach ($groups as $grpIdx => $group) {
                $letter = $group[0];
                $tblNum = $group[1];
                
                $srcRowMaju   = 48 + ($grpIdx * 3);
                $srcRowMundur = $srcRowMaju + 1;
                
                $maxCol = ($grpIdx == 0) ? 10 : 11;
                
                for ($i = 0; $i < $maxCol; $i++) {
                    
                    // === MAJU ===
                    if ($grpIdx == 0) {
                        $fieldNameMaju = "a" . ($i + 1) . "_1_tbl1";
                    } else {
                        if ($i == 0) {
                            $fieldNameMaju = "a1_1_tbl{$tblNum}";
                        } else {
                            $rowNum = $i;
                            $fieldNameMaju = "{$letter}{$rowNum}_1_tbl{$tblNum}";
                        }
                    }
                    
                    $valueMaju = $detail->$fieldNameMaju ?? '';
                    $excelCol = 2 + $i;
                    
                    // 🔥 Convert index ke huruf kolom
                    $colLetter = Coordinate::stringFromColumnIndex($excelCol);
                    
                    $sheet->setCellValue($colLetter . $srcRowMaju, $valueMaju);
                    
                    // === MUNDUR ===
                    if ($grpIdx == 0) {
                        $fieldNameMundur = "a" . ($i + 1) . "_2_tbl1";
                    } else {
                        if ($i == 0) {
                            $fieldNameMundur = "a1_2_tbl{$tblNum}";
                        } else {
                            $rowNum = $i;
                            $fieldNameMundur = "{$letter}{$rowNum}_2_tbl{$tblNum}";
                        }
                    }
                    
                    $valueMundur = $detail->$fieldNameMundur ?? '';
                    
                    $sheet->setCellValue($colLetter . $srcRowMundur, $valueMundur);
                }
                
                \Log::info("Group {$letter} (TBL{$tblNum}) filled: rows {$srcRowMaju}-{$srcRowMundur}");
            }
            
            \Log::info('Repeatability filled: 12 groups (A-L)');
        } else {
            \Log::warning('Detail Surface Plate tidak ditemukan untuk calibration_id: ' . $calibration->id);
        }
        
        // ==============================================================
        // ISI CELL K1 DENGAN NAMA USER
        // ==============================================================
        if (!empty($userName)) {
            $sheet->setCellValue('K1', $userName);
        }
        
        // ==============================================================
        // OPTIMASI UNTUK PRESERVE MACRO
        // ==============================================================
        $spreadsheet->setActiveSheetIndex(0);
        $spreadsheet->garbageCollect();
        
        $calculationEngine = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
        $calculationEngine->setCalculationCacheEnabled(false);
        $calculationEngine->clearCalculationCache();
        
        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->setPreCalculateFormulas(false);
        $writer->save($filePath);
        
        // Hapus temp file jika ada
        if ($tempImagePath && file_exists($tempImagePath)) {
            @unlink($tempImagePath);
        }
        
        \Log::info('SUKSES! Data Surface Plate berhasil diisi ke Excel', [
            'calibration_id' => $calibration->id
        ]);
        
    } catch (Exception $e) {
        if ($tempImagePath && file_exists($tempImagePath)) {
            @unlink($tempImagePath);
        }
        
        \Log::error('Error fillSurfacePlateExcel: ' . $e->getMessage(), [
            'calibration_id' => $calibration->id ?? null,
            'trace' => $e->getTraceAsString()
        ]);
        throw $e;
    }
}
public function downloadVerified($id)
{
    $tmpPath = null;

    try {
        \Log::info('🟢 [DL] START DOWNLOAD VERIFIED, id: ' . $id);

        $calibration = Calibration::findOrFail($id);

        if ($calibration->status !== 'verified') {
            \Log::warning('[DL] Status bukan verified: ' . $calibration->status);
            return back()->with('error', 'File hanya bisa di-download saat status Verified.');
        }

        if (empty($calibration->location_data)) {
            \Log::warning('[DL] location_data kosong');
            return back()->with('error', 'File verified belum tersedia.');
        }

        $userName = auth()->user()->nama ?? auth()->user()->username ?? 'System';
        \Log::info('[DL] User: ' . $userName);

        // ============================================
        // UPDATE approvedBy & approved ke DATABASE
        // ============================================
        try {
            $calibration->approved = now();
            $calibration->approvedBy = $userName;
            $calibration->save();
            \Log::info('✅ [DL] Approved status updated by: ' . $userName);
        } catch (\Throwable $e) {
            \Log::error('❌ [DL] Gagal update approved: ' . $e->getMessage());
        }

        LogHelper::log('download_verified', "{$userName} mendownload file terverifikasi: {$calibration->namaAlat} ({$calibration->NoSeri})", $calibration);
        \Log::info('[DL] LogHelper selesai');

        // ============================================
        // EXTRACT PATH DARI URL
        // ============================================
        $locationData = $calibration->location_data;

        if (strpos($locationData, 'https://paperless.pascalibration.com/') === 0) {
            $relativePath = str_replace('https://paperless.pascalibration.com/', '', $locationData);
        } else {
            $relativePath = ltrim($locationData, '/\\');
        }

        if (!str_starts_with($relativePath, 'data_verified/')) {
            \Log::error('[DL] Security violation: bukan folder data_verified -> ' . $relativePath);
            return back()->with('error', 'Akses file tidak diizinkan.');
        }

        $fullPath = public_path($relativePath);
        $fileName = basename($fullPath);

        \Log::info('[DL] DB value     : ' . $locationData);
        \Log::info('[DL] Relative path: ' . $relativePath);
        \Log::info('[DL] Full path    : ' . $fullPath);
        \Log::info('[DL] File exists  : ' . (file_exists($fullPath) ? 'YES' : 'NO'));

        if (!file_exists($fullPath)) {
            return back()->with('error', 'File tidak ditemukan di server: ' . $fileName);
        }

        \Log::info('[DL] Ukuran file  : ' . filesize($fullPath) . ' byte');
        \Log::info('[DL] Readable     : ' . (is_readable($fullPath) ? 'YES' : 'NO'));
        \Log::info('[DL] ZipArchive   : ' . (class_exists('\ZipArchive') ? 'tersedia' : 'TIDAK ADA (aktifkan ekstensi php-zip)'));
        \Log::info('[DL] storage/app writable: ' . (is_writable(storage_path('app')) ? 'YES' : 'NO'));

        // ============================================
        // SALIN KE TEMPORARY (file asli tidak diubah)
        // ============================================
        $tmpPath = storage_path('app/tmp_' . uniqid() . '_' . $fileName);
        if (!@copy($fullPath, $tmpPath)) {
            \Log::error('[DL] Gagal copy ke temporary: ' . $tmpPath);
            return back()->with('error', 'Gagal menyiapkan file untuk download.');
        }
        \Log::info('[DL] Copy temporary OK: ' . $tmpPath);

        // ============================================
        // ISI J59 DI SHEET SERTIFIKAT (edit XML langsung)
        // ============================================
        try {
            $sheetName = 'SERTIFIKAT';
            $cellRef   = 'J59';
            $nsMain    = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
            $nsRel     = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

            $zip = new \ZipArchive();
            $res = $zip->open($tmpPath);
            if ($res !== true) {
                throw new \RuntimeException("Gagal buka zip, kode ZipArchive: {$res}");
            }
            \Log::info('[XLSX] Zip terbuka, jumlah entry: ' . $zip->numFiles);

            $wbXml   = $zip->getFromName('xl/workbook.xml');
            $relsXml = $zip->getFromName('xl/_rels/workbook.xml.rels');
            if (!$wbXml || !$relsXml) {
                $zip->close();
                throw new \RuntimeException('workbook.xml atau workbook.xml.rels tidak ditemukan');
            }
            \Log::info('[XLSX] workbook.xml & rels terbaca');

            // Cari rId sheet berdasarkan nama
            $wb = simplexml_load_string($wbXml);
            $rId = null;
            $daftarSheet = [];
            foreach ($wb->sheets->sheet as $s) {
                $nama = (string) $s['name'];
                $daftarSheet[] = $nama;
                if ($nama === $sheetName) {
                    $rId = (string) $s->attributes($nsRel)['id'];
                }
            }
            \Log::info('[XLSX] Daftar sheet: ' . implode(' | ', $daftarSheet));
            if (!$rId) {
                $zip->close();
                throw new \RuntimeException("Sheet '{$sheetName}' tidak ditemukan (cek huruf besar/kecil & spasi)");
            }
            \Log::info("[XLSX] Sheet '{$sheetName}' ditemukan, rId: {$rId}");

            // Cari file sheet dari rels
            $rels = simplexml_load_string($relsXml);
            $target = null;
            foreach ($rels->Relationship as $rel) {
                if ((string) $rel['Id'] === $rId) {
                    $target = (string) $rel['Target'];
                    break;
                }
            }
            if (!$target) {
                $zip->close();
                throw new \RuntimeException("Target untuk rId {$rId} tidak ada di rels");
            }
            $sheetPath = ltrim($target, '/');
            if (!str_starts_with($sheetPath, 'xl/')) {
                $sheetPath = 'xl/' . $sheetPath;
            }
            \Log::info("[XLSX] File sheet di dalam zip: {$sheetPath}");

            // Baca & edit XML sheet
            $sheetXml = $zip->getFromName($sheetPath);
            if (!$sheetXml) {
                $zip->close();
                throw new \RuntimeException("Gagal baca {$sheetPath}");
            }
            \Log::info('[XLSX] XML sheet terbaca, ukuran: ' . strlen($sheetXml) . ' byte');

            $dom = new \DOMDocument();
            $dom->preserveWhiteSpace = true;
            if (!$dom->loadXML($sheetXml)) {
                $zip->close();
                throw new \RuntimeException('loadXML sheet gagal');
            }

            $cellNode = null;
            foreach ($dom->getElementsByTagNameNS($nsMain, 'c') as $c) {
                if ($c->getAttribute('r') === $cellRef) {
                    $cellNode = $c;
                    break;
                }
            }
            if (!$cellNode) {
                $zip->close();
                throw new \RuntimeException("Cell {$cellRef} tidak ditemukan di XML sheet {$sheetName}");
            }
            \Log::info("[XLSX] Cell {$cellRef} ketemu. Isi lama: '" . trim($cellNode->textContent) . "', tipe: '" . $cellNode->getAttribute('t') . "'");

            // Kosongkan isi lama (termasuk formula), tulis sebagai inline string
            while ($cellNode->firstChild) {
                $cellNode->removeChild($cellNode->firstChild);
            }
            $cellNode->setAttribute('t', 'inlineStr');
            $is = $dom->createElementNS($nsMain, 'is');
            $t  = $dom->createElementNS($nsMain, 't');
            $t->appendChild($dom->createTextNode($userName));
            $is->appendChild($t);
            $cellNode->appendChild($is);

            if (!$zip->addFromString($sheetPath, $dom->saveXML())) {
                $zip->close();
                throw new \RuntimeException('addFromString gagal');
            }
            if (!$zip->close()) {
                throw new \RuntimeException('zip->close() gagal, perubahan tidak tersimpan (cek izin tulis)');
            }

            \Log::info("✅ [DL] J59 berhasil diisi dengan: {$userName}");
        } catch (\Throwable $e) {
            // Gagal isi J59 tidak membatalkan download, file dikirim apa adanya
            \Log::error('⚠️ [DL] Gagal isi J59: ' . get_class($e) . ' - ' . $e->getMessage()
                . ' @ ' . $e->getFile() . ':' . $e->getLine());
        }

        // ============================================
        // KIRIM FILE
        // ============================================
        while (ob_get_level() > 0) {
            ob_end_clean();
        }

        \Log::info('[DL] Mengirim file ke browser: ' . $fileName . ' (' . filesize($tmpPath) . ' byte)');

        return response()->download($tmpPath, $fileName, [
            'Content-Type'  => 'application/vnd.ms-excel.sheet.macroEnabled.12',
            'Cache-Control' => 'no-cache, no-store, must-revalidate',
        ])->deleteFileAfterSend(true);

    } catch (\Throwable $e) {
        \Log::error('❌ [DL] ERROR download verified: ' . get_class($e) . ' - ' . $e->getMessage()
            . ' @ ' . $e->getFile() . ':' . $e->getLine());
        \Log::error($e->getTraceAsString());

        if ($tmpPath && file_exists($tmpPath)) {
            @unlink($tmpPath);
        }

        return back()->with('error', 'Gagal download file: ' . $e->getMessage());
    }
}

