/**
 * ==============================================================
 * Isi cell J59 di sheet SERTIFIKAT dengan verifiedBy
 * Menggunakan COM Object Excel (Windows only)
 * 
 * PRESERVE 100%:
 * - Macro VBA
 * - Dropdown / ComboBox (VML)
 * - Drawing shape
 * - Named range
 * - Formatting
 * ==============================================================
 */
private function fillCertificateJ59ViaCom($filePath, $calibration)
{
    if (PHP_OS_FAMILY !== 'Windows') {
        \Log::warning('⚠️ COM Object hanya jalan di Windows. Skip isi J59.');
        return false;
    }
    
    $verifiedBy = $calibration->approvedBy ?? auth()->user()->nama ?? auth()->user()->username ?? '';
    
    if (empty($verifiedBy)) {
        \Log::warning('⚠️ approvedBy kosong, skip isi J59');
        return false;
    }
    
    $excel = null;
    $workbook = null;
    
    try {
        \Log::info('🔷 Start fill J59 via COM Object');
        \Log::info('   - File: ' . $filePath);
        \Log::info('   - verifiedBy: ' . $verifiedBy);
        
        // Cek file ada
        if (!file_exists($filePath)) {
            throw new \Exception('File tidak ditemukan: ' . $filePath);
        }
        
        // Buat instance Excel
        $excel = new \COM("Excel.Application");
        $excel->Visible = false;
        $excel->DisplayAlerts = false;
        $excel->ScreenUpdating = false;
        $excel->EnableEvents = false;
        
        \Log::info('✅ COM Excel instance created');
        
        // Buka workbook
        $workbook = $excel->Workbooks->Open($filePath);
        
        \Log::info('✅ Workbook opened');
        
        // Cari sheet SERTIFIKAT
        $sheet = null;
        try {
            $sheet = $workbook->Sheets("SERTIFIKAT");
        } catch (\Exception $e) {
            throw new \Exception('Sheet SERTIFIKAT tidak ditemukan');
        }
        
        if ($sheet === null) {
            throw new \Exception('Sheet SERTIFIKAT tidak ditemukan');
        }
        
        // Isi J59 dengan verifiedBy
        $sheet->Range("J59")->Value = $verifiedBy;
        
        \Log::info('✅ J59 filled: ' . $verifiedBy);
        
        // Save AS .xlsm (52 = xlOpenXMLWorkbookMacroEnabled) — preserve macro
        $workbook->SaveAs($filePath, 52);
        
        \Log::info('✅ Workbook saved as .xlsm (macro preserved)');
        
        // Tutup
        $workbook->Close(false);
        $excel->Quit();
        unset($workbook);
        unset($excel);
        
        \Log::info('✅ COM Excel closed');
        
        // Beri waktu file handle release
        sleep(1);
        
        return true;
        
    } catch (\Exception $e) {
        \Log::error('❌ COM Object error: ' . $e->getMessage());
        
        // Cleanup
        try {
            if ($workbook !== null) {
                $workbook->Close(false);
            }
        } catch (\Exception $ex) {}
        
        try {
            if ($excel !== null) {
                $excel->Quit();
            }
        } catch (\Exception $ex) {}
        
        unset($workbook);
        unset($excel);
        
        throw $e;
    }
}
/**
 * ==============================================================
 * Konversi nama file verified
 * ==============================================================
 */
private function convertVerifiedFilename($fileName, $fullPath = null)
{
    $patterns = [
        '/\.xlsx_verified\.xlsm$/i' => '_verified.xlsm',
        '/\.xls_verified\.xlsm$/i'  => '_verified.xlsm',
        '/\.xlsm_verified\.xlsm$/i' => '_verified.xlsm',
        '/\.xlsx_verified\.xlsx$/i' => '_verified.xlsx',
        '/xlsx_verified\.xlsm$/i'   => '_verified.xlsm',
        '/xls_verified\.xlsm$/i'    => '_verified.xlsm',
    ];
    
    $newFileName = $fileName;
    foreach ($patterns as $pattern => $replacement) {
        if (preg_match($pattern, $fileName)) {
            $newFileName = preg_replace($pattern, $replacement, $fileName);
            break;
        }
    }

    $newFileName = preg_replace('/\.xlsx$/i', '.xlsm', $newFileName);

    return $newFileName;
}

/**
 * ==============================================================
 * Cari file smart berdasarkan ID, nama alat, NoSeri
 * ==============================================================
 */
private function findFileSmart($id, $calibration)
{
    $directory = public_path('data_verified');
    
    if (!is_dir($directory)) {
        \Log::error('❌ Folder tidak ada: ' . $directory);
        return null;
    }
    
    $allFiles = array_merge(
        glob($directory . '/*.xlsm') ?: [],
        glob($directory . '/*.xlsx') ?: []
    );
    
    if (empty($allFiles)) {
        \Log::error('❌ Tidak ada file di folder');
        return null;
    }
    
    $idStr = (string)$id;
    \Log::info('🔍 Smart Search: ID=' . $idStr . ', Total files=' . count($allFiles));
    
    // PRIORITAS 1: Match persis ID
    foreach ($allFiles as $file) {
        $filename = basename($file);
        if (strpos($filename, $idStr) !== false) {
            \Log::info('  ✅ Match (ID): ' . $filename);
            return $file;
        }
    }
    
    // PRIORITAS 2: Match NoSeri
    if (!empty($calibration->NoSeri)) {
        $noSeri = preg_replace('/[^a-zA-Z0-9]/', '', strtoupper($calibration->NoSeri));
        
        if (strlen($noSeri) >= 4) {
            foreach ($allFiles as $file) {
                $filenameClean = preg_replace('/[^a-zA-Z0-9]/', '', strtoupper(basename($file)));
                if (strpos($filenameClean, $noSeri) !== false) {
                    \Log::info('  ✅ Match (NoSeri): ' . basename($file));
                    return $file;
                }
            }
        }
    }
    
    // PRIORITAS 3: Match nama alat (kata kunci)
    if (!empty($calibration->namaAlat)) {
        $namaAlat = preg_replace('/[^a-zA-Z0-9 ]/', '', $calibration->namaAlat);
        $words = explode(' ', $namaAlat);
        
        $keywords = [];
        foreach ($words as $word) {
            if (strlen($word) >= 4) {
                $keywords[] = strtoupper($word);
            }
        }
        
        if (!empty($keywords)) {
            foreach ($allFiles as $file) {
                $filenameUpper = strtoupper(basename($file));
                
                $matchCount = 0;
                foreach ($keywords as $kw) {
                    if (strpos($filenameUpper, $kw) !== false) {
                        $matchCount++;
                    }
                }
                
                if ($matchCount >= 2) {
                    \Log::info('  ✅ Match (' . $matchCount . ' keywords): ' . basename($file));
                    return $file;
                }
            }
        }
    }
    
    // PRIORITAS 4: 6 digit terakhir ID
    $lastSix = substr($idStr, -6);
    if (strlen($lastSix) >= 5) {
        foreach ($allFiles as $file) {
            if (strpos(basename($file), $lastSix) !== false) {
                \Log::info('  ✅ Match (6-digit): ' . basename($file));
                return $file;
            }
        }
    }
    
    \Log::error('❌ Tidak ada file yang cocok');
    return null;
}
        
        public function downloadRejected($id)
{
    try {
        \Log::info('🟢 ===== START DOWNLOAD FILE REJECTED =====');

        $calibration = Calibration::findOrFail($id);

        if ($calibration->status !== 'rejected') {
            \Log::warning("Attempt to download rejected file but status is: " . $calibration->status);
            return back()->with('error', 'File hanya bisa di-download saat status Ditolak.');
        }

        if (empty($calibration->location_data)) {
            \Log::error("location_data kosong untuk ID: " . $id);
            return back()->with('error', 'File rejected belum tersedia.');
        }

        $userName = auth()->user()->nama ?? auth()->user()->username ?? 'System';

        // LOG ACTIVITY: User mendownload file rejected
        LogHelper::log('download_rejected', "{$userName} mendownload file rejected: {$calibration->namaAlat} ({$calibration->NoSeri})", $calibration);
        
        
        
     
        $locationData = $calibration->location_data;
        \Log::info('🌐 Location Data dari DB: ' . $locationData);

        // EXTRACT RELATIVE PATH
        $relativePath = '';

        if (strpos($locationData, 'https://paperless.pascalibration.com/') === 0) {
            $relativePath = str_replace('https://paperless.pascalibration.com/', '', $locationData);
        } elseif (strpos($locationData, 'data_rejected/') === 0) {
            $relativePath = $locationData;
        } elseif (strpos($locationData, 'public/data_rejected/') !== false) {
            $relativePath = str_replace('public/', '', $locationData);
        } else {
            \Log::error('Format location_data tidak dikenali');
            return back()->with('error', 'Format path file tidak valid.');
        }

        if (!str_starts_with($relativePath, 'data_rejected/')) {
            \Log::error('Security violation path: ' . $relativePath);
            return back()->with('error', 'Akses file tidak diizinkan.');
        }

        $fullPath = public_path($relativePath);

        if (!file_exists($fullPath)) {
            $storagePath = storage_path('app/public/' . $relativePath);
            if (file_exists($storagePath)) {
                $fullPath = $storagePath;
            } else {
                return back()->with('error', 'File rejected tidak ditemukan.');
            }
        }

        $fileName = basename($fullPath);
        $fileSize = filesize($fullPath);

        if ($fileSize < 100) {
            return back()->with('error', 'File corrupt atau kosong.');
        }

        $tempFileName = $fileName;
        $tempPath = storage_path('app/temp/' . $tempFileName);

        if (!is_dir(dirname($tempPath))) {
            mkdir(dirname($tempPath), 0755, true);
        }

        copy($fullPath, $tempPath);
        \Log::info('📄 File copied to temp: ' . $tempPath);

        try {
            $this->fillRejectedExcel($tempPath, $calibration);
            \Log::info('✅ Excel rejected berhasil diisi (U13)');
            // 🔧 Fix: Hapus @ dari rumus AGGREGATE
            $this->removeAtSignFromAggregateFormulas($tempPath);
        } catch (\Exception $e) {
            \Log::warning('⚠️ Gagal isi Excel rejected: ' . $e->getMessage());
        }
        
        return response()->download(
            $tempPath,
            $tempFileName,
            [
                'Content-Type' => 'application/vnd.ms-excel.sheet.macroEnabled.12',
                'Content-Disposition' => 'attachment; filename="' . $tempFileName . '"',
                'Content-Length' => filesize($tempPath),
                'Cache-Control' => 'no-cache, no-store, must-revalidate',
                'Pragma' => 'no-cache',
                'Expires' => '0',
            ]
        )->deleteFileAfterSend(true);

    } catch (\Exception $e) {
        \Log::error('💥 ERROR download rejected: ' . $e->getMessage());
        return back()->with('error', 'Terjadi kesalahan saat mengunduh file.');
    }
}


