private function fillRejectedExcel($filePath, $calibration)
{
    \Log::info('📝 Mengisi Excel REJECTED', [
        'calibration_id' => $calibration->id,
        'form_type' => $calibration->form_type
    ]);

    $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($filePath);

    $formType = strtolower($calibration->form_type ?? '');
    $rejectReason = $calibration->reason ?? 'REJECTED';

    // ===============================
    // AMBIL INSULATION TYPE DARI DATA HEAD (KHUSUS INSULATION)
    // ===============================
    $insulationType = '';
    if ($formType === 'insulation') {
        $insulationType = strtolower($calibration->headInsulation->insulation_type ?? '');

        \Log::info('🔍 Cek insulation_type', [
            'calibration_id' => $calibration->id,
            'insulation_type' => $insulationType
        ]);
    }

    // ===============================
    // TENTUKAN SHEET DAN CELL BERDASARKAN FORM TYPE
    // ===============================
    $sheetName = '';
    $targetCell = '';

    switch ($formType) {
        case 'thermometer':
            $sheetName = 'input data';
            $targetCell = 'O29';
            break;

        case 'dial_indicator':
        case 'dial_test_indicator':
            $sheetName = 'INPUT DATA 1';
            $targetCell = 'Q13';
            break;

        case 'caliper':
        case 'depth_caliper':
            $sheetName = 'input data';
            $targetCell = 'Q31';
            break;

        case 'penggaris':
            $sheetName = 'input data';
            $targetCell = 'P23';
            break;

        case 'pressure_gauge':
        case 'differential_pressure_gauge':
            $sheetName = 'input data';
            $targetCell = 'O42';
            break;

        case 'torque_wrench':
            $sheetName = 'input data';
            $targetCell = 'S16';
            break;

        case 'torque_meter':
            $sheetName = 'input data';
            $targetCell = 'R20';
            break;

        case 'volumetrik':
            $sheetName = 'INPUT DATA 1';
            $targetCell = 'O11';
            break;

        case 'viscometer':
            $sheetName = 'INPUT DATA 1';
            $targetCell = 'O13';
            break;

        case 'thickness_gauge':
            $sheetName = 'input data';
            $targetCell = 'U13';
            break;

        case 'pressure_transmitter':
            $sheetName = 'input data';
            $targetCell = 'O42';
            break;

        case 'thermohygrometer':
            $sheetName = 'input data';
            $targetCell = 'O11';
            break;

        case 'push_pull':
            $sheetName = 'input data';
            $targetCell = 'M22';
            break;

        case 'timbangan_bias':
            $sheetName = 'input data';
            $targetCell = 'K25';
            break;

        case 'timbangan':
            $sheetName = 'input data';
            $targetCell = 'K24';
            break;

        case 'timbangan_moisture':
            $sheetName = 'input data';
            $targetCell = 'K24';
            break;

        case 'holetest':
            $sheetName = 'input data';
            $targetCell = 'N21';
            break;

        case 'conductivity_meter':
            $sheetName = 'input data';
            $targetCell = 'N19';
            break;

        case 'coating_thickness':
            $sheetName = 'input data';
            $targetCell = 'O26';
            break;

        case 'mikropipet_dispenset':
            $sheetName = 'INPUT DATA 1';
            $targetCell = 'O15';
            break;

        case 'taper_gauge':
            $sheetName = 'input data';
            $targetCell = 'N21';
            break;

        case 'profil_projector':
            $sheetName = 'input data';
            $targetCell = 'N18';
            break;

        case 'ultrasonic_thickness_gauge':
            $sheetName = 'input data';
            $targetCell = 'N17';
            break;

        case 'height_gauge':
            $sheetName = 'input data';
            $targetCell = 'O33';
            break;

        case 'temp_humid_transmitter':
            $sheetName = 'input data';
            $targetCell = 'Q10';
            break;

        case 'ir_thermometer':
            $sheetName = 'input data';
            $targetCell = 'N29';
            break;

        case 'temp_transmitter':
        case 'temperature_transmitter':
            $sheetName = 'input data';
            $targetCell = 'Q19';
            break;

        case 'visco_cup':
            $sheetName = 'DATA INPUT';
            $targetCell = 'M20';
            break;

        case 'ph_meter':
            $sheetName = 'INPUT DATA';
            $targetCell = 'O22';
            break;

        case 'centrifuge':
            $sheetName = 'INPUT DATA';
            $targetCell = 'Q12';
            break;

        case 'thermoindicator':
            $sheetName = 'INPUT DATA';
            $targetCell = 'N34';
            break;

        case 'durometer':
            $sheetName = 'INPUT DATA';
            $targetCell = 'L24';
            break;

        case 'tachometer':
            $sheetName = 'INPUT DATA';
            $targetCell = 'P22';
            break;

        case 'utm':
            $sheetName = 'INPUT DATA';
            $targetCell = 'O23';
            break;
            
        case 'stopwatch':
            $sheetName = 'INPUT DATA';
            $targetCell = 'M21';
            break;
            
        case 'thread_gauge':
            $sheetName = 'INPUT DATA';
            $targetCell = 'Q12';
            break;

        case 'plain_limit_gauge':
            $sheetName = 'INPUT DATA';
            $targetCell = 'N19';
            break;
            
        case 'chamber':
            $sheetName = 'INPUT DATA';
            $targetCell = 'M22';
            break;

        case 'insulation':
            // Beda file antara Clampmeter & Multimeter
            if ($insulationType === 'clampmeter') {
                $sheetName = 'INPUT DATA';   // TODO: sesuaikan nama sheet clampmeter
                $targetCell = 'M18';         // TODO: sesuaikan cell clampmeter
            } elseif ($insulationType === 'multimeter') {
                $sheetName = 'INPUT DATA';   // TODO: sesuaikan nama sheet multimeter
                $targetCell = 'N21';         // TODO: sesuaikan cell multimeter
            } else {
                // fallback kalau insulation_type tidak dikenal
                $sheetName = 'INPUT DATA';
                $targetCell = 'N20';
            }
            break;

        default:
            // Inside, Outside, Depth Micrometer
            $sheetName = 'input data';
            $targetCell = 'U13';
            break;
    }

    // ===============================
    // AMBIL SHEET YANG DITUJU
    // ===============================
    $sheet = $spreadsheet->getSheetByName($sheetName);

    if (!$sheet) {
        throw new \Exception('Sheet "' . $sheetName . '" tidak ditemukan untuk form type: ' . $formType);
    }

    // ===============================
    // ISI CELL DENGAN NILAI REJECTED
    // ===============================
    $sheet->setCellValue($targetCell, $rejectReason);

    \Log::info('✅ Excel rejected berhasil diisi', [
        'form_type' => $formType,
        'insulation_type' => $insulationType ?: null,
        'sheet' => $sheetName,
        'cell' => $targetCell,
        'value' => $rejectReason
    ]);

    // ===============================
    // OPTIMASI XLSM (PRESERVE MACRO)
    // ===============================
    $spreadsheet->setActiveSheetIndex(0);
    $spreadsheet->garbageCollect();

    $calc = \PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($spreadsheet);
    $calc->setCalculationCacheEnabled(false);
    $calc->clearCalculationCache();

    $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
    $writer->setPreCalculateFormulas(false);
    $writer->save($filePath);

    \Log::info('✅ Excel rejected berhasil di-update', [
        'form_type' => $formType,
        'insulation_type' => $insulationType ?: null,
        'sheet' => $sheetName,
        'cell' => $targetCell,
        'value' => $rejectReason
    ]);
}


       
