      /**
         * Generate nama file download excel
         * Format: 000422 - Nama PT - Nama Alat.xlsm
         * - No Sertifikat: diambil dari Head Model masing-masing alat (diambil 6 digit angka setelah PAS-)
         * - Nama PT & Nama Alat: diambil dari model Calibration
         */
        // private function generateFileName($calibration)
        // {
        //     $headRecord = null;
        //     $formType = $calibration->form_type;
        //     $registry = self::$formRegistry[$formType] ?? null;

        //     if ($registry && isset($registry['head_model']) && class_exists($registry['head_model'])) {
        //         $headClass = $registry['head_model'];
        //         try {
        //             $headRecord = $headClass::where('calibration_id', $calibration->id)->first();
        //         } catch (\Exception $e) {
        //             \Log::warning("⚠️ Gagal mengambil head model {$headClass}: " . $e->getMessage());
        //         }
        //     }

        //     // 1. Certificate ID / No Sertifikat (Ambil dari Head Model terlebih dahulu, lalu ambil 6 digit angka setelah PAS-)
        //     $certId = '';
        //     if ($headRecord) {
        //         $certId = $headRecord->certificate_id ?? $headRecord->no_sertifikat ?? $headRecord->no_certificate ?? '';
        //     }
        //     if (empty($certId)) {
        //         $certId = $calibration->certificate_id ?? $calibration->id ?? '';
        //     }

        //     $certNum = '';
        //     if (preg_match('/PAS-(\d+)/i', $certId, $matches)) {
        //         $certNum = str_pad($matches[1], 6, '0', STR_PAD_LEFT);
        //     } elseif (preg_match('/(\d{6})/', $certId, $matches)) {
        //         $certNum = $matches[1];
        //     } else {
        //         $certNum = '000000';
        //     }

        //     // 2. Nama PT (pemilikAlat) & 3. Nama Alat (diambil langsung dari Calibration model)
        //     $ptName = !empty($calibration->pemilikAlat) ? $calibration->pemilikAlat : (!empty($calibration->lokasiPT) ? $calibration->lokasiPT : '-');
        //     $namaAlat = !empty($calibration->namaAlat) ? $calibration->namaAlat : '-';

        //     // Bersihkan karakter ilegal yang tidak diperbolehkan di nama file OS
        //     $cleanPtName = preg_replace('/[\/\\\:\*\?"<>\|]/', '_', trim($ptName));
        //     $cleanNamaAlat = preg_replace('/[\/\\\:\*\?"<>\|]/', '_', trim($namaAlat));

        //     // Format: 000422 - Nama PT - Nama Alat.xlsm
        //     return "{$certNum} - {$cleanPtName} - {$cleanNamaAlat}.xlsm";
        // }
        
        private function generateFileName($calibration, $specificFormType = null)
        {
            $headRecord = null;
            $formType = $specificFormType ?? $calibration->form_type;
            $registry = self::$formRegistry[$formType] ?? null;

            if ($registry && isset($registry['head_model']) && class_exists($registry['head_model'])) {
                $headClass = $registry['head_model'];
                try {
                    $headRecord = $headClass::where('calibration_id', $calibration->id)->first();
                } catch (\Exception $e) {
                    \Log::warning("⚠️ Gagal mengambil head model {$headClass}: " . $e->getMessage());
                }
            }

            // Jika specificFormType tidak punya headRecord sendiri, coba fallback ke head model form utama
            if (!$headRecord && $specificFormType && $specificFormType !== $calibration->form_type) {
                $mainRegistry = self::$formRegistry[$calibration->form_type] ?? null;
                if ($mainRegistry && isset($mainRegistry['head_model']) && class_exists($mainRegistry['head_model'])) {
                    $mainHeadClass = $mainRegistry['head_model'];
                    try {
                        $headRecord = $mainHeadClass::where('calibration_id', $calibration->id)->first();
                    } catch (\Exception $e) {}
                }
            }

            // 1. Certificate ID / No Sertifikat (Ambil dari Head Model terlebih dahulu, lalu ambil 6 digit angka setelah PAS-)
            $certId = '';
            if ($headRecord) {
                $certId = $headRecord->certificate_id ?? $headRecord->no_sertifikat ?? $headRecord->no_certificate ?? '';
            }
            if (empty($certId)) {
                $certId = $calibration->certificate_id ?? $calibration->id ?? '';
            }

            $certNum = '';
            if (preg_match('/PAS-(\d+)/i', $certId, $matches)) {
                $certNum = str_pad($matches[1], 6, '0', STR_PAD_LEFT);
            } elseif (preg_match('/(\d{6})/', $certId, $matches)) {
                $certNum = $matches[1];
            } else {
                $certNum = '000000';
            }

            // 2. Nama PT (pemilikAlat) & 3. Nama Alat
            $ptName = !empty($calibration->pemilikAlat) ? $calibration->pemilikAlat : (!empty($calibration->lokasiPT) ? $calibration->lokasiPT : '-');
            
            if ($specificFormType) {
                $namaAlat = ucwords(str_replace('_', ' ', $specificFormType));
            } else {
                $namaAlat = !empty($calibration->namaAlat) ? $calibration->namaAlat : '-';
            }

            // Bersihkan karakter ilegal yang tidak diperbolehkan di nama file OS
            $cleanPtName = preg_replace('/[\/\\\:\*\?"<>\|]/', '_', trim($ptName));
            $cleanNamaAlat = preg_replace('/[\/\\\:\*\?"<>\|]/', '_', trim($namaAlat));

            // Format: 000422 - Nama PT - Nama Alat.xlsm
            return "{$certNum} - {$cleanPtName} - {$cleanNamaAlat}.xlsm";
        }
        
     
        
     
              /**
         * Kirim SATU data draft ke checker
         */
        public function sendToChecker($id)
        {
            try {
                $user = auth()->user();
                $calibration = Calibration::findOrFail($id);
                
                // Validasi: hanya teknisi atau super admin
                if (!in_array($user->role, ['teknisi', 'super admin'])) {
                    return redirect()->back()->with('error', 'Anda tidak memiliki izin.');
                }
                
                // Validasi status
                if ($calibration->status !== 'draft') {
                    return redirect()->back()->with('error', 'Hanya data draft yang dapat dikirim.');
                }
                
                // Validasi kepemilikan untuk teknisi
                if ($user->role === 'teknisi' && $calibration->calibratedBy !== $user->nama) {
                    return redirect()->back()->with('error', 'Anda hanya bisa mengirim data milik sendiri.');
                }
                
                $calibration->markAsWaitingVerification($user->nama);
                
                  \App\Helpers\LogHelper::log('send_to_checker', "Data {$calibration->id} dikirim ke checker oleh {$user->nama}");
                
                return redirect()->route('calibrations.index')
                    ->with('success', 'Data berhasil dikirim ke checker.');
                    
            } catch (\Exception $e) {
                \Log::error('Error send to checker: ' . $e->getMessage());
                return redirect()->back()->with('error', 'Terjadi kesalahan.');
            }
        }
        
        /**
         * Kirim SEMUA data draft ke checker
         */
        public function sendAllToChecker()
        {
            try {
                $user = auth()->user();
                
                if (!in_array($user->role, ['teknisi', 'super admin'])) {
                    return redirect()->back()->with('error', 'Anda tidak memiliki izin.');
                }
                
                $query = Calibration::where('status', 'draft');
                
                if ($user->role === 'teknisi') {
                    $query->where('calibratedBy', $user->nama);
                }
                
                $totalDraft = $query->count();
                
                if ($totalDraft === 0) {
                    return redirect()->back()->with('error', 'Tidak ada data draft.');
                }
                
                $updated = 0;
                $calibrations = $query->get();
                
                foreach ($calibrations as $calibration) {
                    $calibration->markAsWaitingVerification($user->nama);
                    $updated++;
                }
                
                   \App\Helpers\LogHelper::log('send_all_to_checker', "{$updated} data draft dikirim ke checker oleh {$user->nama}");
                
                return redirect()->route('calibrations.index')
                    ->with('success', "Berhasil mengirim {$updated} data draft ke checker.");
                    
            } catch (\Exception $e) {
                \Log::error('Error send all to checker: ' . $e->getMessage());
                return redirect()->back()->with('error', 'Terjadi kesalahan.');
            }
        }
        
        /**
         * Update Next Tanggal Kalibrasi via AJAX (saat print)
         */
      public function updateNextDate(Request $request, $id)
        {
            try {
                \Log::info('📅 UPDATE NEXT DATE REQUEST:', [
                    'calibration_id' => $id,
                    'next_date' => $request->next_date
                ]);
                
                $request->validate([
                    'next_date' => 'required|date',
                ]);
                
                $calibration = Calibration::findOrFail($id);
                
                // Update kolom NextTanggalKalibrasi di tabel calibrations
                $calibration->update([
                    'NextTanggalKalibrasi' => $request->next_date
                ]);
                
                \Log::info('✅ Next date updated successfully', [
                    'calibration_id' => $id,
                    'next_date' => $request->next_date
                ]);
                
                return response()->json([
                    'success' => true, 
                    'message' => 'Next date berhasil disimpan'
                ]);
                
            } catch (\Exception $e) {
                \Log::error('❌ Error updating next date:', [
                    'message' => $e->getMessage(),
                    'file' => $e->getFile(),
                    'line' => $e->getLine()
                ]);
                
                return response()->json([
                    'success' => false, 
                    'error' => $e->getMessage()
                ], 500);
            }
        }
        
          /**
         * Recycle Bin Methods
         */
        public function recycleBin()
        {
            if (auth()->user()->role !== 'super admin') {
                return redirect()->route('calibrations.index')->with('error', 'Akses ditolak.');
            }
            
            $calibrations = \App\Models\Calibration::onlyTrashed()->get();
            return view('calibrations.recycle-bin', compact('calibrations'));
        }

        public function restore($id)
        {
            if (auth()->user()->role !== 'super admin') {
                return redirect()->route('calibrations.index')->with('error', 'Akses ditolak.');
            }

            $calibration = \App\Models\Calibration::onlyTrashed()->findOrFail($id);
            $calibration->restore();

            return redirect()->route('calibrations.recycle-bin')->with('success', 'Data kalibrasi berhasil dipulihkan.');
        }

        public function forceDelete($id)
        {
            if (auth()->user()->role !== 'super admin') {
                return redirect()->route('calibrations.index')->with('error', 'Akses ditolak.');
            }

            $calibration = \App\Models\Calibration::onlyTrashed()->findOrFail($id);
              
            // ==================================================================
            // HAPUS DATA FORM UTAMA DAN SUBFORM SEBELUM FORCE DELETE
            // ==================================================================
            if (!empty($calibration->form_type)) {
                self::deleteSubformData($calibration->id, $calibration->form_type);
            }
            if (!empty($calibration->additional_forms) && is_array($calibration->additional_forms)) {
                foreach ($calibration->additional_forms as $subformType) {
                    self::deleteSubformData($calibration->id, $subformType);
                }
            }
            $calibration->forceDelete();

            return redirect()->route('calibrations.recycle-bin')->with('success', 'Data kalibrasi dihapus permanen.');
        }

        public function emptyRecycleBin()
        {
            if (auth()->user()->role !== 'super admin') {
                return redirect()->route('calibrations.index')->with('error', 'Akses ditolak.');
            }

            $calibrations = \App\Models\Calibration::onlyTrashed()->get();
            foreach ($calibrations as $calibration) {
                 // Hapus data form utama dan subform
                if (!empty($calibration->form_type)) {
                    self::deleteSubformData($calibration->id, $calibration->form_type);
                }
                if (!empty($calibration->additional_forms) && is_array($calibration->additional_forms)) {
                    foreach ($calibration->additional_forms as $subformType) {
                        self::deleteSubformData($calibration->id, $subformType);
                    }
                }
                
                $calibration->forceDelete();
            }

            return redirect()->route('calibrations.recycle-bin')->with('success', 'Semua data di recycle bin berhasil dihapus permanen.');
        }
        
        /**
 * Simpan subform secara terpisah (dipanggil dari AJAX edit form)
 */
public function saveSubform(Request $request, $id)
{
    try {
        $calibration = Calibration::findOrFail($id);
        $subFormType = $request->input('form_type');
        
        \Log::info('🎯 SAVE SUBFORM CALLED', [
            'calibration_id' => $id,
            'form_type' => $subFormType,
        ]);
        
        if (empty($subFormType)) {
            return response()->json([
                'success' => false,
                'error' => 'form_type tidak boleh kosong',
            ], 422);
        }
        
        $registry = self::$formRegistry[$subFormType] ?? null;
        if (!$registry) {
            return response()->json([
                'success' => false,
                'error' => "Form type '{$subFormType}' tidak terdaftar",
            ], 422);
        }
        
        // Tentukan certificate ID
        $certificateId = $this->generateCertificateIdFromNamaAlat(
            ucwords(str_replace('_', ' ', $subFormType)),
            $calibration
        );
        
        // Simpan / update subform
        \App\Models\Calibration::$preventUpdating = true;
        try {
            $savedSubforms = self::getSavedSubforms($calibration->id, $calibration->form_type);
            $hasRecord = in_array($subFormType, $savedSubforms);
            
            if ($hasRecord) {
                $updateMethod = $registry['update_method'] ?? null;
                if ($updateMethod && method_exists($this, $updateMethod)) {
                    \Log::info("🔄 Updating subform: {$subFormType}");
                    $this->$updateMethod($request, $calibration, $certificateId);
                }
            } else {
                $storeMethod = $registry['store_method'] ?? null;
                if ($storeMethod && method_exists($this, $storeMethod)) {
                    \Log::info("🆕 Storing subform: {$subFormType}");
                    $this->$storeMethod($request, $calibration, $certificateId);
                    
                    // Update additional_forms
                    $existingForms = $calibration->additional_forms ?? [];
                    if (is_string($existingForms)) {
                        $existingForms = json_decode($existingForms, true) ?? [];
                    }
                    if (!is_array($existingForms)) {
                        $existingForms = [];
                    }
                    if (!in_array($subFormType, $existingForms)) {
                        $existingForms[] = $subFormType;
                        \DB::table('calibrations')
                            ->where('id', $calibration->id)
                            ->update(['additional_forms' => json_encode($existingForms)]);
                    }
                }
            }
        } finally {
            \App\Models\Calibration::$preventUpdating = false;
        }
        
        return response()->json([
            'success' => true,
            'message' => "Form {$subFormType} berhasil disimpan",
        ]);
        
    } catch (\Exception $e) {
        \Log::error('❌ saveSubform error: ' . $e->getMessage());
        return response()->json([
            'success' => false,
            'error' => $e->getMessage(),
        ], 500);
    }
}
        

       
